if(!empty($upResult['ok']))return $upResult;
}
}

return['ok'=>0,'error'=>'تصویر آپلود نشد — 3 تلاش ناموفق (فایل، مستقیم، پراکسی)'];
}

/**
 * v8.58: آیا خطای ووکامرس مربوط به تصویر است؟
 *
 * وقتی ووکامرس نتواند تصویر را از روی آدرس بردارد (هات‌لینک بسته، ۴۰۳،
 * تایم‌اوت)، کل درخواست ساخت محصول را رد می‌کند. یعنی یک تصویرِ نگرفتنی
 * باعث می‌شد اصلاً محصولی ساخته نشود. با تشخیص این خطا، همان محصول را
 * بدون تصویر دوباره می‌فرستیم تا دست‌کم محصول ساخته شود.
 */
function wooIsImageError(array $r): bool {
    $code = (string)($r['body']['code'] ?? '');
    $msg  = (string)($r['body']['message'] ?? '');
    if ($code !== '' && stripos($code, 'image') !== false) return true;
    foreach (['remote image', 'invalid image', 'image_upload', 'upload_error',
              'not a valid image', 'error getting remote'] as $needle) {
        if (stripos($msg, $needle) !== false) return true;
    }
    return false;
}

/**
 * v8.57: تصویر محصول را برای ووکامرس آماده می‌کند.
 *
 * چرا لازم شد: کلید ووکامرس (ck_/cs_) فقط روی مسیرهای wc/v3 معتبر است و
 * هستهٔ وردپرس آن را کاربر نمی‌شناسد. برای همین آپلود به wp/v2/media با
 * ۴۰۱ رد می‌شد و محصول بی‌تصویر ساخته می‌شد. خودِ ووکامرس می‌تواند تصویر
 * را از روی آدرس بردارد (side-load) و همان کلید برایش کافی است.
 *
 * اول آپلود مستقیم به کتابخانهٔ رسانه امتحان می‌شود (اگر سایت اجازه بدهد
 * نتیجه‌اش تمیزتر است)، و اگر نشد آدرس تصویر مستقیم به ووکامرس داده
 * می‌شود. خروجی همان آرایه‌ای است که در فیلد images محصول می‌نشیند.
 */
function wooImagePayload(array $w, string $imgUrl, ?string &$note = null): array {
    $imgUrl = trim($imgUrl);
    if ($imgUrl === '') { $note = 'بدون تصویر — آدرس خالی'; return []; }

    $up = wooUploadImage($w['store_url'], $w['consumer_key'], $w['consumer_secret'], $imgUrl);
    if (!empty($up['ok']) && (int)($up['media_id'] ?? 0) > 0) {
        $note = 'تصویر در کتابخانهٔ رسانه (Media#' . (int)$up['media_id'] . ')';
        return [['id' => (int)$up['media_id']]];
    }

    // آدرس باید از بیرون قابل دسترس باشد، وگرنه ووکامرس هم نمی‌تواند بگیردش
    if (!preg_match('~^https?://~i', $imgUrl)) {
        $note = 'تصویر ناموفق — آدرس نامعتبر: ' . mb_substr($imgUrl, 0, 60);
        return [];
    }
    $note = 'تصویر با آدرس به ووکامرس سپرده شد (آپلود مستقیم نشد: '
          . mb_substr((string)($up['error'] ?? '?'), 0, 60) . ')';
    return [['src' => $imgUrl]];
}

/**
 * v8.64: چند تصویر را برای ووکامرس آماده می‌کند.
 *
 * همان منطق wooImagePayload، ولی روی فهرست. عکس اول شاخص محصول می‌شود
 * و بقیه در گالری می‌نشینند — این ترتیبی است که ووکامرس خودش می‌فهمد.
 * عکسی که آماده نشود ساکت رد می‌شود تا یک آدرس خراب کل گالری را نیندازد.
 */
function wooGalleryPayload(array $w, array $imgUrls, ?string &$note = null): array {
    $out = []; $okN = 0; $badN = 0; $firstNote = null;
    foreach (galleryDedupe($imgUrls) as $u) {
        $n1 = null;
        $one = wooImagePayload($w, (string)$u, $n1);
        if ($firstNote === null) $firstNote = $n1;
        if (!empty($one)) { $out[] = $one[0]; $okN++; } else { $badN++; }
    }
    if ($okN === 0) { $note = $firstNote ?? 'هیچ تصویری آماده نشد'; return []; }
    $note = $okN . ' تصویر آماده شد' . ($badN > 0 ? ' (' . $badN . ' ناموفق)' : '')
          . ($firstNote ? ' — ' . $firstNote : '');
    return $out;
}

/**
 * فهرست تصاویر یک محصول را به‌ترتیب برمی‌گرداند: عکس اصلی اول، بعد گالری.
 * هم شکل جدید (images) و هم قدیمی (فقط image) را می‌فهمد.
 */
function productImageList(array $p): array {
    $list = [];
    $main = trim((string)($p['image'] ?? ''));
    if ($main !== '') $list[] = $main;
    $imgs = $p['images'] ?? null;
    if (is_string($imgs)) $imgs = json_decode($imgs, true);
    if (is_array($imgs)) {
        foreach ($imgs as $u) {
            if (is_array($u)) $u = (string)($u['src'] ?? ($u['url'] ?? ''));
            $u = trim((string)$u);
            if ($u !== '') $list[] = $u;
        }
    }
    return galleryDedupe($list);
}

/* =====================================================================
 *  v8.69: تشخیص «محتوا عوض شده» برای محصولی که از قبل در مقصد هست
 *
 *  تا اینجا تصمیمِ «تکراری است، رد کن» فقط قیمت و موجودی را می‌سنجید.
 *  یعنی اگر بعد از استخراج تازه، توضیحات کامل‌تر شده بود، گالری چند عکس
 *  گرفته بود یا تنوع‌ها اضافه شده بودند، محصول «تکراری» شمرده می‌شد و
 *  آن اطلاعات هیچ‌وقت به مقصد نمی‌رسید.
 *
 *  حالا هر فیلدی که در مبدأ مقدار دارد با همتای مقصد مقایسه می‌شود.
 *  اصل محافظه‌کارانه: چیزی که در مبدأ خالی است هرگز باعث آپدیت نمی‌شود
 *  و روی مقصد را پاک نمی‌کند — فقط داده‌ی تازه اضافه یا اصلاح می‌شود.
 * ===================================================================== */

/** متن را برای مقایسه ساده می‌کند: بدون تگ، بدون فاصلهٔ اضافه */
function contentNorm(?string $s): string {
    $s = (string)$s;
    if ($s === '') return '';
    $s = html_entity_decode(strip_tags($s), ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $s = preg_replace('~[\x{200c}\x{200f}\x{200e}\x{00a0}]~u', ' ', $s);
    $s = preg_replace('~\s+~u', ' ', $s);
    return trim(mb_strtolower($s, 'UTF-8'));
}

/** آیا کاربر «آپدیت محتوا» را خاموش کرده؟ پیش‌فرض روشن است. */
function contentSyncOn(?array $cn = null): bool {
    if ($cn === null) $cn = loadConnections();
    return !isset($cn['content_sync']) || !empty($cn['content_sync']);
}

/**
 * مقایسهٔ محتوای محصول مبدأ با محصول مقصد.
 *
 * $remote باید کلیدهای نرمال‌شده داشته باشد:
 *   short_desc, long_desc, images_count, variations_text, sku
 * هر کلیدی که null باشد یعنی «نمی‌دانیم» و نادیده گرفته می‌شود.
 *
 * خروجی فهرست تغییرات به فارسی است؛ آرایهٔ خالی یعنی چیزی عوض نشده.
 */
function contentChanges(array $p, array $remote): array {
    $out = [];

    $srcShort = contentNorm((string)($p['short_desc'] ?? ''));
    if ($srcShort !== '' && array_key_exists('short_desc', $remote)) {
        if (contentNorm((string)$remote['short_desc']) !== $srcShort) $out[] = 'توضیح کوتاه';
    }

    $srcLong = contentNorm((string)($p['long_desc'] ?? ''));
    if ($srcLong !== '' && array_key_exists('long_desc', $remote)) {
        if (contentNorm((string)$remote['long_desc']) !== $srcLong) $out[] = 'توضیح بلند';
    }

    // گالری: فقط وقتی مبدأ عکسِ بیشتری دارد. کمتر بودن دلیل آپدیت نیست،
    // چون ممکن است خود کاربر در مقصد عکس اضافه کرده باشد.
    if (array_key_exists('images_count', $remote)) {
        $srcN = count(productImageList($p));
        $remN = (int)$remote['images_count'];
        if ($srcN > $remN) $out[] = 'گالری (' . $remN . '→' . $srcN . ' عکس)';
    }

    $srcVar = contentNorm((string)($p['variations_text'] ?? ''));
    if ($srcVar !== '' && array_key_exists('variations_text', $remote)) {
        if (contentNorm((string)$remote['variations_text']) !== $srcVar) $out[] = 'تنوع‌ها';
    }

    $srcSku = trim((string)($p['sku'] ?? ''));
    if ($srcSku !== '' && array_key_exists('sku', $remote)) {
        if (trim((string)$remote['sku']) !== $srcSku) $out[] = 'SKU';
    }

    return $out;
}

/** شکل نرمال‌شدهٔ محصول ووکامرس برای contentChanges */
function wooRemoteContent(array $ex): array {
    $imgs = is_array($ex['images'] ?? null) ? $ex['images'] : [];
    return [
        'short_desc'      => (string)($ex['short_description'] ?? ''),
        'long_desc'       => (string)($ex['description'] ?? ''),
        'images_count'    => count($imgs),
        'sku'             => (string)($ex['sku'] ?? ''),
    ];
}

/**
 * تنوع‌ها را به «ویژگی»های ووکامرس تبدیل می‌کند.
 * محصول ساده می‌ماند (تبدیل به variable کار سنگینی است و نیاز به ساختن
 * هر ترکیب دارد)، ولی گزینه‌ها روی صفحهٔ محصول دیده می‌شوند.
 */
function wooVariationAttributes(array $p): array {
    $groups = $p['variation_groups'] ?? null;
    if (!is_array($groups) || !$groups) {
        $vals = $p['variations'] ?? null;
        if (is_string($vals)) $vals = array_filter(array_map('trim', explode('،', $vals)));
        if (!is_array($vals) || !$vals) return [];
        $groups = [['name' => 'ویژگی', 'values' => array_values($vals)]];
    }
    $out = []; $pos = 0;
    foreach ($groups as $g) {
        if (!is_array($g)) continue;
        $vals = array_values(array_filter(array_map(
            fn($v) => trim((string)$v), (array)($g['values'] ?? []))));
        if (!$vals) continue;
        $name = trim((string)($g['name'] ?? ''));
        if ($name === '') $name = 'ویژگی ' . ($pos + 1);
        $out[] = ['name' => mb_substr($name, 0, 60), 'position' => $pos++,
                  'visible' => true, 'variation' => false,
                  'options' => array_slice($vals, 0, 30)];
    }
    return $out;
}

/**
 * v8.85: نام دستهٔ استخراج‌شده را به شناسهٔ دستهٔ ووکامرس تبدیل می‌کند.
 *
 * فیلد «دسته‌بندی» از صفحهٔ محصول برداشته می‌شد ولی هیچ‌وقت به ووکامرس
 * نمی‌رفت؛ دسته همیشه همان یکی بود که در تنظیمات پروفایل انتخاب شده بود.
 * اینجا نام با فهرست دسته‌های مقصد تطبیق داده می‌شود (با همان نرمال‌سازی
 * عنوان که برای محصولات به کار می‌رود، تا نیم‌فاصله و ی/ک عربی مانع نشود)
 * و اگر نبود، در صورت اجازه ساخته می‌شود.
 *
 * فهرست دسته‌ها یک بار خوانده و در حافظه نگه داشته می‌شود.
 */
function wooCategoryIds(array $w, $raw, bool $create = true): array {
    static $cache = null;         // نام نرمال‌شده => id
    static $failed = false;
    if ($raw === null || $raw === '' || $raw === []) return [];

    // ورودی می‌تواند رشتهٔ «الف، ب» یا آرایه باشد
    $names = is_array($raw) ? $raw : preg_split('~[،,>|/]+~u', (string)$raw);
    $names = array_values(array_filter(array_map(function ($s) {
        $s = trim(preg_replace('~\s+~u', ' ', (string)$s));
        return mb_strlen($s) > 0 && mb_strlen($s) <= 80 ? $s : '';
    }, $names)));
    if (!$names) return [];

    if ($cache === null) {
        $cache = [];
        for ($page = 1; $page <= 10; $page++) {
            $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
                        'products/categories?per_page=100&page=' . $page);
            if (empty($r['ok']) || !is_array($r['body']) || !$r['body']) {
                if ($page === 1) $failed = true;
                break;
            }
            foreach ($r['body'] as $c) {
                $nm = reconNormTitle((string)($c['name'] ?? ''));
                $id = (int)($c['id'] ?? 0);
                if ($nm !== '' && $id > 0 && !isset($cache[$nm])) $cache[$nm] = $id;
            }
            if (count($r['body']) < 100) break;
        }
    }
    if ($failed) return [];

    $ids = [];
    foreach ($names as $nm) {
        $key = reconNormTitle($nm);
        if ($key === '') continue;
        if (isset($cache[$key])) { $ids[] = $cache[$key]; continue; }
        if (!$create) continue;
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'POST',
                    'products/categories', ['name' => $nm]);
        $newId = (int)($r['body']['id'] ?? 0);
        // اگر ووکامرس بگوید «از قبل هست»، شناسه را از خودِ خطا بردار
        if ($newId <= 0) $newId = (int)($r['body']['data']['resource_id'] ?? 0);
        if ($newId > 0) { $cache[$key] = $newId; $ids[] = $newId; }
    }
    return array_values(array_unique(array_filter($ids)));
}

/**
 * توضیحات و تنوع‌های تازه را روی بستهٔ آپدیت باسلام می‌نشاند.
 * فقط چیزی که در مبدأ مقدار دارد نوشته می‌شود، تا آپدیت هیچ‌وقت
 * توضیحات موجود مقصد را با رشتهٔ خالی پاک نکند.
 */
function bslApplyContent(array &$bu, array $p): void {
    $brief = trim(strip_tags((string)($p['short_desc'] ?? $p['shortDesc'] ?? $p['brief'] ?? '')));
    $desc  = trim((string)($p['long_desc'] ?? $p['longDesc'] ?? $p['description'] ?? ''));
    // تنوع‌ها اگر باشند به انتهای توضیح اضافه می‌شوند؛ باسلام برای
    // محصول ساده جای جداگانه‌ای برای گزینه‌ها ندارد.
    $varTxt = trim((string)($p['variations_text'] ?? ''));
    if ($varTxt === '' && !empty($p['variations']) && is_array($p['variations'])) {
        $varTxt = implode('، ', array_map('strval', $p['variations']));
    }
    if ($varTxt === '' && !empty($p['variation_groups']) && is_array($p['variation_groups'])) {
        $nv = function_exists('aiNormalizeVariations') ? aiNormalizeVariations($p['variation_groups']) : ['text'=>''];
        $varTxt = (string)($nv['text'] ?? '');
    }
    if ($varTxt !== '') {
        $line = 'گزینه‌های موجود: ' . $varTxt;
        if ($desc !== '' && mb_strpos($desc, $varTxt) === false && mb_strpos($desc, 'گزینه‌های موجود') === false) {
            $desc .= (str_contains($desc, '<') ? '<p><strong>گزینه‌های موجود:</strong> ' . htmlspecialchars($varTxt, ENT_QUOTES, 'UTF-8') . '</p>' : "\n" . $line);
        } elseif ($desc === '') {
            $desc = $line;
        }
    }
    if ($brief !== '') $bu['brief'] = mb_substr($brief, 0, 250);
    if ($desc !== '')  $bu['description'] = $desc;
    $sku = trim((string)($p['sku'] ?? ''));
    if ($sku !== '') $bu['sku'] = $sku;
}

/** شکل نرمال‌شدهٔ محصول باسلام برای contentChanges */
function bslRemoteContent(array $ex): array {
    $rev = (is_array($ex['revision'] ?? null) && isset($ex['revision']['data'])
            && is_array($ex['revision']['data'])) ? $ex['revision']['data'] : [];
    $photos = $rev['photos'] ?? ($ex['photos'] ?? []);
    $nPhotos = is_array($photos) ? count($photos) : 0;
    if ($nPhotos === 0 && !empty($rev['photo'] ?? ($ex['photo'] ?? null))) $nPhotos = 1;
    return [
        'short_desc'   => (string)($rev['brief'] ?? ($ex['brief'] ?? '')),
        'long_desc'    => (string)($rev['description'] ?? ($ex['description'] ?? '')),
        'images_count' => $nPhotos,
        'sku'          => (string)($rev['sku'] ?? ($ex['sku'] ?? '')),
    ];
}

/* =====================================================================
 *  v8.71: پیدا کردن محصول موجود در نتیجهٔ جست‌وجو
 *
 *  باگ گزارش‌شده: «موقع ارسال محصول آپدیت‌شده، ووکامرس خطای ایجاد و
 *  باسلام خطای محصول تکراری می‌داد.»
 *
 *  علت: تطبیق با مقایسهٔ دقیقِ رشته انجام می‌شد. ولی مقصد عنوان را
 *  عیناً همان‌طور که فرستادیم نگه نمی‌دارد:
 *    • ووکامرس «&» را «&amp;» ذخیره می‌کند
 *    • خیلی از قالب‌ها ی/ک عربی را به فارسی (یا برعکس) تبدیل می‌کنند
 *    • نیم‌فاصله و فاصلهٔ سخت جای فاصلهٔ ساده می‌نشیند
 *  پس محصولِ موجود پیدا نمی‌شد، مسیر «ایجاد» می‌رفت و مقصد آن را
 *  به‌عنوان تکراری رد می‌کرد. یعنی محصول نه ساخته می‌شد نه آپدیت.
 *
 *  حالا اول تطبیق دقیق، بعد تطبیق نرمال‌شده (همان نرمال‌سازی‌ای که
 *  مغایرت‌گیری از v8.64 استفاده می‌کند) و در نهایت شناسهٔ ثبت‌شده.
 * ===================================================================== */

/**
 * در فهرست نتایج جست‌وجو، محصول متناظر با این عنوان را پیدا می‌کند.
 * $rows آرایه‌ای از محصولات مقصد است؛ $nameKey نام کلید عنوان.
 * $altTitle عنوان جایگزین (مثلاً بدون پسوند پروفایل).
 */
function findRemoteByTitle(array $rows, string $title, string $altTitle = '',
                           string $nameKey = 'name', ?string &$how = null): ?array {
    $how = '';
    if (!$rows) return null;
    $t = trim($title);
    $alt = trim($altTitle);
    // ۱) تطبیق دقیق — سریع‌ترین و مطمئن‌ترین
    foreach ($rows as $r) {
        if (!is_array($r)) continue;
        $n = trim((string)($r[$nameKey] ?? ($r['title'] ?? '')));
        if ($n !== '' && ($n === $t || ($alt !== '' && $n === $alt))) { $how = 'exact'; return $r; }
    }
    // ۲) تطبیق نرمال‌شده — &amp;، ی/ک عربی، نیم‌فاصله و علائم را نادیده می‌گیرد
    $nt  = reconNormTitle($t);
    $nal = $alt !== '' ? reconNormTitle($alt) : '';
    if ($nt !== '' || $nal !== '') {
        foreach ($rows as $r) {
            if (!is_array($r)) continue;
            $n = reconNormTitle(trim((string)($r[$nameKey] ?? ($r['title'] ?? ''))));
            if ($n === '') continue;
            if ($n === $nt || ($nal !== '' && $n === $nal)) { $how = 'normalized'; return $r; }
        }
    }
    return null;
}

/**
 * محصول را با شناسهٔ ثبت‌شده در دفترچه پیدا می‌کند.
 * وقتی عنوان در مقصد دستی عوض شده باشد، تنها راه همین است.
 */
function findRemoteById(array $rows, string $target, string $productKey): ?array {
    if ($productKey === '' || !$rows) return null;
    $map = remoteMapLoad()[$target] ?? [];
    $want = (int)($map[$productKey]['id'] ?? 0);
    if ($want <= 0) return null;
    foreach ($rows as $r) {
        if (is_array($r) && (int)($r['id'] ?? 0) === $want) return $r;
    }
    return null;
}

/**
 * v8.80: وقتی باسلام گفت «نام تکراری»، حتماً آپدیت کن.
 *
 * خواستهٔ صریح کاربر: از این به بعد هر وقت خطای محصول تکراری آمد، محصول
 * با PATCH ارسال شود. مشکل این بود که برای PATCH به شناسه نیاز داریم و
 * پیدا کردن شناسه گاهی شکست می‌خورد؛ آن وقت کل کار شکست می‌خورد.
 *
 * این تابع همهٔ راه‌های رسیدن به شناسه را پشت سر هم امتحان می‌کند و اگر
 * شناسه‌ای پیدا شد، PATCH را انجام می‌دهد. هر سه مسیر ارسال از همین یک
 * تابع استفاده می‌کنند تا رفتارشان یکی باشد.
 *
 * خروجی: ['ok'=>bool, 'id'=>int, 'how'=>string, 'error'=>string]
 */
function bslForceUpdateOnDuplicate(string $tk, int $vid, string $title,
                                   string $productKey, array $fields, array $p = []): array {
    $ex = bslFindExisting($tk, $vid, $title, $productKey);
    $id = (int)($ex['id'] ?? 0);
    $how = $id > 0 ? 'lookup' : '';

    /* آخرین تیر: خودِ باسلام می‌داند نام تکراری است، پس محصول قطعاً وجود
       دارد. اگر جست‌وجوها پیدایش نکردند، عنوان را کمی می‌شکنیم و با
       واژه‌های اصلی دنبالش می‌گردیم — عنوان ذخیره‌شده ممکن است پسوند یا
       پیشوندی داشته باشد که ما نداریم. */
    if ($id <= 0) {
        $bare = trim(stripProductCode($title));
        $words = preg_split('~\s+~u', $bare, -1, PREG_SPLIT_NO_EMPTY) ?: [];
        $probes = [];
        if ($bare !== '' && $bare !== trim($title)) $probes[] = $bare;
        if (count($words) >= 3) $probes[] = implode(' ', array_slice($words, 0, 3));
        if (count($words) >= 2) $probes[] = implode(' ', array_slice($words, 0, 2));
        foreach (array_unique($probes) as $probe) {
            $alt = bslFindExisting($tk, $vid, $probe, '');
            $aid = (int)($alt['id'] ?? 0);
            if ($aid > 0) { $id = $aid; $ex = $alt; $how = 'partial'; break; }
        }
    }

    if ($id <= 0) {
        return ['ok' => false, 'id' => 0, 'how' => '',
                'error' => 'باسلام گفت نام تکراری است ولی محصول در غرفه پیدا نشد'];
    }

    if (!empty($p)) bslApplyContent($fields, $p);
    $r = bslReq($tk, 'PATCH', 'products/' . $id, $fields);
    if ((int)($r['code'] ?? 0) === 404 && $vid > 0) {
        $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $id, $fields);
    }
    if (!empty($r['ok'])) {
        if ($productKey !== '') {
            remoteMapRecord('bsl', [['key' => $productKey, 'remote_id' => $id, 'title' => $title]]);
        }
        return ['ok' => true, 'id' => $id, 'how' => $how, 'error' => ''];
    }
    $em = $r['body']['error_description'] ?? ($r['body']['message'] ?? ($r['body']['error'] ?? ''));
    if (is_array($em)) $em = json_encode($em, JSON_UNESCAPED_UNICODE);
    return ['ok' => false, 'id' => $id, 'how' => $how,
            'error' => 'آپدیت #' . $id . ' هم نشد: ' . mb_substr((string)$em, 0, 120)];
}

/**
 * v8.79: آیا باسلام محصول را به‌خاطر تکراری بودن نام رد کرد؟
 *
 * شکل واقعی پاسخ (۴۲۲) که کاربر فرستاده بود:
 *   {"http_status":422,"messages":[{"code":0,"fields":["name"],
 *     "message":"!نام کالا تکراری است و قبلا برای محصول دیگری انتخاب کرده‌اید"}]}
 *
 * قبلاً همین تشخیص در دو جا به‌صورت درون‌خطی نوشته شده بود و مسیر سومی
 * (ایجاد بدون تصویر) اصلاً آن را نداشت. حالا یک تابع مشترک است.
 */
function bslIsDuplicateName(array $r): bool {
    if (!empty($r['ok'])) return false;
    $msgs = $r['body']['messages'] ?? [];
    if (is_array($msgs)) {
        foreach ($msgs as $m) {
            if (!is_array($m)) continue;
            $fields = (array)($m['fields'] ?? []);
            $text   = (string)($m['message'] ?? '');
            if (!in_array('name', $fields, true) && !in_array('title', $fields, true)) continue;
            foreach (['تکرار', 'duplicate', 'already', 'exists'] as $needle) {
                if (mb_stripos($text, $needle) !== false) return true;
            }
        }
    }
    $em = $r['body']['error_description'] ?? ($r['body']['message'] ?? ($r['body']['error'] ?? ''));
    if (is_array($em)) $em = json_encode($em, JSON_UNESCAPED_UNICODE);
    $em = (string)$em;
    foreach (['نام تکرار', 'تکراری', 'duplicate name', 'already exists'] as $needle) {
        if ($em !== '' && mb_stripos($em, $needle) !== false) return true;
    }
    return false;
}

/**
 * v8.71: آیا ووکامرس محصول را به‌خاطر «از قبل موجود بودن» رد کرد؟
 * رایج‌ترین حالت تکراری بودن SKU است، ولی پیام‌های دیگری هم می‌آید.
 */
function wooIsDuplicateError(array $r): bool {
    $code = strtolower((string)($r['body']['code'] ?? ''));
    $msg  = (string)($r['body']['message'] ?? '');
    foreach (['duplicate', 'invalid_sku', 'already', 'exists'] as $needle) {
        if ($code !== '' && strpos($code, $needle) !== false) return true;
    }
    foreach (['قبلا موجود', 'از قبل موجود', 'تکرار', 'duplicate',
              'already exists', 'invalid or duplicated sku'] as $needle) {
        if ($msg !== '' && mb_stripos($msg, $needle) !== false) return true;
    }
    return false;
}

/**
 * v8.71: محصول موجود را در ووکامرس پیدا می‌کند.
 * دو جست‌وجو (با و بدون پسوند) و سه روش تطبیق: دقیق، نرمال‌شده، شناسه.
 */
function wooFindExisting(array $w, string $title, string $suffix = '', string $productKey = ''): ?array {
    $tries = [$title];
    $base = $suffix !== '' ? trim(str_replace($suffix, '', $title)) : '';
    if ($base !== '' && $base !== $title) $tries[] = $base;
    foreach ($tries as $q) {
        if (trim($q) === '') continue;
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
                    'products?search=' . urlencode($q) . '&status=any&per_page=20');
        if (empty($r['ok']) || !is_array($r['body'] ?? null)) continue;
        $how = '';
        $hit = findRemoteByTitle($r['body'], $title, $base, 'name', $how);
        if ($hit) return $hit;
        $byId = findRemoteById($r['body'], 'woo', $productKey);
        if ($byId) return $byId;
    }
    return null;
}

/**
 * v8.71: محصول موجود را در باسلام پیدا می‌کند.
 * چند وضعیت و چند عبارت جست‌وجو، با تطبیق نرمال‌شده و شناسهٔ ثبت‌شده.
 */
/**
 * v8.80: همهٔ وضعیت‌های ممکن، طبق فهرست رسمی خود باسلام.
 *
 * تا ۸.۷۹ فقط پنج وضعیت پرس‌وجو می‌شد (2976، 3790، 3567، 3568، 4184) ولی
 * enum رسمی نُه‌تاست. محصولی که در 2977، 2978، 3248 یا 4221 نشسته باشد در
 * هیچ‌کدام از جست‌وجوهای ما دیده نمی‌شد — با این حال نامش را اشغال کرده و
 * باسلام موقع ساختن، «نام تکراری» می‌دهد. دقیقاً همان بن‌بست.
 */
function bslAllStatuses(): array {
    return [2976, 2977, 2978, 3248, 3567, 3568, 3790, 4184, 4221];
}
function bslStatusQuery(): string {
    $q = '';
    foreach (bslAllStatuses() as $s) $q .= '&statuses=' . $s;
    return $q;
}

/* =====================================================================
 *  v10.35 (۴۷ب): کشِ کاتالوگِ غرفه — به‌جای آبشارِ جست‌وجو برای هر محصول
 *
 *  مشکل: bslFindExisting برای هر محصولی که در دفترچه نبود، تا پنج مرحله
 *  جست‌وجو می‌رفت و در بدترین حالت ۲۰ صفحهٔ ۱۰۰تایی از غرفه را پیمایش
 *  می‌کرد — یعنی تا ۲۴ درخواست برای *یک* محصول، و همهٔ این کار فقط برای
 *  جوابِ «هست یا نیست». روی یک پروفایلِ چندهزارتایی این ده‌ها هزار
 *  درخواست است؛ روی هاستِ اشتراکی یعنی تایم‌اوت.
 *
 *  کلیدِ ماجرا این است که آن آبشار هر بار *همان* داده را دوباره می‌گیرد:
 *  فهرستِ محصولاتِ غرفه. پس یک بار کاملش را می‌گیریم و نگه می‌داریم.
 *  با ۳۰۰۰ محصول، ۳۰ درخواست به‌جای ده‌ها هزار.
 *
 *  ⚠️ شیر اطمینان (خواستهٔ صریحِ کاربر در بندِ ۴۶): این کش آینهٔ کارِ
 *  خودِ ماست و اگر کسی از پنلِ باسلام محصولی اضافه/حذف کند، از آن بی‌خبر
 *  است. پس:
 *    • TTL دارد (۶ ساعت) و بعد از آن خودبه‌خود از نو ساخته می‌شود.
 *    • اگر کاتالوگ به سقفِ صفحه‌ها خورده باشد (partial)، «نبودن» در کش
 *      هرگز به‌عنوانِ «وجود ندارد» پذیرفته نمی‌شود و آبشارِ کامل اجرا
 *      می‌شود — یعنی بدترین حالتش رفتارِ نسخهٔ قبل است، نه بدتر.
 *    • دکمهٔ بازسازیِ دستی هم هست (?bsl_catalog=rebuild).
 * ===================================================================== */

function bslCatalogFile(int $vid): string {
    return BSL_CATALOG_PREFIX . max(0, $vid) . '.json';
}

/* =====================================================================
 * v10.41 (۵۵): کشِ درختِ دسته‌بندیِ باسلام
 *
 * مسئله: `GET categories` کلِ درخت را در یک پاسخ برمی‌گرداند، ولی تا
 * ۱۰.۴۰ در ۱۸ نقطهٔ پراکندهٔ کد مستقیماً صدا زده می‌شد و هرکدام هم یک
 * نسخهٔ کپی‌شدهٔ همان تابعِ «تخت‌کردنِ بازگشتی» را داشت. نتیجه: روی یک
 * اجرای «اصلاح دسته‌بندی» ده‌ها بار همان چند صد کیلوبایت دوباره دانلود
 * می‌شد، و اگر یک بارِ آن‌ها تایم‌اوت می‌خورد، آن اندپوینت با فهرستِ
 * خالی ادامه می‌داد.
 *
 * راه‌حل: یک واکشیِ کامل، ذخیره روی دیسک، و بقیهٔ کد فقط از کش می‌خوانند.
 *   • bslCatsFetch()  — واکشیِ خام + تخت‌کردن (تنها نقطه‌ای که شبکه می‌زند)
 *   • bslCatsRead()   — خواندنِ کش، بدونِ هیچ درخواستی
 *   • bslCatsAll()    — نقطهٔ ورودِ همه: کش هست؟ بده. نیست؟ یک‌بار بگیر.
 *   • bslCatsLeaves() — همان با فیلترِ برگ (level >= 2)
 *
 * درختِ دسته‌ها دادهٔ سراسریِ باسلام است نه غرفه‌ای، پس فایل مشترک است.
 * شیر اطمینان: TTL ۳۰ روزه + بازسازیِ دستی (?bsl_cats=rebuild). اگر
 * واکشی شکست خورد ولی کشِ منقضی موجود بود، همان کشِ کهنه برگردانده
 * می‌شود — فهرستِ کمی قدیمی بی‌نهایت بهتر از فهرستِ خالی است.
 * ===================================================================== */

/** درختِ خامِ باسلام را به آرایهٔ تختِ ['id','name','level'] تبدیل می‌کند */
function bslCatsFlatten($items, int $lv = 0): array {
    if (!is_array($items)) return [];
    $out = [];
    foreach ($items as $c) {
        if (!is_array($c)) continue;
        $id = (int)($c['id'] ?? 0);
        $nm = trim((string)($c['title'] ?? ($c['name'] ?? '')));
        if ($id > 0) $out[] = ['id' => $id, 'name' => $nm, 'level' => $lv];
        $ch = $c['children'] ?? [];
        if (is_array($ch) && $ch) {
            foreach (bslCatsFlatten($ch, $lv + 1) as $s) $out[] = $s;
        }
    }
    return $out;
}

/** کشِ دسته‌ها را می‌خواند (بدون هیچ درخواستِ شبکه‌ای) */
function bslCatsRead(): array {
    if (!is_file(BSL_CATS_FILE)) return [];
    $j = json_decode((string)@file_get_contents(BSL_CATS_FILE), true);
    if (!is_array($j) || empty($j['items']) || !is_array($j['items'])) return [];
    return $j;
}

/** آیا کشِ موجود هنوز تازه است؟ */
function bslCatsFresh(array $c): bool {
    if (empty($c['items'])) return false;
    $at = (int)($c['at'] ?? 0);
    return $at > 0 && (time() - $at) < (int)BSL_CATS_TTL;
}

/**
 * تنها نقطه‌ای که واقعاً `GET categories` را صدا می‌زند.
 * برمی‌گرداند: ['ok'=>bool,'items'=>[],'roots'=>int,'error'=>string]
 */
function bslCatsFetch(string $tk): array {
    $r = bslReq($tk, 'GET', 'categories');
    if (empty($r['ok'])) {
        return ['ok' => false, 'items' => [], 'roots' => 0,
                'error' => 'HTTP ' . (int)($r['code'] ?? 0) . ' ' . mb_substr((string)($r['raw'] ?? ''), 0, 200)];
    }
    $data = $r['body']['data'] ?? ($r['body'] ?? []);
    if (!is_array($data)) $data = [];
    $flat = bslCatsFlatten($data, 0);
    if (!$flat) return ['ok' => false, 'items' => [], 'roots' => 0, 'error' => 'پاسخِ خالی'];
    return ['ok' => true, 'items' => $flat, 'roots' => count($data), 'error' => ''];
}

/** کش را روی دیسک می‌نویسد */
function bslCatsWrite(array $items, int $roots): bool {
    $lv = [];
    foreach ($items as $c) { $l = (int)($c['level'] ?? 0); $lv[$l] = ($lv[$l] ?? 0) + 1; }
    ksort($lv);
    $rec = ['at' => time(), 'count' => count($items), 'roots' => $roots,
            'levels' => $lv, 'items' => $items];
    return (bool)@file_put_contents(BSL_CATS_FILE, json_encode($rec, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/**
 * نقطهٔ ورودِ همهٔ مصرف‌کننده‌ها.
 *
 * $force=true فقط برای بازسازیِ دستی است؛ مسیرهای عادی هرگز آن را
 * نمی‌فرستند، پس در یک اجرای اصلاحِ دسته‌بندی حداکثر یک درخواست می‌رود.
 * در همان اجرا هم نتیجه در حافظه نگه داشته می‌شود تا حتی فایل دوباره
 * خوانده نشود.
 */
function bslCatsAll(string $tk, bool $force = false): array {
    static $mem = null;
    if (!$force && is_array($mem)) return $mem;

    $c = bslCatsRead();
    if (!$force && bslCatsFresh($c)) { $mem = $c['items']; return $mem; }

    $f = bslCatsFetch($tk);
    if (!empty($f['ok'])) {
        bslCatsWrite($f['items'], (int)$f['roots']);
        $mem = $f['items'];
        return $mem;
    }
    /* واکشی شکست خورد: کشِ کهنه بهتر از هیچ */
    if (!empty($c['items'])) { $mem = $c['items']; return $mem; }
    return [];
}

/** فقط دسته‌های برگ (level >= 2) — همان فیلترِ تکراریِ چند اندپوینت */
function bslCatsLeaves(string $tk): array {
    $o = [];
    foreach (bslCatsAll($tk) as $c) if ((int)($c['level'] ?? 0) >= 2) $o[] = $c;
    return $o;
}

/** وضعیتِ کش برای نمایش در رابط کاربری */
function bslCatsStatus(): array {
    $c = bslCatsRead();
    if (empty($c['items'])) return ['cached' => false, 'count' => 0, 'at' => 0, 'fresh' => false, 'levels' => []];
    return ['cached' => true, 'count' => (int)($c['count'] ?? count($c['items'])),
            'at' => (int)($c['at'] ?? 0), 'fresh' => bslCatsFresh($c),
            'roots' => (int)($c['roots'] ?? 0), 'levels' => $c['levels'] ?? []];
}

/**
 * v10.39 (۵۳): بازهٔ تازه‌سازیِ کش، قابل تنظیم از رابط کاربری.
 *
 * تا ۱۰.۳۸ عددِ ۶ ساعت در ثابت هاردکد بود. کاربر ممکن است غرفه‌ای پرتغییر
 * داشته باشد (بازهٔ کوتاه‌تر) یا غرفه‌ای که ماه‌ها ثابت است (بازهٔ بلندتر و
 * صرفه‌جوییِ بیشتر). کف ۱۵ دقیقه است تا کسی سهواً کش را بی‌اثر نکند.
 */
function bslCatalogTtl(?array $cn = null): int {
    if ($cn === null) $cn = loadConnections();
    $h = $cn['bsl_catalog_ttl_h'] ?? 0;
    if ((float)$h <= 0) return (int)BSL_CATALOG_TTL;
    return max(900, min(604800, (int)round((float)$h * 3600)));
}

/** کشِ روی دیسک را می‌خواند (بدون هیچ درخواستِ شبکه‌ای) */
function bslCatalogRead(int $vid): array {
    $f = bslCatalogFile($vid);
    if (!is_file($f)) return [];
    $d = json_decode((string)@file_get_contents($f), true);
    if (!is_array($d) || !is_array($d['items'] ?? null)) return [];
    return $d;
}

/** آیا کشِ این غرفه تازه است؟ */
function bslCatalogFresh(int $vid, ?array $c = null): bool {
    if ($c === null) $c = bslCatalogRead($vid);
    if (!$c) return false;
    $at = (int)($c['at'] ?? 0);
    return $at > 0 && (time() - $at) <= bslCatalogTtl();
}

/**
 * کلِ فهرستِ محصولاتِ یک غرفه را می‌گیرد و به شکلِ «عنوانِ نرمال ⇒ شناسه»
 * روی دیسک می‌نشاند.
 * خروجی: ['ok','count','pages','partial','from'=>'cache|network']
 */
function bslCatalogBuild(string $tk, int $vid, bool $force = false): array {
    if ($tk === '' || $vid <= 0) return ['ok' => false, 'error' => 'غرفهٔ نامعتبر'];
    if (!$force) {
        $c = bslCatalogRead($vid);
        if (bslCatalogFresh($vid, $c))
            return ['ok' => true, 'count' => (int)($c['count'] ?? 0), 'pages' => (int)($c['pages'] ?? 0),
                    'products' => (int)($c['products'] ?? 0), 'total_count' => (int)($c['total_count'] ?? 0),
                    'partial' => !empty($c['partial']), 'from' => 'cache'];
    }
    $statuses = bslStatusQuery();
    $items = []; $pages = 0; $partial = false; $rowsFull = []; $seenId = [];
    /* v10.40 (۵۴الف): «تعدادِ کلِ محصول» را از خودِ پاسخ می‌گیریم تا شرطِ
       پایان فقط به total_page وابسته نباشد. */
    $totalCount = 0;
    for ($page = 1; $page <= (int)BSL_CATALOG_MAX_PAGES; $page++) {
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?per_page=100&page=' . $page . $statuses);
        if (empty($r['ok'])) {
            /* شکستِ وسطِ راه ⇒ کشِ ناقص. ذخیره‌اش می‌کنیم (برای hitها مفید
               است) ولی partial علامت می‌خورد تا «نبودن» هرگز قطعی نشود. */
            $partial = true; break;
        }
        /* v10.40 (۵۴الف): تا ۱۰.۳۹ فقط $r['body']['data'] خوانده می‌شد. اگر
           باسلام روی این مسیر ردیف‌ها را زیر data.products (یا items/results)
           بگذارد، $rows خالی می‌شد و حلقه *بی‌صدا* در همان صفحه می‌ایستاد.
           bslRowsOf همهٔ آن شکل‌ها را می‌فهمد و در ?bsl_products هم
           سال‌هاست همین استفاده می‌شود. */
        $rows = bslRowsOf($r['body']);
        if (!is_array($rows) || !$rows) break;
        if ($totalCount <= 0) $totalCount = bslMetaInt($r['body'], 'total_count', 0);
        $pages++;
        foreach ($rows as $row) {
            if (!is_array($row)) continue;
            $id = (int)($row['id'] ?? 0);
            $t  = (string)($row['title'] ?? ($row['name'] ?? ''));
            if ($id <= 0 || $t === '') continue;
            $seenId[$id] = true;   // v10.40 (۵۴الف): شمارشِ محصولِ یکتا، مستقل از کلیدهای عنوان
            $n = reconNormTitle($t);
            if ($n !== '' && !isset($items[$n])) $items[$n] = $id;
            /* بدونِ پسوندِ کد محصول هم ثبت می‌شود — همان تسامحی که آبشار
               در آخرین مرحله‌اش داشت، وگرنه کش از آن ضعیف‌تر می‌شد. */
            $n2 = reconNormTitle(stripProductCode($t));
            if ($n2 !== '' && !isset($items[$n2])) $items[$n2] = $id;
            /* v10.39 (۵۳): ردیفِ کامل هم نگه داشته می‌شود تا مصرف‌کننده‌هایی
               مثل حذفِ تکراری بتوانند بدونِ یک برداشتِ *دوباره* از باسلام
               کارشان را بکنند. تا ۱۰.۳۸ فقط «عنوان ⇒ شناسه» ذخیره می‌شد و
               برای همین dedup مجبور بود همان صفحه‌ها را از نو بگیرد. */
            $rv = $row['revision']['data'] ?? [];
            $st = $row['status'] ?? null;
            $rowsFull[] = [
                'id'     => $id,
                'name'   => trim($t),
                'status' => (int)(is_array($st) ? ($st['value'] ?? 0) : $st),
                'price'  => (int)($rv['primary_price'] ?? ($row['price'] ?? 0)),
                'stock'  => (int)($rv['stock'] ?? ($row['stock'] ?? 0)),
                'ts'     => $id,
            ];
        }
        /* =============================================================
           v10.40 (۵۴الف): شرطِ پایانِ حلقه بازنویسی شد.

           باگ: تا ۱۰.۳۹ اینجا مستقیم $r['body']['total_page'] خوانده
           می‌شد. باسلام این کلید را — بسته به مسیر — زیر body، یا زیر
           body['meta'] / body['pagination'] / body['data'] می‌گذارد.
           وقتی کلید سرِ جای خام نبود، مقدار به پیش‌فرضِ ۱ می‌افتاد و
           حلقه در پایانِ *همان صفحه* می‌شکست. برداشت ناقص می‌ماند و
           هیچ‌کس خبردار نمی‌شد، چون partial هم علامت نمی‌خورد.
           هلپرِ bslMetaInt دقیقاً برای همین نوشته شده بود و ?bsl_products
           از آن استفاده می‌کرد؛ فقط این مسیر جا مانده بود.

           حالا سه لایهٔ پایان داریم و «صفحهٔ ناقص» معتبرترین‌شان است:
             ۱) صفحه‌ای که کمتر از per_page ردیف داد ⇒ قطعاً آخرین است.
                این نشانه از هر متادیتایی قابل‌اعتمادتر است، چون از خودِ
                داده می‌آید نه از ادعای سرور.
             ۲) total_page، اما فقط وقتی واقعاً >۰ باشد. اگر متادیتا
                غایب بود دیگر «۱» فرض نمی‌کنیم — ادامه می‌دهیم تا
                شرطِ (۱) یا (۳) برسد.
             ۳) total_count: اگر سرور گفته کلاً N محصول دارد و ما N
                شناسهٔ یکتا دیده‌ایم، کار تمام است.
           ============================================================= */
        $tp = bslMetaInt($r['body'], 'total_page', 0);
        if (count($rows) < 100) break;                       // (۱) صفحهٔ ناقص = آخرین صفحه
        if ($tp > 0 && $page >= $tp) break;                  // (۲) متادیتای معتبر
        if ($totalCount > 0 && count($seenId) >= $totalCount) break;   // (۳) همه را گرفته‌ایم
        if ($page >= (int)BSL_CATALOG_MAX_PAGES) $partial = true;
        /* غرفهٔ چندهزارتایی یعنی چند صد درخواستِ پشتِ‌هم؛ کمی مکث تا
           باسلام محدودیتِ نرخ نزند و برداشت وسطِ راه نشکند. */
        usleep(80000);
    }
    $data = ['vendor_id' => $vid, 'at' => time(), 'pages' => $pages,
             'count' => count($items), 'partial' => $partial, 'items' => $items,
             'rows' => $rowsFull, 'rows_count' => count($rowsFull),
             /* v10.40 (۵۴الف): تعدادِ محصولِ *واقعی* (شناسهٔ یکتا). تا ۱۰.۳۹
                فقط count بود که کلیدهای نرمال‌شده را می‌شمرد — و چون هر
                محصول تا دو کلید می‌سازد، عددِ نمایش‌داده‌شده هیچ‌وقت
                «تعدادِ محصول» نبود. */
             'products' => count($seenId),
             'total_count' => $totalCount];
    @file_put_contents(bslCatalogFile($vid), json_encode($data, JSON_UNESCAPED_UNICODE), LOCK_EX);
    $GLOBALS['_bslCatalog'][$vid] = $data;
    return ['ok' => true, 'count' => count($items), 'pages' => $pages,
            'products' => count($seenId), 'total_count' => $totalCount,
            'partial' => $partial, 'from' => 'network'];
}

/** کشِ غرفه، با کشِ درون‌پردازه‌ای تا در یک اجرا صدها بار از دیسک خوانده نشود */
function bslCatalogGet(string $tk, int $vid, bool $build = true): array {
    if (isset($GLOBALS['_bslCatalog'][$vid]) && bslCatalogFresh($vid, $GLOBALS['_bslCatalog'][$vid]))
        return $GLOBALS['_bslCatalog'][$vid];
    $c = bslCatalogRead($vid);
    if (bslCatalogFresh($vid, $c)) { $GLOBALS['_bslCatalog'][$vid] = $c; return $c; }
    if (!$build) return [];
    bslCatalogBuild($tk, $vid, true);
    return $GLOBALS['_bslCatalog'][$vid] ?? [];
}

/**
 * پاسخِ کش به «این عنوان در این غرفه هست؟»
 *   > 0  ⇒ شناسهٔ محصول
 *   0    ⇒ کش می‌گوید نیست و *قابل اعتماد* است (کش کامل و تازه)
 *   -1   ⇒ کش نمی‌داند (نبود، کهنه بود، یا ناقص بود) ⇒ آبشار را اجرا کن
 */
function bslCatalogLookup(string $tk, int $vid, string $title, bool $build = true): int {
    if ($vid <= 0 || trim($title) === '') return -1;
    $c = bslCatalogGet($tk, $vid, $build);
    if (!$c || !is_array($c['items'] ?? null)) return -1;
    foreach ([reconNormTitle($title), reconNormTitle(stripProductCode($title))] as $n) {
        if ($n !== '' && isset($c['items'][$n])) return (int)$c['items'][$n];
    }
    return !empty($c['partial']) ? -1 : 0;
}

/** محصولِ تازه‌ساخته/تازه‌پیداشده را همان لحظه وارد کش می‌کند */
function bslCatalogNote(int $vid, string $title, int $id): void {
    if ($vid <= 0 || $id <= 0 || trim($title) === '') return;
    $c = $GLOBALS['_bslCatalog'][$vid] ?? bslCatalogRead($vid);
    if (!$c || !is_array($c['items'] ?? null)) return;
    $ch = false;
    foreach ([reconNormTitle($title), reconNormTitle(stripProductCode($title))] as $n) {
        if ($n !== '' && ($c['items'][$n] ?? 0) !== $id) { $c['items'][$n] = $id; $ch = true; }
    }
    if (!$ch) return;
    $c['count'] = count($c['items']);
    $GLOBALS['_bslCatalog'][$vid] = $c;
    @file_put_contents(bslCatalogFile($vid), json_encode($c, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/** پاک‌کردنِ کش — vid=0 یعنی همهٔ غرفه‌ها. خروجی: تعداد فایلِ پاک‌شده */
function bslCatalogClear(int $vid = 0): int {
    $GLOBALS['_bslCatalog'] = [];
    if ($vid > 0) return @unlink(bslCatalogFile($vid)) ? 1 : 0;
    $n = 0;
    foreach (glob(BSL_CATALOG_PREFIX . '*.json') ?: [] as $f) if (@unlink($f)) $n++;
    return $n;
}

/** شمارندهٔ صرفه‌جویی — چند بار کش جلوی آبشار را گرفت */
function bslCatalogSaved(int $add = 0): int {
    static $n = 0;
    if ($add > 0) $n += $add;
    return $n;
}

/**
 * v10.39 (۵۳): ردیف‌های کاملِ یک غرفه از روی کش.
 *
 * این همان چیزی است که تا حالا هر مصرف‌کننده خودش با ده‌ها درخواست از
 * باسلام می‌گرفت. حالا یک بار در کش می‌نشیند و همه از همان می‌خوانند.
 *
 * $build=false یعنی «اگر کش نیست/کهنه است، شبکه را دست نزن» — برای جاهایی
 * که فقط می‌خواهند وضعیتِ کش را گزارش کنند.
 * خروجی: ['rows'=>[], 'from'=>'cache|network|none', 'partial'=>bool, 'at'=>int]
 */
function bslCatalogRows(string $tk, int $vid, bool $build = true): array {
    $c = null;
    if (isset($GLOBALS['_bslCatalog'][$vid]) && bslCatalogFresh($vid, $GLOBALS['_bslCatalog'][$vid]))
        $c = $GLOBALS['_bslCatalog'][$vid];
    if ($c === null) { $r = bslCatalogRead($vid); if (bslCatalogFresh($vid, $r)) $c = $r; }
    $from = 'cache';
    /* کشِ ساختهٔ نسخه‌های قبل فقط items داشت و rows نداشت؛ آن هم باید
       دوباره ساخته شود وگرنه مصرف‌کننده فهرستِ خالی می‌بیند. */
    if ($c !== null && !is_array($c['rows'] ?? null)) $c = null;
    if ($c === null) {
        if (!$build) return ['rows' => [], 'from' => 'none', 'partial' => true, 'at' => 0];
        bslCatalogBuild($tk, $vid, true);
        $c = $GLOBALS['_bslCatalog'][$vid] ?? bslCatalogRead($vid);
        $from = 'network';
    }
    if (!is_array($c) || !is_array($c['rows'] ?? null))
        return ['rows' => [], 'from' => 'none', 'partial' => true, 'at' => 0];
    return ['rows' => $c['rows'], 'from' => $from,
            'partial' => !empty($c['partial']), 'at' => (int)($c['at'] ?? 0)];
}

function bslFindExisting(string $tk, int $vid, string $title, string $productKey = ''): ?array {
    $q = bslNormalizeTitle($title);
    $statuses = bslStatusQuery();
    // v8.72: اول شناسهٔ ثبت‌شده. باسلام می‌گوید «نام قبلاً برای محصول دیگری
    // انتخاب شده» — یعنی عنوانِ ذخیره‌شده در غرفه ممکن است اصلاً شبیه عنوان
    // ما نباشد و هیچ جست‌وجویی پیدایش نکند. ولی شناسه‌اش را از ارسال قبلی
    // داریم، پس مستقیم همان را می‌خوانیم.
    if ($productKey !== '') {
        $mapped = (int)((remoteMapLoad()['bsl'][$productKey]['id'] ?? 0));
        if ($mapped > 0) {
            $one = bslReq($tk, 'GET', 'products/' . $mapped);
            $row = $one['body']['data'] ?? ($one['body'] ?? null);
            if (!empty($one['ok']) && is_array($row) && (int)($row['id'] ?? 0) > 0) return $row;
            // حتی اگر خواندن مستقیم جواب نداد، خودِ شناسه برای PATCH کافی است
            return ['id' => $mapped, 'title' => $title, '__from_ledger' => true];
        }
    }
    /* =================================================================
       v10.35 (۴۷ب): گامِ دومِ ارزان — کشِ کاتالوگِ غرفه.

       پیش از هر درخواستی، از فهرستی که یک بار گرفته‌ایم می‌پرسیم. سه
       جوابِ ممکن دارد و هر سه معنی‌دارند:
         شناسه ⇒ همان‌جا برمی‌گردیم (صفر درخواست)
         «نیست» با کشِ کامل و تازه ⇒ محصول واقعاً در غرفه نیست، پس
             آبشارِ ۵ مرحله‌ای هیچ چیزی پیدا نمی‌کند و فقط وقت می‌سوزاند
         «نمی‌دانم» ⇒ دقیقاً مثل قبل ادامه می‌دهیم
       ================================================================= */
    $__cat = bslCatalogLookup($tk, $vid, $title);
    if ($__cat > 0) {
        bslCatalogSaved(1);
        return ['id' => $__cat, 'title' => $title, '__from_catalog' => true];
    }
    if ($__cat === 0) { bslCatalogSaved(1); return null; }

    /* v8.79: پارامتر درست «title» است نه «search». باسلام پارامتر ناشناخته
       را بی‌صدا نادیده می‌گیرد، پس تا حالا این درخواست یک صفحهٔ دلخواه از
       غرفه را برمی‌گرداند و تطبیق عنوان تقریباً همیشه شکست می‌خورد. همین
       باعث می‌شد «تکراری است» بگیریم ولی محصول موجود پیدا نشود. */
    foreach (array_unique([$q, trim($title)]) as $term) {
        if ($term === '') continue;
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?per_page=50'
             . $statuses . '&title=' . urlencode($term));
        if (empty($r['ok'])) continue;
        $rows = $r['body']['data'] ?? [];
        if (!is_array($rows) || !$rows) continue;
        $how = '';
        $hit = findRemoteByTitle($rows, $title, '', 'title', $how);
        if ($hit) return $hit;
        $byId = findRemoteById($rows, 'bsl', $productKey);
        if ($byId) return $byId;
    }

    /* v8.80: دو مسیر دیگر که تا حالا اصلاً استفاده نمی‌کردیم.
       فهرست غرفه تنها راه رسیدن به شناسهٔ محصول نیست. */
    // ۱) فهرست سراسری محصولات با فیلتر غرفه و عنوان
    foreach (array_unique([trim($title), $q]) as $term) {
        if ($term === '') continue;
        $g = bslReq($tk, 'GET', 'products?vendor_ids=' . $vid
             . '&product_title=' . urlencode($term) . '&per_page=50');
        if (empty($g['ok'])) continue;
        $rows = $g['body']['data'] ?? ($g['body']['products'] ?? []);
        if (!is_array($rows) || !$rows) continue;
        $how = '';
        $hit = findRemoteByTitle($rows, $title, '', 'title', $how);
        if ($hit) return $hit;
        $byId = findRemoteById($rows, 'bsl', $productKey);
        if ($byId) return $byId;
    }
    // ۲) موتور جست‌وجوی خود باسلام
    $sr = bslReq($tk, 'POST', 'products/search',
          ['q' => trim($title), 'rows' => 30, 'start' => 0,
           'filters' => ['vendorIds' => (string)$vid]]);
    if (!empty($sr['ok'])) {
        $rows = $sr['body']['products'] ?? ($sr['body']['data'] ?? []);
        if (is_array($rows) && $rows) {
            $how = '';
            $hit = findRemoteByTitle($rows, $title, '', 'title', $how);
            if ($hit) return $hit;
            $byId = findRemoteById($rows, 'bsl', $productKey);
            if ($byId) return $byId;
        }
    }

    /* v8.79: آخرین راه — پیمایش کل غرفه.
       فیلتر «title» سمت باسلام تطبیق سادهٔ رشته‌ای است و به نیم‌فاصله،
       ی/ک عربی و علائم حساس است؛ ولی مقایسهٔ ما (reconNormTitle) همهٔ
       این‌ها را یکسان می‌بیند. پس محصولی که واقعاً همان است می‌تواند از
       فیلتر سمت سرور رد شود. چون فقط وقتی به اینجا می‌رسیم که باسلام
       گفته «تکراری است»، هزینهٔ این پیمایش به‌جاست: بدون آن، محصول نه
       ساخته می‌شود نه آپدیت. */
    $want = reconNormTitle($title);
    if ($want === '') return null;
    for ($page = 1; $page <= 20; $page++) {
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?per_page=100&page=' . $page . $statuses);
        if (empty($r['ok'])) break;
        /* v10.40 (۵۴الف): همان اصلاحِ صفحه‌بندی — ردیف‌ها از هر سه شکلِ
           پاسخ خوانده می‌شوند، نه فقط data. */
        $rows = bslRowsOf($r['body']);
        if (!$rows) break;
        $how = '';
        $hit = findRemoteByTitle($rows, $title, '', 'title', $how);
        if ($hit) return $hit;
        $byId = findRemoteById($rows, 'bsl', $productKey);
        if ($byId) return $byId;
        // بدون پسوند کد محصول هم بسنج — «(کد: ۱)» در مقصد ممکن است نباشد
        foreach ($rows as $row) {
            if (!is_array($row)) continue;
            $rt = reconNormTitle(stripProductCode((string)($row['title'] ?? '')));
            if ($rt !== '' && $rt === reconNormTitle(stripProductCode($title))) return $row;
        }
        /* v10.40 (۵۴الف): صفحهٔ ناقص معتبرترین نشانهٔ پایان است؛
           total_page فقط اگر واقعاً آمده باشد اعمال می‌شود (پیش‌فرضِ ۱
           باعث می‌شد پیمایش همیشه در پایانِ صفحهٔ اول بایستد). */
        if (count($rows) < 100) break;
        $tp = bslMetaInt($r['body'], 'total_page', 0);
        if ($tp > 0 && $page >= $tp) break;
    }
    return null;
}

function detectImageFormat(string $data): string {
if(strlen($data)<4)return '';
$sig=substr($data,0,4);

if(substr($data,0,2)==="\xFF\xD8")return 'jpg';

if($sig==="\x89PNG")return 'png';

if(substr($data,0,3)==='GIF')return 'gif';

if($sig==='RIFF'&&substr($data,8,4)==='WEBP')return 'webp';

if($sig==='BM')return 'bmp';

if(substr($data,4,4)==='ftyp'&&(substr($data,8,4)==='avif'||substr($data,8,4)==='avis'))return 'avif';

if(substr($data,4,4)==='ftyp'&&(substr($data,8,4)==='heic'||substr($data,8,4)==='heix'||substr($data,8,4)==='mif1'))return 'heic';

if(substr($data,0,4)==='<svg')return 'svg';

if($sig==="\x00\x00\x01\x00")return 'ico';

if($sig==="II\x2A\x00")return 'tiff';

if($sig==="MM\x00\x2A")return 'tiff';
return '';
}

function convertToSupportedFormat(string $data): array {
$fmt=detectImageFormat($data);

if(in_array($fmt,['jpg','png','gif','webp','bmp','']))return['ok'=>true,'data'=>$data,'format'=>$fmt?:'jpg'];

if(!function_exists('imagecreatefromstring'))return['ok'=>false,'error'=>'GD not available, cannot convert '.$fmt];
$img=@imagecreatefromstring($data);
if(!$img)return['ok'=>false,'error'=>'imagecreatefromstring failed for '.$fmt];

ob_start();
imagejpeg($img,null,90);
$jpgData=ob_get_clean();
imagedestroy($img);
if($jpgData&&strlen($jpgData)>100)return['ok'=>true,'data'=>$jpgData,'format'=>'jpg','converted_from'=>$fmt];
return['ok'=>false,'error'=>'JPEG conversion failed for '.$fmt];
}

function isImageData(string $data): bool {
if (strlen($data) < 50) return false;
$sig = substr($data, 0, 4);

if (substr($data, 0, 2) === "\xFF\xd8") return true;

if ($sig === "\x89PNG") return true;

if (substr($data, 0, 3) === "GIF") return true;

if ($sig === "RIFF" && substr($data, 8, 4) === "WEBP") return true;

if ($sig === "BM") return true;

if ($sig === "\x00\x00\x01\x00") return true;

if ($sig === "II\x2a\x00") return true;

if ($sig === "MM\x00\x2a") return true;

if (substr($data, 4, 4) === "ftyp" && (substr($data, 8, 4) === "avif" || substr($data, 8, 4) === "avis")) return true;

if (substr($data, 4, 4) === "ftyp" && (substr($data, 8, 4) === "heic" || substr($data, 8, 4) === "heix" || substr($data, 8, 4) === "mif1")) return true;

if (substr($data, 0, 4) === '<svg') return true;

if (substr($data, 0, 1) === '<' && substr($data, 0, 4) !== '<svg') return false;
if (substr($data, 0, 1) === '{') return false;
if (substr($data, 0, 5) === '<?xml') return false;

if (strlen($data) >= 500) {

$sample = substr($data, 0, 100);
$hasNull = strpos($sample, "\x00") !== false;
$hasNonPrintable = preg_match('/[\\x00-\\x08\\x0E-\\x1F]/', $sample);
if ($hasNull || $hasNonPrintable) return true;
}
return false;
}

function saveImageLocal(string $imgUrl, string $productLink = ''): string {
if (empty($imgUrl) || preg_match('~^(data:|blob:|javascript:|#)~i', $imgUrl)) return '';
$imgUrl=html_entity_decode($imgUrl,ENT_QUOTES|ENT_HTML5,'UTF-8');
if (!is_dir(UPLOAD_DIR)) @mkdir(UPLOAD_DIR, 0755, true);
$cacheKey = md5($imgUrl);

$existing = glob(UPLOAD_DIR . 'img_' . $cacheKey . '.*');
foreach ($existing as $f) {
if (file_exists($f) && filesize($f) > 200) {
$fdata = file_get_contents($f);
if (isImageData($fdata)) return $f;
@unlink($f);
break;
}
}
$parsed = parse_url($imgUrl);
$origin = ($parsed['scheme'] ?? 'https') . '://' . ($parsed['host'] ?? '');
$d = ''; $ct = 'image/jpeg';

$ch = curl_init($imgUrl);
curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>1, CURLOPT_FOLLOWLOCATION=>1, CURLOPT_MAXREDIRS=>5, CURLOPT_TIMEOUT=>25, CURLOPT_CONNECTTIMEOUT=>10, CURLOPT_SSL_VERIFYPEER=>0, CURLOPT_SSL_VERIFYHOST=>0, CURLOPT_USERAGENT=>'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36', CURLOPT_REFERER=>$imgUrl, CURLOPT_COOKIEFILE=>'', CURLOPT_HTTPHEADER=>['Accept: image/avif,image/webp,image/apng,image/*,*/*;q=0.8','Accept-Language: fa-IR,fa;q=0.9,en-US;q=0.8,en;q=0.7','Origin: '.$origin,'Sec-Fetch-Dest: image','Sec-Fetch-Mode: no-cors']]);
$d = curl_exec($ch); $err = curl_error($ch); $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE); $ct = curl_getinfo($ch, CURLINFO_CONTENT_TYPE) ?: 'image/jpeg'; curl_close($ch);
if($d && strlen($d) > 200 && isImageData($d)) {  } else { $d=''; }

if(!$d || strlen($d) < 200 || !isImageData($d ?? '')){
$ch2 = curl_init($imgUrl);
curl_setopt_array($ch2, [CURLOPT_RETURNTRANSFER=>1, CURLOPT_FOLLOWLOCATION=>1, CURLOPT_MAXREDIRS=>5, CURLOPT_TIMEOUT=>25, CURLOPT_CONNECTTIMEOUT=>10, CURLOPT_SSL_VERIFYPEER=>0, CURLOPT_SSL_VERIFYHOST=>0, CURLOPT_USERAGENT=>'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36', CURLOPT_REFERER=>$imgUrl, CURLOPT_COOKIEFILE=>'', CURLOPT_HTTPHEADER=>['Accept: image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8','Accept-Language: fa-IR,fa;q=0.9,en-US;q=0.8,en;q=0.7','Cache-Control: no-cache','Origin: '.$origin,'Sec-Ch-Ua: "Not/A)Brand";v="8", "Chromium";v="126", "Google Chrome";v="126"','Sec-Ch-Ua-Mobile: ?0','Sec-Ch-Ua-Platform: "Windows"','Sec-Fetch-Dest: image','Sec-Fetch-Mode: no-cors','Sec-Fetch-Site: cross-site']]);
$d = curl_exec($ch2); $ct2 = curl_getinfo($ch2, CURLINFO_CONTENT_TYPE); if ($ct2) $ct = $ct2; curl_close($ch2);
if(!$d || strlen($d) < 200 || !isImageData($d ?? '')) $d='';
}

if(!$d || strlen($d) < 200 || !isImageData($d ?? '')){
$pageRef = $productLink ?: $origin;
$ch3 = curl_init($imgUrl);
curl_setopt_array($ch3, [CURLOPT_RETURNTRANSFER=>1, CURLOPT_FOLLOWLOCATION=>1, CURLOPT_MAXREDIRS=>5, CURLOPT_TIMEOUT=>25, CURLOPT_CONNECTTIMEOUT=>10, CURLOPT_SSL_VERIFYPEER=>0, CURLOPT_SSL_VERIFYHOST=>0, CURLOPT_USERAGENT=>'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36', CURLOPT_REFERER=>$pageRef, CURLOPT_COOKIEFILE=>'', CURLOPT_HTTPHEADER=>['Accept: image/avif,image/webp,image/apng,image/*,*/*;q=0.8','Accept-Language: fa-IR,fa;q=0.9,en;q=0.7','Referer: '.$pageRef,'Origin: '.$origin,'Sec-Fetch-Dest: image','Sec-Fetch-Mode: no-cors']]);
$d = curl_exec($ch3); $ct3 = curl_getinfo($ch3, CURLINFO_CONTENT_TYPE); if ($ct3) $ct = $ct3; curl_close($ch3);
if(!$d || strlen($d) < 200 || !isImageData($d ?? '')) $d='';
}

if((!$d || strlen($d) < 200) && $productLink) {
$srcPage = fetch_html($productLink, 15);
if (!empty($srcPage['ok']) && !empty($srcPage['html'])) {
$freshImgUrl = extractImageFromHtml($srcPage['html'], $productLink);
if ($freshImgUrl && $freshImgUrl !== $imgUrl) {
$ch4 = curl_init($freshImgUrl);
curl_setopt_array($ch4, [CURLOPT_RETURNTRANSFER=>1, CURLOPT_FOLLOWLOCATION=>1, CURLOPT_MAXREDIRS=>5, CURLOPT_TIMEOUT=>25, CURLOPT_CONNECTTIMEOUT=>10, CURLOPT_SSL_VERIFYPEER=>0, CURLOPT_SSL_VERIFYHOST=>0, CURLOPT_USERAGENT=>'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36', CURLOPT_REFERER=>$productLink, CURLOPT_COOKIEFILE=>'', CURLOPT_HTTPHEADER=>['Accept: image/avif,image/webp,image/apng,image/*,*/*;q=0.8','Referer: '.$productLink,'Origin: '.$origin,'Sec-Fetch-Dest: image','Sec-Fetch-Mode: no-cors']]);
$d = curl_exec($ch4); $ct4 = curl_getinfo($ch4, CURLINFO_CONTENT_TYPE); if ($ct4) $ct = $ct4; curl_close($ch4);
if(!$d || strlen($d) < 200 || !isImageData($d ?? '')) $d='';
}
}
}

if(!$d || strlen($d) < 200 || !isImageData($d ?? '')){
$selfBase2=(isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.$_SERVER['HTTP_HOST'].$_SERVER['SCRIPT_NAME'];
$proxyUrl2=$selfBase2.'?image_proxy='.rawurlencode($imgUrl);
$ch5=curl_init($proxyUrl2);curl_setopt_array($ch5,[CURLOPT_RETURNTRANSFER=>1,CURLOPT_FOLLOWLOCATION=>1,CURLOPT_TIMEOUT=>25,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_SSL_VERIFYPEER=>0,CURLOPT_SSL_VERIFYHOST=>0]);
$d=curl_exec($ch5);$ct5=curl_getinfo($ch5,CURLINFO_CONTENT_TYPE);if($ct5)$ct=$ct5;curl_close($ch5);
if(!$d || strlen($d) < 200 || !isImageData($d ?? '')) $d='';
}

if (!$d || strlen($d) < 200 || !isImageData($d)) return '';

$realFmt=detectImageFormat($d);
if($realFmt==='')$realFmt='jpg';

$convResult=convertToSupportedFormat($d);
if(!empty($convResult['ok'])){
$d=$convResult['data'];
$realFmt=$convResult['format'];
}
$ext=$realFmt;
$localPath = UPLOAD_DIR . 'img_' . $cacheKey . '.' . $ext;
@file_put_contents($localPath, $d);
return $localPath;
}

function bslUpload(string $tk, string $imgUrl): array {

$imgUrl=html_entity_decode($imgUrl,ENT_QUOTES|ENT_HTML5,'UTF-8');
$imgUrl=trim($imgUrl);
if(empty($imgUrl))return['ok'=>0,'error'=>'empty URL'];
$cacheKey=md5($imgUrl);
$log=[];

$urlExt=strtolower(pathinfo(parse_url($imgUrl,PHP_URL_PATH)??'',PATHINFO_EXTENSION)?:'');
if($urlExt)$log[]='url_ext:'.$urlExt;

$retryDelay=max(0,(int)($GLOBALS['_bslRetryDelayMs']??1000));

$bslFileUpload=function($filePath)use($tk,$cacheKey,$retryDelay){
if(!file_exists($filePath)||filesize($filePath)<200)return['ok'=>0,'error'=>'file missing'];
$fdata=@file_get_contents($filePath);
if(!$fdata||!isImageData($fdata))return['ok'=>0,'error'=>'not valid image'];

$realFmt=detectImageFormat($fdata);
if($realFmt==='')$realFmt='jpg';
$fmtLog='fmt:'.$realFmt;

$convResult=convertToSupportedFormat($fdata);
if(!empty($convResult['ok'])&&!empty($convResult['converted_from'])){
$fdata=$convResult['data'];
$realFmt='jpg';
$fmtLog='fmt:'.$convResult['converted_from'].'→jpg';

@file_put_contents($filePath,$fdata);
}
$ext=$realFmt;
$ct='image/'.($ext==='jpg'?'jpeg':$ext);
$cf=new CURLFile($filePath,$ct,'product_'.$cacheKey.'.'.$ext);

for($attempt=1;$attempt<=3;$attempt++){
$r=bslReq($tk,'POST','files',['file'=>$cf,'file_type'=>'product.photo'],true);
if($r['ok']&&!empty($r['body']['id']))return['ok'=>1,'file_id'=>$r['body']['id']];
$bslErr=$r['body']['error_description']??$r['body']['message']??$r['error']??'';
if(is_array($bslErr))$bslErr=json_encode($bslErr,JSON_UNESCAPED_UNICODE);
$logMsg='BSL upload attempt '.$attempt.' fail ['.$fmtLog.']: '.mb_substr($bslErr,0,100).' (HTTP'.($r['code']??'?').')';
if($attempt<3){usleep($retryDelay*1000);}
}
return['ok'=>0,'error'=>$logMsg];
};

$existing=glob(UPLOAD_DIR.'img_'.$cacheKey.'.*');
foreach($existing as $f){
if(file_exists($f)&&filesize($f)>200){
$fdata=@file_get_contents($f);
if(!$fdata||!isImageData($fdata)){@unlink($f);continue;}
$up=$bslFileUpload($f);
if(!empty($up['ok']))return['ok'=>1,'file_id'=>$up['file_id']];
$log[]=$up['error'];

}
}

$productLink=$GLOBALS['_currentProductLink']??'';
$localPath=saveImageLocal($imgUrl,$productLink);
if($localPath&&file_exists($localPath)&&filesize($localPath)>200){
$log[]='file saved ok ('.filesize($localPath).'b)';
$up=$bslFileUpload($localPath);
if(!empty($up['ok']))return['ok'=>1,'file_id'=>$up['file_id']];
$log[]=$up['error'];
return['ok'=>0,'error'=>'تصویر آپلود نشد ['.implode(' | ',$log).']'];
}else{
$log[]='saveImageLocal failed';
}

if($productLink){
$srcPage=fetch_html($productLink,15);
if(!empty($srcPage['ok'])&&!empty($srcPage['html'])){
$freshImgUrl=extractImageFromHtml($srcPage['html'],$productLink);
if($freshImgUrl&&$freshImgUrl!==$imgUrl){
$log[]='fresh URL found';
$localPath2=saveImageLocal($freshImgUrl,$productLink);
if($localPath2&&file_exists($localPath2)&&filesize($localPath2)>200){
$up2=$bslFileUpload($localPath2);
if(!empty($up2['ok']))return['ok'=>1,'file_id'=>$up2['file_id']];
$log[]=$up2['error'];
return['ok'=>0,'error'=>'تصویر آپلود نشد ['.implode(' | ',$log).']'];
}
$log[]='fresh file not valid';
}else{
$log[]='no fresh URL found';
}
}else{
$log[]='product page fetch failed';
}
}

return['ok'=>0,'error'=>'تصویر آپلود نشد ['.implode(' | ',$log).']'];
}

/**
 * v8.64: چند تصویر را به باسلام آپلود می‌کند.
 *
 * باسلام برای هر محصول یک photo (شاخص) و یک آرایهٔ photos می‌گیرد که
 * هر دو شناسهٔ فایل آپلودشده‌اند. آپلود کند است، پس یک سقف دارد و
 * تصویری که آپلود نشود ساکت رد می‌شود تا کل محصول از دست نرود.
 *
 * خروجی: ['ok'=>bool,'main'=>int|null,'ids'=>[int...],'ok_n'=>int,'fail_n'=>int,'note'=>string]
 */
function bslUploadMany(string $tk, array $imgUrls, int $max = 10): array {
    $ids = []; $failN = 0; $firstErr = '';
    foreach (galleryDedupe($imgUrls, max(1, $max)) as $u) {
        $up = bslUpload($tk, (string)$u);
        if (!empty($up['ok']) && !empty($up['file_id'])) { $ids[] = (int)$up['file_id']; continue; }
        $failN++;
        if ($firstErr === '') $firstErr = mb_substr((string)($up['error'] ?? '?'), 0, 80);
    }
    $okN = count($ids);
    return ['ok' => $okN > 0, 'main' => $okN > 0 ? $ids[0] : null, 'ids' => $ids,
            'ok_n' => $okN, 'fail_n' => $failN,
            'note' => $okN > 0
                ? ($okN . ' تصویر آپلود شد' . ($failN > 0 ? ' (' . $failN . ' ناموفق)' : ''))
                : ('هیچ تصویری آپلود نشد' . ($firstErr !== '' ? ' — ' . $firstErr : ''))];
}

/**
 * v9.00: تنظیمات عبور برای «سایت مبدأ» — جدا از تنظیمات هوش مصنوعی.
 *
 * چرا لازم شد: سرور در ایران است و دو مشکل جدا پیش می‌آید.
 *   ۱) بعضی سایت‌ها از ایران اصلاً باز نمی‌شوند (DNS مسموم یا مسیر بسته).
 *   ۲) سایت مبدأ به‌خاطر درخواست مکرر، IP هاست را بلاک می‌کند (۴۰۳/۴۲۹).
 *
 * برای مشکل اول همان ابزارهای بخش هوش مصنوعی جواب می‌دهند (DoH، IP دستی،
 * پروکسی، Worker). برای مشکل دوم هیچ DNSی کمک نمی‌کند — بلاک روی IP است،
 * نه روی نام — و تنها راه‌ها یا کند کردن درخواست‌ها است یا عبور از یک
 * پروکسی/Worker که IP دیگری دارد.
 */
function srcNetCfg(?array $cn = null): array {
    if ($cn === null) $cn = loadConnections();
    $n = (array)($cn['src_net'] ?? []);
    // اگر کاربر چیزی تنظیم نکرده، از تنظیمات هوش مصنوعی قرض می‌گیریم
    $ai = (array)($cn['ai_net'] ?? []);
    $pick = function (string $k, $def) use ($n, $ai) {
        if (array_key_exists($k, $n) && trim((string)$n[$k]) !== '') return $n[$k];
        if (!empty($n['inherit_ai']) && array_key_exists($k, $ai)) return $ai[$k];
        return $def;
    };
    $mode = (string)($n['mode'] ?? 'direct');
    if ($mode === 'inherit') $mode = (string)($ai['mode'] ?? 'direct');
    /* v9.67: اتصال غیرمستقیمِ «به‌ازای هر پروفایل».
       وقتی این پروفایل به‌صورت صریح مستقیم را انتخاب کرده باشد
       (net_indirect خاموش)، بدونِ توجه به تنظیم سراسری، مستقیم وصل می‌شود؛
       وقتی روشن باشد، از همان روشِ غیرمستقیمِ تنظیم‌شده در src_net
       (worker/پروکسی/DoH/...) استفاده می‌شود. مقدار پیش‌فرض: غیرفعال = مستقیم. */
    if (array_key_exists('_srcNetProfileIndirect', $GLOBALS)) {
        if (empty($GLOBALS['_srcNetProfileIndirect'])) $mode = 'direct';
    }
    return [
        'mode'       => in_array($mode, ['direct','doh','dns','proxy','worker'], true) ? $mode : 'direct',
        'resolve_ip' => trim((string)$pick('resolve_ip', '')),
        'doh_url'    => trim((string)$pick('doh_url', 'https://cloudflare-dns.com/dns-query')),
        'worker_url' => trim((string)$pick('worker_url', '')),
        'proxy'      => trim((string)$pick('proxy', '')),
        'proxy_type' => (string)$pick('proxy_type', 'http'),
        'proxy_auth' => trim((string)$pick('proxy_auth', '')),
        'ipv4'       => !isset($n['ipv4']) || !empty($n['ipv4']),
        // فاصلهٔ بین درخواست‌ها به یک دامنه — ضد بلاک شدن IP
        'gap_ms'     => max(0, min(10000, (int)($n['gap_ms'] ?? 0))),
        // فقط برای همین دامنه‌ها عبور اعمال شود (خالی = همه)
        'hosts'      => trim((string)($n['hosts'] ?? '')),
        // v9.77: اگر روش اصلی شکست خورد، روش‌های جایگزینِ فعال را هم امتحان کن
        'fallback'   => !empty($n['fallback']),
    ];
}

/* v9.75: اتصالِ «فقط همین پروفایل» را برای بارگذاریِ صفحه در تبِ سلکتورها اعمال
   می‌کند. اگر تیک «اتصال غیرمستقیم»ِ پروفایل خاموش باشد → مستقیم (بدون توجه به
   تنظیمِ سراسری src_net)؛ اگر روشن باشد → همان راهِ غیرمستقیمِ سراسری. */
/* v9.76: تفسیر درستِ مقدارِ «اتصال غیرمستقیم» — ممکن است boolean، رشتهٔ
   '1'/'0' یا 'true'/'false' باشد (مخصوصاً از داده‌های قدیمی). */
function netIndirectOn($v): bool {
    if (is_bool($v)) return $v;
    if ($v === 1 || $v === '1' || strtolower((string)$v) === 'true') return true;
    return false;
}
function srcNetSetProfileIndirect(?string $pk): void {
    $on = false;
    if ($pk !== '' && $pk !== null) {
        $p = loadProfiles();
        $on = netIndirectOn($p[$pk]['net_indirect'] ?? false);
    }
    $GLOBALS['_srcNetProfileIndirect'] = $on;
}

/** آیا برای این دامنه باید از راه عبور استفاده کنیم؟ */
function srcNetApplies(array $net, string $host): bool {
    if ($net['mode'] === 'direct') return false;
    $list = trim($net['hosts']);
    if ($list === '') return true;                 // همهٔ دامنه‌ها
    $host = strtolower($host);
    foreach (preg_split('~[\s,;\r\n]+~', strtolower($list)) as $h) {
        $h = trim($h);
        if ($h === '') continue;
        if ($host === $h || substr($host, -strlen('.' . $h)) === '.' . $h) return true;
    }
    return false;
}

/**
 * v9.00: فاصلهٔ ادب بین درخواست‌ها به یک دامنه.
 * وقتی سایت مبدأ IP هاست را بلاک کرده، تندتر زدن فقط بلاک را طولانی‌تر
 * می‌کند. این تابع بین دو درخواست به یک دامنه کمی صبر می‌کند.
 */
function srcPace(string $host, int $gapMs): void {
    if ($gapMs <= 0 || $host === '') return;
    static $last = [];
    $now = microtime(true);
    if (isset($last[$host])) {
        $wait = ($gapMs / 1000) - ($now - $last[$host]);
        if ($wait > 0) usleep((int)($wait * 1000000));
    }
    $last[$host] = microtime(true);
}

function srcNetFetchAttempt(string $url, int $timeout, array $net, string $mode): array {
    $parsed = parse_url($url); $origin = ($parsed['scheme'] ?? 'https') . '://' . ($parsed['host'] ?? '');
    $host = strtolower((string)($parsed['host'] ?? ''));
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 5,
        CURLOPT_CONNECTTIMEOUT => 5, CURLOPT_TIMEOUT => $timeout, CURLOPT_ENCODING => '',
        CURLOPT_SSL_VERIFYPEER => false, CURLOPT_SSL_VERIFYHOST => 0,
        CURLOPT_USERAGENT => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36',
        CURLOPT_REFERER => $url, CURLOPT_COOKIEFILE => '',
        CURLOPT_HTTPHEADER => [
            'Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7',
            'Accept-Language: fa-IR,fa;q=0.9,en-US;q=0.8,en;q=0.7', 'Cache-Control: no-cache', 'Origin: '.$origin,
            'Sec-Ch-Ua: "Not/A)Brand";v="8", "Chromium";v="126", "Google Chrome";v="126"', 'Sec-Ch-Ua-Mobile: ?0',
            'Sec-Ch-Ua-Platform: "Windows"', 'Sec-Fetch-Dest: document', 'Sec-Fetch-Mode: navigate',
            'Sec-Fetch-Site: none', 'Sec-Fetch-User: ?1', 'Upgrade-Insecure-Requests: 1',
        ],
    ]);
    if ($mode === 'dns' || $mode === 'doh') {
        $ip = '';
        if ($mode === 'dns') $ip = (string)($net['resolve_ip'] ?? '');
        elseif (function_exists('aiDohResolve')) {
            $r = aiDohResolve($host, (string)($net['doh_url'] ?? ''), min(10, $timeout));
            if (!empty($r['ok'])) $ip = (string)$r['ip'];
        }
        if ($ip !== '') {
            $port = ((parse_url($url, PHP_URL_SCHEME) ?: 'https') === 'https') ? 443 : 80;
            curl_setopt($ch, CURLOPT_RESOLVE, [$host . ':' . $port . ':' . $ip]);
        }
    } elseif ($mode === 'proxy' && !empty($net['proxy'])) {
        curl_setopt($ch, CURLOPT_PROXY, (string)$net['proxy']);
        $map = ['http' => CURLPROXY_HTTP,
                'socks5' => defined('CURLPROXY_SOCKS5_HOSTNAME') ? CURLPROXY_SOCKS5_HOSTNAME : CURLPROXY_SOCKS5,
                'socks4' => defined('CURLPROXY_SOCKS4') ? CURLPROXY_SOCKS4 : CURLPROXY_HTTP];
        curl_setopt($ch, CURLOPT_PROXYTYPE, $map[(string)($net['proxy_type'] ?? 'http')] ?? CURLPROXY_HTTP);
        if (!empty($net['proxy_auth'])) curl_setopt($ch, CURLOPT_PROXYUSERPWD, (string)$net['proxy_auth']);
    } elseif ($mode === 'worker' && !empty($net['worker_url'])) {
        $w = rtrim((string)$net['worker_url'], '/');
        $u = (strpos($w, '{url}') !== false) ? str_replace('{url}', rawurlencode($url), $w) : $w . '/' . ltrim($url, '/');
        curl_setopt($ch, CURLOPT_URL, $u);
    }
    if ($mode !== 'direct' && !empty($net['ipv4']) && defined('CURL_IPRESOLVE_V4')) {
        curl_setopt($ch, CURLOPT_IPRESOLVE, CURL_IPRESOLVE_V4);
    }
    $body = curl_exec($ch); $err = curl_error($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    $finalUrl = curl_getinfo($ch, CURLINFO_EFFECTIVE_URL) ?: $url;
    curl_close($ch);
    return ['ok' => $body !== false && $code >= 200 && $code < 400,
            'error' => $err ?: 'Empty', 'code' => $code, 'url' => $finalUrl,
            'html' => $body === false ? '' : $body, 'mode' => $mode];
}

/* v9.00: راه عبور برای سایت مبدأ — DoH / IP دستی / پروکسی / Worker.
   v9.77: اگر تیک «استفاده از روش‌های جایگزین» روشن باشد و روشِ اصلی شکست
   بخورد (تایم‌اوت، اتصال، بلاک ۴۰۳/۴۲۹)، به ترتیبِ روش‌هایِ فعالِ دیگر هم
   امتحان می‌شود تا اولین موفق برگردد. */
function fetch_html(string $url, int $timeout = 25): array {
    $__srcNet = function_exists('loadConnections') ? srcNetCfg() : ['mode'=>'direct','gap_ms'=>0,'hosts'=>'','fallback'=>false];
    $parsed = parse_url($url); $__srcHost = strtolower((string)($parsed['host'] ?? ''));
    srcPace($__srcHost, (int)($__srcNet['gap_ms'] ?? 0));

    $modes = [];
    // روش اصلی
    if (srcNetApplies($__srcNet, $__srcHost)) $modes[] = (string)$__srcNet['mode'];
    // روش‌های جایگزینِ فعال (فقط اگر تیک روشن باشد)
    if (!empty($__srcNet['fallback'])) {
        $order = ['doh','dns','proxy','worker'];
        foreach ($order as $m) {
            if (in_array($m, $modes, true)) continue;
            if ($m === 'dns'    && trim((string)($__srcNet['resolve_ip'] ?? '')) === '') continue;
            if ($m === 'doh'    && trim((string)($__srcNet['doh_url'] ?? '')) === '') continue;
            if ($m === 'proxy'  && trim((string)($__srcNet['proxy'] ?? '')) === '') continue;
            if ($m === 'worker' && trim((string)($__srcNet['worker_url'] ?? '')) === '') continue;
            $modes[] = $m;
        }
    }
    if (empty($modes)) $modes[] = 'direct';

    $last = null;
    foreach ($modes as $m) {
        $last = srcNetFetchAttempt($url, $timeout, $__srcNet, $m);
        if (!empty($last['ok'])) return $last;
        // اگر خطای قطعیِ منطقی (مثل ۴۰۴/۴۰۰) بود، امتحانِ روشِ دیگر بی‌فایده است
        if ($last['code'] > 0 && !in_array($last['code'], [403, 429], true)) break;
    }
    return $last ?? ['ok' => false, 'error' => 'Empty', 'code' => 0, 'url' => $url, 'html' => '', 'mode' => ''];
}

function extractImageFromHtml(string $html, string $pageUrl): string {
if(empty($html)) return '';
$parsed=parse_url($pageUrl);
$base=($parsed['scheme']??'https').'://'.($parsed['host']??'');

if(preg_match('/<meta[^>]+property=["\']og:image["\'][^>]+content=["\']([^"\']+)["\']/i',$html,$m)) return resolveUrl($m[1],$base,$pageUrl);
if(preg_match('/<meta[^>]+content=["\']([^"\']+)["\'][^>]+property=["\']og:image["\']/i',$html,$m)) return resolveUrl($m[1],$base,$pageUrl);

if(preg_match('/<meta[^>]+name=["\']twitter:image["\'][^>]+content=["\']([^"\']+)["\']/i',$html,$m)) return resolveUrl($m[1],$base,$pageUrl);

if(preg_match_all('/<img[^>]+>/i',$html,$imgs)){
$bestUrl='';$bestScore=0;
foreach($imgs[0] as $img){
$src='';$class='';$id='';$w=0;$h=0;$alt='';
if(preg_match('/src=["\']([^"\']+)["\']/i',$img,$sm))$src=$sm[1];
if(preg_match('/class=["\']([^"\']+)["\']/i',$img,$cm))$class=$cm[1];
if(preg_match('/id=["\']([^"\']+)["\']/i',$img,$im))$id=$im[1];
if(preg_match('/width=["\'](\d+)["\']/i',$img,$wm))$w=(int)$wm[1];
if(preg_match('/height=["\'](\d+)["\']/i',$img,$hm))$h=(int)$hm[1];
if(preg_match('/alt=["\']([^"\']+)["\']/i',$img,$am))$alt=$am[1];
if(!$src||preg_match('/^(data:|javascript:|#)/i',$src))continue;

$score=($w>200&&$h>200?10:0)+($w*$h>50000?5:0);

$kw='product|main|big|large|gallery|featured|hero|primary|item|detail';
if(preg_match('/'.$kw.'/i',$class.$id))$score+=8;
if(preg_match('/'.$kw.'/i',$alt))$score+=3;

if(preg_match('/logo|icon|badge|thumb|avatar|sprite|social|banner|slider/i',$class.$id))$score-=10;
if($score>$bestScore){$bestScore=$score;$bestUrl=$src;}
}
if($bestUrl&&$bestScore>=3)return resolveUrl($bestUrl,$base,$pageUrl);
}

if(preg_match('/<img[^>]+src=["\']([^"\']+)["\'][^>]*>/i',$html,$m)){
$u=$m[1];if(!preg_match('/^(data:|javascript:|#|[\w]+-icon)/i',$u)&&strlen($u)>10)return resolveUrl($u,$base,$pageUrl);
}
return '';
}

function resolveUrl(string $url, string $base, string $pageUrl): string {
if(preg_match('/^https?:\/\//i',$url))return $url;
if(strpos($url,'//')===0)return 'https:'.$url;
if(strpos($url,'/')===0)return $base.$url;
return rtrim($pageUrl,'/').'/'.ltrim($url,'/');
}

/* =====================================================================
 *  بررسی نسخه — فقط خواندنی
 *  ---------------------------------------------------------------
 *  این بخش عمداً هیچ کدی دانلود نمی‌کند و هیچ فایل PHP ای نمی‌نویسد.
 *  فقط شناسهٔ نسخهٔ گیت‌هاب را با فایل فعلی مقایسه می‌کند و نتیجه را
 *  گزارش می‌دهد. کار نصب بر عهدهٔ deploy.php است که فایلی جداگانه است
 *  و روی هدف دیگری می‌نویسد — نه روی خودش و نه روی این فایل از داخل
 *  همین اسکریپت. این جداسازی باعث می‌شود الگوی «دانلود ← بازنویسی خود
 *  ← اجرا» که اسکنرهای امنیتی هاست آن را بک‌دور می‌شناسند شکل نگیرد.
 * ===================================================================== */

const VC_FILE = __DIR__ . '/.versioncheck.json';

function vc_defaults(): array {
    return [
        'check_on_load' => false,
        'repo'          => 'fazilatma/code',
        'branch'        => 'main',
        // v8.68: نام فایل در مخزن. اگر فایل را با نام دیگری نصب کرده‌اید،
        // خودِ همان نام مبنا قرار می‌گیرد تا به‌روزرسانی دنبال فایل اشتباه نگردد.
        'path'          => basename(__FILE__),
        'github_token'  => '',
        'deploy_file'   => 'deploy.php',
        'deploy_token'  => '',
        'last_check'    => 0,
    ];
}

function vc_load(): array {
    $d = vc_defaults();
    if (!is_file(VC_FILE)) return $d;
    $j = json_decode((string)@file_get_contents(VC_FILE), true);
    if (!is_array($j)) return $d;
    $c = array_merge($d, $j);
    // v8.70: مسیر ذخیره‌شده از قبلِ تغییرِ نام فایل، مسیر اشتباه است.
    // بدون این، به‌روزرسانی برای همیشه فایل قدیمی مخزن را می‌سنجید و
    // «به‌روز هستید» می‌گفت، در حالی که نسخهٔ تازه هرگز نصب نمی‌شد.
    $saved = trim((string)($c['path'] ?? ''));
    $self  = basename(__FILE__);
    if ($saved === '' || ($saved !== $self && basename($saved) !== $self
        && preg_match('~^scraper[-_v0-9.]*\.php$~i', basename($saved)))) {
        $c['path'] = $self;
    }
    return $c;
}

function vc_save(array $c): bool {
    $ok = @file_put_contents(VC_FILE, json_encode($c, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), LOCK_EX) !== false;
    if ($ok) @chmod(VC_FILE, 0600);
    return $ok;
}

/** شناسهٔ محتوا با همان الگوریتم گیت، برای مقایسه با پاسخ API */
function vc_content_id(string $data): string {
    return sha1('blob ' . strlen($data) . "\0" . $data);
}

/** پیام خطای گویا برای کدهای رایج گیت‌هاب */
function vc_http_error(int $code, string $fallback, bool $hadToken): string {
    if ($code === 401) {
        return 'توکن گیت‌هاب نامعتبر یا منقضی است (۴۰۱) — چون ریپو عمومی است، توکن را حذف کنید';
    }
    if ($code === 403) {
        return $hadToken
            ? 'دسترسی رد شد (۴۰۳) — توکن مجوز لازم را ندارد'
            : 'محدودیت نرخ گیت‌هاب (۴۰۳) — ساعتی ۶۰ درخواست برای هر IP؛ کمی بعد دوباره تلاش کنید';
    }
    if ($code === 404) return 'فایل، برنچ یا ریپو پیدا نشد (۴۰۴)';
    return $fallback ?: ('خطا HTTP ' . $code);
}

/**
 * درخواست GET فقط برای خواندن اطلاعات (متادیتا)، نه کد.
 * اگر توکن نامعتبر باشد و ریپو عمومی، یک‌بار بدون توکن دوباره تلاش می‌کند
 * تا یک توکن خراب کل قابلیت را از کار نیندازد.
 */
function vc_get_json_auto(string $url, string $token = '', int $timeout = 25): array {
    $r = vc_get_json($url, $token, $timeout);
    if (!$r['ok'] && $r['code'] === 401 && $token !== '') {
        $retry = vc_get_json($url, '', $timeout);
        if ($retry['ok']) {
            $retry['token_rejected'] = true;   // به UI بگو توکن بد است
            return $retry;
        }
    }
    $r['token_rejected'] = false;
    return $r;
}

/** درخواست GET فقط برای خواندن اطلاعات (متادیتا)، نه کد */
function vc_get_json(string $url, string $token = '', int $timeout = 25): array {
    $hdr = [
        'User-Agent: scraper-version-check',
        'Accept: application/vnd.github+json',
        'Cache-Control: no-cache',
    ];
    if ($token !== '') $hdr[] = 'Authorization: Bearer ' . $token;

    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 5,
            CURLOPT_CONNECTTIMEOUT => 12, CURLOPT_TIMEOUT => $timeout, CURLOPT_ENCODING => '',
            CURLOPT_HTTPHEADER => $hdr,
        ]);
        $b = curl_exec($ch);
        $e = curl_error($ch);
        $c = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        curl_close($ch);
        if ($b === false) return ['ok' => false, 'code' => 0, 'error' => $e ?: 'ارتباط ناموفق', 'data' => null];
        if ($c !== 200)   return ['ok' => false, 'code' => $c, 'error' => 'HTTP ' . $c, 'data' => null];
        $d = json_decode((string)$b, true);
        return is_array($d) ? ['ok' => true, 'code' => 200, 'error' => '', 'data' => $d]
                            : ['ok' => false, 'code' => 200, 'error' => 'پاسخ نامعتبر', 'data' => null];
    }

    $ctx = stream_context_create([
        'http' => ['method' => 'GET', 'timeout' => $timeout, 'header' => implode("\r\n", $hdr), 'ignore_errors' => true],
        'ssl'  => ['verify_peer' => true, 'verify_peer_name' => true],
    ]);
    $b = @file_get_contents($url, false, $ctx);
    if ($b === false) return ['ok' => false, 'code' => 0, 'error' => 'ارتباط ناموفق', 'data' => null];
    $d = json_decode((string)$b, true);
    return is_array($d) ? ['ok' => true, 'code' => 200, 'error' => '', 'data' => $d]
                        : ['ok' => false, 'code' => 0, 'error' => 'پاسخ نامعتبر', 'data' => null];
}

/** Store Online Chat Human Support Desk API */
if (isset($_GET['store_chat_api']) || isset($_POST['store_chat_api'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $api_action = $_GET['store_chat_api'] ?: ($_POST['store_chat_api'] ?? 'get_threads');
    $threads_file = __DIR__ . '/chat_threads.json';

    // Auto-bootstrap WordPress if available
    if (!function_exists('get_option')) {
        $wp_loader_candidates = [
            __DIR__ . '/wp-load.php',
            dirname(__DIR__) . '/wp-load.php',
            dirname(dirname(__DIR__)) . '/wp-load.php',
            dirname(dirname(dirname(__DIR__))) . '/wp-load.php',
        ];
        foreach ($wp_loader_candidates as $loader) {
            if (file_exists($loader)) {
                @require_once $loader;
                break;
            }
        }
    }

    $threads = [];
    if (function_exists('get_option')) {
        $threads = get_option('scraper_chat_threads', []);
    }
    if (empty($threads) && file_exists($threads_file)) {
        $threads = @json_decode(file_get_contents($threads_file), true) ?: [];
    }
    if (!is_array($threads)) $threads = [];

    if ($api_action === 'get_threads') {
        $unread_total = 0;
        foreach ($threads as $t) {
            if (!empty($t['unread_admin'])) $unread_total++;
        }
        echo json_encode(['ok' => true, 'threads' => $threads, 'unread_total' => $unread_total], JSON_UNESCAPED_UNICODE);
        exit;
    }

    if ($api_action === 'send_reply') {
        $thread_id = trim((string)($_POST['thread_id'] ?? ''));
        $reply_text = trim((string)($_POST['reply_text'] ?? ''));
        if ($thread_id === '' || $reply_text === '') {
            echo json_encode(['ok' => false, 'error' => 'متن پاسخ یا شناسه گفتگو خالی است.'], JSON_UNESCAPED_UNICODE);
            exit;
        }

        $now = time();
        $time_str = date('H:i');
        $found = false;
        $updated_thread = null;

        foreach ($threads as &$t) {
            if (($t['id'] ?? '') === $thread_id) {
                $t['unread_admin'] = false;
                $t['status'] = 'replied';
                $t['updated_at'] = $now;
                $admin_msg = [
                    'id' => 'msg_' . $now . '_' . rand(100, 999),
                    'sender' => 'admin',
                    'sender_name' => 'ادمین فروشگاه (پاسخ انسانی از اسکریپر)',
                    'text' => $reply_text,
                    'time' => $time_str,
                    'timestamp' => $now,
                ];
                if (!isset($t['messages']) || !is_array($t['messages'])) {
                    $t['messages'] = [];
                }
                $t['messages'][] = $admin_msg;
                $found = true;
                $updated_thread = $t;
                break;
            }
        }
        unset($t);

        if (!$found) {
            echo json_encode(['ok' => false, 'error' => 'گفتگوی مورد نظر یافت نشد.'], JSON_UNESCAPED_UNICODE);
            exit;
        }

        // Save to JSON file and WP DB
        @file_put_contents($threads_file, json_encode($threads, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE), LOCK_EX);
        if (function_exists('update_option')) {
            update_option('scraper_chat_threads', $threads, false);
        }

        // Dispatch to Messengers (Bale, Telegram, Rubika)
        $conn = [];
        if (function_exists('loadConnections')) {
            $conn = loadConnections();
        } elseif (file_exists(__DIR__ . '/connections.json')) {
            $conn = @json_decode(file_get_contents(__DIR__ . '/connections.json'), true) ?: [];
        }

        $c_name = $updated_thread['name'] ?? 'مشتری فروشگاه';
        $c_phone = $updated_thread['phone'] ?? '';
        $dispatch_msg = "🧑‍💼 پاسخ انسانی ادمین به مشتری (ثبت شده از اسکریپر):\n👤 مشتری: {$c_name}" . ($c_phone ? " ({$c_phone})" : '') . "\n💬 پاسخ: {$reply_text}\n⏰ زمان: {$time_str}";

        // Telegram
        $tg_bot = $conn['telegram_bot_token'] ?? ($conn['telegram_token'] ?? '');
        $tg_chat = $conn['telegram_chat_id'] ?? '';
        if ($tg_bot && $tg_chat) {
            @file_get_contents('https://api.telegram.org/bot' . urlencode($tg_bot) . '/sendMessage?chat_id=' . urlencode($tg_chat) . '&text=' . urlencode($dispatch_msg));
        }

        // Bale
        $bale_bot = $conn['bale_token'] ?? ($conn['bale_bot_token'] ?? '');
        $bale_chat = $conn['bale_chat_id'] ?? '';
        if ($bale_bot && $bale_chat) {
            @file_get_contents('https://tapi.bale.ai/bot' . urlencode($bale_bot) . '/sendMessage?chat_id=' . urlencode($bale_chat) . '&text=' . urlencode($dispatch_msg));
        }

        echo json_encode(['ok' => true, 'thread' => $updated_thread, 'msg' => 'پاسخ با موفقیت به مشتری و پیام‌رسان‌ها ارسال شد.'], JSON_UNESCAPED_UNICODE);
        exit;
    }
}

/** مقایسهٔ نسخه — هیچ چیزی دانلود یا نوشته نمی‌شود */
if (isset($_GET['vc_check'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = vc_load();

    if (empty($_GET['force']) && empty($c['check_on_load'])) {
        echo json_encode(['ok' => true, 'skipped' => true, 'update' => false]);
        exit;
    }
    if (trim((string)$c['repo']) === '' || trim((string)$c['path']) === '') {
        echo json_encode(['ok' => false, 'error' => 'ریپو یا مسیر فایل تنظیم نشده'], JSON_UNESCAPED_UNICODE);
        exit;
    }

    $local = vc_content_id((string)@file_get_contents(__FILE__));
    $api = 'https://api.github.com/repos/' . $c['repo'] . '/contents/'
         . implode('/', array_map('rawurlencode', explode('/', $c['path'])))
         . '?ref=' . rawurlencode($c['branch']);
    $r = vc_get_json_auto($api, $c['github_token']);
    if (!$r['ok'] || !isset($r['data']['sha'])) {
        echo json_encode([
            'ok' => false,
            'error' => vc_http_error((int)$r['code'], (string)$r['error'], $c['github_token'] !== ''),
            'code' => (int)$r['code'],
            'bad_token' => (int)$r['code'] === 401,
        ], JSON_UNESCAPED_UNICODE);
        exit;
    }
    // توکن بد بود ولی بدون آن کار کرد — خودکار پاکش کن تا دفعهٔ بعد خطا ندهد
    if (!empty($r['token_rejected'])) {
        $c['github_token'] = '';
        vc_save($c);
    }

    $c['last_check'] = time();
    vc_save($c);

    $remote = (string)$r['data']['sha'];
    echo json_encode([
        'ok'          => true,
        'update'      => $remote !== $local,
        'local_id'    => substr($local, 0, 8),
        'remote_id'   => substr($remote, 0, 8),
        'remote_size' => (int)($r['data']['size'] ?? 0),
        'local_size'  => (int)@filesize(__FILE__),
        'branch'      => $c['branch'],
        'path'        => $c['path'],
        'deploy_ready'=> $c['deploy_token'] !== '' && is_file(__DIR__ . '/' . basename($c['deploy_file'])),
        'deploy_file' => basename($c['deploy_file']),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

/** فهرست برنچ‌ها — فقط خواندنی */
if (isset($_GET['vc_branches'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = vc_load();
    $repo = trim((string)($_GET['repo'] ?? $c['repo']));
    if (!preg_match('~^[\w.-]+/[\w.-]+$~', $repo)) {
        echo json_encode(['ok' => false, 'error' => 'نام ریپو نامعتبر است (قالب: user/repo)'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $r = vc_get_json_auto('https://api.github.com/repos/' . $repo . '/branches?per_page=100', $c['github_token']);
    if (!$r['ok']) {
        echo json_encode([
            'ok' => false,
            'error' => vc_http_error((int)$r['code'], (string)$r['error'], $c['github_token'] !== ''),
            'code' => (int)$r['code'],
            'bad_token' => (int)$r['code'] === 401,
        ], JSON_UNESCAPED_UNICODE);
        exit;
    }
    if (!empty($r['token_rejected'])) { $c['github_token'] = ''; vc_save($c); }
    $out = [];
    foreach ($r['data'] as $b) {
        if (!empty($b['name'])) $out[] = ['name' => $b['name'], 'sha' => substr((string)($b['commit']['sha'] ?? ''), 0, 7)];
    }
    echo json_encode(['ok' => true, 'branches' => $out], JSON_UNESCAPED_UNICODE);
    exit;
}

/** فهرست فایل‌های PHP یک برنچ — فقط خواندنی */
if (isset($_GET['vc_files'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = vc_load();
    $repo   = trim((string)($_GET['repo'] ?? $c['repo']));
    $branch = trim((string)($_GET['branch'] ?? $c['branch']));
    if (!preg_match('~^[\w.-]+/[\w.-]+$~', $repo) || $branch === '') {
        echo json_encode(['ok' => false, 'error' => 'ریپو و برنچ لازم است'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $r = vc_get_json_auto('https://api.github.com/repos/' . $repo . '/git/trees/' . rawurlencode($branch) . '?recursive=1', $c['github_token'], 30);
    if (!$r['ok'] || !isset($r['data']['tree'])) {
        echo json_encode([
            'ok' => false,
            'error' => vc_http_error((int)$r['code'], (string)$r['error'], $c['github_token'] !== ''),
            'code' => (int)$r['code'],
            'bad_token' => (int)$r['code'] === 401,
        ], JSON_UNESCAPED_UNICODE);
        exit;
    }
    if (!empty($r['token_rejected'])) { $c['github_token'] = ''; vc_save($c); }
    $files = [];
    foreach ($r['data']['tree'] as $n) {
        if (($n['type'] ?? '') !== 'blob') continue;
        $p = (string)$n['path'];
        if (!preg_match('~\.php\d?$~i', $p)) continue;
        $files[] = ['path' => $p, 'size' => (int)($n['size'] ?? 0)];
    }
    usort($files, fn($a, $b) => $b['size'] <=> $a['size']);
    echo json_encode(['ok' => true, 'files' => $files], JSON_UNESCAPED_UNICODE);
    exit;
}

/** تنظیمات بررسی نسخه */
if (isset($_GET['vc_settings'])) {
