}
if (!$title && !$link) continue;
/* v8.78: کلید محصول درون‌ریزی‌شده حالا با همان فرمول محصولات اسکرپ‌شده
   ساخته می‌شود. قبلاً md5('import:'.عنوان.'|'.قیمت.'|'.شمارهٔ ردیف) بود که
   سه ایراد داشت: با عوض شدن قیمت یا جابه‌جا شدن ردیف، کلید عوض می‌شد و
   همان محصول دوباره اضافه می‌شد؛ محصولی که هم اسکرپ و هم درون‌ریزی شده
   بود دو کلید متفاوت می‌گرفت و دو بار ارسال می‌شد؛ و دفتر remote_map هم
   نمی‌توانست آن را به محصول مقصد وصل کند. حالا اگر لینک باشد کلید از
   روی لینک ساخته می‌شود، دقیقاً مثل مسیر اسکرپ. */
$key = productKey(['link' => $link, 'title' => $title, 'price' => $price]);
$products[] = [
'key' => $key,
'title' => $title,
'price' => $price,
'image' => $image,
'link' => $link,
'sku' => $sku,
'shortDesc' => $shortDesc,
'longDesc' => $longDesc
];
$count++;
}
echo json_encode(['ok'=>true,'count'=>$count,'products'=>$products], JSON_UNESCAPED_UNICODE); exit;
}

function autoDetectColumns(array $headers): array {
$mapping = [];
$patterns = [
'title' => ['title','عنوان','name','نام','product','محصول','کالا'],
'price' => ['price','قیمت','regular_price','amount','مبلغ','final','نهایی'],
'image' => ['image','تصویر','عکس','img','photo','تصویر_محصول','picture'],
'link' => ['url','لینک','link','href','آدرس','سایت','منبع','source'],
'sku' => ['sku','کد','code','بارکد','barcode','sku_product'],
'shortDesc' => ['short_description','توضیحات_کوتاه','short_desc','خلاصه','brief'],
'longDesc' => ['description','توضیحات','long_desc','توضیحات_بلند','detail','جزئیات'],
];
foreach ($patterns as $field => $keywords) {
foreach ($headers as $i => $h) {
$hl = mb_strtolower(trim($h), 'UTF-8');
foreach ($keywords as $kw) {
if ($hl === $kw || strpos($hl, $kw) !== false) {
$mapping[$field] = $i;
break 2;
}
}
}
}
return $mapping;
}

if(isset($_GET['extract_queue_status'])){
header('Content-Type: application/json; charset=UTF-8');
$queue=extractReadQueue();
$progress=readProgress(EXTRACT_PROGRESS_FILE);
// v8.20: اگر پردازش قطع شده باشد (مثلاً timeout سرور)، ردیف نباید برای
// همیشه «در حال اجرا» بماند؛ بعد از ۱۵ دقیقه بی‌پاسخی «خطا» علامت می‌خورد.
/* v8.91: معیار عوض شد — «سنِ ردیف» به «مدت بی‌حرکتی».
   قاعدهٔ قبلی سن ردیف را می‌سنجید، یعنی اجرای سالمی که ۲۰ دقیقه طول
   می‌کشید (گالری روشن = باز کردن صفحهٔ همهٔ محصولات) وسط کار «خطا»
   می‌خورد. برعکسش هم بد بود: ردیفی که در ثانیهٔ اول مرده بود، ۱۵ دقیقه
   «در حال استخراج» می‌ماند و چون محافظ تکراری‌نبودن آن را می‌دید، اجرای
   بعدی هم راه نمی‌افتاد.
   حالا معیار این است که آخرین بار کِی چیزی نوشته شده. اجرای زنده هر دو
   محصول یک بار می‌نویسد، پس بی‌حرکتیِ طولانی یعنی واقعاً مرده. */
$dirty=false;
$now=time();
$exIdleMax=max(120,(int)(loadConnections()['stall_after']??300));
foreach($queue['entries'] as &$qe){
    if(($qe['status']??'')!=='running')continue;
    /* پردازه‌ای که مرده، خودش running=true را در فایل پیشرفت جا گذاشته —
       دقیقاً چون فرصت نکرده done بنویسد. پس «زنده بودن» را نمی‌شود از
       همان فایل پرسید؛ تنها شاهد قابل اعتماد، زمان آخرین نوشتن است. */
    /* v10.32 (۴۵ج): شاهدِ دوم — قفلِ سراسری. اگر فایلِ پیشرفت به هر دلیلی
       مالِ این ردیف نبود (اجرای هم‌زمانِ دیگری بازنویسی‌اش کرده، یا نسخهٔ
       قدیمیِ کد queue_id را ننوشته)، هنوز نمی‌شود گفت «مرده». قفل نامِ
       صاحبِ واقعیِ اجرا را نگه می‌دارد؛ اگر قفل دستِ همین ردیف است و تازه
       ضربان زده، این کار زنده است و نباید «خطا» بخورد.
       v10.36 (۴۹الف): حالا شاهدِ سومی هم هست — «حرکتِ شمارنده‌ها». همان
       چیزی که کاربر با چشم می‌دید و برنامه نمی‌دید. */
    $_lkBeat=0;
    $_lk=@json_decode((string)@file_get_contents(EXTRACT_LOCK_FILE),true);
    if(is_array($_lk)&&((string)($_lk['queue_id']??''))===((string)($qe['id']??'')))
        $_lkBeat=(int)($_lk['at']??0);
    $_iw=queueRowIdle('extract',$qe,$progress,$now,['lock'=>$_lkBeat]);
    $idle=(int)$_iw['idle'];
    if($idle>$exIdleMax){
        $qe['status']='failed';
        $_rpQ = max(1, (int)($qe['resume_page'] ?? $qe['current'] ?? $progress['page'] ?? 1));
        if ($_rpQ > 1) $_rpQ = max(1, $_rpQ - 1);
        $qe['error']='نیمه‌کاره رها شد ('.$idle.'ث) — ادامه از صفحه '.$_rpQ;
        $qe['resumable']=true;
        $qe['resume_page']=$_rpQ;
        $qe['done_at']=$now;
        $dirty=true;
        $_pkQ=(string)($qe['profile_key']??'');
        if($_pkQ!==''){
            try{
                $_psQ=loadProfiles();
                if(isset($_psQ[$_pkQ])&&is_array($_psQ[$_pkQ])){
                    $_psQ[$_pkQ]['_extract_list_incomplete']=true;
                    $_psQ[$_pkQ]['_extract_resume_from']=$_rpQ;
                    $_psQ[$_pkQ]['_extract_list_page_try']=(int)($qe['current']??$_rpQ+1);
                    $_psQ[$_pkQ]['_extract_list_page_ok']=max(0,$_rpQ);
                    $_psQ[$_pkQ]['_extract_stage_at']=time();
                    saveProfiles($_psQ);
                }
            }catch(Throwable $e){}
        }
    }
}
unset($qe);
if($dirty)extractWriteQueue($queue);
echo json_encode(['ok'=>true,'entries'=>$queue['entries'],'progress'=>$progress],JSON_UNESCAPED_UNICODE);
exit;
}

/* v8.25: گزارش تفصیلی یک اجرای تمام‌شده */
if(isset($_GET['extract_report'])){
header('Content-Type: application/json; charset=UTF-8');
$qid=trim($_GET['queue_id']??'');
if($qid===''){echo json_encode(['ok'=>false,'error'=>'شناسه نامعتبر']);exit;}
$rep=extractLoadReport($qid);
if($rep===null){
// اجرای در حال انجام هنوز گزارش نهایی ندارد؛ از progress زنده بخوان
$p=readProgress(EXTRACT_PROGRESS_FILE);
if(($p['queue_id']??'')===$qid){
$rep=['new_items'=>$p['new_items']??[],'changed_items'=>$p['changed_items']??[],
'removed_items'=>$p['removed_items']??[],'unchanged'=>$p['unchanged']??0,
'price_up'=>$p['price_up']??0,'price_down'=>$p['price_down']??0,
'extracted'=>$p['extracted']??0,'live'=>true];
}
}
if($rep===null){echo json_encode(['ok'=>false,'error'=>'گزارشی برای این اجرا ذخیره نشده']);exit;}
echo json_encode(['ok'=>true,'report'=>$rep],JSON_UNESCAPED_UNICODE);exit;
}

/* حذف یک ردیف از صف استخراج — همتای bsl_queue_delete */
if(isset($_GET['extract_queue_delete'])){
header('Content-Type: application/json; charset=UTF-8');
