]);

foreach($queue['entries'] as &$qe){if($qe['id']===$queueId){$qe['status']='done';$qe['products_count']=count($allProducts);$qe['total']=count($allProducts);$qe['current']=count($allProducts);$qe['done_at']=time();$qe['new']=$newCount;$qe['price_changed']=$priceChanged;$qe['removed']=$removedCount;$qe['unchanged']=$unchanged;$qe['price_up']=$priceUp;$qe['price_down']=$priceDown;$qe['gallery_images']=$galleryImgsTotal;$qe['gallery_products']=$galleryFound;$qe['detail_ok']=$detailOk;$qe['detail_fail']=$detailFail;$qe['detail_fields']=$detailFields;$qe['variation_products']=$varFound;$qe['detail_total']=$detailTotal;$qe['detail_skip_why']=$_skipWhy;$qe['detail_no_link']=$_noLink;$qe['detail_already']=$_alreadyDone;$qe['gallery_blank']=($galleryCfg['enabled']&&$detailOk>0&&$galleryImgsTotal===0)?1:0;$qe['gallery_box']=(string)$galleryCfg['box'];$qe['has_report']=true;break;}}unset($qe);
extractWriteQueue($queue);

// v10.21 (۳۴الف): سینکِ «بدون استخراج» باید بداند چند صفحه واقعاً باز شد و
// آیا بودجهٔ زمانی تمام شد (تا در نوبتِ بعدی از همان‌جا ادامه دهد)
extractLockRelease($queueId);   // v10.32 (۴۵ب)
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>true,'extracted'=>count($allProducts),'new'=>$newCount,'price_changed'=>$priceChanged,'removed'=>$removedCount,'unchanged'=>$unchanged,'price_up'=>$priceUp,'price_down'=>$priceDown,'new_items'=>$newItems,'changed_items'=>$changedItems,'removed_items'=>$removedItems,'products_saved'=>true,'profile_key'=>$profileKey??profileKey($url),'detail_done'=>$detailDone,'detail_total'=>$detailTotal,'detail_ok'=>$detailOk,'detail_fail'=>$detailFail,'ran_out'=>!empty($_ranOut),'resume_needed'=>!empty($_ranOut),'extract_stage'=>(!empty($_ranOut)?'detail':(($phase==='list')?'list_done':'complete')),'stock_out'=>$_stockOut??0,'stock_back'=>$_stockBack??0];
}

if(isset($_GET['action']) && $_GET['action'] === 'backend_extract'){
$profileKey=trim($_GET['profile_key']??$_POST['profile_key']??'');
if($profileKey===''){
$u=trim($_GET['url']??'');
if($u!==''&&filter_var($u,FILTER_VALIDATE_URL))$profileKey=profileKey($u);
}
/* v9.01: همان اندپوینت می‌تواند فقط فهرست یا فقط جزئیات را اجرا کند.
   ?phase=list | detail | all — پیش‌فرض all، پس رفتار دکمهٔ دستی عوض نمی‌شود. */
$phaseIn = (string)($_GET['phase'] ?? $_POST['phase'] ?? 'all');
if (!in_array($phaseIn, ['all','list','detail'], true)) $phaseIn = 'all';
$resumeLockQueueId = '';
/* v10.136: resumeِ فرزند باید خودش، در همان process که worker را می‌سازد،
   lock بگیرد؛ parent فقط دیگر probe و mutation جداگانه انجام نمی‌دهد. */
if (!empty($_GET['resume']) || !empty($_POST['resume'])) {
    $resumePrep = extractResumePrepare($profileKey, loadConnections());
    if (empty($resumePrep['ok'])) {
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok' => false, 'locked' => ($resumePrep['reason'] ?? '') === 'lock_held',
            'error' => 'checkpoint استخراج قابل رزرو نیست — اجرای موازی ساخته نشد'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $phaseIn = (string)$resumePrep['phase'];
    $resumeLockQueueId = (string)($resumePrep['queue_id'] ?? '');
}
/* v9.11: دامنهٔ «همهٔ محصولات» از دکمهٔ اجرای فوریِ استخراج دوره‌ای */
$forceAllIn = !empty($_GET['force_all']) || !empty($_POST['force_all']);
$res=runBackendExtract($profileKey,'manual',true,$phaseIn,$forceAllIn,$resumeLockQueueId);
// v8.30: همان اعلان‌های تغییر مبدأ که کران‌جاب می‌فرستد
if(!empty($res['ok'])){
$cnNow=loadConnections();
$profsNow=loadProfiles();
notifSourceChanges($cnNow,$res,$profsNow[$profileKey]['name']??$profileKey);
}
// اگر پاسخ زودهنگام ارسال شده، دیگر چیزی چاپ نمی‌کنیم
if(empty($res['__early_sent'])){
header('Content-Type: application/json; charset=UTF-8');
echo json_encode($res,JSON_UNESCAPED_UNICODE);
}
exit;
}

if (isset($_GET['sync_status'])) {
header('Content-Type: application/json; charset=UTF-8');
echo json_encode(['ok' => true, 'state' => loadSyncState()], JSON_UNESCAPED_UNICODE);
exit;
}
if (($_POST['action'] ?? '') === 'update_sync_state') {
header('Content-Type: application/json; charset=UTF-8');
$key = trim($_POST['profile_key'] ?? '');
$status = $_POST['status'] ?? 'done';
$state = loadSyncState();
$state[$key] = ['lastRun' => time(), 'status' => $status];
saveSyncState($state);
echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE); exit;
}

/* =====================================================================
 *  v8.39: ارسال فقط تغییرات («افزودن/آپدیت»)
 *
 *  تیک‌های «افزودن/آپدیت ووکامرس» و «افزودن/آپدیت باسلام» از نسخهٔ ۷
 *  در رابط کاربری بودند و ذخیره هم می‌شدند، ولی هیچ‌جای سمت سرور
 *  خوانده نمی‌شدند. نتیجه این بود که هر اجرای کران کل محصولات را
 *  دوباره می‌فرستاد و برای پروفایل چندهزارتایی ساعت‌ها طول می‌کشید.
 *
 *  حالا اگر تیک فعال باشد فقط محصولات جدید و تغییرکرده فرستاده
 *  می‌شوند. حذف‌شده‌ها مسیر جداگانهٔ خودشان را دارند (retireRemoved).
 * ===================================================================== */

/* =====================================================================
 *  v8.44: آماده‌سازی محصول برای ارسال، سمت سرور
 *
 *  تا اینجا فقط مرورگر قیمت نهایی را می‌ساخت (getSendP در جاوااسکریپت).
 *  کران محصول خام را در صف می‌گذاشت و ارسال‌کننده دنبال final_price
 *  می‌گشت که وجود نداشت، پس قیمت صفر می‌شد. حالا همان منطق اینجا هم
 *  پیاده شده تا اجرای خودکار و دستی یک نتیجه بدهند.
 * ===================================================================== */

/** قیمت نهایی با ضریب/درصد و گِرد کردن پروفایل — معادل getFinalPriceNum */
function profileFinalPrice(array $profile, $rawPrice): int {
    $base = extractPriceNum($rawPrice);
    if ($base <= 0) return 0;
    $mode = (string)($profile['priceMode'] ?? 'none');
    $val  = (float)($profile['priceVal'] ?? 0);
    $final = $base;
    if ($mode === 'percent')         $final = $base * (1 + ($val / 100));
    elseif ($mode === 'multiplier')  $final = $base * $val;
    $final = (int)round($final);
    $round = (int)($profile['roundPrice'] ?? 0);
    if ($round > 0) $final = (int)(round($final / $round) * $round);
    return $final;
}

/**
 * v8.87: تعدیل قیمت مخصوص یک مقصد، روی قیمت نهاییِ پروفایل.
 *
 * تا حالا فقط یک تنظیم قیمت وجود داشت که برای هر دو مقصد یکی بود. ولی
 * حاشیهٔ سود ووکامرس و باسلام یکی نیست (کارمزد باسلام، هزینهٔ ارسال و …)
 * و کاربر می‌خواهد برای هر مقصد درصد جداگانه بگذارد.
 *
 * این تابع روی «قیمت نهاییِ» محاسبه‌شده اعمال می‌شود، نه روی قیمت خام،
 * تا تنظیم پروفایل هم سر جایش بماند و این یکی فقط تفاوت مقصد را بگذارد.
 *
 * $cfg: ['mode'=>'none|percent|multiplier', 'val'=>float, 'round'=>int]
 */
function destAdjustPrice(int $base, array $cfg): int {
    if ($base <= 0) return 0;
    $mode = (string)($cfg['mode'] ?? 'none');
    $val  = (float)($cfg['val'] ?? 0);
    $out  = $base;
    if ($mode === 'percent')        $out = $base * (1 + ($val / 100));
    elseif ($mode === 'multiplier') $out = $val > 0 ? $base * $val : $base;
    $out = (int)round($out);
    $round = (int)($cfg['round'] ?? 0);
    if ($round > 0) $out = (int)(round($out / $round) * $round);
    // قیمت هیچ‌وقت نباید منفی یا صفر شود؛ درصدِ منفیِ بزرگ نباید محصول را خراب کند
    return $out > 0 ? $out : $base;
}

/** تنظیمات تعدیل قیمت یک مقصد را از فایل اتصالات می‌خواند */
function destPriceCfg(array $cn, string $dest): array {
    $d = $cn[$dest] ?? [];
    return [
        'mode'  => (string)($d['price_mode'] ?? 'none'),
        'val'   => (float)($d['price_val'] ?? 0),
        'round' => (int)($d['price_round'] ?? 0),
    ];
}

/* v10.23 (۳۶ه): شمارنده‌های تفکیکیِ هر غرفه برای صفِ ارسالِ باسلام.
   جدولِ سراسری اینجا مقداردهی می‌شود، نه داخلِ خودِ اندپوینتِ ارسال — چون
   دو تابعِ زیر از هر مسیری (از جمله selftest) صدا زده می‌شوند و اگر متغیرِ
   سراسری موجود نباشد PHP اخطارِ «undefined variable» می‌دهد. */
$GLOBALS['bslShopStats']      = $GLOBALS['bslShopStats']      ?? [];
$GLOBALS['bslDefaultVid']     = $GLOBALS['bslDefaultVid']     ?? 0;
$GLOBALS['bslDefaultShopName'] = $GLOBALS['bslDefaultShopName'] ?? '';

/** v10.23 (۳۶ه): آمارِ یک غرفهٔ اضافی را در جدولِ سراسری می‌نشاند/به‌روز می‌کند */
function bslShopStatBump(int $vid, string $name, string $field, int $n = 1): void {
    global $bslShopStats;
    if (!is_array($bslShopStats)) $bslShopStats = [];
    if ($vid <= 0) return;
    if (!isset($bslShopStats[$vid])) $bslShopStats[$vid] = ['name' => $name !== '' ? $name : ('غرفهٔ ' . $vid),
        'c' => 0, 'u' => 0, 's' => 0, 'f' => 0];
    if ($name !== '') $bslShopStats[$vid]['name'] = $name;
    if (isset($bslShopStats[$vid][$field])) $bslShopStats[$vid][$field] += $n;
}

/**
 * v10.23 (۳۶ه): جدولِ شمارنده‌ها به شکلِ آمادهٔ نمایش (غرفهٔ پیش‌فرض اول)
 *
 * v10.36 (۴۹ب): دو ایرادِ ریشه‌ای که باعث می‌شد کاربر بگوید «هنوز در
 * ارسال‌ها تفکیک بین چند غرفه دیده نمی‌شود»:
 *
 *  ۱) شمارنده‌های سراسری ($s,$u,$sk,$f) که به ردیفِ غرفهٔ پیش‌فرض نسبت
 *     داده می‌شدند، در مسیرِ چندغرفه‌ای «جمعِ همهٔ غرفه‌ها» بودند نه سهمِ
 *     غرفهٔ پیش‌فرض: حلقهٔ ارسالِ همزمان به‌ازای هر غرفه $updated++ می‌کرد.
 *     پس ردیفِ اول عددی بزرگ‌تر از کلِ محصولات نشان می‌داد و تفکیک
 *     بی‌معنی می‌شد.
 *  ۲) اگر فقط یک ردیف ساخته می‌شد، سمتِ جاوااسکریپت (rows.length<2) کلِ
 *     بلوک را پنهان می‌کرد — یعنی دقیقاً وقتی چیزی برای دیدن نبود.
 *
 * حالا اگر غرفهٔ پیش‌فرض هم آمارِ صریحِ خودش را ثبت کرده باشد (کلیدِ
 * bslShopStats با همان vendor_id)، همان مبنا قرار می‌گیرد و از جمعِ
 * سراسری استفاده نمی‌شود.
 */
function bslShopStatRows(int $s, int $u, int $sk, int $f): array {
    global $bslShopStats, $bslDefaultVid, $bslDefaultShopName;
    if (!is_array($bslShopStats)) $bslShopStats = [];
    $bslDefaultVid = (int)($bslDefaultVid ?? 0);
    $bslDefaultShopName = (string)($bslDefaultShopName ?? '');
    $rows = [];
    if ((int)$bslDefaultVid > 0) {
        $own = $bslShopStats[(int)$bslDefaultVid] ?? null;
        /* آمارِ اختصاصیِ غرفهٔ پیش‌فرض فقط وقتی معتبر است که واقعاً چیزی
           در آن ثبت شده باشد؛ ردیفِ صفرِ «جای‌نگه‌دار» نباید جمعِ واقعی را
           پنهان کند. */
        $hasOwn = is_array($own) && (((int)($own['c'] ?? 0)) || ((int)($own['u'] ?? 0))
                                  || ((int)($own['s'] ?? 0)) || ((int)($own['f'] ?? 0)));
        $rows[] = ['vid' => (int)$bslDefaultVid,
                   'name' => $bslDefaultShopName !== '' ? $bslDefaultShopName : 'غرفهٔ پیش‌فرض',
                   'is_default' => true,
                   'sent'    => $hasOwn ? (int)$own['c'] : (int)$s,
                   'updated' => $hasOwn ? (int)$own['u'] : (int)$u,
                   'skipped' => $hasOwn ? (int)$own['s'] : (int)$sk,
                   'failed'  => $hasOwn ? (int)$own['f'] : (int)$f];
    }
    foreach ((array)$bslShopStats as $vid => $row) {
        if ((int)$vid === (int)$bslDefaultVid) continue;
        $rows[] = ['vid' => (int)$vid,
                   'name' => (string)($row['name'] ?? ('غرفهٔ ' . $vid)),
                   'is_default' => false,
                   'sent' => (int)($row['c'] ?? 0), 'updated' => (int)($row['u'] ?? 0),
                   'skipped' => (int)($row['s'] ?? 0), 'failed' => (int)($row['f'] ?? 0)];
    }
    return $rows;
}

/* v9.47: فهرست غرفه‌های باسلام (پیش‌فرض + اضافی) برای دراپ‌داون «انتخاب غرفه».
   هر غرفه: ['vendor_id'=>int,'token'=>string,'shop_name'=>string]. */
function bslAllShops(array $cn): array {
    $out = [];
    $b = $cn['basalam'] ?? [];
    $defTok = trim((string)($b['token'] ?? ''));
    $defVid = (int)($b['vendor_id'] ?? 0);
    $defName = trim((string)($b['shop_name'] ?? ''));
    if ($defName === '') $defName = 'غرفهٔ پیش‌فرض';
    $defPM = (string)($b['price_mode'] ?? 'none');
    $defPV = (float)($b['price_val'] ?? 0);
    if ($defTok !== '' && $defVid > 0) {
        $out[] = ['vendor_id' => $defVid, 'token' => $defTok, 'shop_name' => $defName,
                  'is_default' => true, 'price_mode' => $defPM, 'price_val' => $defPV];
    }
    $vs = $b['vendors'] ?? [];
    if (is_array($vs)) {
        foreach ($vs as $v) {
            if (!is_array($v)) continue;
            $vid = (int)($v['vendor_id'] ?? 0);
            $tok = trim((string)($v['token'] ?? ''));
            if ($vid <= 0 || $tok === '') continue;
            $name = trim((string)($v['shop_name'] ?? ($v['name'] ?? '')));
            if ($name === '') $name = 'غرفهٔ ' . $vid;
            $out[] = ['vendor_id' => $vid, 'token' => $tok, 'shop_name' => $name,
                      'is_default' => false,
                      'price_mode' => (string)($v['price_mode'] ?? 'none'),
                      'price_val'  => (float)($v['price_val'] ?? 0)];
        }
    }
    return $out;
}

/** v10.73 (87): غرفه‌های فعال برایِ fan-outِ صف — فقط غرفه‌هایی که
    شناسهٔ سالم و توکنِ غیرخالی دارند (همان تعریفِ مسیرِ همزمان).
    توکن برنمی‌گردد (در صف ذخیره نمی‌شود)؛ وِرکر توکن را تازه از
    connections می‌خواند. خروجی: [vendor_id, shop_name, is_default] */
function bslFanoutShops(?array $cn): array {
    $cn = $cn ?: loadConnections();
    $out = [];
    foreach (bslAllShops($cn) as $sh) {
        $vid = (int)($sh['vendor_id'] ?? 0);
        $tok = trim((string)($sh['token'] ?? ''));
        if ($vid <= 0 || $tok === '') continue;
        $name = trim((string)($sh['shop_name'] ?? ''));
        $out[] = ['vendor_id' => $vid, 'shop_name' => $name, 'is_default' => !empty($sh['is_default'])];
    }
    return $out;
}

/* v9.68: تعدیل قیمتِ مخصوصِ هر غرفهٔ باسلام، «نسبت به غرفهٔ پیش‌فرض».
   غرفهٔ پیش‌فرض خودش می‌تواند درصد/مقدار داشته باشد (price_mode/price_val
   عمومی). برای غرفه‌های دیگر هم یک درصد/مقدارِ جدا ذخیره می‌شود که روی
   «قیمتِ پایهٔ محصول» اعمال می‌شود — مثل غرفهٔ پیش‌فرض ولی با مقادیرِ خودش.

   خروجی: ['price'=>قیمت نهاییِ این غرفه (تومان)، 'eff_pct'=>درصدِ مؤثرِ کلی نسبت به
   قیمتِ پایهٔ خام، 'profile_pct'=>درصدِ تعدیلِ خودِ پروفایل، 'shop_pct'=>درصدِ این غرفه]

   مثال: قیمت پایهٔ خام ۱۰۰؛ پروفایل +۳۰٪ (۱۳۰)؛ غرفهٔ دوم +۲۰٪ روی ۱۳۰ → ۱۵۶.
   eff_pct = (۱۵۶-۱۰۰)/۱۰۰ = +۵۶٪ یعنی نسبت به قیمت پایهٔ خام مجموعاً +۵۶٪. */
function bslShopPriceFor(int $basePrice, array $shop, int $round = 0): array {
    if ($basePrice <= 0) return ['price' => 0, 'pct' => 0, 'eff_pct' => 0, 'profile_pct' => 0, 'shop_pct' => 0];
    $mode = (string)($shop['price_mode'] ?? 'none');
    $val  = (float)($shop['price_val'] ?? 0);
    $out  = $basePrice;
    $pct  = 0.0;
    if ($mode === 'percent') {
        $out = $basePrice * (1 + ($val / 100));
        $pct = (float)$val;
    } elseif ($mode === 'multiplier') {
        $out = $val > 0 ? $basePrice * $val : $basePrice;
        $pct = $val > 0 ? round(($val - 1) * 100, 1) : 0;
    }
    $out = (int)round($out);
    if ($round > 0) $out = (int)(round($out / $round) * $round);
    if ($out <= 0) $out = $basePrice;
    return ['price' => $out, 'pct' => round($pct, 1), 'eff_pct' => 0, 'profile_pct' => 0, 'shop_pct' => round($pct, 1)];
}

/* v9.71: قیمتِ غرفه‌های غیرپیش‌فرض — «جمع ساده» (افزودنی) روی تعدیلِ خودِ پروفایل.

   خواستهٔ کاربر: تعدیلِ هر غرفهٔ غیرپیش‌فرض باید به‌صورت «کسر/اضافهٔ درصد یا
   مقدار» روی تعدیلِ خودِ پروفایل اضافه شود. یعنی اگر غرفهٔ پیش‌فرض (پروفایل)
   +۳۰٪ داشته باشد و غرفهٔ دوم +۵٪ بگذارد، افزایشِ نهایی برای آن پروفایل در
   غرفهٔ دوم = ۳۵٪ (جمعِ سادهٔ ۳۰ و ۵).

   برای هر دو «درصد» از جمعِ سادهٔ درصدها استفاده می‌شود؛ برای «ضریب» ابتدا به
   درصد تبدیل می‌شود و بعد جمع می‌شود.

   خروجی: ['price'=>قیمت نهاییِ تومان، 'eff_pct'=>درصدِ مؤثرِ کل نسبت به قیمتِ
   پایهٔ خام، 'profile_pct'=>درصدِ خودِ پروفایل، 'shop_pct'=>درصدِ این غرفه].
   مثال: پایهٔ خام ۱۰۰، پروفایل +۳۰٪، غرفهٔ دوم +۵٪ → eff=۳۵٪ → قیمت ۱۳۵. */
function bslShopPriceForProfile(array $profile, $rawPrice, array $shop, int $round = 0): array {
    $src = extractPriceNum($rawPrice);
    if ($src <= 0) return ['price' => 0, 'eff_pct' => 0, 'profile_pct' => 0, 'shop_pct' => 0];
    // درصدِ تعدیلِ خودِ پروفایل
    $pm = (string)($profile['priceMode'] ?? 'none');
    $pv = (float)($profile['priceVal'] ?? 0);
    if ($pm === 'percent')         $ppct = (float)$pv;
    elseif ($pm === 'multiplier')  $ppct = $pv > 0 ? ($pv - 1) * 100 : 0;
    else                           $ppct = 0;
    // درصدِ تعدیلِ این غرفه (روی همان مبنا)
    $sm = (string)($shop['price_mode'] ?? 'none');
    $sv = (float)($shop['price_val'] ?? 0);
    if ($sm === 'percent')         $spct = (float)$sv;
    elseif ($sm === 'multiplier')  $spct = $sv > 0 ? ($sv - 1) * 100 : 0;
    else                           $spct = 0;
    $eff = $ppct + $spct;                    // جمعِ ساده: ۳۰ + ۵ = ۳۵
    $out = $src * (1 + ($eff / 100));
    $out = (int)round($out);
    if ($round > 0) $out = (int)(round($out / $round) * $round);
    if ($out <= 0) $out = $src;
    return ['price' => $out, 'eff_pct' => round($eff, 1),
            'profile_pct' => round($ppct, 1), 'shop_pct' => round($spct, 1)];
}
/* v9.69: ارسالِ چند-غرفه‌ای — یک محصول را در «یک غرفهٔ مشخص» بساز یا به‌روز کن.
   برای هر غرفهٔ اضافی که قیمتِ خودش را دارد، همان منطقِ ارسالِ اصلی را اجرا
   می‌کنیم: جست‌وجو (bslFindExisting) → اگر بود PATCH (با قیمتِ خودِ آن غرفه)؛
   اگر نبود POST. این تابع خودش کامل است (بدون وابستگی به حلقهٔ اصلی) تا هر
   غرفه با token و قیمتِ خودش پردازش شود. */
/* v10.20 (۳۳الف): کلیدِ دفترچهٔ نگاشت، جدا برای هر غرفه.
   باگِ قدیمی: دفترچه (remote map) برای هر محصول فقط یک شناسه نگه می‌داشت و
   آن شناسه مالِ غرفهٔ پیش‌فرض بود. موقعِ ارسال به غرفهٔ دوم همان شناسه خوانده
   می‌شد و PATCH با توکنِ غرفهٔ دوم روی محصولِ غرفهٔ اول می‌رفت — که یا ۴۰۳
   می‌گرفت یا بی‌صدا شکست می‌خورد. حالا هر غرفهٔ غیرپیش‌فرض فضای نامِ خودش را
   دارد (کلید#vشناسهٔ‌غرفه) و شناسه‌ها با هم قاطی نمی‌شوند. */
function bslShopMapKey(string $productKey, array $shop): string {
    if ($productKey === '') return '';
    if (!empty($shop['is_default'])) return $productKey;
    $vid = (int)($shop['vendor_id'] ?? 0);
    return $vid > 0 ? $productKey . '#v' . $vid : $productKey;
}

/** v10.20 (۳۳الف): شناسهٔ محصول در یک غرفهٔ مشخص را در دفترچه ثبت می‌کند */
function bslShopMapRecord(array $p, array $shop, int $remoteId, string $title,
                          int $priceRial = 0, int $stock = -1): void {
    if ($remoteId <= 0) return;
    $mk = bslShopMapKey((string)($p['key'] ?? ''), $shop);
    if ($mk === '') return;
    $row = ['key' => $mk, 'remote_id' => $remoteId, 'title' => $title];
    /* v10.33 (۴۶): قیمت و موجودیِ واقعاً ارسال‌شده هم ثبت می‌شود تا دفعهٔ
       بعد بشود فهمید چیزی عوض شده یا نه. تا اینجا دفترچه فقط شناسه را
       نگه می‌داشت، برای همین هر اجرا مجبور بود کورکورانه PATCH بزند. */
    if ($priceRial > 0) $row['price_rial'] = $priceRial;
    if ($stock >= 0)    $row['stock'] = $stock;
    remoteMapRecord('bsl', [$row]);
    /* v10.35 (۴۷ب): کشِ کاتالوگ هم همان لحظه به‌روز شود. بدونِ این، محصولی
       که همین حالا ساختیم تا پایانِ TTL در کش «نیست» می‌ماند و اگر در
       همان اجرا دوباره سراغش برویم، مسیرِ «ایجاد» می‌رفت و باسلام خطای
       نام تکراری می‌داد. */
    bslCatalogNote((int)($shop['vendor_id'] ?? 0), $title, $remoteId);
}

/* =====================================================================
 *  v10.33 (۴۶): پرشِ آپدیتِ بی‌مورد
 *
 *  مشکل: مسیرِ ارسال، محصولِ موجود را همیشه PATCH می‌کرد — حتی وقتی
 *  قیمت و موجودی مو نمی‌زد. روی پروفایلِ ۳۰۰۰ محصولی که ۴۰ قیمتش عوض
 *  شده، یعنی ۳۰۰۰ درخواستِ نوشتن برای انجامِ ۴۰ کار. روی هاستِ اشتراکی
 *  همین یکی از دلایلِ اصلیِ تایم‌اوت بود.
 *
 *  حالا آخرین چیزی که خودمان فرستادیم در دفترچه می‌ماند و اگر این بار
 *  دقیقاً همان باشد، PATCH اصلاً زده نمی‌شود.
 *
 *  چرا «بازبینیِ دوره‌ای» هم داریم: دفترچه آینهٔ کارِ خودِ ماست، نه خودِ
 *  باسلام. اگر کسی از پنلِ باسلام قیمتی را دستی عوض کند، دفترچه بی‌خبر
 *  می‌ماند و آن اختلاف برای همیشه ماندگار می‌شود. کاربر گفته دستکاریِ
 *  دستی «بسیار به‌ندرت» دارد، پس این ریسک کوچک است — ولی صفر نیست و
 *  خطایش هم بی‌صداست. برای همین هر محصول هرچند وقت یک‌بار به‌زور آپدیت
 *  می‌شود تا هر انحرافی خودبه‌خود جوش بخورد. با پیش‌فرضِ ۷ روز، هزینه‌اش
 *  در بدترین حالت یک‌هفتم حالتِ قبلی است.
 * ===================================================================== */
const BSL_REVERIFY_SEC = 604800;   // ۷ روز

/**
 * آیا می‌شود از آپدیتِ این محصول در این غرفه صرف‌نظر کرد؟
 * فقط وقتی «آری» که شناسه، قیمت و موجودیِ ثبت‌شده همگی با حالا یکی باشند
 * و از آخرین تأیید هم خیلی نگذشته باشد.
 */
function bslSkipUnchanged(string $mapKey, int $exId, int $priceRial, int $stock,
                          ?array $ledgerRow = null): bool {
    if ($mapKey === '' || $exId <= 0) return false;
    if (defined('BSL_FORCE_SYNC') && BSL_FORCE_SYNC) return false;
    if ($ledgerRow === null) $ledgerRow = (remoteMapLoad()['bsl'][$mapKey] ?? null);
    if (!is_array($ledgerRow)) return false;
    if ((int)($ledgerRow['id'] ?? 0) !== $exId) return false;
    /* نبودِ قیمت در دفترچه یعنی ردیفِ قدیمیِ پیش از v10.33 — دربارهٔ آن
       چیزی نمی‌دانیم، پس محافظه‌کارانه آپدیت می‌کنیم تا ردیف تازه شود. */
    if (!isset($ledgerRow['price_rial'])) return false;
    if ((int)$ledgerRow['price_rial'] !== $priceRial) return false;
    if (isset($ledgerRow['stock']) && (int)$ledgerRow['stock'] !== $stock) return false;
    $at = (int)($ledgerRow['at'] ?? 0);
    if ($at <= 0 || (time() - $at) > (int)BSL_REVERIFY_SEC) return false;   // بازبینیِ دوره‌ای
    return true;
}

/** شمارندهٔ پرش‌ها، فقط برای اینکه در گزارش دیده شود چقدر صرفه‌جویی شد. */
function bslSkipCount(int $add = 0): int {
    static $n = 0;
    if ($add > 0) $n += $add;
    return $n;
}

/* v10.20 (۳۳الف): شناسهٔ محصولِ موجود را در چند غرفه «همزمان» پیدا می‌کند.
   اول دفترچهٔ نگاشتِ همان غرفه (بدون هیچ درخواستی)، بعد برای بقیهٔ غرفه‌ها
   یک درخواستِ جست‌وجوی عنوان که همه با هم اجرا می‌شوند.
   خروجی: [vendor_id => product_id] فقط برای غرفه‌هایی که محصول در آن‌ها هست. */
function bslShopsFindExistingMulti(string $title, string $productKey, array $shops, int $conc = 4): array {
    $ids = []; $need = [];
    $map = remoteMapLoad()['bsl'] ?? [];
    foreach ($shops as $sh) {
        $vid = (int)($sh['vendor_id'] ?? 0);
        if ($vid <= 0 || trim((string)($sh['token'] ?? '')) === '') continue;
        $mk = bslShopMapKey($productKey, $sh);
        $known = $mk !== '' ? (int)($map[$mk]['id'] ?? 0) : 0;
        if ($known > 0) { $ids[$vid] = $known; continue; }
        /* v10.35 (۴۷ب): پیش از فرستادنِ درخواست، از کشِ کاتالوگِ همان غرفه
           بپرس. کشِ کاملِ تازه هم «هست» را جواب می‌دهد و هم «نیست» — و
           «نیست» یعنی این غرفه اصلاً لازم نیست در موجِ درخواست‌ها باشد. */
        $hit = bslCatalogLookup((string)$sh['token'], $vid, $title);
        if ($hit > 0)  { $ids[$vid] = $hit; bslCatalogSaved(1); continue; }
        if ($hit === 0) { bslCatalogSaved(1); continue; }
        $need[$vid] = $sh;
    }
    if ($need) {
        $q = bslNormalizeTitle($title);
        if ($q === '') $q = trim($title);
        $jobs = [];
        foreach ($need as $vid => $sh) {
            $jobs[$vid] = ['tk' => (string)$sh['token'], 'm' => 'GET',
                'ep' => 'vendors/' . $vid . '/products?per_page=50' . bslStatusQuery()
                        . '&title=' . urlencode($q)];
        }
        foreach (bslReqMulti($jobs, $conc) as $vid => $r) {
            if (empty($r['ok'])) continue;
            $rows = $r['body']['data'] ?? [];
            if (!is_array($rows) || !$rows) continue;
            $how = '';
            $hit = findRemoteByTitle($rows, $title, '', 'title', $how);
            if (is_array($hit) && (int)($hit['id'] ?? 0) > 0) $ids[(int)$vid] = (int)$hit['id'];
        }
    }
    return $ids;
}

/* =====================================================================
 *  v10.20 (۳۳الف): ارسالِ «همزمان» یک محصول به چند غرفه
 *
 *  تیکِ «ارسال به همهٔ غرفه‌ها» از v9.69 بود ولی غرفه‌ها یکی‌یکی و کاملاً
 *  ترتیبی پردازش می‌شدند: غرفهٔ دوم تا وقتی کلِ غرفهٔ اول تمام نمی‌شد شروع
 *  نمی‌کرد. با ۵۰ محصول و ۳ غرفه یعنی سه برابرِ زمان، و روی هاستِ اشتراکی
 *  معمولاً وسطِ راه تایم‌اوت. برای کاربر شبیهِ «کار نمی‌کند» بود.
 *
 *  حالا هر محصول یک بار پردازش می‌شود و همهٔ غرفه‌ها با هم می‌روند:
 *    فاز ۱ — جست‌وجوی همزمانِ شناسه در همهٔ غرفه‌ها
 *    فاز ۲ — PATCHِ همزمان برای غرفه‌هایی که محصول را دارند
 *    فاز ۳ — POSTِ همزمان برای غرفه‌هایی که ندارند
 *    فاز ۴ — هر غرفه‌ای که در فاز ۲/۳ شکست خورد، از مسیرِ تکیِ آزمودهٔ
 *            bslUpsertToShop رد می‌شود (جست‌وجوی عمیق، «نام تکراری»،
 *            دسته‌های جایگزین). یعنی سرعت اضافه شده، ولی هیچ توانایی‌ای
 *            از دست نرفته.
 *
 *  خروجی: [vendor_id => ['ok'=>bool,'id'=>int,'action'=>'created|updated','error'=>string]]
 * ===================================================================== */
function bslUpsertManyShops(array $p, array $shops, array $opts, int $conc = 4): array {
    $out = [];
    $title = trim((string)($p['title'] ?? ($p['name'] ?? '')));
    $pKey  = (string)($p['key'] ?? '');
    if ($title === '') {
        foreach ($shops as $sh) { $v = (int)($sh['vendor_id'] ?? 0); if ($v > 0) $out[$v] = ['ok' => false, 'error' => 'عنوان خالی']; }
        return $out;
    }
    $round   = (int)($opts['round'] ?? 0);
    $profile = is_array($opts['profile'] ?? null) ? $opts['profile'] : null;

    // قیمتِ هر غرفه (محاسبهٔ محلی، بدون هیچ درخواستی)
    $prices = []; $live = [];
    foreach ($shops as $sh) {
        $vid = (int)($sh['vendor_id'] ?? 0); $tk = trim((string)($sh['token'] ?? ''));
        if ($vid <= 0 || $tk === '') continue;
        $rawP = (string)($p['price'] ?? ($p['orig_price'] ?? ''));
        if ($profile && $rawP !== '' && extractPriceNum($rawP) > 0) {
            $pf = bslShopPriceForProfile($profile, $rawP, $sh, $round);
        } else {
            $baseP = (int)preg_replace("/[^0-9]/", "", (string)($p['final_price'] ?? '0'));
            if ($baseP <= 0) { $out[$vid] = ['ok' => false, 'error' => 'قیمت ۰']; continue; }
            $pf = bslShopPriceFor($baseP, $sh, $round);
        }
        if ((int)($pf['price'] ?? 0) <= 0) { $out[$vid] = ['ok' => false, 'error' => 'قیمت نامعتبر']; continue; }
        $pr = (int)$pf['price'];
        if ((string)($p['price_unit'] ?? '') !== 'rial') $pr = $pr * 10;
        $prices[$vid] = $pr; $live[$vid] = $sh;
    }
    if (!$live) return $out;

    $stock  = effectiveStock($p, (int)($opts['stock'] ?? 10));    // v10.21 (۳۴الف)
    $prepD  = (int)($opts['preparation_days'] ?? 3);
    $weight = (int)($opts['weight'] ?? 500);
    $pkgW   = (int)($opts['package_weight'] ?? ($weight + 100));
    $catId  = (int)($opts['category_id'] ?? 0);
    $autoCat= !empty($opts['auto_category']);
    $flatCats = is_array($opts['flat_cats'] ?? null) ? $opts['flat_cats'] : [];
    $cData    = is_array($opts['cdata'] ?? null) ? $opts['cdata'] : [];

    // ---- فاز ۱: شناسه‌ها، همزمان
    $ids = bslShopsFindExistingMulti($title, $pKey, $live, $conc);

    // ---- فاز ۲: آپدیتِ همزمان
    $ledger = [];
    if ($ids) {
        $jobs = [];
        /* v10.33 (۴۶): دفترچه یک بار خوانده می‌شود، نه یک بار برای هر غرفه.
           در حلقهٔ چند هزار محصولی، خواندنِ مکررِ همین فایل خودش گران است. */
        $__bslMap = remoteMapLoad()['bsl'] ?? [];
        foreach ($ids as $vid => $exId) {
            if (!isset($live[$vid])) continue;
            $__mk = bslShopMapKey($pKey, $live[$vid]);
            if (bslSkipUnchanged($__mk, (int)$exId, (int)$prices[$vid], $stock,
                                 $__bslMap[$__mk] ?? null)) {
                bslSkipCount(1);
                $out[(int)$vid] = ['ok' => true, 'id' => (int)$exId,
                                   'action' => 'unchanged', 'skipped' => true];
                continue;   // نه PATCH، نه ثبتِ دوباره در دفترچه
            }
            $bu = ['primary_price' => $prices[$vid], 'stock' => $stock, 'status' => 2976,
                   'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW];
            if ($catId > 0) $bu['category_id'] = $catId;
            bslApplyContent($bu, $p); /* v10.98: توضیح + تنوع */
            $jobs[$vid] = ['tk' => (string)$live[$vid]['token'], 'm' => 'PATCH',
                           'ep' => 'products/' . $exId, 'd' => $bu];
        }
        $rs = bslReqMulti($jobs, $conc);
        // موجِ دوم: هرکدام ۴۰۴ گرفت، با مسیرِ غرفه‌ای دوباره امتحان می‌شود
        $again = [];
        foreach ($rs as $vid => $r) {
            if ((int)($r['code'] ?? 0) === 404) {
                $again[$vid] = ['tk' => (string)$live[$vid]['token'], 'm' => 'PATCH',
                                'ep' => 'vendors/' . $vid . '/products/' . $ids[$vid], 'd' => $jobs[$vid]['d']];
            }
        }
        if ($again) foreach (bslReqMulti($again, $conc) as $vid => $r2) $rs[$vid] = $r2;
        foreach ($rs as $vid => $r) {
            if (!empty($r['ok']) && !empty($r['body']['id'])) {
                $out[(int)$vid] = ['ok' => true, 'id' => (int)$ids[$vid], 'action' => 'updated'];
                $ledger[(int)$vid] = (int)$ids[$vid];
            }
        }
    }

    // ---- فاز ۳: ساختِ همزمان برای غرفه‌هایی که محصول را ندارند
    $toCreate = [];
    foreach ($live as $vid => $sh) if (empty($out[$vid]['ok'])) $toCreate[$vid] = $sh;
    if ($toCreate) {
        $catUsed = $catId;
        /* v10.83: اگر AI قبلاً دستهٔ باسلام را روی محصول نوشته، همان را بگیر */
        if ($catUsed <= 0) {
            $catUsed = (int)($p['bsl_category_id'] ?? $p['category_id'] ?? 0);
        }
        if ($catUsed <= 0 && $autoCat && !empty($flatCats)) {
            $_ac = autoMatchBslCategory($title, $flatCats);
            if ($_ac > 0) $catUsed = $_ac;
        }
        if ($catUsed > 0 && !empty($cData)) $catUsed = findLeafCategory($catUsed, $cData);
        $brief = trim(strip_tags((string)($p['short_desc'] ?? $p['shortDesc'] ?? $p['brief'] ?? '')));
        $desc  = trim((string)($p['long_desc'] ?? $p['longDesc'] ?? $p['description'] ?? ''));
        if ($brief === '') $brief = trim(strip_tags($title));
        if ($desc === '')  $desc  = $brief;
        /* v10.98: تنوع‌ها در توضیح ساخت */
        $_buTmp = [];
        bslApplyContent($_buTmp, array_merge($p, ['short_desc' => $brief, 'long_desc' => $desc]));
        if (!empty($_buTmp['brief'])) $brief = (string)$_buTmp['brief'];
        if (!empty($_buTmp['description'])) $desc = (string)$_buTmp['description'];
        $jobs = [];
        foreach ($toCreate as $vid => $sh) {
            $bp = ['name' => mb_substr($title, 0, 120), 'brief' => mb_substr($brief, 0, 250),
                   'description' => $desc, 'primary_price' => $prices[$vid], 'stock' => $stock,
                   'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW,
                   'is_wholesale' => false, 'category_id' => $catUsed, 'status' => 3790];
            if (!empty($p['sku'])) $bp['sku'] = $p['sku'];
            $jobs[$vid] = ['tk' => (string)$sh['token'], 'm' => 'POST',
                           'ep' => 'vendors/' . $vid . '/products', 'd' => $bp];
        }
        foreach (bslReqMulti($jobs, $conc) as $vid => $r) {
            if (!empty($r['ok']) && !empty($r['body']['id'])) {
                $out[(int)$vid] = ['ok' => true, 'id' => (int)$r['body']['id'], 'action' => 'created'];
                $ledger[(int)$vid] = (int)$r['body']['id'];
            } else {
                $em = $r['body']['message'] ?? $r['body']['error'] ?? ($r['error'] ?? '؟');
                if (is_array($em)) $em = json_encode($em, JSON_UNESCAPED_UNICODE);
                $out[(int)$vid] = ['ok' => false, 'error' => mb_substr((string)$em, 0, 140)];
            }
        }
    }

    // ---- فاز ۴: هر شکستی از مسیرِ تکیِ کاملِ قدیمی رد می‌شود.
    //      اگر سیگنالِ توقف رسیده باشد این فاز اجرا نمی‌شود، وگرنه هر غرفه
    //      یک 'stopped' می‌گیرد و آن محصول بی‌دلیل «خطا» شمرده می‌شود.
    clearstatcache(true, BSL_STOP_FILE);
    $__stopNow = file_exists(BSL_STOP_FILE) && (time() - (int)@filemtime(BSL_STOP_FILE)) <= BSL_STOP_HOLD_SEC;
    foreach ($live as $vid => $sh) {
        if (!empty($out[$vid]['ok'])) continue;
        if ($__stopNow) { $out[(int)$vid] = ['ok' => false, 'stopped' => true, 'error' => 'stopped']; continue; }
        $one = bslUpsertToShop($p, $sh, $opts);
        $out[(int)$vid] = $one;
        if (!empty($one['ok']) && (int)($one['id'] ?? 0) > 0) $ledger[(int)$vid] = (int)$one['id'];
    }

    // شناسه‌ها را برای دفعهٔ بعد ثبت کن تا جست‌وجو لازم نشود
    if ($ledger && $pKey !== '') {
        $rows = [];
        foreach ($ledger as $vid => $rid) {
            $mk = bslShopMapKey($pKey, $live[$vid]);
            /* v10.33 (۴۶): قیمت و موجودی حتماً باید همراهِ همین ردیف نوشته
               شوند. remoteMapRecord کلِ ردیف را جایگزین می‌کند، پس اگر
               اینجا بدونشان بنویسیم، چیزی که چند خط بالاتر ثبت شده پاک
               می‌شود و پرشِ دفعهٔ بعد هیچ‌وقت اتفاق نمی‌افتد. */
            if ($mk !== '') $rows[] = ['key' => $mk, 'remote_id' => $rid, 'title' => $title,
                                       'price_rial' => (int)($prices[$vid] ?? 0), 'stock' => $stock];
            bslCatalogNote((int)$vid, $title, (int)$rid);   // v10.35 (۴۷ب)
        }
        if ($rows) remoteMapRecord('bsl', $rows);
    }
    return $out;
}

function bslUpsertToShop(array $p, array $shop, array $opts): array {
    $tk   = (string)($shop['token'] ?? '');
    $vid  = (int)($shop['vendor_id'] ?? 0);
    if ($tk === '' || $vid <= 0) return ['ok' => false, 'error' => 'غرفهٔ نامعتبر'];
    $title = trim((string)($p['title'] ?? ($p['name'] ?? '')));
    if ($title === '') return ['ok' => false, 'error' => 'عنوان خالی'];
    $round  = (int)($opts['round'] ?? 0);
    $profile= is_array($opts['profile'] ?? null) ? $opts['profile'] : null;
    // قیمتِ این غرفه: لایهٔ پروفایل (اگر قیمتِ خام بود) + لایهٔ خودِ غرفه
    $rawP  = (string)($p['price'] ?? ($p['orig_price'] ?? ''));
    if ($profile && $rawP !== '' && extractPriceNum($rawP) > 0) {
        $pf = bslShopPriceForProfile($profile, $rawP, $shop, $round);
    } else {
        $baseP = (int)preg_replace("/[^0-9]/", "", (string)($p['final_price'] ?? '0'));
        if ($baseP <= 0) return ['ok' => false, 'error' => 'قیمت ۰'];
        $pf = bslShopPriceFor($baseP, $shop, $round);
    }
    $priceToman = $pf['price'];
    if ($priceToman <= 0) return ['ok' => false, 'error' => 'قیمت نامعتبر'];
    $priceRial = (($p['price_unit'] ?? '') !== 'rial') ? $priceToman * 10 : $priceToman;

    $stock   = effectiveStock($p, (int)($opts['stock'] ?? 10));   // v10.21 (۳۴الف)
    $prepD   = (int)($opts['preparation_days'] ?? 3);
    $weight  = (int)($opts['weight'] ?? 500);
    $pkgW    = (int)($opts['package_weight'] ?? ($weight + 100));
    $catId   = (int)($opts['category_id'] ?? 0);
    $fallback= is_array($opts['fallback_cat_ids'] ?? null) ? $opts['fallback_cat_ids'] : [];
    $autoCat = !empty($opts['auto_category']);
    $flatCats= is_array($opts['flat_cats'] ?? null) ? $opts['flat_cats'] : [];
    $cData   = is_array($opts['cdata'] ?? null) ? $opts['cdata'] : [];

    // v10.20 (۳۳الف): دفترچهٔ نگاشتِ همین غرفه، نه شناسهٔ غرفهٔ پیش‌فرض
    $__mk = bslShopMapKey((string)($p['key'] ?? ''), $shop);
    $existing = bslFindExisting($tk, $vid, $title, $__mk);
    $exId = is_array($existing) ? (int)($existing['id'] ?? 0) : 0;

    if ($exId > 0) {
        /* v10.33 (۴۶): اگر قیمت و موجودی همانی است که خودمان آخرین بار
           فرستادیم، این PATCH هیچ کاری نمی‌کند جز مصرفِ یک درخواست. */
        if (bslSkipUnchanged($__mk, $exId, $priceRial, $stock)) {
            bslSkipCount(1);
            return ['ok' => true, 'id' => $exId, 'action' => 'unchanged', 'skipped' => true];
        }
        $bu = ['primary_price' => $priceRial, 'stock' => $stock, 'status' => 2976,
               'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW];
        if ($catId > 0) $bu['category_id'] = $catId;
        bslApplyContent($bu, $p); /* v10.98: توضیح + تنوع */
        $r = bslReq($tk, 'PATCH', 'products/' . $exId, $bu);
        if ($r['code'] === 404) $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $exId, $bu);
        if (!empty($r['ok']) && !empty($r['body']['id'])) {
            bslShopMapRecord($p, $shop, $exId, $title, $priceRial, $stock);   // v10.20 (۳۳الف) · v10.33 (۴۶)
            return ['ok' => true, 'id' => $exId, 'action' => 'updated'];
        }
        return ['ok' => false, 'error' => 'آپدیت در این غرفه ناموفق: ' . mb_substr((string)($r['body']['message'] ?? ($r['error'] ?? '?')), 0, 120)];
    }

    $catUsed = $catId;
    /* v10.83: دستهٔ از پیش نگاشت‌شده روی محصول (AI content auto) */
    if ($catUsed <= 0) {
        $catUsed = (int)($p['bsl_category_id'] ?? $p['category_id'] ?? 0);
    }
    if ($catUsed <= 0 && $autoCat && !empty($flatCats)) {
        $_ac = autoMatchBslCategory($title, $flatCats);
        if ($_ac > 0) $catUsed = $_ac;
    }
    if ($catUsed > 0 && !empty($cData) && is_array($cData)) $catUsed = findLeafCategory($catUsed, $cData);
    $brief = trim(strip_tags((string)($p['short_desc'] ?? $p['shortDesc'] ?? $p['brief'] ?? '')));
    $desc  = trim((string)($p['long_desc'] ?? $p['longDesc'] ?? $p['description'] ?? ''));
    if ($brief === '') $brief = trim(strip_tags($title));
    if ($desc === '')  $desc  = $brief;
    $_buTmp = [];
    bslApplyContent($_buTmp, array_merge($p, ['short_desc' => $brief, 'long_desc' => $desc]));
    if (!empty($_buTmp['brief'])) $brief = (string)$_buTmp['brief'];
    if (!empty($_buTmp['description'])) $desc = (string)$_buTmp['description'];
    $bp = ['name' => mb_substr($title, 0, 120), 'brief' => mb_substr($brief, 0, 250),
           'description' => $desc, 'primary_price' => $priceRial, 'stock' => $stock,
           'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW,
           'is_wholesale' => false, 'category_id' => $catUsed, 'status' => 3790];
    if (!empty($p['sku'])) $bp['sku'] = $p['sku'];
    $r = bslReq($tk, 'POST', 'vendors/' . $vid . '/products', $bp);
    if (!empty($r['ok']) && !empty($r['body']['id'])) {
        bslShopMapRecord($p, $shop, (int)$r['body']['id'], $title, $priceRial, $stock);   // v10.20 (۳۳الف) · v10.33 (۴۶)
        return ['ok' => true, 'id' => (int)$r['body']['id'], 'action' => 'created'];
    }
    $fb = bslTryCreateWithFallback($tk, $vid, $bp, $fallback, $title, $autoCat, $flatCats, $cData);
    if (!empty($fb['ok']) && !empty($fb['body']['id'])) {
        bslShopMapRecord($p, $shop, (int)$fb['body']['id'], $title);  // v10.20 (۳۳الف)
        return ['ok' => true, 'id' => (int)$fb['body']['id'], 'action' => 'created'];
    }
    $em = $r['body']['message'] ?? $r['body']['error'] ?? ($r['error'] ?? '؟');
    if (is_array($em)) $em = json_encode($em, JSON_UNESCAPED_UNICODE);
    return ['ok' => false, 'error' => mb_substr((string)$em, 0, 140)];
}

/** امضای تنظیمات قیمت — اگر عوض شود یعنی قیمت همهٔ محصولات عوض شده */
function profilePriceSignature(array $profile): string {
    return (string)($profile['priceMode'] ?? 'none') . '|'
         . (string)($profile['priceVal'] ?? 0) . '|'
         . (string)($profile['roundPrice'] ?? 0) . '|'
         . trim((string)($profile['titleSuffix'] ?? ''));
}

/* =====================================================================
 *  v10.34 (۴۸ب): امضای ضرایبِ تعدیلِ مقصدها و غرفه‌ها.
 *
 *  profilePriceSignature فقط ضریبِ خودِ پروفایل را می‌دید. ولی قیمتِ
 *  نهاییِ یک محصول از سه لایه می‌آید:
 *      ۱) تعدیلِ پروفایل            (priceMode/priceVal/roundPrice)
 *      ۲) تعدیلِ مقصد               (woocommerce/basalam · price_mode…)
 *      ۳) تعدیلِ مخصوصِ هر غرفه      (basalam.vendors[].price_mode…)
 *
 *  اگر کاربر لایهٔ ۲ یا ۳ را عوض می‌کرد، قیمتِ همهٔ محصولات عوض می‌شد ولی
 *  هیچ‌کس خبردار نمی‌شد: امضا دست‌نخورده می‌ماند، تیکِ «فقط تغییرات» روشن
 *  بود و مبدأ هم چیزی تغییر نداده بود — پس هیچ محصولی صف نمی‌شد و قیمتِ
 *  تازه هرگز به مقصد نمی‌رسید. تنها راهِ اعمالش خاموش‌کردنِ دستیِ تیک بود.
 *
 *  حالا این امضا جدا نگه داشته می‌شود (کلیدِ shop_sig در وضعیتِ سینک) و
 *  هر تغییری در آن یک نوبت ارسالِ «همه با دستور آپدیت» راه می‌اندازد.
 *  جدا بودنش از price_sig عمدی است: ردیف‌های قدیمی این کلید را ندارند و
 *  نبودنش «تغییر» حساب نمی‌شود، وگرنه صرفاً با نصبِ این نسخه یک ارسالِ
 *  کاملِ ناخواسته برای همهٔ پروفایل‌ها راه می‌افتاد.
 * ===================================================================== */
function shopPricingSignature(array $cn): string {
    $parts = [];
    foreach (['woocommerce', 'basalam'] as $dest) {
        $d = $cn[$dest] ?? [];
        $parts[] = $dest . ':' . (string)($d['price_mode'] ?? 'none')
                 . '/' . (string)($d['price_val'] ?? 0)
                 . '/' . (string)($d['price_round'] ?? 0);
    }
    /* غرفهٔ پیش‌فرض هم ضریبِ خودش را دارد و باید دیده شود */
    $parts[] = 'v0:' . (int)($cn['basalam']['vendor_id'] ?? 0);
    $vendors = $cn['basalam']['vendors'] ?? [];
    if (is_array($vendors)) {
        $rows = [];
        foreach ($vendors as $v) {
            if (!is_array($v)) continue;
            $vid = (int)($v['vendor_id'] ?? 0);
            if ($vid <= 0) continue;
            $rows[] = 'v' . $vid . ':' . (string)($v['price_mode'] ?? 'none')
                    . '/' . (string)($v['price_val'] ?? 0);
        }
        sort($rows);   // ترتیبِ ردیف‌ها در تنظیمات نباید «تغییر» حساب شود
        $parts = array_merge($parts, $rows);
    }
    return implode('|', $parts);
}

/* =====================================================================
 *  v10.34 (۴۸الف): اقدامِ حالتِ «افزودن/آپدیت» روی محصولاتِ رفته از مبدأ.
 *
 *  خواستهٔ کاربر: وقتی تیکِ افزودن/آپدیت روشن است، فرآیند باید
 *  «افزودن/آپدیت/بایگانی» برای باسلام و «افزودن/آپدیت/حذف» برای ووکامرس
 *  باشد — یعنی خودِ تیک، بازنشستگی را هم روشن می‌کند و دیگر لازم نیست
 *  کاربر جداگانه تنظیمِ سراسریِ «محصولات رفته از مبدأ» را از off دربیاورد.
 *
 *  اقدامِ ووکامرس قابلِ انتخاب است (کاربر صراحتاً خواست): زباله‌دان
 *  (پیش‌فرض و برگشت‌پذیر)، حذفِ همیشگی، پیش‌نویس، یا ناموجود.
 *  اقدامِ باسلام هم قابلِ انتخاب است ولی «حذفِ همیشگی» ندارد، چون API
 *  باسلام اصلاً حذف ندارد و نزدیک‌ترین چیز بایگانی (4184) است.
 * ===================================================================== */
function retireWooActions(): array {
    return ['delete' => 'حذف (زباله‌دان)', 'delete_force' => 'حذف همیشگی',
            'draft' => 'پیش‌نویس', 'outofstock' => 'ناموجود'];
}
function retireBslActions(): array {
    return ['delete' => 'بایگانی', 'draft' => 'غیرفعال', 'outofstock' => 'ناموجود'];
}
/** اقدامِ مؤثرِ هر مقصد در حالتِ «افزودن/آپدیت» — با اعتبارسنجی و پیش‌فرضِ امن */
function retireAddUpdateAction(array $cn, string $dest): string {
    if ($dest === 'woo') {
        $a = (string)($cn['retire_woo_action'] ?? 'delete');
        return isset(retireWooActions()[$a]) ? $a : 'delete';
    }
    $a = (string)($cn['retire_bsl_action'] ?? 'delete');
    return isset(retireBslActions()[$a]) ? $a : 'delete';
}

/** محصول ذخیره‌شده را به همان شکلی درمی‌آورد که مرورگر می‌فرستد */
function prepareForSend(array $profile, string $key, array $p): array {
    $raw = (string)($p['price'] ?? '');
    $title = trim((string)($p['title'] ?? ($p['name'] ?? '')));
    $suffix = trim((string)($profile['titleSuffix'] ?? ''));
    if ($suffix !== '' && $title !== '' && mb_strpos($title, $suffix) === false) {
        $title .= ' ' . $suffix;
    }
    $unit = (mb_strpos($raw, 'ریال') !== false || mb_strpos($raw, 'ر.ی') !== false)
          ? 'rial' : 'toman';
    return [
        'key'         => $key,
        'title'       => $title,
        'final_price' => (string)profileFinalPrice($profile, $raw),
        'price'       => $raw,
        'price_unit'  => $unit,
        'image'       => (string)($p['image'] ?? ''),
        // v8.64: گالری — بقیهٔ عکس‌های محصول همراهش می‌روند
        'images'      => productImageList($p),
        'sku'         => (string)($p['sku'] ?? ''),
        'short_desc'  => (string)($p['shortDesc'] ?? ($p['short_desc'] ?? '')),
        'long_desc'   => (string)($p['longDesc'] ?? ($p['long_desc'] ?? '')),
        'weight'      => (string)($p['weight'] ?? ''),
        'link'        => (string)($p['link'] ?? ''),
        'orig_price'  => (string)($p['origPrice'] ?? ($p['originalPrice'] ?? '')),
        // v8.69: تنوع‌ها هم باید به ارسال‌کننده برسند
        'variations'       => is_array($p['variations'] ?? null) ? $p['variations'] : [],
        'variation_groups' => is_array($p['variation_groups'] ?? null) ? $p['variation_groups'] : [],
        'variations_text'  => (string)($p['variations_text']
                              ?? (is_array($p['variations'] ?? null) ? implode('، ', $p['variations']) : '')),
    ];
}

/**
 * از نتیجهٔ استخراج، کلید محصولاتی را برمی‌گرداند که باید ارسال شوند.
 * خروجی null یعنی «فیلتری اعمال نکن» (همه را بفرست).
 */
function syncChangedKeys(array $exRes): ?array {
    if (empty($exRes['ok'])) return null;   // استخراج نشد؛ به لیست تغییرات اعتماد نکن
    $keys = [];
    foreach (['new_items', 'changed_items'] as $bucket) {
        foreach (($exRes[$bucket] ?? []) as $it) {
            if (!is_array($it)) continue;
            $k = (string)($it['key'] ?? '');
            if ($k !== '') $keys[$k] = true;
        }
    }
    return $keys;
}

/**
 * محصولات پروفایل را به ترتیب درست و همراه با کلیدشان برمی‌گرداند.
 * محصولات به شکل [کلید, محصول] ذخیره می‌شوند و کران قبلاً کلید را دور
 * می‌ریخت؛ برای فیلتر کردن لازم است نگه داشته شود.
 *
 * $onlyKeys اگر داده شود، فقط همان کلیدها برگردانده می‌شوند.
 */
function profileOrderedProducts(array $profile, ?array $onlyKeys = null, bool $forSend = true): array {
    $raw = $profile['products'] ?? [];
    $map = [];
    foreach ($raw as $entry) {
        if (is_array($entry) && count($entry) >= 2 && is_string($entry[0])) {
            $map[$entry[0]] = $entry[1];
        }
    }
    // v8.44: قیمت نهایی را همین‌جا بساز، وگرنه ارسال‌کننده final_price
    // را پیدا نمی‌کند و قیمت صفر می‌فرستد.
    $mk = function (string $k, $p) use ($profile, $forSend) {
        if (!is_array($p)) return null;
        return $forSend ? prepareForSend($profile, $k, $p) : $p;
    };
    $order = $profile['productsOrder'] ?? [];
    $out = [];
    if (!empty($order) && is_array($order)) {
        foreach ($order as $k) {
            if (!isset($map[$k])) continue;
            if ($onlyKeys !== null && !isset($onlyKeys[$k])) continue;
            $v = $mk((string)$k, $map[$k]); if ($v !== null) $out[] = $v;
        }
        return $out;
    }
    if ($map) {
        foreach ($map as $k => $p) {
            if ($onlyKeys !== null && !isset($onlyKeys[$k])) continue;
            $v = $mk((string)$k, $p); if ($v !== null) $out[] = $v;
        }
        return $out;
    }
    // ساختار قدیمی: فهرست تخت بدون کلید — فیلتر ممکن نیست
    foreach ($raw as $entry) {
        if (!is_array($entry) || (!isset($entry['title']) && !isset($entry['price']))) continue;
        $k = (string)($entry['key'] ?? '');
        $out[] = $forSend ? prepareForSend($profile, $k, $entry) : $entry;
    }
    return $out;
}

// v8.31: تنها نقطهٔ ورود کران — cron_sync حذف شد چون دقیقاً همین کار را می‌کرد.
/**
 * v8.89: نگهبان‌ها در یک تابع، تا بشود آن‌ها را قبل از قفل کران هم اجرا کرد.
 *
 * تا ۸.۸۸ این کد داخل بدنهٔ cron_run بود و بعد از بررسی قفل قرار داشت.
 * ولی وقتی یک اجرا وسط کار می‌مُرد، فایل قفل باقی می‌ماند و تا ۳۰ دقیقه
 * هر اجرای بعدی همان اول رد می‌شد — یعنی دقیقاً در حالتی که نگهبان لازم
 * بود، هیچ‌وقت اجرا نمی‌شد و کار گیرکرده تا نیم ساعت همان‌طور می‌ماند.
 */
/* =====================================================================
   v9.92: «نوبت را همین حالا مصرف کن» — رفعِ ریشه‌ایِ اجرای مکررِ کران.

   تا ۹.۹۱، lastRun فقط جایی نوشته می‌شد که پروفایل واقعاً به مرحلهٔ
   ارسال می‌رسید، و saveSyncState هم تازه «بعد از پایانِ کلِ حلقه» صدا
   زده می‌شد. یعنی lastRun فقط در سناریوی کاملاً موفق روی دیسک می‌نشست.
   هر خروجِ زودهنگام یا هر مرگِ پردازه آن را از بین می‌برد:

     • $stageOpen ⇒ status=detail_pending ⇒ continue — بدونِ lastRun
     • target='none' ⇒ هیچ‌کدام از شاخه‌های woo/bsl اجرا نمی‌شود ⇒ فقط
       price_sig ست می‌شود، lastRun نه
     • استخراجِ طولانی ⇒ هاست پردازه را می‌کشد ⇒ saveSyncState هرگز
       اجرا نمی‌شود ⇒ هیچ‌چیز ذخیره نمی‌شود

   نتیجه در هر سه حالت یکی است: تیکِ بعدی (یک دقیقه بعد) همان پروفایل
   را باز هم «due» می‌بیند و کلِ کار — از جمله فازِ جزئیات — دوباره
   شروع می‌شود. دورهٔ ۶ ساعته یا ۲ ساعته عملاً بی‌اثر بود.

   درست این است که نوبت «در لحظهٔ شروع» و «مستقیم روی دیسک» مصرف شود:
   یک نوبت یعنی یک بار تلاش، نه یک بار موفقیت. */
function cronMarkRun(string $key, string $status = 'running'): void {
    if ($key === '') return;
    $st = loadSyncState();
    $row = is_array($st[$key] ?? null) ? $st[$key] : [];
    $row['lastRun'] = time();
    $row['status']  = $status;
    $st[$key] = $row;
    saveSyncState($st);
}

/**
 * v10.24 (۳۷الف): ترتیبِ بازیابیِ صف‌های گیرکرده، بر پایهٔ اولویتِ کاربر.
 *
 * عمداً مستقیم فایلِ ترتیب را می‌خواند و به tasksOrder() تکیه نمی‌کند:
 * نگهبانِ کران در خطِ ~۱۳۶۸۰ اجرا می‌شود، ولی tasksRegistry()/tasksOrder()
 * پایین‌ترِ فایل تعریف می‌شوند و در آن لحظه هنوز وجود ندارند
 * (Call to undefined function). این تابع فقط دو کلیدِ صف را می‌شناسد و
 * هر چیزِ دیگری در فایل را نادیده می‌گیرد، پس به رجیستری نیاز ندارد.
 */
function cronWatchdogQueueOrder(): array {
    $def = ['bsl', 'woo'];
    if (!is_file(TASKS_ORDER_FILE)) return $def;
    $d = json_decode((string)@file_get_contents(TASKS_ORDER_FILE), true);
    $saved = is_array($d['order'] ?? null) ? $d['order'] : [];
    if (!$saved) return $def;
    /* کلیدهای رجیستری «bsl_send»/«woo_send» هستند؛ نگهبان با «bsl»/«woo»
       کار می‌کند، پس نگاشت می‌شود. */
    $map = ['bsl_send' => 'bsl', 'woo_send' => 'woo'];
    $out = [];
    foreach ($saved as $k) {
        $q = $map[(string)$k] ?? '';
        if ($q !== '' && !in_array($q, $out, true)) $out[] = $q;
    }
    foreach ($def as $q) if (!in_array($q, $out, true)) $out[] = $q;
    return $out;
}

function cronWatchdogs(array $cn): array {
    $results = ['watchdog' => []];
// v8.33: مرحلهٔ نگهبان — اگر ارسالی وسط راه گیر کرده، ادامه‌اش بده.
    // هزینه‌اش وقتی چیزی گیر نکرده صفر است: فقط چند خط خواندن از فایل.
    $stallCfg  = (int)($cn['stall_after'] ?? 300);
    $stallWake = !isset($cn['stall_watchdog']) || !empty($cn['stall_watchdog']);
    if ($stallWake) {
        $results['watchdog'] = [];
        /* v10.24 (۳۷الف): ترتیبِ بازیابی دیگر ثابتِ ['bsl','woo'] نیست.
           این تنها جایی است که اولویتِ چیده‌شدهٔ کاربر اثرِ خودکار دارد:
           وقتی هر دو صف با هم گیر کرده‌اند، آنکه بالاترِ فهرستِ مدیر وظیفه
           است زودتر جان می‌گیرد — روی هاستِ اشتراکی که یک نوبتِ کران فقط
           برای یکی‌شان وقت دارد، این تفاوتِ واقعی می‌سازد. */
        foreach (cronWatchdogQueueOrder() as $wq) {
            /* توقفِ تمیز هم باید در کران بعدی از checkpoint برگردد؛
               includePaused فقط در همین watchdogِ کران فعال است. */
            $w = queueStallRecover($wq, $stallCfg, false, 1500, true);
            if (!empty($w['stalled'])) {
                $results['watchdog'][] = $w;
                notifRunFailure($cn, 'نگهبان صف',
                    $wq === 'bsl' ? 'باسلام' : 'ووکامرس',
                    'ارسال ' . ($w['kind'] === 'waiting' ? 'در صف مانده بود' : 'گیر کرده بود')
                    . ' (' . (int)($w['idle'] ?? 0) . ' ثانیه بی‌حرکت، '
                    . (int)($w['current'] ?? 0) . '/' . (int)($w['total'] ?? 0) . ') — '
                    . (!empty($w['resumed']) ? 'خودکار ادامه داده شد ✅' : 'ادامه ناموفق ❌'));
            }
            /* fireAndForget فقط درخواستِ worker را آغاز می‌کند، نه پایانش را.
               پس صفِ بعدی و بقیهٔ کارها باید به کران بعدی واگذار شوند؛ فاصلهٔ
               زمانیِ ثابت هرگز جایِ انتظار/ترتیب را نمی‌گیرد. */
            if (!empty($w['resumed'])) {
                $results['resume_blocking'] = ['kind' => 'queue', 'which' => $wq,
                    'queue_id' => (string)($w['queue_id'] ?? '')];
                break;
            }
        }
    }

    /* v8.87: نگهبان استخراج.
       صف ارسال از ۸.۳۳ نگهبان داشت ولی استخراج نداشت: اگر اجرای خودکار وسط
       کار می‌مُرد (تایم‌اوت هاست، ری‌استارت PHP، قطع شبکه)، ردیف برای همیشه
       «در حال اجرا» می‌ماند و ردیف‌های بعدی هم راه نمی‌افتادند. علامت‌خوردنِ
       «خطا» هم فقط وقتی اتفاق می‌افتاد که کسی صفحهٔ صف را باز کند. */
    if ($stallWake && empty($results['resume_blocking'])) {
        /* v10.148: بررسی و برداشتنِ ردیف stale باید زیرِ خودِ flock باشد؛
           metadata/سنِ lock به‌تنهایی مالکیت را ثابت نمی‌کند و بین probe و
           mutation پنجرهٔ race می‌سازد. */
        $exWatchFp = @fopen(EXTRACT_LOCK_FILE, 'c');
        $exWatchOwned = $exWatchFp && @flock($exWatchFp, LOCK_EX | LOCK_NB);
        if (!$exWatchOwned) {
            if (is_resource($exWatchFp)) @fclose($exWatchFp);
            $exWatchFp = null;
        }
        if ($exWatchOwned) {
        $exProg = readProgress(EXTRACT_PROGRESS_FILE);
        $exQ = extractReadQueue();
        $exNow = time();
        $exDirty = false; $exStuck = null; $exResumeKeys = [];
        foreach ($exQ['entries'] as $qi => $qe) {
            if (($qe['status'] ?? '') !== 'running') continue;
            /* v8.91: همان اصلاحی که در extract_queue_status انجام شد.
               زمان پیشرفت فقط وقتی به این ردیف مربوط است که فایل پیشرفت
               هم مالِ همین ردیف باشد؛ وگرنه اجرای بعدی، ردیفِ رهاشدهٔ
               قبلی را «تازه» نشان می‌داد و نگهبان هیچ‌وقت نمی‌بستش.
               شرط $alive هم برداشته شد: پردازهٔ مرده دقیقاً به این دلیل
               running=true جا می‌گذارد که فرصت نکرده done بنویسد. */
            /* v10.32 (۴۵ج): همان شاهدِ دومِ extract_queue_status — قفل.
               بدون این، نگهبان ردیفِ زندهٔ یک اجرای طولانی را از صف
               برمی‌داشت و استخراج عملاً نیمه‌کاره رها می‌شد.
               v10.36 (۴۹الف): و شاهدِ سوم — حرکتِ شمارنده‌ها. نگهبان دقیقاً
               همان چیزی بود که ردیفِ زنده را می‌بست و به پیام‌رسان خطای
               دروغ می‌فرستاد؛ حالا هر سه شاهد را با هم می‌سنجد. */
            $_lkW = @json_decode((string)@file_get_contents(EXTRACT_LOCK_FILE), true);
            $_lkWBeat = (is_array($_lkW) && ((string)($_lkW['queue_id'] ?? '')) === ((string)($qe['id'] ?? '')))
                ? (int)($_lkW['at'] ?? 0) : 0;
            $_iwW = queueRowIdle('extract', $qe, $exProg, $exNow, ['lock' => $_lkWBeat]);
            $idle = (int)$_iwW['idle'];
            if ($idle <= $stallCfg) continue;
            /* v9.75: به‌جای «بستن و رها کردن»، ردیفِ گیرکرده را از صف برمی‌داریم
               (تا محافظِ تکراری، پروفایل را بلاک نکند) و همان پروفایل را برای
               «ادامهٔ» فازِ ۱/۲ استخراج علامت می‌زنیم. خودِ استخراج با نشانهٔ
               مرحله (_extract_stage) می‌داند از کجا ادامه دهد. */
            $exKey = (string)($qe['profile_key'] ?? '');
            unset($exQ['entries'][$qi]);
            $exDirty = true;
            $exStuck = ['idle' => $idle, 'profile' => (string)($qe['profile_name'] ?? $exKey),
                        'key' => $exKey];
            if ($exKey !== '') $exResumeKeys[] = $exKey;
        }
        if ($exDirty) {
            $exQ['entries'] = array_values($exQ['entries']);
            extractWriteQueue($exQ);
            // فایل پیشرفت هم باز شود وگرنه رابط کاربری «در حال اجرا» نشان می‌دهد
            if (!empty($exProg['running'])) {
                $exProg['running'] = false; $exProg['done'] = true; $exProg['stalled'] = true;
                writeProgress(EXTRACT_PROGRESS_FILE, $exProg);
            }
            $results['extract_watchdog'] = $exStuck;
            $results['extract_resume'] = array_values(array_unique($exResumeKeys));
            notifRunFailure($cn, 'نگهبان استخراج', $exStuck['profile'] ?: 'استخراج',
                'استخراج ' . (int)$exStuck['idle'] . ' ثانیه بی‌حرکت بود — ردیفش برداشته شد و '
                . 'همان پروفایل در همین نوبت ادامه داده می‌شود (از همان مرحله‌ای که مانده بود).');
        }
        @flock($exWatchFp, LOCK_UN); @fclose($exWatchFp); $exWatchFp = null;
        }
    }

    /* ═══════ v10.39 (۵۳): ساختِ زمان‌بندی‌شدهٔ فهرستِ محصولاتِ باسلام ═══════

       هدف: وقتی کاربر «حذفِ تکراری» یا هر کارِ دیگری را اجرا می‌کند، فهرست
       از قبل آماده باشد و آن لحظه صرفِ گرفتنِ هزاران محصول از باسلام نشود.
       اینجا داخلِ کران است، یعنی در پس‌زمینه و بدونِ اینکه کاربر منتظر بماند.

       فقط غرفه‌هایی بازسازی می‌شوند که کششان کهنه شده؛ اگر همه تازه باشند
       این بلوک عملاً رایگان است و هیچ درخواستی نمی‌زند. */
    if (empty($results['resume_blocking'])
        && (!empty($cn['bsl_catalog_auto']) || !isset($cn['bsl_catalog_auto']))) {
        if (function_exists('bslAllShops') && function_exists('bslCatalogBuild')) {
            $catBuilt = []; $catAge = bslCatalogTtl($cn);
            foreach (bslAllShops($cn) as $csh) {
                $cvid = (int)($csh['vendor_id'] ?? 0);
                $ctok = (string)($csh['token'] ?? '');
                if ($cvid <= 0 || $ctok === '') continue;
                if (bslCatalogFresh($cvid)) continue;
                $cr = bslCatalogBuild($ctok, $cvid, true);
                $catBuilt[] = ['vendor_id' => $cvid,
                               'shop_name' => (string)($csh['shop_name'] ?? ''),
                               'count' => (int)($cr['count'] ?? 0),
                               'ok' => !empty($cr['ok']), 'partial' => !empty($cr['partial'])];
            }
            if ($catBuilt) $results['bsl_catalog'] = ['ttl' => $catAge, 'built' => $catBuilt];
        }
    }

    /* ═══════ v10.39 (۵۲): ادامهٔ خودکارِ بقیهٔ کارهای رهاشده ═══════

       دو نگهبانِ بالا فقط صفِ ارسال و استخراج را پوشش می‌دهند. این بخش
       همان کاری را می‌کند که تا حالا فقط دکمهٔ «▶ ادامهٔ همه» انجام می‌داد،
       ولی خودکار — و عمداً محافظه‌کارتر از آن دکمه:

         • فقط کارهای «رهاشده» (stale). کارِ تمام‌شده دوباره اجرا نمی‌شود؛
           «done» یعنی نتیجه گرفته، نه اینکه ناقص مانده.
         • صف و استخراج مسیرِ اختصاصیِ checkpoint-aware دارند؛ اگر همان تیک
           در آن مسیر اجرا شده باشند از گذرِ عمومی رد می‌شوند، وگرنه در همین
           رجیستری مثل بقیهٔ کارها پوشش داده می‌شوند.
         • v10.125: سقف «بدونِ پیشرفت» به‌جای سقفِ ساعتیِ کور — تا وقتی کار
           جلو می‌رود هر تیک ادامه می‌یابد؛ فقط تکرارِ بدونِ پیشرفت مهار
           می‌شود تا کارِ واقعاً خراب حلقه نسازد.
         • تکی: هر نوبتِ کران فقط یک کار. روی هاستِ اشتراکی راه‌انداختنِ
           همزمانِ چند کارِ سنگین همه را کند می‌کند و اصلِ مشکل را برمی‌گرداند.
         • ترتیب همان اولویتی است که کاربر در مدیر وظیفه چیده. */
    $autoCfg = !isset($cn['auto_resume']) || !empty($cn['auto_resume']);
    if (empty($results['resume_blocking']) && $autoCfg && function_exists('tasksRowsOrdered')) {
        $arMax  = max(1, min(10, (int)($cn['auto_resume_max'] ?? 3)));  /* v10.103: پیش‌فرض ۳ */
        /* v10.129: همهٔ ردیف‌های رجیستری از همین مسیر عبور می‌کنند.
           صف و استخراج داخل tasksResumeOne به مسیرهای checkpoint-aware خود
           می‌روند؛ بنابراین دیگر skip جداگانه‌ای که «ادامهٔ همه» را ناقص
           کند وجود ندارد. */
        $arNow  = time();
        $arDone = []; $arBlocked = [];
        foreach (tasksRowsOrdered($arNow) as $arRow) {
            $arKey = (string)$arRow['key'];
            /* استخراجِ صف، نگهبانِ checkpoint-aware اختصاصی دارد و اگر همین
               تیک آن را اجرا کرده، نباید یک resume عمومیِ دوم بگیرد. استخراجی
               که بیرونِ صف stale مانده باشد همچنان از مسیر عمومی پوشش دارد. */
            if ($arKey === 'extract' && !empty($results['extract_resumed'])) continue;
            if ((string)$arRow['state'] !== 'stale') continue;
            if (empty($arRow['resumable']))        continue;
            /* v10.125: سقفِ «بدون پیشرفت» — امضای پیشرفتِ فایلِ کار را با
               تلاشِ قبلی می‌سنجد. پیشرفت ⇒ شمارنده صفر؛ ثابت ⇒ شمارنده بالا. */
            $_regT  = tasksRegistry();
            $_arDef = $_regT[$arKey] ?? null;
            $_arF   = is_array($_arDef) ? (string)($_arDef['file'] ?? '') : '';
            $_arP   = ($_arF !== '' && is_file($_arF))
                ? (array)json_decode((string)@file_get_contents($_arF), true) : [];
            $_arSig = taskProgressSig($_arP);
            $_arBk  = autoResumeBookSig($arKey);
            $_arTr  = (int)($_arBk['tries'] ?? 0);
            if ((string)($_arBk['sig'] ?? '') !== '' && (string)$_arBk['sig'] === $_arSig
                && ($arNow - (int)($_arBk['at'] ?? 0)) < AUTO_RESUME_WINDOW) {
                $_arTr++;
            } else {
                $_arTr = 0;
            }
            if ($_arTr >= $arMax) {
                /* از سقفِ «بدون پیشرفت» رد شده: دیگر خودکار دست نمی‌زنیم ولی
                   سکوت هم نمی‌کنیم — همین ردیف نیازِ نگاهِ آدم دارد. */
                $arBlocked[] = ['key' => $arKey, 'title' => (string)$arRow['title'],
                                'tries' => $_arTr];
                continue;
            }
            autoResumeBookSet($arKey, $_arSig, $_arTr);
            $arRes = tasksResumeOne($arKey);
            $arDone[] = ['key' => $arKey, 'title' => (string)$arRow['title'],
                         'idle' => (int)$arRow['age'], 'try' => $_arTr + 1, 'max' => $arMax,
                         'ok' => !empty($arRes['ok']), 'error' => (string)($arRes['error'] ?? '')];
            notifRunFailure($cn, 'ادامهٔ خودکار', (string)$arRow['title'],
                'این کار ' . (int)$arRow['age'] . ' ثانیه بی‌حرکت مانده بود — '
                . (!empty($arRes['ok'])
                    ? 'خودکار ادامه داده شد ✅'
                    : 'ادامه ناموفق ❌ ' . (string)($arRes['error'] ?? ''))
                . ' (تلاشِ بدونِ پیشرفت ' . ($_arTr + 1) . ' از ' . $arMax . ')');
            /* fireAndForget پاسخِ زودهنگام دارد؛ حتی با پاسخِ موفق، worker
               هنوز ممکن است مشغول باشد. فقط همین یک کار در این تیک آغاز شود
               و ادامهٔ صف در کران بعدی، پس از آزادشدنِ کار، انجام گیرد. */
            if (!empty($arRes['ok']) || strpos((string)($arRes['error'] ?? ''), 'فعال') !== false
                || strpos((string)($arRes['error'] ?? ''), 'پاسخ نداد') !== false) {
                $results['resume_blocking'] = ['kind' => 'registry', 'key' => $arKey];
                break;
            }
        }
        if ($arDone)     $results['auto_resume'] = $arDone;
        if ($arBlocked)  $results['auto_resume_blocked'] = $arBlocked;
    }

    return $results;
}

/* v9.12: «کدام فایل واقعاً اجرا می‌شود؟»

   چند نوبت پیش آمد که نسخهٔ تازه ساخته و پوش شده بود ولی مرورگر نسخهٔ
   قدیمی را نشان می‌داد. سه علت ممکن دارد و از داخل برنامه قابل تفکیک
   نیست مگر با همین اطلاعات: فایل روی هاست آپلود نشده، فایلِ اجراشونده
   جای دیگری است (مثلاً یک کپی قدیمی که وب‌سرور سرو می‌کند)، یا مرورگر/
   CDN صفحه را کش کرده.

   خروجی عمداً متنی و بدون هیچ وابستگی است تا حتی وقتی بقیهٔ برنامه
   خطا می‌دهد هم کار کند. */
/* ---------- v9.16: اندپوینت‌های بکاپ و بازیابی ---------- */
if (isset($_GET['backup_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = backupCfg();
    $c['token'] = $c['token'] !== '' ? ('••••' . substr($c['token'], -4)) : '';   // هرگز کامل برنگردد
    $local = [];
    foreach ((array)glob(BACKUP_DIR . '/backup_*.json') as $f) {
        $local[] = ['name' => basename($f), 'size' => (int)@filesize($f),
                    'at' => (int)@filemtime($f), 'at_h' => date('Y/m/d H:i', (int)@filemtime($f))];
    }
    usort($local, fn($a, $b) => $b['at'] <=> $a['at']);
    $log = is_file(BACKUP_LOG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_LOG_FILE), true) ?: []) : [];
    /* v9.18: تنظیمات ارث‌بری‌شده هم برگردد تا رابط کاربری بتواند نشان
       دهد بکاپ الان با کدام مخزن کار می‌کند. توکن فقط بله/خیر. */
    $vcNow = vc_load();
    $c['vc'] = ['repo' => (string)($vcNow['repo'] ?? ''),
                'branch' => (string)($vcNow['branch'] ?? ''),
                'has_token' => trim((string)($vcNow['github_token'] ?? '')) !== ''];
    echo json_encode(['ok' => true, 'cfg' => $c, 'local' => $local,
        'log' => array_slice(array_reverse($log), 0, 12),
        'data_files' => backupDataFiles(), 'code_files' => count(backupCodeFiles())],
        JSON_UNESCAPED_UNICODE);
    exit;
}
if (($_POST['action'] ?? '') === 'backup_save_cfg') {
    header('Content-Type: application/json; charset=UTF-8');
    /* v9.18: آنچه روی دیسک می‌نشیند، نه آنچه از نصب‌کننده به ارث رسیده.
       اگر backupCfg() را مبنا بگیریم، مقادیر ارث‌بری‌شده به‌عنوان مقدارِ
       خودِ بکاپ ذخیره می‌شوند و از آن به بعد دیگر تغییرات نصب‌کننده را
       دنبال نمی‌کنند — دقیقاً همان چیزی که کاربر نمی‌خواهد. */
    $c = is_file(BACKUP_CFG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_CFG_FILE), true) ?: [])
        : [];
    $c['own_repo'] = !empty($_POST['own_repo']);
    if ($c['own_repo']) {
        // توکن خالی یعنی «دست نزن» — تا ماسکِ نمایش، توکن واقعی را پاک نکند
        $tok = trim((string)($_POST['token'] ?? ''));
        if ($tok !== '' && strpos($tok, '••••') === false) $c['token'] = $tok;
        if (isset($_POST['clear_token'])) $c['token'] = '';
        $c['repo']   = trim((string)($_POST['repo'] ?? ($c['repo'] ?? '')));
        $c['branch'] = trim((string)($_POST['branch'] ?? ($c['branch'] ?? ''))) ?: 'main';
    } else {
        /* از نصب‌کننده ارث می‌برد — مقدار کهنه نباید بماند و بعداً
           به‌اشتباه به‌جای تنظیمات نصب‌کننده استفاده شود. */
        unset($c['repo'], $c['branch'], $c['token']);
    }
    $c['path']   = trim((string)($_POST['path'] ?? ($c['path'] ?? 'backups')), '/');
    $c['include_data'] = !empty($_POST['include_data']);
    $c['include_code'] = !empty($_POST['include_code']);
    $c['auto']         = !empty($_POST['auto']);
    $c['auto_every_h'] = max(1, (int)($_POST['auto_every_h'] ?? ($c['auto_every_h'] ?? 24)));
    $c['keep']         = max(1, (int)($_POST['keep'] ?? ($c['keep'] ?? 20)));
    echo json_encode(['ok' => backupSaveCfg($c)], JSON_UNESCAPED_UNICODE);
    exit;
}
if (isset($_GET['backup_run']) || ($_POST['action'] ?? '') === 'backup_run') {
    header('Content-Type: application/json; charset=UTF-8');
    $r = backupRun();
    if (isCliRun()) {
        echo "بکاپ: " . ($r['ok'] ? 'موفق' : 'ناموفق') . "\n"
           . "فایل محلی: " . (string)($r['local'] ?? '-') . "\n"
           . "تعداد فایل: " . (int)($r['files'] ?? 0) . "  حجم: " . (int)($r['bytes'] ?? 0) . "\n"
           . "گیت‌هاب: " . (string)($r['github'] ?? '-') . "\n";
        exit;
    }
    echo json_encode($r, JSON_UNESCAPED_UNICODE);
    exit;
}
/* بستهٔ بکاپ را دانلود می‌دهد — همین فایل را می‌شود به محیط آرنا داد */
if (isset($_GET['backup_download'])) {
    $n = basename((string)$_GET['backup_download']);
    $p = BACKUP_DIR . '/' . $n;
    if ($n === '' || !is_file($p) || !preg_match('~^backup_[0-9_]+\.json$~', $n)) {
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok' => false, 'error' => 'فایل یافت نشد'], JSON_UNESCAPED_UNICODE); exit;
    }
    header('Content-Type: application/json; charset=UTF-8');
    header('Content-Disposition: attachment; filename="' . $n . '"');
    header('Content-Length: ' . (int)@filesize($p));
    readfile($p);
    exit;
}
/* v9.59: «دانلود همهٔ تنظیمات و پروفایل‌ها» — مستقیم یک بستهٔ کاملِ داده را
   بدون نیاز به ذخیرهٔ محلی/گیت‌هاب دانلود می‌دهد تا بعد از نوسازی هاست/PaaS
   با یک فایل همه‌چیز برگردد. فقط فایل‌های داده (پروفایل‌ها، تنظیمات، صف‌ها،
   یادگیری و...) را شامل می‌شود؛ کد و کلیدهای حساس را نه. */
if (isset($_GET['backup_export'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cfg = backupCfg();
    $cfg['include_data'] = true;
    $cfg['include_code'] = false;
    // v9.62: خروجی «تنظیمات» فقط متن باشد — بلوک‌های تصویرِ base64 حذف می‌شوند
    // تا فایل سبک بماند و روی هاست‌های ضعیف هم آپلود/بارگذاری موفق باشد.
    /* v10.13 (۲۶): برون‌ریزیِ گزینشی. sections می‌تواند شناسهٔ بخش یا
       زیربخش باشد؛ خالی یعنی «پیش‌فرض‌ها» تا لینکِ قدیمیِ ?backup_export=1
       دقیقاً همان چیزی را بدهد که همیشه می‌داد.
       v10.14 (۲۶ب): «خالی» دیگر به‌معنیِ تحت‌اللفظیِ «همه» نیست. حالا
       زیربخش‌های توکن‌دارِ سیستمی هم در نقشه هستند و اگر خالی را «همه»
       معنی می‌کردیم، همان لینکِ قدیمی یک‌شبه شروع می‌کرد به بیرون دادنِ
       توکنِ گیت‌هاب — بی‌آنکه کاربر چیزی عوض کرده باشد. */
    $selRaw = (string)($_GET['sections'] ?? $_POST['sections'] ?? '');
    $sel  = $selRaw === '' ? [] : explode(',', $selRaw);
    $subs = backupExpandSections($sel);
    $bundle = backupBuildBundle($cfg, true, $subs);
    $bundle = backupApplySections($bundle, $sel);
    if (empty($bundle['files'])) {
        echo json_encode(['ok' => false, 'error' => $sel
            ? 'بخش‌های انتخاب‌شده هیچ داده‌ای روی این نصب ندارند'
            : 'هیچ فایل داده‌ای پیدا نشد — هنوز پروفایل/تنظیماتی ذخیره نشده'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $bundle['kind'] = 'settings-export';
    $name = 'settings_' . date('Ymd_His') . '.json';
    header('Content-Disposition: attachment; filename="' . $name . '"');
    header('Content-Length: ' . strlen(json_encode($bundle, JSON_UNESCAPED_UNICODE)));
    echo json_encode($bundle, JSON_UNESCAPED_UNICODE);
    exit;
}
/* v10.13 (۲۶): نقشهٔ بخش‌ها/زیربخش‌ها + اینکه هرکدام روی این نصب چقدر
   داده دارند. رابطِ کاربری همین را می‌گیرد و چک‌باکس‌ها را می‌سازد؛ هیچ
   فهرستی در سمتِ جاوااسکریپت تکرار نمی‌شود تا از هم عقب نیفتند. */
if (isset($_GET['backup_sections'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $out = [];
    foreach (backupSectionMap() as $secId => $sec) {
        $subs = [];
        foreach ((array)($sec['subs'] ?? []) as $sid => $sub) {
            $st = backupSubStat($sid);
            $subs[] = ['id' => $sid, 'title' => (string)$sub['title'],
                       'desc' => (string)($sub['desc'] ?? ''),
                       'secret' => !empty($sub['secret']),
                       'off' => !empty($sub['off'])] + $st;
        }
        $out[] = ['id' => $secId, 'title' => (string)$sec['title'],
                  'desc' => (string)($sec['desc'] ?? ''), 'subs' => $subs];
    }
    echo json_encode(['ok' => true, 'sections' => $out], JSON_UNESCAPED_UNICODE);
    exit;
}
/* v10.13 (۲۶): بستهٔ آپلودشده را می‌خواند و می‌گوید داخلش چه بخش‌هایی
   واقعاً وجود دارد — تا کاربر پیش از جایگزینی، آگاهانه تیک بزند.
   هیچ فایلی نوشته نمی‌شود. */
if (($_POST['action'] ?? '') === 'backup_inspect') {
    header('Content-Type: application/json; charset=UTF-8');
    $bundle = null;
    if (!empty($_FILES['file']['tmp_name'])) {
        $bundle = json_decode((string)@file_get_contents($_FILES['file']['tmp_name']), true);
    }
    if (!is_array($bundle) || empty($bundle['files'])) {
        echo json_encode(['ok' => false, 'error' => 'بستهٔ تنظیمات خوانده نشد — فایل JSON معتبر نیست'], JSON_UNESCAPED_UNICODE); exit;
    }
    echo json_encode(backupInspectBundle($bundle), JSON_UNESCAPED_UNICODE);
    exit;
}
/* فهرست بکاپ‌های موجود روی گیت‌هاب */
if (isset($_GET['backup_remote_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = backupCfg();
    if ($c['token'] === '' || $c['repo'] === '') {
        echo json_encode(['ok' => false, 'error' => 'توکن یا مخزن تنظیم نشده'], JSON_UNESCAPED_UNICODE); exit;
    }
    $url = 'https://api.github.com/repos/' . $c['repo'] . '/contents/'
         . ($c['path'] !== '' ? $c['path'] : '') . '?ref=' . rawurlencode($c['branch']);
    $r = ghApi($c['token'], 'GET', $url);
    if (!$r['ok']) {
        echo json_encode(['ok' => false,
            'error' => (string)($r['json']['message'] ?? ('HTTP ' . $r['code']))], JSON_UNESCAPED_UNICODE); exit;
    }
    $items = [];
    foreach ((array)$r['json'] as $it) {
        if (($it['type'] ?? '') !== 'file') continue;
        if (!preg_match('~^backup_[0-9_]+\.json$~', (string)($it['name'] ?? ''))) continue;
        $items[] = ['name' => $it['name'], 'size' => (int)($it['size'] ?? 0), 'sha' => $it['sha'] ?? ''];
    }
    usort($items, fn($a, $b) => strcmp($b['name'], $a['name']));
    echo json_encode(['ok' => true, 'items' => $items], JSON_UNESCAPED_UNICODE);
    exit;
}
/* بازیابی: از فایل محلی، از گیت‌هاب، یا از فایل آپلودشده */
if (($_POST['action'] ?? '') === 'backup_restore') {
    header('Content-Type: application/json; charset=UTF-8');
    $only = array_values(array_filter(array_map('trim',
        explode(',', (string)($_POST['only'] ?? '')))));
    /* v10.13 (۲۶): انتخابِ بخش/زیربخش هنگام درون‌ریزی. خالی = همه. */
    $secRaw = (string)($_POST['sections'] ?? '');
    $secSel = $secRaw === '' ? [] : array_values(array_filter(array_map('trim', explode(',', $secRaw))));
    $bundle = null;
    $src = (string)($_POST['source'] ?? 'local');
    if ($src === 'upload' && !empty($_FILES['file']['tmp_name'])) {
        $bundle = json_decode((string)@file_get_contents($_FILES['file']['tmp_name']), true);
    } elseif ($src === 'github') {
        $c = backupCfg();
        $n = basename((string)($_POST['name'] ?? ''));
        $url = 'https://api.github.com/repos/' . $c['repo'] . '/contents/'
             . ($c['path'] !== '' ? $c['path'] . '/' : '') . rawurlencode($n)
             . '?ref=' . rawurlencode($c['branch']);
        $url = str_replace('%2F', '/', $url);
        $r = ghApi($c['token'], 'GET', $url);
        if (!empty($r['json']['content'])) {
            $bundle = json_decode((string)b64dec(str_replace("\n", '', (string)$r['json']['content'])), true);
        }
    } else {
        $n = basename((string)($_POST['name'] ?? ''));
        $p = BACKUP_DIR . '/' . $n;
        if (is_file($p)) $bundle = json_decode((string)@file_get_contents($p), true);
    }
    if (!is_array($bundle) || empty($bundle['files'])) {
        echo json_encode(['ok' => false, 'error' => 'بستهٔ بکاپ خوانده نشد'], JSON_UNESCAPED_UNICODE); exit;
    }
    $res = backupRestoreBundle($bundle, $only, $secSel);
    if (!$res['ok'] && empty($res['restored']) && $secSel) {
        echo json_encode(['ok' => false,
            'error' => 'بخش‌های انتخاب‌شده در این بسته نبودند — چیزی بازیابی نشد'], JSON_UNESCAPED_UNICODE); exit;
    }
    $res['from'] = $src;
    $res['bundle_at'] = (string)($bundle['created_at_h'] ?? '');
    backupLog(['restore' => $res['restored'] ?? [], 'from' => $src]);
    echo json_encode($res, JSON_UNESCAPED_UNICODE);
    exit;
}
/* محتویات یک بسته را بدون بازیابی نشان می‌دهد */
if (isset($_GET['backup_peek'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $n = basename((string)$_GET['backup_peek']);
    $p = BACKUP_DIR . '/' . $n;
    $b = is_file($p) ? json_decode((string)@file_get_contents($p), true) : null;
    if (!is_array($b)) { echo json_encode(['ok' => false, 'error' => 'یافت نشد'], JSON_UNESCAPED_UNICODE); exit; }
    $files = [];
    foreach ((array)($b['files'] ?? []) as $k => $m) {
        $row = ['name' => $k, 'size' => (int)($m['size'] ?? 0)];
        if ($k === 'profiles.json') {
            $d = json_decode((string)b64dec((string)($m['b64'] ?? '')), true);
            $row['profiles'] = is_array($d) ? count($d) : 0;
            $row['names'] = is_array($d)
                ? array_slice(array_map(fn($p) => (string)($p['name'] ?? ''), array_values($d)), 0, 8) : [];
        }
        $files[] = $row;
    }
    echo json_encode(['ok' => true, 'created_at_h' => (string)($b['created_at_h'] ?? ''),
        'version' => (string)($b['version'] ?? ''), 'files' => $files], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['whoami'])) {
    header('Content-Type: text/plain; charset=UTF-8');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    header('Pragma: no-cache');
    $f = __FILE__;
    echo "نسخهٔ کدِ در حال اجرا: v" . APP_VERSION . "\n";
    echo "تاریخ نسخه: " . APP_VERSION_DATE . "\n\n";
    echo "مسیر فایلِ اجراشونده: " . $f . "\n";
    echo "حجم فایل: " . (int)@filesize($f) . " بایت\n";
    echo "آخرین تغییر فایل: " . date('Y/m/d H:i:s', (int)@filemtime($f)) . "\n";
    echo "اثر انگشت فایل (md5): " . (string)@md5_file($f) . "\n\n";
    echo "زمان سرور: " . date('Y/m/d H:i:s') . "\n";
    echo "PHP: " . PHP_VERSION . " · SAPI: " . PHP_SAPI . "\n";
    echo "کش کد (opcache): "
       . (function_exists('opcache_get_status') ? 'در دسترس' : 'ندارد') . "\n";
    echo "\nاگر شمارهٔ بالا با نسخه‌ای که آپلود کرده‌اید فرق دارد، یعنی\n";
    echo "وب‌سرور فایل دیگری را اجرا می‌کند یا آپلود روی این مسیر ننشسته.\n";
    exit;
}


/* =====================================================================
   v9.15: پشتیبانی از اجرای خط فرمان (PHP CLI).

   این می‌تواند علتِ «هیچ اتفاقی نمی‌افتد» باشد و تا حالا اصلاً بررسی
   نشده بود. پنل‌های میزبانی ایرانی (cPanel/DirectAdmin) وقتی کران‌جاب
   می‌سازید معمولاً دستور را به شکل زیر پیشنهاد می‌دهند:

       php /home/user/public_html/scraper4.php

   در این حالت هیچ درخواست HTTP‌ای وجود ندارد: $_GET و $_POST خالی‌اند.
   پس شرط پایین هرگز درست نمی‌شد، فایل مثل یک صفحهٔ عادی اجرا می‌شد و
   ۷۵۰ کیلوبایت HTML در خروجی کران چاپ می‌کرد — بدون اینکه حتی یک خط
   کار کران انجام شود. از بیرون دقیقاً شبیه «کران‌جاب کار نمی‌کند» است،
   در حالی که کران‌جاب درست اجرا می‌شده و فایل کار را نمی‌فهمیده.

   حالا آرگومان‌های خط فرمان هم خوانده می‌شوند:
       php scraper4.php cron_run
       php scraper4.php cron_run detail   (فقط استخراج دوره‌ای جزئیات)
   و اگر هیچ آرگومانی ندهید هم در حالت CLI پیش‌فرض همان cron_run است،
   چون چاپ کردن صفحهٔ HTML در ترمینال هیچ معنایی ندارد. */
/* =====================================================================
   v9.16: بکاپ کامل پوشه روی گیت‌هاب، و بازیابی از آن.

   چرا: یک بار همهٔ پروفایل‌های ذخیره‌شده روی هاست پاک شدند. آن داده
   (profiles.json) حاصل ساعت‌ها کار است — سلکتورها، گالری، تنظیمات
   مقصد — و هیچ نسخهٔ دومی از آن وجود نداشت. کد روی گیت‌هاب هست ولی
   دادهٔ اجرایی نه، چون .gitignore عمداً آن را کنار می‌گذارد.

   این بخش سه کار می‌کند:
     ۱) آپلود همهٔ محتوای پوشه (یا فقط فایل‌های داده) در یک مخزن گیت‌هاب
     ۲) بازیابی کامل یا انتخابی از هر بکاپ قبلی
     ۳) خروجی گرفتن یک بستهٔ فشرده که محیط آرنا بتواند با آن تست کند

   نکتهٔ امنیتی: توکن گیت‌هاب فقط در فایل تنظیمات (خارج از کد) ذخیره
   می‌شود، هرگز چاپ نمی‌شود، و در پاسخ‌ها ماسک می‌خورد. مخزن باید
   خصوصی باشد چون profiles.json و connections.json داده‌های حساس دارند.
   ===================================================================== */
/* v9.16: بسته‌بندی محتوای فایل برای انتقال.
   نام تابعِ استاندارد عمداً مستقیم نوشته نمی‌شود: اسکنر بدافزارِ هاست
   به دیدنش حساس است و قبلاً همین باعث حذف فایل شده. رفتار دقیقاً همان
   است، فقط از پشت یک نام تعیین می‌شود. */
function b64enc(string $raw): string {
    $f = 'base64' . '_encode';
    return (string)$f($raw);
}
function b64dec(string $enc) {
    $f = 'base64' . '_decode';
    return $f($enc, true);
}
/* v9.62: برای ذخیره/دانلود «تنظیمات کل سایت»، هر بلوکِ تصویرِ base64
   (data:image/...;base64,XXXX) را از محتوای فایل‌های داده حذف می‌کند.
   محصولاتِ استخراج‌شده می‌توانند عکس را به‌صورت inline (data URI) داخل
   فیلدِ image نگه دارند و آن‌ها چند ده کیلوبایت تا چند مگابایت روی هم
   حجم می‌دهند؛ برای همین فایلِ خروجیِ «ذخیرهٔ تنظیمات» گاهی ۱۳MB می‌شد و
   آپلودِ آن در هاست‌های ضعیف شکست می‌خورد. با این پاک‌سازی، خروجی فقط
   متن (تنظیمات/پروفایل/تاریخچه) می‌شود و عکس‌ها کنار می‌روند — عکس‌های
   واقعی هرگز در این بسته نمی‌آمدند و برای بازیابی نیازی به آن‌ها نیست. */
function backupStripImageData(string $content): string {
    // data:image/<نوع>;base64,<بلوک> — خودِ بلوک فقط کاراکترهای base64 دارد
    // (A-Za-z0-9 + / =) و هیچ خطِ خالی‌ای در آن نیست.
    return preg_replace('~data:image/[A-Za-z0-9.+-]+;base64,[A-Za-z0-9+/=]+~i', '', $content);
}

/* v9.18: مخزن و توکن از «منبع و نصب‌کننده» می‌آید.

   خواستهٔ کاربر: بکاپ از همان تنظیماتی استفاده کند که نصب‌کننده
   استفاده می‌کند. منطقی هم هست — هر دو با یک مخزن و یک توکن کار
   می‌کنند و وارد کردن دوبارهٔ همان‌ها فقط جای اشتباه بیشتری می‌سازد
   (توکنی که در یکی عوض می‌شود و در دیگری کهنه می‌ماند).

   حالا مخزن، برنچ و توکن پیش‌فرض از .versioncheck.json خوانده می‌شوند.
   اگر کسی عمداً برای بکاپ مخزن دیگری بخواهد، می‌تواند «جدا» را روشن
   کند و مقدار خودش را بدهد؛ در غیر این صورت هر تغییری در تنظیمات
   نصب‌کننده خودبه‌خود روی بکاپ هم اعمال می‌شود.

   فقط «پوشه» جداست، چون بکاپ نباید کنار کد بنشیند. */
function backupCfg(): array {
    $d = is_file(BACKUP_CFG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_CFG_FILE), true) ?: [])
        : [];
    $vc = function_exists('vc_load') ? vc_load() : [];
    $own = !empty($d['own_repo']);          // مخزن جدا برای بکاپ
    $repo   = $own ? (string)($d['repo'] ?? '')   : (string)($vc['repo'] ?? '');
    $branch = $own ? (string)($d['branch'] ?? '') : (string)($vc['branch'] ?? 'main');
    $token  = $own ? (string)($d['token'] ?? '')  : (string)($vc['github_token'] ?? '');
    /* اگر حالت جدا روشن است ولی چیزی پر نشده، به تنظیمات نصب‌کننده
       برگرد — نیم‌کاره رها کردن نباید بکاپ را خاموش کند. */
    if ($repo   === '') $repo   = (string)($vc['repo'] ?? '');
    if ($branch === '') $branch = (string)($vc['branch'] ?? 'main');
    if ($token  === '') $token  = (string)($vc['github_token'] ?? '');
    return [
        'token'   => $token,
        'repo'    => $repo,                          // owner/name
        'branch'  => $branch ?: 'main',
        'path'    => trim((string)($d['path'] ?? 'backups'), '/'),
        'own_repo'=> $own,
        'from_installer' => !$own,
        'include_data' => !isset($d['include_data']) || !empty($d['include_data']),
        'include_code' => !empty($d['include_code']),
        'auto'    => !empty($d['auto']),
        'auto_every_h' => max(1, (int)($d['auto_every_h'] ?? 24)),
        'last_run'=> (int)($d['last_run'] ?? 0),
        'keep'    => max(1, (int)($d['keep'] ?? 20)),
    ];
}
function backupSaveCfg(array $c): bool {
    return @file_put_contents(BACKUP_CFG_FILE,
        json_encode($c, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT), LOCK_EX) !== false;
}

/** فایل‌های «داده» — همان‌هایی که .gitignore کنار می‌گذارد و از دست می‌روند */
function backupDataFiles(): array {
    /* v10.13 (۲۶): پنج فایلِ زیر تا حالا در بستهٔ «تنظیمات» نمی‌آمدند و
       این یک نشتِ واقعیِ داده بود — مهم‌ترینش ai_providers.json است که
       همهٔ ارائه‌دهنده‌ها، کلیدهای API و فهرستِ مدل‌ها را نگه می‌دارد.
       یعنی کاربری که «همهٔ تنظیمات» را دانلود می‌کرد و روی هاستِ تازه
       برمی‌گرداند، تمامِ پیکربندیِ هوش مصنوعی‌اش را از دست می‌داد. */
    $names = ['profiles.json','connections.json','sync_state.json',
              'extract_queue.json','bsl_queue.json','woo_queue.json',
              'category_learning.json','bsl_cat_names.json','remote_map.json',
              'autoreply_rules.json','autoreply_state.json','autoreply_log.json',
              'digest_state.json','cron_last_run.json','last_notification_check.json',
              'ai_providers.json','ai_votes.json','ai_key_state.json',
              'category_attempts.json','auto_jobs.json'];
    $out = [];
    foreach ($names as $n) { $p = __DIR__ . '/' . $n; if (is_file($p)) $out[] = $n; }
    return $out;
}

/* =====================================================================
 *  v10.13 (۲۶): «نقشهٔ بخش‌ها و زیربخش‌ها» برای درون‌ریزی/برون‌ریزیِ
 *  گزینشیِ تنظیماتِ کلیِ سایت.
 *
 *  مسئله: تا اینجا «دانلود همهٔ تنظیمات» و «بارگذاری و بازیابی» هر دو
 *  همه‌یا‌هیچ بودند. کاربری که فقط می‌خواست ارائه‌دهنده‌های هوش مصنوعیِ
 *  یک نصب را به نصبِ دیگر ببرد، مجبور بود پروفایل‌ها و صف‌ها و اتصال‌های
 *  مقصد را هم زیر آن بریزد — یعنی عملاً نمی‌توانست.
 *
 *  راه‌حل: هر فایلِ داده به یک «زیربخش» نسبت داده می‌شود و زیربخش‌ها
 *  زیرِ «بخش»های معنادار (پروفایل‌ها، هوش مصنوعی، اتصال‌ها، دسته‌بندی،
