                /* v10.14: پیش‌فرض خاموش. تا نسخهٔ قبل توکنِ گیت‌هاب اصلاً
                   در فایلِ خروجی نبود؛ اگر حالا بی‌صدا تیک‌خورده باشد،
                   هرکس فایلِ تنظیماتش را برای عیب‌یابی به دیگری بدهد
                   توکنش را هم داده است. تیک‌زدنش با خودِ کاربر. */
                'sys_update' => [
                    'title' => 'به‌روزرسانی و مخزنِ گیت‌هاب',
                    'desc'  => '⚠️ شاملِ توکنِ گیت‌هاب و توکنِ deploy — پیش‌فرض خاموش',
                    'files' => ['.versioncheck.json'], 'secret' => true, 'off' => true,
                ],
                'sys_backupcfg' => [
                    'title' => 'زمان‌بندی و مقصدِ بکاپِ خودکار',
                    'desc'  => '⚠️ شاملِ توکنِ مخزنِ بکاپ و دورهٔ اجرا — پیش‌فرض خاموش',
                    'files' => ['.backup-config.json'], 'secret' => true, 'off' => true,
                ],
                'sys_backuplog' => [
                    'title' => 'گزارشِ بکاپ‌ها',
                    'desc'  => 'تاریخچهٔ اجرا — برای انتقال معمولاً لازم نیست',
                    'files' => ['.backup-log.json'], 'off' => true,
                ],
            ],
        ],
        'automation' => [
            'title' => '⏱ اتوماسیون و کران',
            'desc'  => 'کارهای زمان‌بندی‌شده و نشانه‌های زمانیِ اجرا',
            'subs'  => [
                'auto_jobs'  => ['title' => 'کارهای زمان‌بندی‌شده', 'desc' => 'تعریفِ کارهای خودکارِ ایجنتی', 'files' => ['auto_jobs.json']],
                'auto_stamp' => [
                    'title' => 'نشانه‌های زمانیِ اجرا',
                    'desc'  => 'آخرین اجرای کران، آخرین بررسیِ اعلان و خلاصهٔ روزانه',
                    'files' => ['cron_last_run.json', 'last_notification_check.json', 'digest_state.json'],
                ],
            ],
        ],
    ];
}

/**
 * v10.14: زیربخش‌هایی که پیش‌فرض روشن‌اند — یعنی همان چیزی که تا نسخهٔ
 * قبل در بستهٔ «همهٔ تنظیمات» می‌آمد. زیربخش‌های نشان‌دارِ off (توکن‌دار
 * یا صرفاً تاریخچه) باید آگاهانه تیک بخورند.
 */
function backupDefaultSubIds(): array {
    $out = [];
    foreach (backupSectionMap() as $sec) {
        foreach ((array)($sec['subs'] ?? []) as $sid => $sub) {
            if (empty($sub['off'])) $out[] = $sid;
        }
    }
    return $out;
}

/** فهرستِ شناسهٔ همهٔ زیربخش‌ها، به ترتیبِ نقشه */
function backupAllSubIds(): array {
    $out = [];
    foreach (backupSectionMap() as $sec) {
        foreach ((array)($sec['subs'] ?? []) as $sid => $_) $out[] = $sid;
    }
    return $out;
}

/**
 * ورودیِ کاربر می‌تواند شناسهٔ «بخش» یا «زیربخش» باشد؛ خروجی همیشه
 * فهرستِ زیربخش‌هاست. فهرستِ خالی یعنی «همه» — تا رفتارِ نسخه‌های قبل
 * (که اصلاً پارامتری نمی‌فرستادند) عیناً حفظ شود.
 */
function backupExpandSections(array $sel): array {
    $sel = array_values(array_filter(array_map('trim', $sel), fn($v) => $v !== ''));
    /* v10.14: خالی ⇒ پیش‌فرض‌ها (نه تحت‌اللفظیِ «همه»). زیربخش‌های
       نشان‌دارِ off توکن دارند و نباید بدونِ تیکِ صریح راه بیفتند. */
    if (!$sel) return backupDefaultSubIds();
    $map = backupSectionMap();
    $out = [];
    foreach ($sel as $id) {
        if (isset($map[$id])) {
            foreach ((array)($map[$id]['subs'] ?? []) as $sid => $_) $out[] = $sid;
            continue;
        }
        foreach ($map as $sec) {
            if (isset($sec['subs'][$id])) { $out[] = $id; break; }
        }
    }
    return array_values(array_unique($out));
}

/** تعریفِ یک زیربخش را برمی‌گرداند (یا null) */
function backupSubDef(string $subId): ?array {
    foreach (backupSectionMap() as $sec) {
        if (isset($sec['subs'][$subId])) return $sec['subs'][$subId];
    }
    return null;
}

/** فایل‌هایی که این مجموعه زیربخش لمس می‌کنند */
function backupSubsFiles(array $subs): array {
    $out = [];
    foreach ($subs as $sid) {
        $d = backupSubDef($sid);
        if (!$d) continue;
        if (!empty($d['file']))  $out[] = (string)$d['file'];
        foreach ((array)($d['files'] ?? []) as $f) $out[] = (string)$f;
    }
    return array_values(array_unique($out));
}

/**
 * برشِ profiles.json: هر پروفایل یک نگاشت است و کلیدهای products/
 * productsOrder را یا نگه می‌داریم یا دور می‌ریزیم.
 * $mode = 'only' (فقط همان کلیدها) یا 'omit' (همه‌چیز جز آن‌ها).
 */
function backupSliceEntries($data, string $mode, array $keys) {
    if (!is_array($data)) return $data;
    $out = [];
    foreach ($data as $k => $entry) {
        if (!is_array($entry)) { if ($mode === 'omit') $out[$k] = $entry; continue; }
        $row = [];
        foreach ($entry as $ek => $ev) {
            $hit = in_array((string)$ek, $keys, true);
            if (($mode === 'only' && $hit) || ($mode === 'omit' && !$hit)) $row[$ek] = $ev;
        }
        /* در حالتِ only، رکوردی که همهٔ مقادیرِ برش‌خورده‌اش خالی است
           اصلاً وارد بسته نمی‌شود. اگر وارد می‌شد، بازیابی «محصولات» از
           بسته‌ای که پروفایلش هیچ محصولی نداشت، محصولاتِ مقصد را با
           آرایهٔ خالی پاک می‌کرد — یعنی دقیقاً برعکسِ خواستهٔ کاربر. */
        if ($mode === 'omit') { $out[$k] = $row; continue; }
        foreach ($row as $rv) { if ($rv !== [] && $rv !== null && $rv !== '') { $out[$k] = $row; break; } }
    }
    return $out;
}

/**
 * محتوای یک فایل را بر اساسِ زیربخش‌های انتخاب‌شده فیلتر می‌کند.
 * خروجیِ null یعنی «این فایل اصلاً انتخاب نشده».
 */
function backupFilterFileContent(string $file, string $content, array $subs) {
    $whole = false; $slices = [];
    foreach ($subs as $sid) {
        $d = backupSubDef($sid);
        if (!$d) continue;
        if (in_array($file, (array)($d['files'] ?? []), true)) { $whole = true; continue; }
        if ((string)($d['file'] ?? '') === $file) $slices[] = $d;
    }
    if ($whole) return $content;
    if (!$slices) return null;
    $data = json_decode($content, true);
    if (!is_array($data)) return $content;   // نمی‌شناسیمش ⇒ دست‌نخورده
    /* اگر هر دو برشِ یک فایل انتخاب شده‌اند، یعنی کلِ فایل */
    $modes = array_map(fn($d) => (string)($d['slice'] ?? ''), $slices);
    if (in_array('only', $modes, true) && in_array('omit', $modes, true)) return $content;
    $d = $slices[0];
    $sliced = backupSliceEntries($data, (string)($d['slice'] ?? 'omit'), (array)($d['keys'] ?? []));
    return (string)json_encode($sliced, JSON_UNESCAPED_UNICODE);
}

/**
 * بستهٔ ساخته‌شده را به بخش‌های انتخابی می‌برد: فایل‌های خارج از انتخاب
 * حذف و فایل‌های نیمه‌انتخاب‌شده برش داده می‌شوند.
 */
function backupApplySections(array $bundle, array $sel): array {
    $subs = backupExpandSections($sel);
    $all  = backupAllSubIds();
    $cmp  = $subs; sort($cmp); sort($all);
    /* v10.14: میان‌برِ «همه ⇒ دست نزن» فقط وقتی درست است که واقعاً همهٔ
       زیربخش‌ها تیک خورده باشند. با انتخابِ پیش‌فرض باید فیلتر اجرا شود،
       وگرنه فایلِ سیستمیِ تیک‌نخورده در بسته می‌ماند. */
    if ($cmp === $all) return $bundle;
    $files = []; $bytes = 0;
    foreach ((array)($bundle['files'] ?? []) as $name => $meta) {
        $raw = b64dec((string)($meta['b64'] ?? ''));
        if ($raw === false) continue;
        $f = backupFilterFileContent((string)$name, (string)$raw, $subs);
        if ($f === null) continue;
        $bytes += strlen($f);
        $files[$name] = ['size' => strlen($f), 'b64' => b64enc($f)];
    }
    $bundle['files'] = $files;
    $bundle['total_files'] = count($files);
    $bundle['total_bytes'] = $bytes;
    $bundle['sections'] = array_values($subs);
    return $bundle;
}

/**
 * v10.13 (۲۶): بستهٔ آمادهٔ درون‌ریزی را می‌کاود و می‌گوید داخلش چه
 * بخش‌هایی واقعاً هست — تا کاربر پیش از جایگزینی آگاهانه تیک بزند.
 * هیچ فایلی نوشته نمی‌شود.
 */
function backupInspectBundle(array $bundle): array {
    $have = [];
    foreach ((array)($bundle['files'] ?? []) as $n => $m) $have[basename((string)$n)] = (int)($m['size'] ?? 0);
    $out = [];
    foreach (backupSectionMap() as $secId => $sec) {
        $subs = [];
        foreach ((array)($sec['subs'] ?? []) as $sid => $sub) {
            $files = !empty($sub['file']) ? [(string)$sub['file']] : (array)($sub['files'] ?? []);
            $bytes = 0; $in = false; $count = 0;
            foreach ($files as $f) {
                if (!isset($have[$f])) continue;
                $in = true;
                $raw = (string)b64dec((string)($bundle['files'][$f]['b64'] ?? ''));
                if (!empty($sub['slice'])) {
                    $cut = backupFilterFileContent($f, $raw, [$sid]);
                    $raw = $cut === null ? '' : (string)$cut;
                }
                $bytes += strlen($raw);
                $j = json_decode($raw, true);
                if (is_array($j)) {
                    if ($sid === 'profiles_products') {
                        foreach ($j as $e) $count += is_array($e) ? count((array)($e['products'] ?? [])) : 0;
                    } else { $count += count($j); }
                }
            }
            /* برشِ خالی (بسته پروفایل دارد ولی هیچ محصولی داخلش نیست)
               نباید «موجود» شمرده شود، وگرنه کاربر تیک می‌زند و انتظارِ
               بازگشتِ چیزی را دارد که اصلاً در بسته نبوده. */
            if ($in && !empty($sub['slice']) && $count === 0) $in = false;
            $subs[] = ['id' => $sid, 'title' => (string)$sub['title'],
                       'desc' => (string)($sub['desc'] ?? ''),
                       'secret' => !empty($sub['secret']),
                       'off' => !empty($sub['off']),
                       'exists' => $in, 'bytes' => $bytes, 'count' => $count];
        }
        $out[] = ['id' => $secId, 'title' => (string)$sec['title'],
                  'desc' => (string)($sec['desc'] ?? ''), 'subs' => $subs];
    }
    return ['ok' => true, 'sections' => $out,
        'created_at_h' => (string)($bundle['created_at_h'] ?? ''),
        'version' => (string)($bundle['version'] ?? ''),
        'kind' => (string)($bundle['kind'] ?? ''),
        'total_files' => count($have)];
}

/** چند رکورد داخل هر فایلِ داده هست — برای نمایش کنارِ هر زیربخش */
function backupSubStat(string $subId): array {
    $d = backupSubDef($subId);
    if (!$d) return ['exists' => false, 'bytes' => 0, 'count' => 0];
    $files = !empty($d['file']) ? [(string)$d['file']] : (array)($d['files'] ?? []);
    $bytes = 0; $count = 0; $exists = false;
    foreach ($files as $f) {
        $p = __DIR__ . '/' . $f;
        if (!is_file($p)) continue;
        $exists = true;
        $raw = (string)@file_get_contents($p);
        if ($f === 'profiles.json' && !empty($d['slice'])) {
            $raw = (string)backupFilterFileContent($f, $raw, [$subId]);
        }
        $bytes += strlen($raw);
        $j = json_decode($raw, true);
        if (is_array($j)) {
            if ($subId === 'profiles_products') {
                foreach ($j as $e) $count += is_array($e) ? count((array)($e['products'] ?? [])) : 0;
            } else {
                $count += count($j);
            }
        }
    }
    return ['exists' => $exists, 'bytes' => $bytes, 'count' => $count];
}
/** فایل‌های کد و مستندات همین پوشه (بدون زیرپوشه‌های سنگین و بدون رازها) */
function backupCodeFiles(): array {
    $out = [];
    foreach ((array)@scandir(__DIR__) as $f) {
        if ($f === '.' || $f === '..') continue;
        $p = __DIR__ . '/' . $f;
        if (!is_file($p)) continue;
        if ($f[0] === '.') continue;                       // .backup-config.json و امثالش
        if (preg_match('~\.(log|lock)$~i', $f)) continue;
        if (in_array($f, backupDataFiles(), true)) continue;
        if (@filesize($p) > 8 * 1024 * 1024) continue;     // فایل غول‌پیکر نه
        $out[] = $f;
    }
    return $out;
}
/**
 * v10.14 (۲۶ب): «تنظیماتِ سیستمی» — سه فایلِ پیکربندیِ سطحِ نصب. اسمشان
 * با نقطه شروع می‌شود و backupCodeFiles() صراحتاً ردشان می‌کند
 * ($f[0] === '.')، پس تا این نسخه در هیچ مسیری بکاپ نمی‌شدند: نه
 * به‌عنوان داده، نه به‌عنوان کد. یعنی با نوسازیِ هاست، مخزن و برنچ و
 * توکن و کلِ زمان‌بندیِ بکاپ از بین می‌رفت و باید دستی بازساخته می‌شد.
 *
 * عمداً در backupDataFiles() نیست: آن فهرست را backupRun() می‌خورد و
 * بی‌سروصدا روی گیت‌هاب پوش می‌کند. اگر اینجا می‌گذاشتیمش، توکنِ گیت‌هاب
 * خودبه‌خود داخلِ مخزنِ بکاپ می‌نشست. فقط با تیکِ صریح سفر می‌کند.
 */
function backupSystemFiles(): array {
    return ['.versioncheck.json', '.backup-config.json', '.backup-log.json'];
}

/** آیا این نام یکی از فایل‌های سیستمیِ توکن‌دار است؟ */
function backupIsSecretFile(string $name): bool {
    return in_array($name, ['.versioncheck.json', '.backup-config.json'], true);
}

function backupFileList(array $cfg, array $subs = []): array {
    $list = [];
    if (!empty($cfg['include_data'])) $list = array_merge($list, backupDataFiles());
    if (!empty($cfg['include_code'])) $list = array_merge($list, backupCodeFiles());
    /* فایل‌های سیستمی فقط وقتی که زیربخششان صراحتاً انتخاب شده باشد */
    foreach ($subs as $sid) {
        $d = backupSubDef((string)$sid);
        if (!$d) continue;
        foreach ((array)($d['files'] ?? []) as $f) {
            if (in_array($f, backupSystemFiles(), true)) $list[] = $f;
        }
    }
    return array_values(array_unique($list));
}

/** درخواست به API گیت‌هاب */
function ghApi(string $token, string $method, string $url, ?array $body = null): array {
    $ch = curl_init($url);
    $hdr = ['Accept: application/vnd.github+json',
            'User-Agent: scraper-backup',
            'X-GitHub-Api-Version: 2022-11-28'];
    if ($token !== '') $hdr[] = 'Authorization: Bearer ' . $token;
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => 1, CURLOPT_CUSTOMREQUEST => $method,
        CURLOPT_HTTPHEADER => $hdr, CURLOPT_TIMEOUT => 45,
        CURLOPT_CONNECTTIMEOUT => 15, CURLOPT_SSL_VERIFYPEER => 0,
        CURLOPT_SSL_VERIFYHOST => 0,
    ]);
    if ($body !== null) curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($body, JSON_UNESCAPED_UNICODE));
    $raw = curl_exec($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $err = curl_error($ch);
    curl_close($ch);
    $j = json_decode((string)$raw, true);
    return ['ok' => $code >= 200 && $code < 300, 'code' => $code,
            'json' => is_array($j) ? $j : [], 'raw' => (string)$raw, 'error' => $err];
}

/** یک بستهٔ بکاپ می‌سازد: همهٔ فایل‌ها به‌صورت base64 داخل یک JSON */
function backupBuildBundle(array $cfg, bool $stripImages = false, array $subs = []): array {
    $files = backupFileList($cfg, $subs);
    $bundle = ['app' => 'scraper', 'version' => APP_VERSION,
               'created_at' => time(), 'created_at_h' => date('Y/m/d H:i:s'),
               'host' => (string)($_SERVER['HTTP_HOST'] ?? 'cli'),
               'files' => []];
    $bytes = 0;
    foreach ($files as $f) {
        $p = __DIR__ . '/' . $f;
        $c = @file_get_contents($p);
        if ($c === false) continue;
        // v9.62: حالتِ «فقط متن» — بلوک‌های تصویرِ base64 را حذف کن
        if ($stripImages) {
            $stripped = backupStripImageData($c);
            if ($stripped !== $c) { $c = $stripped; $bundle['stripped_images'] = true; }
        }
        $bytes += strlen($c);
        $bundle['files'][$f] = ['size' => strlen($c), 'b64' => b64enc($c)];
    }
    $bundle['total_files'] = count($bundle['files']);
    $bundle['total_bytes'] = $bytes;
    return $bundle;
}

/** بکاپ محلی (همیشه، حتی وقتی گیت‌هاب تنظیم نشده) */
function backupWriteLocal(array $bundle): string {
    if (!is_dir(BACKUP_DIR)) @mkdir(BACKUP_DIR, 0775, true);
    $name = 'backup_' . date('Ymd_His') . '.json';
    @file_put_contents(BACKUP_DIR . '/' . $name,
        json_encode($bundle, JSON_UNESCAPED_UNICODE), LOCK_EX);
    // نگه‌داشتن فقط چند نسخهٔ آخر
    $all = glob(BACKUP_DIR . '/backup_*.json') ?: [];
    sort($all);
    $keep = max(1, (int)(backupCfg()['keep'] ?? 20));
    while (count($all) > $keep) { @unlink(array_shift($all)); }
    return $name;
}

/** آپلود بسته روی گیت‌هاب */
function backupPushGithub(array $cfg, array $bundle, string $name): array {
    if ($cfg['token'] === '' || $cfg['repo'] === '')
        return ['ok' => false, 'error' => 'توکن یا مخزن تنظیم نشده'];
    $path = ($cfg['path'] !== '' ? $cfg['path'] . '/' : '') . $name;
    $url  = 'https://api.github.com/repos/' . $cfg['repo'] . '/contents/' . rawurlencode($path);
    $url  = str_replace('%2F', '/', $url);
    // اگر فایل هست، sha لازم است
    $cur = ghApi($cfg['token'], 'GET', $url . '?ref=' . rawurlencode($cfg['branch']));
    $body = ['message' => 'backup ' . $bundle['created_at_h'] . ' (v' . APP_VERSION . ')',
             'content' => b64enc(json_encode($bundle, JSON_UNESCAPED_UNICODE)),
             'branch'  => $cfg['branch']];
    if (!empty($cur['json']['sha'])) $body['sha'] = $cur['json']['sha'];
    $r = ghApi($cfg['token'], 'PUT', $url, $body);
    if (!$r['ok']) {
        $msg = (string)($r['json']['message'] ?? $r['error'] ?? ('HTTP ' . $r['code']));
        return ['ok' => false, 'error' => $msg, 'code' => $r['code']];
    }
    return ['ok' => true, 'path' => $path,
            'html_url' => (string)($r['json']['content']['html_url'] ?? '')];
}

function backupLog(array $row): void {
    $log = is_file(BACKUP_LOG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_LOG_FILE), true) ?: []) : [];
    $log[] = $row + ['at' => time(), 'at_h' => date('Y/m/d H:i:s')];
    if (count($log) > 50) $log = array_slice($log, -50);
    @file_put_contents(BACKUP_LOG_FILE, json_encode($log, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/** اجرای کامل یک بکاپ */
function backupRun(?array $cfg = null): array {
    $cfg = $cfg ?? backupCfg();
    $bundle = backupBuildBundle($cfg);
    if (empty($bundle['files'])) {
        $res = ['ok' => false, 'error' => 'هیچ فایلی برای بکاپ انتخاب نشده'];
        backupLog($res); return $res;
    }
    $local = backupWriteLocal($bundle);
    $res = ['ok' => true, 'local' => $local,
            'files' => $bundle['total_files'], 'bytes' => $bundle['total_bytes']];
    if ($cfg['token'] !== '' && $cfg['repo'] !== '') {
        $gh = backupPushGithub($cfg, $bundle, $local);
        $res['github'] = $gh['ok'] ? 'ok' : ('failed: ' . (string)($gh['error'] ?? '?'));
        if (!empty($gh['html_url'])) $res['url'] = $gh['html_url'];
        if (!$gh['ok']) $res['ok'] = false;
    } else {
        $res['github'] = 'skipped';
    }
    $c = backupCfg(); $c['last_run'] = time(); backupSaveCfg($c);
    backupLog($res);
    return $res;
}

/** بازیابی از یک بسته */
function backupRestoreBundle(array $bundle, array $only = [], array $sections = []): array {
    /* v10.13 (۲۶): درون‌ریزیِ گزینشی.
       $only  — فهرستِ نامِ فایل (رفتار قدیمی، دست‌نخورده)
       $sections — شناسهٔ بخش/زیربخش. خالی یعنی همه.

       نکتهٔ ظریف: وقتی فقط یکی از دو برشِ profiles.json انتخاب شده،
       نوشتنِ فایل به‌صورت کامل یعنی نابود کردنِ برشِ دیگر. مثلاً کاربری
       که فقط «تنظیماتِ پروفایل‌ها» را برمی‌گرداند، انتظار ندارد محصولاتِ
       فعلی‌اش پاک شوند. برای همین برشِ انتخاب‌شده با فایلِ روی دیسک
       ادغام می‌شود، نه جایگزینِ آن. */
    $subs = $sections ? backupExpandSections($sections) : [];
    $done = []; $skipped = []; $merged = [];
    foreach ((array)($bundle['files'] ?? []) as $name => $meta) {
        $safe = basename((string)$name);
        if ($safe === '' || $safe !== $name) { $skipped[] = $name; continue; }
        if ($only && !in_array($safe, $only, true)) continue;
        /* v10.14: فایلِ سیستمی فقط با انتخابِ صریح بازیابی می‌شود.
           انتخابِ خالی یعنی «هرچه در بسته هست» و اگر استثنا نمی‌گذاشتیم،
           بازیابیِ یک بستهٔ توکن‌دار روی هاستِ مقصد، مخزن و زمان‌بندیِ
           بکاپِ خودِ آن هاست را هم بی‌خبر بازنویسی می‌کرد. */
        if (!$subs && in_array($safe, backupSystemFiles(), true)) { $skipped[] = $safe; continue; }
        $data = b64dec((string)($meta['b64'] ?? ''));
        if ($data === false) { $skipped[] = $safe; continue; }
        $dst = __DIR__ . '/' . $safe;
        if ($subs) {
            $cut = backupFilterFileContent($safe, (string)$data, $subs);
            if ($cut === null) continue;                       // این فایل انتخاب نشده
            if ($cut !== (string)$data) {
                // برشِ ناقص ⇒ باید با محتوای فعلی ادغام شود
                $data = backupMergeSlice($dst, (string)$cut);
                $merged[] = $safe;
            } else { $data = $cut; }
        }
        // نسخهٔ فعلی کنار گذاشته شود تا بازیابیِ اشتباه هم برگشت‌پذیر باشد
        if (is_file($dst)) @copy($dst, $dst . '.before-restore');
        if (@file_put_contents($dst, $data, LOCK_EX) !== false) {
            /* v10.14: فایل‌های سیستمیِ توکن‌دار با 0600 نوشته می‌شوند —
               دقیقاً مثل vc_save(). بدونِ این، بازیابی توکن را با مجوزِ
               پیش‌فرض روی دیسک می‌گذاشت و برای بقیهٔ کاربرانِ هاست
               خواندنی می‌شد. */
            if (backupIsSecretFile($safe)) @chmod($dst, 0600);
            $done[] = $safe;
        }
        else $skipped[] = $safe;
    }
    $res = ['ok' => !empty($done), 'restored' => $done, 'skipped' => $skipped];
    if ($subs)   $res['sections'] = array_values($subs);
    if ($merged) $res['merged'] = array_values(array_unique($merged));
    return $res;
}

/**
 * v10.13 (۲۶): برشِ تازه را روی محتوای فعلیِ فایل می‌نشاند.
 * فقط کلیدهایی که در برش آمده‌اند عوض می‌شوند؛ بقیهٔ کلیدهای هر رکورد
 * (و رکوردهایی که اصلاً در برش نیستند) دست‌نخورده می‌مانند.
 */
function backupMergeSlice(string $dstPath, string $sliceJson): string {
    $slice = json_decode($sliceJson, true);
    if (!is_array($slice)) return $sliceJson;
    $cur = is_file($dstPath) ? json_decode((string)@file_get_contents($dstPath), true) : [];
    if (!is_array($cur)) $cur = [];
    foreach ($slice as $k => $row) {
        if (!is_array($row) || !is_array($cur[$k] ?? null)) { $cur[$k] = $row; continue; }
        /* array_merge کلیدهای عددی را از نو شماره‌گذاری می‌کند و رکوردِ
           پروفایل را خراب می‌کند؛ حلقهٔ صریح امن‌تر است. */
        foreach ($row as $ck => $cv) $cur[$k][$ck] = $cv;
    }
    return (string)json_encode($cur, JSON_UNESCAPED_UNICODE);
}

if (isCliRun()) {
    /* $argv در همهٔ پیکربندی‌ها تعریف نمی‌شود (register_argc_argv=Off)،
       پس $_SERVER['argv'] هم بررسی می‌شود. */
    $_cliArgv = (array)($GLOBALS['argv'] ?? $_SERVER['argv'] ?? []);
    $_cliArgs = array_slice($_cliArgv, 1);
    $_cliCmd  = strtolower(trim((string)($_cliArgs[0] ?? 'cron_run')));
    $_cliCmd  = preg_replace('~^-+~', '', $_cliCmd);          // --cron_run هم قبول
    $_cliCmd  = ltrim($_cliCmd, '?');                          // ?cron_run هم قبول
    if ($_cliCmd === '' || $_cliCmd === 'cron' || $_cliCmd === 'cron_run') {
        $_GET['cron_run'] = '1';
    } elseif ($_cliCmd === 'whoami') {
        $_GET['whoami'] = '1';
    } elseif ($_cliCmd === 'backup') {
        $_GET['backup_run'] = '1';                 // php scraper4.php backup
    } else {
        $_GET['cron_run'] = '1';
    }
}

/* =====================================================================
 *  v10.35 (۴۷ه): «همگام‌سازیِ دستی» — یک دکمه، کلِ زنجیره
 *
 *  ?manual_sync=1&profile=<key>[&force=1]
 *
 *  کاری که می‌کند: پرچمِ کار را می‌گذارد و بعد دقیقاً همان چرخهٔ کران را
 *  اجرا می‌کند (استخراج ⇒ بازنشستگی ⇒ صف‌سازی ⇒ ارسال ⇒ گزارش). چون از
 *  همان مسیر رد می‌شود، هر بهبودی که به کران داده شود خودبه‌خود اینجا هم
 *  هست و هیچ‌وقت دو رفتارِ متفاوت پیدا نمی‌کنند.
 *
 *  ?manual_sync_stop=1 سیگنالِ توقف می‌گذارد؛ حلقه بینِ دو پروفایل و
 *  ارسال‌کننده‌ها در اولین بررسی می‌ایستند.
 * ===================================================================== */
if (isset($_GET['manual_sync_stop'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @file_put_contents(MANUAL_SYNC_STOP_FILE, json_encode(['at' => time()]));
    /* v10.55 (۶۹): توقفِ دستی باید به پردازنده‌هایِ در حالِ اجرایِ ارسال/استخراج
       هم برسد — آن‌ها فقط سیگنالِ توقفِ خودشان را می‌بینند. بدونِ این، «توقف»
       فقط زنجیرهٔ میانِ دو نوبت را می‌ایستاند و ردیفِ در حالِ ارسال تا آخر
       (و با v10.53 ردیف‌های بعدیِ صف هم!) فرستاده می‌شد. */
    @file_put_contents(BSL_STOP_FILE, json_encode(['stop' => true, 'time' => time()], LOCK_EX));
    @file_put_contents(WOO_STOP_FILE, json_encode(['stop' => true, 'time' => time()], LOCK_EX));
    @file_put_contents(EXTRACT_STOP_FILE, json_encode(['stop' => true, 'time' => time()], LOCK_EX));
    echo json_encode(['ok' => true, 'stopped' => true], JSON_UNESCAPED_UNICODE);
    exit;
}
if (isset($_GET['manual_sync_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $msSt = readProgress(MANUAL_SYNC_PROGRESS_FILE);
    /* v10.58 (۷۲): اجرایِ دستیِ کشته‌شدهٔ هاست، فایل را تا ابد «در حال
       اجرا» جا می‌گذارد — رابط روی همان تصویر می‌ماند، دکمه می‌گوید
       «شغال»، و از دید کاربر «اصلاً کار نمی‌کند». همین‌جا همان معیارِ
       زنده‌بودنِ نگهبان اعمال می‌شود: اگر پیشرفت بیش از stall_after بی‌حرکت
       باشد، آن اجرا مرده است. با پیامِ روشن بسته می‌شود تا رابط برگردد و
       کاربر دوباره امتحان کند — بخشِ انجام‌شده روی دیسک است و
       چک‌پوینت جلوی تکرارِ کار را می‌گیرد. */
    if (!empty($msSt['running']) && empty($msSt['done'])) {
        $msIdleD = time() - (int)($msSt['last_progress_ts'] ?? ($msSt['ts'] ?? 0));
        $msMaxD  = max(120, (int)(loadConnections()['stall_after'] ?? 300));
        if ($msIdleD > $msMaxD) {
            $msSt['running']   = false;
            $msSt['done']      = true;
            $msSt['cancelled'] = false;
            $msSt['partial'] = true; $msSt['resumable'] = true; $msSt['stale'] = true;
            if (!is_array($msSt['checkpoint'] ?? null)) $msSt['checkpoint'] = [];
            $msSt['phase']     = 'نیمه‌کاره ماند';
            $msSt['error']     = 'اجرا نیمه‌کاره رها شد (' . $msIdleD . ' ثانیه بی‌حرکت) — احتمالاً هاست پردازه را قطع کرده. بخشِ انجام‌شده روی دیسک است؛ دوباره اجرا کنید تا از چک‌پوینت ادامه دهد.';
            $msLgD = is_array($msSt['recent_log'] ?? null) ? $msSt['recent_log'] : [];
            $msLgD[] = '⚠️ اجرایِ قبلی نیمه‌کاره ماند — وضعیت به‌صورتِ خودکار به‌روزرسانی شد. می‌توانید دوباره امتحان کنید.';
            $msSt['recent_log'] = array_slice($msLgD, -40);
            $msSt['ts'] = time();
            $msSt['last_progress_ts'] = time();
            writeProgress(MANUAL_SYNC_PROGRESS_FILE, $msSt);
        }
    }
    echo json_encode(['ok' => true, 'progress' => $msSt], JSON_UNESCAPED_UNICODE);
    exit;
}
if (isset($_GET['manual_sync'])) {
    /* قفل اختصاصی لازم است: قفلِ کران فقط اجرای دوره‌ای را می‌پوشاند و
       دو resume از مدیر وظیفه می‌توانستند هر دو از checkpoint بخوانند. */
    $_msLockFp = @fopen(MANUAL_SYNC_LOCK_FILE, 'c');
    if (!$_msLockFp || !@flock($_msLockFp, LOCK_EX | LOCK_NB)) {
        if ($_msLockFp) @fclose($_msLockFp);
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok' => false, 'running' => true,
            'error' => 'همگام‌سازی دستی هنوز قفلِ فعال دارد — اجرای موازی ساخته نشد'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    register_shutdown_function(function () use ($_msLockFp) {
        @flock($_msLockFp, LOCK_UN); @fclose($_msLockFp);
    });
    /* =====================================================================
     *  v10.81: همگام‌سازی دستی = همان دکمهٔ «استخراج بک‌اند» + بقیهٔ کارها
     *
     *  قبلاً وارد مسیر کران (cron_run) می‌شدیم: قفل، اعلان، watchdog، …
     *  و گاهی قبل از رسیدن به runBackendExtract می‌مُرد یا رد می‌شد — صف خالی.
     *
     *  حالا دقیقاً مثل ?action=backend_extract:
     *    ۱) همان لحظه runBackendExtract(..., emitEarly=true) → ردیف در EXTRACT_QUEUE
     *    ۲) بعد از استخراج: بایگانی/بازنشستگی + صف ارسال (bsl/woo) مثل حلقهٔ کران
     *    ۳) پمپ ارسال سرورساید
     *  ===================================================================== */
    $_msPrev = readProgress(MANUAL_SYNC_PROGRESS_FILE);
    $_msAge  = time() - (int)($_msPrev['last_progress_ts'] ?? ($_msPrev['ts'] ?? 0));
    $_msResumeCp = is_array($_msPrev['checkpoint'] ?? null) ? $_msPrev['checkpoint'] : [];
    $_msResumeRequested = !empty($_GET['resume']);
    if (!empty($_msPrev['running']) && empty($_msPrev['done']) && empty($_GET['takeover'])) {
        $_msMaxD = max(120, (int)(loadConnections()['stall_after'] ?? 300));
        if ($_msAge >= $_msMaxD) {
            $_msPrev['running'] = false; $_msPrev['done'] = true;
            $_msPrev['phase'] = 'نیمه‌کاره ماند';
            $_msPrev['error'] = 'اجرای قبلی نیمه‌کاره ماند (' . $_msAge . 'ث) — بسته شد.';
            $_msPrev['ts'] = time(); $_msPrev['last_progress_ts'] = time();
            writeProgress(MANUAL_SYNC_PROGRESS_FILE, $_msPrev);
        } else {
            header('Content-Type: application/json; charset=UTF-8');
            echo json_encode(['ok' => false, 'busy' => true,
                'error' => 'یک همگام‌سازی دستی همین حالا در حال اجراست'], JSON_UNESCAPED_UNICODE);
            exit;
        }
    }
    @unlink(MANUAL_SYNC_STOP_FILE);
    if (defined('EXTRACT_STOP_FILE') && is_file(EXTRACT_STOP_FILE)) @unlink(EXTRACT_STOP_FILE);
    if (defined('BSL_STOP_FILE') && is_file(BSL_STOP_FILE)) @unlink(BSL_STOP_FILE);
    if (defined('WOO_STOP_FILE') && is_file(WOO_STOP_FILE)) @unlink(WOO_STOP_FILE);

    $_msKey  = trim((string)($_GET['profile'] ?? $_GET['profile_key'] ?? ''));
    $_msAll  = loadProfiles();
    $_msProf = ($_msKey !== '' && isset($_msAll[$_msKey]) && is_array($_msAll[$_msKey])) ? $_msAll[$_msKey] : null;
    if ($_msKey !== '' && !is_array($_msProf)) {
        $_msRes = profileResolveKey($_msKey, $_msAll);
        if ($_msRes !== null) {
            $_msKey  = $_msRes;
            $_msProf = $_msAll[$_msRes] ?? null;
        }
    }
    if ($_msKey === '' || !is_array($_msProf)) {
        writeProgress(MANUAL_SYNC_PROGRESS_FILE, [
            'running' => false, 'done' => true, 'cancelled' => false,
            'phase' => 'خطا', 'started_at' => time(), 'ts' => time(),
            'last_progress_ts' => time(), 'total' => 4, 'current' => 0,
            'profile_key' => $_msKey, 'profile_name' => $_msKey,
            'recent_log' => ['❌ پروفایل یافت نشد — اول ذخیره کنید'],
            'total_log_count' => 1,
        ]);
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok' => false, 'error' => 'پروفایل یافت نشد'], JSON_UNESCAPED_UNICODE);
        exit;
    }

    try {
        extractClearStaleBlockers($_msKey, [
            'max_idle' => min(90, max(60, (int)(loadConnections()['stall_after'] ?? 300))),
            'clear_waiting' => true,
            'reason' => 'جایگزین شد توسط همگام‌سازی دستی',
        ]);
    } catch (Throwable $e) {}

    $GLOBALS['_manualSync'] = true;
    $GLOBALS['_msKeepConn'] = true;
    @set_time_limit(0);
    @ignore_user_abort(true);

    $_msName = (string)($_msProf['name'] ?? $_msKey);
    $_msResumeSameProfile = $_msResumeRequested
        && (string)($_msResumeCp['profile_key'] ?? '') === $_msKey;
    $_msResumeExtractDone = $_msResumeSameProfile
        && (int)($_msResumeCp['current'] ?? 0) >= 2
        && is_array($_msResumeCp['extract'] ?? null);
    $_msResumeQueueDone = $_msResumeSameProfile
        && is_array($_msResumeCp['enqueue'] ?? null);
    $_msInitialCurrent = $_msResumeQueueDone ? 3 : ($_msResumeExtractDone ? 2 : 1);
    $_msInitialPhase = $_msResumeQueueDone ? 'صف ارسال تمام' : ($_msResumeExtractDone ? 'استخراج تمام' : 'استخراج بک‌اند');
    writeProgress(MANUAL_SYNC_PROGRESS_FILE, [
        'running' => true, 'done' => false, 'cancelled' => false,
        'phase' => $_msInitialPhase, 'started_at' => (int)($_msResumeCp['started_at'] ?? time()), 'ts' => time(),
        'last_progress_ts' => time(),
        'total' => 4, 'current' => $_msInitialCurrent,
        'profile_key' => $_msKey, 'profile_name' => $_msName,
        /* v10.130: فیلدهای extract/enqueue/retire اجرای قبلی باید از همان
           اولین write هم بمانند؛ وگرنه resume=1 پیش از رسیدن به manualSyncProgress
           checkpoint ارکستراسیون را کوتاه می‌کرد. */
        'checkpoint' => array_merge($_msResumeCp, ['profile_key' => $_msKey, 'profile_name' => $_msName,
            'phase' => $_msInitialPhase, 'current' => $_msInitialCurrent, 'total' => 4,
            'started_at' => (int)($_msResumeCp['started_at'] ?? time())]),
        'recent_log' => [
            '▶ همگام‌سازی دستی — همان مسیر «استخراج بک‌اند»',
            '🔑 ' . $_msKey,
            '⚡ شروع runBackendExtract (صف استخراج همین لحظه پر می‌شود)',
        ],
        'total_log_count' => 3,
    ]);

    /* پاسخ فوری + keep-conn (مثل backend_extract + msKeepConn) */
    if (function_exists('msKeepConnStart')) {
        try { msKeepConnStart(); } catch (Throwable $e) {}
    } else {
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok' => true, 'started' => true, 'profile' => $_msKey], JSON_UNESCAPED_UNICODE);
        if (function_exists('fastcgi_finish_request')) { @fastcgi_finish_request(); }
    }

    $_msResults = ['ok' => true, 'manual_sync' => true, 'profile' => $_msKey, 'via' => 'backend_extract'];

    /* ── ۱) استخراج = عین دکمهٔ استخراج بک‌اند ── */
    $_msSyncCfg = is_array($_msProf['syncConfig'] ?? null) ? $_msProf['syncConfig'] : [];
    $_msNoEx = !empty($_msSyncCfg['noExtract']);
    $_msPhase = 'all';
    if ($_msNoEx) {
        $_msPhase = 'detail';
        manualSyncProgress([], '📋 پروفایل بدون‌استخراج فهرست — فاز detail');
    }
    if ($_msResumeExtractDone && (string)($_msResumeCp['profile_key'] ?? '') === $_msKey) {
        $_msEx = $_msResumeCp['extract'];
        manualSyncProgress(['phase' => 'استخراج تمام', 'current' => 2],
            '↻ استخراجِ کاملِ checkpoint دوباره اجرا نشد');
    } else {
        manualSyncProgress(['phase' => 'استخراج بک‌اند', 'current' => 1],
            '⚡ استخراج بک‌اند: ' . $_msName);
        msAlive('extract');
        /* emitEarlyResponse=false چون خودمان پاسخ را فرستادیم؛ trigger=manual_sync */
        $_msEx = runBackendExtract($_msKey, 'manual_sync', false, $_msPhase, true);
    }
    manualSyncProgress(['checkpoint' => ['extract' => $_msEx]], '');
    $_msResults['extract'] = [
        'ok' => !empty($_msEx['ok']),
        'error' => (string)($_msEx['error'] ?? ''),
        'extracted' => (int)($_msEx['extracted'] ?? 0),
        'new' => (int)($_msEx['new'] ?? 0),
        'price_changed' => (int)($_msEx['price_changed'] ?? 0),
        'removed' => (int)($_msEx['removed'] ?? 0),
        'duplicate' => !empty($_msEx['duplicate']),
        'locked' => !empty($_msEx['locked']),
        'queue_id' => (string)($_msEx['queue_id'] ?? ''),
    ];
    if (!empty($_msEx['ok'])) {
        manualSyncProgress(['current' => 2, 'phase' => 'استخراج تمام'],
            '✅ استخراج: ' . (int)($_msEx['extracted'] ?? 0) . ' محصول'
            . (!empty($_msEx['new']) ? (' · جدید ' . (int)$_msEx['new']) : '')
            . (!empty($_msEx['price_changed']) ? (' · قیمت ' . (int)$_msEx['price_changed']) : ''));
        try {
            $cnN = loadConnections();
            notifSourceChanges($cnN, $_msEx, $_msName);
        } catch (Throwable $e) {}
        /* پروفایل تازه بعد از extract */
        $_msAll = loadProfiles();
        $_msProf = $_msAll[$_msKey] ?? $_msProf;
    } else {
        $_msErr = (string)($_msEx['error'] ?? 'استخراج ناموفق');
        if (!empty($_msEx['duplicate'])) $_msErr .= ' (ردیف فعال در صف)';
        if (!empty($_msEx['locked'])) $_msErr .= ' (قفل استخراج)';
        manualSyncProgress(['phase' => 'خطای استخراج'], '❌ ' . mb_substr($_msErr, 0, 280));
        /* استخراج fail نباید کل همگام را بکشد اگر محصول روی دیسک هست — ادامه برای ارسال */
        if (empty($_msProf['products'])) {
            writeProgress(MANUAL_SYNC_PROGRESS_FILE, array_merge(readProgress(MANUAL_SYNC_PROGRESS_FILE), [
                'running' => false, 'done' => true, 'stale' => true, 'error' => $_msErr,
                'checkpoint' => array_merge(
                    (array)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['checkpoint'] ?? []),
                    ['profile_key' => $_msKey, 'phase' => 'خطا', 'current' => 1, 'total' => 4,
                     'started_at' => (int)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['started_at'] ?? time())]),
                'phase' => 'خطا', 'ts' => time(), 'last_progress_ts' => time(),
            ]));
            /* keep-conn: final line */ try { if (defined('MS_KEEP_CONN')) { echo json_encode(['done'=>true], JSON_UNESCAPED_UNICODE)."
"; @ob_flush(); @flush(); } } catch (Throwable $e) {}
            exit;
        }
        manualSyncProgress([], '⚠️ استخراج شکست — ادامه با محصولات ذخیره‌شده برای ارسال');
    }

    if (manualSyncStopped()) {
        writeProgress(MANUAL_SYNC_PROGRESS_FILE, array_merge(readProgress(MANUAL_SYNC_PROGRESS_FILE), [
            'running' => false, 'done' => true, 'stale' => true, 'cancelled' => true,
            'partial' => true, 'resumable' => true,
            'phase' => 'متوقف شد', 'checkpoint' => array_merge(
                (array)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['checkpoint'] ?? []),
                ['profile_key' => $_msKey, 'phase' => 'متوقف شد',
                 'current' => (int)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['current'] ?? 0), 'total' => 4,
                 'started_at' => (int)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['started_at'] ?? time())]),
            'ts' => time(), 'last_progress_ts' => time(),
        ]));
        /* keep-conn: final line */ try { if (defined('MS_KEEP_CONN')) { echo json_encode(['done'=>true], JSON_UNESCAPED_UNICODE)."
"; @ob_flush(); @flush(); } } catch (Throwable $e) {}
        exit;
    }

    /* ── ۲) صف‌سازی ارسال (باسلام / ووکامرس) — همان منطق کران برای یک پروفایل ── */
    if ($_msResumeQueueDone && (string)($_msResumeCp['profile_key'] ?? '') === $_msKey) {
        $_msTarget = (string)($_msResumeCp['target'] ?? ($_msSyncCfg['target'] ?? 'woo'));
        if (!in_array($_msTarget, ['woo', 'bsl', 'both', 'none'], true)) $_msTarget = 'woo';
        $_msResults['target'] = $_msTarget;
        $_msResults['enqueue'] = $_msResumeCp['enqueue'];
        if (is_array($_msResumeCp['extract'] ?? null)) $_msEx = $_msResumeCp['extract'];
        manualSyncProgress(['phase' => 'صف ارسال تمام', 'current' => 3],
            '↻ صف ارسالِ checkpoint دوباره ساخته نشد');
    } else {
    manualSyncProgress(['phase' => 'صف ارسال', 'current' => 3], '📤 آماده‌سازی صف ارسال…');
    msAlive('queue_send');
    try {
        $_msCn = loadConnections();
        $_msTarget = (string)($_msSyncCfg['target'] ?? 'woo');
        if (!in_array($_msTarget, ['woo', 'bsl', 'both', 'none'], true)) $_msTarget = 'woo';
        $_msResults['target'] = $_msTarget;

        /* v10.101: بازنشستگی مشترک (کرون + دستی) — removed + OOS */
        if (!empty($_msEx['ok'])) {
            try {
                /* پروفایل تازه از دیسک بعد از extract */
                $_msProfRet = is_array($_msProf) ? $_msProf : [];
                $_msRetPack = retireAfterExtract($_msCn, $_msProfRet, $_msEx, (string)$_msTarget, $_msSyncCfg, (string)$_msKey);
                if (!empty($_msRetPack['result'])) {
                    $_msRt = $_msRetPack['result'];
                    $_msResults['retire'] = [
                        'mode' => $_msRetPack['mode'],
                        'target' => $_msRetPack['target'],
                        'checked' => (int)($_msRt['checked'] ?? 0),
                        'retired' => (int)($_msRt['retired'] ?? 0),
                        'not_found' => (int)($_msRt['not_found'] ?? 0),
                        'failed' => (int)($_msRt['failed'] ?? 0),
                        'skipped' => (string)($_msRetPack['skipped'] ?? ''),
                        'oos_merged' => (int)($_msRetPack['oos_merged'] ?? 0),
                        'woo_action' => $_msRetPack['woo_action'] ?? '',
                        'bsl_action' => $_msRetPack['bsl_action'] ?? '',
                    ];
                    if (!empty($_msRetPack['oos_merged'])) {
                        manualSyncProgress([], '⛔ ' . (int)$_msRetPack['oos_merged'] . ' کالای ناموجود روی دیسک → بازنشستگی');
                    }
                    if (!empty($_msRetPack['skipped'])) {
                        manualSyncProgress([], '⏭ بازنشستگی: ' . (string)$_msRetPack['skipped']);
                    } else {
                        manualSyncProgress([], '✅ بازنشستگی: ' . (int)($_msRt['retired'] ?? 0)
                            . ' انجام · ' . (int)($_msRt['not_found'] ?? 0) . ' یافت‌نشد · '
                            . (int)($_msRt['failed'] ?? 0) . ' خطا');
                    }
                } elseif (($_msRetPack['skipped'] ?? '') === 'no_items') {
                    manualSyncProgress([], '✓ موردی برای بایگانی/حذف از مبدأ نبود');
                } elseif (!empty($_msRetPack['skipped'])) {
                    manualSyncProgress([], 'ℹ️ بازنشستگی: ' . (string)$_msRetPack['skipped']);
                }
            } catch (Throwable $e) {
                manualSyncProgress([], '⚠️ بازنشستگی: ' . mb_substr($e->getMessage(), 0, 180));
                $_msResults['retire_error'] = $e->getMessage();
            }
        }


        /* محصولات برای ارسال */
        $_msProducts = [];
        if (is_array($_msProf['products'] ?? null)) {
            foreach ($_msProf['products'] as $_mp) {
                if (is_array($_mp) && count($_mp) === 2 && is_array($_mp[1])) {
                    $_msProducts[$_mp[0]] = $_mp[1];
                } elseif (is_array($_mp)) {
                    $_k = (string)($_mp['key'] ?? $_mp['id'] ?? '');
                    if ($_k !== '') $_msProducts[$_k] = $_mp;
                }
            }
        }
        /* اگر exRes محصولات را برگرداند ترجیح بده */
        if (!empty($_msEx['products']) && is_array($_msEx['products'])) {
            // leave disk products as source of truth after extract already saved
        }

        if ($_msTarget === 'none') {
            manualSyncProgress([], '⏭ مقصد none — ارسالی صف نمی‌شود');
        } else {
            /* فراخوانی کمک‌تابع اگر وجود دارد؛ وگرنه منطق inline از cron */
            if (function_exists('cronEnqueueSendsForProfile')) {
                $_msEnq = cronEnqueueSendsForProfile($_msKey, $_msProf, $_msCn, $_msEx ?? [], true);
                $_msResults['enqueue'] = $_msEnq;
                manualSyncProgress([], '📋 صف ارسال: ' . json_encode($_msEnq, JSON_UNESCAPED_UNICODE));
            } else {
                /* Inline minimal enqueue mirroring cron bsl/woo blocks */
                $_msEnq = manualSyncEnqueueSends($_msKey, $_msProf, $_msCn, is_array($_msEx) ? $_msEx : []);
                $_msResults['enqueue'] = $_msEnq;
                if (!empty($_msEnq['log'])) {
                    foreach ((array)$_msEnq['log'] as $_ln) manualSyncProgress([], (string)$_ln);
                }
            }
        }
        manualSyncProgress(['checkpoint' => ['extract' => $_msEx, 'enqueue' => $_msEnq ?? [],
            'retire' => $_msResults['retire'] ?? [], 'target' => $_msTarget]], '');
    } catch (Throwable $e) {
        manualSyncProgress([], '⚠️ صف ارسال: ' . mb_substr($e->getMessage(), 0, 200));
        $_msResults['enqueue_error'] = $e->getMessage();
    }
    }

    if (manualSyncStopped()) {
        writeProgress(MANUAL_SYNC_PROGRESS_FILE, array_merge(readProgress(MANUAL_SYNC_PROGRESS_FILE), [
            'running' => false, 'done' => true, 'stale' => true, 'cancelled' => true,
            'partial' => true, 'resumable' => true,
            'phase' => 'متوقف شد', 'checkpoint' => array_merge(
                (array)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['checkpoint'] ?? []),
                ['profile_key' => $_msKey, 'phase' => 'متوقف شد',
                 'current' => (int)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['current'] ?? 0), 'total' => 4,
                 'started_at' => (int)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['started_at'] ?? time())]),
            'ts' => time(), 'last_progress_ts' => time(),
        ]));
        /* keep-conn: final line */ try { if (defined('MS_KEEP_CONN')) { echo json_encode(['done'=>true], JSON_UNESCAPED_UNICODE)."
"; @ob_flush(); @flush(); } } catch (Throwable $e) {}
        exit;
    }

    /* ── ۳) پمپ ارسال سرورساید ── */
    manualSyncProgress(['phase' => 'ارسال', 'current' => 3], '📡 ارسال از صف…');
    msAlive('send');
    try {
        $_msSendRes = manualServerSendRun();
        $_msResults['ms_server_send'] = $_msSendRes;
        if (!empty($_msSendRes['stopped'])) {
            manualSyncProgress([], '⏹ ارسال با درخواست کاربر متوقف شد');
        } else {
            manualSyncProgress([], '✅ مرحله ارسال تمام شد');
        }
    } catch (Throwable $e) {
        manualSyncProgress([], '⚠️ ارسال: ' . mb_substr($e->getMessage(), 0, 200));
        $_msResults['ms_server_send'] = ['error' => $e->getMessage()];
    }

    /* ── ۴) گزارش ── */
    /* v10.130: خطای صف/ارسال یا توقفِ نرم، پایانِ موفقِ زنجیره نیست. آن را
       stale نگه می‌داریم تا کران بعدی همان checkpoint را resume کند؛ قبلاً
       این مسیر با current=4 و checkpoint=null، کار نیمه‌کاره را done اعلام
       می‌کرد و ادامهٔ خودکار هرگز به آن نمی‌رسید. */
    $_msSendFailed = !empty($_msResults['ms_server_send']['error'])
        || (isset($_msResults['ms_server_send']['ok']) && empty($_msResults['ms_server_send']['ok']));
    $_msPartial = !empty($_msResults['ms_server_send']['stopped']) || $_msSendFailed
        || !empty($_msResults['enqueue_error']) || !empty($_msResults['retire_error'])
        || (isset($_msResults['extract']['ok']) && empty($_msResults['extract']['ok']));
    if ($_msPartial) {
        $_msPartialP = readProgress(MANUAL_SYNC_PROGRESS_FILE);
        $_msPartialCp = is_array($_msPartialP['checkpoint'] ?? null) ? $_msPartialP['checkpoint'] : [];
        $_msPartialP['running'] = false; $_msPartialP['done'] = true;
        $_msSendStopped = !empty($_msResults['ms_server_send']['stopped']);
        $_msPartialP['stale'] = true; $_msPartialP['cancelled'] = $_msSendStopped;
        $_msPartialP['partial'] = true; $_msPartialP['resumable'] = true;
        $_msPartialP['phase'] = $_msSendStopped ? 'متوقف شد' : 'نیمه‌کاره ماند';
        $_msPartialP['error'] = $_msSendStopped ? 'ارسال با درخواست کاربر متوقف شد'
            : 'بخشی از همگام‌سازی ناموفق بود — checkpoint برای ادامه حفظ شد';
        $_msPartialP['checkpoint'] = $_msPartialCp;
        $_msPartialP['summary_data'] = $_msResults;
        $_msPartialP['ts'] = time(); $_msPartialP['last_progress_ts'] = time();
        $_msPartialP['recent_log'][] = $_msPartialP['error'];
        $_msPartialP['recent_log'] = array_slice((array)$_msPartialP['recent_log'], -40);
        writeProgress(MANUAL_SYNC_PROGRESS_FILE, $_msPartialP);
        @unlink(MANUAL_SYNC_STOP_FILE);
        exit;
    }
    try { cronMarkRun($_msKey, 'manual_done'); } catch (Throwable $e) {}
    manualSyncProgress(['phase' => 'تمام شد', 'current' => 4], '✅ همگام‌سازی دستی تمام شد');
    $_msDone = readProgress(MANUAL_SYNC_PROGRESS_FILE);
    $_msDone['running'] = false;
    $_msDone['done'] = true;
    $_msDone['cancelled'] = false;
    $_msDone['current'] = 4;
    $_msDone['phase'] = 'تمام شد';
    $_msDone['checkpoint'] = null;
    $_msDone['stale'] = false;
    $_msDone['ts'] = time();
    $_msDone['last_progress_ts'] = time();
    $_msDone['summary_data'] = $_msResults;
    writeProgress(MANUAL_SYNC_PROGRESS_FILE, $_msDone);
    @unlink(MANUAL_SYNC_STOP_FILE);

    /* cron_last_run برای سازگاری */
    try {
        @file_put_contents(__DIR__ . '/cron_last_run.json', json_encode([
            'ok' => true, 'manual_sync' => true, 'time' => time(),
            'profiles' => [['key' => $_msKey, 'name' => $_msName, 'status' => 'done',
                'extract' => $_msResults['extract'] ?? []]],
        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
    } catch (Throwable $e) {}

    try {
        if (defined('MS_KEEP_CONN')) {
            echo json_encode(['ok' => true, 'done' => true], JSON_UNESCAPED_UNICODE) . "\n";
            @ob_flush(); @flush();
        }
    } catch (Throwable $e) {}
    exit;
}



if (isset($_GET['cron_run']) || (($_POST['action'] ?? '') === 'cron_run')) {
header('Content-Type: application/json; charset=UTF-8');
@set_time_limit(0);
@ignore_user_abort(true);

/* v8.92: «اجرای الان» مثل دکمهٔ «استخراج بک‌اند» رفتار کند.
   کران‌جاب واقعی باید منتظر بماند تا curl نتیجه را بگیرد، ولی دکمهٔ
   مرورگر نباید تا پایان کل کار بلوکه بماند: تا حالا پاسخ فقط وقتی
   می‌آمد که همه‌چیز — استخراج، بازنشستگی، ارسال، اعلان — تمام شده
   بود. روی یک پروفایل بزرگ این یعنی چند دقیقه انتظار، و اگر مرورگر
   یا هاست وسط راه قطع می‌کرد، به نظر می‌رسید دکمه اصلاً کار نکرده.
   با bg=1 همان الگوی استخراج بک‌اند اجرا می‌شود: پاسخ فوری، کار در
   پس‌زمینه، پیشرفت از همان فایل و همان صف خوانده می‌شود. */
/* v9.06: اتصال «همیشه» همین ابتدا بسته می‌شود — نه فقط با bg=1.

   این علتِ واقعیِ «دکمهٔ دستی همه‌چیز را می‌آورد ولی کران فقط فهرست را»
   بود. دکمهٔ دستی از runBackendExtract با emitEarlyResponse=true رد
   می‌شد و همان‌جا fastcgi_finish_request صدا می‌خورد: اتصال بسته،
   پردازه جدا، کار تا آخر ادامه. کران هر دو گام را با
   emitEarlyResponse=false صدا می‌زند، پس اتصال از اولین بایت تا آخرین
   کار باز می‌ماند و وب‌سرور سرِ سقفِ خودش پردازه را می‌کشد. سقفِ
   وب‌سرور از داخل PHP قابل تغییر نیست و set_time_limit(0) جلویش را
   نمی‌گیرد.

   گام ۱ (فهرست) کوتاه است و تمام می‌شود؛ گام ۲ (جزئیات) برای هر محصول
   یک درخواست HTTP می‌زند و دقیقاً همان‌جاست که کشته می‌شود. برای همین
   کاربر فهرست پایه را می‌دید و هیچ گالری‌ای نه.

   حالا کران هم مثل دکمهٔ دستی رفتار می‌کند: پاسخ فوری، اتصال بسته، کار
   در پس‌زمینه. curlِ کران‌جاب هم بلافاصله پاسخ ۲۰۰ می‌گیرد و بسته
   می‌شود — که برای کران‌جاب مطلوب هم هست، چون سرویس‌های کران معمولاً
   خودشان سقف چنددقیقه‌ای دارند و اتصال طولانی را قطع می‌کنند.
   خلاصهٔ نهایی در cron_last_run.json می‌نشیند و با ?cron_last خوانده
   می‌شود. */
/* v9.41: فاز جزئیات را «قبل از» جدا شدن از اتصال، هم‌زمان اجرا کن.

   سرنخِ کاربر: وقتی آدرس ?cron_run را در مرورگر می‌زند، استخراج جزئیات
   کار می‌کند، اما وقتی همین آدرس توسط cron-job.org (یا هر درخواستِ
   خارجی) فرستاده می‌شود، فاز جزئیات اجرا نمی‌شود.

   علت: پایین‌تر finishRequestNow() اتصال را می‌بندد و بقیهٔ کار — از
   جمله فاز جزئیات — باید در پردازهٔ جدا شده در پس‌زمینه ادامه پیدا کند.
   مرورگرِ باز آن پردازه را زنده نگه می‌دارد (یا حداقل هاست فرصت می‌دهد)،
   ولی وقتی یک سرویسِ کرانِ خارجی درخواست می‌زند، هاست همان لحظه که پاسخ
   داده شد و کلاینت رفت، کارگرِ PHP-FPM/LiteSpeed را آزاد می‌کند و کارِ
   پس‌زمینه قبل از رسیدن به فاز جزئیات کشته می‌شود.

   راه‌حل: همین ابتدای کران — قبل از finishRequestNow — فاز جزئیات را
   به‌صورت هم‌زمان اجرا می‌کنیم. این فاز فقط محصولاتِ ناقص را باز می‌کند
   (ارزان است) و چیزی به مقصد نمی‌فرستد، پس هم زیرِ قفل امن است و هم اگر
   بعد از پاسخ پردازه کشته شود، جزئیات از قبل انجام شده است. نتیجه در
   $preDetail نگه داشته می‌شود و مسیرهای قفل/اصلی پایین به‌جای دوباره
   صدا زدن، از همین استفاده می‌کنند (dedup بر اساس detailLastRun هم
   از اجرای دوباره جلوگیری می‌کند). */
/* v9.44: «استخراج دوره‌ای جزئیات» حذف شد — جزئیات حالا به‌صورت درجا و هم‌زمان
   با استخراجِ هر محصول در runBackendExtract گرفته می‌شود، پس دیگر نیازی به
   این گذرِ جداگانه در ابتدای کران نیست. */

$_cronBg = !empty($_POST['bg']) || !empty($_GET['bg']);
/* v10.61 (۷۵): همگام‌سازیِ دستی «جدا نمی‌شود» — توضیح کامل در بالای
   msKeepConnStart(). خلاصه: هاست شما پردژهٔ بدونِ کلاینت را در چند
   ثانیه می‌کُشد و کرانِ هاست هم (به‌گزارشِ کاربر) روزهاست اجرا نمی‌شود،
   پس همگام‌سازیِ دستی که جدا می‌شد، پیش از رسیدن به حلقهٔ همگام‌سازی
   می‌مُرد و هیچ کارتی به صفِ استخراج نمی‌نشست. حالا در حالتِ دستی
   اتصالِ مرورگر تا پایانِ کار باز می‌ماند (ndjson) و برای کران
   رفتارِ قبلی (پاسخِ فوری + پس‌زمینه) دست‌نخورده است. */
if (!empty($GLOBALS['_msKeepConn']) && !isCliRun()) {
    msKeepConnStart();
} else {
    finishRequestNow(json_encode(['ok' => true, 'started' => true, 'bg' => $_cronBg,
        'detached' => true, 'note' => 'اجرا در پس‌زمینه ادامه دارد — نتیجه در cron_last_run.json'],
        JSON_UNESCAPED_UNICODE));
}
/* v10.67 (81): شبکهٔ ایمنیِ کُرش. وقتی هاست پردژه را می‌کُشد یا PHP به
   خطای فیتال می‌خورد (حافظه و...)، رابطِ همگام‌سازیِ دستی نباید تا ابد روی
   «در حال شروع» منجمد بماند: فایلِ پیشرفت با دلیلِ واقعی بسته می‌شود و
   خطا در cron_last_run هم ثبت. این همان جایی است که «هیچ کاری نکردن» را
   از «مردهٔ بی‌صدا» جدا می‌کند. */
if (!isCliRun()) {
    register_shutdown_function(function () {
        $e = error_get_last();
        if (!$e || empty($e['message'])) return;
        if (!in_array($e['type'], [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR, E_USER_ERROR], true)) return;
        $msg = $e['message'];
        try {
            $p = readProgress(MANUAL_SYNC_PROGRESS_FILE);
            if (!empty($p['running']) && empty($p['done'])) {
                $p['running'] = false; $p['done'] = true; $p['cancelled'] = false;
                $p['phase'] = 'خطای فیتال';
                $p['error'] = 'پردژه در میانِ اجرا مُرد: ' . mb_substr($msg, 0, 300) . ' (خط ' . (int)($e['line'] ?? 0) . ')';
                $lg = is_array($p['recent_log'] ?? null) ? $p['recent_log'] : [];
                $lg[] = '💥 ' . $p['error'];
                $p['recent_log'] = array_slice($lg, -40);
                $p['ts'] = time(); $p['last_progress_ts'] = time();
                writeProgress(MANUAL_SYNC_PROGRESS_FILE, $p);
            }
            $lr = ['ok' => false, 'fatal' => true, 'error' => mb_substr($msg, 0, 500),
                   'line' => (int)($e['line'] ?? 0), 'time' => time()];
            @file_put_contents(__DIR__ . '/cron_last_run.json',
                json_encode($lr, JSON_UNESCAPED_UNICODE), LOCK_EX);
        } catch (Throwable $t) {}
    });
}
if ($_cronBg) define('CRON_BG', true);

/* قفلِ واقعیِ کران: وجود یا سنِ فایل معیار مالکیت نیست. مسیر دائمی است و
   همان handle تا پایانِ اجرا flock را نگه می‌دارد؛ مرگِ worker هم قفل را
   خودکار آزاد می‌کند و اجرای کران بعدی بلافاصله می‌تواند ادامه دهد. */
$cronLock = __DIR__ . '/.cron_run.lock';
$cronLockFp = @fopen($cronLock, 'c');
$cronLockHeld = $cronLockFp && @flock($cronLockFp, LOCK_EX | LOCK_NB);
if (!$cronLockHeld) {
    if ($cronLockFp) @fclose($cronLockFp);
    $cronLockFp = null;
}
if ($cronLockHeld) {
    @ftruncate($cronLockFp, 0); @rewind($cronLockFp);
    @fwrite($cronLockFp, (string)time()); @fflush($cronLockFp);
}
/* اگر handle را نگرفتیم، این تیک فقط گزارشِ «اجرای قبلی فعال است» می‌دهد.
   watchdog/worker دیگری در کنار کرانِ زنده اجرا نمی‌شود؛ قفل‌های اختصاصیِ
   هر کار فقط لایهٔ دومِ محافظت‌اند. */
if (!$cronLockHeld) {
    $lockOut = ['ok' => true, 'skipped' => true, 'locked' => true,
        'reason' => 'اجرای قبلی کران هنوز قفلِ واقعی را در اختیار دارد'];
    cronEmit($lockOut);
    exit;
}

/* فقط اجرای صاحبِ handle به حلقهٔ کران می‌رسد؛ اجرای هم‌زمان در guard بالا
   بدون هیچ probe یا حذفِ path متوقف شد. */
/* handle از همین‌جا تا shutdown در اختیارِ همین اجرای کران است؛ path
   دائمی می‌ماند تا worker بعدی همیشه روی همان inode قفل بگیرد. */
register_shutdown_function(function () use ($cronLockFp) {
    if (is_resource($cronLockFp)) {
        @flock($cronLockFp, LOCK_UN);
        @fclose($cronLockFp);
    }
});

/* =====================================================================
   v10.21 (۳۴ج): «نبضِ کران» — علتِ قطع‌شدنِ اعلانِ دوره‌ای

   گزارش کاربر: پیامِ دوره‌ای پیام‌رسان دیگر نمی‌آید.

   ریشه: notifCronPing آخرین کارِ کران است. بینِ شروعِ اجرا و رسیدن به
   آن، کلِ چرخهٔ استخراج/ارسال/ایجنت اجرا می‌شود — روی کاتالوگِ بزرگ
   چند دقیقه. هاستِ اشتراکی معمولاً پردازهٔ پس‌زمینه را قبل از پایان
   می‌کُشد (سقفِ FcgidIOTimeout / request_terminate_timeout). آن‌وقت:
     • پینگ هرگز فرستاده نمی‌شود،
     • cron_last_run.json هم نوشته نمی‌شود،
     • و قفل جا می‌ماند، پس تیک‌های بعدی هم تا نیم ساعت رد می‌شوند.
   نتیجه از بیرون دقیقاً «اعلان قطع شد» است، بدون هیچ ردی.
   با v10.05 که autoTick (کارهای ایجنتِ هوش مصنوعی، ده‌ها ثانیه) درست
   قبل از پینگ اضافه شد، احتمالِ این اتفاق به‌مراتب بیشتر شد — همان
   «بعد از یکی از به‌روزرسانی‌های اخیر قطع شد».

   راه‌حل: نبض «اولِ» اجرا زده می‌شود، نه آخر. اینجا هنوز هیچ کارِ
   طولانی‌ای شروع نشده، پس تقریباً همیشه می‌رسد. throttle (ping_every)
   دقیقاً مثل قبل رعایت می‌شود؛ فقط جای فراخوانی عوض شده. خلاصهٔ کارِ
   انجام‌شده هم از دست نمی‌رود: پینگِ آخرِ کار سرِ جایش می‌ماند و اگر
   اجرا سالم به آخر برسد، همان گزارشِ کامل را می‌فرستد (و چون
   last_cron_ping تازه شده، پیامِ تکراری نمی‌آید مگر دوره‌اش رسیده باشد).
   ===================================================================== */
try {
    $_cnPing = loadConnections();
    $_hb = notifCronPing($_cnPing, ['profiles' => [], 'heartbeat' => true]);
    if (!empty($_hb['sent'])) $results_heartbeat = 'sent';
} catch (Throwable $e) { /* نبض هرگز نباید جلوی کارِ اصلی را بگیرد */ }

$now = time();
$profiles = loadProfiles();
$syncState = loadSyncState();
$cn = loadConnections();
// v8.37: ok صریح، تا ابزارهای بیرونی بتوانند موفقیت اجرا را تشخیص دهند
$results = ['ok' => true, 'time' => $now, 'profiles' => []];
// v10.21 (۳۴ج): نبضِ ابتدای اجرا در گزارش هم بماند
if (!empty($results_heartbeat)) $results['heartbeat'] = $results_heartbeat;

/* v10.48 (۶۲): اعلان‌ها و پاسخ خودکار «اولِ» کران، قبل از هر کار بلند.

   دلایلش همان الگویی است که قبلاً برای نگهبان (۸.۹۷)، بکاپ (۹.۱۶) و
   حلقهٔ جزئیات (۹.۲۰) استفاده شد: هاستِ شما پردازهٔ PHP را وسطِ اجرا
   می‌کشد (پینگِ نبض خود می‌گوید: «اجرای قبلی نیمه‌کاره ماند»). اعلان‌ها
   تا حالا در میانهٔ کران — بعد از تمامِ همگام‌سازی‌ها — اجرا می‌شدند،
   یعنی دقیقاً بعد از همان جایی که پردژه کشته می‌شود؛ کاربر فقط پینگِ
   «شروع شد» را می‌دید و هیچ اعلانی. حالا بررسیِ اعلان (سفارش، پیام،
   محصول) و پاسخ خودکار — که هر دو سبک‌اند و فقط باسلام را می‌خوانند —
   درست بعد از نبض و قبل از بکاپ/جزئیات/همگام‌سازی می‌نشینند؛ حتی اگر
   هاست همین چند ثانیهٔ بعد پردژه را بکشد، اعلانِ همین دور رفته است. */
/* v10.21 (۳۴ج): هر کارِ کران داخل try/catch.
   ریشهٔ «اعلان دوره‌ای قطع شد» همین بود: پینگ آخرین کارِ کران است و هر
   استثنایی در کارهای قبل از آن (اعلان‌ها، پاسخ خودکار، گزارش شبانه) کلِ
   اجرا را می‌کشت — پس نه پینگ می‌رفت، نه cron_last_run نوشته می‌شد، و
   کاربر فقط سکوت می‌دید. حالا هر کار جدا محافظت می‌شود و شکستِ یکی
   بقیه را زمین نمی‌زند. */
try {
    $notifyResult = bslCheckNotifications($cn);
    if (!empty($notifyResult)) $results['notifications'] = $notifyResult;
} catch (Throwable $e) {
    $results['notifications'] = ['error' => mb_substr($e->getMessage(), 0, 200)];
}

// v8.64: پاسخ خودکار به پیام مشتریان — بعد از اعلان‌ها، تا اول خبر برسد
// و بعد ربات جواب دهد. مهلت ادب داخل خود موتور رعایت می‌شود.
if (arCfg($cn)['enabled']) {
    try {
        $arRes = autoReplyRun($cn, false);
        if (!empty($arRes['replied']) || !empty($arRes['failed'])) {
            $results['autoreply'] = ['replied' => (int)$arRes['replied'],
                                     'failed' => (int)$arRes['failed'],
                                     'checked' => (int)$arRes['checked']];
            if (arCfg($cn)['notify'] && (int)$arRes['replied'] > 0) notifSend($cn, arMsg($arRes), 'ar');
        } elseif (!empty($arRes['error'])) {
            $results['autoreply'] = ['error' => $arRes['error']];
        }
    } catch (Throwable $e) {
        $results['autoreply'] = ['error' => $e->getMessage()];
    }
}


/* =====================================================================
   v9.10: استخراج دوره‌ای جزئیات — حلقهٔ مستقل، قبل از همگام‌سازی.

   خواستهٔ کاربر: یک تیک و یک دراپ‌داون دورهٔ جدا، که با اجرای دوره‌ای‌اش
   «همهٔ جزئیات» گرفته شود — گالری، تنوع‌ها، دسته‌بندی، توضیحات و بقیه.

   چرا حلقهٔ جدا و چرا «قبل» از حلقهٔ همگام‌سازی: حلقهٔ پایین در همان
   خط اولش اگر syncConfig.enabled خاموش باشد پروفایل را رد می‌کند. پس
   اگر این کار را داخل آن حلقه می‌گذاشتم، کسی که فقط می‌خواهد جزئیات
   دوره‌ای بگیرد و چیزی به مقصد نفرستد، هیچ‌وقت اجرا نمی‌شد. جدا بودن
   یعنی این دو قابلیت واقعاً مستقل‌اند.

   زمان‌بندی خودش را هم جدا نگه می‌دارد (کلید detail در فایل وضعیت) تا
   دورهٔ جزئیات با دورهٔ همگام‌سازی قاطی نشود. */
/* v9.13: همان حلقه، حالا از تابع مشترک.
   v9.20: این حلقه «اول» اجرا می‌شود — درست بعد از قفل، قبل از بکاپ و
   نگهبان. بکاپ خودکار وقتی فراخوانی می‌شود می‌تواند چند دقیقه طول بکشد و
   اگر وسطِ همان فرآیند پردازه کشته شود، به این حلقه هیچ‌وقت نمی‌رسیدیم و
   جزئیات بی‌رد می‌مرد — دقیقاً همان «اصلاً اجرا نمی‌شود» که کاربر می‌دید.
   حالا ردیفِ جزئیات در همان صفِ استخراج زود و مطمئن می‌نشیند. */

/* v8.97: نگهبان‌ها «اول» اجرا می‌شوند، نه آخر.

   تا اینجا cronWatchdogs بعد از حلقهٔ پروفایل‌ها صدا زده می‌شد. ولی
   دقیقاً همان حلقه است که استخراج را اجرا می‌کند و روی هاست وسط کار
   کشته می‌شود — یعنی در همان حالتی که نگهبان لازم است، هرگز به آن
   نمی‌رسیدیم. کاربر گزارش داد «گویا نگهبان صف اصلاً وجود ندارد» و
   دقیقاً همین بود.

   حالا اول کارهای گیرکرده آزاد می‌شوند و بعد سراغ کار تازه می‌رویم.
   هزینه‌اش وقتی چیزی گیر نکرده چند خط خواندن فایل است. */

/* v10.67 (81): نگهبانِ ابتدایی هم در شبکهٔ catch — استثنأ بی‌جفتِ
   اینجا کلِ همگام‌سازیِ دستی را پیش از حلقه می‌کُشت. */
try {
    $wdEarly = cronWatchdogs($cn);
} catch (Throwable $e) {
    $wdEarly = [];
    $results['watchdog_error'] = 'ابتدایی: ' . mb_substr($e->getMessage(), 0, 200);
}
foreach ($wdEarly as $k => $v) { if (!empty($v)) $results[$k] = $v; }
/* workerهای ادامه با پاسخِ زودهنگام جدا می‌شوند؛ این تیک نباید بعد از
   dispatch، استخراج/ارسال/ایجنتِ دیگری را هم راه بیندازد. کران بعدی همین
   رجیستری و checkpoint را دوباره می‌خواند و اولویت را ادامه می‌دهد. */
if (!empty($wdEarly['resume_blocking'])) {
    $results['deferred_by_resume'] = true;
    cronEmit($results);
    exit;
}

/* پروفایل‌ها و وضعیت دوباره خوانده می‌شوند تا همگام‌سازیِ پایین نسخهٔ
   کهنه (یا پروفایلِ تازه‌ای که همین تیک عوضش کرده) را نبیند. */
$profiles  = loadProfiles();
$syncState = loadSyncState();

/* v9.75: اگر نگهبان، ردیفِ استخراجِ گیرکرده (فازِ ۱ فهرست یا فازِ ۲ جزئیات) را
   برداشته باشد، همان پروفایل را همین‌جا «ادامه» می‌دهیم — نه اینکه صبر کنیم تا
   نوبتِ بعدیِ زمان‌بندی برسد. فازِ مناسب از روی نشانهٔ مرحله انتخاب می‌شود:
   اگر اجرای قبلی وسطِ جزئیات مانده باشد (stage=detail تازه) → detail؛ وگرنه → all
   (فهرست + جزئیاتِ فقطِ محصولاتِ جدید/ناقص). ردیفی که اینجا دوباره ساخته می‌شود
   در صف است، پس حلقهٔ پایین همان پروفایل را تکراری رد می‌کند و کارِ دوگانه پیش
   نمی‌آید. */
/* v9.92: «ادامهٔ نگهبان» هم باید تابعِ زمان‌بندیِ پروفایل باشد.

   این در ۹.۹۱ باگِ اصلیِ «فاز ۲ در هر فراخوانیِ کران اجرا می‌شود» بود و
   دقیقاً همان حلقه‌ای است که کامنتِ v9.73 ادعا می‌کرد بسته شده — ولی از
   درِ پشتیِ مسیرِ v9.75 دوباره باز شده بود:

     کاتالوگِ بزرگ ⇒ فازِ جزئیات هر نوبت از سقفِ زمانیِ هاست می‌ماند
     ⇒ پردازه کشته می‌شود، ردیفِ صف «running» جا می‌ماند و
        _extract_stage='detail' تازه می‌ماند
     ⇒ تیکِ بعدیِ کران (یک دقیقه بعد): نگهبان ردیفِ بی‌حرکت را برمی‌دارد و
        extract_resume را پر می‌کند
     ⇒ همین‌جا بی‌قید runBackendExtract(...,'detail') صدا زده می‌شود —
        قبل و مستقلاً از گیتِ not_due، پس دورهٔ ۶ ساعته هیچ اثری ندارد
     ⇒ دوباره کشته می‌شود ⇒ حلقهٔ بی‌پایانِ «جزئیات در هر دقیقه».

   نگهبان برای «کارِ نیمه‌کارهٔ یک اجرای مرده» ساخته شده، نه برای دور زدنِ
   زمان‌بندی. پس ادامه فقط وقتی مجاز بود که خودِ آن پروفایل هم اکنون در
   نوبتش باشد — وگرنه ردیفِ گیرکرده از صف برداشته می‌شد و کار در نوبتِ
   بعدی ادامه می‌یافت.

   v10.123 این سیاست را عوض کرد: به‌جای گیتِ نوبت، «ادامهٔ استخراج» مستقل
   از بازهٔ سینک و در هر تیکِ کران اجرا می‌شود (خواستهٔ صریحِ کاربر) — چون
   بودجهٔ زمانیِ فهرست/جزئیات (v8.97 / v10.122) تضمین می‌کند هر اجرا تمیز
   بایستد و چک‌پوینت بنویسد. ضدِ حلقهٔ بی‌پایان هم (v10.124) سقفِ «بدون
   پیشرفت» است نه سقفِ ساعتیِ کور: تا وقتی ادامه جلو می‌رود، هر تیک ادامه
   می‌یابد؛ فقط پروفایلی که چند بار پشت‌سرهم هیچ پیشرفتی نمی‌کند مهار می‌شود. */
/* v10.123: گذرِ «ادامهٔ استخراج» — مستقل از گیتِ زمان‌بندیِ سینک.
   خواستهٔ کاربر: استخراجِ متوقف/وسط‌راه‌مانده با کرانِ بعدی ادامه پیدا کند،
   نه دورهٔ بعدیِ اجرایش — درست مثل زدنِ دکمهٔ «▶ ادامه از صفحهٔ X». فهرستِ
   کاندیدا از دو جا می‌آید:
     ۱) پروفایل‌هایی که نگهبانِ بالا ردیفِ بی‌حرکتشان را بسته (extract_resume).
     ۲) هر پروفایلی که روی دیسک علامتِ فهرست/جزئیاتِ نیمه‌کاره دارد (stage میانی،
        incomplete، یا _extract_resume_from) و الان واقعاً در حال اجرا نیست —
        این شاملِ توقفِ تمیزِ بودجهٔ زمانی (ردیفِ paused) هم می‌شود، نه فقطِ مرده‌ها.
   ضدِ حلقهٔ بی‌پایان: سقفِ تعداد در هر تیک + سقفِ «بدون پیشرفت» هر پروفایل —
   اگر ادامهٔ قبلی جلو نرفته باشد (امضای پیشرفت ثابت)، پس از چند تلاش مهار
   می‌شود؛ اما تا وقتی پیشرفت هست، هر تیک ادامه می‌یابد. */
$_resumeCandidates = array_values(array_unique((array)($wdEarly['extract_resume'] ?? [])));
$_rQueueNow = extractReadQueue();
foreach ($profiles as $_rk => $_prR) {
    if (!is_array($_prR)) continue;
    $_rStage = (string)($_prR['_extract_stage'] ?? '');
    $_rMid   = in_array($_rStage, ['list', 'list_done', 'detail', 'stopped'], true);
    $_rInc   = !empty($_prR['_extract_list_incomplete']) || !empty($_prR['_extract_resume_req'])
               || (int)($_prR['_extract_resume_from'] ?? 0) > 0;
    if (!$_rMid && !$_rInc) continue;
    /* اگر همین پروفایل ردیفِ running یا waiting دارد، یا الان کار می‌کند یا
       در نوبت است — خودش می‌رود؛ اینجا دوباره شروعش نکن (اجرای موازی). */
    $_rBusy = extractLockIsHeld();
    foreach ((array)($_rQueueNow['entries'] ?? []) as $_qe) {
        if (!is_array($_qe)) continue;
        if ((string)($_qe['profile_key'] ?? '') !== $_rk) continue;
        if (in_array((string)($_qe['status'] ?? ''), ['running', 'waiting'], true)) { $_rBusy = true; break; }
    }
    if ($_rBusy) continue;
    if (!in_array($_rk, $_resumeCandidates, true)) $_resumeCandidates[] = $_rk;
}
if ($_resumeCandidates) {
    $_resumeBudget = max(1, min(10, (int)($cn['auto_resume_max'] ?? 3)));  /* سقف در هر تیک */
    $_resumeRan = 0;
    foreach ($_resumeCandidates as $_rk) {
        if ($_rk === '') continue;
        if ($_resumeRan >= $_resumeBudget) {
            $results['extract_resume_skipped'][] = ['key' => $_rk, 'reason' => 'tick_budget'];
            continue;
        }
        $_prR = $profiles[$_rk] ?? null;
        if (!is_array($_prR)) continue;
        /* v10.124: سقفِ «بدون پیشرفت» — فقط وقتی مهار می‌شود که ادامهٔ قبلی
           هیچ پیشرفتی نکرده باشد (امضای چک‌پوینت ثابت). پیشرفتِ هر بار، شمارنده
           را صفر می‌کند تا کاتالوگِ بزرگِ سالم هر تیک جلو برود. */
        $_rSig  = extractResumeSig($_prR);
        $_rMeta = is_array($_prR['_extract_resume_meta'] ?? null) ? $_prR['_extract_resume_meta'] : [];
        $_rPrevSig = (string)($_rMeta['sig'] ?? '');
        $_rPrevAt  = (int)($_rMeta['at'] ?? 0);
        $_rTries   = (int)($_rMeta['tries'] ?? 0);
        if ($_rPrevSig !== '' && $_rPrevSig === $_rSig && (time() - $_rPrevAt) < AUTO_RESUME_WINDOW) {
            $_rTries++;
        } else {
            $_rTries = 0;
        }
        if ($_rTries >= $_resumeBudget) {
            $results['extract_resume_skipped'][] = ['key' => $_rk, 'reason' => 'no_progress', 'tries' => $_rTries];
            continue;
        }
        /* امضا و شمارنده را «پیش از» اجرا بنویس تا اگر هاست وسطِ کار کشت،
           تیکِ بعدی بداند این تلاش از کجا شروع شد و پیشرفتی کرده یا نه. */
        $_prR['_extract_resume_meta'] = ['sig' => $_rSig, 'at' => time(), 'tries' => $_rTries];
        $profiles[$_rk] = $_prR;
        saveProfiles($profiles);
        $_prep = extractResumePrepare($_rk, $cn);
        if (empty($_prep['ok'])) {
            $results['extract_resume_skipped'][] = ['key' => $_rk, 'reason' => $_prep['reason'] ?: 'no_profile'];
            continue;
        }
        cronMarkRun($_rk, 'extract_resume');
        $syncState = loadSyncState();
        try {
            $_rr = runBackendExtract($_rk, 'watchdog_resume', false, $_prep['phase'], false, (string)($_prep['queue_id'] ?? ''));
            $results['extract_resumed'][] = ['key' => $_rk, 'phase' => $_prep['phase'], 'ok' => !empty($_rr['ok'])];
            /* worker پاسخِ زودهنگام دارد؛ کارِ دیگری در همین تیک dispatch
               نشود تا ترتیب و مرزِ قفل قابل اتکا بماند. */
            $results['resume_blocking'] = true;
        } catch (Throwable $_rEx) {
            $results['extract_resumed'][] = ['key' => $_rk, 'phase' => $_prep['phase'], 'ok' => false,
                'error' => mb_substr($_rEx->getMessage(), 0, 160)];
            $results['resume_blocking'] = true;
        }
        $_resumeRan++;
        break;
    }
    // پروفایل‌ها و وضعیت را بعد از ادامه‌دادن دوباره بخوان تا حلقهٔ پایین نسخهٔ تازه ببیند
    $profiles  = loadProfiles();
    $syncState = loadSyncState();
}

/* =====================================================================
   v10.35 (۴۷ه): «همگام‌سازیِ دستی» از همین مسیر رد می‌شود، نه از یک مسیرِ
   موازی.

   خواستهٔ کاربر: یک دکمه در تبِ شروع که کلِ فرآیند را از استخراج تا
   ارسال اجرا کند. وسوسه‌انگیز بود که یک اندپوینتِ جدا نوشته شود، ولی
   آن‌وقت دو نسخه از منطقِ «چه چیزی صف شود، با کدام تنظیمات، با کدام
   محافظ» می‌داشتیم و دیر یا زود از هم واگرا می‌شدند — همان چیزی که در
   v8.92 برای سه دکمهٔ استخراج اتفاق افتاده بود.

   پس دکمهٔ دستی دقیقاً همین حلقه را اجرا می‌کند، فقط با دو تفاوت:
     only=<key>  ⇒ فقط همان پروفایل
     force=1     ⇒ گیتِ «هنوز نوبتش نشده» یک بار نادیده گرفته می‌شود
   ===================================================================== */
/* v10.80: در شروع کران/همگام‌سازی خودکار، ردیف و قفل مرده را جارو کن
   تا due بودن پروفایل به enqueue واقعی برسد (نه silent duplicate). */
if (!manualSyncActive()) {
    try {
        $_autoClr = extractClearStaleBlockers('', [
            'max_idle' => max(120, (int)($cn['stall_after'] ?? 300)),
            'clear_waiting' => false,
            'reason' => 'پاک‌سازی کران (ردیف/قفل کهنه)',
        ]);
        if ($_autoClr > 0) $results['stale_cleared'] = $_autoClr;
    } catch (Throwable $_autoClrEx) {}
}

$_onlyKey  = trim((string)($_GET['only'] ?? ''));
$_forceRun = !empty($_GET['force']);
foreach ($profiles as $key => $profile) {
if ($_onlyKey !== '' && $key !== $_onlyKey) continue;
/* v10.61 (۷۵): ضربانِ اتصالِ دستی — پردازندهٔ بی‌خروجی را هاست می‌کُشد؛
   هر پروفایل یک خطِ ndjson می‌زند تا اتصال «زنده» بماند. */
msAlive('پروفایل: ' . (string)($profile['name'] ?? $key));
/* توقفِ دستی: بینِ دو پروفایل بررسی می‌شود تا کارِ نیمه‌کاره نماند */
if (manualSyncActive() && manualSyncStopped()) { $results['manual_stopped'] = true; break; }
$syncCfg = $profile['syncConfig'] ?? [];
$pResult = ['key' => $key, 'name' => $profile['name'] ?? $key];
if (empty($syncCfg['enabled']) && !$_forceRun) { $pResult['status'] = 'sync_disabled'; $results['profiles'][] = $pResult; continue; }
$interval = (int)($syncCfg['interval'] ?? 3600);
$lastRun = (int)($syncState[$key]['lastRun'] ?? 0);
$target = $syncCfg['target'] ?? 'woo';
/* v9.91: «هیچ‌کدام» — استخراج دوره‌ای انجام شود ولی هیچ ارسالی به مقصدها نشود.
   مقدارِ none با هیچ‌کدام از شرط‌های woo/bsl/both جور درنمی‌آید، پس صف‌ها خالی
   می‌مانند. فقط برای اینکه گزارشِ کران روشن باشد، صریح علامت می‌زنیم. */
if (!in_array($target, ['woo', 'bsl', 'both', 'none'], true)) $target = 'woo';
/* v10.35 (۴۷ه): force=1 (همگام‌سازیِ دستی) گیتِ نوبت را یک بار رد می‌کند */
if (!$_forceRun && $interval > 0 && ($now - $lastRun < $interval)) { $pResult['status'] = 'not_due'; $pResult['remaining'] = $interval - ($now - $lastRun); $results['profiles'][] = $pResult; continue; }
/* v9.92: نوبت همین‌جا — پیش از هر کارِ طولانی — مصرف و روی دیسک ثبت شود.
   جزئیاتِ چرایی بالای cronMarkRun(). خلاصه: تا حالا lastRun فقط در مسیرِ
   کاملاً موفق ذخیره می‌شد، پس یک استخراجِ طولانی که هاست وسطش پردازه را
   می‌کشت باعث می‌شد پروفایل در تیکِ بعدیِ کران دوباره «due» باشد و کل
   چرخه (از جمله فاز ۲) هر دقیقه تکرار شود. */
cronMarkRun($key, 'running');
if (!isset($syncState[$key]) || !is_array($syncState[$key])) $syncState[$key] = [];
$syncState[$key]['lastRun'] = $now;
$pResult['status'] = 'syncing'; $pResult['target'] = $target;
manualSyncProgress(['phase' => 'استخراج', 'current' => 1,
    'last_title' => (string)($profile['name'] ?? $key)],
    '🔎 استخراج: ' . (string)($profile['name'] ?? $key));   // v10.35 (۴۷ه)
if ($target === 'none') { $pResult['send'] = 'disabled_by_target'; }
/* v9.45: پروفایل‌های واردشده با اکسل/CSV — بدون استخراج، فقط آپدیت قیمت/موجودی.
   وقتی تیک «بدون استخراج» روشن است، مرحلهٔ استخراج (فهرست/جزئیات) کاملاً رد
   می‌شود و فقط محصولاتِ ازقبل‌داشته با قیمت و موجودیِ فعلی‌شان دوره‌ای به مقصد
   ارسال می‌شوند (طبق دورهٔ خودِ همگام‌سازی). برای این پروفایل‌ها استخراج نه
   لازم است نه ممکن (هیچ URL/سلکتوری ندارند). */
$noExtract = !empty($syncCfg['noExtract']);
if ($noExtract) {
    /* =================================================================
       v10.21 (۳۴الف): در پروفایلِ «بدون استخراج»، سینکِ دوره‌ای از راهِ
       «استخراجِ تفصیلیِ جزئیات» قیمت و موجودی را تازه می‌کند.

       مسئله: تا اینجا «بدون استخراج» یعنی هیچ‌چیز از مبدأ خوانده نشود و
       فقط همان قیمتِ لحظهٔ درون‌ریزیِ فایل دوباره فرستاده شود. یعنی
       پروفایل‌های اکسل/CSV عملاً منجمد بودند: قیمتِ فایلِ سه ماه پیش هر
       شب دوباره به باسلام/ووکامرس می‌رفت و هیچ‌وقت به‌روز نمی‌شد.

       ولی این محصولات «لینکِ صفحهٔ محصول» دارند (ستونِ link فایل). پس
       منبعِ به‌روزرسانی موجود است — فقط فازِ فهرست است که برایشان معنا
       ندارد (نه URLِ فهرست دارند نه سلکتورِ ظرف). دقیقاً همان چیزی که
       فازِ 'detail' انجام می‌دهد: صفحهٔ تک‌تکِ محصولاتِ روی دیسک را باز
       می‌کند، بدون اینکه سراغِ صفحهٔ فهرست برود.

       پس در این حالت runBackendExtract با phase='detail' صدا زده می‌شود.
       شرطش هم روشن است: پروفایل باید سلکتورِ جزئیات (دستِ‌کم قیمت) یا
       گالری داشته باشد و محصولاتش لینک داشته باشند؛ وگرنه مثل قبل فقط
       ارسالِ دوباره انجام می‌شود.
       ================================================================= */
    $pResult['no_extract'] = true;
    $_neSel   = extractNormalizeDetailSelectors($profile['detailSelectors'] ?? []);
    $_neGal   = galleryNormalizeCfg($profile['gallery'] ?? []);
    $_neHasCfg = false;
    foreach ($_neSel as $_nsv) { if (!empty($_nsv)) { $_neHasCfg = true; break; } }
    if (!$_neHasCfg && !empty($_neGal['enabled'])) $_neHasCfg = true;
    // چند محصولِ روی دیسک لینکِ صفحهٔ محصول دارند؟
    $_neLinked = noExtractLinkedCount($profile);
    $_neDue    = $_neHasCfg && $_neLinked > 0 && noExtractRefreshOn($syncCfg);

    if ($_neDue) {
        $pResult['step'] = 'no_extract_detail';
        $pResult['detail_linked'] = $_neLinked;
        // فازِ detail: فقط صفحاتِ محصول باز می‌شوند، صفحهٔ فهرست هرگز
        $exRes = runBackendExtract($key, manualSyncActive() ? 'manual_sync' : 'auto', false, 'detail', false); /* v10.53 (۶۷): همگام‌سازیِ دستی ⇒ برچسبِ جدا در صف */
        if (!empty($exRes['ok'])) {
            $pResult['extracted']      = (int)($exRes['extracted'] ?? 0);
            $pResult['extract_method'] = 'no_extract_detail';
            $pResult['price_changed']  = (int)($exRes['price_changed'] ?? 0);
            $pResult['detail_done']    = (int)($exRes['detail_done'] ?? 0);
            if (!empty($exRes['ran_out'])) $pResult['detail_partial'] = true;
            // v10.21: تغییرِ موجودی هم در گزارشِ کران دیده شود
            if (!empty($exRes['stock_out']))  $pResult['stock_out']  = (int)$exRes['stock_out'];
            if (!empty($exRes['stock_back'])) $pResult['stock_back'] = (int)$exRes['stock_back'];
            /* اعلانِ گران/ارزان و موجود/ناموجود شدن — همان مسیرِ پروفایل‌های
               عادی. تا حالا پروفایل‌های اکسل/CSV هیچ اعلانی نمی‌گرفتند. */
            $srcN = notifSourceChanges($cn, $exRes, $profile['name'] ?? $key);
            if (!empty($srcN['sent'])) $pResult['src_notified'] = $srcN['sent'];
            $profiles = loadProfiles();
            $profile  = $profiles[$key] ?? $profile;
        } else {
            $pResult['extract_error'] = $exRes['error'] ?? 'خطای نامشخص';
            notifRunFailure($cn, 'تازه‌سازی جزئیات', $profile['name'] ?? $key, $pResult['extract_error']);
            // شکستِ تازه‌سازی نباید جلوی ارسالِ دوره‌ای را بگیرد
            $exRes = ['ok'=>true,'extracted'=>0,'no_extract'=>true,
                      'new'=>0,'price_changed'=>0,'removed'=>0,'unchanged'=>0,
                      'new_items'=>[],'changed_items'=>[],'removed_items'=>[],
                      'price_up'=>0,'price_down'=>0];
        }
    } else {
        $pResult['step'] = 'no_extract';
        $pResult['extracted'] = 0;
        // چرا تازه‌سازی انجام نشد — سکوت باعث می‌شد کاربر نداند چه خبر است
        if (!noExtractRefreshOn($syncCfg))  $pResult['no_refresh_why'] = 'disabled';
        elseif (!$_neHasCfg)                $pResult['no_refresh_why'] = 'no_detail_selectors';
        elseif ($_neLinked === 0)           $pResult['no_refresh_why'] = 'no_product_links';
        // برای ارسالِ «فقط محصولاتِ موجود»، exRes را موفق و بدون تغییراتِ جدید بگذار
        $exRes = ['ok'=>true, 'extracted'=>0, 'no_extract'=>true,
                  'new'=>0,'price_changed'=>0,'removed'=>0,'unchanged'=>0,
                  'new_items'=>[],'changed_items'=>[],'removed_items'=>[],
                  'price_up'=>0,'price_down'=>0];
    }
    // گیتِ ارسال را باز کن: در حافظه (نه روی دیسک) نشانه را complete بگذار
    $profile['_extract_stage'] = 'complete';
    $profile['_extract_stage_at'] = time();
} else {
/* v8.94: مرحلهٔ جزئیاتِ نیمه‌کاره را اول تمام کن، بعد سراغ ارسال برو.

   اگر اجرای قبلی وسط فاز جزئیات کشته شده باشد، محصولات روی دیسک هستند
   ولی نیمی‌شان هنوز گالری ندارند. در آن حالت این نوبت فقط استخراج را
   دوباره اجرا می‌کند تا جزئیات کامل شود و ارسال یک نوبت صبر می‌کند؛
   وگرنه محصول بدون عکس به مقصد می‌رفت.

   این بررسی باید «قبل» از اجرای استخراج انجام شود، چون خودِ استخراج در
   پایانش نشانه را روی complete می‌گذارد و بعد از آن دیگر چیزی برای
   تشخیص باقی نمی‌ماند. */
$stagePrev   = (string)($profile['_extract_stage'] ?? '');
$stagePrevAge = time() - (int)($profile['_extract_stage_at'] ?? 0);
$stageStale  = max(120, (int)($cn['stall_after'] ?? 300));
$detailWasUnfinished = in_array($stagePrev, ['list_done', 'detail'], true)
                       && $stagePrevAge <= $stageStale;

/* v9.01: کران سه گام جدا برمی‌دارد — فهرست، جزئیات، ارسال.

   خواستهٔ کاربر: «بعد از استخراج خودکار، دکمهٔ استخراج تفصیلی اجرا شود
   و بعد برود سراغ ارسال». همان کاری که خودش دستی می‌کند.

   چرا جدا بهتر است: مرحلهٔ جزئیات برای هر محصول یک درخواست HTTP می‌زند
   و طولانی‌ترین بخش کار است. وقتی در گام خودش اجرا شود، هر گام کوتاه‌تر
   از سقف زمانی هاست می‌ماند و اگر یکی نیمه‌کاره ماند، بقیه از دست
   نمی‌روند. ترتیب هم تضمین می‌شود: هیچ محصولی بدون گالری فرستاده نمی‌شود.

   گام ۱ فقط وقتی اجرا می‌شود که مرحلهٔ قبلی تمام شده باشد؛ اگر اجرای
   قبلی وسط جزئیات مانده، مستقیم همان را ادامه می‌دهیم. */
/* v9.73: رفعِ نهاییِ «استخراج خودکار جزئیات» در کران.
   کران «هیچ‌وقت» فاز جزئیات را خودکار اجرا نمی‌کند — فقط «list» (فهرستِ تازه +
   ذخیرهٔ محصولات). جزئیاتِ ازقبل‌ذخیره‌شده سر جایش می‌ماند.

   چرا «همیشه list» و نه «ادامهٔ detail»:
   قبلاً اگر اجرای قبلی وسطِ جزئیات ناتمام مانده بود (stage=detail تازه) کران
   همان را ادامه می‌داد. ولی برای کاتالوگِ بزرگ، فازِ جزئیات در هر نوبت از سقفِ
   زمانی هاست می‌ماند و $_ranOut در پایان دوباره stage=detail تازه می‌گذاشت —
   یعنی کران در هر فراخوانیِ بعدی باز هم detail اجرا می‌کرد: یک حلقهٔ بی‌پایانِ
   «استخراج تفصیلی در هر کران» که دقیقاً همان چیزی بود که گزارش می‌شد.

   v9.74: خواستهٔ کاربر — «جزئیات باید بعد از فهرست، فقط برای محصولاتِ جدید یا
   محصولاتِ بدونِ جزئیات اجرا شود». پس کران حالا فازِ «all» را اجرا می‌کند:
   اول فهرستِ تازه را می‌گیرد و بعد همان اجرا جزئیاتِ فقطِ «ناقص‌ها» را باز
   می‌کند (بلوکِ درجای جزئیات فقط برای محصولی که گالری/فیلد ندارد یا تازه‌است).
   محصولاتِ ازقبل‌کامل دوباره باز نمی‌شوند، پس دیگر «هر کران همهٔ جزئیات» نیست.
   اگر اجرای قبلی وسطِ جزئیات کشته شده باشد (stage=detail تازه)، مستقیم همان را
   با فازِ detail ادامه می‌دهیم (بدون گرفتن دوبارهٔ فهرست). */
$stepMode = ($stagePrev === 'detail' && $stagePrevAge <= $stageStale) ? 'detail' : 'all';
/* v10.81: قبل از extract خودکار، موانع کهنهٔ همین پروفایل را بردار — مثل دکمهٔ بک‌اند */
try {
    extractClearStaleBlockers((string)$key, [
        'max_idle' => max(120, (int)($cn['stall_after'] ?? 300)),
        'clear_waiting' => false,
        'reason' => 'پاک‌سازی پیش از extract خودکار',
    ]);
} catch (Throwable $_preEx) {}
$exRes = runBackendExtract($key, manualSyncActive() ? 'manual_sync' : 'auto', false, $stepMode); /* v10.53 (۶۷) / v10.81 */
$pResult['step'] = $stepMode;

/* v9.67: «استخراج تفصیلیِ جداگانه» در هر اجرای کران حذف شد.
   کاربر قبلاً کران را طوری تنظیم کرده بود که با هر فراخوانی، استخراج
   تفصیلی هم انجام دهد. آن تنظیم (استخراج دورهای جزئیات) حذف شده، ولی
   این گامِ جداگانه هنوز در هر اجرا جزئیات را صدا می‌زد — همان چیزی که
   گزارش شد. حالا جزئیات به‌صورت درجا و هم‌زمان با استخراج هر محصول در
   خودِ runBackendExtract گرفته می‌شود (v9.44)، پس این گذرِ جداگانهٔ
   «جزئیات بعد از هر فهرست» برداشته می‌شود تا کران فقط فهرست را بگیرد و
   برود سراغ ارسال. فقط اگر اجرای قبلی وسط فاز جزئیات نیمه‌کاره مانده
   باشد ($stagePrev == detail) همان را ادامه می‌دهیم تا محصولِ ناقص ارسال
   نشود — این ادامهٔ کارِ ناتمام است، نه استخراج دوره‌ای. */
if ($stepMode === 'list') {
    // (گامِ جداگانهٔ جزئیات حذف شد — فقط پروفایلِ تازه‌شده را دوباره می‌خوانیم)
    $profiles = loadProfiles();
    $profile  = $profiles[$key] ?? $profile;
}
if (!empty($exRes['ok'])) {
$pResult['extracted'] = (int)($exRes['extracted'] ?? 0);
$pResult['extract_method'] = 'backend_extract';
$pResult['new'] = (int)($exRes['new'] ?? 0);
$pResult['price_changed'] = (int)($exRes['price_changed'] ?? 0);
$pResult['removed'] = (int)($exRes['removed'] ?? 0);
if (!empty($exRes['ran_out']) || !empty($exRes['resume_needed'])) {
    $pResult['extract_resume'] = true;
    $pResult['detail_done'] = (int)($exRes['detail_done'] ?? 0);
    $pResult['detail_total'] = (int)($exRes['detail_total'] ?? 0);
    $pResult['note'] = 'جزئیات نیمه‌تمام — نوبت بعد ادامه ('
        . (int)($exRes['detail_done'] ?? 0) . '/' . (int)($exRes['detail_total'] ?? 0) . ')';
}
if (!empty($exRes['partial']) || !empty($exRes['cancelled'])) {
    $pResult['extract_partial'] = true;
}
// v8.30: گران/ارزان و موجود/ناموجود شدن سایت مبدأ را اطلاع بده
$srcN = notifSourceChanges($cn, $exRes, $profile['name'] ?? $key);
if (!empty($srcN['sent'])) $pResult['src_notified'] = $srcN['sent'];

// v8.34: محصولاتی که از مبدأ رفته‌اند را روی مقصد بازنشسته کن
/* =================================================================
   v10.34 (۴۸الف): تیکِ «افزودن/آپدیت» خودش بازنشستگی را روشن می‌کند.

   خواستهٔ کاربر: با تیکِ روشن، چرخه باید «افزودن/آپدیت/بایگانی» برای
   باسلام و «افزودن/آپدیت/حذف» برای ووکامرس باشد. تا اینجا بازنشستگی
   فقط به تنظیمِ سراسریِ retire_mode بند بود که پیش‌فرضش off است، پس
   نیمهٔ سومِ کار عملاً هیچ‌وقت اجرا نمی‌شد مگر کاربر جای دیگری هم
   تنظیمش می‌کرد. حالا تیکِ همان مقصد کافی است.

   مقصدِ بازنشستگی هم محدود می‌شود به همان مقصدهایی که تیکشان روشن
   است: اگر فقط تیکِ باسلام روشن باشد، نباید چیزی از ووکامرس حذف شود.
   محافظِ ۳۰٪/۵۰ مورد سرِ جایش می‌ماند و هر اقدام لاگ و گزارش می‌شود.
   ================================================================= */
/* v10.101: همگام خودکار — بایگانی/حذف ناموجود و حذف‌شده‌های مبدأ (مثل دستی) */
if (!empty($exRes['ok']) && empty($exRes['ran_out']) && empty($exRes['resume_needed'])
    && empty($exRes['partial']) && (string)($exRes['guard'] ?? '') === '') {
$_retPack = retireAfterExtract($cn, $profile, $exRes, (string)$target, $syncCfg, (string)$key);
} else {
$_retPack = ['skipped' => !empty($exRes['ran_out']) ? 'extract_incomplete'
    : ((string)($exRes['guard'] ?? '') !== '' ? (string)$exRes['guard'] : 'extract_not_ready')];
}
if (!empty($_retPack['result'])) {
    $rt = $_retPack['result'];
    $pResult['retire'] = [
        'mode' => $_retPack['mode'],
        'target' => $_retPack['target'],
        'retired' => (int)($rt['retired'] ?? 0),
        'not_found' => (int)($rt['not_found'] ?? 0),
        'failed' => (int)($rt['failed'] ?? 0),
        'checked' => (int)($rt['checked'] ?? 0),
        'items' => count($_retPack['items'] ?? []),
        'oos_merged' => (int)($_retPack['oos_merged'] ?? 0),
        'woo_action' => $_retPack['woo_action'] ?? '',
        'bsl_action' => $_retPack['bsl_action'] ?? '',
        'auto' => true,
    ];
    if (!empty($_retPack['skipped'])) $pResult['retire']['skipped'] = $_retPack['skipped'];
} elseif (!empty($_retPack['skipped']) && $_retPack['skipped'] !== 'no_items') {
    $pResult['retire'] = ['skipped' => $_retPack['skipped'], 'auto' => true];
}

$profiles = loadProfiles();
$profile  = $profiles[$key] ?? $profile;
} else {
$pResult['extract_error'] = $exRes['error'] ?? 'خطای نامشخص';
notifRunFailure($cn, 'استخراج', $profile['name'] ?? $key, $pResult['extract_error']);
}
/* v10.67 (81): رابطِ همگام‌سازیِ دستی باید نتیجهٔ واقعیِ استخراج را ببیند.
   تا حالا وقتی استخراج رد می‌شد (ردیف تکراری در صف، قفلِ سراسری، یا
   هر خطایی)، جعبهٔ همگام‌سازی «تمام شد» نشان می‌داد ولی چیزی به صف
   استخراج نمی‌نشست و دلیل فقط به مسنجر می‌رفت — از دید کاربر دکمه
   «تقریباً هیچ کاری نمی‌کرد». حالا دلیلِ واقعی همین‌جاست. */
if (manualSyncActive()) {
    if (!empty($exRes['ok'])) {
        manualSyncProgress([], '✅ استخراج: ' . (int)($exRes['extracted'] ?? 0) . ' محصول ('
            . (int)($exRes['new'] ?? 0) . ' جدید، ' . (int)($exRes['price_changed'] ?? 0) . ' تغییرِ قیمت)');
    } else {
        $_exErr = mb_substr((string)($exRes['error'] ?? 'خطای نامشخص'), 0, 300);
        if (!empty($exRes['duplicate'])) {
            $_exErr .= ' — ردیف قبلی هنوز فعال است؛ اگر کهنه است دوباره همگام‌سازی بزنید';
        }
        if (!empty($exRes['locked'])) {
            $_exErr .= ' — قفل استخراج مشغول است';
        }
        manualSyncProgress([], '❌ استخراج: ' . $_exErr);
    }
}
}   // پایانِ else حالتِ عادی (مقابل noExtract) — v9.45

// Now get products from profile (either freshly scraped or previously saved)
// v8.39: اگر تیک «افزودن/آپدیت» فعال باشد، فقط محصولات جدید و
// تغییرکرده فرستاده می‌شوند نه کل فهرست.
$wooOnlyChanged = !empty($syncCfg['wooAddUpdate']);
$bslOnlyChanged = !empty($syncCfg['bslAddUpdate']);
$changedKeys = ($wooOnlyChanged || $bslOnlyChanged) ? syncChangedKeys($exRes ?? []) : null;
/* v9.45: در پروفایلِ بدون-استخراج، هیچ مقایسه‌ای با مبدأ نیست که بگوییم کدام
   محصول «تغییر کرده». پس فیلتر «فقط تغییرات» را کنار بگذار و همهٔ محصولاتِ موجود
   را بفرست تا قیمت و موجودی‌شان دوره‌ای به‌روز شود — این دقیقاً خواستهٔ کاربر
   برای پروفایل‌های اکسل/CSV است. */
if (!empty($noExtract)) $changedKeys = null;

// v8.58: اگر استخراج انجام نشده باشد، فهرست تغییرات وجود ندارد.
// تا اینجا در آن حالت فیلتر کنار گذاشته می‌شد و «کل» محصولات دوباره
// فرستاده می‌شد — یعنی تیک «افزودن/آپدیت» دقیقاً در همان پروفایل‌هایی
// که استخراجشان شکست می‌خورد (سلکتور ذخیره‌نشده، ردیف جامانده در صف،
// سایت مبدأ خراب) بی‌اثر می‌شد. این همان «بعضی پروفایل‌ها توجهی نمی‌کنند»
// بود. تیک یعنی «فقط تغییرات»؛ وقتی تغییری معلوم نیست، چیزی هم نباید برود.
$extractOk = !empty($exRes['ok']);
if (($wooOnlyChanged || $bslOnlyChanged) && !$extractOk) {
    $changedKeys = [];                       // فهرست خالی = چیزی برای ارسال نیست
    $pResult['add_update_hold'] = $pResult['extract_error'] ?? 'استخراج انجام نشد';
}

// v8.44: اگر ضریب/درصد قیمت یا پسوند عنوان دستی عوض شده باشد، قیمت
// «همهٔ» محصولات عوض شده — حتی آن‌هایی که سایت مبدأ تغییرشان نداده.
// در این حالت فیلتر «فقط تغییرات» باید یک بار کنار گذاشته شود، وگرنه
// قیمت جدید هیچ‌وقت به ووکامرس و باسلام نمی‌رسد.
$priceSig  = profilePriceSignature($profile);
$lastSig   = (string)($syncState[$key]['price_sig'] ?? '');
$pricingChanged = ($lastSig !== '' && $lastSig !== $priceSig);
if ($pricingChanged && $changedKeys !== null) {
    $changedKeys = null;                    // این بار همه را بفرست
    $pResult['pricing_changed'] = true;
    $pResult['pricing_from'] = $lastSig;
    $pResult['pricing_to'] = $priceSig;
}

/* =====================================================================
   v10.34 (۴۸ب): ضریبِ تعدیلِ مقصد یا غرفه هم که عوض شود، «همهٔ» محصولاتِ
   ذخیره‌شده باید یک نوبت با دستورِ آپدیت به ووکامرس و باسلام بروند.

   v8.44 همین کار را برای ضریبِ پروفایل می‌کرد، ولی دو لایهٔ دیگر را
   نمی‌دید: تعدیلِ مخصوصِ مقصد (تنظیماتِ ووکامرس/باسلام) و تعدیلِ مخصوصِ هر
   غرفه. کاربر درصدِ یک غرفه را عوض می‌کرد، مبدأ هیچ تغییری نداشت، پس
   syncChangedKeys خالی برمی‌گشت و قیمتِ تازه هرگز ارسال نمی‌شد.

   دو کارِ همزمان انجام می‌شود:
     • فیلترِ «فقط تغییرات» یک نوبت کنار می‌رود (کلِ کاتالوگ صف می‌شود).
     • پرشِ دفترچهٔ باسلام (bslSkipUnchanged) هم برای همان نوبت خاموش
       می‌شود، وگرنه دفترچه می‌گفت «قیمت همان است» و PATCH نمی‌رفت —
       دقیقاً همان قیمتی که خودمان محاسبه کرده‌ایم، نه قیمتِ تازه.
   ===================================================================== */
$shopSig     = shopPricingSignature($cn);
$lastShopSig = (string)($syncState[$key]['shop_sig'] ?? '');
$shopPricingChanged = ($lastShopSig !== '' && $lastShopSig !== $shopSig);
if ($shopPricingChanged) {
    $changedKeys = null;                    // کلِ کاتالوگ، با دستورِ آپدیت
    $pResult['shop_pricing_changed'] = true;
    $pResult['shop_pricing_from'] = $lastShopSig;
    $pResult['shop_pricing_to']   = $shopSig;
}

/* v8.94: دروازهٔ ارسال — مرحلهٔ جزئیات باید تمام شده باشد.

   دو حالت جلوی ارسال را می‌گیرند:

   ۱) اجرای قبلی وسط فاز جزئیات کشته شده بود ($detailWasUnfinished که
      «قبل» از استخراج این نوبت سنجیده شد). همین نوبت جزئیات را کامل
      کرد، ولی محافظه‌کارانه یک نوبت صبر می‌کنیم تا نتیجه تثبیت شود.
   ۲) خودِ همین نوبت وسط فاز جزئیات مانده — یعنی استخراج تمام نشده و
      نشانه هنوز روی list_done یا detail است.

   بدون این دروازه، محصولاتی که هنوز گالری نگرفته‌اند به مقصد می‌رفتند و
   محصول بی‌عکس در فروشگاه می‌نشست. */
$stageNow   = (string)($profile['_extract_stage'] ?? '');
$stageAge   = time() - (int)($profile['_extract_stage_at'] ?? 0);
$stageStale = max(120, (int)($cn['stall_after'] ?? 300));
/* v9.67: دیگر بعد از گامِ فهرست، «list_done» باعث توقف ارسال نشود — چون گامِ
   جداگانهٔ جزئیات از کران حذف شده و در حالت عادی مرحله «list_done» می‌ماند.
   دروازه فقط وقتی بسته می‌شود که واقعاً وسطِ فاز جزئیات مانده باشیم
   ($stageNow==='detail' و تازه) تا محصولِ نیمه‌کاره فرستاده نشود. */
$stageOpen  = $stageNow === 'detail' && $stageAge <= $stageStale;

/* v9.01: حالا که کران خودش گام جزئیات را اجرا می‌کند، معیار فقط وضعیت
   «همین لحظه» است. اگر مرحلهٔ جزئیات واقعاً تمام شده (complete یا
   detail_done)، دلیلی برای معطل کردن ارسال نیست — حتی اگر اجرای قبلی
   نیمه‌کاره مانده بود، چون همین نوبت تمامش کرد. */
if ($stageOpen) {
    $pResult['status'] = 'detail_pending';
    $pResult['detail_done']  = (int)($profile['_extract_detail_done'] ?? 0);
    $pResult['detail_total'] = (int)($profile['_extract_detail_total'] ?? 0);
    $pResult['note'] = 'مرحلهٔ جزئیات هنوز تمام نشده — ارسال در نوبت بعدی';
    if (!isset($syncState[$key])) $syncState[$key] = [];
    $syncState[$key]['status']    = 'detail_pending';
    $syncState[$key]['price_sig'] = profilePriceSignature($profile);
    $results['profiles'][] = $pResult;
    continue;
}
// نشانهٔ بی‌حرکتِ جامانده: اجرایش مرده، با همین چیزی که هست جلو می‌رویم
if (in_array($stageNow, ['list_done', 'detail'], true)) $pResult['detail_stalled'] = $stageAge;

$orderedProducts = profileOrderedProducts($profile);
$changedProducts = $changedKeys === null
    ? $orderedProducts
    : profileOrderedProducts($profile, $changedKeys);

/* =====================================================================
   v10.34 (۴۸ج): «ارسالِ کامل بدون مقایسه» وقتی تیک خاموش است.

   تیکِ افزودن/آپدیت خاموش یعنی خواستهٔ کاربر «همهٔ محصولات کامل ارسال
   شوند، بدون مقایسه با محصولاتِ موجود در غرفه‌های باسلام». تا اینجا نیمی
   از این خواسته اجرا می‌شد: کلِ کاتالوگ صف می‌شد، ولی دفترچهٔ نگاشتِ
   v10.33 همچنان می‌گفت «قیمت و موجودی همان است» و PATCH را می‌انداخت.
   نتیجه: ارسالِ «کامل» عملاً چند ده محصول را بی‌صدا رد می‌کرد.

   حالا خاموش‌بودنِ تیک (یا عوض‌شدنِ ضرایبِ مقصد/غرفه) یک نشانهٔ force_all
   در ردیفِ صف می‌گذارد و ارسال‌کننده با دیدنش هر پرشِ مبتنی بر مقایسه را
   کنار می‌گذارد. */
$wooForceAll = (!$wooOnlyChanged) || $shopPricingChanged;
$bslForceAll = (!$bslOnlyChanged) || $shopPricingChanged;

if ($changedKeys !== null) {
    $pResult['changed_only'] = count($changedProducts);
    $pResult['catalog_size'] = count($orderedProducts);
}

manualSyncProgress(['phase' => 'صف‌سازی و ارسال', 'current' => 2],
    '📤 آمادهٔ ارسال: ' . count($changedProducts) . ' از ' . count($orderedProducts));   // v10.35 (۴۷ه)

if ($target === 'woo' || $target === 'both') {
// v8.21: Queue products for WooCommerce (not just set sync state)
// v8.39: با تیک «افزودن/آپدیت ووکامرس» فقط تغییرات ارسال می‌شود
$wooSend = $wooOnlyChanged ? $changedProducts : $orderedProducts;
if(!empty($wooSend)){
$wooSuffix=trim($profile['titleSuffix']??'') ?: trim($cn['basalam']['title_suffix']??'');
// v8.56: دستهٔ ووکامرس این پروفایل، وگرنه دستهٔ پیش‌فرض تنظیمات عمومی
$wooCatId=(int)($profile['wooCategoryId']??0);
if($wooCatId<=0)$wooCatId=(int)($cn['woocommerce']['default_category']??0);
$wooQueue=wooReadQueue();
// v8.55: همین پروفایل اگر در صف ووکامرس هست، دوباره اضافه نشود
$wooDup=queueDedupOn($cn)?queueHasProfile($wooQueue['entries'],$key,queueDedupStale($cn)):null;
if($wooDup!==null){
/* v10.51 (۶۵): همان قواعدِ جایگزینیِ ردیفِ کهنه، برای صفِ ووکامرس */
if(queueCfgChanged($wooDup['config']??null,
        ['title_suffix'=>$wooSuffix,'category_id'=>$wooCatId,'force_all'=>$wooForceAll])
    && in_array((string)($wooDup['status']??''),['waiting','paused'],true)){
foreach($wooQueue['entries'] as &$_qe){
if(is_array($_qe)&&($_qe['id']??'')===($wooDup['id']??'')){
$_qe['status']='failed';$_qe['done_at']=time();
$_qe['fail_reason']='تنظیماتِ ارسال تغییر کرد — با ردیفِ جدید جایگزین شد';
}}
unset($_qe);
wooWriteQueue($wooQueue);
$pResult['woo_superseded']=true;
$wooDup=null;
}
}
if($wooDup!==null){
$pResult['woo']='already_queued';
$pResult['woo_queue_id']=$wooDup['id']??'';
}else{
$wooQueueId='cron_woo_'.$key.'_'.$now;
// v8.36: فایل مخصوص همین اجرا — قبلاً همه روی WOO_PRODUCTS_FILE می‌نوشتند
// و اجرای بعدی محصولات اجرای قبلی را می‌فرستاد.
$wooQFile=__DIR__.'/woo_queue_products_'.$wooQueueId.'.json';
@file_put_contents($wooQFile,json_encode($wooSend,JSON_UNESCAPED_UNICODE),LOCK_EX);
// v8.56: در یک اجرای کران ممکن است چند پروفایل صف شوند. قبلاً همه با
// وضعیت «running» ثبت می‌شدند و هرکدام روی فایل مشترک می‌نوشتند؛ نتیجه
// این بود که محصولاتِ آخرین پروفایل با تنظیماتِ اولین پروفایل ارسال
// می‌شد (از جمله دستهٔ اشتباه). فقط یک ردیف در هر لحظه running است.
$wooBusy=false;
foreach($wooQueue['entries'] as $qe0){if(($qe0['status']??'')==='running'){$wooBusy=true;break;}}
$wooStatus=$wooBusy?'waiting':'running';
if($wooStatus==='running'){
@file_put_contents(WOO_PRODUCTS_FILE,json_encode($wooSend,JSON_UNESCAPED_UNICODE),LOCK_EX);
}
$wooQueue['entries'][]=['id'=>$wooQueueId,'status'=>$wooStatus,'products_file'=>$wooQFile,'total'=>count($wooSend),'sent'=>0,'updated'=>0,'skipped'=>0,'failed'=>0,'current'=>0,'started_at'=>$wooStatus==='running'?$now:0,'done_at'=>0,'profile_key'=>$key,'profile_name'=>($profile['name']??$key),'only_changed'=>$wooOnlyChanged,'trigger'=>(manualSyncActive()?'manual_sync':'cron'),/* v10.53 (۶۷) */'config'=>['title_suffix'=>$wooSuffix,'category_id'=>$wooCatId,'force_all'=>$wooForceAll]];
wooWriteQueue($wooQueue);
$pResult['woo']='queued';$pResult['woo_total']=count($wooSend);$pResult['woo_status']=$wooStatus;
}
} else { $pResult['woo'] = $wooOnlyChanged ? 'no_changes' : 'no_products'; }
/* v9.11: کلیدهای دیگرِ همین پروفایل نباید پاک شوند. این انتساب کل
   ردیف را جایگزین می‌کرد و detailLastRun (زمان‌بندی استخراج دوره‌ای
   جزئیات) را می‌انداخت — یعنی دورهٔ آن هر بار از صفر شروع می‌شد. */
$syncState[$key]=array_merge(is_array($syncState[$key]??null)?$syncState[$key]:[],['lastRun'=>$now,'status'=>'running_woo','price_sig'=>$priceSig]);
}
if ($target === 'bsl' || $target === 'both') {
// v8.39: با تیک «افزودن/آپدیت باسلام» فقط تغییرات ارسال می‌شود
$bslSend = $bslOnlyChanged ? $changedProducts : $orderedProducts;
if (!empty($bslSend)) {
$queueId = 'cron_' . $key . '_' . $now;
$qFile = __DIR__ . '/bsl_queue_products_' . $queueId . '.json';
if (@file_put_contents($qFile, json_encode($bslSend, JSON_UNESCAPED_UNICODE), LOCK_EX)) {
$catId = (int)($cn['basalam']['category_id'] ?? 0);
$autoCat = !empty($cn['basalam']['auto_category']);
$titleSuffix = trim($profile['titleSuffix'] ?? '') ?: trim($cn['basalam']['title_suffix'] ?? '');
$delayMs = max(0, (int)($cn['basalam']['delay_ms'] ?? 500));
$retryDelayMs = max(0, (int)($cn['basalam']['retry_delay_ms'] ?? 1000));
$fallbackCats = $cn['basalam']['fallback_cat_ids'] ?? [];
$profileCatId = (int)($profile['bslCategoryId'] ?? 0);
if ($profileCatId > 0) $catId = $profileCatId;
$profileFallbackCats = $profile['bslFallbackCatIds'] ?? [];
$allFallbackCats = array_values(array_unique(array_merge($profileFallbackCats, $fallbackCats)));
$queue = bslReadQueue();
// v8.55: از ورود دوبارهٔ همین پروفایل به صف باسلام جلوگیری کن
$bslDup = queueDedupOn($cn) ? queueHasProfile($queue['entries'], $key, queueDedupStale($cn)) : null;
if ($bslDup !== null) {
    /* v10.51 (۶۵): اگر تنظیماتِ اثرگذار بر ارسال عوض شده باشند — مهم‌تر
       از همهٔ پسوندِ عنوان — ردیفِ قدیمیِ منتظر/توقف‌خورده دیگر معتبر
       نیست و نباید جلوی ردیفِ جدید را بگیرد؛ وگرنه کاربر پسوند را درست
       می‌کند، در «نتایج» درست دیده می‌شود، ولی ارسال تا صف خالی شود با
       همان پسوندِ کهنهٔ ذخیره‌شدهٔ ردیفِ قدیمی ادامه می‌یابد. ردیفِ در
       حالِ اجرا دست نمی‌خورد (با تنظیماتی که شروع کرده تمام می‌کند). */
    if (queueCfgChanged($bslDup['config'] ?? null,
            ['title_suffix' => $titleSuffix, 'category_id' => $catId, 'auto_category' => $autoCat,
             'force_all' => $bslForceAll, 'send_all_shops' => !empty($cn['basalam']['send_all_shops'])])
        && in_array((string)($bslDup['status'] ?? ''), ['waiting', 'paused'], true)) {
        foreach ($queue['entries'] as &$_qe) {
            if (is_array($_qe) && ($_qe['id'] ?? '') === ($bslDup['id'] ?? '')) {
                $_qe['status'] = 'failed';
                $_qe['done_at'] = time();
                $_qe['fail_reason'] = 'تنظیماتِ ارسال تغییر کرد — با ردیفِ جدید جایگزین شد';
            }
        }
        unset($_qe);
        bslWriteQueue($queue);
        $pResult['bsl_superseded'] = true;
        $bslDup = null;
    }
}
if ($bslDup !== null) {
    @unlink($qFile);
    $pResult['bsl'] = 'already_queued';
    $pResult['bsl_queue_id'] = $bslDup['id'] ?? '';
} else {
/* v10.73 (87): همان fan-outِ مسیرِ دستی — هر غرفهٔ فعال یک ردیفِ مستقل.
   ردیفِ اول با شناسهٔ اصلی و بقیه با پسوند _s{vendor_id}؛ همه زیرِ batch_id. */
$bslFanout=!empty($cn['basalam']['send_all_shops'])?bslFanoutShops($cn):[];
if (count($bslFanout) > 1) {
    $__bfFirst=true;
    foreach ($bslFanout as $__bfSh) {
        $__bfVid=(int)$__bfSh['vendor_id'];
        $queue['entries'][] = ['id' => $__bfFirst ? $queueId : $queueId . '_s' . $__bfVid, 'status' => 'waiting', 'products_file' => $qFile, 'total' => count($bslSend), 'sent' => 0, 'updated' => 0, 'skipped' => 0, 'failed' => 0, 'current' => 0, 'started_at' => 0, 'done_at' => 0, 'paused_at' => 0, 'only_changed' => $bslOnlyChanged, 'config' => ['category_id' => $catId, 'auto_category' => $autoCat, 'title_suffix' => $titleSuffix, 'delay_ms' => $delayMs, 'retry_delay_ms' => $retryDelayMs, 'fallback_cat_ids' => $allFallbackCats, 'send_all_shops' => 0, 'fanout' => 1, 'shop_vendor_id' => $__bfVid, 'shop_name' => (string)$__bfSh['shop_name'], 'force_all' => $bslForceAll], 'profile_key' => $key, 'profile_name' => $profile['name'] ?? $key, 'shop_vendor_id' => $__bfVid, 'shop_name' => (string)$__bfSh['shop_name'], 'shop_is_default' => !empty($__bfSh['is_default']), 'batch_id' => $queueId, 'trigger' => (manualSyncActive() ? 'manual_sync' : 'cron'), 'auto_sync' => true];
        $__bfFirst=false;
    }
} else {
$queue['entries'][] = ['id' => $queueId, 'status' => 'waiting', 'products_file' => $qFile, 'total' => count($bslSend), 'sent' => 0, 'updated' => 0, 'skipped' => 0, 'failed' => 0, 'current' => 0, 'started_at' => 0, 'done_at' => 0, 'paused_at' => 0, 'only_changed' => $bslOnlyChanged, 'config' => ['category_id' => $catId, 'auto_category' => $autoCat, 'title_suffix' => $titleSuffix, 'delay_ms' => $delayMs, 'retry_delay_ms' => $retryDelayMs, 'fallback_cat_ids' => $allFallbackCats, /* v10.21 (۳۴ب): سینکِ خودکار هم باید به همهٔ غرفه‌های فعال بفرستد. تا حالا این کلید فقط از مسیرِ دکمهٔ دستی وارد صف می‌شد، پس ارسالِ چندغرفه‌ای در کران هرگز اجرا نمی‌شد — تیک روشن بود ولی شب‌ها فقط غرفهٔ پیش‌فرض به‌روز می‌شد. v10.73 (87): وقتی چند غرفهٔ فعال است، fan-outِ بالا هرکدام را یک ردیف می‌کند و این شاخه برایِ غرفهٔ تکی می‌ماند. */ 'send_all_shops' => !empty($cn['basalam']['send_all_shops']), /* v10.34 (۴۸ج): تیکِ خاموش ⇒ ارسالِ کامل بدون مقایسه با غرفه */ 'force_all' => $bslForceAll], 'profile_key' => $key, 'profile_name' => $profile['name'] ?? $key, /* v10.53 (۶۷): منشأِ ردیف (دستی/خودکار) تا در تبِ ارسال هم دیده شود */ 'trigger' => (manualSyncActive() ? 'manual_sync' : 'cron'), 'auto_sync' => true];
}
bslWriteQueue($queue);
$syncState[$key] = array_merge(is_array($syncState[$key] ?? null) ? $syncState[$key] : [], ['lastRun' => $now, 'status' => 'queued_bsl', 'price_sig' => $priceSig]);   // v9.11
$pResult['bsl'] = 'queued'; $pResult['bsl_total'] = count($bslSend);
}
} else { $pResult['bsl'] = 'file_save_error'; }
} else { $pResult['bsl'] = $bslOnlyChanged ? 'no_changes' : 'no_products'; }
}
// v8.44: امضای قیمت را در هر حالت ثبت کن تا ارسال کامل فقط یک بار
// تکرار شود، نه در هر اجرای بعدی.
if (!isset($syncState[$key])) $syncState[$key] = ['lastRun' => $now, 'status' => 'idle'];
$syncState[$key]['price_sig'] = $priceSig;
/* v10.34 (۴۸ب): امضای ضرایبِ مقصد/غرفه هم ثبت شود تا ارسالِ کاملِ ناشی از
   تغییرِ ضریب فقط یک نوبت اجرا شود، نه در هر اجرای بعدی. */
$syncState[$key]['shop_sig'] = $shopSig;
/* =====================================================================
   v10.35 (۴۷د): گزارشِ کاملِ همین پروفایل — یک بار ثبت، یک بار ارسال.

   جای درستش دقیقاً همین‌جاست: بعد از اینکه استخراج، بازنشستگی و صف‌سازی
   هر سه تصمیمشان را گرفته‌اند، ولی هنوز داخلِ حلقه‌ایم و $pResult کامل
   است. اگر بیرونِ حلقه می‌گذاشتیم، اجرایی که وسطِ پروفایلِ دوم کشته
   می‌شود هیچ گزارشی از پروفایلِ اول هم نمی‌داد. */
try {
    $_sr = syncReportBuild($pResult, manualSyncActive() ? 'manual' : 'cron', (int)$now);
    $_srRes = syncReportEmit($cn, $_sr);
    $pResult['report'] = ['logged' => (int)($_srRes['logged'] ?? 0)]
        + (!empty($_srRes['skipped']) ? ['skipped' => $_srRes['skipped']] : []);
    manualSyncProgress(['phase' => 'گزارش', 'current' => 3,
        'summary' => mb_substr(syncReportText($_sr), 0, 400)],
        '📄 گزارش ثبت و ارسال شد');
} catch (Throwable $e) {
    $pResult['report'] = ['error' => mb_substr($e->getMessage(), 0, 160)];
}
$results['profiles'][] = $pResult;
}
saveSyncState($syncState);

/* v8.97: نگهبان قبل از حلقه اجرا شد؛ این اجرای دوم برای چیزهایی است که
   «در همین نوبت» گیر کرده‌اند (مثلاً ارسالی که همین حالا صف شد و
   نگرفت). نتیجهٔ اجرای اول را پاک نمی‌کند. */
try {
    $wd = cronWatchdogs($cn);
    foreach ($wd as $k => $v) { if (!empty($v) && empty($results[$k])) $results[$k] = $v; }
} catch (Throwable $e) {
    $results['watchdog_error'] = mb_substr($e->getMessage(), 0, 200);
}

/* =====================================================================
   v10.58 (۷۲): ترتیبِ تازه — دو کارِ پرمهلت، بعد از حلقهٔ همگام‌سازی.

   گزارشِ کاربر: «همگام‌سازی‌های دوره‌ای اصلاً کار نمی‌کنند، دستی هم
   همین‌طور؛ هیچ‌کدام یک کارت/ردیف به صفِ استخراج نمی‌افزایند؛ فرانتِ
   کاربری و بک‌اند هماهنگ به نظر نمی‌رسند.»

   ریشه: پمپِ ارسال (منتظرِ تا ۱۲۰ ثانیه) و بکاپِ خودکار (git push،
   چند دقیقه) پیش از حلقهٔ همگام‌سازی اجرا می‌شدند. روی هاستی که
   پردژهٔ پس‌زمینه را می‌کُشد (همان هاست شما)، پردژه در همین پنجره
   می‌مرد و هرگز به حلقهٔ استخراج نمی‌رسید — پس نه کارتی به صفِ
   استخراج می‌نشست و همگام‌سازی از بیرون «مرده» به نظر می‌رسید.

   ترتیبِ تازه: قفل ← نبض ← اعلان ← پاسخِ خودکار ← نگهبان ←
   <b>حلقهٔ همگام‌سازی (کارت همین‌جا فوراً به صفِ استخراج می‌نشیند)</b>
   ← پمپِ ارسال ← بکاپ ← ایجنت/گزارش/پینگِ پایانی.

   حالا اگر پردژه کشته شود، بعد از استخراج کشته می‌شود: کارت در صف
   است، بخشِ انجام‌شده روی دیسک است، و نگهبان در تیکِ بعدی از
   چک‌پوینت ادامه می‌دهد.
   ===================================================================== */
/* v9.16: بکاپ خودکار — قبل از هر کاری که ممکن است داده را خراب کند.
   v10.58 (۷۲): جابجایی به بعد از حلقهٔ همگام‌سازی (سرِ مطلبِ بالا را ببینید).
   قبلاً بی‌درنگِ اولِ تیک بود؛ یک git push چنددقیقه‌ای پردژه را نگه می‌داشت
   (و بعد هاست می‌کُشتش) و به حلقهٔ استخراج هرگز نمی‌رسید. داده‌ها همین حالا
   روی دیسک ذخیره می‌شوند، پس امن است بکاپ به انتهای صف برود — مهم،
   استخراج است. */
$_bkCfg = backupCfg();
if (!empty($_bkCfg['auto'])) {
    $_bkDue = ($now - (int)$_bkCfg['last_run']) >= (max(1, (int)$_bkCfg['auto_every_h']) * 3600);
    if ($_bkDue) {
        $_bkRes = backupRun($_bkCfg);
        $results['backup'] = ['ok' => !empty($_bkRes['ok']),
            'files' => (int)($_bkRes['files'] ?? 0),
            'github' => (string)($_bkRes['github'] ?? '-')];
    }
}

/* v10.49 (۶۳): پمپِ ارسال — عمرِ همین دور را «ارسال» کنیم، نه استخراج.
   v10.58 (۷۲): جابجایی به بعد از حلقهٔ همگام‌سازی (سرِ مطلبِ بالا را ببینید).
   قبلاً پیش از استخراج می‌نشست و انتظارِ تا ۱۲۰ ثانیه‌اش تضمین می‌کرد که
   هاست پردژه را پیش از رسیدن به استخراج بکشد — همان «همگام‌سازی اصلاً
   کار نمی‌کند» که گزارش می‌شد. نقشش عوض نشد: اگر صفِ ارسال کارِ گیر دارد،
   چقدر که هاست اجازه بدهد جلویش می‌راند (چک‌پوینت پیشرفت را نگه می‌دارد).
   در همگام‌سازیِ دستی اجرا نمی‌شود: آنجا مرورگر وصل است و رابط خودش
   ارسال را با اتصالِ زنده راه می‌اندازد (msKickSend). */
if (!manualSyncActive()) {
    $_pumpBlocking = false;
    try {
        $_pumpStall = max(120, (int)($cn['stall_after'] ?? 300));
        foreach (cronWatchdogQueueOrder() as $_pq) {
            $_pqChk = queueStallCheck($_pq, $_pumpStall);
            if (empty($_pqChk['stalled'])) continue;
            $_pqRec = queueStallRecover($_pq, $_pumpStall, false, 120000);
            $results['send_pump'][$_pq] = [
                'from'    => (int)($_pqChk['current'] ?? 0),
                'total'   => (int)($_pqChk['total'] ?? 0),
                'resumed' => !empty($_pqRec['resumed']),
            ];
            $_pqAfter = queueStallCheck($_pq, $_pumpStall);
            $results['send_pump'][$_pq]['now'] = (int)($_pqAfter['current'] ?? 0);
            if (!empty($_pqRec['resumed'])) {
                /* این worker هم پاسخِ زودهنگام دارد؛ صفِ مقصدِ دیگر و همهٔ
                   کارهای پایین‌تر باید به تیکِ بعدی واگذار شوند. */
                $_pumpBlocking = true;
                break;
            }
            if (empty($_pqAfter['stalled'])) break;
        }
    } catch (Throwable $e) {
        $results['send_pump_error'] = mb_substr($e->getMessage(), 0, 200);
    }
    if ($_pumpBlocking) {
        $results['deferred_by_resume'] = true;
        cronEmit($results);
        exit;
    }
}

/* v10.05 (۱۹): زمان‌بندِ کارهای ایجنتی.

   چرا اینجا و نه بالاترِ کران: هر اجرای ایجنت ده‌ها ثانیه طول می‌کشد و
   ممکن است هاست وسطش پردازه را بکشد. اگر بالای کران می‌نشست، استخراج و
   ارسال و اعلان — که کارِ اصلیِ برنامه‌اند — قربانیِ یک کارِ هوش مصنوعی
   می‌شدند. پس آخر صف است: هرچه لازم است اول انجام شده، و اگر اینجا
   کشته شویم چیزی از دست نرفته و کارها در تیکِ بعدی سررسید می‌مانند. */
/* v10.83: تولید خودکار توضیح/دسته برای محصولاتِ بدون محتوا (همهٔ پروفایل‌ها) */
try {
    $_aiAuto = aiContentAutoCfg($cn);
    if (!empty($_aiAuto['enabled'])) {
        $results['ai_content_auto'] = aiAutoFillMissingAcrossProfiles($cn);
    }
} catch (Throwable $e) {
    $results['ai_content_auto'] = ['error' => mb_substr($e->getMessage(), 0, 200)];
}

try {
    $autoRes = autoTick($cn, $now);
    if (!empty($autoRes['ran'])) {
        $results['auto_agent'] = ['ran' => (int)$autoRes['ran'],
                                  'jobs' => $autoRes['jobs'] ?? []];
    } elseif (!empty($autoRes['locked'])) {
        $results['auto_agent'] = 'locked';
    }
} catch (Throwable $e) {
    $results['auto_agent'] = ['error' => $e->getMessage()];
}

/* v10.107: مغایرت‌گیری دوره‌ای همهٔ غرفه‌ها/ووکامرس + اصلاح دسته با AI/یادگیری */
try {
    if (function_exists('reconAutoTick')) {
        $results['recon_auto'] = reconAutoTick($cn, $now);
    }
} catch (Throwable $e) {
    $results['recon_auto'] = ['error' => mb_substr($e->getMessage(), 0, 200)];
}
try {
    if (function_exists('catfixAutoTick')) {
        $results['catfix_auto'] = catfixAutoTick($cn, $now);
    }
} catch (Throwable $e) {
    $results['catfix_auto'] = ['error' => mb_substr($e->getMessage(), 0, 200)];
}


// v8.62: گزارش شبانه — اگر ساعتش رسیده و امروز فرستاده نشده
try {
    $digRes = digestMaybeSend($cn, $now);
    if (!empty($digRes['sent'])) $results['digest'] = $digRes['totals'] ?? 'sent';
    elseif (!empty($digRes['skipped']) && $digRes['skipped'] !== 'not_due') $results['digest'] = $digRes['skipped'];
} catch (Throwable $e) {
    $results['digest'] = ['error' => mb_substr($e->getMessage(), 0, 200)];
}

// v8.37: پینگ — آخرین کار، تا خلاصهٔ همین اجرا را هم بتواند گزارش کند
/* v10.22 (۳۵ج): پینگِ پایانی هرگز نباید «نبض» شمرده شود.
   $results کلیدِ heartbeat را از ابتدای اجرا با خود حمل می‌کند و
   notifCronPing از روی همان تصمیم می‌گرفت چه متنی بسازد — پس گزارشِ
   پایانی هم «کران‌جاب شروع شد» می‌شد و شمارِ پروفایل‌ها و محصولات را
   حذف می‌کرد. یعنی کاربر حتی وقتی پیام می‌رسید، خلاصهٔ کار را نمی‌دید. */
$_pingResults = $results;
unset($_pingResults['heartbeat']);
try {
    $pingRes = notifCronPing($cn, $_pingResults);
    if (!empty($pingRes['sent'])) $results['ping'] = 'sent';
    elseif (!empty($pingRes['skipped'])) $results['ping'] = $pingRes['skipped'];
    elseif (!empty($pingRes['error']))   $results['ping'] = ['error' => $pingRes['error']];
} catch (Throwable $e) {
    $results['ping'] = ['error' => mb_substr($e->getMessage(), 0, 200)];
}

/* v8.92: در حالت پس‌زمینه پاسخ قبلاً فرستاده شده و اتصال بسته است.
   چاپ دوباره یعنی JSON دوتکه؛ خلاصه در فایل کران می‌نشیند تا مرورگر
   بعد از پایانِ رصد بتواند بخواندش.
   v9.06: حالا اتصال «همیشه» بسته است، پس همیشه همین مسیر است. خلاصه در
   cron_last_run.json می‌نشیند و با ?cron_last خوانده می‌شود. */
/* =====================================================================
   v10.50 (۶۴): ارسالِ همگام‌سازیِ دستی، کاملاً سرورساید.

   کارگرِ دستی پاسخش را از همان ابتدای اجرا فرستاده و در سرور زنده است؛
   کاربر می‌تواند تب را ببندد. از این‌جا تا پیش از «تمام شد»، اگر چیزی
   در صفِ ارسال مانده باشد، نوبت‌به‌نوبت پردازش می‌شود (هر نوبت یک
   درخواستِ فرزند با مهلتِ طولانی). اگر کارگر وسط راه بمیرد، پمپِ
   کرانِ v10.49 از همان چک‌پوینت برمی‌دارد.
   ===================================================================== */
/* v10.79: اگر only= کلید هیچ پروفایلی را نزد، صریح بگو — قبلاً silent no-op بود */
if (manualSyncActive() && $_onlyKey !== '') {
    $_matchedOnly = false;
    foreach ((array)($results['profiles'] ?? []) as $_rp) {
        if ((string)($_rp['key'] ?? '') === $_onlyKey) { $_matchedOnly = true; break; }
    }
    if (!$_matchedOnly) {
        $results['profiles'][] = [
            'key' => $_onlyKey, 'name' => $_onlyKey, 'status' => 'not_found',
            'error' => 'پروفایل با این کلید در حلقه اجرا نشد (کلید نامعتبر یا فیلتر only)',
        ];
        manualSyncProgress(['phase' => 'خطا'],
            '❌ پروفایل «' . mb_substr($_onlyKey, 0, 80) . '» در فهرست سرور اجرا نشد — کلید را از کشوی پروفایل دوباره انتخاب کنید');
    } elseif (count($results['profiles']) === 1) {
        $_one = $results['profiles'][0];
        if ((string)($_one['status'] ?? '') === 'sync_disabled') {
            manualSyncProgress([], '⚠️ همگام‌سازی این پروفایل در تنظیمات خاموش است — با force اجرا شد؟');
        }
        if (!empty($_one['extract_error'])) {
            manualSyncProgress([], '⚠️ علت استخراج: ' . mb_substr((string)$_one['extract_error'], 0, 200));
        }
        if (!empty($_one['add_update_hold'])) {
            manualSyncProgress([], '⚠️ ارسال متوقف: ' . mb_substr((string)$_one['add_update_hold'], 0, 200));
        }
    }
}

if (manualSyncActive() && empty($results['manual_stopped'])) {
    try {
        $_msSendRes = manualServerSendRun();
        if (!empty($_msSendRes['stopped'])) $results['manual_stopped'] = true;
        $results['ms_server_send'] = $_msSendRes;
    } catch (Throwable $e) {
        $results['ms_server_send'] = ['error' => mb_substr($e->getMessage(), 200)];
    }
}

/* v10.35 (۴۷ه): بستنِ ردیفِ همگام‌سازیِ دستی در مدیر وظیفه. باید *قبل* از
   cronEmit باشد، چون آن تابع در مسیرِ CLI چیزی چاپ می‌کند و بعدش exit. */
if (manualSyncActive()) {
    $_msDone = readProgress(MANUAL_SYNC_PROGRESS_FILE);
    $_msDone['running']   = false;
    $_msDone['done']      = true;
    $_msDone['cancelled'] = !empty($results['manual_stopped']);
    $_msDone['current']   = 3;
    $_msDone['phase']     = !empty($results['manual_stopped']) ? 'متوقف شد' : 'تمام شد';
    $_msDone['ts']        = time();
    $_msDone['last_progress_ts'] = time();
    $_msDone['profiles_done'] = count($results['profiles'] ?? []);
    $_lg = is_array($_msDone['recent_log'] ?? null) ? $_msDone['recent_log'] : [];
    $_lg[] = !empty($results['manual_stopped']) ? '⏹ با درخواستِ کاربر متوقف شد' : '✅ همگام‌سازیِ دستی تمام شد';
    /* v10.49 (۶۳): اگر چیزی به صفِ ارسال رفته، کاربر همان‌جا ببیند —
       و رابط (msKickSend) بلافاصله ارسال را با اتصالِ مرورگر می‌کوبد. */
    $_msQPending = 0;
    foreach (['باسلام' => bslReadQueue(), 'ووکامرس' => wooReadQueue()] as $_msQN => $_msQ) {
        foreach ((array)($_msQ['entries'] ?? []) as $_msQe) {
            if (in_array((string)($_msQe['status'] ?? ''), ['waiting', 'running', 'paused'], true)) {
                $_msQPending += max(0, (int)($_msQe['total'] ?? 0) - (int)($_msQe['current'] ?? 0));
            }
        }
    }
    if (empty($results['manual_stopped'])) {
        if ($_msQPending > 0) {
            $_lg[] = '📤 ' . $_msQPending . ' product entered the send queue — sending is continuing server-side — no need to keep the tab open';
        } else {
            $_lg[] = '✅ sending finished server-side';
        }
    }
    $_msDone['recent_log'] = array_slice($_lg, -40);
    writeProgress(MANUAL_SYNC_PROGRESS_FILE, $_msDone);
    @unlink(MANUAL_SYNC_STOP_FILE);
    $results['manual_sync'] = true;
}
cronEmit($results);
exit;
}

/* v8.92: خلاصهٔ آخرین اجرای پس‌زمینهٔ کران — «اجرای الان» بعد از تمام
   شدن کار همین را می‌خواند تا همان گزارشی را نشان دهد که قبلاً مستقیم
   از پاسخ می‌گرفت. */
if (isset($_GET['cron_last'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $f = __DIR__ . '/cron_last_run.json';
    if (!is_file($f)) { echo json_encode(['ok' => false, 'error' => 'هنوز اجرایی ثبت نشده'], JSON_UNESCAPED_UNICODE); exit; }
    $d = json_decode((string)@file_get_contents($f), true);
    if (!is_array($d)) { echo json_encode(['ok' => false, 'error' => 'گزارش ناخوانا'], JSON_UNESCAPED_UNICODE); exit; }
    $d['finished_at'] = (int)@filemtime($f);
    echo json_encode($d, JSON_UNESCAPED_UNICODE); exit;
}

/* =====================================================================
 *  v10.58 (۷۲): «دکترِ همگام‌سازی» — چرا کار نمی‌کند؟
 *
 *  گزارشِ کاربر: «دوره‌ای و دستی هیچ‌کدام کار نمی‌کنند؛ کارت به صفِ
 *  استخراج نمی‌آید؛ فرانت و بک هماهنگ نیستند.» مشکلِ واقعی: وضعیتِ
 *  زنجیره هیچ‌جا دیده نمی‌شد — قفلِ کران، قفلِ استخراج، آخرین تیک،
 *  وضعیتِ هر پروفایل — همه پراکنده در فایل‌ها، بدونِ اندپوینتی که
 *  جمعشان کند و بگوید کدام حلقه گیر دارد. این اندپوینت کلِ زنجیره را
 *  معاینه می‌کند و برای هر حلقه، به زبانِ ساده، نتیجه و راهِ حل را
 *  می‌گوید. دکمهٔ «🩺 تشخیص» در بخشِ همگام‌سازیِ دستی همین را می‌خواند.
 * ===================================================================== */
if (isset($_GET['sync_diagnose'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $dgNow = time();
    $dgCn  = loadConnections();
    $dgStall = max(120, (int)($dgCn['stall_after'] ?? 300));
    $dgOut = ['ok' => true, 'now' => $dgNow, 'stall_after' => $dgStall,
              'checks' => [], 'profiles' => [], 'last_cron' => null];
    $chk = function (string $k, bool $ok, string $msg, $extra = null) use (&$dgOut) {
        $c = ['key' => $k, 'ok' => $ok, 'msg' => $msg];
        if ($extra !== null) $c['extra'] = $extra;
        $dgOut['checks'][] = $c;
    };
    /* ۱ — آیا کرانِ هاست اصلاً به ما می‌رسد؟ */
    $cllFile = __DIR__ . '/cron_last_run.json';
    $cllAt = 0;
    if (is_file($cllFile)) {
        $cllAt = (int)@filemtime($cllFile);
        $dgOut['last_cron'] = json_decode((string)@file_get_contents($cllFile), true);
    }
    $cllAge = $cllAt > 0 ? ($dgNow - $cllAt) : null;
    /* v10.61 (۷۵): آدرسِ دقیقِ کران را هم نشان بده تا کاربر همان را در
       کنترلِ پنلِ هاست / سرویسِ کران تنظیم کند. */
    $dgCronUrl = selfBaseUrl() . '?cron_run=1';
    if ($cllAge === null) {
        $chk('last_tick', false,
            'هیچ تیکِ کرانی ثبت نشده — کرانِ هاست اصلاً به این آدرس نمی‌رسد. این آدرس را در کرانِ هاست تنظیم کنید: ' . $dgCronUrl . ' (هر ۵ دقیقه)');
    } else {
        $dc = is_array($dgOut['last_cron']) ? $dgOut['last_cron'] : [];
        $reason = trim((string)($dc['reason'] ?? ''));
        $chk('last_tick', $cllAge <= max(900, (int)($dgCn['cron_lock_min'] ?? 30) * 60),
            'آخرین تیکِ کران: ' . $cllAge . ' ثانیه پیش'
            . ($reason ? (' — ' . $reason) : '')
            . ($cllAge > max(900, (int)($dgCn['cron_lock_min'] ?? 30) * 60) ? (' — کران قطع شده یا می‌مُرد؛ آدرسِ لازم: ' . $dgCronUrl) : ''),
            ['at' => $cllAt, 'ok' => $dc['ok'] ?? null, 'skipped' => $dc['skipped'] ?? null, 'cron_url' => $dgCronUrl]);
    }
    /* ۲ — قفلِ کران */
    $crLock = __DIR__ . '/.cron_run.lock';
    if (is_file($crLock)) {
        $dgSt = (int)trim((string)@file_get_contents($crLock));
        if ($dgSt <= 0) $dgSt = (int)@filemtime($crLock);
        $dgLa = max(0, $dgNow - $dgSt);
        $dgProg = readProgress(EXTRACT_PROGRESS_FILE);
        $dgTs = (int)($dgProg['last_progress_ts'] ?? (int)($dgProg['started_at'] ?? 0));
        $dgDead = (!empty($dgProg['done']) || empty($dgProg['running']))
            ? ($dgLa > $dgStall)
            : (($dgTs > 0 && ($dgNow - $dgTs) > $dgStall && $dgLa > $dgStall));
        $chk('cron_lock', $dgDead, $dgDead
            ? 'قفلِ کران کهنه و مرده است — در تیکِ بعدی خودبه‌خود برداشته می‌شود.'
            : 'قفلِ کران دستِ یک اجرای زنده است (' . $dgLa . ' ثانیه پیش). تا آن اجرا تمام شود، تیک‌های بعدی منتظر می‌مانند — اگر این پیام مدام می‌آید، در «گزارشِ آخرین اجرا» علت را ببینید.',
            ['age' => $dgLa]);
    } else {
        $chk('cron_lock', true, 'قفلِ کران آزاد است.');
    }
    /* ۳ — قفلِ سراسریِ استخراج */
    $exLk = json_decode((string)@file_get_contents(EXTRACT_LOCK_FILE), true);
    if (is_array($exLk) && !empty($exLk['queue_id'])) {
        $dgAge = $dgNow - (int)($exLk['at'] ?? 0);
        $dgTtl = max(120, min((int)EXTRACT_LOCK_TTL, $dgStall * 3));
        $dgWho = trim((string)($exLk['profile_name'] ?? $exLk['profile_key'] ?? ''));
        $chk('extract_lock', $dgAge >= $dgTtl, $dgAge >= $dgTtl
            ? 'قفلِ استخراج کهنه است (صاحب: ' . ($dgWho ?: '?') . ') — اجرایِ بعدی خودبه‌خود برمی‌دارد.'
            : 'قفلِ استخراج دستِ یک استخراجِ زنده است (' . ($dgWho ?: '?') . '، ' . $dgAge . ' ثانیه). استخراجِ‌های تازه نوبتشان را می‌گیرند — این طبیعی است.',
            ['age' => $dgAge, 'ttl' => $dgTtl, 'profile' => $exLk['profile_key'] ?? null]);
    } else {
        $chk('extract_lock', true, 'قفلِ استخراج آزاد است.');
    }
    /* ۴ — وضعیتِ همگام‌سازیِ دستی */
    $msP = readProgress(MANUAL_SYNC_PROGRESS_FILE);
    if (!empty($msP['running']) && empty($msP['done'])) {
        $msIdleD = $dgNow - (int)($msP['last_progress_ts'] ?? ($msP['ts'] ?? 0));
        $chk('manual_sync', $msIdleD <= $dgStall, $msIdleD <= $dgStall
            ? 'یک همگام‌سازیِ دستی در جریان است (فاز: ' . (string)($msP['phase'] ?? '?') . '، آخرین پیشرفت ' . $msIdleD . ' ثانیه پیش).'
            : 'اجرایِ دستی نیمه‌کاره مانده (' . $msIdleD . ' ثانیه بی‌حرکت). اولین بازدید از وضعیت، خودش را بسته و دکمه دوباره کار می‌کند.',
            ['idle' => $msIdleD]);
    } else {
        $chk('manual_sync', true, 'همگام‌سازیِ دستی آماده است.'
            . (!empty($msP['done']) && !empty($msP['error']) ? ' آخرین اجرا: ' . (string)$msP['error'] : ''));
    }
    /* ۵ — صفِ استخراج */
    $qD = extractReadQueue();
    $entriesD = is_array($qD['entries'] ?? null) ? $qD['entries'] : [];
    $bySt = [];
    $activeQ = 0;
    foreach ($entriesD as $eD) {
        $sD = (string)($eD['status'] ?? 'unknown');
        $bySt[$sD] = (int)($bySt[$sD] ?? 0) + 1;
        if (in_array($sD, ['running', 'waiting', 'paused'], true)) $activeQ++;
    }
    $chk('extract_queue', $activeQ === 0, $activeQ === 0
        ? 'صفِ استخراج ردیفِ فعال ندارد (' . count($entriesD) . ' ردیفِ گذشته).'
        : $activeQ . ' ردیفِ فعال در صفِ استخراج — اگر بیشتر از ' . $dgStall . ' ثانیه بی‌حرکت بماند، نگهبان ادامه‌اش می‌دهد.',
        ['by_status' => $bySt, 'total' => count($entriesD)]);
    /* ۶ — هر پروفایل */
    $profilesD = loadProfiles();
    $syncStateD = loadSyncState();
    foreach ($profilesD as $kD => $pD) {
        if (!is_array($pD)) continue;
        $sc = $pD['syncConfig'] ?? [];
        $iv = (int)($sc['interval'] ?? 3600);
        $lr = (int)($syncStateD[$kD]['lastRun'] ?? 0);
        $issues = [];
        if (empty($sc['enabled'])) $issues[] = 'همگام‌سازی در تنظیماتِ پروفایل خاموش است';
        elseif ($iv > 0 && $lr > 0 && ($dgNow - $lr) < $iv)
            $issues[] = 'هنوز نوبتش نشده (' . ($iv - ($dgNow - $lr)) . ' ثانیه مانده)';
        if (queueHasProfile($entriesD, (string)$kD, 0) !== null) $issues[] = 'ردیفِ فعال در صفِ استخراج دارد';
        if (!empty($sc['noExtract'])) {
            $issues[] = 'پروفایلِ «بدون استخراج» است (انتظارِ کارتِ فهرست نداشته باشید)';
        } elseif (empty($pD['selectors']['container']) && empty($pD['products'])) {
            $issues[] = 'نه سلکتورِ فهرست دارد نه محصولِ واردشده — استخراج چیزی نمی‌سازد';
        }
        $dgOut['profiles'][] = [
            'key' => (string)$kD, 'name' => (string)($pD['name'] ?? $kD),
            'enabled' => !empty($sc['enabled']), 'interval' => $iv,
            'last_run_age' => $lr > 0 ? $dgNow - $lr : null,
            'issues' => $issues, 'ok' => !$issues,
        ];
    }
    /* v10.66 (۸۰): صفِ استخراج + آخرین همگام‌سازیِ دستی + «چرا چیزی نمی‌آید؟» */
    $dgExQ = extractReadQueue();
    $dgExE = array_values($dgExQ['entries'] ?? []);
    $dgExActive = 0; $dgExRows = [];
    foreach (array_slice($dgExE, -8) as $dgE) {
        $dgStt = (string)($dgE['status'] ?? '');
        if (in_array($dgStt, queueActiveStatuses(), true)) $dgExActive++;
        $dgExRows[] = [
            'profile'  => (string)($dgE['profile_name'] ?? $dgE['profile_key'] ?? ''),
            'status'   => $dgStt,
            'age'      => (int)($dgE['started_at'] ?? 0) > 0 ? max(0, $dgNow - (int)$dgE['started_at']) : 0,
            'products' => (int)($dgE['products_count'] ?? 0),
            'error'    => mb_substr((string)($dgE['error'] ?? ''), 0, 120),
        ];
    }
    $dgMsP = readProgress(MANUAL_SYNC_PROGRESS_FILE);
    $dgMs = [
        'running'   => !empty($dgMsP['running']) && empty($dgMsP['done']),
        'done'      => !empty($dgMsP['done']),
        'cancelled' => !empty($dgMsP['cancelled']),
        'phase'     => (string)($dgMsP['phase'] ?? ''),
        'profile'   => (string)($dgMsP['profile_name'] ?? ''),
        'error'     => mb_substr((string)($dgMsP['error'] ?? ''), 0, 200),
        'age'       => (int)($dgMsP['last_progress_ts'] ?? 0) > 0 ? max(0, $dgNow - (int)$dgMsP['last_progress_ts']) : 0,
        'log_tail'  => array_map(fn($l) => mb_substr((string)$l, 0, 160), array_slice((array)($dgMsP['recent_log'] ?? []), -10)),
    ];
    $dgWhy = null;
    if ($dgMs['running']) {
        $dgWhy = 'یک همگام‌سازیِ دستی همین حالا در جریان است (مرحله: ' . ($dgMs['phase'] ?: '?') . ') — صف در همان اجرا پر می‌شود.';
    } elseif ($dgExActive > 0) {
        $dgWhy = $dgExActive . ' ردیفِ فعال در صفِ استخراج هست — ردیف‌های تازه بعد از پایانِ همین ردیف اضافه می‌شوند.';
    } elseif ($dgMs['done'] && $dgMs['age'] < 3600) {
        $dgWhy = $dgMs['error'] !== ''
            ? 'آخرین همگام‌سازیِ دستی با خطا تمام شده: ' . $dgMs['error']
            : 'آخرین همگام‌سازیِ دستی بدونِ خطا تمام شده ولی ردیفی در صف نمانده — گزارشِ پایین را ببینید.';
    } else {
        $dgWhy = 'ردیفِ فعالی در صف نیست. اگر همگام‌سازی چیزی نمی‌آورد، وضعیتِ هر پروفایل در «آخرین اجرا» (بالا) را ببینید: هنوز نوبت نیست / غیرفعال / خطا.';
    }
    $dgOut['queue'] = ['count' => count($dgExE), 'active' => $dgExActive, 'rows' => $dgExRows,
                       'manual' => $dgMs, 'why' => $dgWhy];
    echo json_encode($dgOut, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}

/* =====================================================================
 *  v10.21 (۳۴ج): «سلامتِ اعلان‌ها» — چرا پیامی نمی‌آید؟
 *
 *  وقتی اعلانِ دوره‌ای قطع می‌شود، علت می‌تواند هر کدام از این‌ها باشد:
 *  تیکِ پینگ خاموش است، توکنِ پیام‌رسان پاک شده، فاصلهٔ پینگ خیلی زیاد
 *  تنظیم شده، کران‌جاب اصلاً اجرا نمی‌شود، یا اجرا شروع می‌شود ولی هاست
 *  وسطِ کار پردازه را می‌کُشد. تا حالا هیچ‌کدام از بیرون قابلِ تشخیص
 *  نبود و کاربر فقط سکوت می‌دید. این اندپوینت هر شش را جدا جدا می‌گوید.
 * ===================================================================== */
if (isset($_GET['notif_health'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cnH = loadConnections();
    $stH = notifLoadState();
    $now = time();
    $out = ['ok' => true, 'now' => $now, 'checks' => [], 'problems' => []];

    $add = function (string $k, bool $ok, string $msg, $extra = null) use (&$out) {
        $row = ['ok' => $ok, 'msg' => $msg];
        if ($extra !== null) $row['detail'] = $extra;
        $out['checks'][$k] = $row;
        if (!$ok) $out['problems'][] = $msg;
    };

    // ۱) پیام‌رسان تنظیم است؟
    $hasBaleh  = trim((string)($cnH['baleh']['token'] ?? '')) !== '' && trim((string)($cnH['baleh']['chat_id'] ?? '')) !== '';
    $hasRubika = trim((string)($cnH['rubika']['token'] ?? '')) !== '' && trim((string)($cnH['rubika']['chat_id'] ?? '')) !== '';
    $hasTelegram = trim((string)($cnH['telegram']['token'] ?? '')) !== '' && trim((string)($cnH['telegram']['chat_id'] ?? '')) !== '';   // v10.78 (92)
    $add('messenger', $hasBaleh || $hasRubika || $hasTelegram,
         ($hasBaleh || $hasRubika || $hasTelegram) ? ('پیام‌رسان فعال: ' . trim(($hasBaleh ? 'بله ' : '') . ($hasRubika ? 'روبیکا ' : '') . ($hasTelegram ? 'تلگرام' : '')))
                                   : 'هیچ پیام‌رسانی تنظیم نشده (توکن یا شناسهٔ چت خالی است)');

    /* ۲) پیش‌نیازهای اعلانِ باسلام (سفارش/چت/محصول).
       v10.22 (۳۵الف): این‌ها فقط اعلان‌های باسلام را محدود می‌کنند؛
       پینگِ دوره‌ای دیگر به آن‌ها وابسته نیست، پس نبودشان «مشکل» شمرده
       نمی‌شود مگر کاربر واقعاً اعلانِ باسلام را روشن کرده باشد.
       v10.45 (۵۹): پیش‌نیاز دیگر «کامل‌بودنِ غرفهٔ پیش‌فرض» نیست، بلکه
       «حداقل یک غرفه با توکن» است — بررسی‌ها حالا غرفه‌به‌غرفه و با
       توکنِ خودِ هرکدام انجام می‌شوند. */
    $neH = $cnH['notif_events'] ?? [];
    $shopsH = array_values(array_filter(bslAllShops($cnH), fn($s) => trim((string)($s['token'] ?? '')) !== ''));
    $wantsBsl = notifEventOn($neH, 'order_new') || notifEventOn($neH, 'order_status')
             || notifEventOn($neH, 'chat_msg')  || notifEventOn($neH, 'product_status')
             || notifEventOn($neH, 'product_new');
    $shopsOk = $shopsH !== [];
    $add('prereq', $shopsOk || !$wantsBsl,
         $shopsOk ? (count($shopsH) . ' غرفه با توکن در دسترس است'
                    . (count($shopsH) > 1 ? ' — اعلان‌ها برای همهٔ غرفه‌هاست' : ''))
                  : ($wantsBsl ? 'اعلان‌های باسلام کار نمی‌کنند — هیچ غرفه‌ای با توکن تنظیم نشده'
                               : 'اعلانِ باسلام خاموش است — پینگِ دوره‌ای مستقل کار می‌کند'));

    // ۳) تیکِ پینگ روشن است؟
    $pingOn = !empty($cnH['notif_events']['cron_ping']);
    $add('ping_enabled', $pingOn, $pingOn ? 'تیکِ پینگِ کران‌جاب روشن است'
                                          : 'تیکِ «📡 پینگ اجرای کران‌جاب» خاموش است — پیامِ دوره‌ای فرستاده نمی‌شود');

    // ۴) فاصلهٔ پینگ
    $every = (int)($cnH['ping_every'] ?? 360);
    $lastP = (int)($stH['last_cron_ping'] ?? 0);
    $sinceP = $lastP > 0 ? $now - $lastP : -1;
    $add('ping_interval', true,
         'فاصلهٔ پینگ: ' . ($every > 0 ? $every . ' دقیقه' : 'هر اجرا'),
         ['every_min' => $every, 'last_ping_at' => $lastP, 'since_sec' => $sinceP]);
    if ($lastP > 0 && $every > 0 && $sinceP > $every * 60 * 3) {
        $out['problems'][] = 'آخرین پینگ ' . (int)round($sinceP / 3600) . ' ساعت پیش بوده — بیش از سه برابرِ فاصلهٔ تنظیم‌شده';
    }

    // ۵) کران‌جاب اصلاً اجرا می‌شود؟
    $doneF  = __DIR__ . '/cron_last_run.json';
    $doneAt = is_file($doneF) ? (int)@filemtime($doneF) : 0;
    $startAt = (int)($stH['last_cron_start'] ?? 0);
    $ranOk  = $doneAt > 0 && ($now - $doneAt) < 86400;
    $add('cron_runs', $ranOk,
         $doneAt > 0 ? ('آخرین اجرای کاملِ کران: ' . date('Y-m-d H:i:s', $doneAt))
                     : 'هیچ اجرای کاملی ثبت نشده — کران‌جاب را بررسی کنید',
         ['last_complete_at' => $doneAt, 'last_start_at' => $startAt]);

    // ۶) اجرا شروع می‌شود ولی نیمه‌کاره می‌ماند؟ (پردازه کشته می‌شود)
    $killed = $startAt > 0 && $doneAt > 0 && ($startAt - $doneAt) > 120;
    $add('cron_completes', !$killed,
         $killed ? 'کران شروع می‌شود ولی به پایان نمی‌رسد — هاست پردازه را وسطِ کار می‌کُشد'
                 : 'اجراها تا پایان می‌روند');

    // ۷) وضعیتِ قفل — مالکیت فقط با probe واقعیِ flock مشخص می‌شود، نه mtime
    $lockF = __DIR__ . '/.cron_run.lock';
    $lockProbeFp = @fopen($lockF, 'c');
    $lockFree = false; $lockProbeUnknown = !$lockProbeFp;
    if ($lockProbeFp) {
        $lockFree = @flock($lockProbeFp, LOCK_EX | LOCK_NB);
        if ($lockFree) @flock($lockProbeFp, LOCK_UN);
        @fclose($lockProbeFp);
    }
    $lockBusy = !$lockFree && !$lockProbeUnknown;
    $add('lock', $lockFree,
         $lockProbeUnknown ? 'وضعیتِ قفل نامعلوم است — دسترسی به فایل قفل ممکن نیست'
                           : ($lockBusy ? 'قفل در اختیارِ یک اجرای فعال است'
                                        : 'قفل آزاد است'),
         ['locked' => $lockBusy, 'probe_ok' => !$lockProbeUnknown]);

    /* ۸) v10.45 (۵۹): آخرین اجرای کران خطای اعلان داشته؟
       خطاها در cron_last_run.json می‌نشینند و در پینگِ بعدی هم
       اعلام می‌شوند؛ اینجا دلیلِ «سکوت» را مستقیم نشان می‌دهیم. */
    $lastNotifErr = null;
    if (is_file($doneF)) {
        $_lr = json_decode((string)@file_get_contents($doneF), true);
        if (is_array($_lr) && is_array($_lr['notifications']['errors'] ?? null) && $_lr['notifications']['errors']) {
            $lastNotifErr = implode('؛ ', array_slice($_lr['notifications']['errors'], 0, 2));
        }
    }
    $add('notif_errors', $lastNotifErr === null,
         $lastNotifErr === null ? 'خطای اعلان در آخرین اجرا: نیست'
                                : 'خطای اعلان در آخرین اجرا: ' . $lastNotifErr);

    /* ۹) v10.46 (۶۰): آخرین دورِ بررسی رویدادها کِی و چه دیده؟
       اگر این تازه نباشد، کران اجرا نشده — و اگر تازه باشد ولی صفر،
       بررسی شده ولی چیزی پیدا نشده (دکمه‌های تست می‌گویند چرا). */
    $out['last_notif_run'] = (int)($stH['last_notif_run'] ?? 0);
    if ($out['last_notif_run'] > 0) {
        $_ageN = max(0, $now - $out['last_notif_run']);
        $out['last_notif_run_fa'] = $_ageN < 90 ? $_ageN . ' ثانیه پیش'
                             : ($_ageN < 5400 ? (int)round($_ageN / 60) . ' دقیقه پیش'
                                              : (int)round($_ageN / 3600) . ' ساعت پیش');
        if ($out['last_notif_run_fa'] === '0 ثانیه پیش') $out['last_notif_run_fa'] = 'همین حالا';
    }
    $out['last_notif_seen'] = is_array($stH['last_notif_seen'] ?? null) ? $stH['last_notif_seen'] : null;
    $out['last_notif_found'] = is_array($stH['last_notif_found'] ?? null) ? $stH['last_notif_found'] : null;
    $out['last_notif_pending'] = (int)($stH['last_notif_pending'] ?? 0); /* v10.47 (۶۱) */

    $out['healthy'] = empty($out['problems']);
    echo json_encode($out, JSON_UNESCAPED_UNICODE);
    exit;
}

/* v10.66 (۸۰): فیدِ رویدادهایِ زنده برای مرورگر — رویدادهایِ غیرچت */
if (isset($_GET['live_feed'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $lfSince = (int)($_GET['since'] ?? 0);
    echo json_encode(['ok' => true, 'now' => time(),
                      'events' => liveFeedLoad($lfSince)], JSON_UNESCAPED_UNICODE);
    exit;
}

/* v10.21 (۳۴ج): ارسالِ فوریِ یک پیامِ آزمایشی به پیام‌رسان‌ها */
if (isset($_GET['notif_test_send'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cnT = loadConnections();
    $why = notifPrereq($cnT);
    if ($why !== null) { echo json_encode(['ok' => false, 'error' => $why], JSON_UNESCAPED_UNICODE); exit; }
    $d = notifSend($cnT, "🔔 پیام آزمایشی\nزمان سرور: " . date('Y-m-d H:i:s') . "\nنسخه: " . APP_VERSION);
    $anyOk = in_array('sent', array_values($d), true);
    echo json_encode(['ok' => $anyOk, 'delivery' => $d], JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v8.62: اندپوینت‌های ویرایش گروهی / عکس‌دار کردن / گزارش شبانه
 * ===================================================================== */

/** فهرست محصولات مقصد برای انتخاب — ?dest_list=1&target=woo|bsl&page=1&q=... */
if (isset($_GET['dest_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(120);
    $cn = loadConnections();
    $target = (string)($_GET['target'] ?? 'woo');
    $page = max(1, (int)($_GET['page'] ?? 1));
    $q = trim((string)($_GET['q'] ?? ''));
    $rows = [];
    if ($target === 'woo') {
        $w = $cn['woocommerce'] ?? [];
        if (empty($w['store_url'])) { echo json_encode(['ok' => false, 'error' => 'تنظیمات ووکامرس ناقص'], JSON_UNESCAPED_UNICODE); exit; }
        $ep = 'products?per_page=50&status=any&page=' . $page . ($q !== '' ? '&search=' . urlencode($q) : '');
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET', $ep);
        if (empty($r['ok'])) { echo json_encode(['ok' => false, 'error' => 'خطا ' . (int)$r['code']], JSON_UNESCAPED_UNICODE); exit; }
        foreach ((array)$r['body'] as $p) {
            $rows[] = ['id' => (int)($p['id'] ?? 0), 'title' => (string)($p['name'] ?? ''),
                'price' => (int)preg_replace('~[^0-9]~', '', (string)($p['regular_price'] ?? '0')),
                'stock' => $p['stock_quantity'], 'status' => (string)($p['status'] ?? ''),
                'has_image' => !empty($p['images']),
                'link' => rtrim((string)$w['store_url'], '/') . '/wp-admin/post.php?post=' . (int)$p['id'] . '&action=edit'];
        }
    } else {
        $bs = $cn['basalam'] ?? []; $tk = (string)($bs['token'] ?? ''); $vid = (int)($bs['vendor_id'] ?? 0);
        if ($tk === '' || $vid <= 0) { echo json_encode(['ok' => false, 'error' => 'تنظیمات باسلام ناقص'], JSON_UNESCAPED_UNICODE); exit; }
        // v8.79: پارامتر جست‌وجوی باسلام «title» است نه «search»
        $ep = 'vendors/' . $vid . '/products?per_page=50&page=' . $page
            . '&statuses=2976&statuses=3790&statuses=3568&statuses=3567'
            . ($q !== '' ? '&title=' . rawurlencode($q) : '');
        $r = bslReq($tk, 'GET', $ep);
        if (empty($r['ok'])) { echo json_encode(['ok' => false, 'error' => 'خطا ' . (int)$r['code']], JSON_UNESCAPED_UNICODE); exit; }
        $sm = bslStatusMap();
        foreach ((array)($r['body']['data'] ?? $r['body'] ?? []) as $p) {
            $st = (int)($p['status']['id'] ?? $p['status'] ?? 0);
            $pr = (int)($p['price'] ?? $p['primary_price'] ?? 0);
            $rows[] = ['id' => (int)($p['id'] ?? 0), 'title' => (string)($p['title'] ?? $p['name'] ?? ''),
                'price' => $pr > 0 ? (int)round($pr / 10) : 0,   // ریال → تومان
                'stock' => $p['stock'] ?? null, 'status' => $sm[$st] ?? (string)$st,
                'status_id' => $st, 'has_image' => !empty($p['photo']),
                'link' => 'https://basalam.com/p/' . (int)($p['id'] ?? 0)];
        }
    }
    echo json_encode(['ok' => true, 'target' => $target, 'page' => $page,
        'count' => count($rows), 'products' => $rows], JSON_UNESCAPED_UNICODE);
    exit;
}

/** ویرایش گروهی — ?bulk_edit=1  (POST: target, ids, ops, dry, notify) */
if (isset($_GET['bulk_edit'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $lockFile = __DIR__ . '/bulkedit.lock';
    $lockFp = fopen($lockFile, 'c');
    if (!$lockFp || !flock($lockFp, LOCK_EX | LOCK_NB)) {
        if ($lockFp) fclose($lockFp);
        echo json_encode(['ok' => false, 'error' => 'یک ویرایش گروهی در حال اجراست', 'running' => true], JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);
    bulkStopClear();
    $cn = loadConnections();
    $target = (string)($_POST['target'] ?? 'woo');
    $ids = json_decode((string)($_POST['ids'] ?? '[]'), true);
    if (!is_array($ids)) $ids = [];
    $ops = json_decode((string)($_POST['ops'] ?? '{}'), true);
    if (!is_array($ops)) $ops = [];
    $dry = !empty($_POST['dry']);
    $notify = !empty($_POST['notify']);
    /* v10.129: در resume، همان checkpoint منبع حقیقت است؛ مخصوصاً فهرستِ
       باقی‌مانده، تا ویرایشِ نسبیِ قیمت روی محصولِ انجام‌شده دوباره اعمال نشود. */
    $bulkResume = [];
    if (!empty($_GET['resume']) && is_file(BULKEDIT_PROGRESS_FILE)) {
        $oldBulk = json_decode((string)@file_get_contents(BULKEDIT_PROGRESS_FILE), true);
        $oldCp = is_array($oldBulk['checkpoint'] ?? null) ? $oldBulk['checkpoint'] : [];
        if (is_array($oldCp['ids'] ?? null) && is_array($oldCp['ops'] ?? null)
            && in_array((string)($oldCp['target'] ?? ''), ['woo', 'bsl'], true)) {
            $bulkResume = $oldCp;
            $target = (string)$oldCp['target'];
            $ids = is_array($oldCp['remaining_ids'] ?? null) ? $oldCp['remaining_ids'] : $oldCp['ids'];
            $ops = $oldCp['ops'];
            $dry = !empty($oldCp['dry']);
            $notify = !empty($oldCp['notify']);
        }
    }
    if ($target !== 'woo' && $target !== 'bsl') {
        flock($lockFp, LOCK_UN); fclose($lockFp);
        echo json_encode(['ok' => false, 'error' => 'مقصد نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }

    localTaskDbForget(BULKEDIT_PROGRESS_FILE); @unlink(BULKEDIT_PROGRESS_FILE);
    bulkProgress(['running' => true, 'done' => false, 'target' => $target, 'dry' => $dry,
        'total' => count($ids), 'current' => 0, 'started_at' => time(),
        'checkpoint' => ['target' => $target,
            'ids' => array_values($bulkResume['ids'] ?? $ids), 'ops' => $ops,
            'dry' => $dry, 'notify' => $notify, 'remaining_ids' => array_values($ids),
            'changed' => (int)($bulkResume['changed'] ?? 0), 'deleted' => (int)($bulkResume['deleted'] ?? 0),
            'skipped' => (int)($bulkResume['skipped'] ?? 0), 'failed' => (int)($bulkResume['failed'] ?? 0)],
        'log_add' => ['✏️ شروع ویرایش ' . count($ids) . ' محصول — ' . ($target === 'woo' ? 'ووکامرس' : 'باسلام') . ($dry ? ' (پیش‌نمایش)' : '')]]);

    $early = json_encode(['ok' => true, 'started' => true, 'total' => count($ids)], JSON_UNESCAPED_UNICODE);
    header('Connection: close'); header('Content-Length: ' . strlen($early));
    echo $early; @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();
    register_shutdown_function(function () use ($lockFp, $lockFile) {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
    });

    try { $res = bulkEditRun($cn, $target, $ids, $ops, $dry, $bulkResume); }
    catch (Throwable $e) {
        $bulkErrState = is_file(BULKEDIT_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(BULKEDIT_PROGRESS_FILE), true) : [];
        bulkProgress(['running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(),
            'checkpoint' => is_array($bulkErrState['checkpoint'] ?? null) ? $bulkErrState['checkpoint'] : null,
            'log_add' => ['❌ خطا: ' . $e->getMessage() . ' — checkpoint حفظ شد']]); exit;
    }
    if ($notify && !$dry) {
        $why = notifPrereq($cn);
        if ($why === null) { $res['delivery'] = notifSend($cn, bulkEditMsg($res), 'report');
            bulkProgress(['log_add' => ['📤 گزارش به پیام‌رسان‌ها فرستاده شد']]); }
        else { $res['notify_error'] = $why; bulkProgress(['log_add' => ['⚠️ ارسال نشد: ' . $why]]); }
    }
    @file_put_contents(BULKEDIT_RESULT_FILE, json_encode($res, JSON_UNESCAPED_UNICODE), LOCK_EX);
    $bulkLastState = is_file(BULKEDIT_PROGRESS_FILE)
        ? json_decode((string)@file_get_contents(BULKEDIT_PROGRESS_FILE), true) : [];
    $bulkKeepCp = !empty($res['stopped']) || !empty($res['partial']) || empty($res['ok']);
    bulkStopClear();
    bulkProgress(['running' => false, 'done' => true, 'changed' => $res['changed'],
        'deleted' => $res['deleted'], 'failed' => $res['failed'], 'skipped' => $res['skipped'],
        'stale' => $bulkKeepCp,
        'checkpoint' => $bulkKeepCp && is_array($bulkLastState['checkpoint'] ?? null)
            ? $bulkLastState['checkpoint'] : null,
        'log_add' => ['✅ پایان — ' . $res['changed'] . ' ویرایش، ' . $res['deleted'] . ' حذف/بایگانی، ' . $res['failed'] . ' خطا']]);
    exit;
}

if (isset($_GET['bulk_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $st = [];
    if (is_file(BULKEDIT_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(BULKEDIT_PROGRESS_FILE), true);
        if (is_array($d)) $st = $d;
    }
    echo json_encode(['ok' => true, 'status' => $st], JSON_UNESCAPED_UNICODE); exit;
}
if (isset($_GET['bulk_result'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $d = is_file(BULKEDIT_RESULT_FILE)
        ? json_decode((string)@file_get_contents(BULKEDIT_RESULT_FILE), true) : null;
    echo json_encode(['ok' => is_array($d), 'result' => $d], JSON_UNESCAPED_UNICODE); exit;
}

/** عکس‌دار کردن محصولات ووکامرس — ?photo_fix=1[&dry=1][&profile=key][&notify=1] */
if (isset($_GET['photo_fix'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $lockFile = __DIR__ . '/photofix.lock';
    $lockFp = fopen($lockFile, 'c');
    if (!$lockFp || !flock($lockFp, LOCK_EX | LOCK_NB)) {
        if ($lockFp) fclose($lockFp);
        echo json_encode(['ok' => false, 'error' => 'یک اجرا در جریان است', 'running' => true], JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);
    photoStopClear();
    $cn = loadConnections();
    $dry = !empty($_GET['dry']);
    $onlyProfile = trim((string)($_GET['profile'] ?? ''));
    $notify = !empty($_GET['notify']);
    /* v10.129: صفحه و شمارنده‌های بازسازی عکس از آخرین محصول امن ادامه
       می‌یابند؛ محصول جاری در بدترین حالت دوباره با همان گالری مطلق دیده می‌شود. */
    $photoCp = null;
    if (!empty($_GET['resume']) && is_file(PHOTOFIX_PROGRESS_FILE)) {
        $oldPhoto = json_decode((string)@file_get_contents(PHOTOFIX_PROGRESS_FILE), true);
        $oldCp = is_array($oldPhoto['checkpoint'] ?? null) ? $oldPhoto['checkpoint'] : null;
        if (is_array($oldCp) && (string)($oldCp['profile'] ?? '') === $onlyProfile
            && (bool)($oldCp['dry'] ?? false) === $dry) {
            $photoCp = $oldCp;
            $notify = !empty($oldCp['notify']) || $notify;
        }
    }

    localTaskDbForget(PHOTOFIX_PROGRESS_FILE); @unlink(PHOTOFIX_PROGRESS_FILE);
    photoFixProgress(['running' => true, 'done' => false, 'dry' => $dry, 'profile' => $onlyProfile,
        'notify' => $notify, 'started_at' => (int)($photoCp['started_at'] ?? time()),
        'checkpoint' => $photoCp !== null ? $photoCp : ['page' => 1, 'offset' => 0,
            'scanned' => 0, 'missing' => 0, 'matched' => 0, 'fixed' => 0, 'failed' => 0,
            'unmatched' => 0, 'profile' => $onlyProfile, 'dry' => $dry, 'notify' => $notify,
            'started_at' => time()],
        'log_add' => ['🖼 ' . ($photoCp !== null ? 'ادامه عکس‌دار کردن' : 'شروع عکس‌دار کردن')
            . ($dry ? ' (پیش‌نمایش)' : '')]]);

    $early = json_encode(['ok' => true, 'started' => true, 'dry' => $dry], JSON_UNESCAPED_UNICODE);
    header('Connection: close'); header('Content-Length: ' . strlen($early));
    echo $early; @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();
    register_shutdown_function(function () use ($lockFp, $lockFile) {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
    });

    $photoRunCp = is_array($photoCp) ? $photoCp : ['notify' => $notify];
    try { $res = photoFixRun($cn, $dry, $onlyProfile, 2000, $photoRunCp); }
    catch (Throwable $e) {
        $photoErrState = is_file(PHOTOFIX_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(PHOTOFIX_PROGRESS_FILE), true) : [];
        photoFixProgress(['running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(),
            'checkpoint' => is_array($photoErrState['checkpoint'] ?? null) ? $photoErrState['checkpoint'] : null,
            'log_add' => ['❌ خطا: ' . $e->getMessage() . ' — checkpoint حفظ شد']]); exit;
    }
    if ($notify && !$dry) {
        $why = notifPrereq($cn);
        if ($why === null) { $res['delivery'] = notifSend($cn, photoFixMsg($res), 'report');
            photoFixProgress(['log_add' => ['📤 گزارش فرستاده شد']]); }
        else { $res['notify_error'] = $why; }
    }
    @file_put_contents(__DIR__ . '/photofix_result.json', json_encode($res, JSON_UNESCAPED_UNICODE), LOCK_EX);
    $photoLastState = is_file(PHOTOFIX_PROGRESS_FILE)
        ? json_decode((string)@file_get_contents(PHOTOFIX_PROGRESS_FILE), true) : [];
    $photoKeepCp = !empty($res['stopped']) || !empty($res['partial']) || empty($res['ok']);
    photoStopClear();
    photoFixProgress(['running' => false, 'done' => true, 'stopped' => !empty($res['stopped']),
        'fixed' => $res['fixed'] ?? 0,
        'failed' => $res['failed'] ?? 0, 'unmatched' => $res['unmatched'] ?? 0,
        'result_ok' => !empty($res['ok']), 'stale' => $photoKeepCp,
        'checkpoint' => $photoKeepCp && is_array($photoLastState['checkpoint'] ?? null)
            ? $photoLastState['checkpoint'] : null,
        'log_add' => [empty($res['ok']) ? ('❌ ' . ($res['error'] ?? 'ناموفق'))
                     : ('✅ پایان — ' . (int)$res['fixed'] . ' محصول عکس‌دار شد')]]);
    exit;
}

if (isset($_GET['photo_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $st = [];
    if (is_file(PHOTOFIX_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(PHOTOFIX_PROGRESS_FILE), true);
        if (is_array($d)) $st = $d;
    }
    $res = is_file(__DIR__ . '/photofix_result.json')
        ? json_decode((string)@file_get_contents(__DIR__ . '/photofix_result.json'), true) : null;
    echo json_encode(['ok' => true, 'status' => $st, 'result' => $res], JSON_UNESCAPED_UNICODE); exit;
}

/** گزارش شبانه — ?digest=1 پیش‌نمایش · &send=1 ارسال فوری */
// v8.66: این نگهبان باید «فقط» وقتی بگیرد که خودِ digest درخواست شده باشد.
// باگ: bsl_notify_selected هم پارامتر digest می‌فرستد (۰ یا ۱) و چون isset
// در هر دو حالت درست است، دکمهٔ «ارسال انتخاب‌شده‌ها به پیام‌رسان» همیشه
// اینجا می‌افتاد و به‌جای ارسال، گزارش شبانه را برمی‌گرداند.
if (isset($_GET['digest']) && !isset($_GET['bsl_notify_selected'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(120);
    $cn = loadConnections();
    $hours = max(1, min(168, (int)($_GET['hours'] ?? ($cn['digest_hours'] ?? 24))));
    $d = digestBuild($cn, $hours);
    $msg = digestMsg($d);
    $out = ['ok' => true, 'data' => $d, 'message' => $msg,
            'state' => digestLoadState(),
            'enabled' => !empty($cn['digest_enabled']),
            'hour' => (int)($cn['digest_hour'] ?? 23)];
    if (!empty($_GET['send'])) {
        $why = notifPrereq($cn);
        if ($why !== null) { $out['sent'] = false; $out['error'] = $why; }
        else {
            $out['delivery'] = notifSend($cn, $msg);
            $out['sent'] = true;
            $st = digestLoadState();
            $st['last_date'] = date('Y-m-d'); $st['last_at'] = time();
            digestSaveState($st);
        }
    }
    echo json_encode($out, JSON_UNESCAPED_UNICODE); exit;
}

/**
 * v8.34: بازنشستگی دستی — پیش‌نمایش یا اجرا.
 * ?retire_run=1&profile=<key>&mode=draft&dry=1
 * بدون dry=1 واقعاً روی ووکامرس/باسلام اعمال می‌شود.
 */
if (isset($_GET['retire_run'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn  = loadConnections();
    $key = trim((string)($_GET['profile'] ?? ''));
    $dry = !isset($_GET['dry']) || $_GET['dry'] !== '0';   // پیش‌فرض: فقط پیش‌نمایش
    $profiles = loadProfiles();
    /* v10.38 (۵۱الف): کشویی «انتخاب سایت» مقدارش URL است نه کلیدِ پروفایل
       (renderProfileDropdown: opt.value = p.url)، ولی اینجا کلید لازم بود.
       نتیجه: هر «پیش‌نمایش» با «پروفایل نامعتبر» رد می‌شد و کلِ بازنشستگیِ
       دستی از کار افتاده بود. حالا هر دو شکل پذیرفته می‌شود — درست مثل
       ?load_profile که از همان اول URL را با profileKey() تبدیل می‌کرد. */
    if ($key !== '' && !isset($profiles[$key])) {
        $_rkAlt = profileKey($key);
        if ($_rkAlt !== '' && isset($profiles[$_rkAlt])) $key = $_rkAlt;
    }
    if ($key === '' || !isset($profiles[$key])) {
        echo json_encode(['ok' => false, 'error' => 'پروفایل نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $profile = $profiles[$key];
    $mode = (string)($_GET['mode'] ?? ($cn['retire_mode'] ?? 'draft'));
    if (!isset(retireModes()[$mode]) || $mode === 'off') $mode = 'draft';
    $target = (string)($_GET['target'] ?? ($profile['syncConfig']['target'] ?? 'woo'));

    // آخرین گزارش استخراج این پروفایل را پیدا کن
    $rep = null; $newest = 0;
    foreach (glob(__DIR__ . '/extract_report_*.json') ?: [] as $f) {
        $d = json_decode((string)@file_get_contents($f), true);
        if (!is_array($d)) continue;
        if (($d['profile_key'] ?? '') !== $key) continue;
        $ts = (int)@filemtime($f);
        if ($ts >= $newest) { $newest = $ts; $rep = $d; }
    }
    if ($rep === null) {
        echo json_encode(['ok' => false,
            'error' => 'گزارش استخراجی برای این پروفایل نیست — اول یک استخراج اجرا کنید'],
            JSON_UNESCAPED_UNICODE); exit;
    }
    $items = $rep['removed_items'] ?? [];

    /* =================================================================
       v10.35 (۴۷ج): اجرای واقعی فقط با تأییدِ همان پیش‌نمایشی که دیده شد.

       تا اینجا dry=0 مستقیم عمل می‌کرد. یعنی یک آدرسِ ساده در نوارِ
       مرورگر می‌توانست ده‌ها محصول را حذف کند، بدون اینکه کسی فهرستش را
       دیده باشد. حالا چرخه دو مرحله‌ای است:
         ۱) پیش‌نمایش (پیش‌فرض) ⇒ فهرست + یک توکنِ یک‌بارمصرف
         ۲) اجرا ⇒ dry=0 به‌علاوهٔ همان توکن (confirm=)
       توکن یک ساعت اعتبار دارد و پس از مصرف باطل می‌شود، پس «تأیید» واقعاً
       به همان فهرست گره خورده است نه به یک کلیکِ کور.
       ================================================================= */
    if (!$dry) {
        $tokenIn = trim((string)($_GET['confirm'] ?? ''));
        $plan = retirePlanTake($tokenIn);
        if ($plan === null) {
            echo json_encode(['ok' => false, 'need_confirm' => true,
                'error' => 'برای اجرای واقعی، اول پیش‌نمایش بگیرید و بعد همان را تأیید کنید'],
                JSON_UNESCAPED_UNICODE); exit;
        }
        if ((string)($plan['profile_key'] ?? '') !== $key) {
            echo json_encode(['ok' => false,
                'error' => 'این تأیید مالِ پروفایلِ دیگری است'], JSON_UNESCAPED_UNICODE); exit;
        }
        /* عمداً از فهرستِ خودِ نقشه استفاده می‌شود، نه از گزارشِ تازه: کاربر
           همان فهرست را دیده و تأیید کرده. اگر بینِ دو مرحله استخراجِ
           تازه‌ای اجرا شده باشد، نباید بی‌خبر چیزهای دیگری هم حذف شوند. */
        $items  = is_array($plan['items'] ?? null) ? $plan['items'] : $items;
        $mode   = (string)($plan['mode'] ?? $mode);
        $target = (string)($plan['target'] ?? $target);
    }

    $res = retireRemoved($cn, $items, $target, $mode, (int)($rep['extracted'] ?? 0), $dry,
                         (string)($profile['name'] ?? $key), null, $key);
    $res['ok'] = true; $res['profile'] = $profile['name'] ?? $key;
    $res['profile_key'] = $key;
    $res['report_time'] = $newest;
    if ($dry && empty($res['skipped'])) {
        /* فقط چیزهایی که واقعاً «آماده» شده‌اند وارد نقشه می‌شوند — یعنی
           مالکیتشان تأیید شده و روی مقصد پیدا شده‌اند. */
        $ready = [];
        foreach ($items as $it) {
            if (!is_array($it)) continue;
            $t = trim((string)($it['title'] ?? ''));
            if ($t === '') continue;
            foreach ($res['items'] as $ri) {
                if (mb_substr($t, 0, 60) !== (string)($ri['title'] ?? '')) continue;
                $okW = isset($ri['woo']) && strpos((string)$ri['woo'], 'آماده') === 0;
                $okB = isset($ri['bsl']) && strpos((string)$ri['bsl'], 'آماده') === 0;
                if ($okW || $okB) $ready[] = $it;
                break;
            }
        }
        $res['ready'] = count($ready);
        if ($ready) $res['confirm_token'] = retirePlanSave(
            ['profile_key' => $key, 'mode' => $mode, 'target' => $target, 'items' => $ready]);
    }
    echo json_encode($res, JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.35 (۴۷ب): مدیریتِ کشِ کاتالوگِ غرفه‌ها
 *  ?bsl_catalog=1              → وضعیتِ کشِ همهٔ غرفه‌ها
 *  ?bsl_catalog=1&rebuild=1    → بازسازیِ اجباری
 *  ?bsl_catalog=1&clear=1      → پاک‌کردن
 * ===================================================================== */
/* v10.41 (۵۵): وضعیت و بازسازیِ دستیِ کشِ درختِ دسته‌ها.
 *   ?bsl_cats=1          → وضعیت (بدونِ هیچ درخواستی به باسلام)
 *   ?bsl_cats=1&rebuild=1 → واکشیِ دوباره و نوشتنِ کش
 *   ?bsl_cats=1&clear=1   → پاک‌کردنِ کش (واکشیِ بعدی دوباره می‌گیرد) */
if (isset($_GET['bsl_cats'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(300);
    if (!empty($_GET['clear'])) {
        $okC = @unlink(BSL_CATS_FILE);
        echo json_encode(['ok' => true, 'cleared' => (bool)$okC], JSON_UNESCAPED_UNICODE); exit;
    }
    if (!empty($_GET['rebuild'])) {
        $cnK = loadConnections();
        $shK = bslAllShops($cnK);
        $tkK = '';
        foreach ($shK as $sh) { $t = trim((string)($sh['token'] ?? '')); if ($t !== '') { $tkK = $t; break; } }
        if ($tkK === '') { echo json_encode(['ok' => false, 'error' => 'توکنِ باسلام موجود نیست'], JSON_UNESCAPED_UNICODE); exit; }
        $got = bslCatsAll($tkK, true);
        echo json_encode(['ok' => (bool)$got, 'rebuilt' => true, 'count' => count($got),
            'cache' => bslCatsStatus()], JSON_UNESCAPED_UNICODE); exit;
    }
    $st = bslCatsStatus();
    $st['ttl'] = (int)BSL_CATS_TTL;
    $st['at_h'] = !empty($st['at']) ? date('Y/m/d H:i', (int)$st['at']) : '—';
    $st['age_fa'] = !empty($st['at']) ? dedupAgeFa(time() - (int)$st['at']) : '—';
    echo json_encode(['ok' => true] + $st, JSON_UNESCAPED_UNICODE);
    exit;
}
/* =====================================================================
 * v10.90 (۱۰۳): کش هش محصولات — همگام‌سازی افزایشی
 * productHashRead / productHashWrite / productHashCompute*
 * productHashDiff* / productHashUpdate*
 * فایل: product_hash_cache.json
 * ساختار: {bsl:{VID:{PROD_ID:HASH}}, woo:{SITE_KEY:{PROD_ID:HASH}}}
 * ===================================================================== */
function productHashRead(): array {
    if (!is_file(PRODUCT_HASH_FILE)) return ['bsl' => [], 'woo' => []];
    $d = json_decode((string)file_get_contents(PRODUCT_HASH_FILE), true);
    if (!is_array($d)) return ['bsl' => [], 'woo' => []];
    if (!isset($d['bsl'])) $d['bsl'] = [];
    if (!isset($d['woo'])) $d['woo'] = [];
    return $d;
}

function productHashWrite(array $cache): bool {
    return (bool)file_put_contents(PRODUCT_HASH_FILE, json_encode($cache, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

function productHashComputeBsl(array $item): string {
    return hash('sha256', implode('|', [
        (string)($item['id'] ?? $item['product_id'] ?? ''),
        (string)($item['title'] ?? $item['name'] ?? ''),
        (string)($item['price'] ?? ''),
        (string)($item['stock'] ?? $item['stock_quantity'] ?? ''),
        (string)($item['status'] ?? ''),
        (string)($item['category_id'] ?? ''),
    ]));
}

function productHashComputeWoo(array $item): string {
    return hash('sha256', implode('|', [
        (string)($item['id'] ?? ''),
        (string)($item['name'] ?? ''),
        (string)($item['price'] ?? $item['regular_price'] ?? ''),
        (string)($item['stock_quantity'] ?? ''),
        (string)($item['status'] ?? ''),
        (string)($item['categories'][0]['id'] ?? ''),
    ]));
}

/** کش بازل‌ام را برای یک غرفه بروز می‌کند و diff برمی‌گرداند */
function productHashDiffBsl(int $vid, array $currentItems): array {
    $cache = productHashRead();
    $vkey = (string)$vid;
    $old = $cache['bsl'][$vkey] ?? [];
    $new_ = []; $added = []; $changed = []; $deleted = [];
    foreach ($currentItems as $item) {
        $pid = (string)($item['id'] ?? $item['product_id'] ?? '');
        if ($pid === '') continue;
        $h = productHashComputeBsl($item);
        $new_[$pid] = $h;
        if (!isset($old[$pid])) $added[] = $pid;
        elseif ($old[$pid] !== $h) $changed[] = $pid;
    }
    foreach (array_keys($old) as $pid) {
        if (!isset($new_[$pid])) $deleted[] = $pid;
    }
    return ['added' => $added, 'changed' => $changed, 'deleted' => $deleted, 'hashes' => $new_];
}

function productHashUpdateBsl(int $vid, array $hashes): void {
    $cache = productHashRead();
    $cache['bsl'][(string)$vid] = $hashes;
    productHashWrite($cache);
}

/** کش ووکامرس را برای یک سایت بروز می‌کند و diff برمی‌گرداند */
function productHashDiffWoo(string $siteKey, array $currentItems): array {
    $cache = productHashRead();
    $old = $cache['woo'][$siteKey] ?? [];
    $new_ = []; $added = []; $changed = []; $deleted = [];
    foreach ($currentItems as $item) {
        $pid = (string)($item['id'] ?? '');
        if ($pid === '') continue;
        $h = productHashComputeWoo($item);
        $new_[$pid] = $h;
        if (!isset($old[$pid])) $added[] = $pid;
        elseif ($old[$pid] !== $h) $changed[] = $pid;
    }
    foreach (array_keys($old) as $pid) {
        if (!isset($new_[$pid])) $deleted[] = $pid;
    }
    return ['added' => $added, 'changed' => $changed, 'deleted' => $deleted, 'hashes' => $new_];
}

function productHashUpdateWoo(string $siteKey, array $hashes): void {
    $cache = productHashRead();
    $cache['woo'][$siteKey] = $hashes;
    productHashWrite($cache);
}

function productHashClear(string $target = 'all', string $key = ''): int {
    $cache = productHashRead();
    $n = 0;
    if ($target === 'bsl') {
        if ($key === '') { $n = count($cache['bsl']); $cache['bsl'] = []; }
        elseif (isset($cache['bsl'][$key])) { $n = count($cache['bsl'][$key]); unset($cache['bsl'][$key]); }
    } elseif ($target === 'woo') {
        if ($key === '') { $n = count($cache['woo']); $cache['woo'] = []; }
        elseif (isset($cache['woo'][$key])) { $n = count($cache['woo'][$key]); unset($cache['woo'][$key]); }
    } else {
        $n = count($cache['bsl']) + count($cache['woo']);
        $cache = ['bsl' => [], 'woo' => []];
    }
    productHashWrite($cache);
    return $n;
}


/* =====================================================================
 *  v10.90 (۱۰۳): استعلام کش هش محصولات
 *  ?product_hash_diff=1&target=bsl|woo|all[&vid=N][&site=KEY][&update=1]
 * ===================================================================== */
if (isset($_GET['product_hash_diff'])) {
    ob_clean();
    header('Content-Type: application/json; charset=UTF-8');
    $target = (string)($_GET['target'] ?? 'all');
    $doUpdate = !empty($_GET['update']);
    $out = [];
    $cnH = loadConnections();

    if ($target === 'bsl' || $target === 'all') {
        $shops = bslAllShops($cnH);
        $vid_filter = (int)($_GET['vid'] ?? 0);
        foreach ($shops as $sh) {
            $vid = (int)($sh['vendor_id'] ?? 0);
            $tk  = (string)($sh['token'] ?? '');
            if ($vid <= 0 || $tk === '') continue;
            if ($vid_filter > 0 && $vid !== $vid_filter) continue;
            $cat = bslCatalogGet($tk, $vid, false);
            $items = $cat['items'] ?? [];
            if (empty($items)) {
                $out['bsl'][(string)$vid] = ['error' => 'کاتالوگ خالی یا ناموجود', 'shop' => $sh['shop_name'] ?? ''];
                continue;
            }
            $diff = productHashDiffBsl($vid, $items);
            if ($doUpdate) productHashUpdateBsl($vid, $diff['hashes']);
            $out['bsl'][(string)$vid] = [
                'shop'    => (string)($sh['shop_name'] ?? ''),
                'added'   => count($diff['added']),
                'changed' => count($diff['changed']),
                'deleted' => count($diff['deleted']),
                'total'   => count($diff['hashes']),
                'deleted_ids' => $diff['deleted'],
            ];
        }
    }

    if ($target === 'woo' || $target === 'all') {
        $woo = $cnH['woocommerce'] ?? [];
        $siteUrl = trim((string)($woo['store_url'] ?? ''));
        if ($siteUrl !== '' && !empty($woo['enabled'])) {
            $siteKey = md5($siteUrl);
            $wooItems = reconFetchWoo($woo);
            $diff = productHashDiffWoo($siteKey, $wooItems);
            if ($doUpdate) productHashUpdateWoo($siteKey, $diff['hashes']);
            $out['woo'] = [
                'site'    => $siteUrl,
                'added'   => count($diff['added']),
                'changed' => count($diff['changed']),
                'deleted' => count($diff['deleted']),
                'total'   => count($diff['hashes']),
                'deleted_ids' => $diff['deleted'],
            ];
        } else {
            $out['woo'] = ['error' => 'ووکامرس فعال نیست یا آدرس ندارد'];
        }
    }

    if (!empty($_GET['clear'])) {
        $n = productHashClear((string)($_GET['target'] ?? 'all'), (string)($_GET['key'] ?? ''));
        echo json_encode(['ok' => true, 'cleared' => $n], JSON_UNESCAPED_UNICODE);
        exit;
    }

    echo json_encode(['ok' => true, 'updated' => $doUpdate, 'diff' => $out], JSON_UNESCAPED_UNICODE);
    exit;
}



if (isset($_GET['bsl_catalog'])) {
    ob_clean();
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(300);
    if (!empty($_GET['clear'])) {
        $n = bslCatalogClear((int)($_GET['vendor_id'] ?? 0));
        echo json_encode(['ok' => true, 'cleared' => $n], JSON_UNESCAPED_UNICODE); exit;
    }
    $cnC   = loadConnections();
    $shops = bslAllShops($cnC);
    $only  = (int)($_GET['vendor_id'] ?? 0);
    $rows  = [];
    foreach ($shops as $sh) {
        $v = (int)($sh['vendor_id'] ?? 0);
        if ($v <= 0 || ($only > 0 && $v !== $only)) continue;
        if (!empty($_GET['rebuild'])) bslCatalogBuild((string)$sh['token'], $v, true);
        $c = bslCatalogRead($v);
        $rows[] = ['vendor_id' => $v, 'shop_name' => (string)($sh['shop_name'] ?? ''),
                   'count' => (int)($c['count'] ?? 0), 'pages' => (int)($c['pages'] ?? 0),
                   /* v10.40 (۵۴الف): products = تعدادِ محصولِ واقعی · count = کلیدهای
                      عنوانِ نرمال‌شده (هر محصول تا ۲ کلید). قبلاً فقط count نشان
                      داده می‌شد و کاربر آن را «تعدادِ محصول» می‌خواند. */
                   'products' => (int)($c['products'] ?? 0),
                   'total_count' => (int)($c['total_count'] ?? 0),
                   'partial' => !empty($c['partial']), 'at' => (int)($c['at'] ?? 0),
                   'at_h' => !empty($c['at']) ? date('Y/m/d H:i', (int)$c['at']) : '—',
                   'fresh' => bslCatalogFresh($v, $c),
                   /* v10.39 (۵۳): تعدادِ ردیفِ کاملِ ذخیره‌شده — کشِ نسخه‌های
                      قدیمی این کلید را ندارد و ۰ برمی‌گرداند */
                   'rows_count' => (int)($c['rows_count'] ?? (is_array($c['rows'] ?? null) ? count($c['rows']) : 0)),
                   'age' => !empty($c['at']) ? time() - (int)$c['at'] : 0,
                   'age_fa' => !empty($c['at']) ? dedupAgeFa(time() - (int)$c['at']) : '—'];
    }
    echo json_encode(['ok' => true, 'ttl' => bslCatalogTtl($cnC), 'vendors' => $rows,
        'auto' => (!isset($cnC['bsl_catalog_auto']) || !empty($cnC['bsl_catalog_auto'])),
        'rebuilt' => !empty($_GET['rebuild'])], JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.32 (۴۵ه): گزارشِ بایگانی‌شده‌ها
 *  ?retire_log=1[&limit=N]  → فهرست + خلاصه
 *  ?retire_log_clear=1      → پاک کردن
 * ===================================================================== */
if (isset($_GET['retire_log'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $log   = retireLogRead();
    $items = $log['items'];
    $limit = max(1, min((int)RETIRE_LOG_KEEP, (int)($_GET['limit'] ?? 100)));
    /* خلاصه روی *کلِ* لاگ حساب می‌شود، نه فقط تکه‌ای که برمی‌گردانیم —
       وگرنه با limit کوچک، اعدادِ بالای گزارش هم کوچک می‌شدند. */
    $byMode = []; $byProfile = []; $modes = retireModes();
    foreach ($items as $it) {
        $m = (string)($it['mode'] ?? '?');
        $byMode[$m] = ($byMode[$m] ?? 0) + 1;
        $pn = trim((string)($it['profile'] ?? ''));
        if ($pn !== '') $byProfile[$pn] = ($byProfile[$pn] ?? 0) + 1;
    }
    arsort($byProfile);
    $rows = [];
    foreach (array_slice($items, 0, $limit) as $it) {
        $at = (int)($it['at'] ?? 0);
        $rows[] = $it + ['mode_label' => $modes[(string)($it['mode'] ?? '')] ?? '?',
                         'at_h' => $at > 0 ? date('Y/m/d H:i', $at) : '—'];
    }
    echo json_encode(['ok' => true, 'total' => count($items), 'shown' => count($rows),
        'updated' => (int)($log['updated'] ?? 0),
        'by_mode' => $byMode, 'by_profile' => array_slice($byProfile, 0, 10, true),
        'items' => $rows], JSON_UNESCAPED_UNICODE);
    exit;
}
if (isset($_GET['retire_log_clear'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @unlink(RETIRE_LOG_FILE);
    echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.35 (۴۷د): گزارشِ همگام‌سازی‌ها
 *  ?sync_report=1[&limit=N][&profile=<key>]  → فهرست + متنِ خوانا
 *  ?sync_report_clear=1                      → پاک کردن
 * ===================================================================== */
if (isset($_GET['sync_report'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $log   = syncReportRead();
    $items = is_array($log['items'] ?? null) ? $log['items'] : [];
    $pf    = trim((string)($_GET['profile'] ?? ''));
    if ($pf !== '') {
        $items = array_values(array_filter($items,
            fn($r) => is_array($r) && ((string)($r['key'] ?? '') === $pf)));
    }
    $limit = max(1, min((int)SYNC_REPORT_KEEP, (int)($_GET['limit'] ?? 50)));
    $rows = [];
    foreach (array_slice($items, 0, $limit) as $r) {
        if (!is_array($r)) continue;
        $at = (int)($r['at'] ?? 0);
        $r['at_h'] = $at > 0 ? date('Y/m/d H:i', $at) : '—';
        $r['text'] = syncReportText($r);
        $rows[] = $r;
    }
    echo json_encode(['ok' => true, 'total' => count($items), 'shown' => count($rows),
        'updated' => (int)($log['updated'] ?? 0), 'items' => $rows], JSON_UNESCAPED_UNICODE);
    exit;
}
if (isset($_GET['sync_report_clear'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @unlink(SYNC_REPORT_FILE);
    echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * v8.47: مغایرت‌گیری مقصد با پروفایل‌ها.
 * ?recon=1&target=woo|bsl            → فقط گزارش (پیش‌فرض، امن)
 * &apply=1                           → اعمال تغییرات
 * &mode=off|draft|outofstock|delete  → با موارد اضافی چه شود
 * &fix_price=0                       → قیمت‌ها دست نخورند
 */
/**
 * v8.49: مغایرت‌گیری سمت سرور با گزارش زنده.
 * ?recon=1&target=woo|bsl[&apply=1&mode=...&fix_price=0]  → شروع در پس‌زمینه
 * ?recon_status=1                                          → وضعیت زنده
 * ?recon_result=1                                          → نتیجهٔ کامل
 */
if (isset($_GET['recon'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $target = (string)($_GET['target'] ?? '');
    if ($target !== 'woo' && $target !== 'bsl') {
        echo json_encode(['ok' => false, 'error' => 'مقصد نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    // قفل، تا دو مغایرت‌گیری هم‌زمان اجرا نشوند
    $lockFile = __DIR__ . '/recon.lock';
    $fp = fopen($lockFile, 'c');
    if (!$fp || !flock($fp, LOCK_EX | LOCK_NB)) {
        if ($fp) fclose($fp);
        echo json_encode(['ok' => false, 'error' => 'یک مغایرت‌گیری در حال اجراست',
            'running' => true], JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);
    reconStopClear();

    $apply = !empty($_GET['apply']);
    $cn = loadConnections();
    $mode = (string)($_GET['mode'] ?? ($cn['retire_mode'] ?? 'off'));
    if (!isset(retireModes()[$mode])) $mode = 'off';
    $fixPrice = !isset($_GET['fix_price']) || $_GET['fix_price'] !== '0';
    // v8.64: همهٔ پروفایل‌ها، نه فقط آن‌هایی که همگام‌سازی دوره‌ای دارند
    $allProf = !empty($_GET['all_profiles']);
    // v10.107: همهٔ غرفه‌های باسلام / یک غرفهٔ مشخص
    $allVendors = !empty($_GET['all_vendors']);
    $onlyVid = (int)($_GET['vendor_id'] ?? 0);
    if ($target === 'bsl' && !$allVendors && $onlyVid <= 0) {
        // پیش‌فرض: اگر چند غرفه هست و کاربر تیک نزده، فقط پیش‌فرض — مگر all_vendors
        $allVendors = !empty($_GET['all_shops']);
    }

    /* v10.126: ادامهٔ واقعی از چک‌پوینت — اگر resume=1 و فایلِ پیشرفت برای
       همین مقصد چک‌پوینت دارد، آن را نگه می‌داریم؛ واکشی از کشِ صفحه‌ای ادامه
       می‌یابد. در غیر این صورت از نو. */
    $cp = null;
    if (!empty($_GET['resume']) && is_file(RECON_PROGRESS_FILE)) {
        $old = json_decode((string)@file_get_contents(RECON_PROGRESS_FILE), true);
        if (is_array($old) && (string)($old['target'] ?? '') === $target
            && is_array($old['checkpoint'] ?? null)) {
            $cp = $old['checkpoint'];
        }
    }
    if ($cp === null) {
        localTaskDbForget(RECON_PROGRESS_FILE); @unlink(RECON_PROGRESS_FILE);
        @unlink(reconFetchCursorFile());
        /* v10.126: در شروعِ تازه هم چک‌پوینتِ نازکی می‌سازیم تا مسیرِ
           تکی از واکشیِ قابلِ ادامه (کشِ صفحه‌ای) استفاده کند. */
        $cp = ['target' => $target, 'all_profiles' => $allProf, 'started_at' => time()];
    }
    $cpStartedAt = (int)($cp['started_at'] ?? 0);
    reconProgress(['running' => true, 'done' => false, 'target' => $target,
        'apply' => $apply, 'mode' => $mode, 'all_profiles' => $allProf,
        'all_vendors' => $allVendors, 'vendor_id' => $onlyVid,
        'started_at' => ($cpStartedAt > 0 ? $cpStartedAt : time()),
        'phase' => (!empty($_GET['resume']) ? 'resume' : 'start'),
        /* v10.130: checkpoint کاملِ قبلی را نگه می‌داریم؛ جایگزین‌کردنِ آن
           با یک checkpoint نازک، شناسه‌های اعمال‌شده/غرفه‌های انجام‌شده را
           از بین می‌برد و resume را دوباره‌کار می‌کرد. */
        'checkpoint' => $cp !== null ? $cp : ['target' => $target, 'all_profiles' => $allProf,
            'started_at' => ($cpStartedAt > 0 ? $cpStartedAt : time()),
            'was_resume' => !empty($_GET['resume'])],
        'log_add' => [(!empty($_GET['resume']) ? '↻ ادامه از چک‌پوینت — ' : '') . (($apply ? '🚀 شروع اعمال تغییرات' : '🔍 شروع بررسی') . ' — ')
            . ($target === 'woo' ? 'ووکامرس' : 'باسلام')
            . ($allProf ? ' · همهٔ پروفایل‌ها' : ' · فقط پروفایل‌های همگام‌شونده')
            . ($target === 'bsl' && $allVendors ? ' · همهٔ غرفه‌ها' : '')
            . ($onlyVid > 0 ? (' · غرفه #' . $onlyVid) : '')]]);

    // پاسخ فوری، بعد ادامهٔ کار در پس‌زمینه
    $early = json_encode(['ok' => true, 'started' => true, 'target' => $target],
        JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();

    register_shutdown_function(function () use ($fp, $lockFile) {
        @flock($fp, LOCK_UN); @fclose($fp);
    });

    try {
        $res = reconRun($cn, $target, $apply, $mode, $fixPrice, $allProf, $allVendors, $onlyVid, $cp);
    } catch (Throwable $e) {
        /* cursor و checkpointِ اعمال باید بمانند؛ حذفشان یعنی گزارش بعدی
           از صفحهٔ اول و با PUT/DELETEهای تکراری شروع می‌شود. */
        $reconErrState = is_file(RECON_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(RECON_PROGRESS_FILE), true) : [];
        reconProgress(['running' => false, 'done' => true, 'stale' => true, 'partial' => true, 'error' => $e->getMessage(),
            'checkpoint' => is_array($reconErrState['checkpoint'] ?? null) ? $reconErrState['checkpoint'] : null,
            'log_add' => ['❌ خطا: ' . $e->getMessage() . ' — checkpoint حفظ شد']]);
        exit;
    }
    foreach (['extra', 'price_diff', 'matched_items', 'missing'] as $k) {
        if ($k === 'missing') {
            $res['missing_total'] = (int)($res['missing_total'] ?? count($res['missing'] ?? []));
        } else {
            $res[$k . '_total'] = count($res[$k] ?? []);
        }
        if (isset($res[$k]) && count($res[$k]) > 400) $res[$k] = array_slice($res[$k], 0, 400);
    }
    @file_put_contents(__DIR__ . '/recon_result.json',
        json_encode($res, JSON_UNESCAPED_UNICODE), LOCK_EX);
    $reconLastState = is_file(RECON_PROGRESS_FILE)
        ? json_decode((string)@file_get_contents(RECON_PROGRESS_FILE), true) : [];
    $reconKeepCp = !empty($res['stopped']) || !empty($res['partial']) || empty($res['ok']);
    if (!$reconKeepCp) @unlink(reconFetchCursorFile());   // فقط اجرای کامل cache را مصرف می‌کند
    reconStopClear();
    reconProgress(['running' => false, 'done' => true, 'stopped' => !empty($res['stopped']),
        'partial' => !empty($res['partial']), 'stale' => $reconKeepCp,
        'phase' => $reconKeepCp ? 'stopped' : 'done',
        'extra' => (int)($res['extra_total'] ?? count($res['extra'] ?? [])),
        'diff' => (int)($res['price_diff_total'] ?? count($res['price_diff'] ?? [])),
        'missing' => (int)($res['missing_total'] ?? 0),
        'matched' => (int)($res['matched'] ?? 0), 'repriced' => (int)($res['repriced'] ?? 0),
        'deleted' => (int)($res['deleted'] ?? 0), 'failed' => (int)($res['failed'] ?? 0),
        'result_ok' => !empty($res['ok']), 'error' => $res['error'] ?? '',
        'checkpoint' => $reconKeepCp && is_array($reconLastState['checkpoint'] ?? null)
            ? $reconLastState['checkpoint'] : null,
        'log_add' => [$reconKeepCp ? ('⏸ توقف/ناقص — checkpoint حفظ شد') : '✅ پایان']]);
    exit;
}

/**
 * v8.51: پیشنهاد دستهٔ آموخته‌شده برای چند عنوان یک‌جا.
 * ?catlearn_bulk=1&titles=<json آرایه‌ای از {id,title}>
 * فقط پیشنهاد می‌دهد؛ چیزی را تغییر نمی‌دهد.
 */
if (isset($_GET['catlearn_bulk'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $raw = (string)($_POST['titles'] ?? $_GET['titles'] ?? '[]');
    $rows = json_decode($raw, true);
    if (!is_array($rows)) $rows = [];
    $learned = catLearnLoad();
    $out = [];
    foreach ($rows as $r) {
        if (!is_array($r)) continue;
        $t = trim((string)($r['title'] ?? ''));
        if ($t === '') continue;
        $cid = catLearnLookup($t, $learned);
        if ($cid > 0) {
            // v8.60: کلیدی که واقعاً جواب داد را گزارش کن، نه همیشه یک کلمه
            $usedKey = catFirstWord($t);
            for ($i = catLearnWordCount(); $i >= 1; $i--) {
                $k = catFirstWords($t, $i);
                if (catLearnBestFor($k, $learned) === $cid) { $usedKey = $k; break; }
            }
            $out[] = ['id' => (int)($r['id'] ?? 0), 'title' => $t,
                      'word' => $usedKey, 'cat_id' => $cid];
        }
    }
    echo json_encode(['ok' => true, 'matches' => $out, 'count' => count($out)],
        JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.03 (۱۷): اندپوینت‌های «ایجنتِ مدیریت محصولات»
 *  ?agent_start=1&mode=sim|dry|live  (+POST task)  → شروع در پس‌زمینه
 *  ?agent_status=1[&since=N]                       → وضعیت و لاگِ زنده
 *  ?agent_result=1                                 → گزارشِ کامل
 *  ?agent_stop=1                                   → درخواستِ توقف
 *  ?agent_tools=1                                  → فهرستِ ابزارها
 * ===================================================================== */
/* =====================================================================
   v10.05 (۱۹): «اتوماسیونِ ایجنتی» — کارهای زمان‌بندی‌شده با مدل‌های رایگان

   ایدهٔ کلی: در v10.03 موتورِ ایجنت با فراخوانیِ ابزار ساخته شد و در
   v10.04 رابطش به بخشِ هوش مصنوعی رفت. حالا لایهٔ بعدی: به‌جای اینکه
   کاربر هر بار دستی دستور بدهد، مجموعه‌ای از «کارِ آماده» تعریف می‌کند
   که خودشان در دوره‌های زمانیِ معین اجرا شوند.

   چرا روی کرانِ موجود سوار شد و نه یک زمان‌بندِ جدا: هاستِ اشتراکی فقط
   یک کرانِ سیستمی دارد که همین حالا ?cron_run را می‌زند. ساختنِ زمان‌بندِ
   دومی یعنی کاربر باید یک کرانِ دیگر هم تعریف کند — که اکثراً نمی‌کنند و
   بعد گزارش می‌دهند «کارها اجرا نمی‌شوند». پس autoTick() داخلِ همان
   چرخهٔ کران صدا زده می‌شود.
   ===================================================================== */

/** کاتالوگِ مدل‌های رایگانی که فراخوانیِ ابزار (tool calling) دارند.
 *
