            'el' => 'aiContentJobBox', 'open' => 'aicontentOpen', 'resume' => 'aicontent_start=1',
            'stat' => function (array $p): array {
                return ['پرشد' => (int)($p['filled'] ?? 0), 'ناموفق' => (int)($p['failed'] ?? 0),
                        'رد' => (int)($p['skipped'] ?? 0)];
            },
        ],
    ];
}

/**
 * v10.23 (۳۶ج): نشانیِ «شروعِ دوباره»ی یک کار.
 *
 * فقط نامِ اندپوینت کافی نیست: بیشترِ کارها بدونِ پارامترهای اصلی‌شان
 * دوباره اجرا نمی‌شوند (dedup بدونِ مقصد، recon بدونِ target، ایجنت بدونِ
 * دستورِ کار). خوشبختانه همهٔ این‌ها در خودِ فایلِ پیشرفتِ اجرای قبلی ثبت
 * شده‌اند، پس دقیقاً همان اجرا را بازسازی می‌کنیم. اگر پارامترِ حیاتی نبود،
 * رشتهٔ خالی برمی‌گردد و دکمهٔ «ادامه» اصلاً نشان داده نمی‌شود — بهتر از
 * دکمه‌ای که کلیکش خطا می‌دهد.
 */
function tasksResumeUrl(string $key, array $def, array $p): string {
    $base = trim((string)($def['resume'] ?? ''));
    if ($base === '') return '';
    switch ($key) {
        case 'bsl_send':
        case 'woo_send':
            $qid = trim((string)($p['queue_id'] ?? ''));
            if ($qid === '') return '';
            return $base . '&from_file=1&queue_id=' . rawurlencode($qid)
                . '&start_index=' . max(0, (int)($p['current'] ?? 0)) . '&resume=1';
        case 'matrix_build':
            $profile = trim((string)($p['profile'] ?? 'all')) ?: 'all';
            return $base . '&profile=' . rawurlencode($profile) . '&source=tasks_resume&resume=1';
        case 'matrix_fix':
            $scope = (string)($p['scope'] ?? 'all');
            if (!in_array($scope, ['all', 'woo', 'bsl'], true)) $scope = 'all';
            $delay = max(50, min(2000, (int)($p['delay_ms'] ?? 180)));
            return $base . '&scope=' . $scope . '&delay_ms=' . $delay . '&source=tasks_resume&resume=1';
        /* v10.35 (۴۷ه): ادامهٔ همگام‌سازیِ دستی یعنی «همان پروفایل را دوباره
           از اول اجرا کن». بدونِ کلیدِ پروفایل، اجرای مجدد کلِ پروفایل‌ها را
           راه می‌انداخت — رفتاری که کاربر انتظارش را ندارد، پس دکمه اصلاً
           نشان داده نمی‌شود. */
        case 'manual_sync':
            $pk = trim((string)($p['profile_key'] ?? ''));
            if ($pk === '') return '';
            return $base . '&profile=' . rawurlencode($pk) . '&force=1&resume=1';
        case 'extract':
            $pk = trim((string)($p['profile_key'] ?? ''));
            if ($pk !== '') return $base . '&profile_key=' . rawurlencode($pk) . '&resume=1';
            $u = trim((string)($p['url'] ?? ''));
            if ($u === '') return '';
            return $base . '&url=' . rawurlencode($u) . '&resume=1';
        case 'dedup':
            $t = (string)($p['target'] ?? '');
            if ($t !== 'woo' && $t !== 'bsl') return '';
            /* حالتِ حذف عمداً به «گزارش» برگردانده نمی‌شود: اگر کاربر حذف را
               شروع کرده بود، ادامه هم باید حذف باشد وگرنه کار نیمه می‌ماند. */
            $m = ((string)($p['mode'] ?? 'scan')) === 'delete' ? 'delete' : 'scan';
            /* v10.126: &resume=1 — ادامه از چک‌پوینتِ فایلِ پیشرفت، نه از اول */
            return $base . '&target=' . $t . '&mode=' . $m . '&resume=1';
        case 'catfix':
            $m = (string)($p['mode'] ?? 'ai_text');
            if (!in_array($m, ['ai_text', 'master', 'quorum', 'fallback'], true)) $m = 'ai_text';   /* v10.71 (85) */
            $q = $base . '&mode=' . $m;
            if ((int)($p['product_id'] ?? 0) > 0) $q .= '&product_id=' . (int)$p['product_id'];
            if ((int)($p['quorum'] ?? 0) > 0) $q .= '&quorum=' . (int)$p['quorum'];
            if (!empty($p['all_vendors'])) $q .= '&all_vendors=1';
            if (array_key_exists('use_learn', $p) && empty($p['use_learn'])) $q .= '&use_learn=0';
            if ((int)($p['vendor_id'] ?? 0) > 0) $q .= '&vendor_id=' . (int)$p['vendor_id'];
            /* v10.126: &resume=1 — ادامه از چک‌پوینتِ فایلِ پیشرفت، نه از اول */
            return $q . '&resume=1';
        case 'agent':
            $task = trim((string)($p['task'] ?? ''));
            if ($task === '') return '';
            $q = $base . '&mode=' . rawurlencode((string)($p['mode'] ?? 'dry'))
               . '&task=' . rawurlencode($task);
            if (trim((string)($p['model'] ?? '')) !== '') $q .= '&model=' . rawurlencode((string)$p['model']);
            return $q . '&resume=1';
        /* v10.25 (۳۸د): ادامهٔ کشفِ سلکتور یعنی «همان صفحه را دوباره کاوش کن».
           بدونِ url هیچ معنایی ندارد، پس اگر فایلِ پیشرفت آدرس نداشت اصلاً
           دکمهٔ ادامه نشان داده نمی‌شود. */
        case 'selagent':
            $u = trim((string)($p['url'] ?? ''));
            $lu = trim((string)($p['list_url'] ?? ''));
            if ($u === '' && $lu === '') return '';
            $q = $base . '&kind=' . (((string)($p['kind'] ?? 'list')) === 'detail' ? 'detail' : 'list');
            if ($u !== '') $q .= '&url=' . rawurlencode($u);
            if (trim((string)($p['model'] ?? '')) !== '') $q .= '&model=' . rawurlencode((string)$p['model']);
            if (trim((string)($p['pk'] ?? '')) !== '') $q .= '&pk=' . rawurlencode((string)$p['pk']);
            if ($lu !== '') $q .= '&list_url=' . rawurlencode($lu);
            return $q . '&resume=1';
        case 'ai_test':
            $args = is_array($p['args'] ?? null) ? $p['args'] : [];
            /* ai_test_start روی state.running قدیمی «busy» برمی‌گرداند؛
               unstick همان checkpoint نتایج ذخیره‌شده را نگه می‌دارد و فقط
               مدل‌های تست‌نشده را ادامه می‌دهد. */
            $q = 'ai_test_unstick=1&force=1';
            $vals = ['per_provider' => (int)($args['per'] ?? $p['per_provider'] ?? 50),
                     'msg' => (string)($args['msg'] ?? 'سلام'),
                     'cat' => (string)($args['cat'] ?? 'ادو پرفیوم'),
                     'delay' => (int)($args['delay'] ?? $p['delay_ms'] ?? 120),
                     'conc' => (int)($args['conc'] ?? $p['concurrency'] ?? 4),
                     'nonchat' => !empty($args['nonchat']) ? '1' : '0'];
            foreach ($vals as $k => $v) $q .= '&' . $k . '=' . rawurlencode((string)$v);
            return $q . '&resume=1';
        case 'recon':
            $t = (string)($p['target'] ?? '');
            if ($t !== 'woo' && $t !== 'bsl') return '';
            $q = $base . '&target=' . $t;
            if (!empty($p['apply'])) $q .= '&apply=1';
            if ((string)($p['mode'] ?? '') !== '') $q .= '&mode=' . rawurlencode((string)$p['mode']);
            if (array_key_exists('fix_price', $p) && empty($p['fix_price'])) $q .= '&fix_price=0';
            if (!empty($p['all_profiles'])) $q .= '&all_profiles=1';
            if (!empty($p['all_vendors'])) $q .= '&all_vendors=1';
            if ((int)($p['vendor_id'] ?? 0) > 0) $q .= '&vendor_id=' . (int)$p['vendor_id'];
            /* v10.129: گزارش و اعمال هر دو از cursor/checkpoint ادامه می‌یابند. */
            return $q . '&resume=1';
        case 'suffix':
            $t = (string)($p['target'] ?? '');
            if (!in_array($t, ['woo', 'bsl', 'summary', 'all'], true)) return '';
            $q = $base . '&target=' . $t . '&resume=1';
            if (!empty($p['notify'])) $q .= '&notify=1';
            return $q;
        case 'photofix':
            $q = $base . (!empty($p['dry']) ? '&dry=1' : '') . '&resume=1';
            $profile = trim((string)($p['profile'] ?? ''));
            if ($profile !== '') $q .= '&profile=' . rawurlencode($profile);
            if (!empty($p['notify'])) $q .= '&notify=1';
            return $q;
        case 'aicontent':
            $limit = max(1, min(80, (int)($p['limit'] ?? 0)));
            return $base . ($limit > 0 ? '&limit=' . $limit : '') . '&resume=1';
        case 'bulkedit':
            $cp = is_array($p['checkpoint'] ?? null) ? $p['checkpoint'] : [];
            if (!is_array($cp['ids'] ?? null) || !is_array($cp['ops'] ?? null)
                || trim((string)($cp['target'] ?? '')) === '') return '';
            return $base . '&resume=1';
        default:
            return $base;
    }
}

/** درصدِ پیشرفت را از شکل‌های مختلفِ فایل‌های پیشرفت بیرون می‌کشد.
 *  اگر کار «کل» را نمی‌داند (مثلِ ایجنت که از قبل نمی‌داند چند گام
 *  می‌رود) مقدارِ -1 برمی‌گردد یعنی «نامعلوم» — نوارِ پیشرفت آن‌وقت
 *  حالتِ نامعین می‌گیرد به‌جای اینکه دروغِ ۰٪ نشان بدهد. */
function tasksPercent(array $p): int {
    /* ماتریس درصد را مستقیماً ثبت می‌کند و هنوز در همهٔ فازها total ندارد. */
    if (isset($p['pct']) && is_numeric($p['pct'])) {
        return max(0, min(100, (int)round((float)$p['pct'])));
    }
    $total = (int)($p['total'] ?? $p['cur_total'] ?? 0);
    if ($total <= 0) return -1;
    $cur = (int)($p['current'] ?? $p['processed'] ?? $p['tested'] ?? $p['checked'] ?? $p['cur'] ?? 0);
    if ($cur < 0) $cur = 0;
    if ($cur > $total) $cur = $total;
    return (int)floor($cur * 100 / $total);
}

/* =====================================================================
 *  v10.36 (۴۹الف): «ضربانِ» یک کار — تنها منبعِ حقیقت برای زنده‌بودن.
 *
 *  باگی که کاربر گزارش کرد: کارِ استخراج چند لحظه بعد از شروع در مدیر
 *  وظیفه برچسبِ «رهاشده» می‌گرفت و می‌نوشت «۴۰ دقیقه پیش»، در حالی که
 *  شمارندهٔ همان کارت یک دقیقه پیش عوض شده بود.
 *
 *  ریشه: موتورهای واقعی (استخراج، ارسالِ ووکامرس، ارسالِ باسلام) زمانِ
 *  ضربان را در کلیدِ «last_progress_ts» می‌نویسند — این کلید در تمام
 *  writeProgress‌های آن‌ها هست. ولی tasksState و tasksBuildRow فقط
 *  ts / updated_at / started_at را می‌خواندند. هیچ‌کدام از این سه هرگز
 *  به‌روز نمی‌شد، پس عملاً همیشه started_at خوانده می‌شد: یعنی «سنِ کار»
 *  به‌جای «مدتِ بی‌حرکتی». هر کاری که بیش از ۵ دقیقه طول می‌کشید، از
 *  دقیقهٔ پنجم به بعد «رهاشده» بود — هرچقدر هم فعال.
 *
 *  همین اشتباه پیامدهای زنجیره‌ای داشت: نگهبانِ کران ردیفِ زنده را
 *  «مرده» می‌دید، به پیام‌رسان خطا می‌فرستاد، ردیف را قرمز می‌کرد و چون
 *  ردیفِ قبلی هیچ‌وقت درست بسته نمی‌شد، کارِ بعدی هم راه نمی‌افتاد.
 *
 *  حالا یک تابعِ واحد همهٔ شکل‌های ضربان را می‌شناسد و همه‌جا از همین
 *  استفاده می‌شود، تا دوباره دو تعریفِ واگرا پیدا نشود.
 * ===================================================================== */
function tasksHeartbeat(array $p): int {
    if (!is_array($p) || !$p) return 0;
    $best = 0;
    /* ترتیب مهم نیست چون بیشینه می‌گیریم؛ مهم این است که هیچ‌کدام جا نیفتد.
       last_progress_ts = موتورهای استخراج/ارسال · ts = کارهای ایجنتی
       updated_at = فایل‌های قدیمی‌تر · at = برخی فایل‌های وضعیت */
    foreach (['last_progress_ts', 'ts', 'updated_at', 'at', 'progress_at'] as $k) {
        $v = (int)($p[$k] ?? 0);
        if ($v > $best) $best = $v;
    }
    /* started_at آخرین چاره است: کارِ تازه‌شروع‌شده هنوز ضربانی ننوشته و
       نباید فوراً «رهاشده» شود. ولی هرگز جایگزینِ ضربانِ واقعی نمی‌شود. */
    if ($best <= 0) $best = (int)($p['started_at'] ?? 0);
    return $best;
}

/** وضعیتِ یک کار: running | stale | done | idle
 *
 *  «stale» همان تشخیصی است که تا حالا وجود نداشت: فایل می‌گوید در حال
 *  اجراست ولی مدت‌هاست به‌روز نشده. بدونِ این، کارِ مرده تا ابد قفل
 *  می‌ماند و کاربر نمی‌فهمد چرا دکمهٔ شروع کار نمی‌کند. */
function tasksState(array $p, int $now): string {
    if (!is_array($p) || !$p) return 'idle';
    $running = !empty($p['running']);
    $done    = !empty($p['done']);
    if ($running && !$done) {
        // v10.36 (۴۹الف): ضربانِ واقعی، نه سنِ کار
        $ts = tasksHeartbeat($p);
        if ($ts > 0 && ($now - $ts) > TASKS_STALE_SEC) return 'stale';
        /* resume endpointها ممکن است stale/stopped قدیمی را با merge روی
           فایل نگه دارند؛ running تازه و ضربان تازه حقیقتِ فعلی است و نباید
           دکمهٔ ادامه آن را دوباره به‌عنوان کارِ رهاشده انتخاب کند. */
        return 'running';
    }
    /* عملیاتِ متوقف/خطادار با checkpoint عمداً done=true هم دارند؛ stale
       باید برچسبِ اصلی باشد تا نگهبان کران آن را در نوبت بعد resume کند.
       ai_test نیز برای آزادکردنِ state قدیمی از stalled استفاده می‌کند و
       همگام‌سازیِ دستی cancelled را ثبت می‌کند؛ هر دو همان کارِ ناقص‌اند. */
    if (!empty($p['stale']) || !empty($p['stalled']) || !empty($p['stopped']) || !empty($p['cancelled'])
        || !empty($p['paused']) || !empty($p['partial']) || !empty($p['incomplete'])
        || (array_key_exists('result_ok', $p) && !$p['result_ok']) || !empty($p['error']))
        return 'stale';
    /* بعضی workerها هنگام خاتمهٔ ناگهانی running=false می‌نویسند ولی done
       را false نگه می‌دارند؛ وجودِ checkpoint یعنی اجرای ناقص، نه idle/done. */
    if (!$done && is_array($p['checkpoint'] ?? null) && !empty($p['checkpoint'])) return 'stale';
    if ($done || (int)($p['started_at'] ?? 0) > 0) return 'done';
    return 'idle';
}

/* ---------------- v10.24 (۳۷الف): اولویتِ کارهای پس‌زمینه ---------------- */

/**
 * ترتیبِ ذخیره‌شده را می‌خواند و با رجیستریِ فعلی آشتی می‌دهد.
 *
 * دو حالتِ لبه که حتماً باید درست کار کنند:
 *   • کارِ تازه‌ای به رجیستری اضافه شده که در فایل نیست ⇒ ته صف می‌رود
 *     (نه اینکه ناپدید شود).
 *   • کاری از رجیستری حذف شده ولی هنوز در فایل هست ⇒ نادیده گرفته می‌شود
 *     (نه اینکه یک ردیفِ ارواح بسازد).
 * خروجی همیشه دقیقاً همان کلیدهای رجیستری است، فقط مرتب‌شده.
 */
function tasksOrder(?array $reg = null): array {
    if ($reg === null) $reg = tasksRegistry();
    $keys  = array_keys($reg);
    $saved = [];
    if (is_file(TASKS_ORDER_FILE)) {
        $d = json_decode((string)@file_get_contents(TASKS_ORDER_FILE), true);
        if (is_array($d['order'] ?? null)) $saved = $d['order'];
    }
    $out = [];
    foreach ($saved as $k) {
        $k = (string)$k;
        if (isset($reg[$k]) && !in_array($k, $out, true)) $out[] = $k;
    }
    foreach ($keys as $k) if (!in_array($k, $out, true)) $out[] = $k;
    return $out;
}

/** ترتیبِ تازه را می‌نویسد (فقط کلیدهای معتبر) */
function tasksOrderSave(array $order): bool {
    $reg = tasksRegistry();
    $clean = [];
    foreach ($order as $k) {
        $k = (string)$k;
        if (isset($reg[$k]) && !in_array($k, $clean, true)) $clean[] = $k;
    }
    foreach (array_keys($reg) as $k) if (!in_array($k, $clean, true)) $clean[] = $k;
    return (bool)@file_put_contents(TASKS_ORDER_FILE,
        json_encode(['order' => $clean, 'at' => time()], JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/**
 * یک کار را در صف جابه‌جا می‌کند. خروجی: [ok, from, to, order]
 * $dir: up | down | top | bottom
 */
function tasksOrderMove(string $key, string $dir): array {
    $order = tasksOrder();
    $idx = array_search($key, $order, true);
    if ($idx === false) return ['ok' => false, 'error' => 'کارِ ناشناخته'];
    $n = count($order);
    $to = $idx;
    if     ($dir === 'up')     $to = max(0, $idx - 1);
    elseif ($dir === 'down')   $to = min($n - 1, $idx + 1);
    elseif ($dir === 'top')    $to = 0;
    elseif ($dir === 'bottom') $to = $n - 1;
    else return ['ok' => false, 'error' => 'جهتِ نامعتبر'];
    if ($to !== $idx) {
        array_splice($order, $idx, 1);
        array_splice($order, $to, 0, [$key]);
        tasksOrderSave($order);
    }
    return ['ok' => true, 'from' => $idx, 'to' => $to, 'order' => $order];
}

/** یک ردیفِ آمادهٔ نمایش از روی رجیستری + فایلِ پیشرفت */
function tasksBuildRow(string $key, array $def, int $now): array {
    $file = (string)$def['file'];
    $p    = localTaskStateRead($file, []);
    $st   = tasksState($p, $now);
    /* heartbeat کهنه نباید worker دارای flock را stale نشان دهد؛ همین گارد
       مرکزی، UI و هر دو مسیر resume/clear را از اجرای موازی بازمی‌دارد. */
    if ($st === 'stale') {
        $taskLock = tasksLockFile($key);
        if ($taskLock !== '' && is_file($taskLock) && !tasksResumeLockDead($taskLock)) $st = 'running';
    }
    $ts   = tasksHeartbeat($p);   // v10.36 (۴۹الف): همان ضربانی که وضعیت با آن سنجیده شد
    $stat = [];
    foreach (($def['stat'])($p) as $k => $v) if ((int)$v !== 0) $stat[] = ['k' => $k, 'v' => (int)$v];
    /* لاگِ این کار — هر کار شکلِ خودش را دارد (log یا recent_log) */
    $log = [];
    $raw = is_array($p['log'] ?? null) ? $p['log'] : (is_array($p['recent_log'] ?? null) ? $p['recent_log'] : []);
    foreach (array_slice($raw, -12) as $l) {
        if (is_array($l)) {
            $msg = (string)($l['m'] ?? '');
            if (!empty($l['item_id'])) $msg .= ' · 🔎' . (string)$l['item_id'];
            $log[] = $msg;
        } else $log[] = (string)$l;
    }
    /* v10.23 (۳۶ج): «ادامه» فقط برای کارِ رهاشده یا تمام‌شده معنا دارد؛ روی
       کارِ در حال اجرا نشان دادنش فقط باعثِ اجرای موازیِ ناخواسته می‌شود. */
    $resumeUrl = ($st === 'stale' || $st === 'done' || $st === 'idle')
        ? tasksResumeUrl($key, $def, $p) : '';
    return [
        'key'       => $key,
        'title'     => (string)$def['title'],
        'icon'      => (string)$def['icon'],
        'tab'       => (string)$def['tab'],
        /* v10.23 (۳۶الف): نشانیِ ناوبریِ کلیک روی کارت */
        'pane'      => (string)($def['pane'] ?? ''),
        'smenu'     => (string)($def['smenu'] ?? ''),
        'ai'        => (string)($def['ai'] ?? ''),
        'el'        => (string)($def['el'] ?? ''),
        'open'      => (string)($def['open'] ?? ''),
        /* v10.23 (۳۶ج) */
        'resume'    => $resumeUrl,
        'resumable' => $resumeUrl !== '',
        'state'     => $st,
        'percent'   => $st === 'running' || $st === 'stale' ? tasksPercent($p) : ($st === 'done' ? 100 : 0),
        'total'     => (int)($p['total'] ?? $p['cur_total'] ?? 0),
        'current'   => (int)($p['current'] ?? $p['processed'] ?? $p['tested'] ?? $p['cur'] ?? 0),
        'phase'     => (string)($p['phase'] ?? ''),
        'last'      => (string)($p['last_title'] ?? $p['summary'] ?? ''),
        'started'   => (int)($p['started_at'] ?? 0),
        'ts'        => $ts,
        'age'       => $ts > 0 ? max(0, $now - $ts) : 0,
        'cancelled' => !empty($p['cancelled']),
        'stoppable' => (string)$def['stop'] !== '' && $st === 'running',
        'stop'      => (string)$def['stop'],
        'clearable' => $st === 'done' || $st === 'stale',
        'stats'     => $stat,
        'log'       => $log,
    ];
}

/**
 * v10.131: نگاشتِ مرکزیِ قفل و سیگنالِ توقفِ وظایفِ مدیر.
 *
 * پیش از این چهار کارِ server-side (مغایرت‌گیری، گزارشِ پسوند، ساختِ
 * ماتریس، ویرایش گروهی و عکس‌دار کردن) در رجیستری دیده می‌شدند، اما چون
 * stop خالی داشتند، مسیرِ عمومیِ مدیر نمی‌توانست واقعاً متوقفشان کند.
 * یک نگاشتِ واحد، stop/resume/clear را از هم واگرا نمی‌گذارد.
 */
function tasksLockFile(string $key): string {
    $files = [
        'manual_sync' => MANUAL_SYNC_LOCK_FILE,
        'bsl_send' => __DIR__ . '/bsl_backend.lock',
        'woo_send' => __DIR__ . '/woo_backend.lock',
        'extract' => EXTRACT_LOCK_FILE,
        'dedup' => DEDUP_LOCK_FILE,
        'agent' => AGENT_LOCK_FILE,
        'catfix' => CATFIX_LOCK_FILE,
        'selagent' => SELAGENT_LOCK_FILE,
        'ai_test' => AI_TEST_LOCK_FILE,
        'aicontent' => AICONTENT_LOCK_FILE,
        'recon' => __DIR__ . '/recon.lock',
        'suffix' => __DIR__ . '/suffix.lock',
        'bulkedit' => __DIR__ . '/bulkedit.lock',
        'photofix' => __DIR__ . '/photofix.lock',
        'matrix_build' => SYNC_MATRIX_LOCK_FILE,
        'matrix_fix' => SYNC_MATRIX_FIX_LOCK_FILE,
    ];
    return (string)($files[$key] ?? '');
}

function tasksStopFile(string $key): string {
    $files = [
        'manual_sync' => MANUAL_SYNC_STOP_FILE,
        'bsl_send' => BSL_STOP_FILE,
        'woo_send' => WOO_STOP_FILE,
        'extract' => EXTRACT_STOP_FILE,
        'dedup' => DEDUP_STOP_FILE,
        'agent' => AGENT_STOP_FILE,
        'catfix' => CATFIX_STOP_FILE,
        'selagent' => SELAGENT_STOP_FILE,
        'ai_test' => AI_TEST_STOP_FILE,
        'aicontent' => AICONTENT_STOP_FILE,
        'recon' => RECON_STOP_FILE,
        'suffix' => SUFFIX_STOP_FILE,
        'bulkedit' => BULKEDIT_STOP_FILE,
        'photofix' => PHOTOFIX_STOP_FILE,
        'matrix_build' => SYNC_MATRIX_STOP_FILE,
        'matrix_fix' => SYNC_MATRIX_FIX_STOP_FILE,
    ];
    return (string)($files[$key] ?? '');
}

/** آیا قفلِ موتور واقعاً مرده است؟ unlink روی قفلِ در دستِ پردازه ممنوع است. */
function tasksResumeLockDead(string $file): bool {
    if (!is_file($file)) return true;
    $fp = @fopen($file, 'c');
    if (!$fp) return false;
    $dead = @flock($fp, LOCK_EX | LOCK_NB);
    if ($dead) @flock($fp, LOCK_UN);
    @fclose($fp);
    return $dead;
}

/**
 * v10.24 (۳۷ج): ادامه/شروعِ دوبارهٔ یک کار — منطقِ مشترکِ «تکی» و «همه».
 *
 * پیش از این، این منطق داخلِ خودِ اندپوینتِ ?tasks_resume نوشته شده بود.
 * با آمدنِ «ادامهٔ همه» باید دو جا صدا زده می‌شد، و کپی‌کردنش یعنی دیر یا
 * زود یکی از دو نسخه اصلاح شود و دیگری نه — مثلاً قفلِ یک کارِ تازه فقط
 * در یکی از دو مسیر پاک شود.
 */
function tasksResumeOne(string $key): array {
    $reg = tasksRegistry();
    if (!isset($reg[$key])) return ['ok' => false, 'error' => 'کارِ ناشناخته'];
    $def = $reg[$key];
    $row = tasksBuildRow($key, $def, time());
    if ($row['state'] === 'running')
        return ['ok' => false, 'error' => 'این کار همین حالا در حال اجراست'];
    $url = (string)$row['resume'];
    if ($url === '')
        return ['ok' => false, 'error' => 'برای این کار «ادامه» تعریف نشده — از تبِ خودش دوباره شروعش کنید'];

    /* v10.129: هر موتور قفل و checkpoint خودش را دارد. قفلِ آزادشده با پایانِ handle دوباره قابل گرفتن است؛ فایلِ lock حذف نمی‌شود و
       فایل پیشرفت عمداً نگه داشته می‌شود
       تا پارامترها و نقطهٔ امنِ اجرای قبلی از بین نرود. */
    $taskLock = tasksLockFile($key);
    if ($taskLock !== '' && is_file($taskLock)) {
        /* stale/paused بودنِ progress به‌تنهایی دلیلِ کشتنِ worker نیست؛
           هر resume فقط وقتی dispatch می‌شود که flock واقعاً آزاد باشد. */
        if (!tasksResumeLockDead($taskLock))
            return ['ok' => false, 'error' => 'این کار هنوز قفلِ فعال دارد — اجرای موازی ساخته نشد'];
        /* stop signal را اینجا حذف نمی‌کنیم؛ worker پس از گرفتنِ lock خودش
           آن را مصرف می‌کند تا بین probe و dispatch race ایجاد نشود. */
    }

    /* صف‌های ارسال تنها از مسیرِ checkpoint-aware خودشان ادامه می‌یابند؛
       tasksResumeOne هرگز یک worker عمومیِ موازی برایشان شلیک نمی‌کند. */
    if ($key === 'bsl_send' || $key === 'woo_send') {
        $which = $key === 'bsl_send' ? 'bsl' : 'woo';
        if (!empty($GLOBALS['_queueResumeFired'][$which])) {
            return ['ok' => true, 'resumed' => $key, 'already_dispatched' => true];
        }
        $rec = queueStallRecover($which, max(120, (int)(loadConnections()['stall_after'] ?? 300)), false, 2500, true);
        if (!empty($rec['resumed'])) {
            return ['ok' => true, 'resumed' => $key, 'url' => $url,
                'dispatched' => true, 'resume_from' => (int)($rec['resume_from'] ?? 0)];
        }
        return ['ok' => false, 'error' => !empty($rec['deferred'])
            ? 'ادامهٔ صف به‌تازگی شلیک شده و در حال اجراست'
            : 'صفِ قابل‌ادامه‌ای برای این ردیف پیدا نشد'];
    }

    $post = null;
    if ($key === 'extract') {
        $pk = trim((string)($row['profile_key'] ?? ''));
        if ($pk === '') {
            $p = is_file((string)$def['file'])
                ? (array)json_decode((string)@file_get_contents((string)$def['file']), true) : [];
            $pk = trim((string)($p['profile_key'] ?? ''));
            if ($pk === '' && trim((string)($p['url'] ?? '')) !== '') $pk = profileKey((string)$p['url']);
        }
        if ($pk === '') return ['ok' => false, 'error' => 'کلید پروفایل استخراج در checkpoint نیست'];
        /* workerِ فرزند باید خودش reservation را بگیرد؛ parent نباید بین
           probe و fireAndForget checkpoint را mutate کند. */
        $url = 'action=backend_extract&profile_key=' . rawurlencode($pk)
             . '&resume=1';
    } elseif ($key === 'bulkedit') {
        $p = is_file((string)$def['file'])
            ? (array)json_decode((string)@file_get_contents((string)$def['file']), true) : [];
        $cp = is_array($p['checkpoint'] ?? null) ? $p['checkpoint'] : [];
        if (!is_array($cp['ids'] ?? null) || !is_array($cp['ops'] ?? null)
            || !in_array((string)($cp['target'] ?? ''), ['woo', 'bsl'], true)) {
            return ['ok' => false, 'error' => 'checkpoint ویرایش گروهی ناقص است'];
        }
        $post = [
            'target' => (string)$cp['target'], 'ids' => json_encode(array_values($cp['ids']), JSON_UNESCAPED_UNICODE),
            'ops' => json_encode($cp['ops'], JSON_UNESCAPED_UNICODE),
            'dry' => !empty($cp['dry']) ? '1' : '0', 'notify' => !empty($cp['notify']) ? '1' : '0',
        ];
    }

    $started = fireAndForget($url, 2500, $post);
    return ['ok' => $started, 'resumed' => $key, 'url' => $url,
            'dispatched' => $started,
            'error' => $started ? '' : 'worker برای ادامه پاسخ نداد'];
}

/* ═══════════ v10.39 (۵۲): ادامهٔ خودکارِ کارهای رهاشده ═══════════
 *
 * تا ۱۰.۳۸ فقط سه چیز خودکار جان می‌گرفتند: صفِ باسلام، صفِ ووکامرس و
 * استخراج. پنج کارِ دیگر (همگام‌سازیِ دستی، حذفِ تکراری، اصلاحِ دسته،
 * ایجنت، کشفِ سلکتور) فقط با دکمهٔ دستی ادامه می‌یافتند — یعنی اگر شبانه
 * هاست ری‌استارت می‌شد، کار تا وقتی خودتان صفحه را باز نمی‌کردید رها
 * می‌ماند. خودِ موتورِ «ادامه» (tasksResumeOne) از ۱۰.۲۴ آماده بود و فقط
 * هیچ‌وقت از سمتِ سرور صدا زده نمی‌شد.
 *
 * چرا با سقف و نه بی‌قید: کاری که علتِ خرابی‌اش پابرجاست (دسترسیِ فایل،
 * توکنِ منقضی) هر تیک دوباره رها می‌شود. بدونِ سقف این می‌شود یک حلقهٔ
 * بی‌پایانِ شلیک که روی هاستِ اشتراکی بقیهٔ کارها را هم کند می‌کند.
 */

/** دفترچهٔ تلاش‌های خودکار: کلیدِ کار ⇒ فهرستِ زمان‌ها (فقط داخلِ پنجره) */
function autoResumeLogRead(): array {
    if (!is_file(AUTO_RESUME_LOG_FILE)) return [];
    $d = json_decode((string)@file_get_contents(AUTO_RESUME_LOG_FILE), true);
    return is_array($d) ? $d : [];
}

/** شمارشِ تلاش‌های همین کار در پنجرهٔ اخیر. رکوردهای کهنه همین‌جا می‌ریزند
 *  دور تا فایل بی‌نهایت رشد نکند. */
function autoResumeCount(string $key, int $now): int {
    $log = autoResumeLogRead();
    $hits = is_array($log[$key] ?? null) ? $log[$key] : [];
    $keep = [];
    foreach ($hits as $t) if (($now - (int)$t) < AUTO_RESUME_WINDOW) $keep[] = (int)$t;
    return count($keep);
}

/** ثبتِ یک تلاشِ خودکار + پاک‌سازیِ رکوردهای خارج از پنجره */
function autoResumeMark(string $key, int $now): void {
    $log = autoResumeLogRead();
    $out = [];
    foreach ($log as $k => $hits) {
        if (!is_array($hits)) continue;
        $keep = [];
        foreach ($hits as $t) if (($now - (int)$t) < AUTO_RESUME_WINDOW) $keep[] = (int)$t;
        if ($keep) $out[$k] = $keep;
    }
    $out[$key][] = $now;
    @file_put_contents(AUTO_RESUME_LOG_FILE,
        json_encode($out, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/* =====================================================================
 *  v10.125: «ادامهٔ خودکار»ِ پیشرفت‌آگاه برای همهٔ کارهای رهاشده.
 *
 *  تا ۱۰.۱۲۴ این بخش (v10.39) با سقفِ ساعتیِ کور کار می‌کرد: هر کار در
 *  یک ساعت حداکثر auto_resume_max بار ادامه می‌یافت، چه جلو رفته باشد چه
 *  نه. برای کارِ طولانیِ سالم (مثلاً حذفِ تکراری روی چند هزار محصول که
 *  هاست هر بار وسطش می‌کُشد) این یعنی بعد از چند تیک به‌کلی مهار می‌شد
 *  و تا یک ساعت رها می‌ماند — دقیقاً همان بیماری‌ای که برای استخراج در
 *  v10.124 رفع شد.
 *
 *  اینجا همان روشِ استخراج تعمیم داده شده: امضای پیشرفتِ کار از روی
 *  فایلِ پیشرفتش ساخته می‌شود. اگر بین دو تلاش عوض شده باشد یعنی کار
 *  جلو رفته و شمارنده صفر می‌شود (هر تیک ادامه می‌یابد)؛ فقط تکرارِ
 *  بدونِ پیشرفت مهار می‌شود تا کارِ واقعاً خراب حلقه نسازد.
 * ===================================================================== */

/** امضای پیشرفتِ یک کار از روی فایلِ پیشرفت — فقط شمارنده‌ها، نه زمان */
function taskProgressSig(array $p): string {
    /* فقط مقادیرِ پیشرفت؛ timestamp (ts/at/started_at) عمداً نیست وگرنه
       هر تلاش «جدید» به نظر می‌رسید و سقف هیچ‌وقت عمل نمی‌کرد. */
    $keys = ['phase', 'pct', 'current', 'total', 'processed', 'tested', 'checked', 'cur', 'cur_total', 'step',
             'calls', 'fixed', 'filled', 'edited', 'sent', 'updated', 'groups', 'dups',
             'ok_n', 'fail_n', 'skip_n', 'sent_n', 'del_n', 'price_n',
             'deleted', 'diff', 'extra', 'matched', 'repriced', 'failed', 'no_ai',
             'no_cat', 'asked', 'skip_same', 'skip_tried', 'found', 'total_log_count',
             'cur', 'cur_total', 'detail_current', 'page', 'scanned', 'chunks'];
    $out = [];
    foreach ($keys as $k) {
        if (!array_key_exists($k, $p)) continue;
        $v = $p[$k];
        if (is_array($v))      $v = count($v);
        elseif (is_bool($v))   $v = $v ? '1' : '0';
        elseif (is_float($v))  $v = (int)$v;
        $out[] = $k . '=' . (string)$v;
    }
    return implode('|', $out);
}

/** دفترچهٔ امضا/تلاشِ ادامهٔ خودکار — کلیدِ کار ⇒ [sig, at, tries] */
function autoResumeBookRead(): array {
    if (!is_file(AUTO_RESUME_BOOK_FILE)) return [];
    $d = json_decode((string)@file_get_contents(AUTO_RESUME_BOOK_FILE), true);
    return is_array($d) ? $d : [];
}

/** رکوردِ یک کار از دفترچه */
function autoResumeBookSig(string $key): array {
    $all = autoResumeBookRead();
    $row = is_array($all[$key] ?? null) ? $all[$key] : null;
    if ($row === null) return ['sig' => '', 'at' => 0, 'tries' => 0];
    return [
        'sig'   => (string)($row['sig'] ?? ''),
        'at'    => (int)($row['at'] ?? 0),
        'tries' => (int)($row['tries'] ?? 0),
    ];
}

/** ثبتِ امضا و شمارندهٔ تلاش + پاک‌سازیِ رکوردهای خارج از پنجره */
function autoResumeBookSet(string $key, string $sig, int $tries): void {
    $all = autoResumeBookRead();
    $now = time();
    foreach ($all as $k => $r) {
        if (!is_array($r)) { unset($all[$k]); continue; }
        if ($now - (int)($r['at'] ?? 0) > AUTO_RESUME_WINDOW) unset($all[$k]);
    }
    $all[$key] = ['sig' => $sig, 'at' => $now, 'tries' => $tries];
    @file_put_contents(AUTO_RESUME_BOOK_FILE,
        json_encode($all, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/**
 * v10.24 (۳۷الف): همهٔ ردیف‌ها، مرتب‌شده بر اساس اولویتِ کاربر.
 *
 *  یک جا ساخته می‌شود تا هر مصرف‌کننده‌ای (فهرستِ مدیر وظیفه، نگهبانِ کران،
 *  «ادامهٔ همه») دقیقاً همان ترتیب را ببیند. اگر هرکدام خودش مرتب می‌کرد،
 *  دیر یا زود دو جا از هم واگرا می‌شدند و کاربر می‌دید ترتیبی که چیده در
 *  رفتارِ واقعی رعایت نمی‌شود.
 */
function tasksRowsOrdered(int $now): array {
    $reg  = tasksRegistry();
    $rows = [];
    foreach (tasksOrder($reg) as $rank => $key) {
        $row = tasksBuildRow($key, $reg[$key], $now);
        $row['rank'] = $rank + 1;        // نمایشِ ۱-پایه
        $rows[] = $row;
    }
    return $rows;
}

/** فهرستِ زندهٔ همهٔ کارها + کارهای زمان‌بندی‌شده در یک پاسخ.
 *  مدیر وظیفه فقط همین یک اندپوینت را poll می‌کند تا با باز بودنِ
 *  پنجره ده‌تا درخواستِ موازی روی هاستِ اشتراکی نریزد. */
if (isset($_GET['tasks_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $now  = time();
    /* v10.24 (۳۷الف): ترتیب دیگر ترتیبِ ثابتِ رجیستری نیست — اولویتِ کاربر است */
    $rows = tasksRowsOrdered($now);

    /* کارهای زمان‌بندی‌شدهٔ ایجنت هم بخشی از «وظایفِ پس‌زمینه»اند، ولی
       جنسشان فرق دارد: تکرارشونده‌اند و اولویت/فاصله دارند. جدا برمی‌گردند
       تا رابط بتواند برایشان دکمه‌های خودشان را بگذارد. */
    $jobs = [];
    foreach (autoLoadJobs() as $j) {
        $j['next_label'] = autoNextRunLabel($j, $now);
        $j['due']        = autoJobDue($j, $now);
        $jobs[] = $j;
    }
    $running = 0; $stale = 0;
    foreach ($rows as $r) { if ($r['state'] === 'running') $running++; if ($r['state'] === 'stale') $stale++; }
    echo json_encode(['ok' => true, 'now' => $now, 'tasks' => $rows, 'jobs' => $jobs,
        'running' => $running, 'stale' => $stale,
        'stale_after' => TASKS_STALE_SEC], JSON_UNESCAPED_UNICODE);
    exit;
}

/** توقفِ یک کار — همان اندپوینتِ توقفِ خودِ آن کار را داخلی صدا می‌زند.
 *  به‌جای تکرارِ منطقِ توقف، فقط فایلِ سیگنالِ همان کار نوشته می‌شود؛
 *  دقیقاً همان کاری که دکمهٔ توقفِ داخلِ تب می‌کند. */
if (isset($_GET['tasks_stop'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $key = (string)($_GET['key'] ?? '');
    $reg = tasksRegistry();
    if (!isset($reg[$key])) { echo json_encode(['ok' => false, 'error' => 'کارِ ناشناخته'], JSON_UNESCAPED_UNICODE); exit; }
    $sf = tasksStopFile($key);
    if ($sf === '') { echo json_encode(['ok' => false, 'error' => 'این کار توقفِ دستی ندارد'], JSON_UNESCAPED_UNICODE); exit; }
    $stopAt = time();
    @file_put_contents($sf, json_encode(['at' => $stopAt], JSON_UNESCAPED_UNICODE), LOCK_EX);
    /* همگام‌سازیِ دستی چند موتور را پشتِ سر هم اجرا می‌کند؛ stop آن باید
       به همهٔ موتورهای درگیر برسد، نه فقط به orchestrator. */
    if ($key === 'manual_sync') {
        foreach ([BSL_STOP_FILE, WOO_STOP_FILE, EXTRACT_STOP_FILE] as $_sf) {
            @file_put_contents($_sf, json_encode(['stop' => true, 'at' => $stopAt], JSON_UNESCAPED_UNICODE), LOCK_EX);
        }
    }
    echo json_encode(['ok' => true, 'stopped' => $key], JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * v10.23 (۳۶ج): ادامه/شروعِ دوبارهٔ یک کارِ گیرکرده.
 *
 * چرا لازم بود: وقتی پردازهٔ یک کار وسطِ راه کشته می‌شد (تایم‌اوتِ هاست،
 * ری‌استارتِ PHP-FPM)، مدیر وظیفه آن را «رهاشده» نشان می‌داد ولی تنها
 * دکمه‌اش «🗑 پاک» بود. کاربر باید ردِ کار را پاک می‌کرد، بعد خودش می‌گشت
 * تا تبِ اصلیِ آن کار و دکمهٔ شروعش را پیدا کند — و اگر پارامترها را
 * یادش نبود، از اول تنظیمشان می‌کرد.
 *
 * حالا همان‌جا: قفل و فایلِ پیشرفتِ مرده پاک می‌شود و اندپوینتِ شروعِ اصلیِ
 * همان کار — با همان پارامترهای اجرای قبلی — از داخلِ سرور صدا زده می‌شود.
 */
if (isset($_GET['tasks_resume'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $res = tasksResumeOne((string)($_GET['key'] ?? ''));
    echo json_encode($res, JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * v10.24 (۳۷ج): «ادامهٔ همهٔ کارهای گیرکرده» — با رعایتِ اولویت.
 *
 * وقتی هاست یک بار ری‌استارت می‌شود، معمولاً چند کار با هم می‌میرند. تا
 * اینجا کاربر باید تک‌تک روی «▶ ادامه» می‌زد. حالا یک دکمه همه را برمی‌گرداند،
 * و مهم‌تر: **به ترتیبِ اولویتی که خودش چیده** — چون پاسخِ workerها
 * زودهنگام است، فقط یک کار در هر dispatch آغاز می‌شود و بقیه بعد از آزادشدنِ
 * کارِ بالاتر در کران بعدی جان می‌گیرند؛ فاصلهٔ ثابت جایِ ترتیب را نمی‌گیرد.
 */
if (isset($_GET['tasks_resume_all'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $now  = time();
    $only = (string)($_GET['only'] ?? 'stale');   // stale | stale_done
    $rows = tasksRowsOrdered($now);
    $done = []; $skipped = []; $dispatched = false;
    foreach ($rows as $r) {
        $st = (string)$r['state'];
        $want = $only === 'stale_done' ? in_array($st, ['stale', 'done'], true) : ($st === 'stale');
        if (!$want) continue;
        if (empty($r['resumable'])) { $skipped[] = ['key' => $r['key'], 'why' => 'ادامه ندارد']; continue; }
        if ($dispatched) {
            /* worker قبلی با پاسخِ زودهنگام هنوز ممکن است زنده باشد؛
               این ردیف عمداً در checkpoint خودش می‌ماند تا کران بعدی، پس
               از آزادشدنِ قبلی، آن را به همان ترتیب بردارد. */
            $skipped[] = ['key' => $r['key'], 'why' => 'پس از پایانِ کارِ اولویتِ بالاتر، در کران بعدی ادامه می‌یابد'];
            continue;
        }
        $one = tasksResumeOne((string)$r['key']);
        if (!empty($one['ok'])) {
            $done[] = ['key' => $r['key'], 'title' => $r['title'], 'rank' => $r['rank']];
            $dispatched = true;
        } else {
            $skipped[] = ['key' => $r['key'], 'why' => (string)($one['error'] ?? '')];
            /* قفلِ فعال یا dispatch نامطمئن: به کارِ بعدی نرو تا overlap نسازیم. */
            if (strpos((string)($one['error'] ?? ''), 'فعال') !== false
                || strpos((string)($one['error'] ?? ''), 'پاسخ نداد') !== false) $dispatched = true;
        }
    }
    echo json_encode(['ok' => true, 'resumed' => $done, 'skipped' => $skipped,
        'count' => count($done), 'sequential' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

/** v10.24 (۳۷الف): جابه‌جاییِ اولویتِ یک کارِ پس‌زمینه */
if (isset($_GET['tasks_order'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $key = (string)($_GET['key'] ?? '');
    $dir = (string)($_GET['dir'] ?? '');
    if ($dir === 'reset') {
        @unlink(TASKS_ORDER_FILE);
        echo json_encode(['ok' => true, 'reset' => true, 'order' => tasksOrder()], JSON_UNESCAPED_UNICODE); exit;
    }
    echo json_encode(tasksOrderMove($key, $dir), JSON_UNESCAPED_UNICODE);
    exit;
}

/** پاک‌کردنِ ردِ یک کارِ تمام‌شده یا رهاشده.
 *  فایلِ پیشرفت حذف می‌شود تا کار از «تمام‌شده» به «بی‌کار» برگردد و
 *  قفلِ احتمالی‌اش هم برداشته شود — همان کاری که تا حالا باید دستی با
 *  حذفِ فایل روی هاست انجام می‌شد. */
if (isset($_GET['tasks_clear'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $key = (string)($_GET['key'] ?? '');
    $reg = tasksRegistry();
    if ($key === 'all') {
        $n = 0; $now = time();
        foreach ($reg as $k => $def) {
            $row = tasksBuildRow($k, $def, $now);
            if ($row['state'] === 'running') continue;   // کارِ زنده دست نمی‌خورد
            if (@unlink((string)$def['file'])) $n++;
        }
        echo json_encode(['ok' => true, 'cleared' => $n], JSON_UNESCAPED_UNICODE); exit;
    }
    if (!isset($reg[$key])) { echo json_encode(['ok' => false, 'error' => 'کارِ ناشناخته'], JSON_UNESCAPED_UNICODE); exit; }
    $now = time();
    $row = tasksBuildRow($key, $reg[$key], $now);
    if ($row['state'] === 'running') {
        echo json_encode(['ok' => false, 'error' => 'این کار در حال اجراست — اول متوقفش کنید'], JSON_UNESCAPED_UNICODE); exit;
    }
    /* کارِ رهاشده ممکن است قفلش هم جا مانده باشد */
    $taskLock = tasksLockFile($key);
    if ($taskLock !== '' && is_file($taskLock)) {
        if (!tasksResumeLockDead($taskLock)) {
            echo json_encode(['ok' => false, 'error' => 'قفلِ فعال وجود دارد — فایلِ پیشرفت پاک نشد'], JSON_UNESCAPED_UNICODE); exit;
        }
        /* lock مسیرش را حفظ می‌کند؛ فقط فایلِ progress پاک می‌شود. */
    }
    @unlink((string)$reg[$key]['file']);
    echo json_encode(['ok' => true, 'cleared' => 1], JSON_UNESCAPED_UNICODE);
    exit;
}

/** اولویت‌بندیِ کارهای زمان‌بندی‌شده: جابه‌جاییِ یک کار در صف.
 *
 *  ترتیبِ آرایه واقعاً معنا دارد — autoTick از بالا به پایین می‌رود و
 *  در هر تیک فقط AUTO_MAX_PER_TICK کار را می‌دواند. پس کاری که بالاتر
 *  باشد زودتر اجرا می‌شود. تا حالا این ترتیب فقط با حذف و ساختِ دوباره
 *  قابلِ تغییر بود.
 */
if (isset($_GET['tasks_reorder'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $id  = trim((string)($_GET['id'] ?? ''));
    $dir = (string)($_GET['dir'] ?? '');
    $jobs = autoLoadJobs();
    $idx = -1;
    foreach ($jobs as $i => $j) if ((string)$j['id'] === $id) { $idx = $i; break; }
    if ($idx < 0) { echo json_encode(['ok' => false, 'error' => 'کار پیدا نشد'], JSON_UNESCAPED_UNICODE); exit; }
    $to = $idx;
    if ($dir === 'up')        $to = max(0, $idx - 1);
    elseif ($dir === 'down')  $to = min(count($jobs) - 1, $idx + 1);
    elseif ($dir === 'top')   $to = 0;
    elseif ($dir === 'bottom') $to = count($jobs) - 1;
    else { echo json_encode(['ok' => false, 'error' => 'جهتِ نامعتبر'], JSON_UNESCAPED_UNICODE); exit; }
    if ($to !== $idx) {
        $row = $jobs[$idx];
        array_splice($jobs, $idx, 1);
        array_splice($jobs, $to, 0, [$row]);
        autoSaveJobs($jobs);
    }
    echo json_encode(['ok' => true, 'from' => $idx, 'to' => $to], JSON_UNESCAPED_UNICODE);
    exit;
}

/** فهرستِ کارها با وضعیتِ زندهٔ هرکدام */
if (isset($_GET['auto_jobs'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $now  = time();
    $jobs = autoLoadJobs();
    $out  = [];
    foreach ($jobs as $j) {
        $j['next_label'] = autoNextRunLabel($j, $now);
        $j['due']        = autoJobDue($j, $now);
        $j['log_count']  = count(autoLogRead($j['id']));
        $out[] = $j;
    }
    echo json_encode(['ok' => true, 'jobs' => $out, 'now' => $now,
        'max_per_tick' => AUTO_MAX_PER_TICK], JSON_UNESCAPED_UNICODE);
    exit;
}

/** افزودن یا ویرایشِ یک کار */
if (isset($_GET['auto_save'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $id     = trim((string)($_POST['id'] ?? ''));
    $title  = trim((string)($_POST['title'] ?? ''));
    $prompt = trim((string)($_POST['prompt'] ?? ''));
    $mode   = (string)($_POST['mode'] ?? 'dry');
    $every  = (int)($_POST['every'] ?? 1440);
    $model  = trim((string)($_POST['model'] ?? ''));
    $enabled= !empty($_POST['enabled']) && $_POST['enabled'] !== '0';

    if ($title === '')  { echo json_encode(['ok' => false, 'error' => 'عنوانِ کار خالی است'], JSON_UNESCAPED_UNICODE); exit; }
    if ($prompt === '') { echo json_encode(['ok' => false, 'error' => 'دستورِ کار خالی است'], JSON_UNESCAPED_UNICODE); exit; }
    if (!in_array($mode, ['sim', 'dry', 'live'], true)) $mode = 'dry';
    if ($every < 5) $every = 5;

    $jobs  = autoLoadJobs();
    $found = false;
    foreach ($jobs as $i => $j) {
        if ($j['id'] === $id && $id !== '') {
            $jobs[$i] = array_merge($j, ['title' => $title, 'prompt' => $prompt,
                'mode' => $mode, 'every' => $every, 'enabled' => $enabled, 'model' => $model]);
            $found = true;
            break;
        }
    }
    if (!$found) {
        if (count($jobs) >= 40) { echo json_encode(['ok' => false, 'error' => 'سقفِ ۴۰ کار پر شده است'], JSON_UNESCAPED_UNICODE); exit; }
        $id = autoNewId();
        $jobs[] = autoNormalizeJob(['id' => $id, 'title' => $title, 'prompt' => $prompt,
            'mode' => $mode, 'every' => $every, 'enabled' => $enabled, 'model' => $model,
            'created' => time()]);
    }
    $ok = autoSaveJobs($jobs);
    echo json_encode(['ok' => $ok, 'id' => $id, 'edited' => $found,
        'error' => $ok ? '' : 'نوشتن روی دیسک ناموفق بود'], JSON_UNESCAPED_UNICODE);
    exit;
}

/** حذفِ یک کار (لاگش هم پاک می‌شود) */
if (isset($_GET['auto_delete'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $id   = trim((string)($_POST['id'] ?? $_GET['auto_delete']));
    $jobs = autoLoadJobs();
    $out  = [];
    $hit  = false;
    foreach ($jobs as $j) {
        if ($j['id'] === $id) { $hit = true; continue; }
        $out[] = $j;
    }
    if (!$hit) { echo json_encode(['ok' => false, 'error' => 'کار پیدا نشد'], JSON_UNESCAPED_UNICODE); exit; }
    autoLogClear($id);
    echo json_encode(['ok' => autoSaveJobs($out)], JSON_UNESCAPED_UNICODE);
    exit;
}

/** روشن/خاموشِ سریعِ یک کار */
if (isset($_GET['auto_toggle'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $id   = trim((string)($_POST['id'] ?? $_GET['auto_toggle']));
    $jobs = autoLoadJobs();
    $now  = null;
    foreach ($jobs as $i => $j) {
        if ($j['id'] === $id) { $jobs[$i]['enabled'] = empty($j['enabled']); $now = $jobs[$i]['enabled']; break; }
    }
    if ($now === null) { echo json_encode(['ok' => false, 'error' => 'کار پیدا نشد'], JSON_UNESCAPED_UNICODE); exit; }
    echo json_encode(['ok' => autoSaveJobs($jobs), 'enabled' => $now], JSON_UNESCAPED_UNICODE);
    exit;
}

/** لاگِ اجراهای یک کار — برای مودالِ لاگ */
if (isset($_GET['auto_log'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $id  = trim((string)$_GET['auto_log']);
    $job = null;
    foreach (autoLoadJobs() as $j) if ($j['id'] === $id) { $job = $j; break; }
    if (!$job) { echo json_encode(['ok' => false, 'error' => 'کار پیدا نشد'], JSON_UNESCAPED_UNICODE); exit; }
    $rows = autoLogRead($id);
    $okN = 0; $chN = 0;
    foreach ($rows as $r) { if (!empty($r['ok'])) $okN++; $chN += (int)($r['changes'] ?? 0); }
    echo json_encode(['ok' => true, 'job' => $job, 'entries' => $rows,
        'stat' => ['total' => count($rows), 'ok' => $okN, 'fail' => count($rows) - $okN,
                   'changes' => $chN]], JSON_UNESCAPED_UNICODE);
    exit;
}

/** پاک‌کردنِ لاگِ یک کار */
if (isset($_GET['auto_log_clear'])) {
    header('Content-Type: application/json; charset=UTF-8');
    autoLogClear(trim((string)($_POST['id'] ?? $_GET['auto_log_clear'])));
    echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

/** اجرای فوریِ یک کار — «همین حالا اجرا کن» بدون منتظرِ کران ماندن.
 *
 *  عمداً همان الگوی agent_start را دنبال می‌کند (قفلِ flock + بستنِ زودهنگامِ
 *  اتصال) تا کاربر بتواند پیشرفتِ زنده را در همان پنلِ ایجنت ببیند و در
 *  صورت نیاز با همان دکمهٔ «توقف» متوقفش کند. */
if (isset($_GET['auto_run_now'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $id  = trim((string)($_POST['id'] ?? $_GET['auto_run_now']));
    $job = null;
    foreach (autoLoadJobs() as $j) if ($j['id'] === $id) { $job = $j; break; }
    if (!$job) { echo json_encode(['ok' => false, 'error' => 'کار پیدا نشد'], JSON_UNESCAPED_UNICODE); exit; }

    $lockFp = fopen(AGENT_LOCK_FILE, 'c');
    if (!$lockFp || !flock($lockFp, LOCK_EX | LOCK_NB)) {
        if ($lockFp) fclose($lockFp);
        echo json_encode(['ok' => false, 'running' => true,
            'error' => 'یک اجرای ایجنت همین حالا در جریان است'], JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);
    agentClearStop();
    $cn = loadConnections();

    localTaskDbForget(AGENT_PROGRESS_FILE); @unlink(AGENT_PROGRESS_FILE);
    @unlink(AGENT_RESULT_FILE);
    agentProgress(['running' => true, 'done' => false, 'mode' => $job['mode'],
        'task' => $job['prompt'], 'started_at' => time(), 'step' => 0, 'calls' => 0,
        'changes' => 0, 'phase' => 'start',
        'log_add' => ['🗓 اجرای دستیِ کارِ زمان‌بندی‌شده: ' . $job['title']
                      . ' — ' . agentModeLabel($job['mode'])]]);

    $early = json_encode(['ok' => true, 'started' => true, 'mode' => $job['mode'],
        'title' => $job['title']], JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();

    register_shutdown_function(function () use ($lockFp) {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
    });

    $now  = time();
    $jobs = autoLoadJobs();
    foreach ($jobs as $i => $j) if ($j['id'] === $id) $jobs[$i]['last_run'] = $now;
    autoSaveJobs($jobs);

    $e = autoRunJob($cn, $job);
    $e['manual'] = true;

    $jobs = autoLoadJobs();
    foreach ($jobs as $i => $j) {
        if ($j['id'] !== $id) continue;
        $jobs[$i]['last_run'] = $now;
        $jobs[$i]['last_ok']  = $e['ok'];
        $jobs[$i]['last_msg'] = $e['ok'] ? (string)$e['summary'] : (string)$e['error'];
        $jobs[$i]['runs']     = (int)$j['runs'] + 1;
        if (!$e['ok']) $jobs[$i]['fails'] = (int)$j['fails'] + 1;
        $jobs[$i]['changes']  = (int)$j['changes'] + (int)$e['changes'];
    }
    autoSaveJobs($jobs);

    agentClearStop();
    agentProgress(['running' => false, 'done' => true, 'result_ok' => $e['ok'],
        'error' => (string)$e['error'], 'calls' => (int)$e['calls'],
        'changes' => (int)$e['changes'],
        'log_add' => [$e['ok']
            ? ('🏁 پایانِ «' . $job['title'] . '» در ' . $e['took'] . ' ثانیه — '
               . aiFaNum((int)$e['changes']) . ' تغییر')
            : ('❌ ' . $e['error'])]]);
    exit;
}

/** تیکِ دستیِ زمان‌بند — برای آزمایش یا کرانِ اختصاصی */
if (isset($_GET['auto_tick'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $r = autoTick(loadConnections());
    echo json_encode(array_merge(['ok' => true], $r), JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['agent_tools'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $out = [];
    foreach (agentToolSpecs() as $t) {
        $f = $t['function'];
        $out[] = ['name' => $f['name'], 'desc' => $f['description'],
                  'params' => array_keys($f['parameters']['properties'] ?? [])];
    }
    $cfg = aiActiveConfig();
    echo json_encode(['ok' => true, 'tools' => $out,
        'model' => (string)($cfg['model'] ?? ''),
        'provider' => (string)($cfg['provider']['name'] ?? ''),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

/** v10.10 (۲۳): آیا مدلی که کاربر در پنلِ ایجنت انتخاب کرده، واقعاً به یکی از
 *  اتصال‌های ثبت‌شده می‌خورد؟ بدون این، انتخابِ مدل «بی‌صدا» نادیده گرفته
 *  می‌شد و کاربر خیال می‌کرد اجرا با مدلِ دلخواهش رفته است. */
if (isset($_GET['agent_model_check'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $mid = trim((string)($_GET['model'] ?? ($_POST['model'] ?? '')));
    $pin = $mid === '' ? [] : autoResolveModel($mid);
    echo json_encode(['ok' => true, 'model' => $mid, 'found' => !empty($pin),
        'via'      => (string)($pin['via'] ?? ''),
        'provider' => (string)($pin['provider']['name'] ?? ''),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['agent_start'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $mode = (string)($_GET['mode'] ?? 'dry');
    if (!in_array($mode, ['sim', 'dry', 'live'], true)) $mode = 'dry';
    $task = trim((string)($_POST['task'] ?? ($_GET['task'] ?? '')));
    /* v10.10 (۲۳): مدلِ انتخابیِ کاربر در پنلِ ایجنت. تا نسخهٔ ۱۰٫۰۹ فقط
       کارهای زمان‌بندی‌شده می‌توانستند مدل داشته باشند و اجرای دستی همیشه
       با مدلِ پیش‌فرضِ اتصالات می‌رفت؛ حالا همان مسیر برای هر دو یکی است. */
    $model = trim((string)($_POST['model'] ?? ($_GET['model'] ?? '')));
    if ($task === '') {
        echo json_encode(['ok' => false, 'error' => 'دستورِ کار خالی است'], JSON_UNESCAPED_UNICODE); exit;
    }
    $lockFp = fopen(AGENT_LOCK_FILE, 'c');
    if (!$lockFp || !flock($lockFp, LOCK_EX | LOCK_NB)) {
        if ($lockFp) fclose($lockFp);
        echo json_encode(['ok' => false, 'running' => true,
            'error' => 'یک اجرای ایجنت همین حالا در جریان است'], JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);
    agentClearStop();
    $cn = loadConnections();
    /* v10.129: ادامهٔ ایجنت فقط با همان دستور/حالت/مدل و تاریخچهٔ API قبلی
       پذیرفته می‌شود. تاریخچهٔ پیام‌ها و ابزارهای انجام‌شده در checkpoint
       است؛ بنابراین resume یک اجرای تازه و بی‌حافظه نیست. */
    $agentCp = null;
    if (!empty($_GET['resume']) && is_file(AGENT_PROGRESS_FILE)) {
        $oldAgent = json_decode((string)@file_get_contents(AGENT_PROGRESS_FILE), true);
        $oldTask = is_array($oldAgent) ? trim((string)($oldAgent['task'] ?? '')) : '';
        $oldMode = is_array($oldAgent) ? (string)($oldAgent['mode'] ?? '') : '';
        $oldModel = is_array($oldAgent) ? trim((string)($oldAgent['model'] ?? '')) : '';
        if (is_array($oldAgent) && $oldTask === $task && $oldMode === $mode && $oldModel === $model
            && is_array($oldAgent['checkpoint']['messages'] ?? null)
            && count($oldAgent['checkpoint']['messages']) >= 2) {
            $agentCp = $oldAgent['checkpoint'];
        }
    }
    if ($agentCp === null) {
        localTaskDbForget(AGENT_PROGRESS_FILE); @unlink(AGENT_PROGRESS_FILE);
        @unlink(AGENT_RESULT_FILE);
    }
    agentProgress(['running' => true, 'done' => false, 'mode' => $mode, 'task' => $task,
        'model' => $model, 'resume' => $agentCp !== null,
        'started_at' => (int)($agentCp['started_at'] ?? time()),
        'step' => (int)($agentCp['last_step'] ?? 0), 'calls' => (int)($agentCp['calls'] ?? 0),
        'changes' => count((array)($agentCp['changes'] ?? [])),
        'phase' => $agentCp !== null ? 'resume' : 'start',
        'checkpoint' => $agentCp,
        'log_add' => [$agentCp !== null
            ? '↻ ادامهٔ ایجنت از checkpoint — تاریخچهٔ گفتگو و ابزارها حفظ شد'
            : ('🚀 شروعِ ایجنت — ' . agentModeLabel($mode)
               . ($model !== '' ? ' — مدلِ انتخابی: ' . $model : ' — مدلِ پیش‌فرضِ اتصالات'))]]);

    $early = json_encode(['ok' => true, 'started' => true, 'mode' => $mode], JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();

    register_shutdown_function(function () use ($lockFp) {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
    });

    try {
        $rep = agentRun($cn, $task, $mode, $model, $agentCp);
    } catch (Throwable $e) {
        $agentErrState = is_file(AGENT_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(AGENT_PROGRESS_FILE), true) : [];
        agentProgress(['running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(),
            'checkpoint' => is_array($agentErrState['checkpoint'] ?? null) ? $agentErrState['checkpoint'] : null,
            'log_add' => ['❌ خطا: ' . $e->getMessage() . ' — checkpoint حفظ شد']]);
        agentClearStop();
        exit;
    }
    @file_put_contents(AGENT_RESULT_FILE, json_encode($rep, JSON_UNESCAPED_UNICODE), LOCK_EX);
    $stopped = agentStopRequested();
    $agentLastState = is_file(AGENT_PROGRESS_FILE)
        ? json_decode((string)@file_get_contents(AGENT_PROGRESS_FILE), true) : [];
    $agentKeepCp = $stopped || !empty($rep['stopped_by']) || empty($rep['ok']);
    agentClearStop();
    agentProgress(['running' => false, 'done' => true, 'stopped' => $stopped,
        'stale' => $agentKeepCp, 'result_ok' => !empty($rep['ok']), 'error' => $rep['error'] ?? '',
        'checkpoint' => $agentKeepCp && is_array($agentLastState['checkpoint'] ?? null)
            ? $agentLastState['checkpoint'] : null,
        'calls' => $rep['calls'] ?? 0, 'changes' => count($rep['changes'] ?? []),
        'log_add' => [empty($rep['ok'])
            ? ('❌ ' . ($rep['error'] ?? 'ناموفق'))
            : ('🏁 پایان در ' . $rep['took'] . ' ثانیه — '
               . aiFaNum((int)$rep['calls']) . ' فراخوانیِ ابزار، '
               . aiFaNum(count($rep['changes'])) . ' تغییر ('
               . aiFaNum((int)$rep['applied']) . ' واقعی)')]]);
    exit;
}

if (isset($_GET['agent_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $p = [];
    if (is_file(AGENT_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(AGENT_PROGRESS_FILE), true);
        if (is_array($d)) $p = $d;
    }
    $since = max(0, (int)($_GET['since'] ?? 0));
    $log = is_array($p['log'] ?? null) ? $p['log'] : [];
    $p['log'] = array_slice($log, $since);
    $p['log_total'] = count($log);
    /* v10.26 (۳۹ب): جریانِ گفتگو هم مثل لاگ افزایشی فرستاده می‌شود تا
       نظرسنجیِ هر ۱٫۲ ثانیه کلِ تاریخچه را دوباره روی سیم نبرد. */
    $cs = max(0, (int)($_GET['csince'] ?? 0));
    $convo = is_array($p['convo'] ?? null) ? $p['convo'] : [];
    $p['convo'] = array_slice($convo, $cs);
    $p['convo_total'] = count($convo);
    $p['ok'] = true;
    echo json_encode($p, JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['agent_result'])) {
    header('Content-Type: application/json; charset=UTF-8');
    if (!is_file(AGENT_RESULT_FILE)) {
        echo json_encode(['ok' => false, 'error' => 'هنوز گزارشی وجود ندارد'], JSON_UNESCAPED_UNICODE); exit;
    }
    echo (string)@file_get_contents(AGENT_RESULT_FILE);
    exit;
}

if (isset($_GET['agent_stop'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @file_put_contents(AGENT_STOP_FILE, json_encode(['at' => time()]));
    agentProgress(['log_add' => ['⏹ درخواستِ توقف ثبت شد — پس از گامِ جاری متوقف می‌شود']]);
    echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.25 (۳۸ج): اندپوینت‌های ایجنتِ کشفِ سلکتور
 *    ?selagent_start=1&kind=list|detail&url=…[&model=…]  → شروع در پس‌زمینه
 *    ?selagent_status=1[&since=n]                        → وضعیتِ زنده
 *    ?selagent_result=1                                  → نتیجهٔ کامل
 *    ?selagent_stop=1                                    → درخواستِ توقف
 *
 *  عمداً همان الگوی agent_start: قفلِ flock ⇒ بستنِ زودهنگامِ پاسخ ⇒ ادامهٔ
 *  کار در پس‌زمینه. اگر این کار را نکنیم مرورگر تا پایانِ کلِ گفت‌وگو با
 *  مدل (گاهی یک دقیقه) منتظر می‌ماند و اکثرِ هاست‌ها وسطش قطع می‌کنند.
 * ================================================================== */
if (isset($_GET['selagent_start'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $saUrl  = trim((string)($_POST['url'] ?? ($_GET['url'] ?? '')));
    $saKind = ((string)($_POST['kind'] ?? ($_GET['kind'] ?? 'list')) === 'detail') ? 'detail' : 'list';
    $saModel = trim((string)($_POST['model'] ?? ($_GET['model'] ?? '')));
    /* v10.27 (۴۰): pk = کلیدِ پروفایل تا تنظیمِ «اتصالِ غیرمستقیمِ همین پروفایل»
       دقیقاً مثل iframeِ ?visual_proxy اعمال شود؛ list_url = آدرسِ صفحهٔ فهرست
       تا ایجنتِ جزئیات وقتی هیچ محصولی نیست بتواند خودش زنجیره را کامل کند. */
    $saPk   = trim((string)($_POST['pk'] ?? ($_GET['pk'] ?? '')));
    $saList = trim((string)($_POST['list_url'] ?? ($_GET['list_url'] ?? '')));
    if ($saUrl === '' && $saKind === 'detail' && filter_var($saList, FILTER_VALIDATE_URL)) {
        $saUrl = '';   // عمداً خالی: selagentRun خودش صفحهٔ نمونه را می‌سازد
    } elseif (!filter_var($saUrl, FILTER_VALIDATE_URL)) {
        echo json_encode(['ok' => false, 'error' => 'آدرسِ صفحه معتبر نیست'], JSON_UNESCAPED_UNICODE); exit;
    }
    if ($saPk === '') $saPk = profileKey($saUrl !== '' ? $saUrl : $saList);
    $saLock = fopen(SELAGENT_LOCK_FILE, 'c');
    if (!$saLock || !flock($saLock, LOCK_EX | LOCK_NB)) {
        if ($saLock) fclose($saLock);
        echo json_encode(['ok' => false, 'running' => true,
            'error' => 'یک کشفِ سلکتور همین حالا در جریان است'], JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);
    selagentClearStop();
    /* v10.129: تاریخچهٔ مدل، سلکتورهای تأییدشده و شمارنده‌های کاوش در
       checkpoint می‌مانند. برای صفحهٔ جزئیات که URL نمونه‌اش را خودِ ایجنت
       می‌سازد، pk/list_url شناسهٔ اجرای قبلی را تثبیت می‌کنند. */
    $selAgentCp = null;
    if (!empty($_GET['resume']) && is_file(SELAGENT_PROGRESS_FILE)) {
        $oldSel = json_decode((string)@file_get_contents(SELAGENT_PROGRESS_FILE), true);
        $sameUrl = $saUrl === '' || (string)($oldSel['url'] ?? '') === $saUrl
            || (string)($oldSel['checkpoint']['effective_url'] ?? '') === $saUrl;
        if (is_array($oldSel) && $sameUrl && (string)($oldSel['kind'] ?? '') === $saKind
            && (string)($oldSel['pk'] ?? '') === $saPk
            && (string)($oldSel['list_url'] ?? '') === $saList
            && trim((string)($oldSel['model'] ?? '')) === $saModel
            && is_array($oldSel['checkpoint']['messages'] ?? null)
            && count($oldSel['checkpoint']['messages']) >= 2) {
            $selAgentCp = $oldSel['checkpoint'];
        }
    }
    if ($selAgentCp === null) {
        localTaskDbForget(SELAGENT_PROGRESS_FILE); @unlink(SELAGENT_PROGRESS_FILE);
        @unlink(SELAGENT_RESULT_FILE);
    }
    selagentProgress(['running' => true, 'done' => false, 'kind' => $saKind, 'url' => $saUrl,
        'pk' => $saPk, 'list_url' => $saList, 'model' => $saModel, 'resume' => $selAgentCp !== null,
        'started_at' => (int)($selAgentCp['started_at'] ?? time()),
        'step' => (int)($selAgentCp['last_step'] ?? 0), 'calls' => (int)($selAgentCp['calls'] ?? 0),
        'probes' => (int)($selAgentCp['probes'] ?? 0), 'confirmed' => count((array)($selAgentCp['confirmed'] ?? [])),
        'phase' => $selAgentCp !== null ? 'resume' : 'start', 'checkpoint' => $selAgentCp,
        'log_add' => [$selAgentCp !== null
            ? '↻ ادامهٔ کشف سلکتور از checkpoint — گفتگو و حدس‌های تأییدشده حفظ شد'
            : ('🚀 کشفِ سلکتورهای ' . ($saKind === 'detail' ? 'صفحهٔ جزئیات' : 'صفحهٔ فهرست')
               . ' — ' . ($saUrl !== '' ? $saUrl : ('صفحهٔ نمونه از ' . $saList))
               . ($saModel !== '' ? (' — مدل: ' . $saModel) : ' — مدلِ پیش‌فرضِ اتصالات'))]]);

    $saEarly = json_encode(['ok' => true, 'started' => true, 'kind' => $saKind], JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($saEarly));
    echo $saEarly;
    @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();

    register_shutdown_function(function () use ($saLock) {
        @flock($saLock, LOCK_UN); @fclose($saLock);
    });

    try {
        $saRep = selagentRun($saUrl, $saKind, $saModel, $saPk, $saList, $selAgentCp);
    } catch (Throwable $e) {
        $selErrState = is_file(SELAGENT_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(SELAGENT_PROGRESS_FILE), true) : [];
        selagentProgress(['running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(),
            'checkpoint' => is_array($selErrState['checkpoint'] ?? null) ? $selErrState['checkpoint'] : null,
            'log_add' => ['❌ خطا: ' . $e->getMessage() . ' — checkpoint حفظ شد']]);
        selagentClearStop();
        exit;
    }
    @file_put_contents(SELAGENT_RESULT_FILE, json_encode($saRep, JSON_UNESCAPED_UNICODE), LOCK_EX);
    $saStopped = selagentStopRequested();
    $selLastState = is_file(SELAGENT_PROGRESS_FILE)
        ? json_decode((string)@file_get_contents(SELAGENT_PROGRESS_FILE), true) : [];
    $selKeepCp = $saStopped || !empty($saRep['stopped_by']) || empty($saRep['ok']);
    selagentClearStop();
    $saN = count((array)($saRep['selectors'] ?? []));
    selagentProgress(['running' => false, 'done' => true, 'stopped' => $saStopped,
        'stale' => $selKeepCp, 'result_ok' => !empty($saRep['ok']), 'error' => $saRep['error'] ?? '',
        'checkpoint' => $selKeepCp && is_array($selLastState['checkpoint'] ?? null)
            ? $selLastState['checkpoint'] : null,
        'found' => $saN,
        'log_add' => [empty($saRep['ok'])
            ? ('❌ ' . ($saRep['error'] ?? 'ناموفق'))
            : ('🏁 پایان در ' . $saRep['took'] . ' ثانیه — ' . aiFaNum($saN)
               . ' سلکتورِ تأییدشده از ' . aiFaNum((int)($saRep['probes'] ?? 0)) . ' آزمایش')]]);
    exit;
}

if (isset($_GET['selagent_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $sp = [];
    if (is_file(SELAGENT_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(SELAGENT_PROGRESS_FILE), true);
        if (is_array($d)) $sp = $d;
    }
    $sSince = max(0, (int)($_GET['since'] ?? 0));
    $sLog = is_array($sp['log'] ?? null) ? $sp['log'] : [];
    $sp['log'] = array_slice($sLog, $sSince);
    $sp['log_total'] = count($sLog);
    /* v10.26 (۳۹ب): گفتگوی زندهٔ همین ایجنت، افزایشی. */
    $sCs = max(0, (int)($_GET['csince'] ?? 0));
    $sConvo = is_array($sp['convo'] ?? null) ? $sp['convo'] : [];
    $sp['convo'] = array_slice($sConvo, $sCs);
    $sp['convo_total'] = count($sConvo);
    $sp['ok'] = true;
    echo json_encode($sp, JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['selagent_result'])) {
    header('Content-Type: application/json; charset=UTF-8');
    if (!is_file(SELAGENT_RESULT_FILE)) {
        echo json_encode(['ok' => false, 'error' => 'هنوز نتیجه‌ای وجود ندارد'], JSON_UNESCAPED_UNICODE); exit;
    }
    echo (string)@file_get_contents(SELAGENT_RESULT_FILE);
    exit;
}

/* =====================================================================
 *  v10.30 (۴۳ب): اندپوینت‌های پرامپتِ سفارشیِ ایجنتِ کشفِ سلکتور.
 *    ?selagent_prompt=1                 → خواندنِ تنظیمِ فعلی + متنِ پیش‌فرض
 *    ?selagent_prompt_save=1 (POST)     → ذخیره
 *    ?selagent_prompt_preview=1 (POST)  → پیش‌نمایشِ متنِ نهایی بدونِ ذخیره
 * ===================================================================== */
if (isset($_GET['selagent_prompt'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $spKind = ((string)($_GET['kind'] ?? 'list') === 'detail') ? 'detail' : 'list';
    $spCfg  = selagentLoadPrompts();
    $spUrl  = trim((string)($_GET['url'] ?? 'https://example.com/page'));
    echo json_encode(['ok' => true, 'kind' => $spKind,
        'prompts' => ['list' => $spCfg['list'], 'detail' => $spCfg['detail']],
        'updated' => (int)$spCfg['updated'],
        'default' => selagentDefaultPrompt($spKind, $spUrl),
        'floor'   => selagentPromptFloor($spKind),
        'fields'  => array_keys(selagentFields($spKind)),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['selagent_prompt_save'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $spCur = selagentLoadPrompts();
    $spKind = ((string)($_POST['kind'] ?? ($_GET['kind'] ?? 'list')) === 'detail') ? 'detail' : 'list';
    $spNew = ['list' => $spCur['list'], 'detail' => $spCur['detail']];
    $spNew[$spKind] = ['mode' => (string)($_POST['mode'] ?? 'append'),
                       'text' => (string)($_POST['text'] ?? '')];
    $spOk = selagentSavePrompts($spNew);
    $spAfter = selagentLoadPrompts();
    echo json_encode(['ok' => $spOk, 'kind' => $spKind,
        'saved' => $spAfter[$spKind],
        'error' => $spOk ? '' : 'نوشتنِ فایلِ پرامپت ناموفق بود (دسترسیِ نوشتن را بررسی کنید)',
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['selagent_prompt_preview'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $spKind = ((string)($_POST['kind'] ?? ($_GET['kind'] ?? 'list')) === 'detail') ? 'detail' : 'list';
    $spUrl  = trim((string)($_POST['url'] ?? ($_GET['url'] ?? '')));
    if ($spUrl === '') $spUrl = 'https://example.com/page';
    $spFinal = selagentSystemPrompt($spKind, $spUrl,
        ['mode' => (string)($_POST['mode'] ?? 'append'), 'text' => (string)($_POST['text'] ?? '')]);
    echo json_encode(['ok' => true, 'kind' => $spKind, 'prompt' => $spFinal,
        'chars' => mb_strlen($spFinal)], JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.40 (۵۴ب): اندپوینت‌های پرامپتِ سفارشیِ «اصلاحِ دسته‌بندی با AI».
 *    ?catprompt=1                → تنظیمِ فعلی + پرامپتِ پیش‌فرض
 *    ?catprompt_save=1   (POST)  → ذخیره (mode/text)
 *    ?catprompt_preview=1 (POST) → پیش‌نمایشِ پرامپتِ نهایی بدونِ ذخیره
 *  عمداً هم‌شکلِ selagent_prompt* است.
 * ===================================================================== */
if (isset($_GET['catprompt'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cpCur   = catPromptLoad();
    $cpTitle = trim((string)($_GET['title'] ?? '')) ?: 'کیف چرم زنانه دست دوز';
    /* پیش‌فرض = همان پرامپتی که بدونِ متنِ سفارشی ساخته می‌شود */
    $cpDefP  = aiCatPayload($cpTitle, "11: کیف و کوله\n22: چرم و مصنوعات چرمی\n33: پوشاک زنانه", [], '',
        ['mode' => 'off', 'text' => '']);
    echo json_encode(['ok' => true,
        'mode'    => $cpCur['mode'],
        'text'    => $cpCur['text'],
        'updated' => (int)$cpCur['updated'],
        'default' => (string)($cpDefP['messages'][1]['content'] ?? ''),
        'floor'   => catPromptFloor(),
        'vars'    => ['{{title}}', '{{cats}}', '{{profile}}'],
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['catprompt_save'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cpOk = catPromptSave(['mode' => (string)($_POST['mode'] ?? 'append'),
                           'text' => (string)($_POST['text'] ?? '')]);
    $cpAf = catPromptLoad();
    echo json_encode(['ok' => $cpOk, 'saved' => ['mode' => $cpAf['mode'], 'text' => $cpAf['text']],
        'error' => $cpOk ? '' : 'نوشتنِ فایلِ پرامپت ناموفق بود (دسترسیِ نوشتن را بررسی کنید)',
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['catprompt_preview'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cpTitle = trim((string)($_POST['title'] ?? ($_GET['title'] ?? ''))) ?: 'کیف چرم زنانه دست دوز';
    /* پیش‌نمایش نباید فایل را بخواند — متنِ در حالِ ویرایش را موقتاً می‌نشانیم */
    $cpP = aiCatPayload($cpTitle, "11: کیف و کوله\n22: چرم و مصنوعات چرمی\n33: پوشاک زنانه", [], '',
        ['mode' => (string)($_POST['mode'] ?? 'append'), 'text' => (string)($_POST['text'] ?? '')]);
    $cpTxt = (string)($cpP['messages'][1]['content'] ?? '');
    echo json_encode(['ok' => true, 'prompt' => $cpTxt, 'chars' => mb_strlen($cpTxt)],
        JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['selagent_stop'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @file_put_contents(SELAGENT_STOP_FILE, json_encode(['at' => time()]));
    selagentProgress(['log_add' => ['⏹ درخواستِ توقف ثبت شد — پس از گامِ جاری متوقف می‌شود']]);
    echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * v8.53: گزارش محصولات بر اساس پسوند پروفایل.
 * ?suffix_report=1&target=woo|bsl[&notify=1]  → شروع در پس‌زمینه
 * ?suffix_status=1                             → وضعیت زنده
 * ?suffix_result=1                             → نتیجهٔ کامل
 */
if (isset($_GET['suffix_report'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $target = (string)($_GET['target'] ?? '');
    /* v10.114: summary|all = جدول خلاصهٔ پروفایل×محلی×WC×غرفه‌ها */
    if (!in_array($target, ['woo', 'bsl', 'summary', 'all'], true)) {
        echo json_encode(['ok' => false, 'error' => 'مقصد نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $lockFile = __DIR__ . '/suffix.lock';
    $lockFp = fopen($lockFile, 'c');
    if (!$lockFp || !flock($lockFp, LOCK_EX | LOCK_NB)) {
        if ($lockFp) fclose($lockFp);
        echo json_encode(['ok' => false, 'error' => 'یک گزارش در حال اجراست', 'running' => true],
            JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);
    suffixStopClear();
    $notify = !empty($_GET['notify']);
    $cn = loadConnections();
    /* v10.129: صفحاتِ خوانده‌شدهٔ گزارش هم checkpoint دارند؛ در resume
       همان صفحات دوباره از مقصد خوانده نمی‌شوند. */
    $suffixCp = null;
    if (!empty($_GET['resume']) && is_file(SUFFIX_PROGRESS_FILE)) {
        $oldSuffix = json_decode((string)@file_get_contents(SUFFIX_PROGRESS_FILE), true);
        $oldCp = is_array($oldSuffix['checkpoint'] ?? null) ? $oldSuffix['checkpoint'] : null;
        if (is_array($oldCp) && (string)($oldCp['target'] ?? '') === $target
            && (is_array($oldCp['rows'] ?? null)
                || (($target === 'summary' || $target === 'all')
                    && (is_array($oldCp['woo_rows'] ?? null) || is_array($oldCp['shops'] ?? null))))) {
            $suffixCp = $oldCp;
            $notify = !empty($oldCp['notify']) || $notify;
        }
    }
    if ($suffixCp === null && ($target === 'summary' || $target === 'all')) {
        $suffixCp = ['target' => $target, 'phase' => 'start', 'woo_rows' => [], 'shops' => [],
            'started_at' => time(), 'notify' => $notify];
    }
    localTaskDbForget(SUFFIX_PROGRESS_FILE); @unlink(SUFFIX_PROGRESS_FILE);
    suffixProgress(['running' => true, 'done' => false, 'target' => $target,
        'notify' => $notify, 'started_at' => ($suffixCp['started_at'] ?? time()),
        'phase' => ($suffixCp !== null ? 'resume' : 'start'),
        'checkpoint' => $suffixCp !== null ? $suffixCp : ['target' => $target, 'phase' => 'start', 'page' => 0, 'rows' => [], 'notify' => $notify, 'started_at' => time()],
        'log_add' => ['🔍 ' . ($suffixCp !== null ? 'ادامه گزارش — ' : 'شروع گزارش — ')
        . ($target === 'woo' ? 'ووکامرس' : ($target === 'bsl' ? 'باسلام' : 'خلاصهٔ پروفایل‌ها'))]]);

    $early = json_encode(['ok' => true, 'started' => true, 'target' => $target], JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();

    register_shutdown_function(function () use ($lockFp, $lockFile) {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
    });

    try {
        if ($target === 'summary' || $target === 'all') {
            $rep = profileStatsSummary($cn, $suffixCp);
        } else {
            $rep = suffixReport($cn, $target, $suffixCp);
        }
    } catch (Throwable $e) {
        $suffixErrState = is_file(SUFFIX_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(SUFFIX_PROGRESS_FILE), true) : [];
        suffixProgress(['running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(),
            'checkpoint' => is_array($suffixErrState['checkpoint'] ?? null) ? $suffixErrState['checkpoint'] : null,
            'log_add' => ['❌ خطا: ' . $e->getMessage() . ' — checkpoint حفظ شد']]);
        exit;
    }
    if ($notify && !empty($rep['ok'])) {
        $why = notifPrereq($cn);
        if ($why === null) {
            $msg = (!empty($rep['kind']) && $rep['kind'] === 'summary')
                ? profileStatsSummaryMsg($rep) : suffixReportMsg($rep);
            $rep['delivery'] = notifSend($cn, $msg, 'report');
            suffixProgress(['log_add' => ['📤 گزارش به پیام‌رسان‌ها فرستاده شد']]);
        } else {
            $rep['notify_error'] = $why;
            suffixProgress(['log_add' => ['⚠️ ارسال نشد: ' . $why]]);
        }
    }
    @file_put_contents(__DIR__ . '/suffix_result.json',
        json_encode($rep, JSON_UNESCAPED_UNICODE), LOCK_EX);
    $suffixLastState = is_file(SUFFIX_PROGRESS_FILE)
        ? json_decode((string)@file_get_contents(SUFFIX_PROGRESS_FILE), true) : [];
    $suffixKeepCp = !empty($rep['stopped']) || !empty($rep['partial']) || empty($rep['ok']);
    suffixStopClear();
    suffixProgress(['running' => false, 'done' => true, 'stopped' => !empty($rep['stopped']), 'partial' => !empty($rep['partial']), 'stale' => $suffixKeepCp,
        'result_ok' => !empty($rep['ok']), 'error' => $rep['error'] ?? '',
        'checkpoint' => $suffixKeepCp && is_array($suffixLastState['checkpoint'] ?? null)
            ? $suffixLastState['checkpoint'] : null,
        'log_add' => [empty($rep['ok']) ? ('❌ ' . ($rep['error'] ?? 'ناموفق')) : '✅ پایان']]);
    exit;
}

/* =====================================================================
 *  v10.02 (۱۶): اندپوینت‌های حذفِ تکراری — همه سمتِ سرور و بلندمدت
 *
 *  ?dedup_start=1&target=woo|bsl&mode=scan|delete  → شروع در پس‌زمینه
 *  ?dedup_status=1[&since=N]                        → وضعیت و لاگِ زنده
 *  ?dedup_result=1                                  → نتیجهٔ کامل
 *  ?dedup_stop=1                                    → درخواستِ توقف
 *  POST action=dedup_save_cfg                       → ذخیرهٔ تنظیمات
 *  POST action=dedup_preview                        → پیش‌نمایشِ الگوها
 *  POST action=dedup_delete_ids                     → حذفِ دستیِ چند شناسه
 *
 *  چرا «شروع + نظرسنجی» و نه یک درخواستِ طولانی؟ چون روی غرفه‌ای با چند
 *  هزار محصول، فقط مرحلهٔ دریافت ده‌ها درخواست HTTP است و بعد صدها حذف.
 *  هیچ مرورگر/پروکسی/هاستی این‌قدر صبر نمی‌کند و کاربر «خطای شبکه» می‌دید.
 * ===================================================================== */
if (isset($_GET['dedup_start'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $target = (string)($_GET['target'] ?? '');
    $mode   = ((string)($_GET['mode'] ?? 'scan')) === 'delete' ? 'delete' : 'scan';
    if ($target !== 'woo' && $target !== 'bsl') {
        echo json_encode(['ok' => false, 'error' => 'مقصد نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $lockFp = fopen(DEDUP_LOCK_FILE, 'c');
    if (!$lockFp || !flock($lockFp, LOCK_EX | LOCK_NB)) {
        if ($lockFp) fclose($lockFp);
        echo json_encode(['ok' => false, 'running' => true,
            'error' => 'یک عملیاتِ حذفِ تکراری همین حالا در حال اجراست'], JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);
    dedupClearStop();
    /* v10.42 (۵۶): سیگنالِ توقفِ *ارسالِ باسلام* هم پاک می‌شود.
       BSL_STOP_FILE مشترک است و bslReq پیش از هر تماس آن را می‌بیند و
       بدونِ رفتن به شبکه code=0/error='stopped' برمی‌گرداند. اگر کاربر
       قبلاً یک ارسال را متوقف کرده بود و فایل جا مانده بود، کلِ اسکن و
       بایگانیِ تکراری‌ها بی‌صدا شکست می‌خورد — بدونِ هیچ خطای قابلِ
       دیدن. (همین الگو در توقفِ ارسال @۲۸۴۹۵ هم هست.) */
    if (defined('BSL_STOP_FILE') && is_file(BSL_STOP_FILE)) { @unlink(BSL_STOP_FILE); }
    clearstatcache(true,BSL_STOP_FILE);
    $cn  = loadConnections();
    $cfg = dedupCfg($cn);

    /* v10.126: ادامهٔ واقعی از چک‌پوینت — اگر resume=1 و فایلِ پیشرفت برای
       همین مقصد چک‌پوینت دارد، آن را نگه می‌داریم و فقط پرچمِ اجرا را تازه
       می‌کنیم؛ در غیر این صورت مثل قبل از نو شروع می‌شود. */
    $cp = null;
    if (!empty($_GET['resume']) && is_file(DEDUP_PROGRESS_FILE)) {
        $old = json_decode((string)@file_get_contents(DEDUP_PROGRESS_FILE), true);
        if (is_array($old) && (string)($old['target'] ?? '') === $target
            && is_array($old['checkpoint'] ?? null)) {
            $cp = $old['checkpoint'];
        }
    }
    if ($cp === null) {
        localTaskDbForget(DEDUP_PROGRESS_FILE); @unlink(DEDUP_PROGRESS_FILE);
        @unlink(DEDUP_FETCH_CURSOR_FILE);
    }
    $cpStartedAt = ($cp !== null ? (int)($cp['started_at'] ?? 0) : 0);
    dedupProgress(['running' => true, 'done' => false, 'target' => $target, 'mode' => $mode,
        'started_at' => ($cpStartedAt > 0 ? $cpStartedAt : time()), 'total' => 0,
        'groups' => 0, 'dups' => 0,
        'deleted' => (int)($cp['deleted'] ?? 0), 'failed' => (int)($cp['failed'] ?? 0),
        'processed' => (int)($cp['done'] ?? 0),
        'phase' => ($cp !== null ? 'resume' : 'start'),
        'keep' => $cfg['keep'],
        'log_add' => [($cp !== null ? '↻ ادامه از چک‌پوینت — ' : '🚀 شروع — ')
            . ($target === 'woo' ? 'ووکامرس' : 'باسلام')
            . ' · ' . ($mode === 'delete' ? 'حذفِ واقعی' : 'فقط گزارش')
            . ' · نگه‌داری: ' . dedupKeepLabel($cfg['keep'])]]);

    // پاسخِ فوری، سپس ادامهٔ کار در پس‌زمینه
    $early = json_encode(['ok' => true, 'started' => true, 'target' => $target, 'mode' => $mode],
        JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();

    register_shutdown_function(function () use ($lockFp) {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
    });

    try {
        $rep = dedupRun($cn, $target, $cfg, $mode, $cp);
    } catch (Throwable $e) {
        $dedupErrState = is_file(DEDUP_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(DEDUP_PROGRESS_FILE), true) : [];
        dedupProgress(['running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(),
            'checkpoint' => is_array($dedupErrState['checkpoint'] ?? null) ? $dedupErrState['checkpoint'] : null,
            'log_add' => ['❌ خطا: ' . $e->getMessage() . ' — checkpoint حفظ شد']]);
        dedupClearStop();
        exit;
    }
    @file_put_contents(DEDUP_RESULT_FILE, json_encode($rep, JSON_UNESCAPED_UNICODE), LOCK_EX);
    $stopped = dedupStopRequested();
    $dedupLastState = is_file(DEDUP_PROGRESS_FILE)
        ? json_decode((string)@file_get_contents(DEDUP_PROGRESS_FILE), true) : [];
    $dedupKeepCp = $stopped || !empty($rep['partial']) || empty($rep['ok']);
    dedupClearStop();
    if (!$dedupKeepCp) @unlink(DEDUP_FETCH_CURSOR_FILE);
    if (empty($rep['ok'])) {
        $dedupLog = '❌ ' . ($rep['error'] ?? 'ناموفق');
    } elseif ($dedupKeepCp) {
        $dedupLog = '⏸ توقف/برداشت ناقص؛ checkpoint حفظ شد';
    } elseif ($mode === 'delete') {
        $dedupLog = ($target === 'bsl' ? 'بایگانی‌شده: ' : 'حذف‌شده: ') . $rep['deleted']
            . ($rep['failed'] ? ('، ناموفق: ' . $rep['failed']) : '');
    } else {
        $dedupLog = '🏁 پایان در ' . $rep['took'] . ' ثانیه — گزارش آماده است: '
            . $rep['duplicates'] . ' نسخهٔ اضافی';
    }
    dedupProgress(['running' => false, 'done' => true, 'stopped' => $stopped,
        'stale' => $dedupKeepCp, 'result_ok' => !empty($rep['ok']), 'error' => $rep['error'] ?? '',
        'groups' => $rep['groups'] ?? 0, 'dups' => $rep['duplicates'] ?? 0,
        'deleted' => $rep['deleted'] ?? 0, 'failed' => $rep['failed'] ?? 0,
        'partial' => !empty($rep['partial']),
        'partial_msg' => (string)($rep['partial_msg'] ?? ''),
        'checkpoint' => $dedupKeepCp && is_array($dedupLastState['checkpoint'] ?? null)
            ? $dedupLastState['checkpoint'] : null,
        'log_add' => [$dedupLog]]);
    exit;
}

if (isset($_GET['dedup_cfg'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    echo json_encode(['ok' => true, 'cfg' => dedupCfg($cn),
        'defaults' => dedupDefaultCfg(),
        'has_woo' => !empty($cn['woocommerce']['store_url']),
        'has_bsl' => !empty($cn['basalam']['token']) && !empty($cn['basalam']['vendor_id']),
        'has_result' => is_file(DEDUP_RESULT_FILE),
        'running' => is_file(DEDUP_LOCK_FILE)], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['dedup_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $st = [];
    if (is_file(DEDUP_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(DEDUP_PROGRESS_FILE), true);
        if (is_array($d)) $st = $d;
    }
    $log = is_array($st['log'] ?? null) ? $st['log'] : [];
    $since = max(0, (int)($_GET['since'] ?? 0));
    $st['log_total'] = count($log);
    $st['log'] = $since > 0 ? array_slice($log, $since) : array_slice($log, -60);
    /* اگر پردازه مرده باشد ولی فایل هنوز running بگوید، قفل را ملاک بگیر.
       v10.23 (۳۶ب): آستانه از ۹۰ ثانیه به DEDUP_STALE_SEC رسید — با سه‌بار
       تلاشِ یک صفحه (۲+۴ ثانیه مکث + تایم‌اوتِ خودِ درخواست‌ها) کارِ کاملاً
       سالم هم می‌توانست بیش از ۹۰ ثانیه بی‌صدا بماند و «مرده» اعلام شود؛
       آن‌وقت رابط دست از پایش برمی‌داشت در حالی که سرور هنوز کار می‌کرد. */
    if (!empty($st['running']) && !is_file(DEDUP_LOCK_FILE)
        && (time() - (int)($st['ts'] ?? 0)) > DEDUP_STALE_SEC) {
        $st['running'] = false; $st['done'] = true; $st['stale'] = true;
    }
    $st['ok'] = true;
    echo json_encode($st, JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['dedup_result'])) {
    header('Content-Type: application/json; charset=UTF-8');
    if (!is_file(DEDUP_RESULT_FILE)) {
        echo json_encode(['ok' => false, 'error' => 'هنوز گزارشی گرفته نشده'], JSON_UNESCAPED_UNICODE); exit;
    }
    echo (string)@file_get_contents(DEDUP_RESULT_FILE);
    exit;
}

if (isset($_GET['dedup_stop'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @file_put_contents(DEDUP_STOP_FILE, json_encode(['at' => time()]));
    dedupProgress(['log_add' => ['⏹ درخواستِ توقف ثبت شد — پس از موردِ جاری متوقف می‌شود']]);
    echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.23 (۳۶د): اندپوینت‌های «اصلاح دستهٔ باسلام» به‌عنوان کارِ پس‌زمینه
 *
 *  چهار اندپوینت، دقیقاً هم‌شکلِ خانوادهٔ dedup_* و agent_*:
 *    ?catfix_start  · شروع (قفل + پاسخِ زودهنگام + ادامه در پس‌زمینه)
 *    ?catfix_status · پیشرفت و لاگِ افزایشی
 *    ?catfix_result · گزارشِ نهایی
 *    ?catfix_stop   · درخواستِ توقفِ نرم
 * ===================================================================== */
if (isset($_GET['catfix_start'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $mode = (string)($_GET['mode'] ?? 'ai_text');
    if (!in_array($mode, ['ai_text', 'master', 'quorum', 'fallback', 'learned'], true)) $mode = 'ai_text';   /* v10.107: learned */
    $opts = ['quorum' => (int)($_GET['quorum'] ?? 2),
             'product_id' => (int)($_GET['product_id'] ?? 0),
             'all_vendors' => !empty($_GET['all_vendors']),
             'use_learn' => !isset($_GET['use_learn']) || $_GET['use_learn'] !== '0',
             'vendor_id' => (int)($_GET['vendor_id'] ?? 0)];
    if ($mode === 'learned') {
        $mode = 'master';
        $opts['use_learn'] = true;
        $opts['learn_first'] = true;
    }

    $lockFp = fopen(CATFIX_LOCK_FILE, 'c');
    if (!$lockFp || !flock($lockFp, LOCK_EX | LOCK_NB)) {
        if ($lockFp) fclose($lockFp);
        echo json_encode(['ok' => false, 'running' => true,
            'error' => 'یک اصلاحِ دسته‌بندی همین حالا در جریان است'], JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);
    catfixClearStop();
    $cn = loadConnections();

    /* v10.126: ادامهٔ واقعی از چک‌پوینت — اگر resume=1 و فایلِ پیشرفت برای
       همین روش چک‌پوینت دارد، آن را نگه می‌داریم؛ در غیر این صورت از نو. */
    $cp = null;
    if (!empty($_GET['resume']) && is_file(CATFIX_PROGRESS_FILE)) {
        $old = json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true);
        if (is_array($old) && (string)($old['mode'] ?? '') === $mode
            && is_array($old['checkpoint'] ?? null)) {
            $cp = $old['checkpoint'];
        }
    }
    if ($cp === null) {
        localTaskDbForget(CATFIX_PROGRESS_FILE); @unlink(CATFIX_PROGRESS_FILE);
        @unlink(CATFIX_RESULT_FILE);
        @unlink(CATFIX_FETCH_CURSOR_FILE);
    }
    $cpStartedAt = ($cp !== null ? (int)($cp['started_at'] ?? 0) : 0);
    catfixProgress(['running' => true, 'done' => false, 'mode' => $mode,
        'product_id' => (int)$opts['product_id'], 'quorum' => (int)$opts['quorum'],
        'all_vendors' => !empty($opts['all_vendors']), 'use_learn' => !empty($opts['use_learn']),
        'vendor_id' => (int)$opts['vendor_id'],
        'started_at' => ($cpStartedAt > 0 ? $cpStartedAt : time()),
        'total' => 0, 'current' => (int)($cp['idx'] ?? 0),
        'fixed' => (int)($cp['fixed'] ?? 0), 'failed' => (int)($cp['failed'] ?? 0),
        'no_ai' => (int)($cp['no_ai'] ?? 0), 'no_cat' => (int)($cp['no_cat'] ?? 0),
        'skip_same' => (int)($cp['skip_same'] ?? 0), 'skip_tried' => (int)($cp['skip_tried'] ?? 0),
        'asked' => (int)($cp['asked'] ?? 0),
        'phase' => ($cp !== null ? 'resume' : 'start'),
        'log_add' => [($cp !== null ? '↻ ادامه از چک‌پوینت — ' : '🚀 شروعِ اصلاحِ دسته‌بندی — ')
            . 'روش: ' . catfixModeLabel($mode)
            . ((int)$opts['product_id'] > 0 ? (' · فقط محصول #' . (int)$opts['product_id']) : ' · همهٔ محصولاتِ ردشده')]]);

    // پاسخِ فوری، سپس ادامهٔ کار در پس‌زمینه
    $early = json_encode(['ok' => true, 'started' => true, 'mode' => $mode], JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();

    register_shutdown_function(function () use ($lockFp) {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
    });

    try {
        $rep = catfixRun($cn, $mode, $opts, $cp);
    } catch (Throwable $e) {
        /* خطایِ پردازه/شبکه نباید آخرین checkpoint امنِ محصولات را پاک کند؛
           کران بعدی همین اجرای نیمه‌کاره را دوباره می‌گیرد. */
        $catErrState = is_file(CATFIX_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true) : [];
        catfixProgress(['running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(),
            'checkpoint' => is_array($catErrState['checkpoint'] ?? null) ? $catErrState['checkpoint'] : null,
            'log_add' => ['❌ خطا: ' . $e->getMessage() . ' — checkpoint حفظ شد']]);
        catfixClearStop();
        exit;
    }
    @file_put_contents(CATFIX_RESULT_FILE, json_encode($rep, JSON_UNESCAPED_UNICODE), LOCK_EX);
    $stopped = catfixStopRequested();
    $catLastState = is_file(CATFIX_PROGRESS_FILE)
        ? json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true) : [];
    $catKeepCp = $stopped || !empty($rep['partial']) || !empty($rep['stopped']) || empty($rep['ok']);
    if (!$catKeepCp) @unlink(CATFIX_FETCH_CURSOR_FILE);
    catfixClearStop();
    catfixProgress(['running' => false, 'done' => true, 'stopped' => $stopped,
        'stale' => $catKeepCp, 'result_ok' => !empty($rep['ok']), 'error' => $rep['error'] ?? '',
        'fixed' => $rep['fixed'] ?? 0, 'failed' => $rep['failed'] ?? 0,
        'no_ai' => $rep['no_ai'] ?? 0, 'no_cat' => $rep['no_cat'] ?? 0,
        'skip_same' => $rep['skip_same'] ?? 0, 'skip_tried' => $rep['skip_tried'] ?? 0,
        'asked' => $rep['asked'] ?? 0,
        'checkpoint' => $catKeepCp && is_array($catLastState['checkpoint'] ?? null)
            ? $catLastState['checkpoint'] : null,
        'log_add' => [empty($rep['ok'])
            ? ('❌ ' . ($rep['error'] ?? 'ناموفق'))
            : ($catKeepCp ? ('⏸ متوقف شد؛ checkpoint حفظ شد — ' . ($rep['msg'] ?? ''))
                           : ('🏁 پایان در ' . $rep['took'] . ' ثانیه — ' . $rep['msg']))]]);
    exit;
}

if (isset($_GET['catfix_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $st = [];
    if (is_file(CATFIX_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true);
        if (is_array($d)) $st = $d;
    }
    $log = is_array($st['log'] ?? null) ? $st['log'] : [];
    $since = max(0, (int)($_GET['since'] ?? 0));
    $st['log_total'] = count($log);
    $st['log'] = $since > 0 ? array_slice($log, $since) : array_slice($log, -60);
    /* همان گاردِ dedup: اگر پردازه مرده ولی فایل هنوز running می‌گوید */
    if (!empty($st['running']) && !is_file(CATFIX_LOCK_FILE)
        && (time() - (int)($st['ts'] ?? 0)) > DEDUP_STALE_SEC) {
        $st['running'] = false; $st['done'] = true; $st['stale'] = true;
    }
    $st['ok'] = true;
    $st['has_result'] = is_file(CATFIX_RESULT_FILE);
    echo json_encode($st, JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['catfix_result'])) {
    header('Content-Type: application/json; charset=UTF-8');
    if (!is_file(CATFIX_RESULT_FILE)) {
        echo json_encode(['ok' => false, 'error' => 'هنوز گزارشی گرفته نشده'], JSON_UNESCAPED_UNICODE); exit;
    }
    echo (string)@file_get_contents(CATFIX_RESULT_FILE);
    exit;
}

if (isset($_GET['catfix_stop'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @file_put_contents(CATFIX_STOP_FILE, json_encode(['at' => time()]));
    catfixProgress(['log_add' => ['⏹ درخواستِ توقف ثبت شد — پس از محصولِ جاری متوقف می‌شود']]);
    echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

if (($_POST['action'] ?? '') === 'dedup_save_cfg') {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $d  = dedupDefaultCfg();
    $cfg = [];
    foreach ($d as $k => $v) {
        if (!array_key_exists($k, $_POST)) { $cfg[$k] = is_array($cn['dedup'] ?? null) && array_key_exists($k, $cn['dedup']) ? $cn['dedup'][$k] : $v; continue; }
        if (is_bool($v))    $cfg[$k] = !empty($_POST[$k]) && $_POST[$k] !== 'false' && $_POST[$k] !== '0';
        elseif (is_int($v)) $cfg[$k] = (int)$_POST[$k];
        else                $cfg[$k] = (string)$_POST[$k];
    }
    $cn['dedup'] = $cfg;
    saveConnections($cn);
    echo json_encode(['ok' => true, 'cfg' => dedupCfg($cn)], JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * پیش‌نمایشِ زندهٔ الگوها: کاربر چند عنوان نمونه می‌دهد و می‌بیند پس از
 * برداشتنِ پسوند چه چیزی می‌ماند و کدام‌ها هم‌گروه می‌شوند. هیچ درخواستی
 * به مقصد فرستاده نمی‌شود، پس فوری است.
 */
if (($_POST['action'] ?? '') === 'dedup_preview') {
    header('Content-Type: application/json; charset=UTF-8');
    $cfg = dedupCfg();
    foreach (dedupDefaultCfg() as $k => $v) {
        if (!array_key_exists($k, $_POST)) continue;
        if (is_bool($v))    $cfg[$k] = !empty($_POST[$k]) && $_POST[$k] !== 'false' && $_POST[$k] !== '0';
        elseif (is_int($v)) $cfg[$k] = (int)$_POST[$k];
        else                $cfg[$k] = (string)$_POST[$k];
    }
    $raw = (string)($_POST['titles'] ?? '');
    $lines = array_values(array_filter(array_map('trim', preg_split('/[\r\n]+/u', $raw)), function ($x) { return $x !== ''; }));
    $lines = array_slice($lines, 0, 60);
    $pats  = dedupPatterns($cfg);
    $rows = []; $groups = [];
    foreach ($lines as $i => $t) {
        $n = dedupNormalize($t, $cfg, $pats);
        // «تغییر کرد» یعنی الگوها چیزی برداشتند، نه صرفاً کوچک‌سازیِ حروف
        $base = dedupNormalize($t, $cfg, []);
        $rows[] = ['title' => $t, 'norm' => $n, 'changed' => ($n !== $base)];
        if ($n !== '') $groups[$n][] = $i;
    }
    $dups = [];
    foreach ($groups as $n => $idx) if (count($idx) > 1) $dups[] = ['norm' => $n, 'idx' => $idx];
    echo json_encode(['ok' => true, 'rows' => $rows, 'dups' => $dups,
        'patterns' => count($pats)], JSON_UNESCAPED_UNICODE);
    exit;
}

/** حذفِ دستیِ چند شناسه از دلِ گزارش (بدون اجرای دوبارهٔ کلِ اسکن) */
if (($_POST['action'] ?? '') === 'dedup_delete_ids') {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(0); @ignore_user_abort(true);
    $target = (string)($_POST['target'] ?? '');
    $ids = json_decode((string)($_POST['ids'] ?? '[]'), true);
    if (!is_array($ids)) $ids = [];
    $ids = array_values(array_unique(array_filter(array_map('intval', $ids))));
    $ids = array_slice($ids, 0, DEDUP_DEL_MAX);
    if (!$ids || ($target !== 'woo' && $target !== 'bsl')) {
        echo json_encode(['ok' => false, 'error' => 'ورودی نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    /* v10.42 (۵۶): همان محافظِ dedup_start — سیگنالِ جامانده bslReq را
       بی‌صدا خفه می‌کند و کاربر «هیچ اتفاقی نمی‌افتد» می‌بیند. */
    if (defined('BSL_STOP_FILE') && is_file(BSL_STOP_FILE)) { @unlink(BSL_STOP_FILE); }
    clearstatcache(true,BSL_STOP_FILE);
    $cn = loadConnections();

    /* v10.42 (۵۶): نگاشتِ «شناسهٔ محصول ⇒ شناسهٔ غرفه» از آخرین گزارشِ اسکن.
       فرانت‌اند فقط فهرستِ id می‌فرستد، ولی از v10.39 آن idها می‌توانند مالِ
       چند غرفهٔ متفاوت باشند. بدونِ این نگاشت، همه با توکنِ غرفهٔ پیش‌فرض
       PATCH می‌شدند و هرچه مالِ غرفهٔ دیگری بود ۴۰۳ می‌گرفت — همان باگی که
       کاربر دید: «اسکن X مورد پیدا می‌کند ولی حذف هیچ‌کدام را بایگانی
       نمی‌کند». گزارش روی دیسک است، پس نیازی به تغییرِ قراردادِ درخواست
       نیست و گزارش‌های قدیمی (بدونِ vendor_id) هم نمی‌شکنند. */
    $vidOf = [];
    if ($target === 'bsl' && is_file(DEDUP_RESULT_FILE)) {
        $rep = json_decode((string)@file_get_contents(DEDUP_RESULT_FILE), true);
        foreach ((array)($rep['duplicates_list'] ?? []) as $g) {
            if (!is_array($g)) continue;
            foreach ((array)($g['drop'] ?? []) as $p) {
                $pid = (int)($p['id'] ?? 0);
                $pv  = (int)($p['vendor_id'] ?? ($g['vendor_id'] ?? 0));
                if ($pid > 0 && $pv > 0) $vidOf[$pid] = $pv;
            }
        }
    }

    /* v10.44 (۵۸): این هندلر تا اینجا یک درخواستِ *همگام* بود: برای هر
       شناسه یک تماسِ شبکه + ۰٫۲ ثانیه مکث. روی ۲۰۰ مورد یعنی چند دقیقه
       انتظار در یک درخواست — همان چیزی که کامنتِ بالای همین بخش هشدار
       می‌داد: «هیچ مرورگر/پروکسی/هاستی این‌قدر صبر نمی‌کند». مرورگر
       تایم‌اوت می‌کرد، پاسخ هرگز نمی‌رسید و کاربر می‌دید «دکمه کار
       نمی‌کند» — در حالی که سرور داشت کار می‌کرد. حالا دقیقاً مثل
       dedup_start: پاسخِ فوری + اجرا در پس‌زمینه + گزارشِ زنده. */
    $lockFp = fopen(DEDUP_LOCK_FILE, 'c');
    if (!$lockFp || !flock($lockFp, LOCK_EX | LOCK_NB)) {
        if ($lockFp) fclose($lockFp);
        echo json_encode(['ok' => false, 'running' => true,
            'error' => 'یک عملیاتِ تکراری‌ها همین حالا در حال اجراست'], JSON_UNESCAPED_UNICODE); exit;
    }
    dedupClearStop();
    $total = count($ids);
    $verbFa = ($target === 'bsl' ? 'بایگانی' : 'حذف');
    localTaskDbForget(DEDUP_PROGRESS_FILE); @unlink(DEDUP_PROGRESS_FILE);
    dedupProgress(['running' => true, 'done' => false, 'target' => $target, 'mode' => 'delete',
        'started_at' => time(), 'phase' => 'delete', 'total' => $total, 'dups' => $total,
        'groups' => 0, 'processed' => 0, 'deleted' => 0, 'failed' => 0,
        'log_add' => ['🗑 شروعِ ' . $verbFa . ' ' . aiFaNum($total) . ' مورد']]);

    $early = json_encode(['ok' => true, 'started' => true, 'target' => $target, 'count' => $total],
        JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();

    register_shutdown_function(function () use ($lockFp) {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
    });

    $done = 0; $fail = 0; $items = []; $seen = 0; $stopped = false;
    foreach ($ids as $did) {
        if (dedupStopRequested()) { $stopped = true; break; }
        $seen++;
        if ($target === 'bsl') {
            if (!bslAllShops($cn)) { dedupProgress(['running'=>false,'done'=>true,'error'=>'تنظیمات باسلام ناقص','log_add'=>['❌ تنظیمات باسلام ناقص']]); exit; }
            $r  = bslArchiveSmart($cn, $did, (int)($vidOf[$did] ?? 0));
            $ok = !empty($r['ok']);
            $em = (string)($r['msg'] ?? '');
            $vn = (string)($r['vendor_name'] ?? '');
        } else {
            $w = $cn['woocommerce'] ?? [];
            if (empty($w['store_url'])) { dedupProgress(['running'=>false,'done'=>true,'error'=>'تنظیمات ووکامرس ناقص','log_add'=>['❌ تنظیمات ووکامرس ناقص']]); exit; }
            $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'DELETE', 'products/' . $did . '?force=true');
            $ok = !empty($r['ok']);
            $em = $r['body']['message'] ?? ('HTTP ' . ($r['code'] ?? '?'));
            $vn = '';
        }
        if ($ok) { $done++; $items[] = ['id' => $did, 'ok' => true, 'vendor' => $vn]; }
        else     { $fail++; $items[] = ['id' => $did, 'ok' => false, 'msg' => (string)$em, 'vendor' => $vn]; }
        /* گزارشِ زنده: هر مورد همان لحظه در پنل دیده می‌شود */
        dedupProgress(['processed' => $seen, 'deleted' => $done, 'failed' => $fail,
            'phase' => 'delete', 'dups' => $total,
            'log_add' => [($ok ? '✅ ' : '❌ ') . '#' . $did
                . ($vn !== '' ? (' · 🏪 ' . $vn) : '')
                . ($ok ? (' — ' . $verbFa . ' شد') : (' — ' . mb_substr((string)$em, 0, 90, 'UTF-8')))]]);
        usleep(200000);
    }
    /* v10.42 (۵۶): وقتی *همه* ناموفق‌اند، ok=false برمی‌گردد. تا اینجا حتی
       با صفر موفقیت هم ok=true می‌رفت و مرورگر «✅ ۰ محصول بایگانی شد» نشان
       می‌داد — دقیقاً همان «انگار هیچ اتفاقی نمی‌افتد». حالا علتِ واقعیِ
       اولین شکست هم در پیام می‌آید تا کاربر بفهمد مشکل توکن است یا دسترسی. */
    $firstErr = '';
    foreach ($items as $it) if (empty($it['ok']) && ($it['msg'] ?? '') !== '') { $firstErr = (string)$it['msg']; break; }
    $verb = ($target === 'bsl' ? ' محصول بایگانی شد' : ' محصول حذف شد');
    /* v10.44 (۵۸): پاسخ زودتر رفته؛ نتیجهٔ نهایی در فایلِ پیشرفت می‌نشیند تا
       ddWatch آن را ببیند. متنِ خلاصه همان قبلی است تا رابط تغییر نکند. */
    $summary = aiFaNum($done) . $verb
             . ($fail ? ('؛ ' . aiFaNum($fail) . ' ناموفق'
                         . ($firstErr !== '' ? (' (' . mb_substr($firstErr, 0, 80, 'UTF-8') . ')') : '')) : '');
    dedupProgress([
        'running' => false, 'done' => true, 'phase' => 'delete', 'stopped' => $stopped,
        'processed' => $seen, 'deleted' => $done, 'failed' => $fail, 'dups' => $total,
        'del_ok' => $done > 0, 'del_msg' => $summary,
        'error' => $done === 0 ? ('هیچ محصولی ' . ($target === 'bsl' ? 'بایگانی' : 'حذف') . ' نشد'
                                  . ($firstErr !== '' ? (' — ' . $firstErr) : '')) : '',
        'log_add' => [($stopped ? '⏹ متوقف شد — ' : '🏁 پایان — ') . $summary]]);
    /* گزارشِ ریزِ هر مورد برای «آخرین نتیجه» */
    @file_put_contents(DEDUP_DEL_RESULT_FILE, json_encode(
        ['ok' => $done > 0, 'at' => time(), 'target' => $target, 'deleted' => $done,
         'failed' => $fail, 'stopped' => $stopped, 'items' => $items, 'msg' => $summary],
        JSON_UNESCAPED_UNICODE), LOCK_EX);
    exit;
}

if (isset($_GET['suffix_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $st = [];
    if (is_file(SUFFIX_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(SUFFIX_PROGRESS_FILE), true);
        if (is_array($d)) $st = $d;
    }
    $log = is_array($st['log'] ?? null) ? $st['log'] : [];
    $since = max(0, (int)($_GET['since'] ?? 0));
    $st['log_total'] = count($log);
    $st['log'] = $since > 0 ? array_slice($log, $since) : array_slice($log, -50);
    $st['ok'] = true;
    echo json_encode($st, JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['suffix_result'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $f = __DIR__ . '/suffix_result.json';
    if (!is_file($f)) { echo json_encode(['ok' => false, 'error' => 'نتیجه‌ای نیست'], JSON_UNESCAPED_UNICODE); exit; }
    echo (string)@file_get_contents($f);
    exit;
}

/** v8.53: ارسال دوبارهٔ آخرین گزارش به پیام‌رسان‌ها */
if (isset($_GET['suffix_notify'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $why = notifPrereq($cn);
    if ($why !== null) { echo json_encode(['ok' => false, 'error' => $why], JSON_UNESCAPED_UNICODE); exit; }
    $f = __DIR__ . '/suffix_result.json';
    $rep = is_file($f) ? json_decode((string)@file_get_contents($f), true) : null;
    if (!is_array($rep) || empty($rep['ok'])) {
        echo json_encode(['ok' => false, 'error' => 'اول یک گزارش بگیرید'], JSON_UNESCAPED_UNICODE); exit;
    }
    echo json_encode(['ok' => true, 'delivery' => notifSend($cn, ((!empty($rep['kind']) && $rep['kind']==='summary') ? profileStatsSummaryMsg($rep) : suffixReportMsg($rep)), 'report')],
        JSON_UNESCAPED_UNICODE);
    exit;
}

/** v8.55: نمای کلی هر سه صف — کدام پروفایل کجاست */
if (isset($_GET['queues_overview'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $profs = loadProfiles();
    $active = queueActiveStatuses();
    $mk = function (array $entries) use ($profs, $active) {
        $out = ['total' => count($entries), 'active' => 0, 'profiles' => []];
        foreach ($entries as $e) {
            if (!is_array($e)) continue;
            $st = (string)($e['status'] ?? '');
            if (!in_array($st, $active, true)) continue;
            $out['active']++;
            $k = (string)($e['profile_key'] ?? '');
            $out['profiles'][] = ['key' => $k, 'status' => $st,
                'name' => (string)($e['profile_name'] ?? ($profs[$k]['name'] ?? $k))];
        }
        return $out;
    };
    $ex = extractReadQueue();
    $bs = bslReadQueue();
    $wo = wooReadQueue();
    echo json_encode(['ok' => true, 'dedup' => queueDedupOn(),
        'stale_after' => queueDedupStale(),
        'queues' => ['extract' => $mk($ex['entries'] ?? []),
                     'bsl' => $mk($bs['entries'] ?? []),
                     'woo' => $mk($wo['entries'] ?? [])]], JSON_UNESCAPED_UNICODE);
    exit;
}

/** v8.49: وضعیت زندهٔ مغایرت‌گیری */
if (isset($_GET['recon_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $st = reconProgressRead();
    // v8.64: اگر اجرا وسط راه مرده باشد (تایم‌اوت PHP، ری‌استارت سرور)،
    // فایل پیشرفت برای همیشه running می‌ماند و رابط کاربری بی‌نهایت
    // می‌چرخد — همان «کار نمی‌کند». اگر ۳ دقیقه هیچ به‌روزرسانی نبود،
    // اجرا مرده حساب می‌شود و علتش گفته می‌شود.
    if (!empty($st['running']) && empty($st['done'])) {
        $idle = time() - (int)($st['ts'] ?? 0);
        if ($idle > 180) {
            $st['running'] = false; $st['done'] = true; $st['stalled'] = $idle;
            $st['result_ok'] = false;
            $st['error'] = 'اجرا بدون پایان متوقف شد (' . $idle . ' ثانیه بی‌حرکت) — '
                . 'احتمالاً محدودیت زمان اجرای PHP روی این میزبان. '
                . 'دوباره امتحان کنید یا با تعداد صفحهٔ کمتر.';
            $log = is_array($st['log'] ?? null) ? $st['log'] : [];
            $log[] = ['t' => time(), 'm' => '⛔ ' . $st['error']];
            $st['log'] = $log;
            @file_put_contents(RECON_PROGRESS_FILE, json_encode($st, JSON_UNESCAPED_UNICODE), LOCK_EX);
        }
    }
    $since = max(0, (int)($_GET['since'] ?? 0));
    $log = is_array($st['log'] ?? null) ? $st['log'] : [];
    $st['log_total'] = count($log);
    $st['log'] = $since > 0 ? array_slice($log, $since) : array_slice($log, -60);
    $st['ok'] = true;
    echo json_encode($st, JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v8.64: اندپوینت‌های پاسخ خودکار به پیام مشتریان
 *   ?ar_rules=1                   → خواندن قواعد و تنظیمات
 *   POST action=ar_save_rules     → ذخیرهٔ قواعد
 *   ?ar_run=1[&dry=1][&now=1]     → اجرا (dry فقط پیش‌نمایش)
 *   ?ar_test=1&text=...           → کدام قاعده به این متن می‌خورد
 *   ?ar_log=1                     → آخرین پاسخ‌های خودکار
 * ===================================================================== */
/**
 * v8.65: دفترچهٔ شناسهٔ مقصد.
 *   ?remote_map=1                 → خلاصه
 *   &rebuild=woo|bsl              → بازسازی از روی عنوان‌های فعلی مقصد
 *   &clear=woo|bsl                → پاک کردن
 */
/**
 * v8.70: بررسی امنیت نصب.
 * ?sec_check=1 — آیا فایل‌های داده از طریق وب قابل خواندن‌اند؟
 * خودِ سرور به خودش درخواست می‌زند تا واقعیت را ببیند، نه حدس.
 */
if (isset($_GET['sec_check'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(60);
    $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
    $host   = (string)($_SERVER['HTTP_HOST'] ?? 'localhost');
    $dir    = rtrim(str_replace('\\', '/', dirname((string)($_SERVER['SCRIPT_NAME'] ?? '/'))), '/');
    $base   = $scheme . '://' . $host . $dir . '/';
    $checks = []; $exposed = 0;
    foreach (['connections.json', 'profiles.json', 'category_learning.json',
              'remote_map.json', 'autoreply_rules.json'] as $f) {
        if (!is_file(__DIR__ . '/' . $f)) { $checks[] = ['file' => $f, 'state' => 'nofile']; continue; }
        $ch = curl_init($base . $f);
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => 8,
            CURLOPT_SSL_VERIFYPEER => 0, CURLOPT_SSL_VERIFYHOST => 0, CURLOPT_NOBODY => false]);
        $body = (string)curl_exec($ch);
        $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        curl_close($ch);
        // اگر ۲۰۰ برگردد و محتوایش JSON باشد یعنی واقعاً لو رفته
        $isOpen = ($code >= 200 && $code < 300) && $body !== ''
                  && (json_decode($body, true) !== null || $body[0] === '{' || $body[0] === '[');
        if ($isOpen) $exposed++;
        $checks[] = ['file' => $f, 'state' => $isOpen ? 'open' : 'protected', 'http' => $code];
    }
    echo json_encode(['ok' => true, 'base' => $base, 'exposed' => $exposed,
        'checks' => $checks, 'htaccess' => is_file(__DIR__ . '/.htaccess'),
        'advice' => $exposed > 0
            ? 'فایل‌های داده از اینترنت قابل خواندن‌اند — فایل htaccess-sample.txt را با نام .htaccess کنار همین فایل بگذارید'
            : 'فایل‌های داده از بیرون قابل خواندن نیستند'], JSON_UNESCAPED_UNICODE);
    exit;
}



/* =====================================================================
 *  v10.113: ماتریس مقایسه — کاملاً سرورساید + جاب پس‌زمینه + دوره‌ای
 *  ساخت: ?sync_matrix_start=1  (یا POST action=sync_matrix_start)
 *  وضعیت: ?sync_matrix_status=1
 *  خواندن صفحه‌بندی‌شده از نتیجهٔ ذخیره‌شده: ?sync_matrix=1&page=&per_page=
 *  اجرا داخل cron همراه reconAutoTick وقتی build_matrix روشن است
 * ===================================================================== */
function matrixCollectSuffixes(): array {
    $sfx = [];
    foreach (loadProfiles() as $p) {
        $s = trim((string)($p['titleSuffix'] ?? ''));
        if ($s !== '') $sfx[$s] = true;
    }
    return array_keys($sfx);
}
function matrixBareTitle(string $title, array $suffixes = []): string {
    $t = trim($title);
    usort($suffixes, function ($a, $b) {
        return mb_strlen((string)$b) <=> mb_strlen((string)$a);
    });
    foreach ($suffixes as $s) {
        $s = trim((string)$s);
        if ($s === '') continue;
        if (function_exists('mb_substr') && mb_strlen($t) >= mb_strlen($s)
            && mb_substr($t, -mb_strlen($s)) === $s) {
            $t = trim(mb_substr($t, 0, mb_strlen($t) - mb_strlen($s)));
        } elseif (strlen($t) >= strlen($s) && substr($t, -strlen($s)) === $s) {
            $t = trim(substr($t, 0, -strlen($s)));
        }
    }
    return reconNormTitle($t);
}
function matrixPriceTone(int $src, int $dst): string {
    if ($src <= 0 && $dst <= 0) return 'na';
    if ($src <= 0) return 'no_src';
    if ($dst <= 0) return 'missing_dst';
    if ($src === $dst) return 'ok';
    $diff = abs($src - $dst) / max($src, 1);
    if ($diff <= 0.01) return 'ok';
    if ($diff <= 0.05) return 'warn';
    return 'bad';
}
function matrixProgress(array $patch): void {
    $cur = localTaskStateRead(SYNC_MATRIX_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) {
            $log[] = ['t' => time(), 'm' => (string)$l];
        }
        if (count($log) > 120) $log = array_slice($log, -120);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log;
    $cur['ts'] = time();
    writeProgress(SYNC_MATRIX_PROGRESS_FILE, $cur);
}
function matrixStopRequested(): bool { return is_file(SYNC_MATRIX_STOP_FILE); }
function matrixStopClear(): void { @unlink(SYNC_MATRIX_STOP_FILE); }

function matrixProgressRead(): array {
    return localTaskStateRead(SYNC_MATRIX_PROGRESS_FILE, []);
}
function matrixResultLoad(): array {
    if (!is_file(SYNC_MATRIX_RESULT_FILE)) return [];
    $d = json_decode((string)@file_get_contents(SYNC_MATRIX_RESULT_FILE), true);
    return is_array($d) ? $d : [];
}
function matrixResultSave(array $data): bool {
    $data['generated_at'] = $data['generated_at'] ?? time();
    $data['version'] = APP_VERSION;
    $json = json_encode($data, JSON_UNESCAPED_UNICODE);
    if ($json === false) return false;
    // فایل می‌تواند بزرگ باشد
    return false !== @file_put_contents(SYNC_MATRIX_RESULT_FILE, $json, LOCK_EX);
}

/**
 * ساخت کامل ماتریس روی سرور با گزارش پیشرفت.
 * $opts: profile, source (manual|recon_auto|cron)
 */
function matrixBuild(array $opts = []): array {
    @set_time_limit(0);
    @ignore_user_abort(true);
    $cn = loadConnections();
    $suffixes = matrixCollectSuffixes();
    $profileFilter = trim((string)($opts['profile'] ?? 'all'));
    $source = (string)($opts['source'] ?? 'manual');
    $resumeCp = is_array($opts['checkpoint'] ?? null) ? $opts['checkpoint'] : [];
    $startedAt = (int)($resumeCp['started_at'] ?? time());
    $profileRows = is_array($resumeCp['profile_rows'] ?? null) ? $resumeCp['profile_rows'] : [];
    $profilesDone = array_values(array_unique(array_map('strval', (array)($resumeCp['profiles_done'] ?? []))));
    $profilesDoneSet = $profilesDone ? array_fill_keys($profilesDone, true) : [];
    $matrixWooCp = is_array($resumeCp['woo_rows'] ?? null) ? $resumeCp['woo_rows'] : [];
    $matrixWooDone = !empty($resumeCp['woo_done']);
    $matrixWooPage = (int)($resumeCp['woo_page'] ?? 0);
    $matrixWooComplete = !empty($resumeCp['woo_complete']);
    $matrixShopCp = is_array($resumeCp['shop_rows'] ?? null) ? $resumeCp['shop_rows'] : [];
    $matrixShopPages = is_array($resumeCp['shop_pages'] ?? null) ? $resumeCp['shop_pages'] : [];
    $matrixShopDone = is_array($resumeCp['shop_done'] ?? null) ? $resumeCp['shop_done'] : [];
    if (!array_key_exists('shop_done', $resumeCp) && $matrixShopCp) {
        foreach ($matrixShopCp as $savedVid => $_savedRows) $matrixShopDone[(string)$savedVid] = true;
    }
    $matrixCp = static function (string $phase, array $rows, array $done, array $woo, array $shops, int $at, bool $wooDone = false) use ($profileFilter, &$matrixWooPage, &$matrixWooComplete, &$matrixShopPages, &$matrixShopDone): array {
        return ['phase' => $phase, 'profile_filter' => ($profileFilter ?: 'all'),
            'profile_rows' => $rows, 'profiles_done' => $done, 'woo_rows' => $woo,
            'woo_done' => $wooDone, 'woo_page' => $matrixWooPage, 'woo_complete' => $matrixWooComplete,
            'shop_rows' => $shops, 'shop_pages' => $matrixShopPages, 'shop_done' => $matrixShopDone,
            'started_at' => $at];
    };

    matrixProgress([
        'running' => true, 'done' => false, 'error' => '',
        'phase' => 'profiles', 'pct' => $profilesDone ? 2 : 2, 'source' => $source,
        'profile' => $profileFilter, 'started_at' => $startedAt,
        'checkpoint' => $matrixCp('profiles', $profileRows, $profilesDone, $matrixWooCp, $matrixShopCp, $startedAt, $matrixWooDone),
        'log_add' => ['🚀 ' . ($profilesDone ? 'ادامه ساخت جدول مقایسه' : 'شروع ساخت جدول مقایسه')
            . ' (سرورساید) — منبع: ' . $source],
    ]);

    $wooCfg = destPriceCfg($cn, 'woocommerce');
    $bslCfg = destPriceCfg($cn, 'basalam');

    $rowsByKey = $profileRows;
    $stopMatrix = static function (string $phase) use (&$rowsByKey, &$profilesDone, &$matrixWooCp,
        &$matrixShopCp, &$startedAt, &$matrixWooDone, &$matrixWooPage, &$matrixWooComplete,
        &$matrixShopPages, &$matrixShopDone, $profileFilter): array {
        $cp = ['phase' => $phase, 'profile_filter' => ($profileFilter ?: 'all'),
            'profile_rows' => $rowsByKey, 'profiles_done' => $profilesDone,
            'woo_rows' => $matrixWooCp, 'woo_done' => $matrixWooDone,
            'woo_page' => $matrixWooPage, 'woo_complete' => $matrixWooComplete,
            'shop_rows' => $matrixShopCp, 'shop_pages' => $matrixShopPages, 'shop_done' => $matrixShopDone,
            'started_at' => $startedAt];
        matrixProgress(['running' => false, 'done' => true, 'stopped' => true, 'partial' => true,
            'stale' => true, 'phase' => 'stopped', 'checkpoint' => $cp,
            'log_add' => ['⏹ ساخت جدول متوقف شد — checkpoint حفظ شد']]);
        matrixStopClear();
        return ['ok' => true, 'stopped' => true, 'partial' => true, 'checkpoint' => $cp];
    };
    $profiles = loadProfiles();
    $pN = 0; $pTot = max(1, count($profiles));
    foreach ($profiles as $pk => $profile) {
        if (matrixStopRequested()) return $stopMatrix('profiles');
        $pN++;
        if ($profileFilter !== '' && $profileFilter !== 'all' && $profileFilter !== $pk) continue;
        if (isset($profilesDoneSet[(string)$pk])) continue;
        $pname = (string)($profile['name'] ?? $pk);
        if ($pN % 3 === 0 || $pN === $pTot) {
            matrixProgress([
                'phase' => 'profiles', 'pct' => 5 + (int)round(20 * $pN / $pTot),
                'cur' => $pN, 'cur_total' => $pTot,
                'log_add' => ['📁 پروفایل ' . $pN . '/' . $pTot . ' — ' . $pname],
            ]);
        }
        foreach (profileOrderedProducts($profile, null, true) as $p) {
            $title = (string)($p['title'] ?? '');
            $bare = matrixBareTitle($title, $suffixes);
            if ($bare === '') continue;
            $raw = (int)extractPriceNum((string)($p['price'] ?? $p['orig_price'] ?? '0'));
            if ($raw <= 0) $raw = (int)preg_replace('/\D/', '', (string)($p['orig_price'] ?? '0'));
            $profP = (int)($p['final_price'] ?? 0);
            if ($profP <= 0) $profP = profileFinalPrice($profile, (string)($p['price'] ?? ''));
            $wooExpect = $profP > 0 && ($wooCfg['mode'] ?? 'none') !== 'none'
                ? destAdjustPrice($profP, $wooCfg) : $profP;
            $bslExpect = $profP > 0 && ($bslCfg['mode'] ?? 'none') !== 'none'
                ? destAdjustPrice($profP, $bslCfg) : $profP;
            if (!isset($rowsByKey[$bare])) {
                $rowsByKey[$bare] = [
                    'bare' => $bare, 'title' => $title, 'key' => (string)($p['key'] ?? ''),
                    'profile' => $pname, 'profile_key' => (string)$pk,
                    'src_price' => $raw, 'profile_price' => $profP,
                    'woo_expect' => $wooExpect, 'bsl_expect' => $bslExpect,
                    'profile_hits' => 1, 'woo' => null, 'shops' => [],
                ];
            } else {
                $rowsByKey[$bare]['profile_hits']++;
                if ($rowsByKey[$bare]['profile_price'] <= 0 && $profP > 0) {
                    $rowsByKey[$bare]['profile_price'] = $profP;
                    $rowsByKey[$bare]['woo_expect'] = $wooExpect;
                    $rowsByKey[$bare]['bsl_expect'] = $bslExpect;
                    $rowsByKey[$bare]['src_price'] = $raw;
                }
            }
        }
        $profilesDone[] = (string)$pk;
        $profilesDoneSet[(string)$pk] = true;
        matrixProgress([
            'phase' => 'profiles', 'pct' => 5 + (int)round(20 * $pN / $pTot),
            'cur' => $pN, 'cur_total' => $pTot,
            'checkpoint' => $matrixCp('profiles', $rowsByKey, $profilesDone, $matrixWooCp, $matrixShopCp, $startedAt, $matrixWooDone),
        ]);
    }
    matrixProgress([
        'phase' => 'profiles_done', 'pct' => 28,
        'checkpoint' => $matrixCp('woo_fetch', $rowsByKey, $profilesDone, $matrixWooCp, $matrixShopCp, $startedAt, $matrixWooDone),
        'log_add' => ['✅ ' . count($rowsByKey) . ' عنوان یکتا از پروفایل‌ها'],
    ]);

    // Woo
    if (matrixStopRequested()) return $stopMatrix('woo_fetch');
    $wooErr = '';
    $wooRows = array_values(array_filter($matrixWooCp, 'is_array'));
    $w = $cn['woocommerce'] ?? [];
    matrixProgress(['phase' => 'woo_fetch', 'pct' => 32, 'log_add' => [
            $matrixWooDone ? '↻ ووکامرس از checkpoint خوانده شد' : ('📥 دریافت محصولات ووکامرس…'
            . ((function_exists('wooDirectAvailable') && wooDirectAvailable())
                ? ' (مسیر ⚡ مستقیم DB — سریع)' : ' (مسیر 🌐 REST API — کندتر)')),
        ]]);
    if (!$matrixWooDone) {
        $wooMeta = [];
        try {
            if (!empty($w['store_url']) || function_exists('wc_get_products')) {
                // progress via reconProgress is separate; also tick matrix
                $wooRows = reconFetchWoo(is_array($w) ? $w : [], 0, $wooMeta);
            } else {
                $wooErr = 'تنظیمات ووکامرس ناقص';
            }
        } catch (Throwable $e) {
            $wooErr = $e->getMessage();
            $wooMeta = ['partial' => true, 'reason' => 'exception', 'page' => $matrixWooPage];
        }
        $matrixWooCp = $wooRows;
        $matrixWooPage = (int)($wooMeta['page'] ?? $matrixWooPage);
        $matrixWooComplete = empty($wooMeta) || !empty($wooMeta['complete']);
        $matrixWooDone = $wooErr === '' && $matrixWooComplete;
        matrixProgress(['checkpoint' => $matrixCp('woo_' . ($matrixWooDone ? 'map' : 'fetch'), $rowsByKey,
            $profilesDone, $matrixWooCp, $matrixShopCp, $startedAt, $matrixWooDone)]);
        if (!$matrixWooDone) {
            $why = $wooErr ?: 'برداشت ووکامرس کامل نشد';
            matrixProgress(['running' => false, 'done' => true, 'stale' => true, 'partial' => true,
                'error' => $why, 'phase' => 'stopped',
                'checkpoint' => $matrixCp('woo_fetch', $rowsByKey, $profilesDone, $matrixWooCp, $matrixShopCp, $startedAt, false),
                'log_add' => ['⚠️ ' . $why . ' — checkpoint حفظ شد']]);
            return ['ok' => false, 'partial' => true, 'error' => $why];
        }
    }
    matrixProgress([
        'phase' => 'woo_map', 'pct' => 48,
        'log_add' => ['✅ ووکامرس: ' . count($wooRows) . ' محصول' . ($wooErr !== '' ? (' — ' . $wooErr) : '')],
    ]);
    foreach ($wooRows as $wr) {
        $bare = matrixBareTitle((string)($wr['title'] ?? ''), $suffixes);
        if ($bare === '') continue;
        $cell = [
            'id' => (int)($wr['id'] ?? 0),
            'title' => (string)($wr['title'] ?? ''),
            'price' => (int)($wr['price'] ?? 0),
            'status' => (string)($wr['status'] ?? ''),
        ];
        if (!isset($rowsByKey[$bare])) {
            $rowsByKey[$bare] = [
                'bare' => $bare, 'title' => $cell['title'], 'key' => '',
                'profile' => '', 'profile_key' => '', 'src_price' => 0,
                'profile_price' => 0, 'woo_expect' => 0, 'bsl_expect' => 0,
                'profile_hits' => 0, 'woo' => null, 'shops' => [],
            ];
        }
        if ($rowsByKey[$bare]['woo'] !== null) {
            $rowsByKey[$bare]['woo_dup'] = true;
            if (!isset($rowsByKey[$bare]['woo_extra'])) $rowsByKey[$bare]['woo_extra'] = [];
            $rowsByKey[$bare]['woo_extra'][] = $cell;
        } else {
            $rowsByKey[$bare]['woo'] = $cell;
        }
    }

    // Basalam shops
    $shopsMeta = [];
    $bslErr = '';
    $shopList = function_exists('bslAllShops') ? bslAllShops($cn) : [];
    $sTot = max(1, count($shopList));
    $sN = 0;
    foreach ($shopList as $sh) {
        if (matrixStopRequested()) return $stopMatrix('bsl_fetch');
        if (!is_array($sh)) continue;
        $vid = (int)($sh['vendor_id'] ?? 0);
        $tok = trim((string)($sh['token'] ?? ($cn['basalam']['token'] ?? '')));
        $sname = trim((string)($sh['shop_name'] ?? ($sh['name'] ?? ('غرفه ' . $vid))));
        if ($vid <= 0 || $tok === '') continue;
        $sN++;
        $shopsMeta[] = ['vendor_id' => $vid, 'name' => $sname, 'is_default' => !empty($sh['is_default'])];
        matrixProgress([
            'phase' => 'bsl_fetch', 'pct' => 50 + (int)round(30 * $sN / $sTot),
            'cur' => $sN, 'cur_total' => $sTot,
            'log_add' => ['🏪 دریافت غرفه ' . $sN . '/' . $sTot . ' — ' . $sname . ' (فقط فعال)'],
        ]);
        $shopDone = !empty($matrixShopDone[(string)$vid]);
        $remote = is_array($matrixShopCp[(string)$vid] ?? null) ? $matrixShopCp[(string)$vid] : [];
        $shopMeta = [];
        try {
            if (!$shopDone) {
                /* v10.116: فقط محصولات فعال قابل‌مشاهدهٔ مشتری (2976)، با cursor صفحه‌ای */
                $remote = reconFetchResumable('bsl', [], $tok, $vid, $shopMeta, true);
            }
        } catch (Throwable $e) {
            $bslErr .= $sname . ': ' . $e->getMessage() . '; ';
            $shopMeta = ['partial' => true, 'reason' => 'exception', 'page' => (int)($matrixShopPages[(string)$vid] ?? 0)];
        }
        $matrixShopCp[(string)$vid] = $remote;
        $matrixShopPages[(string)$vid] = (int)($shopMeta['page'] ?? ($matrixShopPages[(string)$vid] ?? 0));
        $shopDone = $shopDone || (empty($shopMeta) || !empty($shopMeta['complete'])) && $bslErr === '';
        $matrixShopDone[(string)$vid] = $shopDone;
        matrixProgress(['checkpoint' => $matrixCp('bsl_' . ($shopDone ? 'map' : 'fetch'), $rowsByKey, $profilesDone,
            $matrixWooCp, $matrixShopCp, $startedAt, $matrixWooDone)]);
        if (!$shopDone) {
            $why = $bslErr ?: ('برداشت غرفهٔ ' . $sname . ' کامل نشد');
            matrixProgress(['running' => false, 'done' => true, 'stale' => true, 'partial' => true,
                'error' => $why, 'phase' => 'stopped',
                'checkpoint' => $matrixCp('bsl_fetch', $rowsByKey, $profilesDone, $matrixWooCp, $matrixShopCp, $startedAt, $matrixWooDone),
                'log_add' => ['⚠️ ' . $why . ' — checkpoint حفظ شد']]);
            return ['ok' => false, 'partial' => true, 'error' => $why];
        }
        $seen = [];
        foreach ($remote as $br) {
            $bare = matrixBareTitle((string)($br['title'] ?? ''), $suffixes);
            if ($bare === '') continue;
            $cell = [
                'id' => (int)($br['id'] ?? 0),
                'title' => (string)($br['title'] ?? ''),
                'price' => (int)($br['price_toman'] ?? 0),
                'price_rial' => (int)($br['price'] ?? 0),
            ];
            if (!isset($rowsByKey[$bare])) {
                $rowsByKey[$bare] = [
                    'bare' => $bare, 'title' => $cell['title'], 'key' => '',
                    'profile' => '', 'profile_key' => '', 'src_price' => 0,
                    'profile_price' => 0, 'woo_expect' => 0, 'bsl_expect' => 0,
                    'profile_hits' => 0, 'woo' => null, 'shops' => [],
                ];
            }
            if (isset($seen[$bare])) {
                $rowsByKey[$bare]['shops'][$vid]['dup'] = true;
            }
            $seen[$bare] = true;
            $baseExpect = (int)($rowsByKey[$bare]['bsl_expect'] ?? 0);
            $shopExpect = $baseExpect;
            $profP = (int)($rowsByKey[$bare]['profile_price'] ?? 0);
            if ($profP > 0 && function_exists('bslShopPriceFor')) {
                $afterDest = $baseExpect > 0 ? $baseExpect : $profP;
                $adj = bslShopPriceFor($afterDest, $sh, (int)($bslCfg['round'] ?? 0));
                if (!empty($adj['price'])) $shopExpect = (int)$adj['price'];
            }
            $rowsByKey[$bare]['shops'][$vid] = array_merge($cell, [
                'shop_name' => $sname,
                'expect' => $shopExpect,
                'tone' => matrixPriceTone($shopExpect, (int)$cell['price']),
            ]);
        }
        matrixProgress([
            'log_add' => ['  ✓ ' . $sname . ': ' . count($remote) . ' محصول'],
        ]);
    }

    matrixProgress(['phase' => 'compare', 'pct' => 85, 'log_add' => ['⚖️ محاسبه وضعیت‌ها...']]);

    $rows = [];
    $sum = [
        'total' => 0, 'ok' => 0, 'price_mismatch' => 0, 'missing_woo' => 0,
        'missing_bsl' => 0, 'extra_woo' => 0, 'extra_bsl' => 0,
        'dup_profile' => 0, 'dup_woo' => 0, 'dup_bsl' => 0,
        'in_all' => 0, 'only_profile' => 0,
    ];
    foreach ($rowsByKey as $bare => $r) {
        $hasProf = ($r['profile_hits'] ?? 0) > 0;
        $hasWoo = !empty($r['woo']);
        $shopCount = 0; $shopOk = 0; $shopBad = 0; $shopMiss = 0;
        foreach ($shopsMeta as $sm) {
            $vid = (int)$sm['vendor_id'];
            if (!empty($r['shops'][$vid])) {
                $shopCount++;
                $t = $r['shops'][$vid]['tone'] ?? 'na';
                if ($t === 'ok') $shopOk++;
                elseif ($t === 'bad' || $t === 'warn') $shopBad++;
            } elseif ($hasProf) {
                $shopMiss++;
            }
        }
        $wooTone = 'na';
        if ($hasProf && $hasWoo) {
            $wooTone = matrixPriceTone((int)$r['woo_expect'], (int)($r['woo']['price'] ?? 0));
        } elseif ($hasProf && !$hasWoo) {
            $wooTone = 'missing_dst';
        } elseif (!$hasProf && $hasWoo) {
            $wooTone = 'extra';
        }
        $flags = [];
        if (($r['profile_hits'] ?? 0) > 1) { $flags[] = 'dup_profile'; $sum['dup_profile']++; }
        if (!empty($r['woo_dup'])) { $flags[] = 'dup_woo'; $sum['dup_woo']++; }
        foreach ($r['shops'] as $sc) {
            if (!empty($sc['dup'])) { $flags[] = 'dup_bsl'; $sum['dup_bsl']++; break; }
        }
        if ($wooTone === 'missing_dst') { $flags[] = 'missing_woo'; $sum['missing_woo']++; }
        if ($wooTone === 'extra') { $flags[] = 'extra_woo'; $sum['extra_woo']++; }
        if ($wooTone === 'bad' || $wooTone === 'warn') { $flags[] = 'price_mismatch'; }
        if ($shopMiss > 0 && $hasProf) { $flags[] = 'missing_bsl'; $sum['missing_bsl']++; }
        if ($shopBad > 0) { $flags[] = 'price_mismatch'; }
        $flags = array_values(array_unique($flags));
        if (in_array('price_mismatch', $flags, true)) { $sum['price_mismatch']++; }

        $status = 'partial';
        if ($hasProf && $hasWoo && $shopMiss === 0 && $wooTone === 'ok' && $shopBad === 0) {
            $status = 'ok'; $sum['ok']++; $sum['in_all']++;
        } elseif ($hasProf && !$hasWoo && $shopCount === 0) {
            $status = 'only_profile'; $sum['only_profile']++;
        } elseif (!$hasProf) {
            $status = 'only_dest';
        } elseif ($wooTone === 'bad' || $shopBad > 0) {
            $status = 'mismatch';
        } elseif ($wooTone === 'missing_dst' || $shopMiss > 0) {
            $status = 'missing';
        }

        $r['woo_tone'] = $wooTone;
        $r['status'] = $status;
        $r['flags'] = $flags;
        $r['shop_ok'] = $shopOk;
        $r['shop_bad'] = $shopBad;
        $r['shop_miss'] = $shopMiss;
        $rows[] = $r;
        $sum['total']++;
    }

    $order = ['mismatch' => 0, 'missing' => 1, 'only_profile' => 2, 'only_dest' => 3, 'partial' => 4, 'ok' => 5];
    usort($rows, function ($a, $b) use ($order) {
        $oa = $order[$a['status']] ?? 9;
        $ob = $order[$b['status']] ?? 9;
        if ($oa !== $ob) return $oa <=> $ob;
        return strcmp((string)$a['bare'], (string)$b['bare']);
    });

    $out = [
        'ok' => true,
        'generated_at' => time(),
        'source' => $source,
        'suffixes' => $suffixes,
        'shops' => $shopsMeta,
        'woo_cfg' => $wooCfg,
        'bsl_cfg' => $bslCfg,
        'summary' => $sum,
        'rows' => $rows,
        'woo_error' => $wooErr,
        'bsl_error' => $bslErr,
        'woo_count' => count($wooRows),
        'profile_count' => count($profiles),
        'row_count' => count($rows),
    ];
    matrixProgress([
        'phase' => 'save', 'pct' => 95,
        'log_add' => ['💾 ذخیره ' . count($rows) . ' ردیف روی سرور...'],
    ]);
    if (!matrixResultSave($out)) {
        $out['ok'] = false;
        $out['error'] = 'نوشتن فایل نتیجه ناموفق بود (فضا/مجوز؟)';
        matrixProgress(['running' => false, 'done' => true, 'error' => $out['error'], 'pct' => 100,
            'log_add' => ['❌ ' . $out['error']]]);
        return $out;
    }
    matrixProgress([
        'running' => false, 'done' => true, 'error' => '', 'pct' => 100,
        'phase' => 'done', 'summary' => $sum, 'row_count' => count($rows),
        'checkpoint' => null, 'finished_at' => time(),
        'log_add' => [
            '✅ جدول آماده: ' . count($rows) . ' ردیف',
            '📊 یکسان ' . (int)$sum['ok'] . ' · مغایرت ' . (int)$sum['price_mismatch']
                . ' · نیست در WC ' . (int)$sum['missing_woo'],
        ],
    ]);
    return $out;
}

/**
 * اجرای جاب ساخت ماتریس با قفل فایل.
 * background=true → پاسخ زود و ادامه در همان درخواست پس از flush (مثل recon)
 */

/* =====================================================================
 *  v10.117: اصلاح مغایرت از روی جدول مقایسه (سرورساید + لاگ زنده)
 *  start:  ?sync_matrix_fix_start=1  (یا POST action=)
 *  status: ?sync_matrix_fix_status=1
 *  stop:   ?sync_matrix_fix_stop=1
 *  از نتیجهٔ sync_matrix_result.json می‌خواند و قیمت WC/غرفه‌ها را
 *  طبق «انتظار» اصلاح می‌کند؛ هر ردیف همان لحظه در فایل نتیجه به‌روز می‌شود.
 * ===================================================================== */

function matrixFixProgress(array $patch): void {
    $cur = localTaskStateRead(SYNC_MATRIX_FIX_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) {
            $log[] = ['t' => time(), 'm' => (string)$l];
        }
        if (count($log) > 400) $log = array_slice($log, -400);
        unset($patch['log_add']);
    }
    if (isset($patch['live_add']) && is_array($patch['live_add'])) {
        $live = is_array($cur['live'] ?? null) ? $cur['live'] : [];
        $live[] = $patch['live_add'];
        if (count($live) > 80) $live = array_slice($live, -80);
        $cur['live'] = $live;
        unset($patch['live_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log;
    $cur['ts'] = time();
    writeProgress(SYNC_MATRIX_FIX_PROGRESS_FILE, $cur);
}

function matrixFixProgressRead(): array {
    return localTaskStateRead(SYNC_MATRIX_FIX_PROGRESS_FILE, []);
}

function matrixFixStopRequested(): bool {
    return is_file(SYNC_MATRIX_FIX_STOP_FILE);
}

function matrixFixStopClear(): void {
    @unlink(SYNC_MATRIX_FIX_STOP_FILE);
}

/** به‌روزرسانی یک ردیف در فایل نتیجهٔ ماتریس (با کلید bare) */
function matrixResultPatchRow(string $bare, array $rowPatch, ?array $summaryPatch = null): bool {
    $data = matrixResultLoad();
    if (!$data || empty($data['rows']) || !is_array($data['rows'])) return false;
    $found = false;
    foreach ($data['rows'] as $i => $r) {
        if (!is_array($r)) continue;
        if ((string)($r['bare'] ?? '') !== $bare) continue;
        $data['rows'][$i] = array_merge($r, $rowPatch);
        /* nested shops merge — null cell = حذف */
        if (array_key_exists('shops', $rowPatch) && is_array($rowPatch['shops'])) {
            $shops = is_array($r['shops'] ?? null) ? $r['shops'] : [];
            /* اگر کلیدها فقط عددی/vid هستند merge؛ اگر جایگزینی کامل لیست خالی/بازنویسی */
            foreach ($rowPatch['shops'] as $vid => $cell) {
                if ($cell === null) {
                    unset($shops[$vid]);
                } elseif (is_array($cell) && isset($shops[$vid]) && is_array($shops[$vid])) {
                    $shops[$vid] = array_merge($shops[$vid], $cell);
                } else {
                    $shops[$vid] = $cell;
                }
            }
            $data['rows'][$i]['shops'] = $shops;
        }
        if (array_key_exists('woo', $rowPatch)) {
            if ($rowPatch['woo'] === null) {
                $data['rows'][$i]['woo'] = null;
            } elseif (is_array($rowPatch['woo'])) {
                $w0 = is_array($r['woo'] ?? null) ? $r['woo'] : [];
                $data['rows'][$i]['woo'] = array_merge($w0, $rowPatch['woo']);
            }
        }
        $found = true;
        break;
    }
    if (!$found) return false;
    if (is_array($summaryPatch)) {
        $sum = is_array($data['summary'] ?? null) ? $data['summary'] : [];
        $data['summary'] = array_merge($sum, $summaryPatch);
    }
    $data['fix_at'] = time();
    return matrixResultSave($data);
}

/**
 * ووکامرس: قیمت را با API یا مستقیم DB تنظیم می‌کند.
 * $priceToman عدد صحیح تومان.
 */
function matrixFixWooPrice(array $cn, int $pid, int $priceToman): array {
    if ($pid <= 0 || $priceToman <= 0) {
        return ['ok' => false, 'error' => 'شناسه/قیمت نامعتبر'];
    }
    /* direct when in WP */
    if (function_exists('wooDirectAvailable') && wooDirectAvailable() && function_exists('wc_get_product')) {
        try {
            $p = wc_get_product($pid);
            if ($p && is_object($p)) {
                $p->set_regular_price((string)$priceToman);
                if (method_exists($p, 'set_price')) $p->set_price((string)$priceToman);
                $p->save();
                return ['ok' => true, 'via' => 'direct', 'id' => $pid, 'price' => $priceToman];
            }
        } catch (Throwable $e) {
            /* fall through to API */
        }
    }
    $w = $cn['woocommerce'] ?? [];
    if (empty($w['store_url']) || empty($w['consumer_key'])) {
        return ['ok' => false, 'error' => 'تنظیمات WC ناقص و direct در دسترس نیست'];
    }
    $r = wooEditProduct($w, $pid, [
        'regular_price' => (string)$priceToman,
        'price' => (string)$priceToman,
    ]);
    if (!empty($r['ok'])) return ['ok' => true, 'via' => 'api', 'id' => $pid, 'price' => $priceToman];
    return ['ok' => false, 'error' => (string)($r['error'] ?? ('HTTP ' . ($r['code'] ?? 0))), 'code' => (int)($r['code'] ?? 0)];
}

/** باسلام: قیمت تومان → ریال ×۱۰ */
function matrixFixBslPrice(string $tk, int $vid, int $pid, int $priceToman): array {
    if ($pid <= 0 || $priceToman <= 0 || $tk === '') {
        return ['ok' => false, 'error' => 'ورودی ناقص'];
    }
    $rial = $priceToman * 10;
    $bu = ['primary_price' => $rial];
    $r = bslReq($tk, 'PATCH', 'products/' . $pid, $bu);
    if ((int)($r['code'] ?? 0) === 404 && $vid > 0) {
        $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $pid, $bu);
    }
    if (in_array((int)($r['code'] ?? 0), [401, 403, 422], true) && $vid > 0 && empty($r['ok'])) {
        $r2 = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $pid, $bu);
        if (!empty($r2['ok']) || (int)($r2['code'] ?? 0) !== 404) $r = $r2;
    }
    if (!empty($r['ok'])) return ['ok' => true, 'id' => $pid, 'price' => $priceToman, 'rial' => $rial];
    return ['ok' => false, 'error' => (string)($r['error'] ?? ('HTTP ' . ($r['code'] ?? 0))), 'code' => (int)($r['code'] ?? 0)];
}

/**
 * جمع‌آوری کارهای اصلاح از ردیف‌های ماتریس.
 * فقط مغایرت قیمت روی مقصدهایی که محصول دارند (id موجود).
 * $scope: all|woo|bsl
 */
/**
 * v10.118: کارهای اصلاح از ماتریس —
 *   price_woo / price_bsl  — اصلاح قیمت
 *   send_woo / send_bsl    — در پروفایل هست، در مقصد نیست → ارسال
 *   del_woo / del_bsl      — در پروفایل نیست، در مقصد هست → حذف/بایگانی
 */
function matrixFixCollectJobs(array $data, string $scope = 'all'): array {
    $jobs = [];
    $shops = is_array($data['shops'] ?? null) ? $data['shops'] : [];
    /* اگر meta غرفه خالی است، از خود ردیف‌ها vendor_id را دربیاور */
    if (!$shops) {
        $seen = [];
        foreach ((array)($data['rows'] ?? []) as $r) {
            if (!is_array($r) || empty($r['shops']) || !is_array($r['shops'])) continue;
            foreach ($r['shops'] as $vk => $cell) {
                $vid = (int)$vk;
                if ($vid <= 0 && is_array($cell)) $vid = (int)($cell['vendor_id'] ?? 0);
                if ($vid <= 0 || isset($seen[$vid])) continue;
                $seen[$vid] = true;
                $shops[] = [
                    'vendor_id' => $vid,
                    'name' => (string)(is_array($cell) ? ($cell['shop_name'] ?? ('#' . $vid)) : ('#' . $vid)),
                ];
            }
        }
    }
    /* اگر هنوز خالی و scope bsl/all، از connections */
    if (!$shops && ($scope === 'all' || $scope === 'bsl') && function_exists('bslAllShops') && function_exists('loadConnections')) {
        try {
            foreach (bslAllShops(loadConnections()) as $sh) {
                if (!is_array($sh)) continue;
                $vid = (int)($sh['vendor_id'] ?? 0);
                if ($vid <= 0) continue;
                $shops[] = ['vendor_id' => $vid, 'name' => (string)($sh['shop_name'] ?? $sh['name'] ?? ('#' . $vid))];
            }
        } catch (Throwable $e) { /* ignore */ }
    }
    foreach ((array)($data['rows'] ?? []) as $ri => $r) {
        if (!is_array($r)) continue;
        $bare = (string)($r['bare'] ?? '');
        if ($bare === '' || str_starts_with($bare, '__report_') || !empty($r['is_report'])) continue;
        $title = (string)($r['title'] ?? $bare);
        $flags = array_map('strval', (array)($r['flags'] ?? []));
        $status = (string)($r['status'] ?? '');
        $hits = (int)($r['profile_hits'] ?? 0);
        $pkey = trim((string)($r['profile_key'] ?? ''));
        $prodKey = trim((string)($r['key'] ?? ''));
        $profName = trim((string)($r['profile'] ?? ''));
        $profPrice = (int)($r['profile_price'] ?? 0);
        $hasProf = $hits > 0 || $profPrice > 0 || $pkey !== '' || $profName !== '';
        /* اگر status صریحاً only_dest است، مبدأ نیست */
        if ($status === 'only_dest') $hasProf = false;
        if (in_array($status, ['only_profile', 'missing'], true)) $hasProf = true;

        /* ---- Woo ---- */
        if ($scope === 'all' || $scope === 'woo') {
            $wooRaw = $r['woo'] ?? null;
            $woo = (is_array($wooRaw) && ((int)($wooRaw['id'] ?? 0) > 0 || (int)($wooRaw['price'] ?? 0) > 0 || trim((string)($wooRaw['title'] ?? '')) !== ''))
                ? $wooRaw : null;
            $wooTone = (string)($r['woo_tone'] ?? '');
            $expect = (int)($r['woo_expect'] ?? 0);
            if ($expect <= 0 && $profPrice > 0) $expect = $profPrice;
            $wid = $woo ? (int)($woo['id'] ?? 0) : 0;
            $got = $woo ? (int)($woo['price'] ?? 0) : 0;
            $flagMissWoo = in_array('missing_woo', $flags, true) || $wooTone === 'missing_dst'
                || in_array($status, ['missing', 'only_profile'], true);
            $flagExtraWoo = in_array('extra_woo', $flags, true) || $wooTone === 'extra' || ($status === 'only_dest' && $woo);
            $flagPrice = in_array('price_mismatch', $flags, true)
                || in_array($wooTone, ['bad', 'warn'], true)
                || $status === 'mismatch';

            if ($hasProf && !$woo) {
                $jobs[] = [
                    'kind' => 'send_woo', 'bare' => $bare, 'title' => $title,
                    'row_i' => $ri, 'profile_key' => $pkey, 'product_key' => $prodKey,
                    'expect' => $expect, 'why' => 'missing_woo',
                ];
            } elseif ($hasProf && $woo && $wid > 0 && $expect > 0 && $got !== $expect) {
                $need = $flagPrice || ($got > 0 && abs($got - $expect) / max($expect, 1) > 0.01)
                    || ($got <= 0 && $expect > 0);
                if ($need) {
                    $jobs[] = [
                        'kind' => 'price_woo', 'bare' => $bare, 'title' => $title,
                        'row_i' => $ri, 'id' => $wid, 'from' => $got, 'to' => $expect,
                        'why' => 'price_woo',
                    ];
                }
            } elseif (!$hasProf && $woo && $wid > 0) {
                $jobs[] = [
                    'kind' => 'del_woo', 'bare' => $bare, 'title' => $title,
                    'row_i' => $ri, 'id' => $wid, 'why' => 'extra_woo',
                ];
            } elseif ($hasProf && $flagMissWoo && !$woo) {
                /* already covered */
            }
        }

        /* ---- BSL shops ---- */
        if ($scope === 'all' || $scope === 'bsl') {
            $rowShops = is_array($r['shops'] ?? null) ? $r['shops'] : [];
            foreach ($shops as $sm) {
                if (!is_array($sm)) continue;
                $vid = (int)($sm['vendor_id'] ?? 0);
                if ($vid <= 0) continue;
                $sname = (string)($sm['name'] ?? $sm['shop_name'] ?? ('#' . $vid));
                $cell = null;
                if (isset($rowShops[$vid]) && is_array($rowShops[$vid])) $cell = $rowShops[$vid];
                elseif (isset($rowShops[(string)$vid]) && is_array($rowShops[(string)$vid])) $cell = $rowShops[(string)$vid];
                /* بعضی JSONها کلید را به‌صورت لیست نگه می‌دارند */
                if ($cell === null) {
                    foreach ($rowShops as $k => $c) {
                        if (!is_array($c)) continue;
                        if ((int)$k === $vid || (int)($c['vendor_id'] ?? 0) === $vid) { $cell = $c; break; }
                    }
                }
                $hasCell = is_array($cell) && ((int)($cell['id'] ?? 0) > 0 || (int)($cell['price'] ?? 0) > 0);

                if ($hasProf && !$hasCell) {
                    $jobs[] = [
                        'kind' => 'send_bsl', 'bare' => $bare, 'title' => $title,
                        'row_i' => $ri, 'vendor_id' => $vid, 'shop_name' => $sname,
                        'profile_key' => $pkey, 'product_key' => $prodKey,
                        'expect' => (int)($r['bsl_expect'] ?? $profPrice),
                        'why' => 'missing_bsl',
                    ];
                } elseif ($hasProf && $hasCell) {
                    $expect = (int)($cell['expect'] ?? ($r['bsl_expect'] ?? 0));
                    if ($expect <= 0) $expect = (int)($r['bsl_expect'] ?? $profPrice);
                    $got = (int)($cell['price'] ?? 0);
                    $bid = (int)($cell['id'] ?? 0);
                    $tone = (string)($cell['tone'] ?? '');
                    $need = in_array($tone, ['bad', 'warn'], true)
                        || in_array('price_mismatch', $flags, true)
                        || ($got > 0 && $expect > 0 && abs($got - $expect) / max($expect, 1) > 0.01)
                        || ($got <= 0 && $expect > 0 && $bid > 0);
                    if ($need && $bid > 0 && $expect > 0 && $got !== $expect) {
                        $jobs[] = [
                            'kind' => 'price_bsl', 'bare' => $bare, 'title' => $title,
                            'row_i' => $ri, 'id' => $bid, 'vendor_id' => $vid,
                            'shop_name' => $sname, 'from' => $got, 'to' => $expect,
                            'why' => 'price_bsl',
                        ];
                    }
                } elseif (!$hasProf && $hasCell) {
                    $bid = (int)($cell['id'] ?? 0);
                    if ($bid > 0) {
                        $jobs[] = [
                            'kind' => 'del_bsl', 'bare' => $bare, 'title' => $title,
                            'row_i' => $ri, 'id' => $bid, 'vendor_id' => $vid,
                            'shop_name' => $sname, 'why' => 'extra_bsl',
                        ];
                    }
                }
            }
        }
    }
    $order = [
        'del_woo' => 0, 'del_bsl' => 1,
        'price_woo' => 2, 'price_bsl' => 3,
        'send_woo' => 4, 'send_bsl' => 5,
    ];
    usort($jobs, function ($a, $b) use ($order) {
        $oa = $order[$a['kind'] ?? ''] ?? 9;
        $ob = $order[$b['kind'] ?? ''] ?? 9;
        if ($oa !== $ob) return $oa <=> $ob;
        return strcmp((string)($a['bare'] ?? ''), (string)($b['bare'] ?? ''));
    });
    return $jobs;
}

/** پیدا کردن محصول پروفایل با bare title / key */
function matrixFixFindProduct(string $bare, string $profileKey = '', string $productKey = ''): ?array {
    $suffixes = function_exists('matrixCollectSuffixes') ? matrixCollectSuffixes() : [];
    $profiles = loadProfiles();
    $tryList = [];
    if ($profileKey !== '' && isset($profiles[$profileKey])) {
        $tryList[$profileKey] = $profiles[$profileKey];
    } else {
        foreach ($profiles as $pk => $pr) {
            if (!is_array($pr)) continue;
            if ($profileKey !== '') {
                $nm = trim((string)($pr['name'] ?? $pk));
                if ($pk !== $profileKey && mb_strtolower($nm) !== mb_strtolower($profileKey)) continue;
            }
            $tryList[$pk] = $pr;
        }
        if (!$tryList) $tryList = $profiles;
    }
    foreach ($tryList as $pk => $profile) {
        if (!is_array($profile)) continue;
        $only = null;
        if ($productKey !== '') $only = [$productKey => true];
        $list = profileOrderedProducts($profile, $only, true);
        if ($productKey !== '' && !$list) {
            $list = profileOrderedProducts($profile, null, true);
        }
        foreach ($list as $p) {
            if (!is_array($p)) continue;
            if ($productKey !== '' && (string)($p['key'] ?? '') === $productKey) {
                return ['product' => $p, 'profile' => $profile, 'profile_key' => (string)$pk];
            }
            $b = matrixBareTitle((string)($p['title'] ?? ''), $suffixes);
            if ($b !== '' && $b === $bare) {
                return ['product' => $p, 'profile' => $profile, 'profile_key' => (string)$pk];
            }
        }
    }
    return null;
}

/** ساخت payload ووکامرس از محصول پروفایل */
function matrixFixBuildWooPayload(array $p, array $profile, array $cn): array {
    $w = $cn['woocommerce'] ?? [];
    $title = trim((string)($p['title'] ?? ''));
    $sfx = trim((string)($profile['titleSuffix'] ?? ''));
    if ($sfx === '') $sfx = trim((string)($cn['basalam']['title_suffix'] ?? ''));
    if ($sfx !== '' && mb_strpos($title, $sfx) === false) $title = trim($title . ' ' . $sfx);
    $price = (int)($p['final_price'] ?? 0);
    if ($price <= 0) $price = profileFinalPrice($profile, (string)($p['price'] ?? ''));
    $wooCfg = function_exists('destPriceCfg') ? destPriceCfg($cn, 'woocommerce') : ['mode' => 'none'];
    if ($price > 0 && ($wooCfg['mode'] ?? 'none') !== 'none' && function_exists('destAdjustPrice')) {
        $price = destAdjustPrice($price, $wooCfg);
    }
    $stock = function_exists('effectiveStock')
        ? effectiveStock($p, (int)($w['stock_quantity'] ?? 10))
        : (int)($w['stock_quantity'] ?? 10);
    $wp = [
        'name' => mb_substr($title, 0, 200),
        'type' => 'simple',
        'regular_price' => (string)max(0, $price),
        'status' => (string)($w['default_status'] ?? 'publish'),
        'manage_stock' => !empty($w['manage_stock']),
        'stock_quantity' => $stock,
    ];
    if (!empty($p['shortDesc']) || !empty($p['short_desc'])) {
        $wp['short_description'] = (string)($p['shortDesc'] ?? $p['short_desc']);
    }
    if (!empty($p['longDesc']) || !empty($p['long_desc'])) {
        $wp['description'] = (string)($p['longDesc'] ?? $p['long_desc']);
    }
    $img = trim((string)($p['image'] ?? ''));
    if ($img !== '' && preg_match('~^https?://~i', $img)) {
        $wp['images'] = [['src' => $img]];
    }
    $cat = (int)($profile['wooCategoryId'] ?? 0);
    if ($cat <= 0) $cat = (int)($w['default_category'] ?? 0);
    if ($cat > 0) $wp['categories'] = [['id' => $cat]];
    return $wp;
}

function matrixFixSendWoo(array $cn, array $found, int $expect = 0): array {
    $p = $found['product'];
    $profile = $found['profile'];
    $w = $cn['woocommerce'] ?? [];
    $wp = matrixFixBuildWooPayload($p, $profile, $cn);
    if ($expect > 0) $wp['regular_price'] = (string)$expect;
    $key = (string)($p['key'] ?? '');
    if (function_exists('wooUpsertWithMode')) {
        $r = wooUpsertWithMode($w, $wp, null, $key);
    } else {
        $r = ['ok' => false, 'error' => 'wooUpsertWithMode نیست'];
    }
    $id = (int)($r['body']['id'] ?? ($r['id'] ?? 0));
    if (!empty($r['ok']) && $id <= 0 && !empty($r['body']) && is_array($r['body'])) {
        $id = (int)($r['body']['id'] ?? 0);
    }
    /* direct may return id differently */
    if (!empty($r['ok']) && $id <= 0) $id = (int)($r['product_id'] ?? $r['id'] ?? 0);
    if (!empty($r['ok'])) {
        $price = (int)preg_replace('~\D~', '', (string)($wp['regular_price'] ?? '0'));
        return ['ok' => true, 'id' => $id, 'price' => $price, 'via' => (string)($r['via'] ?? 'api'), 'action' => (string)($r['action'] ?? 'upsert')];
    }
    return ['ok' => false, 'error' => (string)($r['error'] ?? ($r['message'] ?? 'ارسال WC ناموفق'))];
}

function matrixFixSendBsl(array $cn, array $found, int $vid, string $tok, int $expect = 0): array {
    $p = $found['product'];
    $profile = $found['profile'];
    /* اگر expect از جدول داریم، final_price را همسو کن تا bslUpsert همان را بفرستد */
    if ($expect > 0) {
        $p = array_merge($p, ['final_price' => $expect, 'price' => (string)$expect]);
    }
    $shop = null;
    foreach (function_exists('bslAllShops') ? bslAllShops($cn) : [] as $sh) {
        if ((int)($sh['vendor_id'] ?? 0) === $vid) { $shop = $sh; break; }
    }
    if (!$shop) {
        $shop = ['vendor_id' => $vid, 'token' => $tok, 'shop_name' => 'غرفه ' . $vid];
    } else {
        $shop['token'] = $tok !== '' ? $tok : (string)($shop['token'] ?? '');
    }
    $b = $cn['basalam'] ?? [];
    $opts = [
        'profile' => $profile,
        'round' => (int)($b['price_round'] ?? 0),
        'stock' => (int)($b['stock'] ?? 10),
        'preparation_days' => (int)($b['preparation_days'] ?? 3),
        'weight' => (int)($b['weight'] ?? 500),
        'package_weight' => (int)($b['package_weight'] ?? 0),
        'category_id' => (int)($profile['bslCategoryId'] ?? ($b['category_id'] ?? 0)),
        'fallback_cat_ids' => array_values(array_filter(array_map('intval', (array)($b['fallback_cat_ids'] ?? [])))),
        'auto_category' => !empty($b['auto_category']),
    ];
    if (!function_exists('bslUpsertToShop')) {
        return ['ok' => false, 'error' => 'bslUpsertToShop نیست'];
    }
    $r = bslUpsertToShop($p, $shop, $opts);
    if (!empty($r['ok'])) {
        $id = (int)($r['id'] ?? 0);
        $price = 0;
        /* read expect from product */
        $profP = (int)($p['final_price'] ?? 0);
        if ($profP <= 0) $profP = profileFinalPrice($profile, (string)($p['price'] ?? ''));
        $bslCfg = function_exists('destPriceCfg') ? destPriceCfg($cn, 'basalam') : ['mode' => 'none'];
        if ($profP > 0 && ($bslCfg['mode'] ?? 'none') !== 'none' && function_exists('destAdjustPrice')) {
            $profP = destAdjustPrice($profP, $bslCfg);
        }
        if ($profP > 0 && function_exists('bslShopPriceFor')) {
            $adj = bslShopPriceFor($profP, $shop, (int)($bslCfg['round'] ?? 0));
            if (!empty($adj['price'])) $price = (int)$adj['price'];
        }
        if ($price <= 0) $price = $profP;
        return ['ok' => true, 'id' => $id, 'price' => $price, 'action' => (string)($r['action'] ?? 'upsert')];
    }
    return ['ok' => false, 'error' => (string)($r['error'] ?? 'ارسال باسلام ناموفق')];
}

function matrixFixDelWoo(array $cn, int $pid): array {
    if ($pid <= 0) return ['ok' => false, 'error' => 'id نامعتبر'];
    /* direct trash */
    if (function_exists('wooDirectAvailable') && wooDirectAvailable() && function_exists('wp_trash_post')) {
        try {
            $r = wp_trash_post($pid);
            if ($r) return ['ok' => true, 'via' => 'direct', 'id' => $pid];
        } catch (Throwable $e) { /* api */ }
    }
    $w = $cn['woocommerce'] ?? [];
    if (empty($w['store_url'])) return ['ok' => false, 'error' => 'WC تنظیمات ناقص'];
    $r = wooDeleteProduct($w, $pid, false);
    if (!empty($r['ok'])) return ['ok' => true, 'via' => 'api', 'id' => $pid];
    return ['ok' => false, 'error' => (string)($r['error'] ?? ('HTTP ' . ($r['code'] ?? 0)))];
}

function matrixFixDelBsl(array $cn, int $pid, int $vid): array {
    if ($pid <= 0) return ['ok' => false, 'error' => 'id نامعتبر'];
    if (function_exists('bslArchiveSmart')) {
        $r = bslArchiveSmart($cn, $pid, $vid);
        if (!empty($r['ok'])) return ['ok' => true, 'id' => $pid, 'vendor_id' => (int)($r['vendor_id'] ?? $vid)];
        return ['ok' => false, 'error' => (string)($r['msg'] ?? ('HTTP ' . ($r['code'] ?? 0)))];
    }
    $tok = function_exists('bslShopTokenFor') ? bslShopTokenFor($cn, $vid) : '';
    if ($tok === '') $tok = trim((string)($cn['basalam']['token'] ?? ''));
    if ($tok === '' || !function_exists('bslArchiveProduct')) {
        return ['ok' => false, 'error' => 'آرشیو باسلام در دسترس نیست'];
    }
    $r = bslArchiveProduct($tok, $vid, $pid);
    if (!empty($r['ok'])) return ['ok' => true, 'id' => $pid];
    return ['ok' => false, 'error' => (string)($r['error'] ?? 'آرشیو ناموفق')];
}

/** جزئیات استانداردِ یک اصلاح برای شمارنده‌ها و مودالِ مقصد */
function matrixFixDetail(string $target, string $destination, string $kind, string $title,
                         bool $ok, string $label, int $id = 0, array $extra = []): array {
    return array_merge([
        'ok' => $ok, 'fixed' => $ok, 'target' => $target,
        'destination' => $destination, 'kind' => $kind,
        'title' => $title, 'id' => $id, 'label' => $label,
    ], $extra);
}

/** افزودن/به‌روزرسانی دو ردیف گزارش در انتهای جدول */
function matrixFixAppendReportRows(array $stats): void {
    $data = matrixResultLoad();
    if (!$data || !isset($data['rows']) || !is_array($data['rows'])) return;
    $rows = [];
    foreach ($data['rows'] as $r) {
        if (!is_array($r)) continue;
        if (!empty($r['is_report']) || str_starts_with((string)($r['bare'] ?? ''), '__report_')) continue;
        $rows[] = $r;
    }
    $ok = (int)($stats['ok'] ?? 0);
    $fail = (int)($stats['fail'] ?? 0);
    $total = (int)($stats['total'] ?? 0);
    $sent = (int)($stats['sent'] ?? 0);
    $del = (int)($stats['deleted'] ?? 0);
    $priced = (int)($stats['priced'] ?? 0);
    $scope = (string)($stats['scope'] ?? 'all');
    $stopped = !empty($stats['stopped']);
    $details = is_array($stats['details'] ?? null) ? $stats['details'] : [];
    $lines = [];
    foreach (array_slice($details, -40) as $d) {
        if (!is_array($d)) continue;
        $mark = !empty($d['ok']) ? '✅' : '❌';
        $lines[] = $mark . ' ' . (string)($d['label'] ?? $d['title'] ?? '');
    }
    $summaryTxt = ($stopped ? '⏹ متوقف — ' : '✅ تمام — ')
        . "موفق {$ok} · ناموفق {$fail} از {$total}"
        . " · 💰قیمت {$priced} · 📤ارسال {$sent} · 🗑حذف {$del}"
        . ' · محدوده ' . $scope;
    /* خلاصهٔ مقصدها داخل خودِ ردیف گزارش هم بماند؛ UI جدید آن را به
       شمارندهٔ کلیک‌پذیر تبدیل می‌کند و UIهای قدیمی دست‌خالی نمی‌مانند. */
    $destinationLines = [];
    $destinationCounts = [];
    foreach ($details as $d) {
        if (!is_array($d) || empty($d['ok']) || empty($d['target'])) continue;
        $dest = (string)($d['destination'] ?? ($d['target'] === 'woo' ? 'ووکامرس' : 'باسلام'));
        $destinationCounts[$dest] = (int)($destinationCounts[$dest] ?? 0) + 1;
    }
    foreach ($destinationCounts as $dest => $nDest) {
        $destinationLines[] = '📍 ' . $dest . ': ' . $nDest . ' اصلاح موفق';
    }

    $rowWork = [
        'bare' => '__report_work__',
        'title' => '📋 گزارش کار انجام‌شده',
        'is_report' => true,
        'report_type' => 'work',
        'profile' => '—',
        'profile_key' => '',
        'profile_hits' => 0,
        'src_price' => 0,
        'profile_price' => 0,
        'woo_expect' => 0,
        'bsl_expect' => 0,
        'woo' => null,
        'shops' => [],
        'woo_tone' => 'na',
        'status' => 'report',
        'flags' => ['report'],
        'report_text' => $summaryTxt,
        'report_lines' => array_merge([
            '💰 اصلاح قیمت: ' . $priced,
            '📤 ارسال (در مقصد نبود): ' . $sent,
            '🗑 حذف/بایگانی (فقط مقصد): ' . $del,
            'محدوده: ' . $scope,
            'زمان: ' . date('Y-m-d H:i:s', (int)($stats['at'] ?? time())),
        ], $destinationLines),
        'fix_at' => time(),
    ];
    $rowResult = [
        'bare' => '__report_result__',
        'title' => '📊 نتیجهٔ عملیات',
        'is_report' => true,
        'report_type' => 'result',
        'profile' => '—',
        'profile_key' => '',
        'profile_hits' => 0,
        'src_price' => 0,
        'profile_price' => 0,
        'woo_expect' => 0,
        'bsl_expect' => 0,
        'woo' => null,
        'shops' => [],
        'woo_tone' => 'na',
        'status' => 'report',
        'flags' => ['report'],
        'report_text' => $summaryTxt,
        'report_lines' => array_merge($destinationLines, $lines ?: ['موردی ثبت نشد']),
        'report_ok' => $ok,
        'report_fail' => $fail,
        'report_total' => $total,
        'fix_at' => time(),
    ];
    $rows[] = $rowWork;
    $rows[] = $rowResult;
    $data['rows'] = $rows;
    $data['row_count'] = count($rows);
    $data['fix_stats'] = $stats;
    $data['fix_at'] = time();
    $data['reports'] = [$rowWork, $rowResult];
    $okSave = matrixResultSave($data);
    if (!$okSave) {
        matrixFixProgress(['log_add' => ['❌ ذخیرهٔ ردیف گزارش در فایل نتیجه ناموفق بود']]);
    } else {
        matrixFixProgress(['log_add' => ['💾 گزارش در فایل نتیجه ذخیره شد (' . count($rows) . ' ردیف)']]);
    }
}

/**
 * اجرای کامل اصلاح از روی ماتریس — سرورساید با progress/log زنده.
 * v10.118: قیمت + ارسال missing + حذف extra + دو ردیف گزارش.
 */
function matrixFixRun(array $opts = []): array {
    @set_time_limit(0);
    @ignore_user_abort(true);
    /* stop را caller پس از گرفتنِ lockِ واقعیِ همین کار مصرف می‌کند؛ این
       تابع از recon_auto هم صدا زده می‌شود و نباید در شروع، درخواستِ تازهٔ
       کاربر را بین lock و اولینِ probe پاک کند. */
    $scope = (string)($opts['scope'] ?? 'all');
    if (!in_array($scope, ['all', 'woo', 'bsl'], true)) $scope = 'all';
    $delayMs = max(50, min(2000, (int)($opts['delay_ms'] ?? 180)));
    $source = (string)($opts['source'] ?? 'manual');
    $fixCp = is_array($opts['checkpoint'] ?? null) ? $opts['checkpoint'] : [];
    $doneJobs = array_values(array_unique(array_map('strval', (array)($fixCp['done_jobs'] ?? []))));
    $doneJobSet = $doneJobs ? array_fill_keys($doneJobs, true) : [];
    $fixStartedAt = (int)($fixCp['started_at'] ?? time());
    $jobKey = static function (array $j): string {
        return (string)($j['kind'] ?? '') . '|' . (string)($j['bare'] ?? '') . '|'
            . (int)($j['id'] ?? 0) . '|' . (int)($j['vendor_id'] ?? 0);
    };

    $data = matrixResultLoad();
    if (!$data || empty($data['rows'])) {
        matrixFixProgress([
            'running' => false, 'done' => true, 'error' => 'جدول مقایسه موجود نیست — اول بسازید',
            'pct' => 100, 'log_add' => ['❌ جدول مقایسه روی سرور نیست'],
        ]);
        return ['ok' => false, 'error' => 'no_matrix'];
    }

    $jobs = matrixFixCollectJobs($data, $scope);
    $total = count($jobs);
    $nPrice = $nSend = $nDel = 0;
    foreach ($jobs as $j) {
        $k = (string)($j['kind'] ?? '');
        if (str_starts_with($k, 'price_')) $nPrice++;
        elseif (str_starts_with($k, 'send_')) $nSend++;
        elseif (str_starts_with($k, 'del_')) $nDel++;
    }
    matrixFixProgress([
        'running' => true, 'done' => false, 'error' => '', 'pct' => 1,
        'phase' => 'start', 'started_at' => $fixStartedAt, 'source' => $source,
        'scope' => $scope, 'delay_ms' => $delayMs, 'job' => 'fix',
        'total' => $total, 'cur' => 0, 'ok_n' => (int)($fixCp['ok_n'] ?? 0),
        'fail_n' => (int)($fixCp['fail_n'] ?? 0), 'skip_n' => (int)($fixCp['skip_n'] ?? 0),
        'sent_n' => (int)($fixCp['sent_n'] ?? 0), 'del_n' => (int)($fixCp['del_n'] ?? 0),
        'price_n' => (int)($fixCp['price_n'] ?? 0), 'done_jobs' => $doneJobs,
        'checkpoint' => ['scope' => $scope, 'done_jobs' => $doneJobs, 'started_at' => $fixStartedAt,
            'ok_n' => (int)($fixCp['ok_n'] ?? 0), 'fail_n' => (int)($fixCp['fail_n'] ?? 0),
            'sent_n' => (int)($fixCp['sent_n'] ?? 0), 'del_n' => (int)($fixCp['del_n'] ?? 0),
            'price_n' => (int)($fixCp['price_n'] ?? 0)],
        'live' => [],
        'log_add' => array_merge([
            '🔧 شروع مغایرت‌گیری کامل از جدول — محدوده: ' . $scope,
            '📋 ' . $total . ' کار: 💰' . $nPrice . ' قیمت · 📤' . $nSend . ' ارسال · 🗑' . $nDel . ' حذف',
        ], array_map(function ($j) {
            return '  → ' . (string)($j['kind'] ?? '') . ' · ' . mb_substr((string)($j['title'] ?? $j['bare'] ?? ''), 0, 40);
        }, array_slice($jobs, 0, 8))),
    ]);

    if ($total === 0) {
        /* وقتی جدول کاری برای اجرا ندارد، فقط یک نتیجهٔ عادی ثبت کن؛ جزئیات
           داخلیِ ردیف‌ها و نمونه‌های تشخیصی نباید در گزارش کاربر پخش شوند. */
        $emptyMsg = 'هیچ مغایرت قابل اجرایی در جدول پیدا نشد';
        $stats = [
            'at' => time(), 'ok' => 0, 'fail' => 0, 'total' => 0,
            'sent' => 0, 'deleted' => 0, 'priced' => 0,
            'stopped' => false, 'scope' => $scope,
            'details' => [['ok' => true, 'label' => $emptyMsg]],
        ];
        matrixFixAppendReportRows($stats);
        matrixFixProgress([
            'running' => false, 'done' => true, 'pct' => 100, 'phase' => 'done',
            'ok_n' => 0, 'fail_n' => 0, 'total' => 0, 'cur' => 0,
            'sent_n' => 0, 'del_n' => 0, 'price_n' => 0,
            'log_add' => ['ℹ️ ' . $emptyMsg],
            'finished_at' => time(),
        ]);
        return ['ok' => true, 'total' => 0, 'ok_n' => 0, 'fail_n' => 0, 'empty' => true];
    }

    $cn = loadConnections();
    $shopTok = [];
    foreach (function_exists('bslAllShops') ? bslAllShops($cn) : [] as $sh) {
        if (!is_array($sh)) continue;
        $vid = (int)($sh['vendor_id'] ?? 0);
        $tok = trim((string)($sh['token'] ?? ($cn['basalam']['token'] ?? '')));
        if ($vid > 0 && $tok !== '') $shopTok[$vid] = $tok;
    }
    $defTok = trim((string)($cn['basalam']['token'] ?? ''));

    $okN = (int)($fixCp['ok_n'] ?? 0); $failN = (int)($fixCp['fail_n'] ?? 0);
    $sentN = (int)($fixCp['sent_n'] ?? 0); $delN = (int)($fixCp['del_n'] ?? 0); $priceN = (int)($fixCp['price_n'] ?? 0);
    $stopped = false;
    $details = [];

    foreach ($jobs as $ji => $job) {
        $jk = $jobKey($job);
        if (isset($doneJobSet[$jk])) continue;
        if (matrixFixStopRequested()) {
            $stopped = true;
            matrixFixProgress(['log_add' => ['⏹ توقف توسط کاربر']]);
            break;
        }
        $n = $ji + 1;
        $jobOk = false;
        $pct = 5 + (int)round(90 * $n / max(1, $total));
        $title = mb_substr((string)$job['title'], 0, 48);
        $bare = (string)$job['bare'];
        $kind = (string)($job['kind'] ?? '');

        /* ========== PRICE WOO ========== */
        if ($kind === 'price_woo') {
            $from = (int)$job['from']; $to = (int)$job['to'];
            matrixFixProgress([
                'phase' => 'woo_fix', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['💰 [' . $n . '/' . $total . '] WC قیمت · ' . $title
                    . ' — ' . number_format($from) . ' → ' . number_format($to)],
            ]);
            $res = matrixFixWooPrice($cn, (int)$job['id'], $to);
            if (!empty($res['ok'])) {
                $jobOk = true; $okN++; $priceN++;
                matrixResultPatchRow($bare, [
                    'woo' => ['price' => $to, 'id' => (int)$job['id']],
                    'woo_tone' => 'ok', 'fix_woo_at' => time(), 'fix_woo_ok' => true,
                ]);
                $details[] = matrixFixDetail('woo', 'ووکامرس', 'price', $title, true, 'قیمت WC · ' . $title . ' → ' . number_format($to), (int)$job['id'], ['from' => $from, 'to' => $to]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN, 'price_n' => $priceN,
                    'log_add' => ['  ✅ WC #' . (int)$job['id'] . ' · ' . number_format($to) . ' (' . ($res['via'] ?? '') . ')'],
                    'live_add' => ['ok' => true, 'kind' => 'price_woo', 'bare' => $bare, 'title' => $title, 'to' => $to, 't' => time()],
                ]);
            } else {
                $failN++;
                $err = (string)($res['error'] ?? 'خطا');
                $details[] = matrixFixDetail('woo', 'ووکامرس', 'price', $title, false, 'قیمت WC · ' . $title . ' — ' . $err, (int)$job['id'], ['error' => $err]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN,
                    'log_add' => ['  ❌ WC · ' . $title . ' — ' . $err],
                    'live_add' => ['ok' => false, 'kind' => 'price_woo', 'bare' => $bare, 'error' => $err, 't' => time()],
                ]);
            }
        }
        /* ========== PRICE BSL ========== */
        elseif ($kind === 'price_bsl') {
            $from = (int)$job['from']; $to = (int)$job['to'];
            $vid = (int)($job['vendor_id'] ?? 0);
            $tok = $shopTok[$vid] ?? $defTok;
            $sname = (string)($job['shop_name'] ?? ('#' . $vid));
            matrixFixProgress([
                'phase' => 'bsl_fix', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['💰 [' . $n . '/' . $total . '] ' . $sname . ' قیمت · ' . $title
                    . ' — ' . number_format($from) . ' → ' . number_format($to)],
            ]);
            if ($tok === '') {
                $failN++;
                $details[] = matrixFixDetail('bsl', $sname, 'price', $title, false, 'قیمت ' . $sname . ' · بدون توکن', (int)($job['id'] ?? 0), ['vendor_id' => $vid, 'error' => 'بدون توکن']);
                matrixFixProgress(['fail_n' => $failN, 'log_add' => ['  ❌ توکن غرفه نیست']]);
            } else {
                $res = matrixFixBslPrice($tok, $vid, (int)$job['id'], $to);
                if (!empty($res['ok'])) {
                    $jobOk = true; $okN++; $priceN++;
                    matrixResultPatchRow($bare, [
                        'shops' => [$vid => [
                            'price' => $to, 'price_rial' => $to * 10, 'tone' => 'ok',
                            'id' => (int)$job['id'], 'expect' => $to,
                        ]],
                        'fix_bsl_at' => time(),
                    ]);
                    $details[] = matrixFixDetail('bsl', $sname, 'price', $title, true, 'قیمت ' . $sname . ' · ' . $title . ' → ' . number_format($to), (int)$job['id'], ['vendor_id' => $vid, 'from' => $from, 'to' => $to]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN, 'price_n' => $priceN,
                        'log_add' => ['  ✅ ' . $sname . ' #' . (int)$job['id'] . ' · ' . number_format($to)],
                        'live_add' => ['ok' => true, 'kind' => 'price_bsl', 'bare' => $bare, 'shop' => $sname, 'to' => $to, 't' => time()],
                    ]);
                } else {
                    $failN++;
                    $err = (string)($res['error'] ?? 'خطا');
                    $details[] = matrixFixDetail('bsl', $sname, 'price', $title, false, 'قیمت ' . $sname . ' · ' . $title . ' — ' . $err, (int)$job['id'], ['vendor_id' => $vid, 'error' => $err]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN,
                        'log_add' => ['  ❌ ' . $sname . ' · ' . $err],
                        'live_add' => ['ok' => false, 'kind' => 'price_bsl', 'error' => $err, 't' => time()],
                    ]);
                }
            }
        }
        /* ========== SEND WOO ========== */
        elseif ($kind === 'send_woo') {
            matrixFixProgress([
                'phase' => 'woo_send', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['📤 [' . $n . '/' . $total . '] ارسال WC · ' . $title],
            ]);
            $found = matrixFixFindProduct($bare, (string)($job['profile_key'] ?? ''), (string)($job['product_key'] ?? ''));
            if (!$found) {
                $failN++;
                $details[] = matrixFixDetail('woo', 'ووکامرس', 'send', $title, false, 'ارسال WC · محصول در پروفایل پیدا نشد: ' . $title, 0, ['error' => 'در پروفایل پیدا نشد']);
                matrixFixProgress(['fail_n' => $failN, 'log_add' => ['  ❌ در پروفایل پیدا نشد']]);
            } else {
                $res = matrixFixSendWoo($cn, $found, (int)($job['expect'] ?? 0));
                if (!empty($res['ok'])) {
                    $jobOk = true; $okN++; $sentN++;
                    $id = (int)($res['id'] ?? 0);
                    $price = (int)($res['price'] ?? 0);
                    matrixResultPatchRow($bare, [
                        'woo' => ['id' => $id, 'price' => $price, 'status' => 'publish', 'title' => $title],
                        'woo_tone' => 'ok',
                        'status' => 'ok',
                        'fix_send_woo_at' => time(),
                    ]);
                    $details[] = matrixFixDetail('woo', 'ووکامرس', 'send', $title, true, 'ارسال WC · ' . $title . ($id ? (' #' . $id) : ''), $id, ['to' => $price]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN, 'sent_n' => $sentN,
                        'log_add' => ['  ✅ ارسال WC' . ($id ? (' #' . $id) : '') . ' · ' . ($res['via'] ?? '')],
                        'live_add' => ['ok' => true, 'kind' => 'send_woo', 'bare' => $bare, 'id' => $id, 't' => time()],
                    ]);
                } else {
                    $failN++;
                    $err = (string)($res['error'] ?? 'خطا');
                    $details[] = matrixFixDetail('woo', 'ووکامرس', 'send', $title, false, 'ارسال WC · ' . $title . ' — ' . $err, 0, ['error' => $err]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN,
                        'log_add' => ['  ❌ ارسال WC — ' . $err],
                        'live_add' => ['ok' => false, 'kind' => 'send_woo', 'error' => $err, 't' => time()],
                    ]);
                }
            }
        }
        /* ========== SEND BSL ========== */
        elseif ($kind === 'send_bsl') {
            $vid = (int)($job['vendor_id'] ?? 0);
            $tok = $shopTok[$vid] ?? $defTok;
            $sname = (string)($job['shop_name'] ?? ('#' . $vid));
            matrixFixProgress([
                'phase' => 'bsl_send', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['📤 [' . $n . '/' . $total . '] ارسال ' . $sname . ' · ' . $title],
            ]);
            $found = matrixFixFindProduct($bare, (string)($job['profile_key'] ?? ''), (string)($job['product_key'] ?? ''));
            if (!$found) {
                $failN++;
                $details[] = matrixFixDetail('bsl', $sname, 'send', $title, false, 'ارسال ' . $sname . ' · محصول پیدا نشد: ' . $title, 0, ['vendor_id' => $vid, 'error' => 'در پروفایل پیدا نشد']);
                matrixFixProgress(['fail_n' => $failN, 'log_add' => ['  ❌ در پروفایل پیدا نشد']]);
            } elseif ($tok === '') {
                $failN++;
                $details[] = matrixFixDetail('bsl', $sname, 'send', $title, false, 'ارسال ' . $sname . ' · بدون توکن', 0, ['vendor_id' => $vid, 'error' => 'بدون توکن']);
                matrixFixProgress(['fail_n' => $failN, 'log_add' => ['  ❌ توکن غرفه نیست']]);
            } else {
                $res = matrixFixSendBsl($cn, $found, $vid, $tok, (int)($job['expect'] ?? 0));
                if (!empty($res['ok'])) {
                    $jobOk = true; $okN++; $sentN++;
                    $id = (int)($res['id'] ?? 0);
                    $price = (int)($res['price'] ?? 0);
                    matrixResultPatchRow($bare, [
                        'shops' => [$vid => [
                            'id' => $id, 'price' => $price, 'price_rial' => $price * 10,
                            'tone' => 'ok', 'expect' => $price, 'shop_name' => $sname,
                            'title' => $title,
                        ]],
                        'fix_send_bsl_at' => time(),
                    ]);
                    $details[] = matrixFixDetail('bsl', $sname, 'send', $title, true, 'ارسال ' . $sname . ' · ' . $title . ($id ? (' #' . $id) : ''), $id, ['vendor_id' => $vid, 'to' => $price]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN, 'sent_n' => $sentN,
                        'log_add' => ['  ✅ ارسال ' . $sname . ($id ? (' #' . $id) : '') . ' · ' . ($res['action'] ?? '')],
                        'live_add' => ['ok' => true, 'kind' => 'send_bsl', 'bare' => $bare, 'shop' => $sname, 'id' => $id, 't' => time()],
                    ]);
                } else {
                    $failN++;
                    $err = (string)($res['error'] ?? 'خطا');
                    $details[] = matrixFixDetail('bsl', $sname, 'send', $title, false, 'ارسال ' . $sname . ' · ' . $title . ' — ' . $err, 0, ['vendor_id' => $vid, 'error' => $err]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN,
                        'log_add' => ['  ❌ ارسال ' . $sname . ' — ' . $err],
                        'live_add' => ['ok' => false, 'kind' => 'send_bsl', 'error' => $err, 't' => time()],
                    ]);
                }
            }
        }
        /* ========== DEL WOO ========== */
        elseif ($kind === 'del_woo') {
            matrixFixProgress([
                'phase' => 'woo_del', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['🗑 [' . $n . '/' . $total . '] حذف WC · ' . $title . ' #' . (int)$job['id']],
            ]);
            $res = matrixFixDelWoo($cn, (int)$job['id']);
            if (!empty($res['ok'])) {
                $jobOk = true; $okN++; $delN++;
                matrixResultPatchRow($bare, [
                    'woo' => null, 'woo_tone' => 'na',
                    'status' => 'only_dest_removed',
                    'fix_del_woo_at' => time(),
                    'flags' => [],
                ]);
                /* mark gone */
                $dataNow = matrixResultLoad();
                foreach ((array)($dataNow['rows'] ?? []) as $rr) {
                    if ((string)($rr['bare'] ?? '') !== $bare) continue;
                    $stillBsl = false;
                    foreach ((array)($rr['shops'] ?? []) as $c) if (!empty($c['id'])) $stillBsl = true;
                    matrixResultPatchRow($bare, [
                        'woo' => null,
                        'woo_tone' => 'na',
                        'status' => $stillBsl ? 'only_dest' : 'removed',
                        'title' => $title . ' (حذف‌شده از WC)',
                    ]);
                    break;
                }
                $details[] = matrixFixDetail('woo', 'ووکامرس', 'delete', $title, true, 'حذف WC · ' . $title . ' #' . (int)$job['id'], (int)$job['id']);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN, 'del_n' => $delN,
                    'log_add' => ['  ✅ حذف/زباله‌دان WC #' . (int)$job['id']],
                    'live_add' => ['ok' => true, 'kind' => 'del_woo', 'id' => (int)$job['id'], 't' => time()],
                ]);
            } else {
                $failN++;
                $err = (string)($res['error'] ?? 'خطا');
                $details[] = matrixFixDetail('woo', 'ووکامرس', 'delete', $title, false, 'حذف WC · ' . $title . ' — ' . $err, (int)$job['id'], ['error' => $err]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN,
                    'log_add' => ['  ❌ حذف WC — ' . $err],
                    'live_add' => ['ok' => false, 'kind' => 'del_woo', 'error' => $err, 't' => time()],
                ]);
            }
        }
        /* ========== DEL BSL ========== */
        elseif ($kind === 'del_bsl') {
            $vid = (int)($job['vendor_id'] ?? 0);
            $sname = (string)($job['shop_name'] ?? ('#' . $vid));
            matrixFixProgress([
                'phase' => 'bsl_del', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['🗑 [' . $n . '/' . $total . '] بایگانی ' . $sname . ' · ' . $title . ' #' . (int)$job['id']],
            ]);
            $res = matrixFixDelBsl($cn, (int)$job['id'], $vid);
            if (!empty($res['ok'])) {
                $jobOk = true; $okN++; $delN++;
                matrixResultPatchRow($bare, [
                    'shops' => [$vid => null],
                    'fix_del_bsl_at' => time(),
                ]);
                /* clear shop cell properly */
                $dataNow = matrixResultLoad();
                foreach ((array)($dataNow['rows'] ?? []) as $rr) {
                    if ((string)($rr['bare'] ?? '') !== $bare) continue;
                    $shops = is_array($rr['shops'] ?? null) ? $rr['shops'] : [];
                    unset($shops[$vid]);
                    matrixResultPatchRow($bare, [
                        'shops' => $shops,
                        'status' => empty($shops) && empty($rr['woo']) ? 'removed' : (string)($rr['status'] ?? 'only_dest'),
                        'title' => $title . ' (بایگانی از ' . $sname . ')',
                    ]);
                    break;
                }
                $details[] = matrixFixDetail('bsl', $sname, 'delete', $title, true, 'بایگانی ' . $sname . ' · ' . $title . ' #' . (int)$job['id'], (int)$job['id'], ['vendor_id' => $vid]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN, 'del_n' => $delN,
                    'log_add' => ['  ✅ بایگانی ' . $sname . ' #' . (int)$job['id']],
                    'live_add' => ['ok' => true, 'kind' => 'del_bsl', 'shop' => $sname, 'id' => (int)$job['id'], 't' => time()],
                ]);
            } else {
                $failN++;
                $err = (string)($res['error'] ?? 'خطا');
                $details[] = matrixFixDetail('bsl', $sname, 'delete', $title, false, 'بایگانی ' . $sname . ' · ' . $title . ' — ' . $err, (int)$job['id'], ['vendor_id' => $vid, 'error' => $err]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN,
                    'log_add' => ['  ❌ بایگانی ' . $sname . ' — ' . $err],
                    'live_add' => ['ok' => false, 'kind' => 'del_bsl', 'error' => $err, 't' => time()],
                ]);
            }
        }

        /* فقط کارِ واقعاً موفق از صفِ checkpoint حذف می‌شود؛ شکست
           باید در اجرای بعدی دوباره امتحان شود. */
        if ($jobOk) { $doneJobs[] = $jk; $doneJobSet[$jk] = true; }
        $incomplete = $stopped || count($doneJobs) < $total;
        matrixFixProgress(['done_jobs' => $doneJobs,
            'checkpoint' => ['scope' => $scope, 'done_jobs' => $doneJobs, 'started_at' => $fixStartedAt,
                'ok_n' => $okN, 'fail_n' => $failN, 'sent_n' => $sentN, 'del_n' => $delN,
                'price_n' => $priceN, 'cur' => $n, 'total' => $total],
            'cur' => $n, 'total' => $total]);
        usleep($delayMs * 1000);
    }

    /* recount summary */
    $dataF = matrixResultLoad();
    $mm = 0; $okRows = 0; $miss = 0;
    foreach ((array)($dataF['rows'] ?? []) as $rr) {
        if (!is_array($rr) || !empty($rr['is_report'])) continue;
        if ((string)($rr['status'] ?? '') === 'ok') $okRows++;
        if (in_array('price_mismatch', (array)($rr['flags'] ?? []), true)
            || (string)($rr['status'] ?? '') === 'mismatch') $mm++;
        if ((string)($rr['status'] ?? '') === 'missing' || (string)($rr['status'] ?? '') === 'only_profile') $miss++;
    }
    if ($dataF) {
        $sum = is_array($dataF['summary'] ?? null) ? $dataF['summary'] : [];
        $sum['price_mismatch'] = $mm;
        $sum['ok'] = $okRows;
        $dataF['summary'] = $sum;
        matrixResultSave($dataF);
    }

    $incomplete = $stopped || count($doneJobs) < $total;
    $stats = [
        'at' => time(),
        'ok' => $okN, 'fail' => $failN, 'total' => $total,
        'partial' => $incomplete,
        'sent' => $sentN, 'deleted' => $delN, 'priced' => $priceN,
        'stopped' => $stopped, 'scope' => $scope,
        'details' => $details,
    ];
    matrixFixAppendReportRows($stats);

    matrixFixProgress([
        'running' => false, 'done' => true, 'partial' => $incomplete,
        'stale' => $incomplete, 'pct' => 100,
        'phase' => $stopped ? 'stopped' : ($incomplete ? 'partial' : 'done'),
        'ok_n' => $okN, 'fail_n' => $failN, 'cur' => $n ?? $total, 'total' => $total,
        'sent_n' => $sentN, 'del_n' => $delN, 'price_n' => $priceN,
        'finished_at' => time(),
        'done_jobs' => $doneJobs,
        'checkpoint' => $incomplete ? ['scope' => $scope, 'done_jobs' => $doneJobs, 'started_at' => $fixStartedAt,
            'ok_n' => $okN, 'fail_n' => $failN, 'sent_n' => $sentN, 'del_n' => $delN, 'price_n' => $priceN,
            'cur' => $n ?? 0, 'total' => $total] : null,
        'log_add' => [
            ($stopped ? '⏹ متوقف شد — ' : '✅ تمام — ')
            . 'موفق ' . $okN . ' · ناموفق ' . $failN . ' از ' . $total
            . ' · 💰' . $priceN . ' · 📤' . $sentN . ' · 🗑' . $delN,
            '📋 دو ردیف گزارش به انتهای جدول اضافه شد',
        ],
    ]);
    matrixFixStopClear();
    return [
        'ok' => true, 'partial' => $incomplete, 'total' => $total, 'ok_n' => $okN, 'fail_n' => $failN,
        'sent' => $sentN, 'deleted' => $delN, 'priced' => $priceN, 'stopped' => $stopped,
    ];
}

function matrixJobRun(array $opts = []): array {
    $bg = !empty($opts['background']);
    /* v10.129: cron و فراخوانی‌های داخلی هم باید همان checkpoint رابط را
       مصرف کنند؛ فقط دکمهٔ صریحِ resume نباید قادر به ادامه باشد. */
    if (!is_array($opts['checkpoint'] ?? null)) {
        $mp = matrixProgressRead();
        $mcp = is_array($mp['checkpoint'] ?? null) ? $mp['checkpoint'] : null;
        if (!empty($mcp) && empty($mp['done']) && is_array($mcp['profile_rows'] ?? null)) {
            $opts['checkpoint'] = $mcp;
        }
    }
    $lockFile = SYNC_MATRIX_LOCK_FILE;
    $fp = @fopen($lockFile, 'c');
    if (!$fp || !flock($fp, LOCK_EX | LOCK_NB)) {
        if ($fp) @fclose($fp);
        return ['ok' => false, 'error' => 'یک ساخت جدول در حال اجراست', 'running' => true];
    }
    $release = function () use ($fp, $lockFile) {
        @flock($fp, LOCK_UN);
        @fclose($fp);
    };
    if ($bg) {
        // caller already sent early response
    }
    try {
        $res = matrixBuild($opts);
    } catch (Throwable $e) {
        matrixProgress([
            'running' => false, 'done' => true, 'error' => $e->getMessage(), 'pct' => 100,
            'log_add' => ['❌ ' . $e->getMessage()],
        ]);
        $release();
        return ['ok' => false, 'error' => $e->getMessage()];
    }
    $release();
    return $res;
}

/** فیلتر + صفحه‌بندی روی نتیجهٔ ذخیره‌شده (بدون rebuild) */
function matrixQueryPage(array $opts = []): array {
    $data = matrixResultLoad();
    if (!$data || empty($data['rows'])) {
        $prog = matrixProgressRead();
        return [
            'ok' => false,
            'error' => 'هنوز جدولی ساخته نشده',
            'need_build' => true,
            'running' => !empty($prog['running']),
            'progress' => $prog,
        ];
    }
    $q = matrixBareTitle((string)($opts['q'] ?? ''), []);
    $onlyDup = !empty($opts['only_dup']);
    $onlyMismatch = !empty($opts['only_mismatch']);
    $onlyMissing = !empty($opts['only_missing']);
    $all = [];
    foreach ((array)$data['rows'] as $r) {
        if (!is_array($r)) continue;
        if ($q !== '' && mb_strpos((string)($r['bare'] ?? ''), $q) === false
            && mb_strpos(matrixBareTitle((string)($r['title'] ?? ''), []), $q) === false) {
            continue;
        }
        $flags = (array)($r['flags'] ?? []);
        $st = (string)($r['status'] ?? '');
        /* ردیف‌های گزارش کار/نتیجه همیشه می‌آیند */
        $isRep = !empty($r['is_report']) || str_starts_with((string)($r['bare'] ?? ''), '__report_');
        if (!$isRep) {
            if ($onlyDup && !preg_grep('/^dup_/', $flags) && empty($r['woo_dup']) && (int)($r['profile_hits'] ?? 0) < 2) continue;
            if ($onlyMismatch && $st !== 'mismatch' && !in_array('price_mismatch', $flags, true)) continue;
            if ($onlyMissing && $st !== 'missing' && $st !== 'only_profile' && !in_array('missing_woo', $flags, true) && !in_array('missing_bsl', $flags, true)) continue;
        }
        $all[] = $r;
    }
    /* گزارش‌ها را جدا کن و فقط در صفحهٔ آخر بچسبان */
    $reports = [];
    $main = [];
    foreach ($all as $rr) {
        if (!empty($rr['is_report']) || str_starts_with((string)($rr['bare'] ?? ''), '__report_')) $reports[] = $rr;
        else $main[] = $rr;
    }
    $page = max(1, (int)($opts['page'] ?? 1));
    $per = (int)($opts['per_page'] ?? 50);
    if ($per < 10) $per = 10;
    if ($per > 500) $per = 500;
    $total = count($main) + count($reports);
    $pages = max(1, (int)ceil(max(1, count($main)) / max(1, $per)));
    if ($page > $pages) $page = $pages;
    $slice = array_slice($main, ($page - 1) * $per, $per);
    if ($page >= $pages && $reports) {
        $slice = array_merge($slice, $reports);
    }
    $prog = matrixProgressRead();
    $fixProg = function_exists('matrixFixProgressRead') ? matrixFixProgressRead() : [];
    /* گزارش‌ها همیشه جداگانه هم برگردند (نه فقط صفحهٔ آخر) */
    $allReports = [];
    if (!empty($data['reports']) && is_array($data['reports'])) {
        foreach ($data['reports'] as $rr) {
            if (is_array($rr)) $allReports[] = $rr;
        }
    }
    if (!$allReports) {
        foreach ((array)($data['rows'] ?? []) as $rr) {
            if (!is_array($rr)) continue;
            if (!empty($rr['is_report']) || str_starts_with((string)($rr['bare'] ?? ''), '__report_')) {
                $allReports[] = $rr;
            }
        }
    }
    return [
        'ok' => true,
        'from_file' => true,
        'server_side' => true,
        'page' => $page,
        'per_page' => $per,
        'pages' => $pages,
        'total' => $total,
        'summary' => $data['summary'] ?? [],
        'shops' => $data['shops'] ?? [],
        'woo_cfg' => $data['woo_cfg'] ?? [],
        'bsl_cfg' => $data['bsl_cfg'] ?? [],
        'rows' => $slice,
        'reports' => $allReports,
        'fix_stats' => is_array($data['fix_stats'] ?? null) ? $data['fix_stats'] : null,
        'fix_at' => (int)($data['fix_at'] ?? 0),
        'woo_error' => $data['woo_error'] ?? '',
        'bsl_error' => $data['bsl_error'] ?? '',
        'woo_count' => $data['woo_count'] ?? 0,
        'generated_at' => $data['generated_at'] ?? 0,
        'source' => $data['source'] ?? '',
        'row_count_all' => (int)($data['row_count'] ?? count($data['rows'] ?? [])),
        'running' => !empty($prog['running']) || !empty($fixProg['running']),
        'progress' => !empty($fixProg['running']) || (!empty($fixProg['done']) && empty($prog['running'])) ? $fixProg : $prog,
        'fix_progress' => $fixProg,
        'note' => 'خواندن از فایل سرور · بدون rebuild · صفحه‌بندی سمت سرور',
    ];
}

// --- endpoints ---
if (isset($_GET['sync_matrix_status']) || (($_POST['action'] ?? '') === 'sync_matrix_status')) {
    header('Content-Type: application/json; charset=UTF-8');
    $prog = matrixProgressRead();
    $fix = function_exists('matrixFixProgressRead') ? matrixFixProgressRead() : [];
    $has = is_file(SYNC_MATRIX_RESULT_FILE);
    $age = $has ? (time() - (int)@filemtime(SYNC_MATRIX_RESULT_FILE)) : -1;
    $anyRun = !empty($prog['running']) || !empty($fix['running']);
    echo json_encode([
        'ok' => true,
        'running' => $anyRun,
        'build_running' => !empty($prog['running']),
        'fix_running' => !empty($fix['running']),
        'done' => !empty($prog['done']) || !empty($fix['done']),
        'progress' => !empty($fix['running']) || (!empty($fix['done']) && empty($prog['running'])) ? $fix : $prog,
        'build_progress' => $prog,
        'fix_progress' => $fix,
        'has_result' => $has,
        'result_age_sec' => $age,
        'result_rows' => $has ? (int)((matrixResultLoad()['row_count'] ?? 0)) : 0,
        'job' => !empty($fix['running']) ? 'fix' : (!empty($prog['running']) ? 'build' : ((string)($fix['phase'] ?? '') === 'done' || !empty($fix['done']) ? 'fix' : 'build')),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['sync_matrix_start']) || (($_POST['action'] ?? '') === 'sync_matrix_start')) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(0);
    @ignore_user_abort(true);
    $opts = [
        'profile' => (string)($_GET['profile'] ?? $_POST['profile'] ?? 'all'),
        'source' => (string)($_GET['source'] ?? $_POST['source'] ?? 'manual'),
        'background' => true,
    ];
    /* v10.129: مرحلهٔ خواندن پروفایل‌ها checkpoint دارد. دادهٔ محلیِ کامل
       ذخیره می‌شود؛ اگر قطع در یکی از واکشی‌های مقصد رخ دهد، فقط آن واکشی
       دوباره انجام می‌شود و پروفایل‌های مبدأ از ابتدا تکرار نمی‌شوند. */
    $matrixCp = null;
    if (!empty($_GET['resume']) && is_file(SYNC_MATRIX_PROGRESS_FILE)) {
        $oldMatrix = json_decode((string)@file_get_contents(SYNC_MATRIX_PROGRESS_FILE), true);
        $oldCp = is_array($oldMatrix['checkpoint'] ?? null) ? $oldMatrix['checkpoint'] : null;
        if (is_array($oldCp)
            && (string)($oldCp['profile_filter'] ?? 'all') === ($opts['profile'] ?: 'all')
            && is_array($oldCp['profile_rows'] ?? null)) {
            $matrixCp = $oldCp;
        }
    }
    $opts['checkpoint'] = $matrixCp;
    // قفل زود — حذف cursor و مصرف stop فقط بعد از مالکیت واقعی انجام می‌شود.
    $lockFile = SYNC_MATRIX_LOCK_FILE;
    $fp = @fopen($lockFile, 'c');
    if (!$fp || !flock($fp, LOCK_EX | LOCK_NB)) {
        if ($fp) @fclose($fp);
        echo json_encode(['ok' => false, 'error' => 'یک ساخت جدول در حال اجراست', 'running' => true], JSON_UNESCAPED_UNICODE);
        exit;
    }
    if ($matrixCp === null && function_exists('reconFetchCursorFile')) @unlink(reconFetchCursorFile());
    matrixStopClear();
    matrixProgress([
        'running' => true, 'done' => false, 'error' => '', 'pct' => 1,
        'phase' => 'start', 'started_at' => (int)($matrixCp['started_at'] ?? time()),
        'source' => $opts['source'], 'profile' => $opts['profile'],
        'checkpoint' => $matrixCp ?: ['phase' => 'profiles', 'profile_filter' => ($opts['profile'] ?: 'all'),
            'profile_rows' => [], 'profiles_done' => [], 'started_at' => time()],
        'log_add' => ['🚀 ' . ($matrixCp ? 'ادامه ساخت جدول از checkpoint' : 'جاب ساخت جدول در صف سرور') . '...'],
    ]);
    $early = json_encode(['ok' => true, 'started' => true, 'message' => 'ساخت روی سرور شروع شد'], JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_end_flush();
    @ob_flush();
    @flush();
    if (function_exists('fastcgi_finish_request')) {
        @fastcgi_finish_request();
    }
    register_shutdown_function(function () use ($fp, $lockFile) {
        @flock($fp, LOCK_UN);
        @fclose($fp);
    });
    try {
        matrixBuild($opts);
        matrixStopClear();
    } catch (Throwable $e) {
        $matrixErrState = matrixProgressRead();
        matrixStopClear();
        matrixProgress([
            'running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(), 'pct' => 100,
            'checkpoint' => is_array($matrixErrState['checkpoint'] ?? null) ? $matrixErrState['checkpoint'] : null,
            'log_add' => ['❌ ' . $e->getMessage() . ' — checkpoint حفظ شد'],
        ]);
    }
    exit;
}

if (isset($_GET['sync_matrix']) || (($_POST['action'] ?? '') === 'sync_matrix')) {
    header('Content-Type: application/json; charset=UTF-8');
    $opts = [
        'page' => (int)($_GET['page'] ?? $_POST['page'] ?? 1),
        'per_page' => (int)($_GET['per_page'] ?? $_POST['per_page'] ?? 50),
        'q' => (string)($_GET['q'] ?? $_POST['q'] ?? ''),
        'only_dup' => !empty($_GET['only_dup']) || !empty($_POST['only_dup']),
        'only_mismatch' => !empty($_GET['only_mismatch']) || !empty($_POST['only_mismatch']),
        'only_missing' => !empty($_GET['only_missing']) || !empty($_POST['only_missing']),
    ];
    // refresh=1 فقط وضعیت/شروع را پیشنهاد می‌کند — دیگر در همان درخواست rebuild نمی‌کند
    if (!empty($_GET['refresh']) || !empty($_POST['refresh'])) {
        echo json_encode([
            'ok' => true,
            'need_start' => true,
            'message' => 'برای ساخت مجدد sync_matrix_start را صدا بزنید',
            'progress' => matrixProgressRead(),
            'has_result' => is_file(SYNC_MATRIX_RESULT_FILE),
        ], JSON_UNESCAPED_UNICODE);
        exit;
    }
    echo json_encode(matrixQueryPage($opts), JSON_UNESCAPED_UNICODE);
    exit;
}

/* v10.117: اصلاح مغایرت از جدول مقایسه */
if (isset($_GET['sync_matrix_fix_status']) || (($_POST['action'] ?? '') === 'sync_matrix_fix_status')) {
    header('Content-Type: application/json; charset=UTF-8');
    $prog = matrixFixProgressRead();
    $since = max(0, (int)($_GET['since'] ?? $_POST['since'] ?? 0));
    $log = is_array($prog['log'] ?? null) ? $prog['log'] : [];
    $logTotal = count($log);
    if ($since > 0 && $since < $logTotal) {
        $prog['log_delta'] = array_slice($log, $since);
    } else {
        $prog['log_delta'] = array_slice($log, -40);
    }
    $prog['log_total'] = $logTotal;
    /* keep full log for UI that wants it, but also delta */
    echo json_encode([
        'ok' => true,
        'running' => !empty($prog['running']),
        'done' => !empty($prog['done']),
        'progress' => $prog,
        'job' => 'fix',
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['sync_matrix_fix_stop']) || (($_POST['action'] ?? '') === 'sync_matrix_fix_stop')) {
    header('Content-Type: application/json; charset=UTF-8');
    @file_put_contents(SYNC_MATRIX_FIX_STOP_FILE, json_encode(['at' => time()]), LOCK_EX);
    matrixFixProgress(['log_add' => ['⏹ درخواست توقف ثبت شد…']]);
    echo json_encode(['ok' => true, 'stopping' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['sync_matrix_fix_start']) || (($_POST['action'] ?? '') === 'sync_matrix_fix_start')) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(0);
    @ignore_user_abort(true);
    $opts = [
        'scope' => (string)($_GET['scope'] ?? $_POST['scope'] ?? 'all'),
        'delay_ms' => (int)($_GET['delay_ms'] ?? $_POST['delay_ms'] ?? 180),
        'source' => (string)($_GET['source'] ?? $_POST['source'] ?? 'manual'),
    ];
    $matrixFixCp = null;
    if (!empty($_GET['resume']) && is_file(SYNC_MATRIX_FIX_PROGRESS_FILE)) {
        $oldFix = json_decode((string)@file_get_contents(SYNC_MATRIX_FIX_PROGRESS_FILE), true);
        $oldFixCp = is_array($oldFix['checkpoint'] ?? null) ? $oldFix['checkpoint'] : null;
        if (is_array($oldFixCp) && (string)($oldFixCp['scope'] ?? 'all') === $opts['scope']
            && is_array($oldFixCp['done_jobs'] ?? null)) $matrixFixCp = $oldFixCp;
    }
    $opts['checkpoint'] = $matrixFixCp;
    if (!is_file(SYNC_MATRIX_RESULT_FILE)) {
        echo json_encode(['ok' => false, 'error' => 'اول جدول مقایسه را بسازید'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    /* don't run while matrix build is running */
    $mxProg = matrixProgressRead();
    if (!empty($mxProg['running'])) {
        echo json_encode(['ok' => false, 'error' => 'ساخت جدول در حال اجراست — صبر کنید', 'running' => true], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $lockFile = SYNC_MATRIX_FIX_LOCK_FILE;
    $fp = @fopen($lockFile, 'c');
    if (!$fp || !flock($fp, LOCK_EX | LOCK_NB)) {
        if ($fp) @fclose($fp);
        echo json_encode(['ok' => false, 'error' => 'یک اصلاح در حال اجراست', 'running' => true], JSON_UNESCAPED_UNICODE);
        exit;
    }
    /* stopِ قدیمی را فقط پس از مالکیتِ lock مصرف کن؛ stopی که بعد از این
       خط نوشته شود دست‌نخورده می‌ماند و worker در اولینِ probe آن را می‌بیند. */
    matrixFixStopClear();
    matrixFixProgress([
        'running' => true, 'done' => false, 'error' => '', 'pct' => 1,
        'phase' => 'queued', 'started_at' => (int)($matrixFixCp['started_at'] ?? time()), 'source' => $opts['source'],
        'scope' => $opts['scope'], 'delay_ms' => $opts['delay_ms'],
        'job' => 'fix', 'log' => [], 'live' => [],
        'checkpoint' => $matrixFixCp ?: ['scope' => $opts['scope'], 'done_jobs' => [], 'started_at' => time()],
        'log_add' => ['🚀 ' . ($matrixFixCp ? 'ادامه اصلاح مغایرت از checkpoint' : 'جاب اصلاح مغایرت در صف سرور') . '…'],
    ]);
    $early = json_encode(['ok' => true, 'started' => true, 'message' => 'اصلاح روی سرور شروع شد', 'running' => true], JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_end_flush();
    @ob_flush();
    @flush();
    if (function_exists('fastcgi_finish_request')) {
        @fastcgi_finish_request();
    }
    register_shutdown_function(function () use ($fp, $lockFile) {
        @flock($fp, LOCK_UN);
        @fclose($fp);
    });
    try {
        matrixFixRun($opts);
    } catch (Throwable $e) {
        $fixErrState = matrixFixProgressRead();
        matrixFixProgress([
            'running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(), 'pct' => 100,
            'checkpoint' => is_array($fixErrState['checkpoint'] ?? null) ? $fixErrState['checkpoint'] : null,
            'log_add' => ['❌ ' . $e->getMessage() . ' — checkpoint حفظ شد'],
        ]);
    }
    exit;
}


if (isset($_GET['remote_map'])) {
    ob_clean();
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(180);
    $clr = (string)($_GET['clear'] ?? '');
    if ($clr === 'woo' || $clr === 'bsl') {
        $m = remoteMapLoad(); $m[$clr] = []; remoteMapSave($m);
        echo json_encode(['ok' => true, 'cleared' => $clr], JSON_UNESCAPED_UNICODE); exit;
    }
    $rb = (string)($_GET['rebuild'] ?? '');
    if ($rb === 'woo' || $rb === 'bsl') {
        // یک بار با عنوان تطبیق می‌دهیم و شناسه‌ها را ثبت می‌کنیم، تا از این
        // به بعد تغییر نام محصول دیگر تطبیق را خراب نکند.
        $cnR = loadConnections();
        $st = null;
        $exp = reconExpected($rb, true, $st);
        $byTitleKey = [];
        foreach (loadProfiles() as $pk => $pv) {
            foreach (profileOrderedProducts($pv) as $pp) {
                $t = reconNormTitle((string)($pp['title'] ?? ''));
                $kk = trim((string)($pp['key'] ?? ''));
                if ($t !== '' && $kk !== '' && !isset($byTitleKey[$t])) $byTitleKey[$t] = ['key' => $kk, 'title' => $pp['title'] ?? ''];
            }
        }
        if ($rb === 'woo') {
            $w = $cnR['woocommerce'] ?? [];
            if (empty($w['store_url'])) { echo json_encode(['ok' => false, 'error' => 'تنظیمات ووکامرس ناقص'], JSON_UNESCAPED_UNICODE); exit; }
            $remote = reconFetchWoo($w);
        } else {
            $tk = (string)($cnR['basalam']['token'] ?? ''); $vid = (int)($cnR['basalam']['vendor_id'] ?? 0);
            if ($tk === '' || $vid <= 0) { echo json_encode(['ok' => false, 'error' => 'تنظیمات باسلام ناقص'], JSON_UNESCAPED_UNICODE); exit; }
            $remote = reconFetchBsl($tk, $vid);
        }
        $rows = [];
        foreach ($remote as $r) {
            $t = reconNormTitle((string)$r['title']);
            if (!isset($byTitleKey[$t])) continue;
            $rows[] = ['key' => $byTitleKey[$t]['key'], 'remote_id' => (int)$r['id'],
                       'title' => (string)$r['title']];
        }
        $n = remoteMapRecord($rb, $rows);
        echo json_encode(['ok' => true, 'rebuilt' => $rb, 'recorded' => $n,
            'remote_seen' => count($remote), 'profile_titles' => count($byTitleKey),
            'note' => $n . ' شناسه ثبت شد — از این به بعد تغییر نام محصول تطبیق را خراب نمی‌کند'],
            JSON_UNESCAPED_UNICODE);
        exit;
    }
    $m = remoteMapLoad();
    $sample = [];
    foreach (['woo', 'bsl'] as $t) {
        $i = 0;
        foreach ($m[$t] as $k => $v) {
            if ($i++ >= 5) break;
            $sample[$t][] = ['key' => mb_substr($k, 0, 10), 'id' => (int)($v['id'] ?? 0),
                             'title' => (string)($v['title'] ?? '')];
        }
    }
    echo json_encode(['ok' => true, 'woo' => count($m['woo']), 'bsl' => count($m['bsl']),
        'sample' => $sample], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ar_rules'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cnAR = loadConnections();
    // ?defaults=1 قواعد کارخانه را برمی‌گرداند بدون اینکه چیزی را ذخیره کند
    $rulesAR = !empty($_GET['defaults']) ? arDefaultRules() : arLoadRules();
    echo json_encode(['ok' => true, 'rules' => $rulesAR, 'cfg' => arCfg($cnAR),
        'saved' => is_file(AUTOREPLY_RULES_FILE),
        'offhours_now' => arIsOffHours(arCfg($cnAR), time())], JSON_UNESCAPED_UNICODE);
    exit;
}

if (($_POST['action'] ?? '') === 'ar_save_rules') {
    header('Content-Type: application/json; charset=UTF-8');
    $rules = json_decode((string)($_POST['rules'] ?? '[]'), true);
    if (!is_array($rules)) { echo json_encode(['ok' => false, 'error' => 'قواعد نامعتبر'], JSON_UNESCAPED_UNICODE); exit; }
    $ok = arSaveRules($rules);
    echo json_encode(['ok' => $ok, 'count' => count($rules),
        'error' => $ok ? '' : 'نوشتن فایل قواعد ناموفق بود'], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ar_test'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $txt = (string)($_GET['text'] ?? '');
    if (trim($txt) === '') { echo json_encode(['ok' => false, 'error' => 'متن خالی است'], JSON_UNESCAPED_UNICODE); exit; }
    $rules = arLoadRules();
    $cfgAR = arCfg();
    $all = [];
    foreach ($rules as $r) {
        $all[] = ['id' => $r['id'] ?? '', 'on' => !empty($r['on']),
                  'match' => arRuleMatches($r, $txt)];
    }
    /* v9.38: آزمایش طبق «ترتیب اولویت» انتخاب‌شده اجرا می‌شود (rules_first /
       ai_first / rules_only / ai_only) تا نتیجه‌اش همان چیزی باشد که در عمل
       اتفاق می‌افتد. هوش مصنوعی واقعاً صدا زده می‌شود.
       v9.35: مهلت کوتاه (۸ ثانیه) تا دکمهٔ آزمایش هرگز کاربر را معطل نکند
       و سریع جواب بدهد. */
    @set_time_limit(40);
    $order = (string)($cfgAR['reply_order'] ?? 'rules_first');
    $aiOk = false; $aiText = ''; $aiErr = '';
    $hit = null; $ruleReply = ''; $ruleId = '';
    if ($order === 'ai_first' || $order === 'ai_only') {
        $aiRes = arAiReplyText($txt, 8);
        $aiOk = !empty($aiRes['ok']);
        $aiText = $aiOk ? ($aiRes['text'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '')) : '';
        $aiErr = $aiOk ? '' : (string)($aiRes['error'] ?? 'خطا');
        if (!$aiOk && $order === 'ai_first') $hit = arPickRule($rules, $txt);
    } elseif ($order === 'rules_first') {
        $hit = arPickRule($rules, $txt);
        if ($hit === null) {
            $aiRes = arAiReplyText($txt, 8);
            $aiOk = !empty($aiRes['ok']);
            $aiText = $aiOk ? ($aiRes['text'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '')) : '';
            $aiErr = $aiOk ? '' : (string)($aiRes['error'] ?? 'خطا');
        }
    } else { // rules_only
        $hit = arPickRule($rules, $txt);
    }
    if ($hit) {
        $ruleId = (string)$hit['id'];
        $ruleReply = $hit['reply'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '');
    }
    $finalReply = $aiOk ? $aiText : $ruleReply;
    $source = $aiOk ? 'ai' : ($hit ? 'rule' : 'none');
    echo json_encode(['ok' => true, 'normalized' => arNormText($txt),
        'order' => $order,
        'ai_ok' => $aiOk, 'ai_error' => $aiErr, 'ai_reply' => $aiText,
        'rule' => $ruleId, 'rule_reply' => $ruleReply,
        'source' => $source, 'reply' => $finalReply,
        'checked' => $all], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ar_log'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $stAR = arLoadState();
    echo json_encode(['ok' => true, 'log' => array_slice(arLogRead(), 0, 30),
        'last_run' => (int)($stAR['last_run'] ?? 0), 'daily' => $stAR['daily'] ?? []],
        JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.55 (69): پاسخ دستی به پیام‌های مشتری
 *
 *  خواستهٔ کاربر: برای جواب دادن به مشتری نباید رفت پلتفرمِ باسلام را
 *  باز کرد. گفتگوها داخلِ پنل باز می‌شوند و پاسخ همین‌جا فرستاده می‌شود.
 *  • bsl_chats         — فهرستِ گفتگوهایِ تازه (با شمارِ خوانده‌نشده)
 *  • bsl_chat_messages — تاریخچهٔ کاملِ یک گفتگو (هر دو طرف)
 *  • bsl_chat_reply    — ارسالِ پاسخ (فرستندهٔ واقعی همان bslSendChatMessage
 *                        است — یک فرستنده برای همهٔ پاسخ‌ها)
 * ===================================================================== */
if (isset($_GET['bsl_chats'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(60);
    $cnMR = loadConnections();
    $shopsMR = bslChatShops($cnMR);
    if (!$shopsMR) { echo json_encode(['ok' => false, 'error' => 'غرفهٔ باسلامی با توکن تنظیم نشده است'], JSON_UNESCAPED_UNICODE); exit; }
    $limMR = max(5, min(50, (int)($_GET['limit'] ?? 30)));
    $onlyMR = (int)($_GET['shop'] ?? 0);   // 0 = همهٔ غرفه‌ها
    /* v10.57 (۷۱): کشِ ۲ ثانیه‌ای — رابط کاربری هر ثانیه پُل می‌زند؛ با کش
       هر غرفه در هر ۲ ثانیه یک‌بار به API می‌رسد، نه هر ثانیه. */
    $cFileMR = __DIR__ . '/bsl_chats_cache.json';
    $cachedMR = [];
    if (is_file($cFileMR) && time() - (int)@filemtime($cFileMR) <= 2) {
        $cD = json_decode((string)@file_get_contents($cFileMR), true);
        if (is_array($cD) && is_array($cD['rows'] ?? null)) $cachedMR = $cD['rows'];
    }
    $rowsMR = []; $shopErrMR = []; $shopOutMR = [];
    foreach ($shopsMR as $shMR) {
        if ($onlyMR > 0 && (int)$shMR['shop'] !== $onlyMR) continue;
        $kMR = (string)$shMR['shop'];
        if (isset($cachedMR[$kMR])) {
            $rowsMR = array_merge($rowsMR, $cachedMR[$kMR]);
            $shopOutMR[] = ['shop' => (int)$shMR['shop'], 'name' => $shMR['name'], 'ok' => true, 'n' => count($cachedMR[$kMR])];
            continue;
        }
        $outShMR = [];
        $rMR = bslReqRead($shMR['token'], 'chats?limit=' . $limMR . '&order_by=updated_at');
        if (empty($rMR['ok'])) {
            $shopErrMR[] = ['shop' => (int)$shMR['shop'], 'name' => $shMR['name'],
                            'error' => bslApiError($rMR, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read')];
            $shopOutMR[] = ['shop' => (int)$shMR['shop'], 'name' => $shMR['name'], 'ok' => false, 'n' => 0];
            continue;
        }
        $myIdMR = bslMyUserId($shMR['token']);
        $rawMR = $rMR['body']['data']['chats'] ?? ($rMR['body']['data'] ?? []);
        if (!is_array($rawMR)) $rawMR = [];
        foreach ($rawMR as $cMR) {
            if (!is_array($cMR)) continue;
            $ncMR = bslNormalizeChat($cMR);
            $lmMR = is_array($cMR['last_message'] ?? null) ? $cMR['last_message'] : [];
            if ($ncMR['chat_id'] <= 0) continue;
            /* v10.62 (۷۶): آدرسِ تصویرِ آخرین پیام (اگر پیام تصویر باشد) —
               پیش‌نمایش در کارتِ نوتیف و لیستِ گفتگوها. از همهٔ شکل‌هایِ
               ممکنِ پاسخ برداشته می‌شود (همان الگوی bslChatThread). */
            $lmImgMR = '';
            foreach ([$lmMR['attachment']['files'][0]['url'] ?? null,
                      $lmMR['content']['url'] ?? null,
                      $lmMR['content']['files'][0]['url'] ?? null,
                      $lmMR['url'] ?? null,
                      $lmMR['content']['image'] ?? null,
                      $lmMR['image'] ?? null] as $uImgMR) {
                if (is_string($uImgMR) && strncmp($uImgMR, 'http', 4) === 0) { $lmImgMR = $uImgMR; break; }
            }
            $outShMR[] = [
                'chat_id'      => $ncMR['chat_id'],
                'who'          => $ncMR['who'],
                'text'         => $ncMR['text'],
                'unseen'       => $ncMR['unseen'],
                'updated_at'   => $ncMR['updated_at'],
                'last_is_mine' => ($myIdMR > 0 && (int)($lmMR['sender']['id'] ?? 0) === $myIdMR),
                /* v10.60 (۷۴): شناسهٔ آخرین پیام — مبنای کشفِ پیامِ تازهٔ مشتری
                   برای نوتیفیکیشنِ زنده (کارتِ سوایپ‌شونده). */
                'last_msg_id'  => (int)($lmMR['id'] ?? 0),
                'last_img'     => $lmImgMR,
                'last_type'    => (string)($lmMR['message_type'] ?? ''),
                'shop'         => (int)$shMR['shop'],
                'shop_name'    => $shMR['name'],
                'vendor_id'    => (int)$shMR['vendor_id'],
            ];
        }
        $rowsMR = array_merge($rowsMR, $outShMR);
        $cachedMR[$kMR] = $outShMR;
        $shopOutMR[] = ['shop' => (int)$shMR['shop'], 'name' => $shMR['name'], 'ok' => true, 'n' => count($outShMR)];
    }
    @file_put_contents($cFileMR, json_encode(['rows' => $cachedMR], JSON_UNESCAPED_UNICODE), LOCK_EX);
    usort($rowsMR, function ($a, $b) { return strcmp((string)($b['updated_at'] ?? ''), (string)($a['updated_at'] ?? '')); });
    echo json_encode(['ok' => true, 'chats' => $rowsMR, 'shops' => $shopOutMR, 'shop_errors' => $shopErrMR], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['bsl_chat_messages'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(60);
    $cnMR = loadConnections();
    $shopsMR = bslChatShops($cnMR);
    if (!$shopsMR) { echo json_encode(['ok' => false, 'error' => 'غرفهٔ باسلامی با توکن تنظیم نشده است'], JSON_UNESCAPED_UNICODE); exit; }
    $chatIdMR = (int)($_GET['chat_id'] ?? 0);
    $limMR = max(1, min(50, (int)($_GET['limit'] ?? 30)));
    $shopNMR = (int)($_GET['shop'] ?? 0);
    if ($chatIdMR <= 0) { echo json_encode(['ok' => false, 'error' => 'شناسهٔ گفتگو نامعتبر'], JSON_UNESCAPED_UNICODE); exit; }
    /* v10.57 (۷۱): اگر شمارهٔ غرفه آمده فقط همان؛ وگرنه گفتگو ممکن است از
       هر غرفه‌ای باشد — به ترتیب امتحان می‌کنیم تا یکی جواب بدهد. */
    $tryMR = ($shopNMR > 0)
        ? array_values(array_filter($shopsMR, function ($x) use ($shopNMR) { return (int)$x['shop'] === $shopNMR; }))
        : $shopsMR;
    $msgsMR = []; $shMR = null;
    foreach ($tryMR as $candMR) {
        $msgsMR = bslChatThread($candMR['token'], $chatIdMR, $limMR);
        if ($msgsMR) { $shMR = $candMR; break; }
    }
    echo json_encode(['ok' => true, 'messages' => $msgsMR,
                      'shop' => $shMR ? (int)$shMR['shop'] : 0,
                      'shop_name' => $shMR ? $shMR['name'] : ''], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['bsl_chat_reply'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(90);
    @ini_set('post_max_size', '16M');
    @ini_set('upload_max_filesize', '16M');
    $cnMR = loadConnections();
    $shopsMR = bslChatShops($cnMR);
    if (!$shopsMR) { echo json_encode(['ok' => false, 'error' => 'غرفهٔ باسلامی با توکن تنظیم نشده است'], JSON_UNESCAPED_UNICODE); exit; }
    $chatIdMR = (int)($_POST['chat_id'] ?? $_GET['chat_id'] ?? 0);
    $textMR = trim((string)($_POST['text'] ?? $_GET['text'] ?? ''));
    $shopNMR = (int)($_POST['shop'] ?? $_GET['shop'] ?? 0);
    $shMR = $shopNMR > 0 ? bslShopByNum($shopsMR, $shopNMR) : null;
    if ($shMR === null) $shMR = $shopsMR[0];   // عقب‌نشینی: اولینِ (پیش‌فرض)
    if ($chatIdMR <= 0) { echo json_encode(['ok' => false, 'error' => 'شناسهٔ گفتگو لازم است'], JSON_UNESCAPED_UNICODE); exit; }
    /* v10.57 (۷۱): تصویر (dataURL یا base64) — اول به سرویسِ آپلودِ باسلام
       می‌رود (chat.photo)، بعد به‌صورتِ attachment به گفتگو پیوست می‌شود. */
    $fileMR = null;
    $imgB64MR = trim((string)($_POST['image_b64'] ?? ''));
    $imgNameMR = trim((string)($_POST['image_name'] ?? ''));
    if ($imgNameMR === '') $imgNameMR = 'تصویر';
    $imgMimeMR = trim((string)($_POST['image_mime'] ?? ''));
    if ($imgB64MR !== '') {
        if (preg_match('/^data:(image\/[^;]+);base64,(.+)$/is', $imgB64MR, $mImgMR)) {
            $imgMimeMR = $mImgMR[1]; $imgB64MR = $mImgMR[2];
        }
        $b64LenMR = strlen($imgB64MR);
        if ($b64LenMR < 100 || $b64LenMR > 9500000) {
            echo json_encode(['ok' => false, 'error' => 'تصویر نامعتبر است (بیش‌ازحد بزرگ — حداکثر حدود ۷ مگابایت)'], JSON_UNESCAPED_UNICODE); exit;
        }
        $binMR = base64_decode($imgB64MR, true);
        if ($binMR === false) { echo json_encode(['ok' => false, 'error' => 'فایلِ تصویر خراب است'], JSON_UNESCAPED_UNICODE); exit; }
        $tmpMR = tempnam(sys_get_temp_dir(), 'mrimg_');
        if ($tmpMR === false || file_put_contents($tmpMR, $binMR) === false) {
            echo json_encode(['ok' => false, 'error' => 'ذخیرهٔ موقتِ تصویر ناموفق بود'], JSON_UNESCAPED_UNICODE); exit;
        }
        $isImgMR = (strpos($imgMimeMR, 'image/') === 0);
        $upMR = bslChatUploadFile($shMR['token'], $tmpMR, $imgMimeMR, $imgNameMR, $isImgMR ? 'chat.photo' : 'chat.file');
        @unlink($tmpMR);
        if (empty($upMR['ok'])) {
            echo json_encode(['ok' => false, 'error' => 'آپلود تصویر: ' . ($upMR['error'] ?? 'ناموفق')], JSON_UNESCAPED_UNICODE); exit;
        }
        $fileMR = ['id' => $upMR['id'], 'url' => $upMR['url'], 'width' => $upMR['width'],
                   'height' => $upMR['height'], 'size' => $upMR['size'],
                   'name' => $imgNameMR, 'type' => $isImgMR ? 'picture' : 'file'];
    }
    if ($textMR === '' && $fileMR === null) {
        echo json_encode(['ok' => false, 'error' => 'متنِ پیام یا یک تصویر لازم است'], JSON_UNESCAPED_UNICODE); exit;
    }
    $rMR = bslChatSendEx($shMR['token'], $chatIdMR, $textMR, $fileMR);
    /* پاسخِ دستی (متن یا تصویر) هم در همان لاگِ پاسخ‌ها ثبت می‌شود. */
    arLogAdd(['type' => 'manual', 'chat_id' => $chatIdMR, 'who' => '',
              'text' => mb_substr($textMR !== '' ? $textMR : '🖼 تصویر', 0, 90),
              'ok' => !empty($rMR['ok']), 'source' => 'manual',
              'shop' => (int)$shMR['shop'], 'has_image' => $fileMR !== null]);
    if (empty($rMR['ok'])) {
        echo json_encode(['ok' => false, 'error' => $rMR['error'] ?? 'ارسال ناموفق'], JSON_UNESCAPED_UNICODE); exit;
    }
    echo json_encode(['ok' => true, 'shop' => (int)$shMR['shop']], JSON_UNESCAPED_UNICODE);
    exit;
}

/* v9.36: محیط چتِ آزمایش پاسخ خودکار (مودال).
   مثل ar_test ولی با اطلاعات بیشتر برای نمایش در یک پنجرهٔ چت:
   منبع (هوش مصنوعی / قاعده / بدون پاسخ)، مدلِ استفاده‌شده، تأخیر، و پیام خطا. */
if (isset($_GET['ar_chat'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(40);
    $txt = (string)($_GET['msg'] ?? ($_GET['text'] ?? ''));
    if (trim($txt) === '') { echo json_encode(['ok' => false, 'error' => 'متن خالی است'], JSON_UNESCAPED_UNICODE); exit; }
    $rules = arLoadRules();
    $cfgAR = arCfg();
    $t0 = microtime(true);
    $order = (string)($cfgAR['reply_order'] ?? 'rules_first');
    $aiOk = false; $aiText = ''; $aiErr = ''; $modelUsed = '';
    $hit = null; $ruleReply = ''; $ruleId = '';
    if ($order === 'ai_first' || $order === 'ai_only') {
        $aiRes = arAiReplyText($txt, 8);
        $aiOk = !empty($aiRes['ok']);
        $aiText = $aiOk ? ($aiRes['text'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '')) : '';
        $aiErr = $aiOk ? '' : (string)($aiRes['error'] ?? 'خطا');
        $modelUsed = (string)($aiRes['model'] ?? '');
        if (!$aiOk && $order === 'ai_first') $hit = arPickRule($rules, $txt);
    } elseif ($order === 'rules_first') {
        $hit = arPickRule($rules, $txt);
        if ($hit === null) {
            $aiRes = arAiReplyText($txt, 8);
            $aiOk = !empty($aiRes['ok']);
            $aiText = $aiOk ? ($aiRes['text'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '')) : '';
            $aiErr = $aiOk ? '' : (string)($aiRes['error'] ?? 'خطا');
            $modelUsed = (string)($aiRes['model'] ?? '');
        }
    } else { // rules_only
        $hit = arPickRule($rules, $txt);
    }
    $latMs = (int)round((microtime(true) - $t0) * 1000);
    if ($hit) {
        $ruleId = (string)$hit['id'];
        $ruleReply = $hit['reply'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '');
    }
    $finalReply = $aiOk ? $aiText : $ruleReply;
    $source = $aiOk ? 'ai' : ($hit ? 'rule' : 'none');
    echo json_encode([
        'ok' => true,
        'order' => $order,
        'source' => $source,
        'reply' => $finalReply,
        'ai_ok' => $aiOk,
        'ai_error' => $aiErr,
        'model' => $modelUsed,
        'rule' => $ruleId,
        'latency_ms' => $latMs,
        'matched_rules' => array_values(array_filter(array_map(function ($r) use ($txt) {
            return ['id' => $r['id'] ?? '', 'reply' => $r['reply'] ?? ''];
        }, $rules), function ($x) use ($txt) {
            return $x['reply'] !== '';
        })),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ar_run'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(180);
    $cnAR = loadConnections();
    $dryAR = !empty($_GET['dry']);
    // ?now=1 یعنی مهلت ادب را نادیده بگیر — برای وقتی کاربر دستی اجرا می‌کند
    $resAR = autoReplyRun($cnAR, $dryAR, !empty($_GET['now']));
    if (!$dryAR && !empty($resAR['ok']) && (int)$resAR['replied'] > 0 && arCfg($cnAR)['notify']) {
        $resAR['delivery'] = notifSend($cnAR, arMsg($resAR));
    }
    echo json_encode($resAR, JSON_UNESCAPED_UNICODE);
    exit;
}

/** v8.49: نتیجهٔ کامل آخرین مغایرت‌گیری */

/**
 * v10.108: صف‌کردن دستی «در مقصد نیست»
 * ?recon_enqueue=1&target=woo|bsl
 * اختیاری: body/POST missing=json  یا از آخرین recon_result.json
 */
if (isset($_GET['recon_enqueue'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $target = (string)($_GET['target'] ?? '');
    if ($target !== 'woo' && $target !== 'bsl') {
        echo json_encode(['ok' => false, 'error' => 'مقصد نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $cn = loadConnections();
    $missing = [];
    $raw = (string)($_POST['missing'] ?? $_GET['missing'] ?? '');
    if ($raw !== '') {
        $d = json_decode($raw, true);
        if (is_array($d)) $missing = $d;
    }
    if (!$missing && is_file(__DIR__ . '/recon_result.json')) {
        $rr = json_decode((string)@file_get_contents(__DIR__ . '/recon_result.json'), true);
        if (is_array($rr) && (string)($rr['target'] ?? '') === $target) {
            $missing = is_array($rr['missing'] ?? null) ? $rr['missing'] : [];
        } elseif (is_array($rr) && empty($rr['target']) && $target === 'bsl') {
            $missing = is_array($rr['missing'] ?? null) ? $rr['missing'] : [];
        }
    }
    if (!$missing) {
        echo json_encode(['ok' => false, 'error' => 'لیست «در مقصد نیست» خالی است — اول مغایرت‌گیری کنید'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $max = max(1, min(5000, (int)($_GET['max'] ?? $_POST['max'] ?? 2000)));
    $res = reconEnqueueMissingProducts($cn, $target, $missing, [
        'max' => $max,
        'vendor_id' => (int)($_GET['vendor_id'] ?? 0),
    ]);
    echo json_encode($res, JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['recon_result'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $f = __DIR__ . '/recon_result.json';
    if (!is_file($f)) { echo json_encode(['ok' => false, 'error' => 'نتیجه‌ای نیست'], JSON_UNESCAPED_UNICODE); exit; }
    echo (string)@file_get_contents($f);
    exit;
}

/**
 * v8.48: مدیریت حافظهٔ یادگیری دسته‌بندی.
 * ?catlearn=1                 → فهرست آموخته‌ها
 * &forget=<کلمه>              → فراموش کردن یک کلمه
 * &clear=1                    → پاک کردن همه
 * &test=<عنوان>               → ببین برای این عنوان چه پیشنهاد می‌دهد
 */
/**
 * v8.61: عیب‌یابی اتصال هوش مصنوعی.
 * ?ai_probe=1  → همهٔ روش‌های عبور را یکی‌یکی امتحان می‌کند و می‌گوید
 *                کدام روی این سرور جواب می‌دهد.
 * هیچ چیزی ذخیره نمی‌شود؛ فقط گزارش می‌دهد.
 */
/* v9.00: آزمایش اتصال به سایت مبدأ با تنظیمات فعلی.
   می‌گوید صفحهٔ فهرست و یک صفحهٔ محصول از روی سرور باز می‌شوند یا نه —
   چون همین دو تا هستند که استخراج به آن‌ها نیاز دارد. */
if (isset($_GET['src_probe'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $u = trim((string)($_GET['url'] ?? ''));
    if ($u === '' || !filter_var($u, FILTER_VALIDATE_URL)) {
        echo json_encode(['ok' => false, 'error' => 'آدرس نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $net = srcNetCfg();
    $host = strtolower((string)parse_url($u, PHP_URL_HOST));
    $t0 = microtime(true);
    $r = fetch_html($u, 30);
    $ms = (int)round((microtime(true) - $t0) * 1000);
    $out = ['ok' => !empty($r['ok']), 'code' => (int)($r['code'] ?? 0),
            'ms' => $ms, 'host' => $host,
            'mode' => $net['mode'], 'applies' => srcNetApplies($net, $host),
            'gap_ms' => (int)$net['gap_ms'],
            'error' => (string)($r['error'] ?? ''),
            'bytes' => strlen((string)($r['html'] ?? ''))];
    $code = (int)($r['code'] ?? 0);
    if ($code === 403 || $code === 429) {
        $out['diagnosis'] = 'سایت مبدأ درخواست سرور را رد کرد (' . $code . ') — یعنی IP هاست بلاک یا محدود شده. '
                          . 'تغییر DNS اینجا فایده ندارد؛ فاصلهٔ بین درخواست‌ها را زیاد کنید یا پروکسی بگذارید.';
    } elseif (!empty($r['ok'])) {
        $out['diagnosis'] = 'اتصال سالم است — صفحه در ' . $ms . ' میلی‌ثانیه گرفته شد.';
    } elseif (stripos((string)$r['error'], 'resolve') !== false) {
        $out['diagnosis'] = 'نام دامنه از روی سرور پیدا نشد — اینجا DoH یا IP دستی کمک می‌کند.';
    } else {
        $out['diagnosis'] = 'اتصال برقرار نشد: ' . (string)$r['error'];
    }
    echo json_encode($out, JSON_UNESCAPED_UNICODE); exit;
}

if (isset($_GET['ai_probe'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(120);
    $cn  = loadConnections();
    $ai  = $cn['ai'] ?? [];
    $net = aiNetCfg($cn);
    // اجازهٔ آزمایش مقادیر واردشده در فرم، بدون ذخیره
    foreach (['mode','resolve_ip','doh_url','worker_url','proxy','proxy_type','proxy_auth'] as $k) {
        if (isset($_GET['net_' . $k])) $net[$k] = trim((string)$_GET['net_' . $k]);
    }
    /* v9.27: از «ارائه‌دهندهٔ فعال» آدرس واقعی و کلید/مدل را بگیر.
       تا ۹.۲۶ این بخش به فیلدهای تک-AI قدیمی (base_url) وابسته بود که در
       بازنویسی چند-ارائه‌دهنده حذف شدند — برای همین host خالی می‌آمد و
       عیب‌یابی همیشه «میزبان خالی» می‌گفت. حالا از خودِ ارائه‌دهندهٔ فعال
       و مدلِ فعال استفاده می‌شود. */
    $probeUrl = '';
    $apiKey   = '';
    $model    = '';
    $provId   = '';
    $provName = '';
    $_ac = aiActiveConfig();
    if (!empty($_ac['provider'])) {
        $provId   = (string)($_ac['provider']['id'] ?? '');
        $provName = (string)($_ac['provider']['name'] ?? $provId);
        /* v10.01: عیب‌یابی هم با «کلیدِ سالم» انجام شود، نه با کلیدی که
           اعتبارش تمام شده — وگرنه گزارش، خطای اعتبار را به‌جای خطای شبکه
           نشان می‌دهد. */
        $_pk      = aiPickApiKey($_ac['provider'], $provId);
        $apiKey   = trim((string)($_pk['key'] ?? ''));
        if ($apiKey === '') $apiKey = trim((string)($_ac['provider']['apiKey'] ?? ''));
        $model    = (string)($_ac['model'] ?? '');
        $ep = aiProviderEndpoint($_ac['provider'], $model);
        // برای تستِ عیب‌یابی، آدرس chat/completions را می‌سنجیم
        $probeUrl = (string)($ep['url'] ?? '');
        // Cloudflare آدرس مستقیم مدل می‌دهد؛ برای هاست هم همان را بگیر
        if ($probeUrl === '') $probeUrl = (string)($_ac['provider']['url'] ?? '');
    }
    // سازگاری: اگر ارائه‌دهنده‌ای نیست، به مقادیر قدیمی برگرد
    if ($probeUrl === '') {
        $baseUrl0 = trim((string)($_GET['base_url'] ?? ($ai['base_url'] ?? 'https://dashscope.aliyuncs.com/compatible-mode/v1')));
        $probeUrl = rtrim($baseUrl0, '/') . '/chat/completions';
        $apiKey   = $apiKey !== '' ? $apiKey : trim((string)($ai['api_key'] ?? ''));
        $model    = $model !== '' ? $model : trim((string)($ai['model'] ?? 'qwen-plus'));
    }
    $host = (string)(parse_url($probeUrl, PHP_URL_HOST) ?? '');
    $port = (int)(parse_url($probeUrl, PHP_URL_PORT) ?? (parse_url($probeUrl, PHP_URL_SCHEME) === 'https' ? 443 : 80));

    $out = ['ok' => true, 'host' => $host, 'port' => $port, 'base_url' => $probeUrl,
            'provider' => $provId, 'provider_name' => $provName, 'model' => $model,
            'has_key' => $apiKey !== '', 'steps' => [], 'modes' => []];

    // ۱) DNS محلی چه می‌گوید؟
    $t0 = microtime(true);
    $localIp = $host !== '' ? @gethostbyname($host) : '';
    $out['steps'][] = ['name' => 'DNS محلی سرور', 'ok' => ($localIp !== '' && $localIp !== $host),
        'detail' => ($localIp !== '' && $localIp !== $host) ? $localIp : 'پاسخ نداد',
        'ms' => (int)((microtime(true) - $t0) * 1000)];

    // ۲) DoH در دسترس است؟ (فقط حلِ DNS — هنوز به اندپوینت وصل نشده)
    $t0 = microtime(true);
    $doh = aiDohResolve($host !== '' ? $host : 'example.com', (string)$net['doh_url'], 10);
    $out['steps'][] = ['name' => 'DNS-over-HTTPS (' . parse_url((string)$net['doh_url'], PHP_URL_HOST) . ')',
        'ok' => !empty($doh['ok']), 'detail' => $doh['ok'] ? $doh['ip'] : ($doh['error'] ?? '?'),
        'ms' => (int)((microtime(true) - $t0) * 1000)];
    if (!empty($doh['ok']) && !empty($localIp) && $localIp !== $host && $localIp !== $doh['ip']) {
        $out['steps'][] = ['name' => '⚠️ DNS محلی با DoH فرق دارد', 'ok' => false,
            'detail' => 'محلی=' . $localIp . ' · واقعی=' . $doh['ip'] . ' — احتمال DNS آلوده'];
    }

    // ۳) هر روش را با یک درخواست واقعی بسنج
    $probeModes = ['direct', 'doh'];
    if ($net['resolve_ip'] !== '') $probeModes[] = 'dns';
    if ($net['worker_url'] !== '') $probeModes[] = 'worker';
    if ($net['proxy'] !== '')      $probeModes[] = 'proxy';

    $payload = ['model' => $model, 'max_tokens' => 5,
                'messages' => [['role' => 'user', 'content' => 'ping']]];
    $url = $probeUrl; // v9.27: از ارائه‌دهندهٔ فعال گرفته شد
    $headers = ['Content-Type: application/json', 'Authorization: Bearer ' . ($apiKey !== '' ? $apiKey : 'probe')];

    $working = [];
    foreach ($probeModes as $m) {
        $t0 = microtime(true);
        $r  = aiHttp($url, $headers, $payload, $net, $m);
        $ms = (int)((microtime(true) - $t0) * 1000);
        $code = (int)$r['code'];
        // 401 یعنی شبکه رسید ولی کلید غلط است — از نظر عبور، موفق است
        $reached = $code > 0;
        // v9.26: «DNS حل شد ولی اتصال برقرار نشد» یعنی خودِ IP مقصد بلاک است
        $connNote = '';
        if ($m === 'doh' && $code === 0) {
            $connNote = ' ⚠️ DoH دامنه را حل کرد ولی اتصال به IP مقصد برقرار نشد — DNS سالم است ولی مسیر IP بسته است؛ پروکسی/Worker لازم است';
        }
        $note = $code === 0 ? ('نرسید: ' . mb_substr((string)$r['error'], 0, 70) . $connNote)
              : ($code === 401 ? 'رسید ✓ (کلید نامعتبر یا خالی)'
              : ($code >= 200 && $code < 300 ? 'کامل ✓' : 'رسید ✓ (HTTP ' . $code . ')'));
        if ($reached) $working[] = $m;
        $out['modes'][] = ['mode' => $m, 'reached' => $reached, 'http' => $code,
                           'ms' => $ms, 'note' => $note, 'via' => $r['via'] ?? $m];
    }
    $out['working'] = $working;
    $out['recommended'] = $working[0] ?? '';
    $out['summary'] = empty($working)
        ? 'هیچ روشی به مقصد نرسید — Worker یا پروکسی لازم است (DoH فقط DNS را حل می‌کند، نه مسیر IP)'
        : ('روش‌های کارآمد: ' . implode(' · ', $working));
    echo json_encode($out, JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * v8.62: درون‌ریزی حافظهٔ یادگیری.
 * اگر فایل کد را با نام یا در پوشهٔ دیگری نصب کنید، آموخته‌ها همراهش
 * نمی‌آیند چون کنار خودِ فایل ذخیره می‌شوند. با این دو اندپوینت می‌شود
 * حافظه را از نصب قبلی بیرون کشید و در نصب تازه ریخت.
 */
/* v10.12 (۲۵): مدیریتِ حافظهٔ «دسته‌های امتحان‌شده».
   op=stats  ⇒ آمار کلی
   op=list   ⇒ تلاش‌های یک محصول (برای نمایش زیر ردیفِ فاز ۲)
   op=clear  ⇒ پاک‌کردنِ یک محصول (pid) یا کلِ حافظه (pid=0) */
if (($_POST['action'] ?? '') === 'cat_tried') {
    header('Content-Type: application/json; charset=UTF-8');
    $op  = (string)($_POST['op'] ?? 'stats');
    $pid = (int)($_POST['pid'] ?? 0);
    if ($op === 'clear') {
        $n = catTriedClear($pid);
        echo json_encode(['ok' => true, 'cleared' => $n,
            'msg' => $pid > 0 ? 'حافظهٔ تلاش این محصول پاک شد' : 'کل حافظهٔ تلاش‌ها پاک شد (' . aiFaNum($n) . ' محصول)'],
            JSON_UNESCAPED_UNICODE); exit;
    }
    if ($op === 'list') {
        $row = catTriedRow($pid);
        $out = [];
        foreach ((array)($row['tried'] ?? []) as $cid => $info) {
            $out[] = ['id' => (int)$cid, 'name' => (string)($info['name'] ?? ''),
                      'n' => (int)($info['n'] ?? 1), 'at' => (int)($info['at'] ?? 0),
                      'by' => (string)($info['by'] ?? ''), 'res' => (string)($info['res'] ?? '')];
        }
        usort($out, function ($a, $b) { return $b['at'] <=> $a['at']; });
        echo json_encode(['ok' => true, 'pid' => $pid, 'cur' => (int)($row['cur'] ?? 0),
                          'title' => (string)($row['t'] ?? ''), 'tried' => $out], JSON_UNESCAPED_UNICODE); exit;
    }
    echo json_encode(['ok' => true] + catTriedStats(), JSON_UNESCAPED_UNICODE); exit;
}

if (($_POST['action'] ?? '') === 'catlearn_import') {
    header('Content-Type: application/json; charset=UTF-8');
    $inc = json_decode((string)($_POST['data'] ?? '{}'), true);
    if (!is_array($inc) || empty($inc)) {
        echo json_encode(['ok' => false, 'error' => 'داده‌ای برای درون‌ریزی نیست'], JSON_UNESCAPED_UNICODE); exit;
    }
    $replace = !empty($_POST['replace']);
    $cur = $replace ? [] : catLearnLoad();
    $added = 0; $merged = 0;
    foreach ($inc as $w => $row) {
        $w = (string)$w;
        if ($w === '' || !is_array($row) || empty($row['cats']) || !is_array($row['cats'])) continue;
        if (!isset($cur[$w])) { $cur[$w] = $row; $added++; continue; }
        // ادغام: شمارش‌ها جمع می‌شوند تا انتخاب پرتکرارتر برنده بماند
        foreach ($row['cats'] as $cid => $info) {
            $cid = (string)$cid;
            $prevN = (int)($cur[$w]['cats'][$cid]['n'] ?? 0);
            $cur[$w]['cats'][$cid] = [
                'n'    => $prevN + (int)($info['n'] ?? 0),
                'name' => (string)($info['name'] ?? ($cur[$w]['cats'][$cid]['name'] ?? '')),
                'at'   => max((int)($info['at'] ?? 0), (int)($cur[$w]['cats'][$cid]['at'] ?? 0)),
            ];
        }
        $cur[$w]['n'] = (int)($cur[$w]['n'] ?? 0) + (int)($row['n'] ?? 0);
        $cur[$w]['last'] = max((int)($cur[$w]['last'] ?? 0), (int)($row['last'] ?? 0));
        $merged++;
    }
    catLearnSave($cur);
    echo json_encode(['ok' => true, 'added' => $added, 'merged' => $merged,
        'total' => count($cur), 'replaced' => $replace], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['catlearn'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $d = catLearnLoad();

    // v8.62: برون‌بری کامل برای انتقال به نصب دیگر
    if (!empty($_GET['export'])) {
        echo json_encode(['ok' => true, 'count' => count($d), 'file' => CATLEARN_FILE,
            'exported_at' => time(), 'data' => $d], JSON_UNESCAPED_UNICODE); exit;
    }

    $forget = trim((string)($_GET['forget'] ?? ''));
    if ($forget !== '') {
        $w = catFirstWord($forget) ?: $forget;
        unset($d[$w]);
        catLearnSave($d);
        echo json_encode(['ok' => true, 'forgot' => $w, 'left' => count($d)], JSON_UNESCAPED_UNICODE); exit;
    }
    if (!empty($_GET['clear'])) {
        catLearnSave([]);
        echo json_encode(['ok' => true, 'cleared' => true], JSON_UNESCAPED_UNICODE); exit;
    }
    $test = trim((string)($_GET['test'] ?? ''));
    if ($test !== '') {
        // v8.60: هر دور را جداگانه نشان بده تا معلوم شود کدام طول جواب داد
        $maxN = catLearnWordCount();
        $rounds = [];
        for ($i = 1; $i <= $maxN; $i++) {
            $k = catFirstWords($test, $i);
            $rounds[] = ['words' => $i, 'key' => $k, 'cat_id' => catLearnBestFor($k, $d)];
        }
        echo json_encode(['ok' => true, 'title' => $test, 'first_word' => catFirstWord($test),
            'word_count' => $maxN, 'rounds' => $rounds,
            'learned_cat' => catLearnLookup($test, $d)], JSON_UNESCAPED_UNICODE); exit;
    }

    $rows = [];
    foreach ($d as $w => $row) {
        if (!is_array($row)) continue;
        $bestId = 0; $bestN = 0; $bestName = '';
        foreach (($row['cats'] ?? []) as $cid => $info) {
            if ((int)($info['n'] ?? 0) > $bestN) {
                $bestN = (int)$info['n']; $bestId = (int)$cid;
                $bestName = (string)($info['name'] ?? '');
            }
        }
        $rows[] = ['word' => $w, 'cat_id' => $bestId, 'cat_name' => $bestName,
                   'times' => $bestN, 'total' => (int)($row['n'] ?? 0),
                   'variants' => count($row['cats'] ?? []), 'last' => (int)($row['last'] ?? 0)];
    }
    usort($rows, fn($a, $b) => $b['last'] <=> $a['last']);
    echo json_encode(['ok' => true, 'count' => count($rows),
        'rows' => array_slice($rows, 0, 300)], JSON_UNESCAPED_UNICODE);
    exit;
}

/** v8.33: بررسی/ادامهٔ دستی صف گیرکرده */
if (isset($_GET['queue_watchdog'])) {
    ob_clean();
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $after = (int)($_GET['after'] ?? ($cn['stall_after'] ?? 300));
    $dry   = !empty($_GET['dry']);
    $which = (string)($_GET['which'] ?? 'both');
    $out = [];
    foreach (($which === 'both' ? ['bsl', 'woo'] : [$which]) as $wq) {
        if ($wq !== 'bsl' && $wq !== 'woo') continue;
        $out[] = queueStallRecover($wq, max(30, $after), $dry);
    }
    echo json_encode(['ok' => true, 'checks' => $out], JSON_UNESCAPED_UNICODE);
    exit;
}

