// v8.19: Re-scrape a profile using its manual selectors. Returns updated products array.
// If selectors are empty, returns null (caller should use saved products).
/* =====================================================================
 *  v8.29: اعلان‌های باسلام
 *  به سه بررسی مستقل تقسیم شده تا هرکدام دکمهٔ تست جدا داشته باشند و
 *  در کران‌جاب هم به ترتیب اولویت اجرا شوند.
 * ===================================================================== */


/** v10.79 (93): لاگِ تلاش‌هایِ پینگ — ۳۰ آخرین، برایِ عیب‌یابیِ
    «کجا گیر کرده» بدونِ گمان‌زنی. */
function notifPingLog(array $entry): void {
    $f = __DIR__ . '/notif_ping_log.json';
    $d = json_decode((string)@file_get_contents($f), true);
    $list = (is_array($d) && is_array($d['log'] ?? null)) ? $d['log'] : [];
    array_unshift($list, $entry + ['at' => time(), 'time' => date('Y-m-d H:i:s')]);
    @file_put_contents($f, json_encode(['log' => array_slice($list, 0, 30)], JSON_UNESCAPED_UNICODE), LOCK_EX);
}
function notifPingSrc(array $results, bool $force): string {
    if ($force) return 'دستی';
    if (!empty($results['heartbeat'])) return 'نبضِ کران';
    if (array_key_exists('locked', $results)) return 'قفل';
    return 'کران';
}
function notifLoadState(): array {
    if (!is_file(NOTIF_STATE_FILE)) return [];
    $d = json_decode((string)@file_get_contents(NOTIF_STATE_FILE), true);
    return is_array($d) ? $d : [];
}

function notifSaveState(array $st): void {
    @file_put_contents(NOTIF_STATE_FILE, json_encode($st, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/* =====================================================================
 *  v8.38: پیگیری تک‌تک موارد + یادآوری
 *
 *  تا نسخهٔ ۸.۳۷ فقط یک «زمان آخرین بررسی» ذخیره می‌شد. یعنی هر مورد
 *  دقیقاً یک بار اعلان می‌شد و بعد برای همیشه ساکت می‌ماند — حتی اگر
 *  پیام مشتری بی‌جواب مانده بود.
 *
 *  حالا وضعیت هر مورد جداگانه نگه داشته می‌شود:
 *    • مورد تازه            → اعلان
 *    • وضعیتش عوض شده       → اعلان (رویداد تازه است)
 *    • بی‌تغییر ولی بی‌جواب  → بعد از فاصلهٔ تعیین‌شده، یادآوری
 *    • جواب داده شده        → دیگر یادآوری نمی‌شود
 * ===================================================================== */

/** تنظیمات یادآوری: فاصله (ثانیه) و سقف تعداد */
function notifRemindCfg(array $cn): array {
    $after = $cn['notif_remind_after'] ?? 30;      // دقیقه
    $after = (int)$after;
    if ($after < 0) $after = 0;                    // ۰ = یادآوری خاموش
    $max = (int)($cn['notif_remind_max'] ?? 0);    // ۰ = بی‌نهایت
    return ['after' => $after * 60, 'max' => max(0, $max)];
}

/**
 * تصمیم می‌گیرد برای یک مورد اعلان بفرستیم یا نه.
 *
 * $sig امضای وضعیت است؛ اگر عوض شود یعنی اتفاق تازه‌ای افتاده.
 * $pending یعنی هنوز کاری برایش لازم است (پیام بی‌جواب، سفارش ارسال‌نشده).
 *
 * خروجی: '' یعنی نفرست · 'new' · 'changed' · 'remind'
 */
function notifDecide(array &$st, string $key, string $sig, bool $pending,
                     array $cfg, int $now): string {
    if (!isset($st['items']) || !is_array($st['items'])) $st['items'] = [];
    $prev = $st['items'][$key] ?? null;

    if (!is_array($prev)) {
        $st['items'][$key] = ['sig' => $sig, 'first' => $now, 'last' => $now,
                              'n' => 1, 'pending' => $pending];
        return 'new';
    }
    if ((string)($prev['sig'] ?? '') !== $sig) {
        // امضا عوض شده — مثلاً پیام تازه رسیده یا وضعیت سفارش تغییر کرده
        $st['items'][$key] = ['sig' => $sig, 'first' => (int)($prev['first'] ?? $now),
                              'last' => $now, 'n' => 1, 'pending' => $pending];
        return 'changed';
    }
    // همان وضعیت قبلی
    if (!$pending) { $st['items'][$key]['pending'] = false; return ''; }
    if ($cfg['after'] <= 0) return '';
    if ($now - (int)($prev['last'] ?? 0) < $cfg['after']) return '';
    $n = (int)($prev['n'] ?? 1);
    if ($cfg['max'] > 0 && $n > $cfg['max']) return '';   // سقف یادآوری پر شده
    $st['items'][$key]['last'] = $now;
    $st['items'][$key]['n'] = $n + 1;
    $st['items'][$key]['pending'] = true;
    return 'remind';
}

/**
 * موارد قدیمی و تمام‌شده را پاک می‌کند تا فایل وضعیت بی‌نهایت بزرگ نشود.
 * موارد بی‌جواب نگه داشته می‌شوند چون هنوز باید یادآوری شوند.
 */
function notifPrune(array &$st, int $now, int $maxAge = 604800): void {
    if (empty($st['items']) || !is_array($st['items'])) return;
    foreach ($st['items'] as $k => $v) {
        if (!is_array($v)) { unset($st['items'][$k]); continue; }
        $age = $now - (int)($v['last'] ?? 0);
        if (empty($v['pending']) && $age > 86400)   { unset($st['items'][$k]); continue; }
        if ($age > $maxAge)                          { unset($st['items'][$k]); }
    }
    // سقف سخت، برای وقتی غرفه خیلی شلوغ است
    if (count($st['items']) > 500) {
        uasort($st['items'], fn($a, $b) => (int)($b['last'] ?? 0) <=> (int)($a['last'] ?? 0));
        $st['items'] = array_slice($st['items'], 0, 500, true);
    }
}

/**
 * هنگام ارتقا از نسخه‌های قبلی، موارد قدیمی را بی‌صدا ثبت می‌کند.
 * بدون این کار، اولین اجرا هر ۱۰ مورد موجود را «تازه» می‌دید و یک‌جا
 * ۱۰ پیام می‌فرستاد.
 */
function notifSeedIfNeeded(array &$st, string $kind, array $seen, int $watermark): bool {
    $flag = 'seeded_' . $kind;
    if (!empty($st[$flag])) return false;
    if (!isset($st['items']) || !is_array($st['items'])) $st['items'] = [];
    if ($watermark > 0) {
        foreach ($seen as $s) {
            // فقط مواردی که قبلاً هم بوده‌اند؛ موارد تازه‌تر باید اعلان شوند
            if ((int)$s['ts'] > 0 && (int)$s['ts'] <= $watermark) {
                $st['items'][$s['key']] = ['sig' => $s['sig'], 'first' => (int)$s['ts'],
                    'last' => $watermark, 'n' => 1, 'pending' => !empty($s['pending'])];
            }
        }
    }
    $st[$flag] = time();
    return true;
}

/** سرتیتر پیام بر اساس نوع رویداد */
function notifHead(string $why, string $base, int $n = 0): string {
    if ($why !== 'remind') return $base;
    $tag = '🔁 یادآوری' . ($n > 1 ? ' (' . $n . ')' : '');
    return $base === '' ? $tag : $tag . ' — ' . $base;
}

/* =====================================================================
 *  v10.45 (۵۹): یک منبعِ حق برای «این رویداد روشن است؟»
 *
 *  تا اینجا رابطِ کاربری نبودِ کلید را «روشن» نشان می‌داد
 *  (checked = ne.X !== false) ولی سرور آن را «خاموش» می‌شمرد
 *  (!empty(...)). یعنی تیک روشن بود و هیچ رویدادی ارسال نمی‌شد —
 *  دقیقاً همان «اعلان‌ها نمی‌آیند» که دلیلش هیچ‌جا دیده نمی‌شد.
 *  حالا دو طرف روی یک توافق‌اند: نبودِ کلید = روشن (همان چیزی که
 *  رابط پیش‌فرض نشان می‌دهد)، روشنِ صریح = روشن، خاموشِ صریح = خاموش.
 *  تنها استثنای cron_ping است که در هر دو طرف پیش‌فرضِ خاموش دارد
 *  (وگرنه بدون فاصلهٔ throttle روزی ۲۸ پیام می‌شد).
 * ===================================================================== */
function notifEventOn(array $ne, string $key): bool {
    if ($key === 'cron_ping') return !empty($ne['cron_ping']);
    if (!array_key_exists($key, $ne)) return true;
    return !empty($ne[$key]);
}

/** ارسال یک پیام به همهٔ پیام‌رسان‌های فعال */
/* v10.66 (۸۰): فیدِ رویداد — هر رویدادی که به پیام‌رسان رفته، اینجا هم می‌نشیند
   تا مرورگر (کارتِ زنده + اعلانِ سیستم) آن را ببیند. چت استثناست: مرورگر
   خودش هر ۵ ثانیه چت‌ها را مستقیم می‌پوید و تکرار نمی‌خواهد. */
function liveFeedPush(string $kind, string $msg): void {
    try {
        $f = LIVE_FEED_FILE;
        $d = is_file($f) ? (json_decode((string)@file_get_contents($f), true) ?: []) : [];
        $ev = is_array($d['events'] ?? null) ? $d['events'] : [];
        $flat = trim((string)preg_replace('/\s+/u', ' ', $msg));
        $ev[] = ['ts' => time(), 'kind' => $kind, 'msg' => mb_substr($flat, 0, 600)];
        $ev = array_slice($ev, -80);
        @file_put_contents($f, json_encode(['events' => $ev], JSON_UNESCAPED_UNICODE), LOCK_EX);
    } catch (Throwable $e) { /* فید نباید اعلان را قطع کند */ }
}
function liveFeedLoad(int $since = 0): array {
    try {
        if (!is_file(LIVE_FEED_FILE)) return [];
        $d = json_decode((string)@file_get_contents(LIVE_FEED_FILE), true) ?: [];
        $ev = is_array($d['events'] ?? null) ? $d['events'] : [];
        if ($since > 0) $ev = array_values(array_filter($ev, fn($e) => (int)($e['ts'] ?? 0) > $since));
        return array_slice($ev, -80);
    } catch (Throwable $e) { return []; }
}
/* =====================================================================
   v10.72 (86): Web Push — مسیرِ «واقعی»ِ اعلانِ سیستم.

   چرا: اعلانِ سطحِ صفحه (new Notification یا showNotificationِ صدا
   زده‌شده از صفحه) روی دسکتاپ خوب است، ولی روی اندروید وقتی کاربر
   گوشی را قفل می‌کند یا اپ را عوض می‌کند، اندروید جاوااسکریپتِ صفحه
   را در عرضِ چند ثانیه می‌کُشد — پس اعلان‌هایِ «واقعی» (رویدادهایی که
   در زمانِ بسته‌بودنِ صفحه اتفاق می‌افتند) هرگز نمایش داده نمی‌شوند. Web Push تنها
   مسیرِ مطمئن است: سرور اعلان را به سرویسِ push می‌فرستد، و سرویس
   سرویس‌ورکرِ سایت را روی گوشیِ کاربر بیدار می‌کند و اعلان را
   نمایش می‌دهد — حتی اگر صفحه هرگز باز نباشد.

   چرخه: مرورگر با کلیدِ عمومیِ VAPID subscribe می‌کند و اشتراک روی
   سرور ذخیره می‌شود (فایل push_subscriptions.json). با هر رویدادی که
   باید به پیام‌رسان برود، webpushSend اعلان را به همهٔ اشتراک‌ها
   می‌فرستد (curl_multi موازی، TTL کوتاه). رمزگذاری بر اساس RFC 8291
   (authE2048): ECDH P-256 + HKDF + AES-128-GCM، امضای JWT با ES256.
   ===================================================================== */
function pushB64url($bytes): string {
    return rtrim(strtr(base64_encode($bytes), '+/', '-_'), '=');
}
function pushB64urlDecode(string $s): ?string {
    $b = strtr($s, '-_', '+/');
    $pad = strlen($b) % 4;
    if ($pad === 1) return null;
    if ($pad === 2) $b .= '==';
    elseif ($pad === 3) $b .= '=';
    $raw = base64_decode($b, true);
    return $raw === false ? null : $raw;
}
function pushSpkiFromRawPoint(string $raw65): string {
    return "\x30\x59\x30\x13\x06\x07\x2a\x86\x48\xce\x3d\x02\x01"
         . "\x06\x08\x2a\x86\x48\xce\x3d\x03\x01\x07\x03\x42\x00" . $raw65;
}
function pushEcdhRaw($privRes, string $peerSpkiDer): ?string {
    $peerRes = openssl_pkey_get_public($peerSpkiDer);
    if (!$peerRes || !$privRes) return null;
    $ss = openssl_pkey_derive($peerRes, $privRes);
    return ($ss === false || $ss === null) ? null : $ss;
}
function pushHkdfExpand(string $prk, string $info, int $len): string {
    $t = ''; $tm = ''; $i = 1;
    while (strlen($t) < $len) {
        $tm = hash_hmac('sha256', $tm . $info . chr($i), $prk, true);
        $t .= $tm; $i++;
    }
    return substr($t, 0, $len);
}
function pushAes128GcmEncrypt(string $key, string $iv, string $aad, string $pt): ?string {
    $tag = '';
    $ct = openssl_encrypt($pt, 'aes-128-gcm', $key, OPENSSL_RAW_DATA, $iv, $tag, $aad, 16);
    if ($ct === false || strlen($tag) !== 16) return null;
    return $ct . $tag;
}
function pushLoadSubs(): array {
    $d = json_decode((string)@file_get_contents(PUSH_SUBS_FILE), true);
    return (is_array($d) && is_array($d['subs'] ?? null)) ? $d['subs'] : [];
}
function pushSaveSubs(array $subs): bool {
    return @file_put_contents(PUSH_SUBS_FILE, json_encode(['subs' => $subs, 'at' => time()], JSON_UNESCAPED_UNICODE), LOCK_EX) !== false;
}
function pushUpsertSub(array $sub): bool {
    $subs = pushLoadSubs();
    $ep = (string)($sub['endpoint'] ?? '');
    $p256 = (string)($sub['keys']['p256dh'] ?? '');
    $auth = (string)($sub['keys']['auth'] ?? '');
    if ($ep === '' || $p256 === '' || $auth === '') return false;
    $subs[$ep] = ['endpoint' => $ep,
                  'keys' => ['p256dh' => $p256, 'auth' => $auth],
                  'at' => time()];
    $subs = array_slice($subs, -30, null, true);   // سقف ۳۰ اشتراک
    return pushSaveSubs($subs);
}
function pushDropSub(string $endpoint): void {
    $subs = pushLoadSubs();
    if (isset($subs[$endpoint])) {
        unset($subs[$endpoint]);
        pushSaveSubs($subs);
    }
}
function pushDerToRawSig(string $der): ?string {
    if (strlen($der) < 8 || ord($der[0]) !== 0x30) return null;
    $len = ord($der[1]);
    if ($len < 2 || 2 + $len > strlen($der)) return null;
    $i = 2; $parts = [];
    for ($n = 0; $n < 2; $n++) {
        if ($i + 2 > strlen($der) || ord($der[$i]) !== 0x02) return null;
        $il = ord($der[$i + 1]);
        if ($i + 2 + $il > strlen($der)) return null;
        $val = substr($der, $i + 2, $il);
        $val = ltrim($val, "\x00");
        if (strlen($val) > 32) return null;
        $parts[] = str_pad($val, 32, "\x00", STR_PAD_LEFT);
        $i += 2 + $il;
    }
    return $parts[0] . $parts[1];
}
function webpushVapidJwt(string $aud): ?string {
    $priv = openssl_pkey_get_private(base64_decode(VAPID_PRIVATE_KEY_B64));
    if (!$priv) return null;
    $h = pushB64url(json_encode(['typ' => 'JWT', 'alg' => 'ES256']));
    $p = pushB64url(json_encode(['aud' => $aud, 'exp' => time() + 120, 'iat' => time(), 'sub' => VAPID_SUBJECT]));
    $sigInput = $h . '.' . $p;
    if (!openssl_sign($sigInput, $derSig, $priv, OPENSSL_ALGO_SHA256)) return null;
    $raw = pushDerToRawSig($derSig);
    if ($raw === null || strlen($raw) !== 64) return null;
    return $sigInput . '.' . pushB64url($raw);
}
function webpushBuildRequest(string $endpoint, array $keys, string $payloadJson): ?array {
    $detRaw = pushB64urlDecode((string)($keys['p256dh'] ?? ''));
    $serverRaw = pushB64urlDecode(VAPID_PUBLIC_KEY_B64URL);
    if ($detRaw === null || strlen($detRaw) !== 65 || $detRaw[0] !== "\x04") return null;
    if (pushB64urlDecode((string)($keys['auth'] ?? '')) === null) return null;
    if ($serverRaw === null || strlen($serverRaw) !== 65) return null;
    $epriv = openssl_pkey_new(['curve_name' => 'prime256v1']);
    if (!$epriv) return null;
    $ss = pushEcdhRaw($epriv, pushSpkiFromRawPoint($detRaw));
    if ($ss === null) return null;
    $ccek        = hash_hkdf('sha256', $ss, '', 'Content Cryptography Key', 16, true);
    $contentSalt = hash_hkdf('sha256', $ss, '', 'Content Salt', 16, true);
    $headerSalt  = hash_hkdf('sha256', $ss, '', 'Header Salt', 16, true);
    $iv = random_bytes(12);
    $ct = pushAes128GcmEncrypt($ccek, $iv, $contentSalt, $payloadJson);
    if ($ct === null) return null;
    $body = $iv . $ct;
    /* نقطهٔ ephemeral برای هدرها: P256ECWSK + r1/r2 */
    $det = openssl_pkey_get_details($epriv);
    $epubRaw = '';
    if (is_array($det) && !empty($det['ec']['x']) && !empty($det['ec']['y'])) {
        $x = ltrim($det['ec']['x'], "\x00");
        $y = ltrim($det['ec']['y'], "\x00");
        if (strlen($x) > 32 || strlen($y) > 32) return null;
        $epubRaw = "\x04" . str_pad($x, 32, "\x00", STR_PAD_LEFT) . str_pad($y, 32, "\x00", STR_PAD_LEFT);
    }
    if (strlen($epubRaw) !== 65) return null;
    $r1 = substr($epubRaw, 1, 32);
    $r2 = substr($epubRaw, 33, 16);
    $b64Server = pushB64url($serverRaw);
    $b64User   = pushB64url($detRaw);
    $aad = "BePush2.0\x01" . $r2 . $b64Server . $b64User . $endpoint . "\x00\x01";
    $host = parse_url($endpoint, PHP_URL_HOST);
    if (empty($host)) return null;
    $jwt = webpushVapidJwt(parse_url($endpoint, PHP_URL_SCHEME) . '://' . $host);
    if ($jwt === null) return null;
    $headers = [
        'Authorization: WebPush ' . $jwt,
        'Content-Encoding: authE2048',
        'Content-Length: ' . strlen($body),
        'TTL: 60',
        'Crypto-Key: keyid="",r1=' . pushB64url($r1) . ',r2=' . pushB64url($r2),
        'P256ECWSK: ' . pushB64url($epubRaw),
        'AAD: ' . pushB64url($aad),
    ];
    return ['headers' => $headers, 'body' => $body];
}
/** v10.74 (88): مسیرهایِ ارسالِ Push — مستقیم / پراکسیِ خارجی / Workerِ واسط.
    هاست‌هایِ داخلِ ایران به fcm.googleapis.com دسترسی ندارند؛ برای همین
    دو مسیرِ جایگزین روی تنظیماتِ کاربر ذخیره شده و فقط وقتی مسیرِ مستقیم
    اتصالِ برقرار نمی‌کند (HTTP 0) به کار می‌افتند. */
/* v10.80 (94): پارامتر اختیاری شد — فراخوانی‌هایِ بدونِ آرگومان
   (webpushSend و اندپوینتِ push_status) قبلاً fatal «Too few
   arguments» می‌دادند و از نسخهٔ ۱۰.۷۴ تمامِ ارسالِ اعلان را قطع
   کرده بودند (همِ «هیچ اعلانی نمی‌آید» و هم «خطای شبکه» دکمهٔ پینگ). */
function pushRouteCfg(?array $cn = null): array {
    $cn = $cn ?: loadConnections();
    $pr = is_array($cn['push_route'] ?? null) ? $cn['push_route'] : [];
    $proxy = trim((string)($pr['proxy'] ?? ''));
    $source = 'push_route';
    if ($proxy === '') {
        /* v10.76 (90): اگر کاربر مسیرِ جداگانهٔ Push نگذاشته، از همان
           اتصالِ غیرمستقیمی که برایِ عبورِ «هوش مصنوعی» یا «سایت مبدأ»
           تنظیم کرده استفاده می‌شود (قالبِ {url} یا آدرسِ proxy.php). */
        foreach (['ai_net', 'src_net'] as $k) {
            $w = trim((string)($cn[$k]['worker_url'] ?? ''));
            if ($w === '') continue;
            if (strpos($w, '{url}') !== false) { $proxy = $w; $source = $k; break; }
            $pb = (string)(parse_url($w, PHP_URL_PATH) ?? '');
            $bn = strtolower(basename($pb));
            if ($bn !== '' && substr($bn, -4) === '.php') { $proxy = $w; $source = $k; break; }
        }
    }
    return [
        'proxy'  => $proxy,
        'worker' => trim((string)($pr['worker_url'] ?? '')),
        'token'  => (string)($pr['worker_token'] ?? ''),
        'site_source' => $source,
    ];
}
/** یک دورِ ارسال روی یک مسیر؛ برمی‌گرداند فهرستِ endpointهایی که هنوز
    ارسالِ برقرار نشد (فقط اتصالِ ناموفق = HTTP 0) تا دورِ بعد امتحان شود.
    v10.75 (89): مسیرِ تازهٔ «site_proxy» — انتقالِ شفاف از طریقِ
    interface.php (اتصالِ غیرمستقیمِ خودِ سایت): POST {base}?url={endpoint}
    با همان سردر و بدنهٔ Web Push؛ پاسخِ سرویسِ مقصد عیناً برمی‌گردد. */
function pushSendRound(array $pending, array $routeCfg, array $viaCfg, string $via, array &$detail, array &$drop): array {
    if (!$pending) return $pending;
    $mh = curl_multi_init(); $chs = [];
    foreach ($pending as $ep => $req) {
        $ch = curl_init();
        if ($via === 'worker') {
            $wBody = json_encode(['url' => $req['endpoint'], 'headers' => $req['headers'], 'body_b64' => base64_encode($req['body'])], JSON_UNESCAPED_UNICODE);
            $wHeaders = ['Content-Type: application/json'];
            if ($routeCfg['token'] !== '') $wHeaders[] = 'X-Push-Auth: ' . $routeCfg['token'];
            curl_setopt_array($ch, [CURLOPT_URL => $routeCfg['worker'], CURLOPT_POST => true, CURLOPT_POSTFIELDS => $wBody,
                CURLOPT_HTTPHEADER => $wHeaders, CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 25, CURLOPT_CONNECTTIMEOUT => 10]);
        } elseif ($via === 'site_proxy') {
            /* اتصالِ غیرمستقیمِ خودِ سایت (interface.php) — انتقالِ شفاف:
               پراکسی سردرها و بدنه را بدونِ تغییر به fcm.googleapis.com می‌دهد
               و وضعیت/بدنهٔ پاسخ را عیناً برمی‌گرداند. */
            /* قالبِ {url} (همان قالبِ عبورِ هوش مصنوعی/مبدأ) یا آدرسِ ساده */
            $pu = strpos($viaCfg['url'], '{url}') !== false
                ? str_replace('{url}', rawurlencode($req['endpoint']), $viaCfg['url'])
                : $viaCfg['url'] . (strpos($viaCfg['url'], '?') !== false ? '&' : '?') . 'url=' . rawurlencode($req['endpoint']);
            curl_setopt_array($ch, [CURLOPT_URL => $pu,
                CURLOPT_POST => true, CURLOPT_POSTFIELDS => $req['body'],
                CURLOPT_HTTPHEADER => $req['headers'],
                CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 40, CURLOPT_CONNECTTIMEOUT => 12, CURLOPT_SSL_VERIFYPEER => true]);
        } else {
            $opt = [CURLOPT_URL => $req['endpoint'], CURLOPT_POST => true, CURLOPT_POSTFIELDS => $req['body'],
                CURLOPT_HTTPHEADER => $req['headers'], CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 12,
                CURLOPT_CONNECTTIMEOUT => 8, CURLOPT_SSL_VERIFYPEER => true];
            if ($via === 'proxy') {
                $opt[CURLOPT_PROXY] = $viaCfg['url'];
                if ($viaCfg['auth'] !== '') $opt[CURLOPT_PROXYUSERPWD] = $viaCfg['auth'];
            }
            curl_setopt_array($ch, $opt);
        }
        curl_multi_add_handle($mh, $ch);
        $chs[(string)$ep] = $ch;
    }
    $left = $pending;
    if ($chs) {
        do {
            $act = curl_multi_exec($mh, $running);
            if ($running > 0) curl_multi_select($mh, 0.2);
        } while ($running > 0);
        foreach ($chs as $ep => $ch) {
            $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
            $err = (string)curl_error($ch);
            $resp = (string)curl_result($ch);
            if ($via === 'worker' && $code >= 200 && $code < 300) {
                // Worker زنده است — وضعیتِ واقعیِ سرویسِ Push را از پاسخِ خودِ Worker بخوان
                $wj = json_decode($resp, true);
                if (is_array($wj) && isset($wj['status'])) $code = (int)$wj['status'];
                else $err = 'پاسخِ Worker خوانا نبود';
            }
            if ($code < 200 || $code >= 300) {
                /* v10.75 (89): پیامِ خطایِ JSONِ پراکسی/Worker را خوانا نشان بده */
                $ej = json_decode($resp, true);
                if (is_array($ej) && !empty($ej['message'])) $err = $ej['message'];
                elseif ($err === '' && $resp !== '' && strlen($resp) < 200) $err = trim($resp);
                if ($via === 'site_proxy' && $code === 403) $err .= ' — fcm.googleapis.com را به فهرستِ PROXY_TARGET_HOSTSِ interface.php اضافه کنید';
            }
            curl_multi_remove_handle($mh, $ch);
            curl_close($ch);
            $detail[(string)$ep] = ['via' => $via, 'code' => $code, 'error' => $err];
            if ($code >= 200 && $code < 300) { unset($left[(string)$ep]); }
            elseif (in_array($code, [404, 410], true)) { unset($left[(string)$ep]); $drop[] = (string)$ep; }
            elseif ($code === 0) { /* اتصال برقرار نشد — این endpoint برای دورِ بعد می‌ماند */ }
            else { unset($left[(string)$ep]); }
        }
    }
    curl_multi_close($mh);
    return $left;
}
function webpushSend(string $title, string $body, ?string $kind = null, ?array $cn = null): array {
    $subs = pushLoadSubs();
    if (!$subs) return ['sent' => 0, 'failed' => 0, 'total' => 0, 'detail' => []];
    $payload = json_encode(['title' => $title, 'body' => $body,
                            'kind' => $kind ?? '', 'tag' => 'mr_push_' . ($kind ?? 'event'),
                            'requireInteraction' => true, 'at' => time()], JSON_UNESCAPED_UNICODE);
    $routeCfg = pushRouteCfg();
    $proxyUrl = ''; $proxyAuth = '';
    if ($routeCfg['proxy'] !== '' && stripos($routeCfg['proxy'], '@') !== false) {
        $at = stripos($routeCfg['proxy'], '@');
        $proxyAuth = substr($routeCfg['proxy'], 0, $at);
        $proxyUrl = substr($routeCfg['proxy'], $at + 1);
    } else {
        $proxyUrl = $routeCfg['proxy'];
    }
    $pending = []; $detail = []; $drop = [];
    foreach ($subs as $ep => $sub) {
        $req = webpushBuildRequest((string)$sub['endpoint'], (array)($sub['keys'] ?? []), $payload);
        if ($req === null) { $drop[] = (string)$ep; $detail[(string)$ep] = ['via' => '-', 'code' => 0, 'error' => 'ساختِ درخواست ناموفق']; continue; }
        $pending[(string)$ep] = ['endpoint' => (string)$sub['endpoint'], 'headers' => $req['headers'], 'body' => $req['body']];
    }
    /* v10.75 (89): زنجیرهٔ مسیرها — اول مستقیم؛ اگر اتصال برقرار نشود،
       اتصالِ غیرمستقیمِ خودِ سایت (interface.php)؛ بعد (اختیاری) Worker.
       هاستِ خارجی (دسترسیِ مستقیم) هرگز مسیرِ دوم را لمس نمی‌کند. */
    $pending = pushSendRound($pending, $routeCfg, [], 'direct', $detail, $drop);
    if ($proxyUrl !== '' && $pending) $pending = pushSendRound($pending, $routeCfg, ['url' => $proxyUrl, 'auth' => $proxyAuth], ($proxyAuth !== '' ? 'proxy' : 'site_proxy'), $detail, $drop);
    if ($routeCfg['worker'] !== '' && $pending) $pending = pushSendRound($pending, $routeCfg, ['url' => $routeCfg['worker']], 'worker', $detail, $drop);
    foreach (array_keys($pending) as $ep) $detail[(string)$ep] = $detail[(string)$ep] ?? ['via' => '-', 'code' => 0, 'error' => 'هیچ مسیری جواب نداد'];
    if ($drop) { foreach (array_unique($drop) as $d) pushDropSub($d); }
    $sent = 0; $failed = 0;
    foreach ($detail as $v) {
        $c = (int)($v['code'] ?? 0);
        if (in_array($c, [404, 410], true)) continue;
        if ($c >= 200 && $c < 300) $sent++;
        else $failed++;
    }
    return ['sent' => $sent, 'failed' => $failed, 'total' => count($subs), 'detail' => $detail];
}
function notifSend(array $cn, string $msg, ?string $feed = null, array $media = []): array {
    $out = [];
    $bt = $cn['baleh']['token'] ?? '';  $bc = $cn['baleh']['chat_id'] ?? '';
    $rt = $cn['rubika']['token'] ?? ''; $rc = $cn['rubika']['chat_id'] ?? '';
    $tt = $cn['telegram']['token'] ?? ''; $tc = $cn['telegram']['chat_id'] ?? '';   // v10.78 (92): تلگرام
    /* v10.109: لینک‌های داخل متن — پیش‌نمایش وب برای تلگرام/بله */
    $wantPreview = $media !== [] || (bool)preg_match('~https?://\S+~u', $msg);
    if ($bt !== '' && $bc !== '')  { $rb = bslSendToBaleh($bt, $bc, $msg, $wantPreview); $out['baleh'] = $rb['ok'] ? 'sent' : 'fail'; if (!$rb['ok'] && $rb['error'] !== '') $out['baleh_err'] = $rb['error']; if ($rb['ok'] && ($rb['message_id'] ?? '') !== '') { $out['baleh_msg_id'] = $rb['message_id']; msgrSaveMsg('bale', $rb['message_id'], 0, 0); } }   // v10.79 (93)
    if ($rt !== '' && $rc !== '')  { $rr = bslSendToRubika($rt, $rc, $msg); $out['rubika'] = $rr['ok'] ? 'sent' : 'fail'; if (!$rr['ok'] && $rr['error'] !== '') $out['rubika_err'] = $rr['error']; if ($rr['ok'] && ($rr['message_id'] ?? '') !== '') { $out['rubika_msg_id'] = $rr['message_id']; msgrSaveMsg('rubika', $rr['message_id'], 0, 0); } }
    if ($tt !== '' && $tc !== '')  { $tr = bslSendToTelegram($tt, $tc, $msg, $wantPreview); $out['telegram'] = $tr['ok'] ? 'sent' : 'fail'; if (!$tr['ok'] && $tr['error'] !== '') $out['telegram_err'] = $tr['error']; if ($tr['ok'] && ($tr['message_id'] ?? '') !== '') { $out['telegram_msg_id'] = $tr['message_id']; msgrSaveMsg('telegram', $tr['message_id'], 0, 0); } }
    /* v10.109: فوروارد چندرسانه‌ای (عکس/ویدیو/گیف/فایل/لینک) بعد از متن */
    if ($media) {
        $mediaSent = 0; $mediaFail = 0;
        foreach (array_slice($media, 0, 8) as $it) {
            if (!is_array($it) || trim((string)($it['url'] ?? '')) === '') continue;
            if ($bt !== '' && $bc !== '') {
                $r = bslSendMediaToMessenger('baleh', $bt, $bc, $it);
                if (!empty($r['ok'])) $mediaSent++; else $mediaFail++;
            }
            if ($tt !== '' && $tc !== '') {
                $r = bslSendMediaToMessenger('telegram', $tt, $tc, $it);
                if (!empty($r['ok'])) $mediaSent++; else $mediaFail++;
            }
            if ($rt !== '' && $rc !== '') {
                // روبیکا: API عمومی sendPhoto ندارد — لینک را متنی می‌فرستیم
                $r = bslSendMediaToMessenger('rubika', $rt, $rc, $it);
                if (!empty($r['ok'])) $mediaSent++; else $mediaFail++;
            }
        }
        if ($mediaSent > 0) $out['media_sent'] = $mediaSent;
        if ($mediaFail > 0) $out['media_fail'] = $mediaFail;
    }
    if (!$out) $out['none'] = 'no_messenger';
    if ($feed !== null) liveFeedPush($feed, $msg);   /* v10.66 (۸۰) */
    /* v10.72 (86): Web Push — در کنارِ پیام‌رسان، به دستگاهِ کاربر.
       رویدادها چه «لحظه‌ای» (درخواستِ مرورگر) باشند چه «کران‌جاب» —
       هر دو از همین تابع رد می‌شوند، پس هر دو Push می‌شوند. */
    if ($feed !== null && is_file(PUSH_SUBS_FILE)) {
        try {
            $_pt = ['order' => '🛒 سفارش', 'product' => '📦 محصول', 'price' => '💰 قیمت/موجودی',
                    'sync' => '🔄 همگام‌سازی', 'report' => '📄 گزارش', 'error' => '⚠️ خطا',
                    'retire' => '🗂 بازنشستگی', 'remind' => '⏰ یادآوری', 'ar' => '↩️ پاسخ خودکار',
                    'ping' => '💓 کران زنده است', 'digest' => '📊 خلاصه'];
            $out['push'] = webpushSend($_pt[$feed] ?? '🔔 اعلان', mb_substr($msg, 0, 400), (string)$feed, $cn);   // v10.77 (91): کانالِ نجوا
        } catch (Throwable $e) {}
    }
    return $out;
}

/**
 * v8.37: پیام «پینگ» برای اثبات اینکه خودِ کران‌جاب اجرا می‌شود.
 *
 * فرق این با «خطای اجرای خودکار»: آن وقتی می‌آید که کاری شکست بخورد،
 * ولی اگر کران‌جاب اصلاً اجرا نشود هیچ پیامی نمی‌آید و سکوت گمراه‌کننده
 * است. پینگ دقیقاً همین حالت را آشکار می‌کند.
 *
 * ⚠️ چون کران معمولاً هر ۵ دقیقه اجرا می‌شود، ارسال پیام در هر اجرا
 * روزی ۲۸۸ پیام می‌شود. برای همین یک فاصلهٔ زمانی (پیش‌فرض ۶ ساعت)
 * رعایت می‌شود؛ با ping_every=0 می‌توان هر اجرا را فرستاد.
 */
function notifCronPing(array $cn, array $results, bool $force = false): array {
    if (!$force && empty($cn['notif_events']['cron_ping'])) return ['ok' => true, 'skipped' => 'disabled'];
    /* v10.22 (۳۵الف): پینگ فقط به پیام‌رسان نیاز دارد، نه به باسلام.
       تا حالا notifPrereq() صدا زده می‌شد که علاوه بر پیام‌رسان، توکنِ
       باسلام و شناسهٔ غرفه را هم لازم می‌دانست. ولی پینگ اصلاً به باسلام
       کاری ندارد — فقط می‌گوید «کران‌جاب اجرا شد». نتیجه: هر کس توکنِ
       باسلامش منقضی/پاک شده بود یا فقط با غرفه‌های چندگانه کار می‌کرد
       (vendor_id اصلی صفر)، پیامِ دوره‌ای‌اش کاملاً قطع می‌شد — دقیقاً
       همان «اعلان‌ها نمی‌آیند»، بدون هیچ ردی در گزارش. */
    $_hasMsgr = (trim((string)($cn['baleh']['token'] ?? '')) !== '' && trim((string)($cn['baleh']['chat_id'] ?? '')) !== '')
             || (trim((string)($cn['rubika']['token'] ?? '')) !== '' && trim((string)($cn['rubika']['chat_id'] ?? '')) !== '')
             || (trim((string)($cn['telegram']['token'] ?? '')) !== '' && trim((string)($cn['telegram']['chat_id'] ?? '')) !== '');   // v10.78 (92)
    if (!$_hasMsgr) { notifPingLog(['ok' => false, 'src' => notifPingSrc($results, $force), 'error' => 'هیچ پیام‌رسانی تنظیم نشده']); return ['ok' => false, 'error' => 'هیچ پیام‌رسانی تنظیم نشده (بله/روبیکا/تلگرام)']; }

    $everyMin = (int)($cn['ping_every'] ?? 360);   // دقیقه
    $st  = notifLoadState();
    $last = (int)($st['last_cron_ping'] ?? 0);
    $now  = time();
    if (!$force && $everyMin > 0 && $last > 0 && ($now - $last) < $everyMin * 60) {
        notifPingLog(['ok' => true, 'skipped' => 'throttled', 'src' => notifPingSrc($results, $force)]);
        return ['ok' => true, 'skipped' => 'throttled',
                'next_in' => $everyMin * 60 - ($now - $last)];
    }

    // خلاصهٔ کاری که همین اجرا انجام داد تا پینگ فقط «زنده‌ام» نباشد
    $profiles = is_array($results['profiles'] ?? null) ? $results['profiles'] : [];
    $ran = 0; $notDue = 0; $errs = 0; $extracted = 0;
    foreach ($profiles as $p) {
        $stt = $p['status'] ?? '';
        if ($stt === 'not_due') { $notDue++; continue; }
        if ($stt === 'sync_disabled') continue;
        $ran++;
        $extracted += (int)($p['extracted'] ?? 0);
        if (!empty($p['extract_error'])) $errs++;
    }
    $sinceTxt = $last > 0 ? gmdate('H:i', min(359999, $now - $last)) : '—';

    /* v10.21 (۳۴ج): اگر اجرای قبلی نیمه‌کاره مانده باشد، پینگ باید بگوید.
       نشانه‌اش روشن است: کران شروع شده (نبض ثبت شده) ولی گزارشِ پایان
       (cron_last_run.json) از آن قدیمی‌تر است — یعنی هاست وسطِ راه پردازه
       را کشته. تا حالا این حالت کاملاً بی‌صدا بود و کاربر فقط می‌دید
       اعلان‌ها کم‌کم قطع شده‌اند. */
    $incomplete = '';
    $_startAt = (int)($st['last_cron_start'] ?? 0);
    $_doneF   = __DIR__ . '/cron_last_run.json';
    $_doneAt  = is_file($_doneF) ? (int)@filemtime($_doneF) : 0;
    if ($_startAt > 0 && $_doneAt > 0 && $_startAt - $_doneAt > 120) {
        $incomplete = "\n⚠️ اجرای قبلی نیمه‌کاره ماند (هاست پردازه را کشت)"
                    . "\n   آخرین اجرای کاملِ ثبت‌شده: " . date('m-d H:i', $_doneAt);
    }
    /* v10.22 (۳۵ج): «نبض» فقط وقتی نبض است که پینگِ خلاصه‌دار به‌تازگی
       نرفته باشد.

       رگرسیونِ v10.21: نبضِ ابتدای کران و پینگِ پایانی هر دو از یک
       پنجرهٔ throttle استفاده می‌کنند. نبض اولِ اجرا می‌رود و پنجره را
       مصرف می‌کند، بعد پینگِ پایانی — همان که خلاصهٔ واقعیِ کار را دارد
       — همیشه 'throttled' می‌خورد. نتیجه: کاربر به‌جای گزارشِ کامل، فقط
       یک «شروع شد» خالی می‌گرفت و حس می‌کرد اعلان‌ها بی‌محتوا یا قطع
       شده‌اند. حالا نبض سهمِ خودش را دارد: اگر اجرای قبلی سالم تمام شده
       باشد اصلاً نبض نمی‌فرستیم و پنجره را برای گزارشِ پایانی نگه
       می‌داریم؛ نبض فقط وقتی می‌رود که واقعاً خبری از پایان نیست. */
    $hb = !empty($results['heartbeat']);
    if ($hb && !$force) {
        $_pDoneF  = __DIR__ . '/cron_last_run.json';
        $_pDoneAt = is_file($_pDoneF) ? (int)@filemtime($_pDoneF) : 0;
        $_pStart  = (int)($st['last_cron_start'] ?? 0);
        /* اجرای قبلی سالم به پایان رسیده؟ (گزارشِ پایان از شروعش تازه‌تر
           است) پس مسیرِ عادی کار می‌کند و نبض لازم نیست — بگذار پینگِ
           پایانیِ همین اجرا با خلاصهٔ کامل برود. */
        if ($_pDoneAt > 0 && ($_pStart <= 0 || $_pDoneAt >= $_pStart - 120)) {
            $st['last_cron_start'] = $now;
            notifSaveState($st);
            notifPingLog(['ok' => true, 'skipped' => 'heartbeat_not_needed', 'src' => 'نبضِ کران']);
            return ['ok' => true, 'skipped' => 'heartbeat_not_needed'];
        }
    }

    $msg = ($hb ? "📡 کران‌جاب شروع شد" : "📡 کران‌جاب اجرا شد")
         . "\nزمان سرور: " . date('Y-m-d H:i:s')
         . "\nنسخه: " . APP_VERSION
         . (!$hb ? "\nپروفایل‌های اجراشده: " . $ran : '')
         . (!$hb && $notDue > 0 ? " · نوبتشان نبود: " . $notDue : '')
         . ($extracted > 0 ? "\nمحصولات استخراج‌شده: " . $extracted : '')
         . ($errs > 0 ? "\n⚠️ خطا در " . $errs . " پروفایل" : '')
         . (!empty($results['locked']) ? "\n🔒 اجرای قبلی هنوز در جریان است (" . (int)$results['locked'] . " ثانیه)" : '')
         . $incomplete
         . ($last > 0 ? "\nفاصله از پینگ قبلی: " . $sinceTxt : '')
         . ($force ? "\n(پینگ آزمایشی)" : '');

    /* v10.47 (۶۱): پینگ تنها پیامی است که کاربر قطعاً هر بار آن را
       می‌بیند — پس وضعیتِ کاملِ بررسیِ اعلان‌ها سوارِ همان پیام شود:
       اجرا شد؟ غرفه دید؟ چند گفتگو، چند بی‌جواب؟ خطایی بود؟
       با این، «چرا اعلانی نمی‌آید» دیگر گمان‌زنی نیست: خطِ
       «اعلان‌ها: ...» را از خودِ پینگ بخوانید. */
    $_nres = $results['notifications'] ?? null;
    /* v10.48 (۶۲): پینگِ نبض سرِ «شروع» اجرا می‌رود — بررسیٔ اعلان هنوز
       در همین دور انجام نشده، پس نتیجهٔ «این» دور آنجا وجود ندارد.
       پیامِ غلطِ «پیام‌رسان یا غرفه ندارد» را با وضعیتِ آخرین بررسیِ
       ثبت‌شده عوض می‌کنیم — همان چیزی که کاربر برای قضاوت نیاز دارد. */
    if (!empty($results['heartbeat'])) {
        $_stHb = notifLoadState();
        $_lrHb = (int)($_stHb['last_notif_run'] ?? 0);
        if ($_lrHb > 0) {
            $_ageHb = max(0, time() - $_lrHb);
            $_faHb = $_ageHb < 90 ? $_ageHb . ' ثانیه پیش'
                     : ($_ageHb < 5400 ? (int)round($_ageHb / 60) . ' دقیقه پیش'
                                       : (int)round($_ageHb / 3600) . ' ساعت پیش');
            $_seenHb = is_array($_stHb['last_notif_seen'] ?? null) ? $_stHb['last_notif_seen'] : [];
            $_pendHb = (int)($_stHb['last_notif_pending'] ?? 0);
            $msg .= "\nاعلان‌ها (آخرین بررسی " . $_faHb . "): گفتگو " . (int)($_seenHb['chats'] ?? 0)
                 . ($_pendHb > 0 ? ' (' . $_pendHb . ' بی‌جواب)' : '')
                 . ' · سفارش ' . (int)($_seenHb['orders'] ?? 0)
                 . ' · محصول ' . (int)($_seenHb['products'] ?? 0);
            if (is_array($_stHb['last_notif_errors'] ?? null) && $_stHb['last_notif_errors']) {
                $msg .= "\n⚠️ خطای آخرین بررسی: " . mb_substr(implode('؛ ', array_slice((array)$_stHb['last_notif_errors'], 0, 2)), 0, 140);
            }
        } else {
            $msg .= "\nاعلان‌ها: هنوز بررسی‌ای ثبت نشده (اولین دور)";
        }
    } elseif (is_array($_nres) && !empty($_nres['skipped'])) {
        $_why = $_nres['skipped'] === 'no_basalam_shops'
              ? 'هیچ غرفهٔ باسلامی با توکن تنظیم نشده'
              : (string)$_nres['skipped'];
        $msg .= "\n⚠️ اعلان‌ها: اجرا نشد — " . $_why;
    } elseif (is_array($_nres) && !empty($_nres['events_off'])) {
        $msg .= "\nاعلان‌ها: اجرا نشد — هیچ رویدادی روشن نیست";
    } elseif (is_array($_nres) && !empty($_nres['error'])) {
        $msg .= "\n⚠️ اعلان‌ها: خطا در بررسی — " . mb_substr((string)$_nres['error'], 0, 120);
    } elseif (is_array($_nres) && $_nres) {
        $_bits = [];
        if (isset($_nres['seen_chats'])) {
            $_bits[] = 'گفتگو ' . (int)$_nres['seen_chats']
                     . (!empty($_nres['pending_chats']) ? ' (' . (int)$_nres['pending_chats'] . ' بی‌جواب)' : '');
        }
        if (isset($_nres['seen_orders']))   $_bits[] = 'سفارش ' . (int)$_nres['seen_orders'];
        if (isset($_nres['seen_products'])) $_bits[] = 'محصول ' . (int)$_nres['seen_products'];
        if (!empty($_nres['found_total']))  $_bits[] = '🔔 ' . (int)$_nres['found_total'] . ' رویداد اعلان شد';
        if (is_array($_nres['errors'] ?? null) && $_nres['errors']) {
            $_bits[] = '⚠️ ' . mb_substr(implode('؛ ', array_slice(array_unique($_nres['errors']), 0, 2)), 0, 140);
        }
        $msg .= "\nاعلان‌ها: " . implode(' · ', $_bits);
    } else {
        $msg .= "\nاعلان‌ها: اجرا نشد (پیام‌رسان یا غرفهٔ باسلام ندارد)";
    }

    $delivery = notifSend($cn, $msg, 'ping');
    /* v10.22 (۳۵ب): پنجرهٔ throttle فقط وقتی مصرف می‌شود که پیام واقعاً
       رسیده باشد.

       این تلهٔ بی‌صدا بود: notifSend شکست می‌خورد (پیام‌رسان لحظه‌ای قطع،
       توکن منقضی، ۴۲۹ روی هاست) ولی بلافاصله last_cron_ping = الان ثبت
       می‌شد. یعنی پیام نرفته بود اما ساعتِ شمارش صفر شده بود و تا شش
       ساعتِ بعد هیچ تلاشِ دیگری نمی‌شد. یک اختلالِ چندثانیه‌ای، شش ساعت
       سکوت می‌ساخت؛ و اگر هر بار همان لحظه تکرار می‌شد، برای همیشه.
       حالا اگر هیچ مقصدی 'sent' نگرفت، حالت دست‌نخورده می‌ماند تا تیکِ
       بعدیِ کران دوباره تلاش کند. */
    $anySent = in_array('sent', array_values($delivery), true);
    notifPingLog(['ok' => $anySent, 'src' => notifPingSrc($results, $force), 'delivery' => $delivery]);   // v10.79 (93)
    if (!$force && $anySent) {
        $st['last_cron_ping'] = $now;
        if ($hb) $st['last_cron_start'] = $now;   // v10.21: زمانِ شروعِ این اجرا
        notifSaveState($st);
    }
    if (!$anySent) {
        return ['ok' => false, 'error' => 'ارسال به پیام‌رسان ناموفق بود',
                'delivery' => $delivery, 'message' => $msg, 'retry' => true];
    }
    return ['ok' => true, 'sent' => true, 'delivery' => $delivery, 'message' => $msg];
}

/** پیش‌نیازها را بررسی می‌کند و در صورت نبود، علت را برمی‌گرداند */
function notifPrereq(array $cn): ?string {
    if (trim((string)($cn['basalam']['token'] ?? '')) === '') return 'توکن باسلام تنظیم نشده';
    if ((int)($cn['basalam']['vendor_id'] ?? 0) <= 0)         return 'شناسهٔ غرفه تنظیم نشده';
    $hasMsgr = (!empty($cn['baleh']['token']) && !empty($cn['baleh']['chat_id']))
            || (!empty($cn['rubika']['token']) && !empty($cn['rubika']['chat_id']))
            || (!empty($cn['telegram']['token']) && !empty($cn['telegram']['chat_id']));   // v10.78 (92)
    if (!$hasMsgr) return 'هیچ پیام‌رسانی تنظیم نشده (بله/روبیکا/تلگرام)';
    return null;
}

/**
 * v8.31: پیام خطای گویا برای پاسخ‌های ناموفق باسلام.
 * ۴۰۴ معمولاً یعنی مسیر عوض شده (باسلام به API Gateway مهاجرت کرده) و
 * ۴۰۳ یعنی توکن اسکوپ لازم را ندارد — این دو را نباید یکی گزارش کرد.
 */
function bslApiError(array $r, string $what, string $endpoint, string $scope = ''): string {
    $c = (int)($r['code'] ?? 0);
    // v9.84: «stopped» خطای شبکه نیست — سیگنال توقفِ ارسال است. قبلاً با
    // کد ۰ قاطی می‌شد و کاربر پیام گمراه‌کنندهٔ «ارتباط برقرار نشد» می‌دید،
    // در حالی که اینترنت و توکن سالم بودند.
    if ((string)($r['error'] ?? '') === 'stopped') {
        return $what . ' — ارسال متوقف شده است؛ از «پاک‌سازی فایل‌های موقت» استفاده کنید یا چند دقیقه صبر کنید';
    }
    if ($c === 404) return $what . ' — مسیر یافت نشد (۴۰۴): ' . $endpoint;
    if ($c === 401) return $what . ' — توکن نامعتبر یا منقضی (۴۰۱)';
    if ($c === 403) return $what . ' — توکن دسترسی لازم را ندارد (۴۰۳)'
                         . ($scope !== '' ? ' · اسکوپ موردنیاز: ' . $scope : '');
    if ($c === 429) return $what . ' — تعداد درخواست بیش از حد (۴۲۹)، کمی بعد تلاش کنید';
    // v8.33: ۴۲۲ یعنی پارامتر ورودی نامعتبر است — جزئیات را از پاسخ بیرون می‌کشیم
    if ($c === 422) {
        $det = [];
        foreach ((array)($r['body']['detail'] ?? []) as $d) {
            if (!is_array($d)) continue;
            $loc = is_array($d['loc'] ?? null) ? end($d['loc']) : '';
            $m   = (string)($d['msg'] ?? '');
            if ($loc !== '' || $m !== '') $det[] = trim($loc . ' ' . $m);
        }
        $att = is_array($r['attempts'] ?? null) ? ' — روش‌های امتحان‌شده: ' . implode('، ', $r['attempts']) : '';
        return $what . ' — پارامتر نامعتبر (۴۲۲)'
             . ($det ? ': ' . mb_substr(implode(' · ', $det), 0, 160) : ' در ' . $endpoint) . $att;
    }
    if ($c === 0)   return $what . ' — ارتباط با باسلام برقرار نشد';
    return $what . ' — خطای HTTP ' . $c . $att;
}

/* =====================================================================
 *  v8.32: وضعیت سفارش‌های غرفه‌دار و نرمال‌سازی پاسخ باسلام
 *  کدها از مستندات رسمی order_processing گرفته شده‌اند (پارامتر statuses).
 * ===================================================================== */

/** کد وضعیت سفارش → نام فارسی */
function bslParcelStatuses(): array {
    return [
        3739 => 'جدید',              3237 => 'در حال آماده‌سازی',
        3238 => 'ارسال شده',          5017 => 'اطلاعات ارسال نادرست',
        3572 => 'نرسیده',             3740 => 'ثبت مشکل شده',
        4633 => 'درخواست لغو مشتری',  5075 => 'درخواست توافق تأخیر',
        3195 => 'رضایت',              3233 => 'عودت وجه کامل',
        3067 => 'لغو',                6440 => 'درخواست لغو غرفه‌دار',
    ];
}

/** سفارش‌هایی که هنوز ارسال نشده‌اند و غرفه‌دار باید کاری برایشان بکند */
function bslUnsentStatuses(): array { return [3739, 3237]; }

/**
 * v8.32: نام مشتری را از ساختار درست بیرون می‌کشد.
 * طبق مستندات، customer سه کلید دارد: recipient / city / user — و
 * «name» مستقیم زیر customer وجود ندارد. نسخهٔ ۸.۳۱ اشتباه می‌خواند و
 * همیشه «نامشخص» می‌داد.
 */
function bslParcelCustomerName(array $o): string {
    $c = $o['order']['customer'] ?? ($o['customer'] ?? []);
    if (!is_array($c)) return 'نامشخص';
    foreach ([['recipient', 'name'], ['user', 'name']] as $p) {
        $v = trim((string)($c[$p[0]][$p[1]] ?? ''));
        if ($v !== '') return $v;
    }
    $v = trim((string)($c['name'] ?? ''));
    return $v !== '' ? $v : 'نامشخص';
}

/** یک ردیف vendor-parcels را به ساختار ساده و یک‌دست تبدیل می‌کند */
function bslNormalizeParcel(array $o): array {
    $stId  = (int)($o['status']['id'] ?? 0);
    $names = bslParcelStatuses();
    $stTxt = trim((string)($o['status']['title'] ?? ''));
    if ($stTxt === '') $stTxt = $names[$stId] ?? '—';
    $items = [];
    foreach (($o['items'] ?? []) as $it) {
        if (!is_array($it)) continue;
        $items[] = ['title' => (string)($it['title'] ?? ''), 'qty' => (int)($it['quantity'] ?? 1)];
    }
    return [
        'parcel_id'   => (int)($o['id'] ?? 0),
        'order_id'    => (int)($o['order']['id'] ?? 0),
        'customer'    => bslParcelCustomerName($o),
        'amount'      => (int)($o['total_items_price'] ?? 0),
        'status_id'   => $stId,
        'status'      => $stTxt,
        'unsent'      => in_array($stId, bslUnsentStatuses(), true),
        'created_at'  => (string)($o['created_at'] ?? ''),
        'send_before' => (string)($o['estimate_send_at'] ?? ''),
        'items'       => $items,
        'items_count' => count($items),
    ];
}

/**
 * v8.32: یک ردیف chats را نرمال می‌کند.
 * طبق مستندات، متن پیام زیر last_message.content.text است نه
 * last_message.text — نسخهٔ ۸.۳۱ اشتباه می‌خواند و همیشه «...» می‌فرستاد.
 */

/**
 * v10.109: استخراج آدرس‌های چندرسانه‌ای از یک پیام باسلام.
 * شکل‌های ممکن attachment/content (همان الگوی اتاق چت v10.57) + لینک در متن.
 * @return array{type:string,url:string,name:string,urls:string[],links:string[],label:string}
 */
function bslMsgExtractMedia(array $m): array {
    $mt = strtolower(trim((string)($m['message_type'] ?? '')));
    $urls = [];
    $name = '';
    $cands = [
        $m['attachment']['files'] ?? null,
        $m['content']['files'] ?? null,
        $m['files'] ?? null,
        $m['attachment']['file'] ?? null,
    ];
    foreach ($cands as $files) {
        if (!is_array($files)) continue;
        // single file object
        if (isset($files['url']) || isset($files['id'])) $files = [$files];
        foreach ($files as $f) {
            if (!is_array($f)) continue;
            foreach (['url', 'primary', 'download_url', 'src', 'link', 'path'] as $uk) {
                $u = $f[$uk] ?? null;
                if (is_string($u) && strncmp($u, 'http', 4) === 0) { $urls[] = $u; break; }
                if (is_array($u) && is_string($u['primary'] ?? null) && strncmp($u['primary'], 'http', 4) === 0) {
                    $urls[] = $u['primary']; break;
                }
            }
            if ($name === '' && trim((string)($f['name'] ?? $f['file_name'] ?? $f['filename'] ?? '')) !== '') {
                $name = trim((string)($f['name'] ?? $f['file_name'] ?? $f['filename'] ?? ''));
            }
        }
    }
    foreach ([
        $m['content']['url'] ?? null,
        $m['content']['image'] ?? null,
        $m['content']['video'] ?? null,
        $m['content']['file'] ?? null,
        $m['url'] ?? null,
        $m['image'] ?? null,
        $m['video'] ?? null,
        $m['file_url'] ?? null,
        $m['attachment']['url'] ?? null,
        $m['attachment']['image'] ?? null,
        is_array($m['content']['urls'] ?? null) ? ($m['content']['urls']['primary'] ?? null) : null,
    ] as $u) {
        if (is_string($u) && strncmp($u, 'http', 4) === 0) $urls[] = $u;
    }
    $urls = array_values(array_unique(array_filter($urls, fn($u) => is_string($u) && strncmp($u, 'http', 4) === 0)));

    $text = '';
    foreach ([$m['content']['text'] ?? null, $m['text'] ?? null, $m['content'] ?? null] as $cand) {
        if (is_string($cand) && trim($cand) !== '') { $text = trim($cand); break; }
    }
    $links = [];
    if ($text !== '' && preg_match_all('~https?://[^\s<>"\']+~u', $text, $mm)) {
        foreach ($mm[0] as $lnk) {
            $lnk = rtrim($lnk, '.,);]');
            if (strncmp($lnk, 'http', 4) === 0) $links[] = $lnk;
        }
    }
    $links = array_values(array_unique($links));
    // لینک‌هایی که خود فایل رسانه‌اند را به urls هم اضافه کن
    foreach ($links as $lnk) {
        if (preg_match('~\.(jpe?g|png|gif|webp|bmp|mp4|webm|mov|m4v|avi|mkv|mp3|ogg|wav|pdf|zip|rar|7z)(\?|$)~i', $lnk)) {
            if (!in_array($lnk, $urls, true)) $urls[] = $lnk;
        }
    }

    $primary = $urls[0] ?? '';
    $kind = 'text';
    if ($mt !== '' && $mt !== 'text') $kind = $mt;
    if ($primary !== '') {
        $extKind = bslMediaKindFromUrl($primary, $mt);
        if ($kind === 'text' || $kind === '') $kind = $extKind;
        elseif (in_array($kind, ['picture', 'image', 'photo'], true)) $kind = 'picture';
        elseif (in_array($kind, ['video', 'clip'], true)) $kind = 'video';
        elseif (in_array($kind, ['gif', 'animation', 'sticker'], true)) $kind = 'animation';
        elseif (in_array($kind, ['voice', 'audio', 'sound'], true)) $kind = 'audio';
        elseif (in_array($kind, ['file', 'document', 'pdf'], true)) $kind = 'file';
    } elseif ($links) {
        $kind = 'link';
        $primary = $links[0];
    }
    $labels = [
        'picture' => '🖼 تصویر', 'image' => '🖼 تصویر', 'photo' => '🖼 تصویر',
        'video' => '🎬 ویدیو', 'animation' => '🎞 گیف', 'gif' => '🎞 گیف',
        'file' => '📎 فایل', 'document' => '📎 فایل', 'audio' => '🎧 صوت', 'voice' => '🎤 پیام صوتی',
        'link' => '🔗 لینک', 'location' => '📍 موقعیت', 'product' => '🛍 محصول',
    ];
    $label = $labels[$kind] ?? ($kind !== '' && $kind !== 'text' ? ('[' . $kind . ']') : '');
    return [
        'type'  => $kind,
        'url'   => $primary,
        'name'  => $name,
        'urls'  => $urls,
        'links' => $links,
        'label' => $label,
        'text'  => $text,
    ];
}

/** v10.109: نوع رسانه برای API پیام‌رسان از روی URL / نوع باسلام */
function bslMediaKindFromUrl(string $url, string $hint = ''): string {
    $h = strtolower(trim($hint));
    if (in_array($h, ['picture', 'image', 'photo'], true)) return 'picture';
    if (in_array($h, ['video', 'clip'], true)) return 'video';
    if (in_array($h, ['gif', 'animation', 'sticker'], true)) return 'animation';
    if (in_array($h, ['voice', 'audio', 'sound'], true)) return 'audio';
    if (in_array($h, ['file', 'document', 'pdf'], true)) return 'file';
    $path = strtolower((string)(parse_url($url, PHP_URL_PATH) ?? ''));
    if (preg_match('~\.(gif)(\?|$)~', $path) || str_contains($path, '.gif')) return 'animation';
    if (preg_match('~\.(jpe?g|png|webp|bmp)(\?|$)~', $path)) return 'picture';
    if (preg_match('~\.(mp4|webm|mov|m4v|avi|mkv)(\?|$)~', $path)) return 'video';
    if (preg_match('~\.(mp3|ogg|wav|m4a|aac)(\?|$)~', $path)) return 'audio';
    if ($url !== '') return 'file';
    return 'link';
}

/**
 * v10.109: تبدیل رسانهٔ باسلام به آیتم‌های قابل ارسال به بله/تلگرام/روبیکا.
 * @return list<array{kind:string,url:string,caption:string,name:string}>
 */
function bslMediaToMsgrItems(array $media, string $caption = ''): array {
    $items = [];
    $seen = [];
    $urls = $media['urls'] ?? [];
    if (!$urls && !empty($media['url'])) $urls = [(string)$media['url']];
    $type = (string)($media['type'] ?? '');
    $name = (string)($media['name'] ?? '');
    $capOnce = $caption;
    foreach ($urls as $u) {
        $u = trim((string)$u);
        if ($u === '' || isset($seen[$u])) continue;
        $seen[$u] = true;
        $k = bslMediaKindFromUrl($u, $type);
        // map to messenger kind
        $mk = match ($k) {
            'picture', 'image', 'photo' => 'photo',
            'video' => 'video',
            'animation', 'gif' => 'animation',
            'audio', 'voice' => 'audio',
            'file', 'document' => 'document',
            default => 'document',
        };
        $items[] = ['kind' => $mk, 'url' => $u, 'caption' => $capOnce, 'name' => $name];
        $capOnce = ''; // فقط اولی caption کامل
    }
    foreach (($media['links'] ?? []) as $lnk) {
        $lnk = trim((string)$lnk);
        if ($lnk === '' || isset($seen[$lnk])) continue;
        // اگر قبلاً به‌عنوان فایل آمده رد کن
        $seen[$lnk] = true;
        // لینک عمومی — به‌صورت پیام متنی با پیش‌نمایش
        if (!preg_match('~\.(jpe?g|png|gif|webp|mp4|webm|mov|pdf|zip)(\?|$)~i', $lnk)) {
            $items[] = ['kind' => 'link', 'url' => $lnk, 'caption' => $capOnce !== '' ? $capOnce : ('🔗 ' . $lnk), 'name' => ''];
            $capOnce = '';
        }
    }
    return $items;
}

function bslNormalizeChat(array $c): array {
    $lm = is_array($c['last_message'] ?? null) ? $c['last_message'] : [];
    $txt = '';
    foreach ([$lm['content']['text'] ?? null, $lm['text'] ?? null] as $cand) {
        if (is_string($cand) && trim($cand) !== '') { $txt = trim($cand); break; }
    }
    $ct = $c['contact'] ?? [];
    $who = '';
    if (is_array($ct)) {
        foreach (['name', 'title', 'username', 'hash_id'] as $k) {
            $v = trim((string)($ct[$k] ?? ''));
            if ($v !== '') { $who = $v; break; }
        }
    } elseif (is_string($ct)) { $who = trim($ct); }
    if ($who === '') $who = trim((string)($lm['sender']['name'] ?? ''));
    if ($who === '') $who = 'مشتری';
    $type = (string)($lm['message_type'] ?? '');
    /* v10.109: رسانهٔ آخرین پیام (عکس/ویدیو/فایل/لینک) */
    $media = bslMsgExtractMedia(is_array($lm) ? $lm : []);
    if ($txt === '') {
        if ($media['label'] !== '') $txt = $media['label'] . ($media['url'] !== '' ? ' ' . $media['url'] : '');
        elseif ($type !== '' && $type !== 'text') $txt = '[' . $type . ']';
        else $txt = '—';
    }
    return [
        'chat_id'    => (int)($c['id'] ?? 0),
        'who'        => $who,
        'text'       => $txt,
        'unseen'     => (int)($c['unseen_message_count'] ?? 0),
        'updated_at' => (string)($c['updated_at'] ?? ($c['created_at'] ?? '')),
        'chat_type'  => (string)($c['chat_type'] ?? ''),
        'sender'     => trim((string)($lm['sender']['name'] ?? '')),
        'media_url'  => (string)($media['url'] ?? ''),
        'media_type' => (string)($media['type'] ?? ''),
        'media_urls' => $media['urls'] ?? [],
        'media_links'=> $media['links'] ?? [],
    ];
}

/** متن پیام‌رسان برای یک سفارش */
function bslParcelMsg(array $n, string $head = '🛒 سفارش باسلام'): string {
    $s = $head . "\nشماره: #" . ($n['order_id'] ?: $n['parcel_id'])
       . "\nمشتری: " . $n['customer']
       . "\nمبلغ: " . number_format($n['amount']) . ' تومان'
       . "\nوضعیت: " . $n['status'];
    if (!empty($n['items'])) {
        $lines = [];
        foreach (array_slice($n['items'], 0, 3) as $it) {
            $lines[] = '• ' . mb_substr($it['title'], 0, 45) . ' ×' . $it['qty'];
        }
        $more = count($n['items']) - count($lines);
        if ($more > 0) $lines[] = '• و ' . $more . ' قلم دیگر';
        $s .= "\n" . implode("\n", $lines);
    }
    return $s;
}

/**
 * v8.33: متن پیام‌های خوانده‌نشدهٔ یک گفتگو را می‌گیرد.
 * فقط پیام‌های طرف مقابل برگردانده می‌شود، به ترتیب قدیم به جدید،
 * تا در پیام‌رسان همان چیزی دیده شود که مشتری نوشته است.
 */
function bslMyUserId(string $tk): int {
    static $cache = [];
    $k = substr(md5($tk), 0, 12);
    if (isset($cache[$k])) return $cache[$k];
    $r = bslReqRead($tk, 'users/me');
    $id = 0;
    if (!empty($r['ok'])) $id = (int)($r['body']['id'] ?? ($r['body']['user_id'] ?? 0));
    return $cache[$k] = $id;
}

function bslFetchChatMessages(string $tk, int $chatId, int $limit = 10, int $myUserId = -1): array {
    if ($chatId <= 0) return [];
    // v8.33: پیش‌فرض یعنی «خودت پیدا کن» تا پاسخ‌های خود غرفه‌دار فیلتر شوند
    if ($myUserId < 0) $myUserId = bslMyUserId($tk);
    $lim = max(1, min(50, $limit));
    $r = bslReqRead($tk, 'chats/' . $chatId . '/messages?limit=' . $lim . '&order=desc');
    if (!$r['ok']) return [];
    $rows = $r['body']['data']['messages'] ?? ($r['body']['data'] ?? []);
    if (!is_array($rows)) return [];
    $out = [];
    foreach ($rows as $m) {
        if (!is_array($m)) continue;
        $sid = (int)($m['sender']['id'] ?? 0);
        if ($myUserId > 0 && $sid === $myUserId) continue;   // پیام‌های خودمان را نشان نده
        $media = bslMsgExtractMedia($m);
        $txt = $m['content']['text'] ?? null;
        if (!is_string($txt) || trim($txt) === '') {
            $mt = (string)($m['message_type'] ?? ($media['type'] ?? ''));
            if ($media['label'] !== '') {
                $txt = $media['label'];
                if ($media['url'] !== '') $txt .= ' ' . $media['url'];
            } else {
                $txt = $mt !== '' && $mt !== 'text' ? '[' . $mt . ']' : '';
            }
        }
        $txt = trim((string)$txt);
        // v10.109: پیام فقط‌رسانه را هم نگه دار (قبلاً اگر متن خالی بود drop می‌شد)
        if ($txt === '' && empty($media['urls']) && empty($media['links'])) continue;
        if ($txt === '' && $media['label'] !== '') $txt = $media['label'];
        $out[] = [
            'text'   => $txt,
            'at'     => (string)($m['created_at'] ?? ''),
            'sender' => trim((string)($m['sender']['name'] ?? '')),
            'type'   => (string)($media['type'] ?? ($m['message_type'] ?? 'text')),
            'url'    => (string)($media['url'] ?? ''),
            'urls'   => $media['urls'] ?? [],
            'links'  => $media['links'] ?? [],
            'name'   => (string)($media['name'] ?? ''),
            'label'  => (string)($media['label'] ?? ''),
        ];
    }
    return array_reverse($out);   // قدیمی‌ترین اول، مثل خود گفتگو
}

/**
 * متن پیام‌رسان برای یک گفتگو.
 * v8.33: اگر متن پیام‌ها داده شود، همه را می‌فرستد نه فقط آخری.
 */
function bslChatMsg(array $n, string $head = '💬 پیام مشتری باسلام', array $msgs = []): string {
    $s = $head . "\nمشتری: " . $n['who']
       . ($n['unseen'] > 0 ? ' (' . $n['unseen'] . ' خوانده‌نشده)' : '');
    if ($msgs) {
        $s .= "\n━━━━━━━━━━";
        $budget = 3000;   // سقف امن برای بله/روبیکا
        foreach ($msgs as $m) {
            $t = trim((string)($m['text'] ?? ''));
            $u = trim((string)($m['url'] ?? ''));
            $lab = trim((string)($m['label'] ?? ''));
            if ($t === '' && $lab !== '') $t = $lab;
            if ($u !== '' && $t !== '' && mb_strpos($t, $u) === false) $t .= "\n" . $u;
            elseif ($t === '' && $u !== '') $t = ($lab !== '' ? $lab . ' ' : '') . $u;
            foreach (($m['links'] ?? []) as $lnk) {
                $lnk = trim((string)$lnk);
                if ($lnk !== '' && mb_strpos($t, $lnk) === false) $t .= "\n🔗 " . $lnk;
            }
            $line = "\n▸ " . mb_substr($t, 0, 700);
            if (mb_strlen($line) > $budget) { $s .= "\n… (بقیه در باسلام)"; break; }
            $s .= $line; $budget -= mb_strlen($line);
        }
        return $s;
    }
    $body = mb_substr((string)($n['text'] ?? ''), 0, 700);
    $mu = trim((string)($n['media_url'] ?? ''));
    if ($mu !== '' && mb_strpos($body, $mu) === false) $body .= ($body !== '' ? "\n" : '') . $mu;
    return $s . "\nپیام: " . $body;
}

/**
 * v10.109: جمع‌آوری آیتم‌های رسانه از لیست پیام‌های fetch‌شده + نرمال‌گفتگو.
 * @return list<array{kind:string,url:string,caption:string,name:string}>
 */
function bslChatCollectMedia(array $n, array $msgs = []): array {
    $items = [];
    $seen = [];
    $add = function (array $media, string $cap = '') use (&$items, &$seen) {
        foreach (bslMediaToMsgrItems($media, $cap) as $it) {
            $u = (string)($it['url'] ?? '');
            if ($u === '' || isset($seen[$u])) continue;
            $seen[$u] = true;
            $items[] = $it;
        }
    };
    if ($msgs) {
        foreach ($msgs as $m) {
            if (!is_array($m)) continue;
            $add([
                'type'  => (string)($m['type'] ?? ''),
                'url'   => (string)($m['url'] ?? ''),
                'urls'  => $m['urls'] ?? [],
                'links' => $m['links'] ?? [],
                'name'  => (string)($m['name'] ?? ''),
                'label' => (string)($m['label'] ?? ''),
            ], mb_substr((string)($m['text'] ?? ''), 0, 200));
        }
    } else {
        $add([
            'type'  => (string)($n['media_type'] ?? ''),
            'url'   => (string)($n['media_url'] ?? ''),
            'urls'  => $n['media_urls'] ?? [],
            'links' => $n['media_links'] ?? [],
            'name'  => '',
            'label' => '',
        ], mb_substr((string)($n['text'] ?? ''), 0, 200));
    }
    return $items;
}


/* =====================================================================
 *  v8.64: پاسخ خودکار به پیام مشتریان باسلام
 *
 *  هر قاعده یک «محرک» دارد (چند کلمه یا عبارت) و یک «پاسخ». وقتی پیام
 *  خوانده‌نشدهٔ مشتری با یکی از محرک‌ها بخورد، همان پاسخ برایش فرستاده
 *  می‌شود. مهم‌ترین تصمیم‌های طراحی:
 *
 *   • تأخیر ادب (grace) — پیش‌فرض چند دقیقه صبر می‌کند تا اگر خودِ
 *     غرفه‌دار جواب داد، ربات وسط حرف نپرد. با ۰ دقیقه فوری جواب می‌دهد.
 *   • هر گفتگو در یک بازهٔ زمانی فقط یک بار پاسخ خودکار می‌گیرد، و هر
 *     قاعده هم سقف روزانه دارد — تا حلقهٔ پاسخ‌به‌پاسخ راه نیفتد.
 *   • ساعت کاری — می‌شود گفت فقط بیرون ساعت کاری جواب بده (وقتی آدم
 *     نیست)، یا همیشه.
 *   • قاعدهٔ «پیش‌فرض» (بدون محرک) برای وقتی هیچ‌کدام نخورد.
 *   • حالت آزمایشی: هیچ پیامی فرستاده نمی‌شود، فقط می‌گوید چه می‌کرد.
 *
 *  ⚠️ تنها فرستندهٔ واقعی bslSendChatMessage است و فقط از یک نقطه صدا
 *  زده می‌شود، تا «پیش‌نمایش» هیچ‌وقت به‌اشتباه ارسال نکند.
 * ===================================================================== */

/** متن را برای تطبیق ساده می‌کند: بدون اعراب، بدون ی/ک عربی، بدون علائم */
function arNormText(string $t): string {
    $t = persianToEnglish($t);
    // ي ك عربی → ی ک فارسی، حذف اعراب و نیم‌فاصله
    $t = str_replace(['ي', 'ك', 'ة', 'ۀ', 'أ', 'إ', 'آ', 'ؤ'],
                     ['ی', 'ک', 'ه', 'ه', 'ا', 'ا', 'ا', 'و'], $t);
    $t = preg_replace('~[\x{064B}-\x{065F}\x{0670}\x{200c}\x{200f}\x{200e}]~u', '', $t);
    $t = preg_replace('~[^\p{L}\p{N}\s]~u', ' ', $t);
    $t = preg_replace('~\s+~u', ' ', $t);
    return trim(mb_strtolower($t, 'UTF-8'));
}

/** قواعد پیش‌فرض — فقط وقتی هنوز چیزی ذخیره نشده */
function arDefaultRules(): array {
    return [
        ['id' => 'greet', 'on' => true, 'match' => 'contains',
         'triggers' => "سلام\nدرود\nوقت بخیر\nروز بخیر",
         'reply' => 'سلام و وقت بخیر 🌷 در خدمتم، بفرمایید.', 'priority' => 10, 'daily_max' => 100],
        ['id' => 'thanks', 'on' => true, 'match' => 'contains',
         'triggers' => "ممنون\nمرسی\nسپاس\nتشکر\nلطف کردید\nدمت گرم",
         'reply' => 'خواهش می‌کنم 🙏 خوشحالم که راضی بودید.', 'priority' => 10, 'daily_max' => 100],
        ['id' => 'price', 'on' => false, 'match' => 'contains',
         'triggers' => "قیمت\nچند\nهزینه\nتخفیف",
         'reply' => 'قیمت همان است که روی صفحهٔ محصول نوشته شده. اگر محصول خاصی مدنظرتان است، لینکش را بفرستید.',
         'priority' => 20, 'daily_max' => 50],
        ['id' => 'send', 'on' => false, 'match' => 'contains',
         'triggers' => "ارسال\nپست\nکی می‌رسه\nچند روزه\nتیپاکس",
         'reply' => 'سفارش‌ها معمولاً ۱ تا ۳ روز کاری بعد از ثبت ارسال می‌شوند و کد رهگیری برایتان می‌آید.',
         'priority' => 20, 'daily_max' => 50],
        ['id' => 'bye', 'on' => false, 'match' => 'contains',
         'triggers' => "خداحافظ\nخدانگهدار\nفعلا",
         'reply' => 'خدانگهدار 🌹 هر وقت سؤالی داشتید در خدمتم.', 'priority' => 30, 'daily_max' => 100],
        ['id' => 'fallback', 'on' => false, 'match' => 'always',
         'triggers' => '',
         'reply' => 'پیام شما رسید 🙏 در اولین فرصت پاسخ می‌دهم.', 'priority' => 99, 'daily_max' => 30],
    ];
}

/** تنظیمات پاسخ خودکار با پیش‌فرض‌ها */
function arCfg(?array $cn = null): array {
    if ($cn === null) $cn = loadConnections();
    $a = (array)($cn['autoreply'] ?? []);
    return [
        'enabled'      => !empty($a['enabled']),
        'grace_min'    => max(0, min(1440, (int)($a['grace_min'] ?? 10))),
        'per_chat_min' => max(0, min(10080, (int)($a['per_chat_min'] ?? 180))),
        'max_per_run'  => max(1, min(50, (int)($a['max_per_run'] ?? 5))),
        'only_offhours'=> !empty($a['only_offhours']),
        'work_from'    => max(0, min(23, (int)($a['work_from'] ?? 9))),
        'work_to'      => max(0, min(23, (int)($a['work_to'] ?? 21))),
        'sign'         => trim((string)($a['sign'] ?? '')),
        'notify'       => !empty($a['notify']),
        'scan_limit'   => max(5, min(50, (int)($a['scan_limit'] ?? 20))),
        // v9.33: حالت جایگزین وقتی قاعده‌ای نخورد.
        // سازگاری با نسخهٔ قبل: اگر fallback تنظیم نشده ولی ai_reply روشن بود،
        // یعنی کاربر قبلاً «پاسخ با هوش مصنوعی» را انتخاب کرده بود.
        'fallback'     => (function () use ($a) {
            $f = (string)($a['fallback'] ?? '');
            if (in_array($f, ['none','premade','ai'], true)) return $f;
            return !empty($a['ai_reply']) ? 'ai' : 'none';
        })(),
        'fallback_text'=> trim((string)($a['fallback_text'] ?? '')),
        // v9.37: پیام سیستمیِ هوش مصنوعی
        'ai_system_mode' => in_array((string)($a['ai_system_mode'] ?? 'default'), ['default','custom'], true) ? $a['ai_system_mode'] : 'default',
        'ai_system_text' => trim((string)($a['ai_system_text'] ?? '')),
        // v9.38: ترتیب اولویت پاسخ‌دهی بین قواعد آماده و هوش مصنوعی
        'reply_order'   => in_array((string)($a['reply_order'] ?? 'rules_first'), ['rules_first','ai_first','rules_only','ai_only'], true) ? $a['reply_order'] : 'rules_first',
    ];
}

function arLoadRules(): array {
    if (!is_file(AUTOREPLY_RULES_FILE)) return arDefaultRules();
    $d = json_decode((string)@file_get_contents(AUTOREPLY_RULES_FILE), true);
    if (!is_array($d) || !isset($d['rules']) || !is_array($d['rules'])) return arDefaultRules();
    return $d['rules'];
}

function arSaveRules(array $rules): bool {
    $clean = [];
    foreach ($rules as $r) {
        if (!is_array($r)) continue;
        $m = (string)($r['match'] ?? 'contains');
        if (!in_array($m, ['contains', 'exact', 'starts', 'regex', 'always'], true)) $m = 'contains';
        $id = preg_replace('~[^A-Za-z0-9_-]~', '', (string)($r['id'] ?? ''));
        if ($id === '') $id = 'r' . substr(md5(json_encode($r) . mt_rand()), 0, 8);
        $clean[] = [
            'id'        => $id,
            'on'        => !empty($r['on']),
            'match'     => $m,
            'triggers'  => trim((string)($r['triggers'] ?? '')),
            'reply'     => trim((string)($r['reply'] ?? '')),
            'priority'  => max(1, min(999, (int)($r['priority'] ?? 50))),
            'daily_max' => max(0, min(1000, (int)($r['daily_max'] ?? 50))),
        ];
    }
    return @file_put_contents(AUTOREPLY_RULES_FILE,
        json_encode(['rules' => $clean, 'saved_at' => time()], JSON_UNESCAPED_UNICODE),
        LOCK_EX) !== false;
}

function arLoadState(): array {
    if (!is_file(AUTOREPLY_STATE_FILE)) return ['chats' => [], 'daily' => [], 'day' => ''];
    $d = json_decode((string)@file_get_contents(AUTOREPLY_STATE_FILE), true);
    if (!is_array($d)) return ['chats' => [], 'daily' => [], 'day' => ''];
    $d['chats'] = is_array($d['chats'] ?? null) ? $d['chats'] : [];
    $d['daily'] = is_array($d['daily'] ?? null) ? $d['daily'] : [];
    return $d;
}

function arSaveState(array $st): void {
    // گفتگوهای قدیمی‌تر از ۳۰ روز لازم نیستند
    $cut = time() - 30 * 86400;
    foreach ($st['chats'] as $k => $v) {
        if ((int)($v['at'] ?? 0) < $cut) unset($st['chats'][$k]);
    }
    @file_put_contents(AUTOREPLY_STATE_FILE, json_encode($st, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/**
 * v9.21: تولید پاسخ با هوش مصنوعی (مدل فعال، با بک‌آپ مدل رایگان Bonsai).
 * وقتی هیچ قاعدهٔ دستی‌ای به پیام مشتری نمی‌خورد و «پاسخ هوش مصنوعی»
 * روشن باشد، یک پاسخ کوتاه و مؤدبانهٔ فارسی از ارائه‌دهندهٔ فعال می‌گیریم.
 * خروجی ['ok'=>bool, 'text'=>string, 'error'=>string]
 */
function arAiReplyText(string $text, ?int $timeoutSec = null): array {
    $text = trim((string)$text);
    if ($text === '') return ['ok' => false, 'text' => '', 'error' => 'پیام خالی'];
    // v9.37: پیام سیستمیِ هوش مصنوعی — پیش‌فرض یا سفارشی از تنظیمات
    $arCfg = arCfg();
    if ((string)($arCfg['ai_system_mode'] ?? 'default') === 'custom' && trim((string)($arCfg['ai_system_text'] ?? '')) !== '') {
        $system = trim((string)$arCfg['ai_system_text']);
    } else {
        $system = 'تو دستیار پاسخ‌گویی یک فروشگاه اینترنتی هستی و به پیام‌های مشتریان به زبان فارسی پاسخ می‌دهی. '
                . 'پاسخ‌ها باید کوتاه، مؤدبانه و حرفه‌ای باشند (حداکثر ۲-۳ جمله). '
                . 'اگر پاسخ سؤال را نمی‌دانی، بگو همکاران به‌زودی پاسخ می‌دهند. '
                . 'چیزی خارج از نقش پشتیبانی ننویس.';
    }
    $prompt = "مشتری این پیام را فرستاده:\n\"{$text}\"\n\n"
            . "با توجه به دستورالعمل‌ات، همین حالا پاسخ مناسب را بده.";
    $net = aiNetCfg();
    // v9.35: اگر مهلت داده شد (مثلاً برای دکمهٔ آزمایش که نباید کاربر را معطل
    // کند)، همان مهلتِ کوتاه روی همهٔ تلاش‌ها اعمال می‌شود تا حداکثر در
    // (timeout × روش‌ها) ثانیه جواب برگردد و دکمه هرگز «کار نمی‌کند» نشود.
    if ($timeoutSec !== null && $timeoutSec > 0) $net['timeout'] = max(5, min(30, (int)$timeoutSec));
    $r = aiActiveChat(['messages' => [
        ['role' => 'system', 'content' => $system],
        ['role' => 'user', 'content' => $prompt],
    ], 'temperature' => 0.5, 'max_tokens' => 160], $net);
    if (empty($r['ok'])) return ['ok' => false, 'text' => '', 'error' => mb_substr((string)($r['error'] ?? 'خطا'), 0, 120), 'model' => ''];
    $body = $r['body'] ?? [];
    // v9.94: استخراجِ آگاه به مدل استدلالی (reasoning/reasoning_content + حذف <think>)
    $reply = aiExtractAnswer($body);
    if ($reply === '') return ['ok' => false, 'text' => '', 'error' => 'پاسخ خالی از مدل', 'model' => ''];
    $reply = preg_replace('/\s+/u', ' ', $reply);
    $modelName = (string)($body['model'] ?? ($r['model'] ?? ($r['backup']['model'] ?? '')));
    return ['ok' => true, 'text' => mb_substr($reply, 0, 500), 'error' => '', 'model' => $modelName];
}

/** شمارندهٔ روزانهٔ هر قاعده — با عوض شدن روز صفر می‌شود */
function arDailyCount(array &$st, string $ruleId, int $now): int {
    $today = date('Y-m-d', $now);
    if (($st['day'] ?? '') !== $today) { $st['day'] = $today; $st['daily'] = []; }
    return (int)($st['daily'][$ruleId] ?? 0);
}

function arDailyBump(array &$st, string $ruleId, int $now): void {
    $today = date('Y-m-d', $now);
    if (($st['day'] ?? '') !== $today) { $st['day'] = $today; $st['daily'] = []; }
    $st['daily'][$ruleId] = (int)($st['daily'][$ruleId] ?? 0) + 1;
}

/** آیا این لحظه «بیرون ساعت کاری» است؟ */
function arIsOffHours(array $cfg, int $now): bool {
    $h = (int)date('G', $now);
    $f = $cfg['work_from']; $t = $cfg['work_to'];
    if ($f === $t) return false;                       // ۲۴ ساعته
    if ($f < $t)  return !($h >= $f && $h < $t);       // مثلاً ۹ تا ۲۱
    return !($h >= $f || $h < $t);                     // شیفت شب، مثلاً ۲۲ تا ۶
}

/** آیا متن با این قاعده می‌خورد؟ */
function arRuleMatches(array $rule, string $text): bool {
    $m = (string)($rule['match'] ?? 'contains');
    if ($m === 'always') return true;
    $norm = arNormText($text);
    if ($norm === '') return false;
    foreach (preg_split('~[\r\n|]+~u', (string)($rule['triggers'] ?? '')) as $trig) {
        $trig = trim((string)$trig);
        if ($trig === '') continue;
        if ($m === 'regex') {
            if (@preg_match('~' . str_replace('~', '\~', $trig) . '~ui', $text)) return true;
            continue;
        }
        $tn = arNormText($trig);
        if ($tn === '') continue;
        if ($m === 'exact'  && $norm === $tn) return true;
        if ($m === 'starts' && mb_strpos($norm, $tn) === 0) return true;
        if ($m === 'contains') {
            // مرز کلمه، تا «چند» داخل «چندین» بی‌خود نخورد
            if (preg_match('~(^|\s)' . preg_quote($tn, '~') . '(\s|$)~u', $norm)) return true;
            // عبارت‌های چندکلمه‌ای بدون مرز هم پذیرفته‌اند
            if (mb_strpos($tn, ' ') !== false && mb_strpos($norm, $tn) !== false) return true;
        }
    }
    return false;
}

/** اولین قاعده‌ای که می‌خورد، به ترتیب اولویت */
function arPickRule(array $rules, string $text): ?array {
    $on = array_values(array_filter($rules, fn($r) => !empty($r['on']) && trim((string)($r['reply'] ?? '')) !== ''));
    usort($on, fn($a, $b) => ((int)($a['priority'] ?? 50)) <=> ((int)($b['priority'] ?? 50)));
    foreach ($on as $r) if (arRuleMatches($r, $text)) return $r;
    return null;
}

/** ارسال واقعی یک پیام به گفتگوی باسلام */
function bslSendChatMessage(string $tk, int $chatId, string $text): array {
    if ($chatId <= 0 || trim($text) === '') return ['ok' => false, 'error' => 'ورودی نامعتبر'];
    // طبق openapi چت باسلام: content.text + message_type
    $body = ['content' => ['text' => mb_substr($text, 0, 3000)], 'message_type' => 'text'];
    $r = bslReq($tk, 'POST', 'chats/' . $chatId . '/messages', $body);
    return ['ok' => !empty($r['ok']), 'code' => (int)($r['code'] ?? 0),
            'error' => bslApiError($r, 'ارسال پیام ناموفق', 'chats/{id}/messages', 'customer.chat.write'),
            'body' => $r['body'] ?? null];
}

/* =====================================================================
 *  v10.57 (۷۱): محیطِ چتِ چندغرفه‌ای + آپلود تصویر + ارسالِ چندرسانه‌ای
 *
 *  • bslChatShops      — فهرستِ غرفه‌هایِ فعال (نرخ‌شمارهٔ ۱‌مبنا ثابت است:
 *                        همانِ ترتیبِ bslAllShops — پیش‌فرض اول، بقیه بعد)
 *  • bslChatUploadFile — آپلود تصویر به سرویسِ آپلود باسلام (chat.photo)
 *  • bslChatSendEx     — ارسالِ پیامِ متن و/یا تصویر (attachment)
 * ===================================================================== */

/** فهرستِ غرفه‌هایِ باسلامِ دارایِ توکن، با شمارهٔ پایدارِ ۱‌مبنا */
function bslChatShops(array $cn): array {
    $out = [];
    foreach (bslAllShops($cn) as $sh) {
        $tok = trim((string)($sh['token'] ?? ''));
        $vid = (int)($sh['vendor_id'] ?? 0);
        if ($tok === '' || $vid <= 0) continue;
        $out[] = ['shop' => count($out) + 1, 'vendor_id' => $vid, 'token' => $tok,
                  'name' => (string)($sh['shop_name'] ?? ('غرفهٔ ' . $vid)),
                  'is_default' => !empty($sh['is_default'])];
    }
    return array_slice($out, 0, 8);   // سقفِ محافظ: پُلِ هر ثانیه روی ۸ غرفه نمی‌چرخد
}

function bslShopByNum(array $shops, int $num): ?array {
    foreach ($shops as $sh) if ((int)$sh['shop'] === $num) return $sh;
    return null;
}

/**
 * v10.57 (۷۱): آپلودِ یک فایل (معمولاً تصویر) به سرویسِ آپلود باسلام.
 * طبق openapi: POST /v1/files — multipart با fieldِ «file» و «file_type»
 * (برای چت: chat.photo / chat.file). خروجی id + url است که در
 * attachmentِ پیام استفاده می‌شود.
 */
function bslChatUploadFile(string $tk, string $tmpPath, string $mime, string $name, string $fileType = 'chat.photo'): array {
    if (!class_exists('CURLFile')) return ['ok' => false, 'error' => 'کلاسِ CURLFile در دسترس نیست'];
    if (!is_file($tmpPath)) return ['ok' => false, 'error' => 'فایلِ موقت پیدا نشد'];
    $cf = new CURLFile($tmpPath, $mime !== '' ? $mime : 'application/octet-stream', $name !== '' ? $name : 'upload.jpg');
    $r = bslReq($tk, 'POST', 'files', ['file' => $cf, 'file_type' => $fileType], true, null, true, 1);
    $b = is_array($r['body'] ?? null) ? $r['body'] : [];
    $id = (int)($b['id'] ?? 0);
    $url = (string)($b['urls']['primary'] ?? ($b['url'] ?? ''));
    if (!empty($r['ok']) && $id > 0 && $url !== '') {
        return ['ok' => true, 'id' => $id, 'url' => $url,
                'width' => (int)($b['width'] ?? 0), 'height' => (int)($b['height'] ?? 0),
                'size' => (int)($b['size'] ?? 0)];
    }
    return ['ok' => false, 'id' => $id, 'url' => $url, 'code' => (int)($r['code'] ?? 0),
            'error' => bslApiError($r, 'آپلود فایل ناموفق', 'files (upload)', 'upload')];
}

/**
 * v10.57 (۷۱): ارسالِ پیام به یک گفتگو — متن و/یا تصویر.
 * $file = ['id'=>int,'url'=>str,'width'=>int,'height'=>int,'size'=>int,'name'=>str,'type'=>'picture'|'file']
 * (id و url از bslChatUploadFile می‌آیند؛ attachment طبق openapi).
 */
function bslChatSendEx(string $tk, int $chatId, string $text, ?array $file = null): array {
    if ($chatId <= 0) return ['ok' => false, 'error' => 'ورودی نامعتبر'];
    if ($file) {
        $body = ['message_type' => (($file['type'] ?? '') === 'file') ? 'file' : 'picture',
                 'attachment' => ['files' => [['id' => (int)$file['id'], 'url' => (string)$file['url']]]]];
        if (!empty($file['width']))  $body['attachment']['files'][0]['width'] = (int)$file['width'];
        if (!empty($file['height'])) $body['attachment']['files'][0]['height'] = (int)$file['height'];
        if (!empty($file['size']))   $body['attachment']['files'][0]['size'] = (int)$file['size'];
        if (trim((string)($file['name'] ?? '')) !== '') $body['attachment']['files'][0]['name'] = (string)$file['name'];
        if (trim($text) !== '') $body['content'] = ['text' => mb_substr($text, 0, 3000)];
    } else {
        $body = ['content' => ['text' => mb_substr($text, 0, 3000)], 'message_type' => 'text'];
    }
    $r = bslReq($tk, 'POST', 'chats/' . $chatId . '/messages', $body, false, null, true);
    if (empty($r['ok'])) {
        return ['ok' => false, 'code' => (int)($r['code'] ?? 0),
                'error' => bslApiError($r, 'ارسال پیام ناموفق', 'chats/{id}/messages', 'customer.chat.write')];
    }
    return ['ok' => true];
}

/**
 * v10.55 (69): تاریخچهٔ یک گفتگو — هر دو طرف (مشتری + خودِ ما)،
 * قدیم به جدید. بر خلاف bslFetchChatMessages که برای اعلان فقط طرفِ
 * مقابل را برمی‌گرداند، برای پنجرهٔ «پاسخ دستی» است تا بافتِ
 * گفتگو قبل از جواب دیدنی باشد.
 */
function bslChatThread(string $tk, int $chatId, int $limit = 30): array {
    if ($chatId <= 0) return [];
    $myId = bslMyUserId($tk);
    $lim = max(1, min(50, $limit));
    $r = bslReqRead($tk, 'chats/' . $chatId . '/messages?limit=' . $lim . '&order=desc');
    if (!$r['ok']) return [];
    $rows = $r['body']['data']['messages'] ?? ($r['body']['data'] ?? []);
    if (!is_array($rows)) return [];
    $out = [];
    foreach ($rows as $m) {
        if (!is_array($m)) continue;
        $sid = (int)($m['sender']['id'] ?? 0);
        $mt  = (string)($m['message_type'] ?? '');
        $txt = $m['content']['text'] ?? null;
        if (!is_string($txt) || trim($txt) === '') $txt = ($mt !== '' && $mt !== 'text') ? '[' . $mt . ']' : '';
        /* v10.57 (۷۱): اگر پیام تصویر/فایل است، آدرسش را از شکل‌هایِ ممکنِ
           پاسخ بردار تا در پنجرهٔ چت نمایش داده شود. */
        $imgMR = '';
        foreach ([$m['attachment']['files'][0]['url'] ?? null,
                  $m['content']['url'] ?? null,
                  $m['content']['files'][0]['url'] ?? null,
                  $m['url'] ?? null] as $uImgMR) {
            if (is_string($uImgMR) && strncmp($uImgMR, 'http', 4) === 0) { $imgMR = $uImgMR; break; }
        }
        $out[] = ['mine'   => ($myId > 0 && $sid === $myId),
                  'sender' => trim((string)($m['sender']['name'] ?? '')),
                  'text'   => trim((string)$txt),
                  'at'     => (string)($m['created_at'] ?? ''),
                  'type'   => $mt,
                  'img'    => $imgMR];
    }
    return array_reverse($out);
}

/** آخرین ۲۰ پاسخ خودکار، برای نمایش در رابط کاربری */
function arLogAdd(array $row): void {
    $log = [];
    if (is_file(AUTOREPLY_LOG_FILE)) {
        $d = json_decode((string)@file_get_contents(AUTOREPLY_LOG_FILE), true);
        if (is_array($d)) $log = $d;
    }
    $row['at'] = time();
    $log[] = $row;
    if (count($log) > 60) $log = array_slice($log, -60);
    @file_put_contents(AUTOREPLY_LOG_FILE, json_encode($log, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

function arLogRead(): array {
    if (!is_file(AUTOREPLY_LOG_FILE)) return [];
    $d = json_decode((string)@file_get_contents(AUTOREPLY_LOG_FILE), true);
    return is_array($d) ? array_reverse($d) : [];
}

/**
 * موتور پاسخ خودکار.
 *
 * $dry=true یعنی هیچ چیزی فرستاده و ذخیره نمی‌شود — فقط گزارش می‌دهد که
 * چه اتفاقی می‌افتاد. همان مسیر و همان تصمیم‌ها، فقط بدون ارسال.
 */
function autoReplyRun(array $cn, bool $dry = false, bool $ignoreGrace = false): array {
    $now = time();
    $cfg = arCfg($cn);
    $out = ['ok' => true, 'dry' => $dry, 'checked' => 0, 'replied' => 0, 'skipped' => 0,
            'failed' => 0, 'items' => [], 'at' => $now];

    if (!$cfg['enabled'] && !$dry) { $out['ok'] = false; $out['error'] = 'پاسخ خودکار خاموش است'; return $out; }
    $tk = (string)($cn['basalam']['token'] ?? '');
    if ($tk === '') { $out['ok'] = false; $out['error'] = 'توکن باسلام تنظیم نشده'; return $out; }

    $rules = arLoadRules();
    if (!array_filter($rules, fn($r) => !empty($r['on']))) {
        $out['ok'] = false; $out['error'] = 'هیچ قاعدهٔ فعالی وجود ندارد'; return $out;
    }
    if ($cfg['only_offhours'] && !arIsOffHours($cfg, $now)) {
        $out['skipped_all'] = 'داخل ساعت کاری — پاسخ خودکار فقط بیرون ساعت کاری فعال است';
        return $out;
    }

    $r = bslReq($tk, 'GET', 'chats?limit=' . $cfg['scan_limit'] . '&order_by=updated_at');
    if (empty($r['ok'])) {
        $out['ok'] = false;
        $out['error'] = bslApiError($r, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read');
        return $out;
    }
    $rows = $r['body']['data']['chats'] ?? ($r['body']['data'] ?? []);
    if (!is_array($rows)) $rows = [];

    $st = arLoadState();
    $myId = bslMyUserId($tk);

    foreach ($rows as $c) {
        if (!is_array($c)) continue;
        if ($out['replied'] >= $cfg['max_per_run']) break;
        $nc = bslNormalizeChat($c);
        $chatId = (int)$nc['chat_id'];
        if ($chatId <= 0) continue;
        $out['checked']++;
        $row = ['chat_id' => $chatId, 'who' => $nc['who'], 'text' => mb_substr($nc['text'], 0, 90)];

        // فقط گفتگویی که پیام خوانده‌نشده دارد
        if ((int)$nc['unseen'] <= 0) { $out['skipped']++; continue; }

        $lm = is_array($c['last_message'] ?? null) ? $c['last_message'] : [];
        // اگر آخرین پیام مال خودمان است یعنی جواب داده‌ایم
        if ($myId > 0 && (int)($lm['sender']['id'] ?? 0) === $myId) {
            $out['skipped']++; continue;
        }
        // فقط پیام متنی — عکس و فاکتور و سفارش را دست نمی‌زنیم
        $mt = (string)($lm['message_type'] ?? 'text');
        if ($mt !== '' && $mt !== 'text') {
            $row['skip'] = 'پیام متنی نیست (' . $mt . ')'; $out['items'][] = $row; $out['skipped']++; continue;
        }

        // تأخیر ادب — به ادمین فرصت بده خودش جواب دهد
        $msgAt = strtotime((string)($lm['created_at'] ?? ($nc['updated_at'] ?: ''))) ?: 0;
        if (!$ignoreGrace && $cfg['grace_min'] > 0 && $msgAt > 0
            && ($now - $msgAt) < $cfg['grace_min'] * 60) {
            $row['skip'] = 'هنوز در مهلت ' . $cfg['grace_min'] . ' دقیقه‌ای ادمین';
            $out['items'][] = $row; $out['skipped']++; continue;
        }

        // یک گفتگو در بازهٔ تعیین‌شده فقط یک پاسخ خودکار می‌گیرد
        $prev = $st['chats']['c' . $chatId] ?? null;
        if ($prev && $cfg['per_chat_min'] > 0
            && ($now - (int)($prev['at'] ?? 0)) < $cfg['per_chat_min'] * 60) {
            $row['skip'] = 'به‌تازگی پاسخ خودکار گرفته';
            $out['items'][] = $row; $out['skipped']++; continue;
        }
        // همان پیام قبلی، دوباره جواب نده
        $lastId = (int)($lm['id'] ?? 0);
        if ($prev && $lastId > 0 && (int)($prev['msg_id'] ?? 0) === $lastId) {
            $row['skip'] = 'برای همین پیام قبلاً پاسخ رفته';
            $out['items'][] = $row; $out['skipped']++; continue;
        }

        $text = (string)($lm['content']['text'] ?? $nc['text']);
        /* v9.38: ترتیب اولویت پاسخ‌دهی بین قواعد آماده و هوش مصنوعی.
           در تنظیمات می‌توان از بین این حالت‌ها انتخاب کرد:
             rules_first → اول قواعد؛ اگر هیچ قاعده‌ای نخورد هوش مصنوعی
             ai_first    → اول هوش مصنوعی؛ اگر خطا داد قواعد
             rules_only  → فقط قواعد آماده (هوش مصنوعی صدا زده نمی‌شود)
             ai_only     → فقط هوش مصنوعی (قواعد نادیده گرفته می‌شوند)
           پیش‌فرض rules_first است: «سلام» و سؤال‌های ساده را همان قواعدِ
           آماده جواب می‌دهند (سریع و مطمئن) و سؤال‌های پیچیده‌تر که هیچ
           قاعده‌ای به آن‌ها نمی‌خورد را هوش مصنوعی پاسخ می‌دهد. */
        $order = (string)($cfg['reply_order'] ?? 'rules_first');
        $aiMode = false;             // true = پاسخ از هوش مصنوعی
        $rid = ''; $dmax = 0;
        $reply = '';
        $aiError = '';
        $rule = null;

        if ($order === 'ai_first') {
            $aiRes = arAiReplyText($text);
            if (!empty($aiRes['ok'])) {
                $reply = $aiRes['text'];
                $rid = 'ai';
                $aiMode = true;
            } else {
                $aiError = (string)($aiRes['error'] ?? 'خطا');
                $rule = arPickRule($rules, $text);
                if ($rule !== null) {
                    $rid = (string)$rule['id'];
                    $dmax = (int)($rule['daily_max'] ?? 0);
                    $reply = (string)$rule['reply'];
                }
            }
        } elseif ($order === 'ai_only') {
            $aiRes = arAiReplyText($text);
            if (!empty($aiRes['ok'])) {
                $reply = $aiRes['text'];
                $rid = 'ai';
                $aiMode = true;
            } else {
                $aiError = (string)($aiRes['error'] ?? 'خطا');
            }
        } elseif ($order === 'rules_only') {
            $rule = arPickRule($rules, $text);
            if ($rule !== null) {
                $rid = (string)$rule['id'];
                $dmax = (int)($rule['daily_max'] ?? 0);
                $reply = (string)$rule['reply'];
            }
        } else { // rules_first (پیش‌فرض)
            $rule = arPickRule($rules, $text);
            if ($rule !== null) {
                $rid = (string)$rule['id'];
                $dmax = (int)($rule['daily_max'] ?? 0);
                $reply = (string)$rule['reply'];
            } else {
                $aiRes = arAiReplyText($text);
                if (!empty($aiRes['ok'])) {
                    $reply = $aiRes['text'];
                    $rid = 'ai';
                    $aiMode = true;
                } else {
                    $aiError = (string)($aiRes['error'] ?? 'خطا');
                }
            }
        }

        // تصمیم نهایی — اگر هیچ منبعی پاسخ نداد، این گفتگو رد می‌شود
        if ($reply === '') {
            if ($order === 'rules_only')      $row['skip'] = 'هیچ قاعده‌ای نخورد';
            elseif ($order === 'ai_only')     $row['skip'] = 'هوش مصنوعی پاسخ نداد';
            else                              $row['skip'] = 'هیچ قاعده‌ای نخورد و هوش مصنوعی هم پاسخ نداد';
            $out['items'][] = $row; $out['skipped']++;
            continue;
        }
        if (!$aiMode && $dmax > 0 && arDailyCount($st, $rid, $now) >= $dmax) {
            $row['skip'] = 'سقف روزانهٔ قاعدهٔ «' . $rid . '» پر شده';
            $out['items'][] = $row; $out['skipped']++; continue;
        }
        if ($cfg['sign'] !== '') $reply .= "\n" . $cfg['sign'];
        $row['rule'] = $rid;
        $row['reply'] = mb_substr($reply, 0, 160);
        if ($aiError !== '') $row['ai_error'] = $aiError;

        if ($dry) {
            $row['status'] = 'ارسال می‌شد';
            $out['items'][] = $row; $out['replied']++;
            continue;
        }

        $send = bslSendChatMessage($tk, $chatId, $reply);
        if (!empty($send['ok'])) {
            $out['replied']++;
            $row['status'] = '✅ ارسال شد';
            $st['chats']['c' . $chatId] = ['at' => $now, 'msg_id' => $lastId, 'rule' => $rid];
            if ($aiMode) {
                arLogAdd(['chat_id' => $chatId, 'who' => $nc['who'], 'rule' => 'ai',
                          'in' => mb_substr($text, 0, 120), 'out' => mb_substr($reply, 0, 160)]);
            } else {
                arDailyBump($st, $rid, $now);
                arLogAdd(['chat_id' => $chatId, 'who' => $nc['who'], 'rule' => $rid,
                          'in' => mb_substr($text, 0, 120), 'out' => mb_substr($reply, 0, 160)]);
            }
        } else {
            $out['failed']++;
            $row['status'] = '❌ ' . mb_substr((string)($send['error'] ?? 'خطا'), 0, 90);
        }
        $out['items'][] = $row;
        usleep(400000);
    }

    if (!$dry) { $st['last_run'] = $now; arSaveState($st); }
    return $out;
}

/** خلاصهٔ پاسخ‌های خودکار برای پیام‌رسان */
function arMsg(array $r): string {
    $m = "🤖 پاسخ خودکار به پیام مشتریان\n";
    if (!empty($r['dry'])) $m .= "(پیش‌نمایش — چیزی ارسال نشد)\n";
    $m .= "───────────────\n";
    $m .= 'بررسی‌شده: ' . (int)$r['checked'] . "\n";
    $m .= '✅ پاسخ داده شد: ' . (int)$r['replied'] . "\n";
    if ((int)$r['skipped'] > 0) $m .= '⏭ رد شد: ' . (int)$r['skipped'] . "\n";
    if ((int)$r['failed'] > 0)  $m .= '❌ ناموفق: ' . (int)$r['failed'] . "\n";
    foreach (array_slice($r['items'] ?? [], 0, 6) as $it) {
        if (empty($it['rule'])) continue;
        $m .= '• ' . ($it['who'] ?? '') . ' → «' . ($it['rule'] ?? '') . '»' . "\n";
    }
    return $m;
}

/**
 * بررسی سفارش‌های جدید یا تغییر‌یافته.
 * $test=true یعنی حالت آزمایشی: وضعیت ذخیره نمی‌شود تا اجرای بعدی هم
 * همان نتیجه را بدهد، و اگر چیزی نبود یک پیام نمونه فرستاده می‌شود.
 *
 * v10.45 (۵۹): حالا <b>همهٔ غرفه‌ها</b> را می‌گیرد، نه فقط پیش‌فرض.
 * هر غرفه با <b>توکنِ خودِ خودش</b> و برای <b>vendor_idِ خودش</b>
 * پرس‌وجو می‌شود. شناسهٔ ردیف‌های وضعیت هم با vendor_id نام‌گذاری شده
 * تا شناسهٔ تکراری در دو غرفه (مثلاً سفارش #۵ در هر دو) قاطی نشود.
 * اولین بازدید از هر غرفه <b>خاموش</b> است: وگرنه افزودنِ غرفهٔ دوم،
 * ده موردِ قدیمی را یک‌جا «تازه» می‌دید و ده پیام پشت سر هم می‌فرستاد.
 */
/* v10.86 (100): تعداد ردیف‌ها در هر استعلامِ اعلان. پیش‌فرض ۲۰ (قبلاً ۱۰). */
function notifScanLimit(array $cn): int {
    return max(5, min(50, (int)($cn['notif_scan_limit'] ?? 20)));
}

function notifCheckOrders(array $cn, bool $test = false, bool $send = true): array {
    $shops = array_values(array_filter(bslAllShops($cn),
        fn($s) => trim((string)($s['token'] ?? '')) !== ''));
    if (!$shops) return ['ok' => false, 'found' => 0, 'total_seen' => 0, 'shops' => [],
            'sent' => [], 'sample' => '',
            'errors' => ['تنظیمات باسلام ناقص است (توکن یا غرفه)']];
    $st = notifLoadState(); $now = time(); $cfg = notifRemindCfg($cn);
    $multi = count($shops) > 1;
    $found = 0; $reminded = 0; $totalSeen = 0; $sentTo = []; $samples = [];
    $shopRows = []; $errors = []; $testFound = 0;

    foreach ($shops as $sh) {
        $tk = trim((string)$sh['token']); $vid = (int)$sh['vendor_id'];
        $isDef = !empty($sh['is_default']); $name = (string)$sh['shop_name'];
        // v8.31: مسیر درست طبق مستندات رسمی — سفارش‌های غرفه‌دار
        $r = bslReqRead($tk, 'vendor-parcels?items.vendor_ids=' . $vid . '&per_page=' . notifScanLimit($cn)); /* v10.86 (100) */
        if (!$r['ok']) {
            /* v10.45 (۵۹): خطا دیگر دور ریخته نمی‌شود؛ در 'errors' برمی‌گردد
               تا در گزارشِ آخرین اجرا و پینگِ بعدی دیده شود. */
            $err = bslApiError($r, 'دریافت سفارش‌ها ناموفق', 'vendor-parcels', 'vendor.parcel.read');
            $errors[] = $name . ': ' . $err;
            $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => false, 'error' => $err];
            continue;
        }

        $rows = $r['body']['data'] ?? [];
        $totalSeen += count($rows);

        // v8.38: امضا = وضعیت سفارش. «بی‌جواب» یعنی هنوز ارسال نشده،
        // پس تا وقتی غرفه‌دار کاری نکند یادآوری می‌شود.
        $norm = [];
        foreach ($rows as $o) {
            if (!is_array($o)) continue;
            $np = bslNormalizeParcel($o);
            if ($np['parcel_id'] <= 0) continue;
            $norm[] = ['np' => $np, 'key' => ($isDef ? 'order:' : 'order:' . $vid . ':') . $np['parcel_id'],
                       'sig' => (string)$np['status_id'],
                       'ts' => strtotime($np['created_at'] ?: 'now') ?: $now,
                       'pending' => !empty($np['unsent'])];
        }

        /* نشانِ «آخرین بررسی» جدا برای هر غرفه؛ پیش‌فرض همان کلیدِ
           قدیمی تا وضعیتِ قبلیِ کاربر به‌هم نریزد. */
        $wmKey = $isDef ? 'last_order_check' : 'last_order_check:' . $vid;
        $since = (int)($st[$wmKey] ?? 0);

        if ($test) {
            $testFound += count($norm);
            $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => true,
                           'seen' => count($rows), 'found' => count($norm)];
            if ($norm) $samples[] = bslParcelMsg($norm[0]['np'], '🛒 سفارش جدید باسلام');
            continue;   // حالت تست: وضعیت ذخیره نمی‌شود
        }

        if ($since <= 0) {
            /* v10.45 (۵۹): اولین مشاهدهٔ این غرفه خاموش است (توضیح در بالای تابع). */
            if (!isset($st['items']) || !is_array($st['items'])) $st['items'] = [];
            foreach ($norm as $f) {
                $st['items'][$f['key']] = ['sig' => $f['sig'], 'first' => (int)$f['ts'],
                    'last' => $now, 'n' => 1, 'pending' => !empty($f['pending'])];
            }
            $st[$wmKey] = $now;
            $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => true,
                           'seen' => count($rows), 'found' => 0, 'new_shop' => true];
            continue;
        }

        notifSeedIfNeeded($st, $isDef ? 'orders' : 'orders:' . $vid, $norm, $since);
        $suffix = $multi ? ' — ' . $name : '';
        $shopFound = 0; $shopRemind = 0;
        foreach ($norm as $f) {
            $why = notifDecide($st, $f['key'], $f['sig'], $f['pending'], $cfg, $now);
            if ($why === '') continue;
            $n = (int)($st['items'][$f['key']]['n'] ?? 1);
            $base = $why === 'changed' ? '📦 تغییر وضعیت سفارش باسلام' : '🛒 سفارش جدید باسلام';
            $msg = bslParcelMsg($f['np'], notifHead($why, $base . $suffix, $n - 1));
            $samples[] = $msg;
            if ($why === 'remind') { $shopRemind++; $reminded++; } else { $shopFound++; $found++; }
            if ($send) $sentTo = notifSend($cn, $msg, 'order');
        }
        $st[$wmKey] = $now;
        $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => true,
                       'seen' => count($rows), 'found' => $shopFound, 'reminded' => $shopRemind];
    }

    if ($test) {
        if ($send) {
            $lines = ['🧪 تست سفارش‌ها — ' . count($shops) . ' غرفه'];
            foreach ($shopRows as $sr) {
                if (empty($sr['ok'])) { $lines[] = '• ' . $sr['shop_name'] . ' — ✗ ' . $sr['error']; continue; }
                $lines[] = '• ' . $sr['shop_name'] . ' — ' . (int)$sr['seen']
                         . ' مورد اخیر · ' . (int)$sr['found'] . ' مورد قابل اعلان';
            }
            if ($samples) { $lines[] = '━━━ نمونه:'; $lines[] = mb_substr((string)$samples[0], 0, 400); }
            $sentTo = notifSend($cn, implode("\n", $lines), 'order');
        }
        return ['ok' => true, 'found' => $testFound, 'total_seen' => $totalSeen,
                'sent' => $sentTo, 'sample' => $samples[0] ?? '',
                'shops' => $shopRows, 'errors' => $errors];
    }

    notifPrune($st, $now);
    notifSaveState($st);
    return ['ok' => true, 'found' => $found, 'reminded' => $reminded,
            'total_seen' => $totalSeen, 'sent' => $sentTo, 'sample' => $samples[0] ?? '',
            'shops' => $shopRows, 'errors' => $errors];
}

/**
 * بررسی پیام‌های جدید مشتری.
 * v10.45 (۵۹): همهٔ غرفه‌ها با توکنِ خودشان (توضیح در بالای تابعِ سفارش‌ها).
 *
 * نکتهٔ مهمِ امضا: امضای هر گفتگو شناسهٔ آخرین پیام است. اگر باسلام برای
 * آخرین پیام <b>شناسه برنگرداند</b>، امضا برای همیشه «0» می‌ماند و هیچ
 * پیامِ تازه‌ای «تغییر» نمی‌سازد — یعنی اعلانِ پیامِ مشتری برای همیشه
 * خاموش می‌ماند در حالی‌که همه‌چیز دیگر سالم به نظر می‌رسد. حالا در آن
 * صورت امضا از <b>متنِ خودِ پیام</b> ساخته می‌شود (پیام تازه = متن تازه).
 * یک‌بار هم که امضای جدید ساخته شد، تفاوت با امضای قدیمی <b>بی‌صدا</b>
 * جبران می‌شود تا بلافاصله بعد از به‌روزرسانی سیلی پیام «تغییر وضعیت»
 * فرستاده نشود.
 */
function notifCheckChats(array $cn, bool $test = false, bool $send = true): array {
    $shops = array_values(array_filter(bslAllShops($cn),
        fn($s) => trim((string)($s['token'] ?? '')) !== ''));
    if (!$shops) return ['ok' => false, 'found' => 0, 'total_seen' => 0, 'shops' => [],
            'sent' => [], 'sample' => '',
            'errors' => ['تنظیمات باسلام ناقص است (توکن یا غرفه)']];
    /* v10.46 (۶۰): انتخاب غرفه برای رویداد «پیام مشتری» (دراپ‌داونِ بخش
       اعلان‌ها). 0 = همهٔ غرفه‌ها. اگر غرفهٔ انتخاب‌شده حذف شده باشد، به
       جای سکوتِ کامل، همهٔ غرفه‌ها برگردانده می‌شوند. */
    $onlyVid = (int)($cn['notif_chat_shop'] ?? 0);
    if ($onlyVid > 0) {
        $sel = array_values(array_filter($shops, fn($s) => (int)($s['vendor_id'] ?? 0) === $onlyVid));
        if ($sel) $shops = $sel;
    }
    $st = notifLoadState(); $now = time(); $cfg = notifRemindCfg($cn);
    $multi = count($shops) > 1;
    $found = 0; $reminded = 0; $totalSeen = 0; $sentTo = []; $samples = [];
    $shopRows = []; $errors = []; $testFound = 0; $pendingNow = 0; $rawSample = '';

    foreach ($shops as $sh) {
        $tk = trim((string)$sh['token']); $vid = (int)$sh['vendor_id'];
        $isDef = !empty($sh['is_default']); $name = (string)$sh['shop_name'];
        // v8.31: مسیر درست — گفتگوها زیر ریشه است، نه زیر vendors
        $r = bslReqRead($tk, 'chats?limit=' . notifScanLimit($cn) . '&order_by=updated_at'); /* v10.86 (100) */
        if (!$r['ok']) {
            /* v10.45 (۵۹): خطا دیگر دور ریخته نمی‌شود (توضیح در تابع سفارش‌ها). */
            $err = bslApiError($r, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read');
            $errors[] = $name . ': ' . $err;
            $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => false, 'error' => $err];
            continue;
        }

        // v8.31: پاسخ chats به شکل data.chats است، نه data
        $rows = $r['body']['data']['chats'] ?? ($r['body']['data'] ?? []);
        $totalSeen += count($rows);

        $norm = [];
        foreach ($rows as $c) {
            if (!is_array($c)) continue;
            $nc = bslNormalizeChat($c);
            if ($nc['chat_id'] <= 0) continue;
            /* v10.84 (98): اگر آخرین پیام از خودِ غرفه‌دار (ادمین) باشد،
               رویداد «پیام مشتری» نمی‌زند — پاسخِ خودِ ما نباید به
               پیام‌رسان برود. (bslMyUserId کشِ استاتیک دارد؛ بدونِ
               درخواستِ API اضافه.) */
            $_myUid84 = bslMyUserId($tk);
            $_lmSid84 = (int)($c['last_message']['sender']['id'] ?? 0);
            if ($_myUid84 > 0 && $_lmSid84 > 0 && $_lmSid84 === $_myUid84) continue;
            $lastId = (int)($c['last_message']['id'] ?? 0);
            // v8.38: امضا فقط شناسهٔ آخرین پیام است. اگر تعداد خوانده‌نشده را هم
            // در امضا بیاوریم، جواب دادن مشتری (۲ → ۰) مثل «رویداد تازه» دیده
            // می‌شود و یک اعلان بی‌مورد می‌فرستد.
            // v10.45 (۵۹): اگر شناسهٔ آخرین پیام نبود، امضا از متنِ پیام ساخته می‌شود.
            // v10.47 (۶۱): و اگر متن هم نیامد (تغییرِ ساختارِ API)، updated_at
            // آخرین نشانهٔ «پیام تازه» است — وگرنه امضا برای همیشه ثابت می‌ماند
            // و هیچ رویدادی دیگر دیده نمی‌شود (سکوتِ کاملِ بی‌صدا).
            $sig = $lastId > 0 ? (string)$lastId
                               : ('t' . substr(md5(((string)$nc['text']) . '|' . (string)$nc['updated_at']), 0, 12));
            $norm[] = ['nc' => $nc, 'key' => ($isDef ? 'chat:' : 'chat:' . $vid . ':') . $nc['chat_id'],
                       'sig' => $sig,
                       'ts' => strtotime($nc['updated_at'] ?: 'now') ?: $now,
                       'pending' => $nc['unseen'] > 0];
        }

        /* v10.47 (۶۱): شمارشِ «بی‌جواب» (موردِ یادآوری) و تشخیصِ
           «متنِ پیام نمی‌آید» — اگر ساختارِ پاسخِ باسلام عوض شده باشد،
           این دو نشانه در تست دیده می‌شوند: pending صفر می‌ماند و متن
           «—» می‌شود، بدون اینکه خطایی گزارش شود. */
        $pendShop = 0; $noText = 0;
        foreach ($norm as $f) {
            if (!empty($f['pending'])) $pendShop++;
            $t = trim((string)$f['nc']['text']);
            if ($t === '' || $t === '—') $noText++;
        }
        $pendingNow += $pendShop;
        if ($noText > 0 && $rawSample === '' && isset($rows[0]) && is_array($rows[0])) {
            $rawSample = mb_substr((string)json_encode($rows[0], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), 0, 320);
        }

        $wmKey = $isDef ? 'last_chat_check' : 'last_chat_check:' . $vid;
        $since = (int)($st[$wmKey] ?? 0);

        if ($test) {
            $testFound += count($norm);
            $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => true,
                           'seen' => count($rows), 'found' => count($norm),
                           'pending' => $pendShop, 'no_text' => $noText];
            if ($norm) {
                $f = $norm[0];
                $body = $f['pending'] ? bslFetchChatMessages($tk, $f['nc']['chat_id'], min(10, max(1, $f['nc']['unseen']))) : [];
                $samples[] = bslChatMsg($f['nc'], '💬 پیام مشتری باسلام', $body);
            }
            continue;   // حالت تست: وضعیت ذخیره نمی‌شود
        }

        if ($since <= 0) {
            /* v10.45 (۵۹): اولین مشاهدهٔ این غرفه خاموش است (توضیح در تابع سفارش‌ها). */
            if (!isset($st['items']) || !is_array($st['items'])) $st['items'] = [];
            foreach ($norm as $f) {
                $st['items'][$f['key']] = ['sig' => $f['sig'], 'first' => (int)$f['ts'],
                    'last' => $now, 'n' => 1, 'pending' => !empty($f['pending'])];
            }
            $st[$wmKey] = $now;
            $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => true,
                           'seen' => count($rows), 'found' => 0, 'new_shop' => true];
            continue;
        }

        /* v10.45 (۵۹): مهاجرتِ یک‌بارهٔ امضا — اگر برای ردیفی که قبلاً
           ثبت شده امضای جدید شکلِ دیگری گرفت، امضا را بی‌صدا به‌روز می‌کنیم
           تا یک سیلِ «تغییر وضعیت» نشود. */
        if (empty($st['chat_sig2']) && isset($st['items']) && is_array($st['items'])) {
            foreach ($norm as $f) {
                $pk = $st['items'][$f['key']] ?? null;
                if (is_array($pk) && (string)($pk['sig'] ?? '') !== $f['sig']) {
                    $pk['sig'] = $f['sig'];
                    $st['items'][$f['key']] = $pk;
                }
            }
            $st['chat_sig2'] = $now;
        }

        notifSeedIfNeeded($st, $isDef ? 'chats' : 'chats:' . $vid, $norm, $since);
        $suffix = $multi ? ' — ' . $name : '';
        $shopFound = 0; $shopRemind = 0;
        foreach ($norm as $f) {
            $why = notifDecide($st, $f['key'], $f['sig'], $f['pending'], $cfg, $now);
            if ($why === '') continue;
            $n = (int)($st['items'][$f['key']]['n'] ?? 1);
            $body = $f['pending'] ? bslFetchChatMessages($tk, $f['nc']['chat_id'], min(10, max(1, $f['nc']['unseen']))) : [];
            $msg = bslChatMsg($f['nc'], notifHead($why, '💬 پیام مشتری باسلام' . $suffix, $n - 1), $body);
            $samples[] = $msg;
            if ($why === 'remind') { $shopRemind++; $reminded++; } else { $shopFound++; $found++; }
            if ($send) {
                $_media109 = bslChatCollectMedia($f['nc'], $body);
                $sentTo = notifSend($cn, $msg, null, $_media109);
                /* v10.85 (99): message_id با context چت برای webhook */
                $_ncCh85 = (int)($f['nc']['chat_id'] ?? 0); $_ncSh85 = (int)($f['nc']['shop'] ?? 1); $_ncWh85 = (string)($f['nc']['who'] ?? '');
                foreach (['bale_msg_id' => 'bale', 'rubika_msg_id' => 'rubika', 'telegram_msg_id' => 'telegram'] as $_kM85 => $_mM85) {
                    if (!empty($sentTo[$_kM85])) msgrSaveMsg($_mM85, (string)$sentTo[$_kM85], $_ncCh85, $_ncSh85, $_ncWh85);
                }
            }
        }
        $st[$wmKey] = $now;
        $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => true,
                       'seen' => count($rows), 'found' => $shopFound, 'reminded' => $shopRemind,
                       'pending' => $pendShop]; /* v10.47 (۶۱): چند گفتگوی بی‌جواب است */
    }

    if ($test) {
        if ($send) {
            $lines = ['🧪 تست پیام‌ها — ' . count($shops) . ' غرفه'];
            foreach ($shopRows as $sr) {
                if (empty($sr['ok'])) { $lines[] = '• ' . $sr['shop_name'] . ' — ✗ ' . $sr['error']; continue; }
                $lines[] = '• ' . $sr['shop_name'] . ' — ' . (int)$sr['seen']
                         . ' گفتگوی اخیر · ' . (int)$sr['found'] . ' مورد قابل اعلان'
                         /* v10.47 (۶۱): «بی‌جواب» و «متن نمی‌آید» را هم نشان بده */
                         . (!empty($sr['pending']) ? ' · ' . (int)$sr['pending'] . ' بی‌جواب' : '')
                         . (!empty($sr['no_text']) ? ' · ⚠️ متنِ پیام نمی‌آید' : '');
            }
            if ($rawSample !== '') {
                $lines[] = '⚠️ نمونه دادهٔ خام باسلام (برای بررسی ساختار):';
                $lines[] = $rawSample;
            }
            if ($samples) { $lines[] = '━━━ نمونه:'; $lines[] = mb_substr((string)$samples[0], 0, 400); }
            $sentTo = notifSend($cn, implode("\n", $lines));
        }
        return ['ok' => true, 'found' => $testFound, 'total_seen' => $totalSeen, 'pending' => $pendingNow, /* v10.47 (۶۱) */
                'sent' => $sentTo, 'sample' => $samples[0] ?? '',
                'shops' => $shopRows, 'errors' => $errors];
    }

    notifPrune($st, $now);
    notifSaveState($st);
    return ['ok' => true, 'found' => $found, 'reminded' => $reminded, 'pending' => $pendingNow, /* v10.47 (۶۱) */
            'total_seen' => $totalSeen, 'sent' => $sentTo, 'sample' => $samples[0] ?? '',
            'shops' => $shopRows, 'errors' => $errors];
}

/**
 * بررسی تغییر وضعیت یا افزوده شدن محصول.
 * v10.45 (۵۹): همهٔ غرفه‌ها با توکنِ خودشان (توضیح در بالای تابعِ سفارش‌ها).
 */
function notifCheckProducts(array $cn, bool $test = false, bool $send = true): array {
    $shops = array_values(array_filter(bslAllShops($cn),
        fn($s) => trim((string)($s['token'] ?? '')) !== ''));
    if (!$shops) return ['ok' => false, 'found' => 0, 'total_seen' => 0, 'shops' => [],
            'sent' => [], 'sample' => '',
            'errors' => ['تنظیمات باسلام ناقص است (توکن یا غرفه)']];
    $st = notifLoadState(); $now = time(); $cfg = notifRemindCfg($cn);
    $multi = count($shops) > 1;
    $found = 0; $reminded = 0; $totalSeen = 0; $sentTo = []; $samples = [];
    $shopRows = []; $errors = []; $testFound = 0;

    foreach ($shops as $sh) {
        $tk = trim((string)$sh['token']); $vid = (int)$sh['vendor_id'];
        $isDef = !empty($sh['is_default']); $name = (string)$sh['shop_name'];
        $r = bslReqRead($tk, 'vendors/' . $vid . '/products?per_page=' . notifScanLimit($cn) . '&statuses=2976&statuses=3790&statuses=3567'); /* v10.86 (100) */
        if (!$r['ok']) {
            /* v10.45 (۵۹): خطا دیگر دور ریخته نمی‌شود (توضیح در تابع سفارش‌ها). */
            $err = bslApiError($r, 'دریافت محصولات ناموفق', 'vendors/{id}/products', 'vendor.product.read');
            $errors[] = $name . ': ' . $err;
            $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => false, 'error' => $err];
            continue;
        }

        $rows = $r['body']['data'] ?? [];
        $totalSeen += count($rows);

        // v8.38: امضا = وضعیت محصول. «تأیید نشده» نیاز به اقدام دارد، پس
        // تا وقتی درست نشود یادآوری می‌شود؛ محصول فعال یادآوری ندارد.
        $norm = [];
        $sfx = $multi ? ' — ' . $name : '';
        foreach ($rows as $p) {
            if (!is_array($p)) continue;
            $pid = (int)($p['id'] ?? 0);
            if ($pid <= 0) continue;
            $ps = $p['status'] ?? [];
            $val = is_array($ps) ? (int)($ps['value'] ?? 0) : (int)$ps;
            $title = mb_substr((string)($p['title'] ?? ($p['name'] ?? 'محصول')), 0, 60);
            if ($val === 3567)      { $txt = "📋 تغییر وضعیت محصول باسلام" . $sfx . "\nمحصول: " . $title . "\nوضعیت جدید: تأیید نشده ❌"; $pend = true; }
            elseif ($val === 4184)  { $txt = "📋 تغییر وضعیت محصول باسلام" . $sfx . "\nمحصول: " . $title . "\nوضعیت جدید: بایگانی 🗑️"; $pend = false; }
            elseif ($val === 2976)  { $txt = "➕ محصول جدید باسلام" . $sfx . "\nمحصول: " . $title . "\nوضعیت: فعال ✅"; $pend = false; }
            else continue;
            $norm[] = ['key' => ($isDef ? 'prod:' : 'prod:' . $vid . ':') . $pid, 'sig' => (string)$val, 'text' => $txt,
                       'ts' => strtotime($p['created_at'] ?? 'now') ?: $now, 'pending' => $pend];
        }

        $wmKey = $isDef ? 'last_product_check' : 'last_product_check:' . $vid;
        $since = (int)($st[$wmKey] ?? 0);

        if ($test) {
            $testFound += count($norm);
            $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => true,
                           'seen' => count($rows), 'found' => count($norm)];
            if ($norm) $samples[] = $norm[0]['text'];
            continue;   // حالت تست: وضعیت ذخیره نمی‌شود
        }

        if ($since <= 0) {
            /* v10.45 (۵۹): اولین مشاهدهٔ این غرفه خاموش است (توضیح در تابع سفارش‌ها). */
            if (!isset($st['items']) || !is_array($st['items'])) $st['items'] = [];
            foreach ($norm as $f) {
                $st['items'][$f['key']] = ['sig' => $f['sig'], 'first' => (int)$f['ts'],
                    'last' => $now, 'n' => 1, 'pending' => !empty($f['pending'])];
            }
            $st[$wmKey] = $now;
            $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => true,
                           'seen' => count($rows), 'found' => 0, 'new_shop' => true];
            continue;
        }

        notifSeedIfNeeded($st, $isDef ? 'products' : 'products:' . $vid, $norm, $since);
        $shopFound = 0; $shopRemind = 0;
        foreach ($norm as $f) {
            $why = notifDecide($st, $f['key'], $f['sig'], $f['pending'], $cfg, $now);
            if ($why === '') continue;
            $n = (int)($st['items'][$f['key']]['n'] ?? 1);
            $msg = $why === 'remind'
                 ? notifHead($why, '', $n - 1) . "\n" . $f['text']
                 : $f['text'];
            $samples[] = $msg;
            if ($why === 'remind') { $shopRemind++; $reminded++; } else { $shopFound++; $found++; }
            if ($send) $sentTo = notifSend($cn, $msg, 'product');
        }
        $st[$wmKey] = $now;
        $shopRows[] = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => true,
                       'seen' => count($rows), 'found' => $shopFound, 'reminded' => $shopRemind];
    }

    if ($test) {
        if ($send) {
            $lines = ['🧪 تست محصولات — ' . count($shops) . ' غرفه'];
            foreach ($shopRows as $sr) {
                if (empty($sr['ok'])) { $lines[] = '• ' . $sr['shop_name'] . ' — ✗ ' . $sr['error']; continue; }
                $lines[] = '• ' . $sr['shop_name'] . ' — ' . (int)$sr['seen']
                         . ' محصول اخیر · ' . (int)$sr['found'] . ' مورد قابل اعلان';
            }
            if ($samples) { $lines[] = '━━━ نمونه:'; $lines[] = mb_substr((string)$samples[0], 0, 400); }
            $sentTo = notifSend($cn, implode("\n", $lines), 'product');
        }
        return ['ok' => true, 'found' => $testFound, 'total_seen' => $totalSeen,
                'sent' => $sentTo, 'sample' => $samples[0] ?? '',
                'shops' => $shopRows, 'errors' => $errors];
    }

    notifPrune($st, $now);
    notifSaveState($st);
    return ['ok' => true, 'found' => $found, 'reminded' => $reminded,
            'total_seen' => $totalSeen, 'sent' => $sentTo, 'sample' => $samples[0] ?? '',
            'shops' => $shopRows, 'errors' => $errors];
}

/* =====================================================================
 *  v8.33: نگهبان صف — تشخیص گیر کردن ارسال و ادامهٔ خودکار
 *
 *  چرا امن است: قفل‌های bsl_backend/woo_backend با flock گرفته می‌شوند.
 *  اگر پردازه واقعاً زنده باشد قفل در اختیار اوست و درخواست تازه فوراً
 *  «already running» می‌گیرد و برمی‌گردد. اگر پردازه مرده باشد، سیستم‌عامل
 *  قفل را آزاد کرده و کار ادامه پیدا می‌کند. پس نگهبان هیچ‌وقت دو پردازش
 *  موازی نمی‌سازد و روی سرعت ارسال اثری ندارد — فقط یک درخواست HTTP سبک
 *  است که وقتی چیزی گیر نکرده باشد اصلاً فرستاده نمی‌شود.
 * ===================================================================== */

/** آدرس خود اسکریپت برای فراخوانی داخلی */
function selfBaseUrl(): string {
    $host = $_SERVER['HTTP_HOST'] ?? '';
    if ($host === '') return '';
    $https = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off';
    return ($https ? 'https' : 'http') . '://' . $host . ($_SERVER['SCRIPT_NAME'] ?? '');
}

/* =====================================================================
 *  v10.35 (۴۷ه): وضعیتِ «همگام‌سازیِ دستی»
 *
 *  دکمهٔ تبِ شروع یک کارِ پس‌زمینه راه می‌اندازد که ممکن است دقایقی طول
 *  بکشد. برای اینکه در مدیر وظیفه ردیفِ خودش را داشته باشد (با نوار
 *  پیشرفت، دکمهٔ توقف و «ادامه»)، مثل بقیهٔ کارها یک فایلِ پیشرفتِ
 *  استاندارد می‌نویسد.
 * ===================================================================== */

/** آیا این اجرا یک همگام‌سازیِ دستی است؟ */
function manualSyncActive(): bool {
    return !empty($_GET['manual_sync']);
}

/** سیگنالِ توقف — فقط وقتی تازه باشد معتبر است */
function manualSyncStopped(): bool {
    clearstatcache(true, MANUAL_SYNC_STOP_FILE);
    if (!file_exists(MANUAL_SYNC_STOP_FILE)) return false;
    return (time() - (int)@filemtime(MANUAL_SYNC_STOP_FILE)) <= 900;
}

/** یک خط در پیشرفتِ همگام‌سازیِ دستی می‌نویسد (اگر اجرای دستی نباشد بی‌اثر است) */
function manualSyncProgress(array $patch, string $log = ''): void {
    if (!manualSyncActive()) return;
    $p = readProgress(MANUAL_SYNC_PROGRESS_FILE);
    if (!is_array($p)) $p = [];
    foreach ($patch as $k => $v) $p[$k] = $v;
    if ($log !== '') {
        $lg = is_array($p['recent_log'] ?? null) ? $p['recent_log'] : [];
        $lg[] = $log;
        if (count($lg) > 40) $lg = array_slice($lg, -40);
        $p['recent_log'] = $lg;
        $p['total_log_count'] = (int)($p['total_log_count'] ?? 0) + 1;
    }
    $p['ts'] = time();
    $p['last_progress_ts'] = time();
    /* v10.129: خودِ زنجیرهٔ دستی هم یک checkpoint ارکستراسیون دارد؛
       بنابراین قطع بین استخراج، صف‌سازی و پمپ ارسال در کران بعدی قابل تشخیص است. */
    $oldManualCp = is_array($p['checkpoint'] ?? null) ? $p['checkpoint'] : [];
    /* checkpoint یک snapshot است، نه فهرستِ محدودِ فیلدها: queue_id،
       counters و phaseهای مقصدی را هم در resume نگه دار. */
    $p['checkpoint'] = array_merge($oldManualCp, [
        'profile_key' => (string)($p['profile_key'] ?? ($oldManualCp['profile_key'] ?? '')),
        'profile_name' => (string)($p['profile_name'] ?? ($oldManualCp['profile_name'] ?? '')),
        'phase' => (string)($p['phase'] ?? ($oldManualCp['phase'] ?? '')),
        'current' => (int)($p['current'] ?? ($oldManualCp['current'] ?? 0)),
        'total' => (int)($p['total'] ?? ($oldManualCp['total'] ?? 4)),
        'target' => (string)($p['target'] ?? ($oldManualCp['target'] ?? '')),
        'started_at' => (int)($p['started_at'] ?? ($oldManualCp['started_at'] ?? time())),
    ]);
    writeProgress(MANUAL_SYNC_PROGRESS_FILE, $p);
}

/** یک فراخوانی «شلیک کن و فراموش کن» به خود اسکریپت */
function fireAndForget(string $qs, int $timeoutMs = 1200, ?array $post = null): bool {
    $base = selfBaseUrl();
    if ($base === '') return false;
    $ch = curl_init($base . '?' . ltrim($qs, '?'));
    $opt = [CURLOPT_RETURNTRANSFER => 1, CURLOPT_NOSIGNAL => 1,
        CURLOPT_TIMEOUT_MS => $timeoutMs, CURLOPT_CONNECTTIMEOUT => 3,
        CURLOPT_SSL_VERIFYPEER => 0, CURLOPT_SSL_VERIFYHOST => 0];
    // v8.45: پردازنده‌ها پارامترها را از POST می‌خوانند. نگهبان قبلاً فقط
    // GET می‌فرستاد، پس from_file و queue_id و start_index خالی می‌ماندند
    // و بازیابی از محصول اول شروع می‌شد — کار تکراری و گاهی ارسال دوباره.
    if ($post !== null) {
        $opt[CURLOPT_POST] = true;
        $opt[CURLOPT_POSTFIELDS] = http_build_query($post);
    }
    curl_setopt_array($ch, $opt);
    $body = curl_exec($ch);
    $err = curl_errno($ch);
    curl_close($ch);
    if ($err === CURLE_OPERATION_TIMEDOUT) return true;
    if ($err !== 0) return false;
    /* پاسخِ فوریِ workerِ موازی «already running» است، نه dispatch موفق. */
    $reply = is_string($body) ? json_decode($body, true) : null;
    if (is_array($reply) && empty($reply['ok']) && (!empty($reply['skipped']) || !empty($reply['running']))) return false;
    return true;
}

/** قفل مشترکِ worker و mutationهای حساسِ صف؛ فایل عمداً حذف نمی‌شود. */
function queueBackendLock(string $which) {
    $file = __DIR__ . ($which === 'bsl' ? '/bsl_backend.lock' : '/woo_backend.lock');
    $fp = @fopen($file, 'c');
    if (!$fp || !@flock($fp, LOCK_EX | LOCK_NB)) {
        if (is_resource($fp)) @fclose($fp);
        return null;
    }
    return $fp;
}
function queueBackendUnlock($fp): void {
    if (is_resource($fp)) { @flock($fp, LOCK_UN); @fclose($fp); }
}

/**
 * بررسی می‌کند صف ارسال گیر کرده یا نه.
 * گیر کرده = ردیفی در حال اجراست ولی از آخرین پیشرفتش بیش از
 * $staleAfter ثانیه گذشته، یا ردیفی در انتظار مانده و هیچ‌کس نمی‌بردش.
 */
function queueStallCheck(string $which, int $staleAfter = 300, bool $includePaused = false): array {
    $isBsl = $which === 'bsl';
    $qFile = $isBsl ? BSL_QUEUE_FILE : WOO_QUEUE_FILE;
    $pFile = $isBsl ? BSL_PROGRESS_FILE : WOO_PROGRESS_FILE;
    $lock  = __DIR__ . ($isBsl ? '/bsl_backend.lock' : '/woo_backend.lock');

    $q = json_decode((string)@file_get_contents($qFile), true);
    $entries = is_array($q['entries'] ?? null) ? $q['entries'] : [];
    $running = null; $waiting = null;
    foreach ($entries as $e) {
        $st = $e['status'] ?? '';
        if ($st === 'running' && $running === null) $running = $e;
        if (($st === 'waiting' || ($includePaused && $st === 'paused')) && $waiting === null) $waiting = $e;
    }
    if ($running === null && $waiting === null) {
        return ['stalled' => false, 'reason' => 'صفی در جریان نیست'];
    }

    // v8.45: ردیفی که کارش تمام شده ولی وضعیتش «running» مانده، جلوی
    // شروع ردیف بعدی را می‌گیرد. اول این را ببند تا صف راه بیفتد.
    if ($running !== null) {
        $pg = readProgress($pFile);
        $sameRow = ((string)($pg['queue_id'] ?? '') === (string)($running['id'] ?? ''))
                   || ((string)($pg['queue_id'] ?? '') === '');
        $tot = (int)($running['total'] ?? 0);
        $cur = max((int)($running['current'] ?? 0), (int)($pg['current'] ?? 0));
        $finished = !empty($pg['done']) || ($tot > 0 && $cur >= $tot);
        if ($sameRow && $finished) {
            /* بسته‌کردنِ ردیفِ تمام‌شده هم mutation است؛ آن را با snapshot
               قدیمی و بدونِ مالکیت ننویس، چون worker/دکمه ممکن است در همین
               فاصله صف را عوض کرده باشد. */
            $finishFp = @fopen($lock, 'c');
            $finishOwned = $finishFp && @flock($finishFp, LOCK_EX | LOCK_NB);
            if (!$finishOwned) {
                if (is_resource($finishFp)) @fclose($finishFp);
            } else {
                $latestQ = json_decode((string)@file_get_contents($qFile), true);
                $latestQ = is_array($latestQ) ? $latestQ : ['entries' => []];
                $latestEntries = is_array($latestQ['entries'] ?? null) ? $latestQ['entries'] : [];
                foreach ($latestEntries as $i => $e) {
                    if (!is_array($e) || (string)($e['id'] ?? '') !== (string)($running['id'] ?? '')
                        || (string)($e['status'] ?? '') !== 'running') continue;
                    $latestEntries[$i]['status'] = 'done';
                    $latestEntries[$i]['done_at'] = time();
                    $latestEntries[$i]['current'] = max((int)($latestEntries[$i]['current'] ?? 0), $cur);
                    break;
                }
                $latestQ['entries'] = $latestEntries;
                @file_put_contents($qFile, json_encode($latestQ, JSON_UNESCAPED_UNICODE), LOCK_EX);
                $q = $latestQ; $entries = $latestEntries; $running = null;
                @flock($finishFp, LOCK_UN); @fclose($finishFp);
            }
            if ($running === null) {
                $waiting = null;
                foreach ($entries as $e) {
                    if (($e['status'] ?? '') === 'waiting'
                        || ($includePaused && ($e['status'] ?? '') === 'paused')) { $waiting = $e; break; }
                }
                if ($waiting === null) {
                    return ['stalled' => false, 'reason' => 'ردیف تمام‌شده بسته شد'];
                }
            }
        }
    }

    $prog = readProgress($pFile);
    $now  = time();
    // پردازهٔ زنده قفل را در دست دارد؛ اگر قفل باز شود یعنی پردازه رفته
    $lockFresh = false;
    if (is_file($lock)) {
        $fp = @fopen($lock, 'c');
        if ($fp) {
            $lockFresh = !@flock($fp, LOCK_EX | LOCK_NB);   // نشد ⇒ کسی گرفته ⇒ زنده
            if (!$lockFresh) @flock($fp, LOCK_UN);
            @fclose($fp);
        }
    }

    if ($running !== null && !$lockFresh
        && (!empty($prog['stopped']) || !empty($prog['cancelled']) || !empty($prog['failed_resume'])
            || (!empty($prog['partial']) && !empty($prog['done'])))
        && empty($prog['running'])) {
        /* stop/error checkpoint بعد از مرگِ worker نباید ۵ دقیقهٔ دیگر پشتِ
           سنِ heartbeat بماند؛ lock آزاد + state ناقص یعنی همین cron باید
           آن را به queueStallRecover تحویل بدهد. */
        $stopCur = max((int)($running['current'] ?? 0), (int)($prog['current'] ?? 0));
        return ['stalled' => true, 'kind' => 'running', 'idle' => 0,
            'queue_id' => $running['id'] ?? '', 'lock_held' => false,
            'beat_from' => 'stopped_checkpoint', 'current' => $stopCur,
            'resume_from' => $stopCur, 'total' => (int)($running['total'] ?? 0)];
    }

    if ($running !== null) {
        /* v10.36 (۴۹الف): همان اصلاحِ استخراج، برای ارسال‌ها.
           کاربر گزارش داد این داستان «برای ارسال‌ها هم دیده شده» — و
           دقیقاً همان ریشه را داشت: ردیف‌های صفِ ارسال اصلاً queue_id
           جداگانه در فایلِ پیشرفت ندارند، پس هر وقت فایل مالِ ردیفِ دیگری
           بود مبنا می‌شد started_at، یعنی سنِ کار. ارسالِ ۵۰۰ محصولی که
           نیم ساعت طول می‌کشد، از دقیقهٔ پنجم «گیرکرده» اعلام می‌شد. */
        $_iwS = queueRowIdle($which, $running, $prog, $now,
            $lockFresh ? ['lock' => $now] : []);
        $idle = (int)$_iwS['idle'];
        if ($lockFresh && $idle <= $staleAfter) {
            return ['stalled' => false, 'reason' => 'در حال اجرا', 'idle' => $idle];
        }
        if ($idle > $staleAfter) {
            /* v10.56 (۷۰): چک‌پوینتِ ادامه. در طولِ ارسالِ طولانی «current»ِ
               ردیفِ صف صفر می‌ماند (وِرکر آن را فقط در پایان و در هنگام پُلِ
               مرورگر می‌نویسد) — نگهبان اگر فقط ردیف را بخواند، وظیفه را از
               محصولِ ۱ دوباره راه می‌اندازد. حالا اگر فایلِ پیشرفت مالِ همین
               ردیف است، currentِ خودش هم مبنا می‌شود. معنای «current»:
               شمارهٔ ۱‌مبنا از آخرینِ محصولِ در حالِ کار — یعنی اولینِ
               محصولی که باید (دوباره) پردازش شود. */
            $stCur = (int)($running['current'] ?? 0);
            $stPgQ = trim((string)($prog['queue_id'] ?? ''));
            if ($stPgQ === (string)($running['id'] ?? '')) {
                $stCur = max($stCur, (int)($prog['current'] ?? 0));
            }
            return ['stalled' => true, 'kind' => 'running', 'idle' => $idle,
                'queue_id' => $running['id'] ?? '', 'lock_held' => $lockFresh,
                'beat_from' => (string)$_iwS['why'],
                'current' => $stCur,
                'resume_from' => $stCur,
                'total' => (int)($running['total'] ?? 0)];
        }
        return ['stalled' => false, 'reason' => 'تازه شروع شده', 'idle' => $idle];
    }

    // فقط ردیف در انتظار — اگر پردازنده‌ای زنده نیست باید راهش انداخت
    if ($lockFresh) return ['stalled' => false, 'reason' => 'پردازنده فعال است'];
    $pendingResumeAt = (int)($waiting['resume_requested_at'] ?? 0);
    if ($pendingResumeAt > 0 && $now >= $pendingResumeAt
        && ($now - $pendingResumeAt) <= QUEUE_RESUME_HANDOFF_SEC) {
        return ['stalled' => false, 'reason' => 'درخواست ادامه در حال تحویل به worker است', 'idle' => 0];
    }
    /* v10.104: ردیف waiting هم ممکن است current داشته باشد (ادامهٔ failed) */
    $__wCur = max(0, (int)($waiting['current'] ?? 0));
    return ['stalled' => true, 'kind' => 'waiting', 'idle' => 0,
        'queue_id' => $waiting['id'] ?? '', 'lock_held' => false,
        'current' => $__wCur, 'resume_from' => $__wCur,
        'total' => (int)($waiting['total'] ?? 0)];
}

/** اگر صف گیر کرده باشد، پردازش را دوباره راه می‌اندازد */
/**
 * v8.45: بازیابی صف گیرکرده — با ادامه از همان جایی که مانده بود.
 *
 * قبلاً فقط یک GET خالی فرستاده می‌شد. چون پردازنده پارامترها را از POST
 * می‌خواند، هر بازیابی از محصول اول شروع می‌کرد؛ یعنی صدها محصول دوباره
 * بررسی می‌شدند و در بدترین حالت دوباره ارسال. حالا شمارهٔ محصول جاری،
 * شناسهٔ صف و پرچم from_file فرستاده می‌شوند.
 */
/** v10.103: سقف تلاش ادامه برای هر ردیف صف (مثل «ادامه» در مدیر وظیفه) */
const QUEUE_RESUME_MAX_TRIES = 3;
/** فاصلهٔ حداقل بین تلاش‌های ادامهٔ یک ردیف (ثانیه) */
const QUEUE_RESUME_COOLDOWN  = 90;
/** فاصلهٔ بیکاری صف قبل از تلاش دوباره روی ردیف‌های failed_resume (ثانیه) */
const QUEUE_IDLE_RETRY_AFTER = 300;
/** مهلتِ رزروِ dispatch؛ بعد از آزادشدنِ lock فقط همین request مجاز به شروع است */
const QUEUE_RESUME_HANDOFF_SEC = 120;

/**
 * دفترچهٔ تلاش‌های ادامهٔ هر ردیف صف — کلید: which:queue_id
 * @return array{tries:int, at:int, from:int, status:string}
 */
function queueResumeBook(string $which, string $qid, ?array $patch = null): array {
    $file = __DIR__ . '/queue_resume_book.json';
    $d = json_decode((string)@file_get_contents($file), true);
    $d = is_array($d) ? $d : [];
    $key = $which . ':' . ($qid !== '' ? $qid : '_none');
    $row = is_array($d[$key] ?? null) ? $d[$key] : ['tries' => 0, 'at' => 0, 'from' => 0, 'status' => ''];
    if ($patch !== null) {
        foreach ($patch as $k => $v) $row[$k] = $v;
        $d[$key] = $row;
        /* پاکسازی رکوردهای کهنه (>24h) */
        $now = time();
        foreach ($d as $kk => $vv) {
            if (!is_array($vv)) { unset($d[$kk]); continue; }
            if (($now - (int)($vv['at'] ?? 0)) > 86400) unset($d[$kk]);
        }
        @file_put_contents($file, json_encode($d, JSON_UNESCAPED_UNICODE), LOCK_EX);
    }
    return $row;
}

/** علامت‌زدن ردیف صف به‌عنوان failed بعد از ۳ تلاش ناموفق */
function queueMarkEntryFailed(string $which, string $qid, string $reason = ''): bool {
    if ($qid === '') return false;
    $isBsl = $which === 'bsl';
    $lockFile = __DIR__ . ($isBsl ? '/bsl_backend.lock' : '/woo_backend.lock');
    $lockFp = @fopen($lockFile, 'c');
    if (!$lockFp || !@flock($lockFp, LOCK_EX | LOCK_NB)) {
        if (is_resource($lockFp)) @fclose($lockFp);
        return false;
    }
    $found = false;
    $q = $isBsl
        ? (function_exists('bslReadQueue') ? bslReadQueue() : [])
        : (function_exists('wooReadQueue') ? wooReadQueue() : []);
    if (is_array($q) && !empty($q['entries']) && is_array($q['entries'])) {
        foreach ($q['entries'] as &$e) {
            if (!is_array($e) || (string)($e['id'] ?? '') !== $qid
                || !in_array((string)($e['status'] ?? ''), ['running', 'waiting', 'paused'], true)) continue;
            $e['status'] = 'failed';
            $e['fail_reason'] = $reason !== '' ? $reason : 'پس از ۳ تلاش ادامه، متوقف شد';
            $e['done_at'] = time();
            $e['resume_exhausted'] = 1;
            $found = true;
            break;
        }
        unset($e);
    }
    if ($found) {
        if ($isBsl && function_exists('bslWriteQueue')) bslWriteQueue($q);
        elseif (!$isBsl && function_exists('wooWriteQueue')) wooWriteQueue($q);
        /* پیشرفت را هم ببند تا UI گیر نکند؛ این write زیر همان lock صف است. */
        $pFile = $isBsl ? BSL_PROGRESS_FILE : WOO_PROGRESS_FILE;
        $pg = readProgress($pFile);
        if (is_array($pg) && ((string)($pg['queue_id'] ?? '') === $qid || empty($pg['queue_id']))) {
            $pg['running'] = false;
            $pg['done'] = true;
            $pg['failed_resume'] = true;
            $lg = is_array($pg['recent_log'] ?? null) ? $pg['recent_log'] : [];
            $lg[] = '❌ ' . ($reason !== '' ? $reason : 'پس از ۳ تلاش ادامه متوقف شد');
            $pg['recent_log'] = array_slice($lg, -40);
            $pg['last_progress_ts'] = time();
            writeProgress($pFile, $pg);
        }
    }
    @flock($lockFp, LOCK_UN);
    @fclose($lockFp);
    return $found;
}

/**
 * v10.103: وقتی صف بیکار است، ردیف‌های failed_resume را دوباره تا ۳ بار آزمایش کن.
 * v10.155: انتخاب، تبدیل به waiting و dispatch زیرِ همان flock انجام می‌شود.
 */
function queueIdleRetryFailed(string $which): ?array {
    $isBsl = $which === 'bsl';
    $lockFile = __DIR__ . ($isBsl ? '/bsl_backend.lock' : '/woo_backend.lock');
    $lockFp = @fopen($lockFile, 'c');
    if (!$lockFp || !@flock($lockFp, LOCK_EX | LOCK_NB)) {
        if (is_resource($lockFp)) @fclose($lockFp);
        return null;
    }
    $q = $isBsl
        ? (function_exists('bslReadQueue') ? bslReadQueue() : [])
        : (function_exists('wooReadQueue') ? wooReadQueue() : []);
    $entries = is_array($q['entries'] ?? null) ? $q['entries'] : [];
    /* running و waiting active/pending هستند؛ paused عمداً متوقف است. */
    foreach ($entries as $e) {
        if (is_array($e) && in_array((string)($e['status'] ?? ''), ['running', 'waiting'], true)) {
            @flock($lockFp, LOCK_UN); @fclose($lockFp);
            return null;
        }
    }
    $now = time();
    $picked = null;
    foreach ($entries as $e) {
        if (!is_array($e) || (string)($e['status'] ?? '') !== 'failed') continue;
        if (empty($e['resume_exhausted']) && empty($e['fail_reason'])) continue;
        $fr = (string)($e['fail_reason'] ?? '');
        if (strpos($fr, '۳ تلاش') === false && empty($e['resume_exhausted'])) continue;
        $qid = (string)($e['id'] ?? '');
        if ($qid === '') continue;
        $book = queueResumeBook($which, $qid);
        $lastAt = (int)($book['at'] ?? 0);
        if ($lastAt > 0 && ($now - $lastAt) < QUEUE_IDLE_RETRY_AFTER) continue;
        if ((string)($book['status'] ?? '') === 'exhausted') {
            queueResumeBook($which, $qid, ['tries' => 0, 'status' => 'idle_retry', 'at' => $now]);
        }
        $picked = $e;
        break;
    }
    if ($picked === null) {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
        return null;
    }
    $qid = (string)($picked['id'] ?? '');
    $start = max(0, (int)($picked['current'] ?? 0));
    foreach ($q['entries'] as &$e) {
        if (!is_array($e) || (string)($e['id'] ?? '') !== $qid) continue;
        $e['status'] = 'waiting';
        $e['resume_requested_at'] = $now;
        unset($e['fail_reason'], $e['resume_exhausted'], $e['done_at']);
        break;
    }
    unset($e);
    if ($isBsl && function_exists('bslWriteQueue')) bslWriteQueue($q);
    elseif (!$isBsl && function_exists('wooWriteQueue')) wooWriteQueue($q);
    /* v10.142: stop signal را parent پاک نمی‌کند؛ worker پس از گرفتنِ
       flock واقعی آن را در یک resume صریح مصرف می‌کند. */
    /* اکنون ردیف و مهرِ handoff ذخیره شده‌اند؛ lock را پیش از fire آزاد کن
       تا child بتواند همان lock را بگیرد. مهرِ بالا جلوی dispatch موازی را
       تا رسیدنِ child می‌گیرد. */
    @flock($lockFp, LOCK_UN); @fclose($lockFp);
    $action = $isBsl ? 'bsl_backend' : 'woo_backend';
    $post = ['from_file' => '1', 'start_index' => (string)$start, 'queue_id' => $qid,
             'resume' => '1'];
    $ok = fireAndForget('action=' . $action, 2000, $post);
    $book = queueResumeBook($which, $qid);
    $tries = (int)($book['tries'] ?? 0) + 1;
    queueResumeBook($which, $qid, ['tries' => $tries, 'at' => $now, 'from' => $start, 'status' => $ok ? 'idle_fired' : 'idle_fail']);
    return ['ok' => $ok, 'which' => $which, 'queue_id' => $qid, 'try' => $tries,
            'kind' => 'idle_retry', 'resume_from' => $start];
}

function queueStallRecover(string $which, int $staleAfter = 300, bool $dryRun = false, int $waitMs = 1500, bool $includePaused = false): array {
    $chk = queueStallCheck($which, $staleAfter, $includePaused);
    $chk['which'] = $which;
    if (empty($chk['stalled']) || $dryRun) {
        $chk['resumed'] = false;
        /* v10.103: در بیکاری صف، failedهای قبلی را دوباره تا ۳ بار آزمایش کن */
        if (empty($chk['stalled']) && !$dryRun && function_exists('queueIdleRetryFailed')) {
            $idle = queueIdleRetryFailed($which);
            if (is_array($idle)) {
                $chk['idle_retry'] = $idle;
                $chk['resumed'] = !empty($idle['ok']);
            }
        }
        return $chk;
    }

    $qid   = (string)($chk['queue_id'] ?? '');
    /* flock شاهدِ قوی‌تری از سنِ heartbeat است: یک درخواستِ شبکهٔ طولانی
       ممکن است بیش از staleAfter طول بکشد، اما تا وقتی قفل در دستِ worker
       است، نه آن را بکش و نه worker دوم بساز. */
    if (!empty($chk['lock_held'])) {
        $chk['resumed'] = false;
        $chk['deferred'] = true;
        $chk['reason_defer'] = 'lock_held';
        return $chk;
    }
    /* v10.56 (۷۰): resume_from = چک‌پوینتِ واقعی */
    $start = max(0, (int)($chk['resume_from'] ?? $chk['current'] ?? 0));

    /* v10.103: سقف ۳ تلاش ادامه — مثل دکمهٔ «ادامه» در مدیر وظیفه؛ بعد failed */
    $book = queueResumeBook($which, $qid);
    $tries = (int)($book['tries'] ?? 0);
    $lastAt = (int)($book['at'] ?? 0);
    $now = time();
    /* اگر از آخرین تلاش واقعاً جلو رفته (چک‌پوینت بالاتر) — شمارنده از نو */
    if ((int)($book['from'] ?? 0) > 0 && $start > (int)$book['from'] + 0) {
        $tries = 0;
        queueResumeBook($which, $qid, ['tries' => 0, 'from' => $start, 'status' => 'progressed', 'at' => $now]);
        $book['tries'] = 0;
    }
    /* کول‌داون بین تلاش‌ها */
    if ($lastAt > 0 && ($now - $lastAt) < QUEUE_RESUME_COOLDOWN && $tries > 0
        && (string)($book['status'] ?? '') !== 'exhausted') {
        $chk['resumed'] = false;
        $chk['deferred'] = true;
        $chk['attempt'] = $tries;
        $chk['reason_defer'] = 'cooldown';
        return $chk;
    }
    if ($tries >= QUEUE_RESUME_MAX_TRIES) {
        $reason = 'پس از ' . QUEUE_RESUME_MAX_TRIES . ' تلاش ادامه، متوقف شد (از محصول #' . max(1, $start) . ')';
        queueMarkEntryFailed($which, $qid, $reason);
        queueResumeBook($which, $qid, ['tries' => $tries, 'at' => $now, 'from' => $start, 'status' => 'exhausted']);
        $chk['resumed'] = false;
        $chk['exhausted'] = true;
        $chk['attempt'] = $tries;
        $chk['fail_reason'] = $reason;
        return $chk;
    }

    $resumeFp = null;
    if ($qid !== '') {
        /* paused را فقط زیرِ همان lock واقعی به running تبدیل کن؛ وگرنه یک
           شروعِ همزمان می‌تواند بین probe و fire وضعیت توقف را برگرداند. */
        $resumeLockFile = __DIR__ . ($which === 'bsl' ? '/bsl_backend.lock' : '/woo_backend.lock');
        $resumeFp = @fopen($resumeLockFile, 'c');
        if (!$resumeFp || !@flock($resumeFp, LOCK_EX | LOCK_NB)) {
            if (is_resource($resumeFp)) @fclose($resumeFp);
            $chk['resumed'] = false; $chk['deferred'] = true;
            $chk['reason_defer'] = 'lock_held';
            return $chk;
        }
        $rq = json_decode((string)@file_get_contents($which === 'bsl' ? BSL_QUEUE_FILE : WOO_QUEUE_FILE), true);
        $rq = is_array($rq) ? $rq : ['entries' => []];
        $ridx = -1; $rentry = null;
        foreach (($rq['entries'] ?? []) as $ri => $re) {
            if (is_array($re) && (string)($re['id'] ?? '') === $qid) {
                $ridx = $ri; $rentry = $re; break;
            }
        }
        if ($ridx < 0 || !is_array($rentry)
            || !in_array((string)($rentry['status'] ?? ''), ['paused', 'waiting', 'running'], true)) {
            @flock($resumeFp, LOCK_UN); @fclose($resumeFp); $resumeFp = null;
            $chk['resumed'] = false; $chk['deferred'] = false;
            $chk['reason_defer'] = 'queue_row_changed';
            return $chk;
        }
        /* هر دو worker از اینجا با یک ردیفِ running شروع می‌شوند؛ مخصوصاً
           woo_backend ردیفِ waiting را خودش انتخاب نمی‌کند. */
        $rq['entries'][$ridx]['resume_requested_at'] = time();
        if (in_array((string)($rentry['status'] ?? ''), ['paused', 'waiting'], true)) {
            $rq['entries'][$ridx]['status'] = 'running';
            $rq['entries'][$ridx]['started_at'] = time();
            $rq['entries'][$ridx]['paused_at'] = 0;
        }
        $qFile = $which === 'bsl' ? BSL_QUEUE_FILE : WOO_QUEUE_FILE;
        @file_put_contents($qFile, json_encode($rq, JSON_UNESCAPED_UNICODE), LOCK_EX);
        if ($which !== 'bsl') {
            /* products_file همان row است؛ copy هم پیش از آزادکردنِ reservation
               انجام می‌شود تا woo از فایلِ مقصدِ اشتباه شروع نکند. */
            @copy((string)($rentry['products_file'] ?? ''), WOO_PRODUCTS_FILE);
        }
        /* child باید بتواند همین lock را بگیرد؛ جلوگیری از duplicate با مهرِ
           resume_requested_at و سنِ شروعِ تازه انجام می‌شود، نه با held ماندنِ
           lock هنگام fire (که child را خودش با already-running رد می‌کند). */
        @flock($resumeFp, LOCK_UN); @fclose($resumeFp); $resumeFp = null;
    }

    /* v10.143: stop signal را parent پاک نمی‌کند؛ worker پس از گرفتنِ
       flock واقعی آن را در یک resume صریح مصرف می‌کند. */
    $action = $which === 'bsl' ? 'bsl_backend' : 'woo_backend';
    $post = ['from_file' => '1', 'start_index' => (string)$start, 'resume' => '1'];
    if ($qid !== '') $post['queue_id'] = $qid;

    $chk['resume_from'] = $start;
    $chk['resumed'] = fireAndForget('action=' . $action, $waitMs, $post);
    if (!empty($chk['resumed'])) {
        if (!isset($GLOBALS['_queueResumeFired']) || !is_array($GLOBALS['_queueResumeFired']))
            $GLOBALS['_queueResumeFired'] = [];
        $GLOBALS['_queueResumeFired'][$which] = time();
    }
    $tries++;
    queueResumeBook($which, $qid, [
        'tries' => $tries, 'at' => $now, 'from' => $start,
        'status' => !empty($chk['resumed']) ? 'fired' : 'fire_fail',
    ]);
    $chk['attempt'] = $tries;
    $chk['attempt_max'] = QUEUE_RESUME_MAX_TRIES;
    /* سازگاری با شمارندهٔ قدیمی state */
    try {
        $st = notifLoadState();
        $k  = 'stall_' . $which;
        $st[$k] = ['at' => $now, 'n' => $tries, 'queue_id' => $qid, 'from' => $start];
        notifSaveState($st);
    } catch (Throwable $e) {}
    /* اگر این سومین تلاش بود و fire شکست خورد → همان‌جا failed */
    if ($tries >= QUEUE_RESUME_MAX_TRIES && empty($chk['resumed'])) {
        $reason = 'پس از ' . QUEUE_RESUME_MAX_TRIES . ' تلاش ادامه، متوقف شد';
        queueMarkEntryFailed($which, $qid, $reason);
        queueResumeBook($which, $qid, ['tries' => $tries, 'at' => $now, 'status' => 'exhausted']);
        $chk['exhausted'] = true;
        $chk['fail_reason'] = $reason;
    }
    return $chk;
}

/**
 * v10.59 (۷۳): بازسازیِ خودکارِ صفِ ارسال — از همان تبِ بازِ مرورگر.
 *
 * گزارشِ کاربر: «ارسال‌ها بعد از ارسالِ آخرین محصول فریز می‌مانند و
 * وظیفه را تمام نمی‌کنند؛ همچنان در حالِ فعالیت دیده می‌شوند و گیر
 * می‌کنند، مگر دستی دکمهٔ توقف را بزنیم.»
 *
 * ریشه: وِرکرِ ارسال وقتی توسط هاست کشته می‌شود (همان هاستی که پردژهٔ
 * پس‌زمینه را می‌کُشد — v10.49/10.50/10.58) ردیفِ صف را «running» جا
 * می‌گذارد. تنها راه‌هایِ بازیابی، تیکِ کران (نگهبان + پمپ) و دکمه‌های
 * دستی بودند؛ و روی هاستی که کرانش اصلاً به آدرس نمی‌رسد، هیچ‌کدام
 * اتفاق نمی‌افتاد. دکمهٔ توقف «حل» به نظر می‌رسید فقط چون خودش مستقیم
 * وضعیت را روی «failed» می‌نشانَد.
 *
 * حالا: تبِ ارسال هر ۲ ثانیه poll_bsl/poll_woo را می‌زند — همین پویینگ
 * موتورِ بازیابی می‌شود. اگر صف گیر کرده باشد (ردیفِ در حالِ اجرای
 * بی‌حرکت، یا ردیفِ منتظرِ بی‌پردازنده)، پردازنده با همان چک‌پوینتِ
 * v10.56 از جایی که مانده بود دوباره راه می‌افتد. دو محافظ:
 *   ۱. کول‌داونِ ۱۲۰ ثانیه‌ای — پویینگِ ۲ ثانیه‌ای هرگز در چرخهٔ
 *      تکراریِ راه‌اندازی نیفتد (اگر پردازندهٔ تازه واقعاً زنده باشد،
 *      قفلِ flock هم نگهبان را «شغول» می‌بیند و اصلاً stalled نمی‌شود).
 *   ۲. هر کاری که queueStallCheck/queueStallRecover می‌کنند همان
 *      مکانیزمِ آزموده‌شدهٔ نگهبانِ کران است — منطقِ تازه‌ای اضافه نشده.
 */
function sendAutoRecover(string $which): ?array {
    try {
        $cnA  = loadConnections();
        $stallA = max(120, (int)($cnA['stall_after'] ?? 300));
        $chkA = queueStallCheck($which, $stallA);
        if (empty($chkA['stalled'])) return null;
        $nowA = time();
        $stFileA = __DIR__ . '/send_autorecover_state.json';
        $sdA = json_decode((string)@file_get_contents($stFileA), true);
        $sdA = is_array($sdA) ? $sdA : [];
        if ($nowA - (int)($sdA[$which] ?? 0) < 120) return null;   // کول‌داون
        $resA = queueStallRecover($which, $stallA, false, 2000);
        $sdA[$which] = $nowA;
        @file_put_contents($stFileA, json_encode($sdA, JSON_UNESCAPED_UNICODE), LOCK_EX);
        return $resA;
    } catch (Throwable $eA) {
        return null;   // بازسازی هرگز نباید خودِ پویینگ را خراب کند
    }
}

/* =====================================================================
 *  v10.50 (۶۴): ارسالِ همگام‌سازیِ دستی، کاملاً سرورساید.
 *
 *  کارگرِ دستی پاسخش را از همان ابتدای اجرا فرستاده و در سرور زنده
 *  می‌ماند؛ کاربر آزاد است تبِ مرورگر را ببندد. این تابع تا وقتی که
 *  کارگر زنده است صفِ ارسال را نوبت‌به‌نوبت جلو می‌رساند: در هر نوبت
 *  یک پردازندهٔ ارسال (bsl_backend / woo_backend) به‌صورت درخواستِ
 *  فرزند با مهلتِ طولانی راه می‌اندازد و منتظرش می‌ماند، بعد صف را
 *  دوباره بررسی می‌کند؛ اگر ردیفِ درانتظار مانده باشد نوبتِ بعدی.
 *  چون پیشرفت به‌ازایِ هر محصول چک‌پوینت شده است (v8.22)، اگر خودِ
 *  کارگر وسط راه بمیرد، پمپِ کرانِ v10.49 از همان نقطهٔ قطع‌شده
 *  برمی‌دارد. قفلِ flock جلوی دو پردازندهٔ هم‌زمان را می‌گیرد، پس
 *  شلیکِ تکراری (دکمهٔ ارسال، msKickSend مرورگر) بی‌خطر است.
 * ===================================================================== */
function msLockFresh(string $which): bool {
    $lock = __DIR__ . ($which === 'bsl' ? '/bsl_backend.lock' : '/woo_backend.lock');
    if (!is_file($lock)) return false;
    $fp = @fopen($lock, 'c');
    if (!$fp) return false;
    $held = !@flock($fp, LOCK_EX | LOCK_NB);
    if (!$held) @flock($fp, LOCK_UN);
    @fclose($fp);
    return $held;
}

function msQueuePendingRow(string $which): ?array {
    $q = $which === 'bsl' ? bslReadQueue() : wooReadQueue();
    $entries = is_array($q['entries'] ?? null) ? $q['entries'] : [];
    foreach ($entries as $e) {
        if (is_array($e) && in_array((string)($e['status'] ?? ''), ['waiting', 'running', 'paused'], true)) {
            return $e;
        }
    }
    return null;
}


/**
 * v10.81: صف‌سازی ارسال برای یک پروفایل بعد از استخراج بک‌اند (همگام دستی).
 * منطق خلاصه‌شده از حلقهٔ کران — بدون قفل کران.
 */
function manualSyncEnqueueSends(string $key, array $profile, array $cn, array $exRes): array {
    $out = ['log' => [], 'woo' => false, 'bsl' => false];
    $syncCfg = is_array($profile['syncConfig'] ?? null) ? $profile['syncConfig'] : [];
    $target = (string)($syncCfg['target'] ?? 'woo');
    if (!in_array($target, ['woo', 'bsl', 'both', 'none'], true)) $target = 'woo';
    if ($target === 'none') {
        $out['log'][] = '⏭ مقصد none';
        return $out;
    }
    $now = time();
    /* Build product list from profile disk */
    $products = [];
    foreach ((array)($profile['products'] ?? []) as $entry) {
        if (is_array($entry) && count($entry) === 2 && is_array($entry[1])) {
            $pk = (string)$entry[0];
            $products[$pk] = $entry[1];
            $products[$pk]['key'] = $pk;
        }
    }
    if (!$products) {
        $out['log'][] = '⚠️ محصولی روی دیسک نیست — صف ارسال خالی';
        return $out;
    }
    $out['log'][] = '📦 ' . count($products) . ' محصول برای صف ارسال';

    $wooOn = ($target === 'woo' || $target === 'both') && !empty($syncCfg['wooAddUpdate']);
    $bslOn = ($target === 'bsl' || $target === 'both') && !empty($syncCfg['bslAddUpdate']);
    /* اگر تیک add/update نبود ولی target هست، باز هم صف کن (رفتار force دستی) */
    if (!$wooOn && ($target === 'woo' || $target === 'both')) $wooOn = true;
    if (!$bslOn && ($target === 'bsl' || $target === 'both')) $bslOn = true;

    $bslForceAll = empty($syncCfg['bslOnlyChanged']); /* force full on manual */
    $wooForceAll = empty($syncCfg['wooOnlyChanged']);
    /* manual always prefers sending something */
    $bslOnlyChanged = false;
    $wooOnlyChanged = false;

    /* Serialize products file for queue */
    $qDir = __DIR__;
    $stamp = date('Ymd_His');
    $safeKey = preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $key);

    if ($wooOn && function_exists('wooReadQueue') && function_exists('wooWriteQueue')) {
        try {
            $wooSend = array_values($products);
            $wooQFile = $qDir . '/woo_queue_' . $safeKey . '_' . $stamp . '.json';
            @file_put_contents($wooQFile, json_encode($wooSend, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            $wooQueue = wooReadQueue();
            if (!isset($wooQueue['entries']) || !is_array($wooQueue['entries'])) $wooQueue['entries'] = [];
            /* clear stale for this profile */
            foreach ($wooQueue['entries'] as &$we) {
                if (!is_array($we)) continue;
                if ((string)($we['profile_key'] ?? '') !== $key) continue;
                if (in_array((string)($we['status'] ?? ''), ['waiting', 'running', 'paused'], true)) {
                    $we['status'] = 'failed';
                    $we['error'] = 'جایگزین همگام دستی';
                    $we['done_at'] = $now;
                }
            }
            unset($we);
            $wooQueueId = 'woo_' . $safeKey . '_' . time() . '_' . substr(bin2hex(random_bytes(2)), 0, 4);
            $wooSuffix = (string)($profile['titleSuffix'] ?? '');
            $wooCatId = (int)($syncCfg['wooCategoryId'] ?? 0);
            $wooQueue['entries'][] = [
                'id' => $wooQueueId, 'status' => 'waiting',
                'products_file' => $wooQFile, 'total' => count($wooSend),
                'sent' => 0, 'updated' => 0, 'skipped' => 0, 'failed' => 0, 'current' => 0,
                'started_at' => 0, 'done_at' => 0,
                'profile_key' => $key, 'profile_name' => (string)($profile['name'] ?? $key),
                'only_changed' => $wooOnlyChanged, 'trigger' => 'manual_sync',
                'config' => ['title_suffix' => $wooSuffix, 'category_id' => $wooCatId, 'force_all' => true],
            ];
            wooWriteQueue($wooQueue);
            $out['woo'] = true;
            $out['woo_total'] = count($wooSend);
            $out['log'][] = '🛒 ووکامرس: ' . count($wooSend) . ' در صف';
        } catch (Throwable $e) {
            $out['log'][] = '⚠️ ووکامرس: ' . mb_substr($e->getMessage(), 0, 120);
        }
    }

    if ($bslOn && function_exists('bslReadQueue') && function_exists('bslWriteQueue')) {
        try {
            $bslSend = array_values($products);
            $qFile = $qDir . '/bsl_queue_' . $safeKey . '_' . $stamp . '.json';
            @file_put_contents($qFile, json_encode($bslSend, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            $queue = bslReadQueue();
            if (!isset($queue['entries']) || !is_array($queue['entries'])) $queue['entries'] = [];
            foreach ($queue['entries'] as &$be) {
                if (!is_array($be)) continue;
                if ((string)($be['profile_key'] ?? '') !== $key) continue;
                if (in_array((string)($be['status'] ?? ''), ['waiting', 'running', 'paused'], true)) {
                    $be['status'] = 'failed';
                    $be['error'] = 'جایگزین همگام دستی';
                    $be['done_at'] = $now;
                }
            }
            unset($be);
            $queueId = 'bsl_' . $safeKey . '_' . time() . '_' . substr(bin2hex(random_bytes(2)), 0, 4);
            $catId = (int)($profile['bslCategoryId'] ?? $syncCfg['bslCategoryId'] ?? 0);
            $autoCat = !empty($syncCfg['bslAutoCategory']);
            $titleSuffix = (string)($profile['titleSuffix'] ?? '');
            $delayMs = (int)($cn['basalam']['delay_ms'] ?? 400);
            $retryDelayMs = (int)($cn['basalam']['retry_delay_ms'] ?? 1500);
            $allFallbackCats = is_array($profile['bslFallbackCatIds'] ?? null) ? $profile['bslFallbackCatIds'] : [];
            $queue['entries'][] = [
                'id' => $queueId, 'status' => 'waiting',
                'products_file' => $qFile, 'total' => count($bslSend),
                'sent' => 0, 'updated' => 0, 'skipped' => 0, 'failed' => 0, 'current' => 0,
                'started_at' => 0, 'done_at' => 0, 'paused_at' => 0,
                'only_changed' => false,
                'config' => [
                    'category_id' => $catId, 'auto_category' => $autoCat,
                    'title_suffix' => $titleSuffix, 'delay_ms' => $delayMs,
                    'retry_delay_ms' => $retryDelayMs, 'fallback_cat_ids' => $allFallbackCats,
                    'send_all_shops' => !empty($cn['basalam']['send_all_shops']),
                    'force_all' => true,
                ],
                'profile_key' => $key, 'profile_name' => (string)($profile['name'] ?? $key),
                'trigger' => 'manual_sync', 'auto_sync' => true,
            ];
            bslWriteQueue($queue);
            $out['bsl'] = true;
            $out['bsl_total'] = count($bslSend);
            $out['log'][] = '⭐ باسلام: ' . count($bslSend) . ' در صف';
        } catch (Throwable $e) {
            $out['log'][] = '⚠️ باسلام: ' . mb_substr($e->getMessage(), 0, 120);
        }
    }

    if (!$out['woo'] && !$out['bsl']) {
        $out['log'][] = 'ℹ️ مقصد فعالی برای صف ارسال نبود (target=' . $target . ')';
    }
    return $out;
}

function manualServerSendRun(int $roundMs = 1500000, int $maxRounds = 12): array {
    $out = ['rounds' => 0, 'stopped' => false, 'dests' => []];
    foreach (cronWatchdogQueueOrder() as $dest) {
        $isBsl  = ($dest === 'bsl');
        $pFile  = $isBsl ? BSL_PROGRESS_FILE : WOO_PROGRESS_FILE;
        $action = $isBsl ? 'bsl_backend' : 'woo_backend';
        $label  = $isBsl ? 'باسلام' : 'ووکامرس';
        $lastSig = '';
        $stuck = 0;
        for ($round = 1; $round <= $maxRounds; $round++) {
            if (manualSyncStopped()) { $out['stopped'] = true; break; }
            $row = msQueuePendingRow($dest);
            if ($row === null) break;                    // صف این مقصد خالی شد
            $pg = readProgress($pFile);
            manualSyncProgress(['phase' => 'ارسال ' . $label, 'current' => 3,
                'summary' => ((int)($row['current'] ?? 0)) . '/' . ((int)($row['total'] ?? 0)) . ' در صفِ ' . $label],
                '📤 ارسال سرورساید: ' . $label . ' — ردیف ' . (string)($row['id'] ?? '') . ' (' . (int)($row['current'] ?? 0) . '/' . (int)($row['total'] ?? 0) . ')');
            /* اگر پردازندهٔ زنده دیگری (دکمهٔ ارسال / msKickSend) قفل را
               در دست دارد، چند لحظه منتظر بمانیم تا او ادامه بدهد — این
               نوبت «گیر» شمرده نمی‌شود. */
            for ($w = 0; $w < 6 && msLockFresh($dest); $w++) sleep(5);
            if (msLockFresh($dest)) continue;
            $sig = (string)($row['id'] ?? '') . ':' . (int)($row['current'] ?? 0)
                 . ':' . (int)($pg['current'] ?? 0) . ':' . (int)($pg['sent'] ?? 0)
                 . ':' . (int)($pg['updated'] ?? 0) . ':' . (int)($pg['skipped'] ?? 0);
            msAlive('ارسال ' . $label . ' — ' . (int)($row['current'] ?? 0) . '/' . (int)($row['total'] ?? 0));   /* v10.61 (۷۵) */
            $fired = fireAndForget('action=' . $action, $roundMs, ['from_file' => '1']);
            $out['rounds']++;
            if (!$fired || $sig === $lastSig) { $stuck++; } else { $stuck = 0; }
            if ($sig !== '') $lastSig = $sig;
            if ($stuck >= 2) {
                manualSyncProgress(['phase' => 'ارسال ' . $label, 'current' => 3],
                    '⚠ پیشرفتِ ارسال دیده نشد — ادامه با پمپِ کران');
                break;
            }
        }
        $rowAfter = msQueuePendingRow($dest);
        $out['dests'][$dest] = $rowAfter === null ? 'done'
            : ('pending:' . (int)($rowAfter['total'] ?? 0) . ':' . (int)($rowAfter['current'] ?? 0));
        if (!empty($out['stopped'])) break;
    }
    return $out;
}

/* =====================================================================
 *  v8.34: بازنشستگی خودکار محصولاتی که از مبدأ رفته‌اند
 *
 *  وقتی محصولی در سایت مبدأ ناموجود یا حذف می‌شود، تا امروز فقط گزارش
 *  می‌شد و روی ووکامرس/باسلام دست‌نخورده می‌ماند. حالا می‌توان خودکار
 *  آن را از دسترس خارج کرد.
 *
 *  پیش‌فرض عمداً «پیش‌نویس/غیرفعال» است نه حذف، چون برگشت‌پذیر است و
 *  نظرات و تاریخچهٔ محصول از بین نمی‌رود.
 *
 *  ⚠️ محافظ ایمنی: اگر سایت مبدأ یک بار خراب شود و چیزی برنگرداند،
 *  همهٔ محصولات «حذف‌شده» به نظر می‌رسند. برای همین اگر نسبت حذف‌ها از
 *  یک آستانه بگذرد، هیچ کاری انجام نمی‌شود و فقط هشدار می‌رود.
 * ===================================================================== */

/** حالت‌های مجاز بازنشستگی */
function retireModes(): array {
    return ['off' => 'کاری نکن', 'draft' => 'پیش‌نویس/غیرفعال', 'outofstock' => 'ناموجود کن', 'delete' => 'حذف کامل'];
}

/**
 * تصمیم می‌گیرد که آیا بازنشستگی مجاز است یا محافظ باید جلویش را بگیرد.
 * $removed تعداد رفته‌ها، $total کل محصولات دیده‌شده در این اجرا.
 */
function retireGuard(int $removed, int $total, array $cfg): array {
    $maxPct   = (float)($cfg['retire_max_pct'] ?? 30);   // درصد
    $maxCount = (int)($cfg['retire_max_count'] ?? 50);   // سقف مطلق
    if ($removed <= 0) return ['allow' => false, 'reason' => 'موردی برای بازنشستگی نیست'];
    // اگر استخراج تقریباً هیچ محصولی نداده، یعنی مبدأ خراب بوده — دست نزن
    if ($total <= 0) return ['allow' => false, 'blocked' => true,
        'reason' => 'استخراج هیچ محصولی برنگرداند — احتمال خرابی سایت مبدأ'];
    $pct = $total > 0 ? ($removed / max(1, $total + $removed)) * 100 : 100;
    if ($pct > $maxPct) return ['allow' => false, 'blocked' => true, 'pct' => round($pct, 1),
        'reason' => 'نسبت حذف‌ها (' . round($pct, 1) . '٪) از آستانهٔ ' . $maxPct . '٪ بیشتر است'];
    if ($removed > $maxCount) return ['allow' => false, 'blocked' => true, 'pct' => round($pct, 1),
        'reason' => 'تعداد حذف‌ها (' . $removed . ') از سقف ' . $maxCount . ' بیشتر است'];
    return ['allow' => true, 'pct' => round($pct, 1)];
}

/** یک محصول ووکامرس را با عنوان پیدا می‌کند */
/* =====================================================================
 *  v8.62: ویرایش مستقیم محصولات روی مقصد (ووکامرس و باسلام)
 *
 *  ⚠️ نکتهٔ مهم دربارهٔ «حذف» در باسلام:
 *  در OpenAPI رسمی باسلام هیچ متد DELETE برای محصول وجود ندارد؛ فقط
 *  PATCH /v1/products/{id} و PATCH /v1/vendors/{vid}/products/batch-updates.
 *  یعنی حذف همیشگی ذاتاً در API نیست. کاری که واقعاً می‌شود کرد، عوض
 *  کردن وضعیت است:
 *      2976 فعال · 3790 غیرفعال · 4184 بایگانی
 *  «بایگانی» نزدیک‌ترین چیز به حذف است و محصول را از غرفه برمی‌دارد.
 *  فراخوانی‌های DELETE قبلی روی اندپوینتی می‌رفتند که وجود ندارد و
 *  فقط ۴۰۴ می‌گرفتند — یعنی حذف باسلام هیچ‌وقت کار نمی‌کرده است.
 * ===================================================================== */

/** وضعیت‌های محصول باسلام */
function bslStatusMap(): array {
    return [2976 => 'فعال', 3567 => 'تأیید نشده', 3568 => 'در انتظار',
            3790 => 'غیرفعال', 4184 => 'بایگانی'];
}

/**
 * یک محصول باسلام را ویرایش می‌کند.
 * $fields می‌تواند شامل primary_price، stock، status، name، description،
 * brief، preparation_days، weight و ... باشد.
 */
function bslEditProduct(string $tk, int $vid, int $pid, array $fields): array {
    if ($pid <= 0 || empty($fields)) return ['ok' => false, 'code' => 0, 'error' => 'ورودی ناقص'];
    $r = bslReq($tk, 'PATCH', 'products/' . $pid, $fields);
    /* بعضی نصب‌ها فقط مسیر زیر غرفه را قبول می‌کنند.
       v10.42 (۵۶): تا اینجا فالبک *فقط* روی ۴۰۴ بود. ولی وقتی توکن مالِ
       غرفهٔ دیگری باشد، باسلام روی مسیرِ سراسریِ products/{id} پاسخِ ۴۰۳
       (و گاهی ۴۰۱) می‌دهد، نه ۴۰۴ — یعنی دقیقاً همان حالتی که مسیرِ
       زیرِ غرفه می‌توانست نجاتش بدهد، فالبک نمی‌خورد و عملیات بی‌صدا
       شکست می‌خورد. حالا هر سه کدِ «دسترسی/نبودن» فالبک می‌گیرند. */
    /* v10.49 (۶۳): ۲۲ هم فالبک می‌گیرد — گاهی مسیرِ سراسریِ products/{id}
       پارامتر را می‌پرسد ولی مسیرِ زیرِ غرفه قبولش می‌کند (و برعکس). */
    if (in_array((int)($r['code'] ?? 0), [401, 403, 404, 422], true) && $vid > 0) {
        $r2 = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $pid, $fields);
        /* فقط وقتی جایگزین می‌شود که واقعاً بهتر باشد؛ وگرنه خطای اولیه
           گویاتر است و نباید با یک ۴۰۴ِ مسیرِ دوم پوشانده شود. */
        if (!empty($r2['ok']) || (int)($r2['code'] ?? 0) !== 404) $r = $r2;
    }
    return $r;
}

/* =====================================================================
 *  v10.51 (۶۵): تغییرِ وضعیتِ محصول (و بایگانی) با روشِ چندگانه.
 *
 *  گزارشِ کاربر: بایگانیِ دستی و حذفِ تکراری‌ها با وجودِ فالبکِ مسیرِ
 *  غرفه (v10.49) باز هم ۴۲۲ می‌داد — یعنی خودِ باسلام PATCHِ «فقط
 *  وضعیت» را در این نصب رد می‌کند (۴۲۲ لاراول = اعتبارسنجیِ فرم).
 *  چون آپدیتِ همگام‌سازیِ همین برنامه با «پیلودِ کامل» (قیمت، موجودی،
 *  عکس...) موفق است، اینجا اول محصول را می‌خوانیم، وضعیتِ جدید را در
 *  پیلودِ کامل می‌گذاریم و می‌فرستیم؛ اگر باز نشد، نسخه‌هایی از API
 *  اندپوینتِ اختصاصیِ «بایگانی» دارند — آن را هم می‌آزماییم. فهرستِ
 *  تلاش‌ها در پیامِ خطای نهایی هم می‌آید تا علت دقیق معلوم شود.
 * ===================================================================== */

/** یک محصول را می‌خواند — ردیفِ کامل، وگرنه null */
function bslGetProductRow(string $tk, int $vid, int $pid, int $maxAttempts = 3): ?array {
    $r = bslReq($tk, 'GET', 'products/' . $pid, null, false, null, false, $maxAttempts);
    $row = $r['body']['data'] ?? ($r['body'] ?? null);
    if (!empty($r['ok']) && is_array($row) && (int)($row['id'] ?? 0) > 0) return $row;
    if ($vid > 0) {
        $r2 = bslReq($tk, 'GET', 'vendors/' . $vid . '/products/' . $pid, null, false, null, false, $maxAttempts);
        $row2 = $r2['body']['data'] ?? ($r2['body'] ?? null);
        if (!empty($r2['ok']) && is_array($row2) && (int)($row2['id'] ?? 0) > 0) return $row2;
    }
    return null;
}

/** پیلودِ «کاملِ» آپدیت از روی ردیفِ جاریِ محصول — با وضعیتِ جدید */
function bslProductFullPatch(array $row, int $newStatus): ?array {
    $name = trim((string)($row['title'] ?? $row['name'] ?? ''));
    $bu = ['status' => $newStatus];
    if ($name !== '') $bu['name'] = mb_substr($name, 0, 120);
    if (isset($row['brief']))            $bu['brief'] = (string)$row['brief'];
    if (isset($row['description']))      $bu['description'] = (string)$row['description'];
    if (isset($row['primary_price']))    $bu['primary_price'] = (int)$row['primary_price'];
    if (isset($row['inventory']))        $bu['stock'] = (int)$row['inventory'];
    elseif (isset($row['stock']))        $bu['stock'] = (int)$row['stock'];
    if (isset($row['preparation_days'])) $bu['preparation_days'] = (int)$row['preparation_days'];
    if (isset($row['weight']))           $bu['weight'] = (int)$row['weight'];
    if (isset($row['category_id']))      $bu['category_id'] = (int)$row['category_id'];
    if (isset($row['sku']))              $bu['sku'] = (string)$row['sku'];
    $photos = [];
    if (isset($row['photos']) && is_array($row['photos'])) {
        foreach ($row['photos'] as $ph) {
            $id = is_array($ph) ? (int)($ph['id'] ?? 0) : (int)$ph;
            if ($id > 0) $photos[] = $id;
        }
    }
    $photo = 0;
    if (isset($row['photo'])) {
        $photo = is_array($row['photo']) ? (int)($row['photo']['id'] ?? 0) : (int)$row['photo'];
    }
    if ($photo > 0 && !in_array($photo, $photos, true)) array_unshift($photos, $photo);
    if ($photos) { $bu['photos'] = $photos; $bu['photo'] = $photos[0]; }
    if (count($bu) <= 1) return null;   // دادهٔ کافی برای پیلودِ کامل نداریم
    return $bu;
}

/**
 * v10.52 (۶۶): هر «گام»ِ تغییرِ وضعیت، به‌تنهایی کفایتِ یک درخواستِ
 * HTTPِ کوتاه:
 *  'simple'  → PATCH فقط-وضعیت (زیرِ غرفه، بعد سراسری)       ≤ ۲ درخواست
 *  'full'    → خواندنِ محصول + PATCH پیلودِ کامل            ≤ ۴ درخواست
 *  'archive' → POST اندپوینتِ اختصاصیِ بایگانی               ≤ ۲ درخواست
 *  'disable' → v10.53: PATCH فقط-وضعیت روی ۳۷ (غیرفعال)      ≤ ۲ درخواست
 *  'hide'    → v10.53: پیلودِ کامل با موجودی=۰ و قیمت=۰      ≤ ۴ درخواست
 *  v10.53 (۶۷): اگر بایگانی ممکن نبود، پلکان ادامه دارد:
 *  اول «غیرفعال» (۳۷) و در بدترین حالت «ناموجود» (صفرکردنِ
 *  موجودی و قیمت) تا محصول اصلاً پیدا نشود.
 * مسیرِ قدیمیِ v10.51 این سه گام را در یک درخواست تا ۸ بار پشتِ سرِ هم
 * می‌زد؛ روی هاست‌هایی که پنجرهٔ HTTP کوتاه دارند (تایم‌اوتِ LiteSpeed
 * یا فایروال) کلِ زنجیره از پنجره بیرون می‌خورد و ۵۰۲ می‌گرفت. حالا
 * مسیرِ تعاملی (بایگانیِ دستی/تغییرِ وضعیت) هر گام را در یک درخواستِ
 * جدا می‌زند و کلاینت (JS) خودکار به گامِ بعد می‌رود؛ در صورتِ شکستِ
 * گام، کلیدِ 'next' گامِ بعدی را می‌گوید.
 */
function bslStatusStep(string $tk, int $vid, int $pid, int $newStatus, string $step, int $maxAttempts = 1): array {
    $order = ($newStatus === 4184) ? ['simple', 'full', 'archive', 'disable', 'hide'] : ['simple', 'full']; /* v10.53 (۶۷): پلکانِ کامل فقط برای بایگانی (۴۱۸۴)؛ تغییرِ وضعیتِ دیگر فقط simple/full */
    $si = array_search($step, $order, true);
    $next = ($si === false || $si + 1 >= count($order)) ? null : $order[$si + 1];
    $r = null;
    if ($step === 'simple') {
        $eps = [];
        if ($vid > 0) $eps[] = 'vendors/' . $vid . '/products/' . $pid;
        $eps[] = 'products/' . $pid;
        foreach ($eps as $ep) {
            $r = bslReq($tk, 'PATCH', $ep, ['status' => $newStatus], false, null, false, $maxAttempts);
            if (!empty($r['ok'])) { $r['status_strategy'] = 'simple'; return $r; }
            if ((int)($r['code'] ?? 0) !== 404) break;   // ۴۰۴ = مسیر نیست؛ خطای دیگر = پایانِ گام
        }
    } elseif ($step === 'full') {
        $row = bslGetProductRow($tk, $vid, $pid, $maxAttempts);
        $full = is_array($row) ? bslProductFullPatch($row, $newStatus) : null;
        if ($full !== null) {
            $eps = [];
            if ($vid > 0) $eps[] = 'vendors/' . $vid . '/products/' . $pid;
            $eps[] = 'products/' . $pid;
            foreach ($eps as $ep) {
                $r = bslReq($tk, 'PATCH', $ep, $full, false, null, false, $maxAttempts);
                if (!empty($r['ok'])) { $r['status_strategy'] = 'full'; return $r; }
                if ((int)($r['code'] ?? 0) !== 404) break;
            }
        }
    } elseif ($step === 'archive') {
        $eps = [];
        if ($vid > 0) $eps[] = 'vendors/' . $vid . '/products/' . $pid . '/archive';
        $eps[] = 'products/' . $pid . '/archive';
        foreach ($eps as $ep) {
            $r = bslReq($tk, 'POST', $ep, [], false, null, false, $maxAttempts);
            if (!empty($r['ok'])) { $r['status_strategy'] = 'archive'; $r['archived'] = true; return $r; }
            if ((int)($r['code'] ?? 0) !== 404) break;
        }
    } elseif ($step === 'disable') {
        /* v10.53 (۶۷): بایگانی ممکن نبود → حداقل محصول غیرفعال (۳۷)
           شود تا در ویترین دیده نشود. */
        $eps = [];
        if ($vid > 0) $eps[] = 'vendors/' . $vid . '/products/' . $pid;
        $eps[] = 'products/' . $pid;
        foreach ($eps as $ep) {
            $r = bslReq($tk, 'PATCH', $ep, ['status' => 3790], false, null, false, $maxAttempts);
            if (!empty($r['ok'])) { $r['status_strategy'] = 'disable'; return $r; }
            if ((int)($r['code'] ?? 0) !== 404) break;
        }
    } else { // 'hide'
        /* v10.53 (۶۷): آخرین راه — موجودی و قیمت را صفر کن تا محصول
           نه دیده شود نه قابلِ خرید باشد. وضعیتِ فعلی دست‌نخورده می‌ماند
           (پیلودِ کامل همان وضعیتِ موجود را نگه می‌دارد). */
        $row = bslGetProductRow($tk, $vid, $pid, $maxAttempts);
        if (is_array($row)) {
            $curStatus = (int)($row['status'] ?? 0);
            $full = bslProductFullPatch($row, $curStatus > 0 ? $curStatus : $newStatus);
            if ($full !== null) {
                $full['stock'] = 0;
                $full['primary_price'] = 0;
                $eps = [];
                if ($vid > 0) $eps[] = 'vendors/' . $vid . '/products/' . $pid;
                $eps[] = 'products/' . $pid;
                foreach ($eps as $ep) {
                    $r = bslReq($tk, 'PATCH', $ep, $full, false, null, false, $maxAttempts);
                    if (!empty($r['ok'])) { $r['status_strategy'] = 'hide'; return $r; }
                    if ((int)($r['code'] ?? 0) !== 404) break;
                }
            }
        }
    }
    if ($r === null) $r = ['ok' => false, 'code' => 0, 'body' => null];
    $r['next'] = $next;
    return $r;
}

/**
 * وضعیتِ محصول را با چند روشِ به‌ترتیب عوض می‌کند:
 * v10.51 (۶۵): سه روش — فقط-وضعیت / پیلودِ کامل / اندپوینتِ archive.
 * v10.52 (۶۶): $step='auto' (کارگرِ سرورساید مثلِ حذفِ تکراری) هر سه
 * گام را پشتِ‌سرِ هم می‌زند؛ گامِ مشخص فقط همان گام (برای درخواست‌های
 * تعاملی که پنجرهٔ HTTPِ کوتاه دارند).
 * v10.53 (۶۷): پلکان ۵ گامه شد (+غیرفعال +ناموجود)؛ 'auto' همهٔ ۵ گام را
 * پشتِ‌سرِ هم می‌زند.
 */
function bslSetProductStatus(string $tk, int $vid, int $pid, int $newStatus, string $step = 'auto'): array {
    if ($step !== 'auto') return bslStatusStep($tk, $vid, $pid, $newStatus, $step);
    $attempts = [];
    $last = null;
    foreach ((int)$newStatus === 4184 ? ['simple', 'full', 'archive', 'disable', 'hide'] : ['simple', 'full'] as $st) { /* v10.53 (۶۷) */
        $r = bslStatusStep($tk, $vid, $pid, $newStatus, $st, 3);
        $last = $r;
        if (!empty($r['ok'])) return $r;
        $attempts[] = $st . '=' . (int)($r['code'] ?? 0);
        if (empty($r['next'])) break;
    }
    if ($last === null) $last = ['ok' => false, 'code' => 0, 'body' => null];
    $last['attempts'] = $attempts;
    return $last;
}


/**
 * «حذف» محصول باسلام = بایگانی کردن (4184).
 * چون API حذف واقعی ندارد، این تنها راه برداشتن محصول از غرفه است.
 * v10.51 (۶۵): از مسیرِ چندروشهِ bslSetProductStatus می‌رود — قبلاً
 * فقط PATCHِ فقط-وضعیت بود که در بعضی نصب‌ها ۴۲۲ می‌گرفت.
 */
function bslArchiveProduct(string $tk, int $vid, int $pid): array {
    $r = bslSetProductStatus($tk, $vid, $pid, 4184);
    if (!empty($r['ok']) || !empty($r['archived'])) $r['archived'] = true;
    return $r;
}

/* =====================================================================
 *  v10.42 (۵۶): انتخابِ توکنِ درستِ هر غرفه — و بایگانیِ «چندغرفه‌آگاه»
 *
 *  گزارشِ کاربر: اسکنِ حذفِ تکراری X موردِ تکراری را پیدا می‌کرد، ولی
 *  زدنِ دکمهٔ حذف حتی یک محصول را هم بایگانی نمی‌کرد.
 *
 *  ریشه: از v10.39 اسکن چندغرفه‌ای شد (همهٔ غرفه‌های $b['vendors'] خوانده
 *  می‌شوند) ولی مسیرِ بایگانی همان تک‌غرفه‌ایِ قدیمی ماند و همیشه با
 *  توکن/شناسهٔ *غرفهٔ پیش‌فرض* PATCH می‌زد. محصولی که مالِ غرفهٔ دوم بود
 *  با توکنِ غرفهٔ اول ⇒ ۴۰۳ ⇒ «ناموفق». چون شمارشِ ناموفق‌ها هم به چشمِ
 *  کاربر نمی‌آمد، نتیجه «هیچ اتفاقی نمی‌افتد» دیده می‌شد.
 *
 *  bslArchiveSmart همین را می‌بندد: اگر شناسهٔ غرفه معلوم باشد مستقیم با
 *  توکنِ خودش می‌رود؛ اگر معلوم نباشد (مثلاً گزارشِ ذخیره‌شدهٔ نسخه‌های
 *  قبل که vendor_id نداشت) همهٔ غرفه‌ها را به ترتیب امتحان می‌کند تا
 *  یکی بگیرد. خروجی همیشه می‌گوید کدام غرفه جواب داد.
 * ===================================================================== */

/** توکنِ غرفه‌ای با این vendor_id — رشتهٔ خالی یعنی چنین غرفه‌ای نداریم */
function bslShopTokenFor(array $cn, int $vid): string {
    if ($vid <= 0) return '';
    foreach (bslAllShops($cn) as $sh) {
        if ((int)($sh['vendor_id'] ?? 0) === $vid) return (string)($sh['token'] ?? '');
    }
    return '';
}

/** نامِ خواناى غرفه برای پیام‌های خطا */
function bslShopNameFor(array $cn, int $vid): string {
    foreach (bslAllShops($cn) as $sh) {
        if ((int)($sh['vendor_id'] ?? 0) === $vid) return (string)($sh['shop_name'] ?? ('غرفهٔ ' . $vid));
    }
    return $vid > 0 ? ('غرفهٔ ' . $vid) : 'غرفهٔ نامعلوم';
}

/**
 * بایگانیِ یک محصول با توکنِ غرفهٔ خودش.
 * $vid=0 یعنی «نمی‌دانم مالِ کدام غرفه است» ⇒ همه را امتحان کن.
 * خروجی: ['ok','code','msg','vendor_id','vendor_name','tried']
 */
function bslArchiveSmart(array $cn, int $pid, int $vid = 0): array {
    $shops = bslAllShops($cn);
    if (!$shops) return ['ok' => false, 'code' => 0, 'msg' => 'هیچ غرفهٔ باسلامی تنظیم نشده است',
                         'vendor_id' => 0, 'vendor_name' => '', 'tried' => 0];
    /* غرفهٔ خودِ محصول اول امتحان می‌شود؛ بقیه فقط وقتی که آن نگرفت. */
    $order = [];
    if ($vid > 0) foreach ($shops as $sh) if ((int)$sh['vendor_id'] === $vid) $order[] = $sh;
    foreach ($shops as $sh) if ($vid <= 0 || (int)$sh['vendor_id'] !== $vid) $order[] = $sh;

    $lastCode = 0; $lastMsg = ''; $tried = 0;
    foreach ($order as $sh) {
        $tk = (string)($sh['token'] ?? '');
        $sv = (int)($sh['vendor_id'] ?? 0);
        if ($tk === '' || $sv <= 0) continue;
        $tried++;
        $r  = bslArchiveProduct($tk, $sv, $pid);
        $ok = !empty($r['ok']) || in_array((int)($r['code'] ?? 0), [200, 204], true);
        if ($ok) {
            return ['ok' => true, 'code' => (int)($r['code'] ?? 200), 'msg' => '',
                    'vendor_id' => $sv, 'vendor_name' => (string)($sh['shop_name'] ?? ''), 'tried' => $tried];
        }
        $lastCode = (int)($r['code'] ?? 0);
        $lastMsg  = bslErrText($r);
        /* ۴۰۳/۴۰۴ = «مالِ این غرفه نیست» ⇒ سراغِ غرفهٔ بعدی معنا دارد.
           هر چیزِ دیگر (۰ شبکه، ۴۲۹، ۵xx) مشکلِ خودِ درخواست است و
           تکرارش روی غرفه‌های دیگر فقط وقت تلف می‌کند. */
        if (!in_array($lastCode, [401, 403, 404], true)) break;
        /* وقتی شناسهٔ غرفه معلوم بوده و خودش رد کرده، گشتنِ کورکورانه در
           بقیهٔ غرفه‌ها بی‌معناست — محصول مالِ همان غرفه است. */
        if ($vid > 0) break;
    }
    return ['ok' => false, 'code' => $lastCode,
            'msg' => $lastMsg !== '' ? $lastMsg : ('HTTP ' . ($lastCode ?: '?')),
            'vendor_id' => $vid, 'vendor_name' => bslShopNameFor($cn, $vid), 'tried' => $tried];
}

/**
 * v10.42 (۵۶): متنِ خطای باسلام را از هر شکلی که آمده بیرون می‌کشد.
 * باسلام گاهی message، گاهی error_description و گاهی آرایهٔ errors می‌دهد؛
 * تا اینجا فقط message خوانده می‌شد و بقیه به «HTTP ?» تنزل می‌کرد.
 */
function bslErrText(array $r): string {
    $b = $r['body'] ?? null;
    if (is_array($b)) {
        foreach (['message', 'error_description', 'error', 'detail', 'title'] as $k) {
            $v = $b[$k] ?? null;
            if (is_string($v) && trim($v) !== '') return trim($v);
        }
        if (is_array($b['errors'] ?? null)) {
            $parts = [];
            foreach ($b['errors'] as $k => $v) {
                if (is_array($v)) $v = implode('، ', array_map('strval', $v));
                $parts[] = (is_string($k) ? ($k . ': ') : '') . (string)$v;
            }
            if ($parts) return mb_substr(implode(' | ', $parts), 0, 160, 'UTF-8');
        }
    }
    $code = (int)($r['code'] ?? 0);
    $net  = trim((string)($r['error'] ?? ''));
    if ($code === 0) {
        if ($net === 'stopped') return 'سیگنالِ «توقفِ ارسال» فعال است — درخواست اصلاً به باسلام نرفت';
        return $net !== '' ? ('خطای شبکه: ' . $net) : 'پاسخی از باسلام نیامد';
    }
    $known = [401 => 'توکن نامعتبر یا منقضی', 403 => 'این توکن به این محصول دسترسی ندارد (غرفهٔ اشتباه؟)',
              404 => 'محصول پیدا نشد', 422 => 'داده‌های ارسالی را باسلام نپذیرفت',
              429 => 'محدودیتِ نرخِ باسلام'];
    return 'HTTP ' . $code . (isset($known[$code]) ? (' — ' . $known[$code]) : '');
}

/**
 * ویرایش گروهی باسلام با اندپوینت رسمی batch-updates.
 * هر آیتم باید id داشته باشد؛ بقیهٔ فیلدها اختیاری‌اند.
 * در دسته‌های ۵۰تایی فرستاده می‌شود تا درخواست خیلی بزرگ نشود.
 */
function bslBatchUpdate(string $tk, int $vid, array $items): array {
    $items = array_values(array_filter($items, fn($i) => (int)($i['id'] ?? 0) > 0));
    if (empty($items) || $vid <= 0) return ['ok' => false, 'done' => 0, 'error' => 'ورودی خالی'];
    $done = 0; $failed = 0; $errors = [];
    foreach (array_chunk($items, 50) as $chunk) {
        $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/batch-updates', ['data' => $chunk]);
        if (!empty($r['ok'])) { $done += count($chunk); }
        else {
            // اگر گروهی نشد، تک‌تک امتحان کن تا یک محصول خراب کل دسته را نبرد
            foreach ($chunk as $one) {
                $id = (int)$one['id']; unset($one['id']);
                $r2 = bslEditProduct($tk, $vid, $id, $one);
                if (!empty($r2['ok'])) $done++;
                else { $failed++; if (count($errors) < 10) $errors[] = '#' . $id . ' → ' . (int)($r2['code'] ?? 0); }
            }
        }
        usleep(200000);
    }
    return ['ok' => $failed === 0, 'done' => $done, 'failed' => $failed, 'errors' => $errors];
}

/** یک محصول ووکامرس را ویرایش می‌کند */
function wooEditProduct(array $w, int $pid, array $fields): array {
    if ($pid <= 0 || empty($fields)) return ['ok' => false, 'code' => 0, 'error' => 'ورودی ناقص'];
    return wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                  'PUT', 'products/' . $pid, $fields);
}

/**
 * حذف محصول ووکامرس.
 * $force=false یعنی به زباله‌دان (برگشت‌پذیر)، true یعنی نابودی همیشگی.
 * برخلاف باسلام، ووکامرس واقعاً حذف دائمی دارد.
 */
function wooDeleteProduct(array $w, int $pid, bool $force = false): array {
    if ($pid <= 0) return ['ok' => false, 'code' => 0, 'error' => 'شناسه نامعتبر'];
    return wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                  'DELETE', 'products/' . $pid . '?force=' . ($force ? 'true' : 'false'));
}

/**
 * قیمت تازه را از روی دستور کاربر می‌سازد.
 *   set:12000   → همین عدد
 *   inc:10%     → ۱۰٪ گران‌تر     ·  dec:10%  → ۱۰٪ ارزان‌تر
 *   inc:5000    → ۵۰۰۰ اضافه      ·  dec:5000 → ۵۰۰۰ کم
 * خروجی null یعنی دستور نامفهوم بود و نباید چیزی نوشته شود.
 */
function editApplyPrice(string $op, string $val, int $current): ?int {
    $val = trim(persianToEnglish($val));
    $isPct = substr($val, -1) === '%';
    $num = (float)preg_replace('~[^0-9.\-]~', '', $val);
    if ($op === 'set') return $num > 0 ? (int)round($num) : null;
    if ($current <= 0) return null;
    $delta = $isPct ? ($current * $num / 100) : $num;
    if ($op === 'inc') return max(0, (int)round($current + $delta));
    if ($op === 'dec') return max(0, (int)round($current - $delta));
    return null;
}

function wooFindByTitle(array $w, string $title): ?array {
    if ($title === '') return null;
    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
        'products?search=' . urlencode($title) . '&status=any&per_page=10');
    if (empty($r['ok']) || !is_array($r['body'] ?? null)) return null;
    foreach ($r['body'] as $ep) {
        if (trim((string)($ep['name'] ?? '')) === $title) return $ep;
    }
    return null;
}

/** یک محصول باسلام را با عنوان پیدا می‌کند */
function bslFindByTitle(string $tk, int $vid, string $title): ?array {
    if ($title === '' || $vid <= 0) return null;
    $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?per_page=20&title=' . rawurlencode($title));
    if (empty($r['ok'])) return null;
    foreach (($r['body']['data'] ?? []) as $p) {
        if (!is_array($p)) continue;
        if (trim((string)($p['title'] ?? ($p['name'] ?? ''))) === $title) return $p;
    }
    return null;
}

/* =====================================================================
 *  v10.32 (۴۵د/۴۵ه): لاگِ ماندگارِ بایگانی
 *
 *  تا اینجا نتیجهٔ retireRemoved فقط برگردانده و به اعلان داده می‌شد.
 *  هیچ‌جا نمی‌ماند، پس این سؤالِ کاملاً بجای کاربر بی‌جواب بود: «کدام
 *  محصول‌ها بایگانی شده‌اند؟» حالا هر موردِ واقعاً اعمال‌شده یک ردیف
 *  می‌گیرد و از اندپوینتِ ?retire_log خوانده می‌شود.
 * ===================================================================== */

/** لاگ را می‌خواند: ['items'=>[...], 'updated'=>int] */
function retireLogRead(): array {
    if (!file_exists(RETIRE_LOG_FILE)) return ['items' => [], 'updated' => 0];
    $d = @json_decode((string)@file_get_contents(RETIRE_LOG_FILE), true);
    if (!is_array($d)) return ['items' => [], 'updated' => 0];
    if (!isset($d['items']) || !is_array($d['items'])) $d['items'] = [];
    return $d;
}

/** ردیف‌های تازه را جلوی لاگ می‌گذارد (تازه‌ترین اول) و هرس می‌کند. */
function retireLogAdd(array $rows): int {
    if (!$rows) return 0;
    $log = retireLogRead();
    /* تازه‌ترین بالا. کلیدِ یکتا نداریم چون یک محصول ممکن است در دو نوبت
       بایگانی شود (مثلاً برگشته و دوباره رفته) و هر دو باید دیده شوند. */
    $log['items'] = array_merge($rows, $log['items']);
    if (count($log['items']) > (int)RETIRE_LOG_KEEP)
        $log['items'] = array_slice($log['items'], 0, (int)RETIRE_LOG_KEEP);
    $log['updated'] = time();
    @file_put_contents(RETIRE_LOG_FILE, json_encode($log, JSON_UNESCAPED_UNICODE), LOCK_EX);
    return count($rows);
}

/* =====================================================================
 *  v10.35 (۴۷ج): بایگانیِ مقصدمحور — فقط چیزی که خودمان فرستاده‌ایم
 *
 *  تا اینجا بازنشستگی محصول را با «عنوان» در مقصد پیدا می‌کرد. دو خطرِ
 *  واقعی داشت:
 *
 *   ۱) مالکیت. اگر محصولی با همان عنوان در غرفه بود ولی مالِ پروفایلِ
 *      دیگری (یا اصلاً دستیِ خودِ کاربر) بود، حذف می‌شد. یعنی یک پروفایلِ
 *      کوچک می‌توانست محصولِ پروفایلِ دیگر را ببرد.
 *   ۲) شکنندگی. عنوان در مقصد عوض می‌شود (ویرایشِ دستی، تغییرِ پسوند) و
 *      آن‌وقت محصول «یافت نشد» می‌شد و برای همیشه در غرفه می‌ماند.
 *
 *  دفترچهٔ نگاشت هر دو را حل می‌کند: کلیدِ محصول ⇒ شناسهٔ مقصد ⇒ نامِ
 *  پروفایلی که آن را فرستاده. پس اول از دفترچه می‌پرسیم:
 *      • ردیف هست و مالِ همین پروفایل است ⇒ مستقیم با شناسه (بدونِ
 *        جست‌وجو، بدونِ وابستگی به عنوان)
 *      • ردیف هست ولی مالِ پروفایلِ دیگری است ⇒ دست نمی‌زنیم
 *      • ردیفی نیست ⇒ مثل قبل با عنوان می‌گردیم (سازگاریِ عقب‌رو برای
 *        محصولاتی که پیش از دفترچه ارسال شده‌اند)
 * ===================================================================== */

/**
 * مالکیتِ یک محصولِ رفته را از دفترچه استعلام می‌کند.
 * خروجی: ['id'=>int, 'known'=>bool, 'owned'=>bool, 'owner'=>string]
 */
function retireOwnership(string $target, string $productKey, string $profileKey): array {
    $out = ['id' => 0, 'known' => false, 'owned' => true, 'owner' => ''];
    if ($productKey === '' || ($target !== 'woo' && $target !== 'bsl')) return $out;
    $row = remoteMapLoad()[$target][$productKey] ?? null;
    if (!is_array($row)) return $out;
    $id = (int)($row['id'] ?? 0);
    if ($id <= 0) return $out;
    $owner = trim((string)($row['profile'] ?? ''));
    $out['id'] = $id; $out['known'] = true; $out['owner'] = $owner;
    /* مالکِ ثبت‌نشده یعنی ردیفِ قدیمیِ پیش از ثبتِ پروفایل — مانع نمی‌شویم،
       چون در آن دوره هیچ پروفایلی ثبت نمی‌شد و بلاک‌کردنش یعنی بازنشستگی
       برای همهٔ کاربرانِ قدیمی از کار بیفتد. */
    /* v10.38 (۵۱ب): صف‌های ووکامرس/باسلام مقدارِ خامِ کشویی را به‌عنوان
       profile_key در دفترچه ثبت می‌کنند و آن مقدار URL است، نه کلید. پس
       ردیف‌های واقعی «مالک = URL» دارند و مقایسه با کلید همیشه نابرابر
       می‌شد ⇒ همه چیز «مالِ پروفایلِ دیگر» و هیچ‌وقت هیچ چیز بایگانی
       نمی‌شد. هر دو شکل را به کلید نرمال می‌کنیم و بعد مقایسه. */
    $_own = $owner; $_ask = $profileKey;
    if ($_own !== '' && strpos($_own, '://') !== false) { $_k = profileKey($_own); if ($_k !== '') $_own = $_k; }
    if ($_ask !== '' && strpos($_ask, '://') !== false) { $_k = profileKey($_ask); if ($_k !== '') $_ask = $_k; }
    if ($_own !== '' && $_ask !== '' && $_own !== $_ask) $out['owned'] = false;
    return $out;
}

/* -------------------- نقشهٔ بازنشستگی: پیش‌نمایش و تأیید -------------------- */

/** فایلِ نقشه‌های در انتظارِ تأیید */
function retirePlanFile(): string { return __DIR__ . '/retire_plan.json'; }

/** نقشهٔ پیش‌نمایش را ذخیره می‌کند و توکنش را برمی‌گرداند */
function retirePlanSave(array $plan): string {
    $token = substr(hash('sha256', uniqid('rp', true) . mt_rand()), 0, 24);
    $all = json_decode((string)@file_get_contents(retirePlanFile()), true);
    if (!is_array($all)) $all = [];
    $now = time();
    /* نقشه‌های کهنه (بیش از یک ساعت) دور ریخته می‌شوند: تأییدِ چیزی که
       نیم‌روز پیش دیده شده، تأیید نیست. */
    foreach ($all as $t => $p) if ($now - (int)($p['at'] ?? 0) > 3600) unset($all[$t]);
    $plan['at'] = $now;
    $all[$token] = $plan;
    if (count($all) > 20) $all = array_slice($all, -20, null, true);
    @file_put_contents(retirePlanFile(), json_encode($all, JSON_UNESCAPED_UNICODE), LOCK_EX);
    return $token;
}

/** نقشه را می‌خواند و (در صورت مصرف) حذفش می‌کند */
function retirePlanTake(string $token, bool $consume = true): ?array {
    if ($token === '') return null;
    $all = json_decode((string)@file_get_contents(retirePlanFile()), true);
    if (!is_array($all) || !isset($all[$token]) || !is_array($all[$token])) return null;
    $plan = $all[$token];
    if (time() - (int)($plan['at'] ?? 0) > 3600) { unset($all[$token]);
        @file_put_contents(retirePlanFile(), json_encode($all, JSON_UNESCAPED_UNICODE), LOCK_EX);
        return null; }
    if ($consume) {
        unset($all[$token]);
        @file_put_contents(retirePlanFile(), json_encode($all, JSON_UNESCAPED_UNICODE), LOCK_EX);
    }
    return $plan;
}


/**
 * v10.101: اقلام بازنشستگی از پروفایل — کالاهای in_stock=false روی دیسک.
 * حذف‌شده‌ها/بی‌قیمت از extractLiveCompare می‌آیند؛ ناموجودیِ جزئیات فقط
 * پرچم in_stock را می‌گذارد و تا حالا به removed_items نمی‌رفت.
 */
function collectOosRetireItems(array $profile): array {
    $out = [];
    foreach ((array)($profile['products'] ?? []) as $ent) {
        $pk = ''; $pp = null;
        if (is_array($ent) && count($ent) >= 2 && is_string($ent[0]) && is_array($ent[1])) {
            $pk = (string)$ent[0]; $pp = $ent[1];
        } elseif (is_array($ent)) {
            $pk = (string)($ent['key'] ?? ''); $pp = $ent;
        }
        if ($pk === '' || !is_array($pp)) continue;
        if (array_key_exists('in_stock', $pp) && empty($pp['in_stock'])) {
            $out[] = [
                'title'  => (string)($pp['title'] ?? $pp['name'] ?? $pk),
                'key'    => $pk,
                'link'   => (string)($pp['link'] ?? ''),
                'image'  => (string)($pp['image'] ?? ''),
                'price'  => (string)($pp['price'] ?? ''),
                'reason' => 'ناموجود (in_stock=false)',
            ];
        }
    }
    return $out;
}

/** ادغام removed_items استخراج با اقلام OOS بدون تکرار کلید */
function mergeRetireItems(array $removed, array $extra): array {
    $seen = [];
    $out = [];
    foreach (array_merge(array_values($removed), array_values($extra)) as $it) {
        if (!is_array($it)) continue;
        $k = (string)($it['key'] ?? '');
        $t = trim((string)($it['title'] ?? ''));
        $id = $k !== '' ? ('k:' . $k) : ('t:' . mb_strtolower($t));
        if ($id === 'k:' || $id === 't:') continue;
        if (isset($seen[$id])) continue;
        $seen[$id] = true;
        $out[] = $it;
    }
    return $out;
}

/**
 * v10.101: پس از استخراج (کرون یا دستی) — بایگانی/حذف ناموجودها روی مقصد.
 * مقصد از target پروفایل + تیک add/update؛ اگر تیک نبود ولی target هست،
 * همان مقصد با اقدام پیش‌فرض retire می‌شود (دیگر فقط با retire_mode سراسری نیست).
 *
 * @return array{items:list, result:?array, mode:string, target:string, skipped:string}
 */

/**
 * v10.102: نتیجهٔ بایگانی/حذف ناموجودها را به‌صورت ردیف‌های «تک‌محصول»
 * در صف ارسال باسلام و ووکامرس ثبت می‌کند تا در گزارش صف دیده شود.
 */
function retireReportToSendQueues(array $rt, string $profileKey = '', string $profileName = '', string $target = 'both'): array {
    $out = ['bsl' => false, 'woo' => false, 'bsl_n' => 0, 'woo_n' => 0];
    if (empty($rt) || !is_array($rt)) return $out;
    $items = is_array($rt['items'] ?? null) ? $rt['items'] : [];
    $nRet = (int)($rt['retired'] ?? 0);
    if (!$items && $nRet <= 0) return $out;

    $now = time();
    $stamp = date('Ymd_His');
    $safe = preg_replace('~[^a-zA-Z0-9_\-]+~', '_', $profileKey !== '' ? $profileKey : 'retire') ?: 'retire';
    $name = $profileName !== '' ? $profileName : ($profileKey !== '' ? $profileKey : 'بازنشستگی');

    $bslDetails = [];
    $wooDetails = [];
    foreach ($items as $it) {
        if (!is_array($it)) continue;
        $title = trim((string)($it['title'] ?? ''));
        if ($title === '') continue;
        $key = (string)($it['key'] ?? '');
        $reason = (string)($it['reason'] ?? '');
        $b = (string)($it['bsl'] ?? '');
        $w = (string)($it['woo'] ?? '');
        $didB = $b !== '' && (strpos($b, 'بایگانی') !== false || strpos($b, 'انجام شد') !== false);
        $didW = $w !== '' && strpos($w, 'انجام شد') !== false;
        $failB = $b !== '' && strpos($b, 'خطا') !== false;
        $failW = $w !== '' && strpos($w, 'خطا') !== false;
        $nfB = $b !== '' && strpos($b, 'یافت') !== false;
        $nfW = $w !== '' && strpos($w, 'یافت') !== false;
        if ($didB || $failB || $nfB) {
            $st = $didB ? 'retired' : ($failB ? 'failed' : 'not_found');
            $bslDetails[] = [
                'key' => $key, 'title' => $title,
                'action' => $didB ? 'archive' : ($failB ? 'fail' : 'skip'),
                'status' => $st,
                'detail' => trim($b . ($reason !== '' ? ' · ' . $reason : '')),
                'reason' => $reason, 'retire' => 1, 'at' => $now,
                'result' => $st === 'retired' ? 'sent' : ($st === 'failed' ? 'failed' : 'skipped'),
            ];
        }
        if ($didW || $failW || $nfW) {
            $st = $didW ? 'retired' : ($failW ? 'failed' : 'not_found');
            $wooDetails[] = [
                'key' => $key, 'title' => $title,
                'action' => $didW ? 'delete' : ($failW ? 'fail' : 'skip'),
                'status' => $st,
                'detail' => trim($w . ($reason !== '' ? ' · ' . $reason : '')),
                'reason' => $reason, 'retire' => 1, 'at' => $now,
                'result' => $st === 'retired' ? 'sent' : ($st === 'failed' ? 'failed' : 'skipped'),
            ];
        }
    }
    if (!$bslDetails && !$wooDetails && $nRet > 0) {
        $sum = [
            'key' => '', 'title' => 'بازنشستگی گروهی (' . $nRet . ' مورد)',
            'action' => 'retire', 'status' => 'retired',
            'detail' => 'retired=' . $nRet . ' failed=' . (int)($rt['failed'] ?? 0),
            'retire' => 1, 'at' => $now, 'result' => 'sent',
        ];
        if ($target === 'bsl' || $target === 'both') $bslDetails[] = $sum;
        if ($target === 'woo' || $target === 'both') $wooDetails[] = $sum;
    }

    $wantBsl = ($target === 'bsl' || $target === 'both') && $bslDetails
            && function_exists('bslReadQueue') && function_exists('bslWriteQueue');
    $wantWoo = ($target === 'woo' || $target === 'both') && $wooDetails
            && function_exists('wooReadQueue') && function_exists('wooWriteQueue');

    if ($wantBsl) {
        try {
            $q = bslReadQueue();
            if (!isset($q['entries']) || !is_array($q['entries'])) $q['entries'] = [];
            $qid = 'retire_bsl_' . $safe . '_' . $stamp . '_' . substr(md5((string)mt_rand()), 0, 4);
            $qFile = __DIR__ . '/bsl_queue_products_' . $qid . '.json';
            $plist = [];
            foreach ($bslDetails as $d) {
                $plist[] = ['key' => $d['key'], 'title' => $d['title'], 'retire' => 1, 'final_price' => '0'];
            }
            @file_put_contents($qFile, json_encode($plist, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            $sentD = []; $failD = []; $skipD = [];
            foreach ($bslDetails as $d) {
                if (($d['status'] ?? '') === 'retired') $sentD[] = $d;
                elseif (($d['status'] ?? '') === 'failed') $failD[] = $d;
                else $skipD[] = $d;
            }
            $q['entries'][] = [
                'id' => $qid,
                'status' => 'done',
                'products_file' => $qFile,
                'total' => count($bslDetails),
                'sent' => count($sentD), 'updated' => 0,
                'skipped' => count($skipD), 'failed' => count($failD),
                'current' => count($bslDetails),
                'started_at' => $now, 'done_at' => $now,
                'profile_key' => $profileKey,
                'profile_name' => $name . ' · بایگانی/بازنشستگی',
                'trigger' => 'retire',
                'retire_report' => 1,
                'kind' => 'retire',
                'sent_details' => $sentD,
                'updated_details' => [],
                'skipped_details' => $skipD,
                'failed_details' => $failD,
                'recent_log' => [
                    '🗂 گزارش بایگانی باسلام — ' . count($sentD) . ' مورد',
                    'پروفایل: ' . $name,
                ],
                'config' => ['retire' => 1],
            ];
            if (count($q['entries']) > 80) $q['entries'] = array_slice($q['entries'], -80);
            bslWriteQueue($q);
            $out['bsl'] = true;
            $out['bsl_n'] = count($sentD);
            $out['bsl_id'] = $qid;
        } catch (Throwable $e) {
            $out['bsl_err'] = $e->getMessage();
        }
    }

    if ($wantWoo) {
        try {
            $q = wooReadQueue();
            if (!isset($q['entries']) || !is_array($q['entries'])) $q['entries'] = [];
            $qid = 'retire_woo_' . $safe . '_' . $stamp . '_' . substr(md5((string)mt_rand()), 0, 4);
            $qFile = __DIR__ . '/woo_queue_products_' . $qid . '.json';
            $plist = [];
            foreach ($wooDetails as $d) {
                $plist[] = ['key' => $d['key'], 'title' => $d['title'], 'retire' => 1, 'final_price' => '0'];
            }
            @file_put_contents($qFile, json_encode($plist, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            $sentD = []; $failD = []; $skipD = [];
            foreach ($wooDetails as $d) {
                if (($d['status'] ?? '') === 'retired') $sentD[] = $d;
                elseif (($d['status'] ?? '') === 'failed') $failD[] = $d;
                else $skipD[] = $d;
            }
            $q['entries'][] = [
                'id' => $qid,
                'status' => 'done',
                'products_file' => $qFile,
                'total' => count($wooDetails),
                'sent' => count($sentD), 'updated' => 0,
                'skipped' => count($skipD), 'failed' => count($failD),
                'current' => count($wooDetails),
                'started_at' => $now, 'done_at' => $now,
                'profile_key' => $profileKey,
                'profile_name' => $name . ' · حذف/بازنشستگی',
                'trigger' => 'retire',
                'retire_report' => 1,
                'kind' => 'retire',
                'sent_details' => $sentD,
                'updated_details' => [],
                'skipped_details' => $skipD,
                'failed_details' => $failD,
                'recent_log' => [
                    '🗂 گزارش حذف ووکامرس — ' . count($sentD) . ' مورد',
                    'پروفایل: ' . $name,
                ],
                'config' => ['retire' => 1],
            ];
            if (count($q['entries']) > 80) $q['entries'] = array_slice($q['entries'], -80);
            wooWriteQueue($q);
            $out['woo'] = true;
            $out['woo_n'] = count($sentD);
            $out['woo_id'] = $qid;
        } catch (Throwable $e) {
            $out['woo_err'] = $e->getMessage();
        }
    }
    return $out;
}

function retireAfterExtract(array $cn, array $profile, array $exRes, string $target, array $syncCfg, string $profileKey = ''): array {
    $empty = ['items' => [], 'result' => null, 'mode' => 'off', 'target' => $target, 'skipped' => ''];
    if (empty($exRes['ok'])) {
        $empty['skipped'] = 'extract_not_ok';
        return $empty;
    }
    if (!in_array($target, ['woo', 'bsl', 'both'], true)) {
        $empty['skipped'] = 'target_none';
        return $empty;
    }
    $removed = is_array($exRes['removed_items'] ?? null) ? $exRes['removed_items'] : [];
    $oos = collectOosRetireItems($profile);
    $items = mergeRetireItems($removed, $oos);
    if (!$items) {
        $empty['skipped'] = 'no_items';
        return $empty;
    }

    $mode = (string)($cn['retire_mode'] ?? 'off');
    $auW = !empty($syncCfg['wooAddUpdate']);
    $auB = !empty($syncCfg['bslAddUpdate']);
    $auT = [];
    if ($auW && ($target === 'woo' || $target === 'both')) $auT[] = 'woo';
    if ($auB && ($target === 'bsl' || $target === 'both')) $auT[] = 'bsl';
    /* مقصد روشن است ⇒ بازنشستگی همان مقصد حتی بدون تیک add/update */
    if (!$auT) {
        if ($target === 'woo' || $target === 'both') $auT[] = 'woo';
        if ($target === 'bsl' || $target === 'both') $auT[] = 'bsl';
    }
    $retTarget = count($auT) === 2 ? 'both' : $auT[0];
    $per = [
        'woo' => function_exists('retireAddUpdateAction') ? retireAddUpdateAction($cn, 'woo') : 'delete',
        'bsl' => function_exists('retireAddUpdateAction') ? retireAddUpdateAction($cn, 'bsl') : 'delete',
    ];
    if ($mode === 'off') $mode = 'delete';

    $name = (string)($profile['name'] ?? $profileKey);
    $pk = $profileKey !== '' ? $profileKey : (string)($profile['key'] ?? '');
    $rt = retireRemoved(
        $cn, $items, $retTarget, $mode,
        (int)($exRes['extracted'] ?? 0), false, $name, $per, $pk
    );
    try {
        if (function_exists('notifRetire')) {
            $rt['woo_action'] = $per['woo'];
            $rt['bsl_action'] = $per['bsl'];
            $rt['mode_woo'] = $per['woo'];
            $rt['mode_bsl'] = $per['bsl'];
            notifRetire($cn, $rt, $name);
        }
    } catch (Throwable $e) {}
    $queueRep = ['bsl' => false, 'woo' => false];
    try {
        if (function_exists('retireReportToSendQueues') && (int)($rt['retired'] ?? 0) > 0) {
            $queueRep = retireReportToSendQueues($rt, $pk, $name, $retTarget);
        }
    } catch (Throwable $e) {}

    return [
        'items' => $items,
        'result' => $rt,
        'mode' => $mode,
        'target' => $retTarget,
        'skipped' => (string)($rt['skipped'] ?? ''),
        'oos_merged' => count($oos),
        'removed_src' => count($removed),
        'woo_action' => $per['woo'],
        'bsl_action' => $per['bsl'],
        'queue_report' => $queueRep,
    ];
}

function retireRemoved(array $cn, array $items, string $target, string $mode,
                       int $extracted, bool $dryRun = false, string $profileName = '',
                       ?array $perTarget = null, string $profileKey = ''): array {
    /* v10.34 (۴۸الف): اقدامِ هر مقصد می‌تواند جدا باشد. $perTarget اگر داده
       شود کلیدهای 'woo' و 'bsl' را می‌پذیرد و جای $mode را برای همان مقصد
       می‌گیرد؛ مسیرهای قدیمی که آن را نمی‌دهند دقیقاً مثل قبل کار می‌کنند. */
    $modeWoo = ($perTarget !== null && isset($perTarget['woo'])) ? (string)$perTarget['woo'] : $mode;
    $modeBsl = ($perTarget !== null && isset($perTarget['bsl'])) ? (string)$perTarget['bsl'] : $mode;
    $out = ['mode' => $mode, 'target' => $target, 'checked' => 0,
            'retired' => 0, 'not_found' => 0, 'failed' => 0, 'items' => [], 'dry_run' => $dryRun];
    if ($perTarget !== null) { $out['mode_woo'] = $modeWoo; $out['mode_bsl'] = $modeBsl; }
    if ($mode === 'off' || !$items) { $out['skipped'] = 'غیرفعال'; return $out; }
    // v9.91: مقصدِ «هیچ‌کدام» یعنی هیچ تماسی با ووکامرس/باسلام گرفته نشود
    if ($target === 'none') { $out['skipped'] = 'مقصد «هیچ‌کدام» است'; return $out; }

    $guard = retireGuard(count($items), $extracted, $cn);
    $out['guard'] = $guard;
    if (empty($guard['allow'])) { $out['skipped'] = $guard['reason']; return $out; }

    $w   = $cn['woocommerce'] ?? [];
    $tk  = (string)($cn['basalam']['token'] ?? '');
    $vid = (int)($cn['basalam']['vendor_id'] ?? 0);
    $suffix = trim((string)($w['title_suffix'] ?? ''));
    $_rlRows = [];   // v10.32 (۴۵د): ردیف‌های لاگِ ماندگار
    $out['not_owned'] = 0;   // v10.35 (۴۷ج): مالِ پروفایلِ دیگری بود ⇒ دست نخورد

    foreach ($items as $it) {
        $title = trim((string)($it['title'] ?? ''));
        if ($title === '') continue;
        $pKey  = trim((string)($it['key'] ?? ''));
        $out['checked']++;
        $row = ['title' => mb_substr($title, 0, 60), 'reason' => $it['reason'] ?? '',
                'key' => $pKey];

        if ($target === 'woo' || $target === 'both') {
            /* v10.35 (۴۷ج): اول دفترچه — هم دقیق‌تر است هم مالکیت را می‌داند */
            $own = retireOwnership('woo', $pKey, $profileKey);
            if ($own['known'] && !$own['owned']) {
                $out['not_owned']++;
                $row['woo'] = 'مالِ پروفایلِ دیگر (' . $own['owner'] . ') — دست نخورد';
                $ex = null;
            } elseif ($own['known']) {
                $ex = ['id' => $own['id']];
                $row['woo_match'] = 'ledger';
            } else {
                $t = $suffix !== '' && mb_strpos($title, $suffix) === false ? $title . $suffix : $title;
                $ex = wooFindByTitle($w, $t) ?: wooFindByTitle($w, $title);
                if ($ex) $row['woo_match'] = 'title';
            }
            if (isset($row['woo']) && $row['woo'] !== '') { /* مالکیتِ رد‌شده — کاری نکن */ }
            elseif (!$ex) { $out['not_found']++; $row['woo'] = 'یافت نشد'; }
            elseif ($dryRun) { $row['woo'] = 'آماده: #' . $ex['id']; }
            else {
                $id = (int)$ex['id'];
                if ($modeWoo === 'delete') {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'DELETE', 'products/' . $id . '?force=false');   // به زباله‌دان، نه نابودی
                } elseif ($modeWoo === 'delete_force') {
                    /* v10.34 (۴۸الف): حذفِ همیشگی — فقط وقتی کاربر خودش
                       این گزینه را انتخاب کرده باشد. برگشت‌پذیر نیست. */
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'DELETE', 'products/' . $id . '?force=true');
                } elseif ($modeWoo === 'outofstock') {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'PUT', 'products/' . $id, ['stock_status' => 'outofstock', 'stock_quantity' => 0]);
                } else {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'PUT', 'products/' . $id, ['status' => 'draft']);
                }
                if (!empty($r['ok'])) { $out['retired']++; $row['woo'] = 'انجام شد #' . $id; }
                else { $out['failed']++; $row['woo'] = 'خطا ' . (int)($r['code'] ?? 0); }
            }
        }

        /* v10.38 (۵۱ج): تا اینجا اگر مقصد باسلام بود ولی توکن/شناسهٔ غرفه
           تنظیم نبود، این شاخه بی‌صدا رد می‌شد: نه فیلدی در ردیف، نه
           شمارنده‌ای، نه پیامی. کاربر فقط می‌دید «۲ بررسی‌شده، ۰ آماده» و
           هیچ سرنخی نداشت. حالا صریح گفته می‌شود. */
        if (($target === 'bsl' || $target === 'both') && ($tk === '' || $vid <= 0)) {
            $row['bsl'] = 'اتصالِ باسلام تنظیم نیست (توکن/شناسهٔ غرفه)';
            $out['no_conn'] = ($out['no_conn'] ?? 0) + 1;
        }
        if (($target === 'bsl' || $target === 'both') && $tk !== '' && $vid > 0) {
            /* v10.35 (۴۷ج): همان منطقِ مالکیت برای باسلام. کلیدِ غرفهٔ
               پیش‌فرض خودِ productKey است (bslShopMapKey)، پس همین کافی است. */
            $own = retireOwnership('bsl', $pKey, $profileKey);
            if ($own['known'] && !$own['owned']) {
                $out['not_owned']++;
                $row['bsl'] = 'مالِ پروفایلِ دیگر (' . $own['owner'] . ') — دست نخورد';
                $ex = null;
            } elseif ($own['known']) {
                $ex = ['id' => $own['id']];
                $row['bsl_match'] = 'ledger';
            } else {
                $ex = bslFindByTitle($tk, $vid, $title);
                if ($ex) $row['bsl_match'] = 'title';
            }
            if (isset($row['bsl']) && $row['bsl'] !== '') { /* مالکیتِ رد‌شده */ }
            elseif (!$ex) { $out['not_found']++; $row['bsl'] = 'یافت نشد'; }
            elseif ($dryRun) { $row['bsl'] = 'آماده: #' . $ex['id']; }
            else {
                $id = (int)$ex['id'];
                if ($modeBsl === 'delete' || $modeBsl === 'delete_force') {
                    // v8.62: باسلام حذف واقعی ندارد — بایگانی نزدیک‌ترین معادل است.
                    // قبلاً DELETE به اندپوینتی می‌رفت که وجود ندارد و همیشه ۴۰۴ می‌شد.
                    $r = bslArchiveProduct($tk, $vid, $id);
                } elseif ($modeBsl === 'outofstock') {
                    $r = bslEditProduct($tk, $vid, $id, ['stock' => 0]);
                } else {
                    $r = bslEditProduct($tk, $vid, $id, ['status' => 3790]);   // غیرفعال
                }
                if (!empty($r['ok'])) {
                    $out['retired']++;
                    $row['bsl'] = (($modeBsl === 'delete' || $modeBsl === 'delete_force') ? 'بایگانی شد #' : 'انجام شد #') . $id;
                }
                else { $out['failed']++; $row['bsl'] = 'خطا ' . (int)($r['code'] ?? 0); }
            }
        }
        if (count($out['items']) < 50) $out['items'][] = $row;
        /* v10.32 (۴۵د): ردیفِ لاگ فقط وقتی ساخته می‌شود که واقعاً کاری
           انجام شده باشد — پیش‌نمایش (dry run) و «یافت نشد» ثبت نمی‌شوند،
           وگرنه گزارش پر می‌شد از چیزهایی که هیچ‌وقت بایگانی نشده‌اند. */
        if (!$dryRun) {
            $didW = isset($row['woo']) && strpos((string)$row['woo'], 'انجام شد') !== false;
            $didB = isset($row['bsl']) && (strpos((string)$row['bsl'], 'انجام شد') !== false
                                        || strpos((string)$row['bsl'], 'بایگانی شد') !== false);
            if ($didW || $didB) {
                /* v10.34 (۴۸الف): وقتی اقدامِ دو مقصد فرق دارد، ثبتِ یک «mode»
                   گمراه‌کننده است — هر مقصد اقدامِ خودش را در لاگ می‌گذارد. */
                $_rlMode = $modeWoo === $modeBsl ? $modeWoo : ($modeWoo . '/' . $modeBsl);
                $_rlRows[] = ['title' => (string)$row['title'], 'mode' => $_rlMode,
                    'target' => $target, 'profile' => $profileName,
                    'reason' => (string)($row['reason'] ?? ''),
                    'woo' => (string)($row['woo'] ?? ''), 'bsl' => (string)($row['bsl'] ?? ''),
                    'at' => time()];
            }
        }
    }
    /* v10.32 (۴۵د): یک بار نوشتن در پایان، نه یک بار به‌ازای هر محصول —
       با ۵۰ حذف‌شده، ۵۰ بار بازنویسیِ کلِ فایل روی هاستِ اشتراکی گران است. */
    if (!empty($_rlRows)) { retireLogAdd($_rlRows); $out['logged'] = count($_rlRows); }
    return $out;
}

/* =====================================================================
 *  v8.47: مغایرت‌گیری — مقایسهٔ مقصد با نتایج پروفایل‌ها
 *
 *  همهٔ پروفایل‌هایی که همگام‌سازی دوره‌ای‌شان روشن است را می‌گیرد،
 *  فهرست محصولاتِ نهاییِ آن‌ها را می‌سازد، بعد کل محصولات ووکامرس یا
 *  باسلام را می‌خواند و سه چیز را گزارش می‌کند:
 *    • در مقصد هست ولی در هیچ پروفایلی نیست  → حذف/بازنشستگی
 *    • قیمتش با قیمت پروفایل فرق دارد         → به‌روزرسانی قیمت
 *    • یکسان است                              → دست نخورده
 *
 *  ⚠️ حذف خطرناک است، پس همان محافظ بازنشستگی اینجا هم اعمال می‌شود و
 *  حالت پیش‌فرض «فقط گزارش» است.
 * ===================================================================== */

/** عنوان را برای مقایسه یکدست می‌کند */
/**
 * v8.64: نرمال‌سازی عنوان برای مقایسه با مقصد.
 *
 * نسخهٔ قبلی فقط فاصله‌ها را جمع می‌کرد و کوچک می‌نوشت. نتیجه این بود که
 * محصولی که در پروفایل «کیف چرم & کفش» بود، در ووکامرس با «&amp;» ذخیره
 * شده و «در هیچ پروفایلی نیست» گزارش می‌شد. همین اتفاق برای ی/ک عربی
 * (که خیلی از فروشگاه‌ها موقع ذخیره تبدیل می‌کنند)، نیم‌فاصله و فاصلهٔ
 * سخت (NBSP) هم می‌افتاد. یعنی مغایرت‌گیری روی داده‌های واقعی تقریباً
 * همه‌چیز را «اضافی» می‌دید و اگر کاربر «حذف» می‌زد فاجعه بود.
 *
 * حالا قبل از مقایسه: انتیتی‌های HTML باز می‌شوند، ارقام فارسی/عربی به
 * لاتین، حروف عربی به فارسی، نیم‌فاصله و فاصله‌های نامرئی به فاصلهٔ
 * ساده، و علائم نگارشی حذف می‌شوند.
 */
/* =====================================================================
 *  v8.65: دفترچهٔ شناسهٔ مقصد
 *
 *  تا اینجا مغایرت‌گیری، آمار پسوند و عکس‌دار کردن، محصول را با «عنوان»
 *  در مقصد پیدا می‌کردند. مشکل این است که عنوان تغییر می‌کند: یک ویرایش
 *  دستی در پنل ووکامرس، یا پسوندی که بعداً عوض شود، و آن محصول ناگهان
 *  «در هیچ پروفایلی نیست» گزارش می‌شود. اگر کاربر روی چنین گزارشی حذف
 *  بزند، محصول سالم پاک می‌شود.
 *
 *  هر بار که چیزی با موفقیت ارسال یا آپدیت می‌شود، شناسهٔ مقصد کنار
 *  کلید محصول ثبت می‌شود. کلید محصول از روی آدرس صفحهٔ مبدأ ساخته شده و
 *  با تغییر عنوان عوض نمی‌شود. از آن به بعد تطبیق اول با شناسه انجام
 *  می‌شود و عنوان فقط راه دوم است.
 * ===================================================================== */

/* =====================================================================
 *  v10.35 (۴۷الف): دفترچه، جدا برای هر غرفه
 *
 *  کلیدِ هر ردیف از v10.20 به این شکل است:
 *      productKey            → ووکامرس یا غرفهٔ پیش‌فرضِ باسلام
 *      productKey#v{vid}     → غرفهٔ غیرپیش‌فرضِ شمارهٔ vid
 *
 *  همین پسوند تعیین می‌کند ردیف در کدام فایل بنشیند. پس «جداسازی» هیچ
 *  تغییری در کلیدها یا در رفتارِ خواننده‌ها لازم ندارد؛ فقط نوشتن است
 *  که دیگر روی یک فایلِ مشترک نمی‌رود.
 * ===================================================================== */

/** shardِ یک کلید: رشتهٔ خالی برای فایلِ اصلی، وگرنه «v{vid}» */
function remoteMapShardOf(string $key): string {
    $p = strrpos($key, '#v');
    if ($p === false) return '';
    $vid = substr($key, $p + 2);
    return ($vid !== '' && ctype_digit($vid)) ? 'v' . $vid : '';
}

/** مسیرِ فایلِ یک shard */
function remoteMapFile(string $shard): string {
    return $shard === '' ? REMOTEMAP_FILE
                         : REMOTEMAP_VENDOR_PREFIX . substr($shard, 1) . '.json';
}

/** shardهایی که همین حالا روی دیسک هستند (همیشه شاملِ فایلِ اصلی).
 *  الگو از خودِ ثابت ساخته می‌شود، نه از نامِ فایلِ نوشته‌شده در کد — وگرنه
 *  تغییرِ مسیر (یا هارنسِ تست که مسیرِ دیگری تعریف می‌کند) باعث می‌شد
 *  shardها اصلاً پیدا نشوند و دفترچه بی‌صدا نصفه دیده شود. */
function remoteMapShards(): array {
    $out = [''];
    $pre = REMOTEMAP_VENDOR_PREFIX;
    foreach (glob($pre . '*.json') ?: [] as $f) {
        if (strpos($f, $pre) !== 0) continue;
        $vid = substr($f, strlen($pre), -5);   // ".json" را بردار
        if ($vid !== '' && ctype_digit($vid)) $out[] = 'v' . $vid;
    }
    return array_values(array_unique($out));
}

/** خواندنِ خامِ یک shard — بدون کش، بدون مهاجرت */
function remoteMapReadShard(string $shard): array {
    $f = remoteMapFile($shard);
    if (!is_file($f)) return ['woo' => [], 'bsl' => []];
    $d = json_decode((string)@file_get_contents($f), true);
    if (!is_array($d)) return ['woo' => [], 'bsl' => []];
    return ['woo' => is_array($d['woo'] ?? null) ? $d['woo'] : [],
            'bsl' => is_array($d['bsl'] ?? null) ? $d['bsl'] : []];
}

/** نوشتنِ یک shard. shardِ کاملاً خالی حذف می‌شود تا آشغال جا نماند. */
function remoteMapWriteShard(string $shard, array $m): bool {
    $f = remoteMapFile($shard);
    $woo = is_array($m['woo'] ?? null) ? $m['woo'] : [];
    $bsl = is_array($m['bsl'] ?? null) ? $m['bsl'] : [];
    if ($shard !== '' && !$woo && !$bsl) { @unlink($f); return true; }
    return @file_put_contents($f, json_encode(['woo' => $woo, 'bsl' => $bsl],
        JSON_UNESCAPED_UNICODE), LOCK_EX) !== false;
}

/**
 * مهاجرتِ تنبل: ردیف‌های «#v» که هنوز در فایلِ اصلی مانده‌اند به shardِ
 * خودشان منتقل می‌شوند. یک بار در هر پردازه اجرا می‌شود و اگر چیزی برای
 * انتقال نباشد هزینه‌اش صفر است.
 *
 * چرا تنبل و نه یک اسکریپتِ مهاجرت: کاربر نباید هیچ کاری بکند و هیچ
 * لحظه‌ای نباید دفترچه ناقص باشد. اگر وسطِ کار پردازه بمیرد، بدترین حالت
 * این است که ردیف در هر دو فایل باشد — و چون کلید یکی است، خواندنِ
 * ادغام‌شده همان مقدار را می‌دهد.
 */
/* $rescan فقط برای سلف‌تست است. در اجرای عادی نباید true شود: پویشِ
   دوبارهٔ فایلِ اصلی به‌ازای هر ثبت، روی دفترچهٔ بیست‌هزارتایی گران است و
   بعد از اولین مهاجرت هم هیچ ردیفی برای انتقال باقی نمانده. */
function remoteMapMigrateLegacy(bool $rescan = false): array {
    static $done = false;
    $base = remoteMapReadShard('');
    if ($done && !$rescan) return $base;
    $move = [];
    foreach (['woo', 'bsl'] as $t) {
        foreach ($base[$t] as $k => $v) {
            $sh = remoteMapShardOf((string)$k);
            if ($sh === '') continue;
            $move[$sh][$t][$k] = $v;
        }
    }
    if ($move) {
        foreach ($move as $sh => $byTarget) {
            $cur = remoteMapReadShard($sh);
            foreach ($byTarget as $t => $rows) {
                foreach ($rows as $k => $v) {
                    if (!isset($cur[$t][$k])) $cur[$t][$k] = $v;
                    unset($base[$t][$k]);
                }
            }
            remoteMapWriteShard($sh, $cur);
        }
        remoteMapWriteShard('', $base);
    }
    $done = true;
    return $base;
}

/** کشِ درون‌پردازه‌ایِ نمای ادغام‌شده — با هر نوشتن باطل می‌شود.
 *  $rescan نگهبانِ «یک بار مهاجرت» را هم باز می‌کند؛ فقط سلف‌تست که
 *  فایل‌ها را زیرِ پای برنامه عوض می‌کند به آن نیاز دارد. */
function remoteMapCacheClear(bool $rescan = false): void {
    $GLOBALS['_remoteMapCache'] = null;
    if ($rescan) $GLOBALS['_remoteMapRescan'] = true;
}

/**
 * نمای ادغام‌شدهٔ همهٔ shardها — دقیقاً همان شکلی که همهٔ خواننده‌های
 * قبلی انتظار دارند، پس هیچ نقطهٔ مصرفی لازم نیست عوض شود.
 */
function remoteMapLoad(): array {
    if (isset($GLOBALS['_remoteMapCache']) && is_array($GLOBALS['_remoteMapCache']))
        return $GLOBALS['_remoteMapCache'];
    $out = remoteMapMigrateLegacy(!empty($GLOBALS['_remoteMapRescan']));
    $GLOBALS['_remoteMapRescan'] = false;
    foreach (remoteMapShards() as $sh) {
        if ($sh === '') continue;
        $d = remoteMapReadShard($sh);
        foreach (['woo', 'bsl'] as $t) {
            foreach ($d[$t] as $k => $v) $out[$t][$k] = $v;
        }
    }
    $GLOBALS['_remoteMapCache'] = $out;
    return $out;
}

/**
 * ذخیرهٔ نمای ادغام‌شده — هر ردیف به shardِ خودش می‌رود.
 * shardهایی که در ورودی ردیفی ندارند صریحاً خالی نوشته (یا حذف) می‌شوند،
 * وگرنه «پاک‌کردنِ دفترچه» فقط فایلِ اصلی را پاک می‌کرد.
 */
function remoteMapSave(array $m): bool {
    $byShard = [];
    foreach (remoteMapShards() as $sh) $byShard[$sh] = ['woo' => [], 'bsl' => []];
    foreach (['woo', 'bsl'] as $t) {
        foreach ((is_array($m[$t] ?? null) ? $m[$t] : []) as $k => $v) {
            $sh = remoteMapShardOf((string)$k);
            if (!isset($byShard[$sh])) $byShard[$sh] = ['woo' => [], 'bsl' => []];
            $byShard[$sh][$t][$k] = $v;
        }
    }
    $ok = true;
    foreach ($byShard as $sh => $data) $ok = remoteMapWriteShard($sh, $data) && $ok;
    remoteMapCacheClear();
    return $ok;
}

/**
 * فهرست «کلید → شناسه» را برای یک مقصد ثبت می‌کند.
 * $rows همان sent_details/updated_details است: هر ردیف key و remote_id دارد.
 *
 * v10.35 (۴۷الف): نوشتن shard به shard. اگر ارسال به غرفهٔ ۷ و غرفهٔ ۹
 * هم‌زمان جلو برود، هرکدام فقط فایلِ خودش را می‌خواند و می‌نویسد، پس
 * دیگر هیچ‌کدام کارِ دیگری را بازنویسی نمی‌کند.
 */
function remoteMapRecord(string $target, array $rows, string $profileKey = ''): int {
    if ($target !== 'woo' && $target !== 'bsl') return 0;
    /* v10.38 (۵۱ب): فراخوان‌ها این را از مقدارِ خامِ کشویی می‌گیرند که URL
       است. مالکیت را همیشه به شکلِ کلید ذخیره کن تا مقایسهٔ بعدی در
       retireOwnership درست باشد و ردیف‌های تازه دیگر کج ثبت نشوند. */
    $profileKey = trim($profileKey);
    if ($profileKey !== '' && strpos($profileKey, '://') !== false) {
        $_pk = profileKey($profileKey);
        if ($_pk !== '') $profileKey = $_pk;
    }
    $add = [];
    foreach ($rows as $r) {
        if (!is_array($r)) continue;
        $k = trim((string)($r['key'] ?? ''));
        $id = (int)($r['remote_id'] ?? 0);
        if ($k === '' || $id <= 0) continue;
        $add[$k] = ['id' => $id, 'title' => mb_substr((string)($r['title'] ?? ''), 0, 120),
                    'profile' => $profileKey, 'at' => time()];
        /* v10.33 (۴۶): آخرین قیمت/موجودیِ ارسال‌شده، اگر فراخوان داده باشد.
           هر دو اختیاری‌اند تا فراخوان‌های قدیمی دست‌نخورده کار کنند. */
        if (isset($r['price_rial']) && (int)$r['price_rial'] > 0) $add[$k]['price_rial'] = (int)$r['price_rial'];
        if (isset($r['stock']) && (int)$r['stock'] >= 0)          $add[$k]['stock']      = (int)$r['stock'];
    }
    if (!$add) return 0;
    remoteMapMigrateLegacy();          // پیش از هر نوشتنی، ردیف‌های قدیمی سرِ جایشان
    $byShard = [];
    foreach ($add as $k => $v) $byShard[remoteMapShardOf((string)$k)][$k] = $v;
    foreach ($byShard as $sh => $rowsIn) {
        $m = remoteMapReadShard((string)$sh);
        foreach ($rowsIn as $k => $v) $m[$target][$k] = $v;
        // سقف منطقی تا فایل بی‌نهایت رشد نکند
        if (count($m[$target]) > REMOTEMAP_MAX_ROWS) {
            uasort($m[$target], fn($a, $b) => ((int)($b['at'] ?? 0)) <=> ((int)($a['at'] ?? 0)));
            $m[$target] = array_slice($m[$target], 0, REMOTEMAP_MAX_ROWS, true);
        }
        remoteMapWriteShard((string)$sh, $m);
    }
    remoteMapCacheClear();
    return count($add);
}

/** نگاشت معکوس: شناسهٔ مقصد → کلید محصول */
function remoteMapById(string $target): array {
    $out = [];
    foreach ((remoteMapLoad()[$target] ?? []) as $k => $v) {
        $id = (int)($v['id'] ?? 0);
        if ($id > 0) $out[$id] = $k;
    }
    return $out;
}

function reconNormTitle(string $t): string {
    $t = html_entity_decode($t, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $t = persianToEnglish($t);
    $t = str_replace(['ي', 'ك', 'ة', 'ۀ', 'أ', 'إ', 'ؤ'],
                     ['ی', 'ک', 'ه', 'ه', 'ا', 'ا', 'و'], $t);
    // نیم‌فاصله، فاصلهٔ سخت و نشانه‌های جهت‌دهی → فاصلهٔ ساده
    $t = preg_replace('~[\x{200c}\x{200d}\x{200e}\x{200f}\x{00a0}\x{feff}]~u', ' ', $t);
    // اعراب
    $t = preg_replace('~[\x{064B}-\x{065F}\x{0670}]~u', '', $t);
    // v8.73: پسوند کد محصول «(کد: ۱)» قبل از حذف علائم برداشته شود،
    // وگرنه فقط پرانتزش می‌رود و «کد 1» توی عنوان می‌ماند.
    $t = stripProductCode($t);
    // علائم نگارشی و جداکننده‌ها — «&» و «-» و «—» نباید تفاوت بسازند
    $t = preg_replace('~[^\p{L}\p{N}\s]~u', ' ', $t);
    $t = preg_replace('~\s+~u', ' ', $t);
    $t = trim($t);
    return function_exists('mb_strtolower') ? mb_strtolower($t, 'UTF-8') : strtolower($t);
}

/* =====================================================================
 *  v8.53: آمار محصولات بر اساس پسوند یکتای هر پروفایل
 *
 *  هر پروفایل یک پسوند دارد که به انتهای عنوان محصول اضافه می‌شود.
 *  همین پسوند اجازه می‌دهد در فهرست مقصد بفهمیم هر محصول مال کدام
 *  پروفایل است، بدون اینکه چیزی جداگانه ذخیره کرده باشیم.
 * ===================================================================== */

/** پسوند هر پروفایل، فقط آن‌هایی که پسوند دارند */
function suffixProfiles(): array {
    $out = [];
    foreach (loadProfiles() as $key => $p) {
        $sfx = trim((string)($p['titleSuffix'] ?? ''));
        if ($sfx === '') continue;
        $out[] = ['key' => $key, 'name' => (string)($p['name'] ?? $key),
                  'suffix' => $sfx, 'target' => (string)($p['syncConfig']['target'] ?? 'woo')];
    }
    return $out;
}

/* =====================================================================
 *  v10.36 (۴۹ه): «این محصولِ مقصد مالِ کدام پروفایل است؟»
 *
 *  برای دادنِ نامِ پروفایل به مدل، اول باید بدانیم محصول مالِ کدام
 *  پروفایل است. سه راه داریم، به ترتیبِ دقت:
 *    ۱) دفترچهٔ نگاشت (v8.65 + v10.35) — شناسهٔ مقصد ⇒ پروفایل. دقیق‌ترین
 *       است چون خودمان موقعِ ارسال ثبتش کرده‌ایم و به عنوان وابسته نیست.
 *    ۲) پسوندِ یکتای پروفایل در عنوان — همان چیزی که suffixProfiles
 *       برایش ساخته شده.
 *    ۳) هیچ‌کدام ⇒ رشتهٔ خالی، و مدل مثل قبل فقط با عنوان کار می‌کند.
 *
 *  خروجی یک کلوژر است تا دفترچه و فهرستِ پروفایل‌ها فقط یک بار خوانده
 *  شوند؛ صدا زدنش برای هر محصول در حلقه هیچ ورودی/خروجی‌ای ندارد.
 * ===================================================================== */
function catProfileResolver(string $target = 'bsl'): callable {
    $byId = [];
    $profiles = [];
    if (function_exists('remoteMapLoad')) {
        foreach ((remoteMapLoad()[$target] ?? []) as $k => $v) {
            $id = (int)($v['id'] ?? 0);
            $pk = trim((string)($v['profile'] ?? ''));
            if ($id > 0 && $pk !== '') $byId[$id] = $pk;
        }
    }
    foreach (loadProfiles() as $key => $p) {
        $profiles[$key] = trim((string)($p['name'] ?? $key));
    }
    $sfx = suffixProfiles();
    /* پسوندِ بلندتر اول سنجیده شود: اگر «فروشگاه الف» و «الف» هر دو پسوند
       باشند، عنوانی که هر دو را دارد باید به بلندتر نسبت داده شود. */
    usort($sfx, function ($a, $b) {
        $sa = function_exists('suffixTextNormalize') ? suffixTextNormalize((string)$a['suffix']) : (string)$a['suffix'];
        $sb = function_exists('suffixTextNormalize') ? suffixTextNormalize((string)$b['suffix']) : (string)$b['suffix'];
        return mb_strlen($sb, 'UTF-8') <=> mb_strlen($sa, 'UTF-8');
    });

    return function (int $remoteId, string $title) use ($byId, $profiles, $sfx): string {
        if ($remoteId > 0 && isset($byId[$remoteId])) {
            $pk = $byId[$remoteId];
            $nm = trim((string)($profiles[$pk] ?? ''));
            if ($nm !== '') return $nm;
            if ($pk !== '') return $pk;
        }
        $t = trim($title);
        if ($t !== '') {
            foreach ($sfx as $s) {
                if ($s['suffix'] !== '' && (function_exists('suffixMatches')
                    ? suffixMatches($t, (string)$s['suffix'])
                    : mb_strpos($t, (string)$s['suffix']) !== false)) {
                    return (string)$s['name'];
                }
            }
        }
        return '';
    };
}

/* =====================================================================
 *  v8.62: ویرایش گروهی و تکی محصولات مقصد — سمت سرور
 *
 *  همه‌چیز پس‌زمینه اجرا می‌شود: مرورگر بسته شود هم ادامه دارد، پیشرفت
 *  در فایل نوشته می‌شود و در پایان گزارش به پیام‌رسان‌ها می‌رود.
 * ===================================================================== */

function bulkProgress(array $patch): void {
    $cur = localTaskStateRead(BULKEDIT_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 300) $log = array_slice($log, -300);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['ts'] = time();
    writeProgress(BULKEDIT_PROGRESS_FILE, $cur);
}

/**
 * اجرای ویرایش گروهی.
 *
 * $target  woo | bsl
 * $ids     فهرست شناسه‌های محصول در مقصد
 * $ops     ['price'=>['op'=>'inc','val'=>'10%'], 'stock'=>5, 'status'=>'draft',
 *           'desc'=>'...', 'short_desc'=>'...', 'delete'=>true, 'force'=>false]
 * $dry     فقط پیش‌نمایش، بدون تغییر واقعی
 */
function bulkStopRequested(): bool { return is_file(BULKEDIT_STOP_FILE); }
function bulkStopClear(): void { @unlink(BULKEDIT_STOP_FILE); }

function bulkEditRun(array $cn, string $target, array $ids, array $ops, bool $dry = false, array $resume = []): array {
    $allIds = array_values(array_filter(array_map('intval', $resume['ids'] ?? $ids), fn($v) => $v > 0));
    $remainingIds = array_values(array_filter(array_map('intval', $resume['remaining_ids'] ?? $ids), fn($v) => $v > 0));
    $retryFromCp = array_values(array_filter(array_map('intval', $resume['retry_ids'] ?? []), fn($v) => $v > 0));
    $ids = array_values(array_unique(array_merge($retryFromCp, $remainingIds)));
    if (!$allIds) $allIds = $ids;
    $out = ['ok' => true, 'target' => $target,
            'total' => max(count($allIds), (int)($resume['total'] ?? 0)),
            'changed' => (int)($resume['changed'] ?? 0), 'deleted' => (int)($resume['deleted'] ?? 0),
            'skipped' => (int)($resume['skipped'] ?? 0), 'failed' => (int)($resume['failed'] ?? 0),
            'dry' => $dry, 'items' => [], 'started_at' => time()];
    if (empty($ids) && empty($allIds)) { $out['ok'] = false; $out['error'] = 'محصولی انتخاب نشده'; return $out; }
    /* v10.129: پیش از نخستین درخواستِ تغییر، طرحِ دقیقِ همان محصول در
       checkpoint می‌نشیند. بنابراین اگر هاست بینِ درخواست مقصد و نوشتنِ
       نتیجه قطع شود، resume همان مقدار مطلق را دوباره می‌فرستد و افزایشِ
       نسبیِ قیمت دوباره محاسبه نمی‌شود. */
    $plan = is_array($resume['plan'] ?? null) ? $resume['plan'] : [];
    $retryIds = [];
    $saveCheckpoint = function (int $next) use (&$out, &$plan, &$retryIds, $allIds, $ids, $target, $ops, $dry): void {
        $remaining = array_values(array_unique(array_merge($retryIds, array_slice($ids, $next))));
        bulkProgress(['current' => $next, 'total' => $out['total'],
            'changed' => $out['changed'], 'deleted' => $out['deleted'],
            'failed' => $out['failed'], 'skipped' => $out['skipped'],
            'checkpoint' => ['target' => $target, 'ids' => $allIds, 'ops' => $ops, 'dry' => $dry,
                'remaining_ids' => $remaining, 'retry_ids' => $retryIds, 'plan' => $plan,
                'changed' => $out['changed'], 'deleted' => $out['deleted'],
                'skipped' => $out['skipped'], 'failed' => $out['failed'], 'total' => $out['total']]]);
    };

    $w  = $cn['woocommerce'] ?? [];
    $bs = $cn['basalam'] ?? [];
    $tk = (string)($bs['token'] ?? ''); $vid = (int)($bs['vendor_id'] ?? 0);
    if ($target === 'woo' && empty($w['store_url'])) { $out['ok'] = false; $out['error'] = 'تنظیمات ووکامرس ناقص'; return $out; }
    if ($target === 'bsl' && ($tk === '' || $vid <= 0)) { $out['ok'] = false; $out['error'] = 'تنظیمات باسلام ناقص'; return $out; }

    $wantDelete = !empty($ops['delete']);
    $n = 0; $stopped = false;
    foreach ($ids as $pid) {
        if (bulkStopRequested()) {
            $stopped = true;
            bulkProgress(['running' => false, 'done' => true, 'stopped' => true,
                'partial' => true, 'checkpoint' => ['target' => $target, 'ids' => $allIds,
                    'ops' => $ops, 'dry' => $dry, 'remaining_ids' => array_values(array_unique(array_merge($retryIds, array_slice($ids, $n)))),
                    'retry_ids' => $retryIds, 'plan' => $plan, 'changed' => $out['changed'], 'deleted' => $out['deleted'],
                    'skipped' => $out['skipped'], 'failed' => $out['failed'], 'total' => $out['total']],
                'log_add' => ['⏹ توقف توسط کاربر — checkpoint حفظ شد']]);
            break;
        }
        $n++;
        if ($n % 5 === 1 || $n === count($ids)) {
            bulkProgress(['current' => $n, 'total' => $out['total'],
                'changed' => $out['changed'], 'deleted' => $out['deleted'],
                'failed' => $out['failed'], 'skipped' => $out['skipped']]);
        }
        $row = ['id' => $pid];
        $planned = is_array($plan[(string)$pid] ?? null) ? $plan[(string)$pid] : null;

        // ---- وضعیت فعلی محصول را بگیر تا درصد قیمت درست حساب شود ----
        $curPrice = 0; $title = '';
        if ($planned !== null) {
            $curPrice = (int)($planned['old_price'] ?? 0);
            $title = (string)($planned['title'] ?? '');
            if (is_array($planned['row'] ?? null)) $row = array_merge($row, $planned['row']);
        } elseif ($target === 'woo') {
            $g = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET', 'products/' . $pid);
            if (empty($g['ok'])) { $out['failed']++; $retryIds[] = $pid; $row['error'] = 'یافت نشد (' . (int)$g['code'] . ')'; $out['items'][] = $row; $saveCheckpoint($n); continue; }
            $gb = $g['body'] ?? [];
            $curPrice = (int)preg_replace('~[^0-9]~', '', (string)($gb['regular_price'] ?? '0'));
            $title = (string)($gb['name'] ?? '');
        } else {
            $g = bslReq($tk, 'GET', 'products/' . $pid);
            $gb = $g['body'] ?? [];
            $curPrice = (int)($gb['price'] ?? $gb['primary_price'] ?? 0);
            // باسلام ریالی است و کاربر تومانی فکر می‌کند
            if ($curPrice > 0) $curPrice = (int)round($curPrice / 10);
            $title = (string)($gb['title'] ?? $gb['name'] ?? '');
        }
        $row['title'] = $row['title'] ?? mb_substr($title, 0, 60);
        $row['old_price'] = $row['old_price'] ?? $curPrice;

        // ---- حذف ----
        if ($wantDelete) {
            if ($planned === null) {
                $plan[(string)$pid] = ['delete' => true, 'old_price' => $curPrice,
                    'title' => $title, 'row' => $row];
                $saveCheckpoint($n - 1); // این محصول هنوز در remaining است
            }
            if ($dry) {
                $row['action'] = $target === 'bsl' ? 'بایگانی می‌شود' : 'حذف می‌شود';
                $out['items'][] = $row; $out['deleted']++; $saveCheckpoint($n); continue;
            }
            if ($target === 'woo') {
                $r = wooDeleteProduct($w, $pid, !empty($ops['force']));
                $row['action'] = !empty($ops['force']) ? 'حذف همیشگی' : 'به زباله‌دان';
            } else {
                $r = bslArchiveProduct($tk, $vid, $pid);
                $row['action'] = 'بایگانی (باسلام حذف همیشگی ندارد)';
            }
            if (!empty($r['ok'])) { $out['deleted']++; }
            else { $out['failed']++; $retryIds[] = $pid; $row['error'] = 'خطا ' . (int)($r['code'] ?? 0); }
            $out['items'][] = $row;
            $saveCheckpoint($n);
            usleep(250000);
            continue;
        }

        // ---- ساخت فیلدهای تغییر ----
        $fields = [];
        if ($planned !== null) {
            $fields = is_array($planned['fields'] ?? null) ? $planned['fields'] : [];
        } else {
            if (!empty($ops['price']) && is_array($ops['price'])) {
                $np = editApplyPrice((string)($ops['price']['op'] ?? ''), (string)($ops['price']['val'] ?? ''), $curPrice);
                if ($np !== null && $np !== $curPrice) {
                    $row['new_price'] = $np;
                    $row['pct'] = $curPrice > 0 ? round(($np - $curPrice) / $curPrice * 100, 1) : 0;
                    if ($target === 'woo') $fields['regular_price'] = (string)$np;
                    else $fields['primary_price'] = $np * 10;   // باسلام ریالی
                }
            }
            if (isset($ops['stock']) && $ops['stock'] !== '') {
                $st = (int)$ops['stock'];
                if ($target === 'woo') { $fields['manage_stock'] = true; $fields['stock_quantity'] = $st;
                                         $fields['stock_status'] = $st > 0 ? 'instock' : 'outofstock'; }
                else $fields['stock'] = $st;
                $row['stock'] = $st;
            }
            if (!empty($ops['status'])) {
                $s = (string)$ops['status'];
                if ($target === 'woo') { $fields['status'] = in_array($s, ['publish','draft','private','pending'], true) ? $s : 'draft'; }
                else { $sm = bslStatusMap(); $si = (int)$s; if (isset($sm[$si])) $fields['status'] = $si; }
                $row['status'] = $s;
            }
            if (isset($ops['desc']) && $ops['desc'] !== '') {
                if ($target === 'woo') $fields['description'] = (string)$ops['desc'];
                else $fields['description'] = (string)$ops['desc'];
                $row['desc'] = true;
            }
            if (isset($ops['short_desc']) && $ops['short_desc'] !== '') {
                if ($target === 'woo') $fields['short_description'] = (string)$ops['short_desc'];
                else $fields['brief'] = mb_substr((string)$ops['short_desc'], 0, 250);
                $row['short_desc'] = true;
            }
            if (!empty($ops['title_prefix']) || !empty($ops['title_suffix'])) {
                $nt = (string)($ops['title_prefix'] ?? '') . $title . (string)($ops['title_suffix'] ?? '');
                $nt = trim($nt);
                if ($nt !== '' && $nt !== $title) {
                    if ($target === 'woo') $fields['name'] = $nt; else $fields['name'] = mb_substr($nt, 0, 120);
                    $row['new_title'] = mb_substr($nt, 0, 60);
                }
            }
        }

        if ($planned === null) {
            $plan[(string)$pid] = ['delete' => false, 'old_price' => $curPrice,
                'title' => $title, 'fields' => $fields, 'row' => $row];
            $saveCheckpoint($n - 1); // طرح پیش از اولین PATCH/PUT امن شد
        }
        if (empty($fields)) { $out['skipped']++; $row['action'] = 'تغییری لازم نبود'; $out['items'][] = $row; $saveCheckpoint($n); continue; }
        if ($dry) { $row['action'] = 'آماده: ' . implode('، ', array_keys($fields)); $out['items'][] = $row; $out['changed']++; $saveCheckpoint($n); continue; }

        $r = $target === 'woo' ? wooEditProduct($w, $pid, $fields) : bslEditProduct($tk, $vid, $pid, $fields);
        if (!empty($r['ok'])) { $out['changed']++; $row['action'] = 'انجام شد'; }
        else { $out['failed']++; $retryIds[] = $pid; $row['error'] = 'خطا ' . (int)($r['code'] ?? 0) . ' ' . mb_substr((string)($r['body']['message'] ?? ''), 0, 60); }
        $out['items'][] = $row;
        $saveCheckpoint($n);
        usleep(250000);
    }
    $out['stopped'] = $stopped;
    $out['partial'] = $stopped || (int)$out['failed'] > 0;
    $out['finished_at'] = time();
    return $out;
}

/** پیام گزارش ویرایش گروهی برای پیام‌رسان */
function bulkEditMsg(array $r): string {
    $t = ($r['target'] ?? '') === 'woo' ? 'ووکامرس' : 'باسلام';
    $m = "✏️ ویرایش گروهی — {$t}\n";
    if (!empty($r['dry'])) $m .= "(پیش‌نمایش — چیزی تغییر نکرد)\n";
    $m .= "───────────────\n";
    $m .= "کل: " . (int)($r['total'] ?? 0) . "\n";
    if ((int)($r['changed'] ?? 0) > 0) $m .= "✅ ویرایش شد: " . (int)$r['changed'] . "\n";
    if ((int)($r['deleted'] ?? 0) > 0) {
        $m .= (($r['target'] ?? '') === 'bsl' ? "🗄 بایگانی شد: " : "🗑 حذف شد: ") . (int)$r['deleted'] . "\n";
    }
    if ((int)($r['skipped'] ?? 0) > 0) $m .= "⏭ بدون تغییر: " . (int)$r['skipped'] . "\n";
    if ((int)($r['failed'] ?? 0) > 0)  $m .= "❌ خطا: " . (int)$r['failed'] . "\n";
    $priced = array_values(array_filter($r['items'] ?? [], fn($i) => isset($i['new_price'])));
    if ($priced) {
        $m .= "\n💰 نمونهٔ تغییر قیمت:\n";
        foreach (array_slice($priced, 0, 5) as $i) {
            $sign = ($i['pct'] ?? 0) >= 0 ? '+' : '';
            $m .= '• ' . mb_substr((string)$i['title'], 0, 34) . ' — '
                . number_format((int)$i['old_price']) . ' → ' . number_format((int)$i['new_price'])
                . ' (' . $sign . $i['pct'] . "٪)\n";
        }
    }
    return $m;
}

/* =====================================================================
 *  v8.62: عکس‌دار کردن محصولات ووکامرس از روی پروفایل‌ها
 *
 *  محصولاتی که بی‌تصویر در ووکامرس نشسته‌اند (چه به‌خاطر باگ‌های قدیمی
 *  آپلود، چه به‌خاطر تصویر نگرفتنی) با تطبیق عنوان به تصویرِ همان محصول
 *  در پروفایل وصل می‌شوند. از همان مسیر wooImagePayload استفاده می‌کند،
 *  پس اگر آپلود مستقیم نشد، آدرس به خود ووکامرس سپرده می‌شود.
 * ===================================================================== */

function photoFixProgress(array $patch): void {
    $cur = localTaskStateRead(PHOTOFIX_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 300) $log = array_slice($log, -300);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['ts'] = time();
    writeProgress(PHOTOFIX_PROGRESS_FILE, $cur);
}

/** نگاشت «عنوان نرمال‌شده → تصویر» از روی همهٔ پروفایل‌ها */
function photoFixIndex(?string $onlyProfile = null, ?array &$byKey = null): array {
    $idx = [];
    $byKey = [];   // v8.65: همان تصویرها، این بار با کلید محصول
    foreach (loadProfiles() as $key => $p) {
        if ($onlyProfile !== null && $onlyProfile !== '' && $key !== $onlyProfile) continue;
        $suffix = trim((string)($p['titleSuffix'] ?? ''));
        foreach (profileOrderedProducts($p, null, false) as $prod) {
            if (!is_array($prod)) continue;
            $img = trim((string)($prod['image'] ?? ''));
            if ($img === '') continue;
            $rec = ['image' => $img, 'profile' => $p['name'] ?? $key,
                    'images' => productImageList($prod)];
            $pk = trim((string)($prod['key'] ?? ''));
            if ($pk !== '' && !isset($byKey[$pk])) $byKey[$pk] = $rec;
            $t = trim((string)($prod['title'] ?? $prod['name'] ?? ''));
            if ($t === '') continue;
            foreach ([$t, ($suffix !== '' ? trim($t . ' ' . $suffix) : $t)] as $variant) {
                $k = bslNormalizeTitle($variant);
                if ($k !== '' && !isset($idx[$k])) $idx[$k] = $rec;
            }
        }
    }
    return $idx;
}

/**
 * محصولات بی‌تصویر ووکامرس را پیدا و از روی پروفایل عکس‌دار می‌کند.
 * $dry فقط گزارش می‌دهد.
 */
function photoStopRequested(): bool { return is_file(PHOTOFIX_STOP_FILE); }
function photoStopClear(): void { @unlink(PHOTOFIX_STOP_FILE); }

function photoFixRun(array $cn, bool $dry = false, string $onlyProfile = '', int $maxItems = 2000,
                     ?array $cp = null): array {
    $cp = is_array($cp) ? $cp : [];
    $w = $cn['woocommerce'] ?? [];
    $out = ['ok' => true, 'scanned' => (int)($cp['scanned'] ?? 0),
            'missing' => (int)($cp['missing'] ?? 0), 'matched' => (int)($cp['matched'] ?? 0),
            'fixed' => (int)($cp['fixed'] ?? 0), 'failed' => (int)($cp['failed'] ?? 0),
            'unmatched' => (int)($cp['unmatched'] ?? 0), 'dry' => $dry,
            'items' => is_array($cp['items'] ?? null) ? $cp['items'] : [],
            'started_at' => (int)($cp['started_at'] ?? time())];
    if (empty($w['store_url'])) { $out['ok'] = false; $out['error'] = 'تنظیمات ووکامرس ناقص'; return $out; }

    $pfByKey = null;
    $idx = photoFixIndex($onlyProfile !== '' ? $onlyProfile : null, $pfByKey);
    $out['index_size'] = count($idx);
    if (empty($idx)) { $out['ok'] = false; $out['error'] = 'در پروفایل‌ها تصویری پیدا نشد'; return $out; }
    // v8.65: تطبیق با شناسهٔ ثبت‌شده، برای محصولی که در ووکامرس تغییر نام داده
    $pfIdMap = remoteMapById('woo');
    $out['by_id'] = 0;
    photoFixProgress(['log_add' => ['🗂 ' . count($idx) . ' تصویر از پروفایل‌ها فهرست شد'
        . (count($pfIdMap) ? ' · ' . count($pfIdMap) . ' شناسهٔ ثبت‌شده' : '')]]);

    $page = max(1, (int)($cp['page'] ?? 1));
    $startOffset = max(0, (int)($cp['offset'] ?? 0));
    $runScanned = 0;
    $stopped = false;
    $incomplete = false;
    $incompleteReason = '';
    $savePhotoCheckpoint = function (int $nextPage, int $nextOffset) use (&$out, $onlyProfile, $dry, $cp): void {
        photoFixProgress(['scanned' => $out['scanned'], 'missing' => $out['missing'],
            'matched' => $out['matched'], 'fixed' => $out['fixed'], 'failed' => $out['failed'],
            'unmatched' => $out['unmatched'], 'checkpoint' => [
                'page' => $nextPage, 'offset' => $nextOffset, 'scanned' => $out['scanned'],
                'missing' => $out['missing'], 'matched' => $out['matched'], 'fixed' => $out['fixed'],
                'failed' => $out['failed'], 'unmatched' => $out['unmatched'],
                'profile' => $onlyProfile, 'dry' => $dry, 'notify' => !empty($cp['notify']),
                'items' => $out['items'], 'started_at' => $out['started_at']]]);
    };
    /* maxItems محدودیتِ هر نوبت است، نه کلِ کار؛ شمارندهٔ تجمعی در
       checkpoint می‌ماند و اجرای بعدی با همان page/offset ادامه می‌دهد. */
    while ($runScanned < $maxItems) {
        if (photoStopRequested()) {
            $stopped = true;
            photoFixProgress(['log_add' => ['⏹ توقف توسط کاربر — checkpoint حفظ شد']]);
            break;
        }
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
                    'products?per_page=100&page=' . $page . '&status=any');
        if (empty($r['ok']) || !is_array($r['body'] ?? null)) {
            $incomplete = true; $incompleteReason = 'http';
            $savePhotoCheckpoint($page, 0);
            photoFixProgress(['phase' => 'fetch', 'log_add' => ['⚠️ دریافت صفحهٔ ' . $page . ' ناموفق ماند — checkpoint حفظ شد']]);
            break;
        }
        if (empty($r['body'])) break; // پایان طبیعی فهرست
        $itemOffset = 0;
        foreach ($r['body'] as $p) {
            if (photoStopRequested()) {
                $stopped = true;
                photoFixProgress(['log_add' => ['⏹ توقف توسط کاربر — checkpoint حفظ شد']]);
                break;
            }
            if ($runScanned >= $maxItems) {
                $incomplete = true; $incompleteReason = 'run_limit';
                break;
            }
            if ($page === (int)($cp['page'] ?? 1) && $itemOffset < $startOffset) {
                $itemOffset++;
                continue;
            }
            $itemOffset++;
            $out['scanned']++; $runScanned++;
            $imgs = $p['images'] ?? [];
            if (!empty($imgs) && is_array($imgs)) { $savePhotoCheckpoint($page, $itemOffset); continue; }    // تصویر دارد
            $out['missing']++;
            $pid = (int)($p['id'] ?? 0);
            $name = trim((string)($p['name'] ?? ''));
            $hit = $idx[bslNormalizeTitle($name)] ?? null;
            if ($hit === null && $pid > 0 && isset($pfIdMap[$pid])
                && isset($pfByKey[$pfIdMap[$pid]])) {
                $hit = $pfByKey[$pfIdMap[$pid]];   // عنوان عوض شده، شناسه نه
                $out['by_id']++;
            }
            if ($hit === null) {
                $out['unmatched']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => 'در پروفایل‌ها نبود'];
                $savePhotoCheckpoint($page, $itemOffset);
                continue;
            }
            $out['matched']++;
            if ($dry) {
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60),
                    'status' => 'آماده', 'profile' => $hit['profile'], 'image' => $hit['image']];
                $savePhotoCheckpoint($page, $itemOffset);
                continue;
            }
            $note = null;
            $GLOBALS['_currentProductLink'] = '';
            $imgsHit = !empty($hit['images']) && is_array($hit['images'])
                     ? $hit['images'] : [(string)$hit['image']];
            $payload = wooGalleryPayload($w, $imgsHit, $note);
            if (empty($payload)) {
                $out['failed']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => 'تصویر آماده نشد: ' . (string)$note];
                $savePhotoCheckpoint($page, $itemOffset);
                continue;
            }
            $u = wooEditProduct($w, $pid, ['images' => $payload]);
            if (empty($u['ok']) && wooIsImageError($u)) {
                $out['failed']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => 'ووکامرس تصویر را نگرفت'];
                $savePhotoCheckpoint($page, $itemOffset);
                continue;
            }
            if (!empty($u['ok'])) { $out['fixed']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => '✅ عکس‌دار شد', 'profile' => $hit['profile']]; }
            else { $out['failed']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => 'خطا ' . (int)$u['code']]; }
            $savePhotoCheckpoint($page, $itemOffset);
            usleep(200000);
        }
        if ($stopped) break;
        photoFixProgress(['scanned' => $out['scanned'], 'missing' => $out['missing'],
            'fixed' => $out['fixed'], 'failed' => $out['failed'], 'unmatched' => $out['unmatched'],
            'log_add' => ['📄 صفحهٔ ' . $page . ' — بررسی‌شده ' . $out['scanned'] . '، بی‌تصویر ' . $out['missing'] . '، درست‌شده ' . $out['fixed']]]);
        $savePhotoCheckpoint($page + 1, 0);
        if (count($r['body']) < 100) break;
        $page++;
    }
    if (!$stopped && !$incomplete && $runScanned >= $maxItems) {
        $incomplete = true; $incompleteReason = 'run_limit';
    }
    if ($incomplete && $incompleteReason === 'run_limit') {
        /* اگر کلِ صفحه مصرف شده، checkpoint صفحهٔ بعد است؛ اگر وسطِ صفحه
           قطع شد، همان offsetِ محصول بعدی را نگه می‌داریم. */
        $bodyCount = isset($r['body']) && is_array($r['body']) ? count($r['body']) : 0;
        $nextPage = ($bodyCount > 0 && (int)($itemOffset ?? 0) >= $bodyCount) ? $page + 1 : $page;
        $nextOffset = $nextPage > $page ? 0 : (int)($itemOffset ?? 0);
        $savePhotoCheckpoint($nextPage, $nextOffset);
    }
    $out['stopped'] = $stopped;
    $out['partial'] = $stopped || $incomplete || (int)$out['failed'] > 0;
    $out['partial_reason'] = $stopped ? 'stopped' : ($incompleteReason ?: ((int)$out['failed'] > 0 ? 'item_error' : ''));
    $out['finished_at'] = time();
    return $out;
}

function photoFixMsg(array $r): string {
    $m = "🖼 عکس‌دار کردن محصولات ووکامرس\n";
    if (!empty($r['dry'])) $m .= "(پیش‌نمایش — چیزی تغییر نکرد)\n";
    $m .= "───────────────\n";
    $m .= "بررسی‌شده: " . (int)($r['scanned'] ?? 0) . "\n";
    $m .= "بی‌تصویر: " . (int)($r['missing'] ?? 0) . "\n";
    $m .= "✅ عکس‌دار شد: " . (int)($r['fixed'] ?? 0) . "\n";
    if ((int)($r['unmatched'] ?? 0) > 0) $m .= "❓ در پروفایل‌ها نبود: " . (int)$r['unmatched'] . "\n";
    if ((int)($r['failed'] ?? 0) > 0)    $m .= "❌ ناموفق: " . (int)$r['failed'] . "\n";
    return $m;
}

/* =====================================================================
 *  v8.62: گزارش شبانهٔ تفصیلی (پیش‌فرض ساعت ۲۳)
 *
 *  از گزارش‌های استخراج هر پروفایل، محصولات اضافه‌شده، تغییر قیمت‌داده و
 *  حذف‌شده را جمع می‌کند و با میزان و درصد تغییر می‌فرستد. وضعیت ارسال
 *  به ووکامرس و باسلام هم از صف‌ها خوانده می‌شود.
 *
 *  کران‌جاب هر پنج دقیقه اجرا می‌شود، پس اینجا فقط تصمیم می‌گیریم که
 *  «آیا الان وقتش هست و امروز فرستاده‌ایم یا نه».
 * ===================================================================== */

function digestLoadState(): array {
    if (!is_file(DIGEST_STATE_FILE)) return [];
    $d = json_decode((string)@file_get_contents(DIGEST_STATE_FILE), true);
    return is_array($d) ? $d : [];
}
function digestSaveState(array $s): void {
    @file_put_contents(DIGEST_STATE_FILE, json_encode($s, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/** آیا الان باید گزارش شبانه برود؟ */
function digestDue(array $cn, int $now): bool {
    if (empty($cn['digest_enabled'])) return false;
    $hour = max(0, min(23, (int)($cn['digest_hour'] ?? 23)));
    // ساعت محلی سرور؛ اگر منطقهٔ زمانی تنظیم شده باشد همان اعمال می‌شود
    $tz = trim((string)($cn['digest_tz'] ?? ''));
    if ($tz !== '') { $old = @date_default_timezone_get(); @date_default_timezone_set($tz); }
    $h = (int)date('G', $now);
    $today = date('Y-m-d', $now);
    if ($tz !== '' && isset($old)) @date_default_timezone_set($old);

    if ($h < $hour) return false;                    // هنوز نرسیده
    $st = digestLoadState();
    if (($st['last_date'] ?? '') === $today) return false;   // امروز فرستاده شده
    return true;
}

/**
 * جمع‌آوری آمار همهٔ پروفایل‌ها از گزارش‌های استخراج امروز.
 * $sinceHours بازهٔ زمانی که گزارش‌ها را از آن می‌خوانیم.
 */
function digestBuild(array $cn, int $sinceHours = 24): array {
    $since = time() - $sinceHours * 3600;
    $profiles = loadProfiles();
    $out = ['ok' => true, 'since' => $since, 'hours' => $sinceHours,
            'profiles' => [], 'tot_new' => 0, 'tot_changed' => 0, 'tot_removed' => 0,
            'tot_up' => 0, 'tot_down' => 0, 'sum_pct' => 0.0, 'n_pct' => 0];

    // آخرین گزارش هر پروفایل در بازه
    $byProfile = [];
    foreach (glob(__DIR__ . '/extract_report_*.json') ?: [] as $f) {
        $ts = (int)@filemtime($f);
        if ($ts < $since) continue;
        $d = json_decode((string)@file_get_contents($f), true);
        if (!is_array($d)) continue;
        $pk = (string)($d['profile_key'] ?? '');
        $pn = (string)($d['profile_name'] ?? $pk);
        $key = $pk !== '' ? $pk : $pn;
        if ($key === '') continue;
        if (!isset($byProfile[$key]) || $ts > $byProfile[$key]['_ts']) {
            $d['_ts'] = $ts; $d['_name'] = $pn !== '' ? $pn : $key;
            $byProfile[$key] = $d;
        }
    }

    foreach ($byProfile as $key => $d) {
        $new = (array)($d['new_items'] ?? []);
        $chg = (array)($d['changed_items'] ?? []);
        $rem = (array)($d['removed_items'] ?? []);
        $up = 0; $down = 0; $pctSum = 0.0; $pctN = 0;
        foreach ($chg as $c) {
            if (($c['dir'] ?? '') === 'up') $up++; else $down++;
            if (isset($c['pct'])) { $pctSum += (float)$c['pct']; $pctN++; }
        }
        $row = [
            'name' => (string)$d['_name'],
            'at' => (int)$d['_ts'],
            'extracted' => (int)($d['extracted'] ?? 0),
            'new' => count($new), 'changed' => count($chg), 'removed' => count($rem),
            'up' => $up, 'down' => $down,
            'avg_pct' => $pctN > 0 ? round($pctSum / $pctN, 1) : 0,
            'new_items' => array_slice($new, 0, 5),
            'changed_items' => array_slice($chg, 0, 5),
            'removed_items' => array_slice($rem, 0, 5),
        ];
        $out['profiles'][] = $row;
        $out['tot_new'] += $row['new']; $out['tot_changed'] += $row['changed'];
        $out['tot_removed'] += $row['removed'];
        $out['tot_up'] += $up; $out['tot_down'] += $down;
        $out['sum_pct'] += $pctSum; $out['n_pct'] += $pctN;
    }
    $out['avg_pct'] = $out['n_pct'] > 0 ? round($out['sum_pct'] / $out['n_pct'], 1) : 0;

    // وضعیت ارسال به مقصدها در همین بازه
    foreach ([['woo', wooReadQueue()], ['bsl', bslReadQueue()]] as [$k, $q]) {
        $sent = 0; $upd = 0; $skip = 0; $fail = 0; $rows = 0;
        foreach ((array)($q['entries'] ?? []) as $e) {
            $at = (int)($e['done_at'] ?? $e['started_at'] ?? 0);
            if ($at < $since) continue;
            $rows++;
            $sent += (int)($e['sent'] ?? 0); $upd += (int)($e['updated'] ?? 0);
            $skip += (int)($e['skipped'] ?? 0); $fail += (int)($e['failed'] ?? 0);
        }
        $out[$k] = ['rows' => $rows, 'sent' => $sent, 'updated' => $upd,
                    'skipped' => $skip, 'failed' => $fail];
    }
    return $out;
}

/** متن گزارش شبانه */
function digestMsg(array $d): string {
    $m = "🌙 گزارش شبانهٔ محصولات\n";
    $m .= '🗓 ' . date('Y-m-d H:i') . ' · ' . (int)($d['hours'] ?? 24) . " ساعت گذشته\n";
    $m .= "═══════════════\n";
    $m .= "📊 مجموع همهٔ پروفایل‌ها\n";
    $m .= '🆕 اضافه‌شده: ' . (int)$d['tot_new'] . "\n";
    $m .= '💰 تغییر قیمت: ' . (int)$d['tot_changed']
        . ' (↑' . (int)$d['tot_up'] . ' ↓' . (int)$d['tot_down'] . ")\n";
    if ((int)$d['tot_changed'] > 0) {
        $s = $d['avg_pct'] >= 0 ? '+' : '';
        $m .= '   میانگین تغییر: ' . $s . $d['avg_pct'] . "٪\n";
    }
    $m .= '❌ حذف‌شده از مبدأ: ' . (int)$d['tot_removed'] . "\n";

    $wo = $d['woo'] ?? []; $bs = $d['bsl'] ?? [];
    if ((int)($wo['rows'] ?? 0) > 0 || (int)($bs['rows'] ?? 0) > 0) {
        $m .= "\n📤 ارسال به مقصد\n";
        if ((int)($wo['rows'] ?? 0) > 0) {
            $m .= '🛒 ووکامرس: ' . (int)$wo['sent'] . ' جدید · ' . (int)$wo['updated'] . ' آپدیت'
                . ((int)$wo['failed'] > 0 ? ' · ❌' . (int)$wo['failed'] : '') . "\n";
        }
        if ((int)($bs['rows'] ?? 0) > 0) {
            $m .= '🏪 باسلام: ' . (int)$bs['sent'] . ' جدید · ' . (int)$bs['updated'] . ' آپدیت'
                . ((int)$bs['failed'] > 0 ? ' · ❌' . (int)$bs['failed'] : '') . "\n";
        }
    }

    foreach ((array)$d['profiles'] as $p) {
        if ((int)$p['new'] === 0 && (int)$p['changed'] === 0 && (int)$p['removed'] === 0) continue;
        $m .= "\n───────────────\n📁 " . $p['name'] . "\n";
        $m .= '   🆕 ' . (int)$p['new'] . '  💰 ' . (int)$p['changed']
            . ' (↑' . (int)$p['up'] . ' ↓' . (int)$p['down'] . ')  ❌ ' . (int)$p['removed'] . "\n";
        foreach ((array)$p['changed_items'] as $c) {
            $sign = ($c['dir'] ?? '') === 'up' ? '📈' : '📉';
            $pc = isset($c['pct']) ? (((float)$c['pct'] >= 0 ? '+' : '') . $c['pct'] . '٪') : '';
            $m .= '   ' . $sign . ' ' . mb_substr((string)($c['title'] ?? ''), 0, 30)
                . ' ' . (string)($c['old_price'] ?? '') . '→' . (string)($c['new_price'] ?? '')
                . ' ' . $pc . "\n";
        }
        foreach ((array)$p['new_items'] as $c) {
            $m .= '   🆕 ' . mb_substr((string)($c['title'] ?? ''), 0, 34) . "\n";
        }
        foreach ((array)$p['removed_items'] as $c) {
            $m .= '   ❌ ' . mb_substr((string)($c['title'] ?? ''), 0, 34) . "\n";
        }
    }
    if (empty($d['profiles'])) $m .= "\n(در این بازه گزارش استخراجی ثبت نشده)\n";
    return $m;
}

/** اگر وقتش باشد، گزارش شبانه را می‌فرستد */
function digestMaybeSend(array $cn, int $now): array {
    if (!digestDue($cn, $now)) return ['sent' => false, 'skipped' => 'not_due'];
    $why = notifPrereq($cn);
    if ($why !== null) return ['sent' => false, 'skipped' => $why];
    $d = digestBuild($cn, max(1, min(168, (int)($cn['digest_hours'] ?? 24))));
    $res = notifSend($cn, digestMsg($d), 'digest');
    $st = digestLoadState();
    $st['last_date'] = date('Y-m-d', $now);
    $st['last_at'] = $now;
    $st['last_totals'] = ['new' => $d['tot_new'], 'changed' => $d['tot_changed'], 'removed' => $d['tot_removed']];
    digestSaveState($st);
    return ['sent' => true, 'delivery' => $res, 'totals' => $st['last_totals']];
}

function suffixProgress(array $patch): void {
    $cur = localTaskStateRead(SUFFIX_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 200) $log = array_slice($log, -200);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['ts'] = time();
    writeProgress(SUFFIX_PROGRESS_FILE, $cur);
}

/**
 * همهٔ محصولات باسلام با وضعیتشان.
 * برخلاف reconFetchBsl که فقط فعال و غیرفعال را می‌گیرد، اینجا وضعیت
 * تأیید نشده و در انتظار هم لازم است.
 */
function suffixStopRequested(): bool { return is_file(SUFFIX_STOP_FILE); }
function suffixStopClear(): void { @unlink(SUFFIX_STOP_FILE); }

function suffixFetchBsl(string $tk, int $vid, int $maxPages = 80, ?array $cp = null,
                         ?array &$meta = null, string $checkpointTarget = 'bsl', array $summaryContext = []): array {
    $meta = ['complete' => false, 'partial' => false, 'stopped' => false,
             'reason' => '', 'error' => '', 'page' => (int)($cp['page'] ?? 0)];
    $rows = is_array($cp['rows'] ?? null) && (string)($cp['target'] ?? '') === 'bsl'
        ? array_values(array_filter($cp['rows'], 'is_array')) : [];
    if (($cp['phase'] ?? '') === 'match' && (!empty($cp['complete']) || $rows)) {
        $meta['complete'] = true;
        return $rows;
    }
    $startPage = max(1, (int)($cp['page'] ?? 0) + 1);
    $lastPage = max(0, $startPage - 1);
    $statuses = '&statuses=2976&statuses=3790&statuses=3567&statuses=3568&statuses=4184';
    $save = static function (int $page, array $rows, bool $complete = false) use
        ($checkpointTarget, $summaryContext, $vid, $cp): void {
        $base = $summaryContext;
        $base['target'] = $checkpointTarget;
        $base['phase'] = 'fetch';
        $base['page'] = $page;
        $base['rows'] = $rows;
        $base['complete'] = $complete;
        $base['current_vid'] = $vid;
        $base['started_at'] = (int)($summaryContext['started_at'] ?? ($cp['started_at'] ?? time()));
        $base['notify'] = !empty($summaryContext['notify']) || !empty($cp['notify']);
        if ($checkpointTarget !== 'summary') {
            $base = ['target' => $checkpointTarget, 'phase' => 'fetch', 'page' => $page,
                'rows' => $rows, 'complete' => $complete, 'notify' => $base['notify'],
                'started_at' => $base['started_at']];
        }
        suffixProgress(['phase' => 'fetch', 'page' => $page, 'fetched' => count($rows),
            'checkpoint' => $base]);
    };
    $limit = $startPage + max(1, $maxPages);
    for ($page = $startPage; $page < $limit; $page++) {
        if (suffixStopRequested()) {
            $meta['stopped'] = true; $meta['partial'] = true; $meta['reason'] = 'stopped';
            $meta['page'] = $lastPage;
            $save($lastPage, $rows, false);
            break;
        }
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $page
             . '&per_page=100' . $statuses);
        if (empty($r['ok'])) {
            $meta['partial'] = true; $meta['reason'] = 'http';
            $meta['error'] = (string)($r['error'] ?? ('HTTP ' . ($r['code'] ?? 0)));
            $meta['page'] = $page;
            $save($lastPage, $rows, false); // retry this page on the next run
            break;
        }
        $batch = bslRowsOf($r['body'] ?? []);
        if (!$batch) {
            $meta['complete'] = true; $meta['page'] = $lastPage;
            $save($lastPage, $rows, true);
            break;
        }
        foreach ($batch as $pr) {
            if (!is_array($pr)) continue;
            $rev  = $pr['revision']['data'] ?? [];
            $name = trim((string)($pr['title'] ?? ($pr['name'] ?? ($rev['title'] ?? ''))));
            if ($name === '') continue;
            $st = $pr['status'] ?? null;
            $rows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name,
                       'status' => (int)(is_array($st) ? ($st['value'] ?? 0) : $st)];
        }
        $lastPage = $page; $meta['page'] = $page;
        suffixProgress(['log_add' => ['📄 باسلام صفحهٔ ' . $page . ': ' . count($batch)
            . ' محصول (مجموع ' . count($rows) . ')'], 'phase' => 'fetch', 'page' => $page,
            'fetched' => count($rows)]);
        if (count($batch) < 100) {
            $meta['complete'] = true;
            $save($page, $rows, true);
            break;
        }
        $save($page, $rows, false);
        usleep(150000);
    }
    if (!$meta['complete'] && !$meta['partial']) {
        $meta['partial'] = true; $meta['reason'] = 'max_pages'; $meta['page'] = $lastPage;
        $save($lastPage, $rows, false);
    }
    return $rows;
}

/** همهٔ محصولات ووکامرس با وضعیتشان */
function suffixFetchWoo(array $w, int $maxPages = 80, ?array $cp = null,
                        ?array &$meta = null, string $checkpointTarget = 'woo', array $summaryContext = []): array {
    $meta = ['complete' => false, 'partial' => false, 'stopped' => false,
             'reason' => '', 'error' => '', 'page' => (int)($cp['page'] ?? 0)];
    $rows = is_array($cp['rows'] ?? null) && (string)($cp['target'] ?? '') === 'woo'
        ? array_values(array_filter($cp['rows'], 'is_array')) : [];
    if (($cp['phase'] ?? '') === 'match' && (!empty($cp['complete']) || $rows)) {
        $meta['complete'] = true;
        return $rows;
    }
    $startPage = max(1, (int)($cp['page'] ?? 0) + 1);
    $lastPage = max(0, $startPage - 1);
    $save = static function (int $page, array $rows, bool $complete = false) use
        ($checkpointTarget, $summaryContext, $cp): void {
        $base = $summaryContext;
        $base['target'] = $checkpointTarget; $base['phase'] = 'fetch';
        $base['page'] = $page; $base['rows'] = $rows; $base['complete'] = $complete;
        $base['started_at'] = (int)($summaryContext['started_at'] ?? ($cp['started_at'] ?? time()));
        $base['notify'] = !empty($summaryContext['notify']) || !empty($cp['notify']);
        if ($checkpointTarget !== 'summary') {
            $base = ['target' => $checkpointTarget, 'phase' => 'fetch', 'page' => $page,
                'rows' => $rows, 'complete' => $complete, 'notify' => $base['notify'],
                'started_at' => $base['started_at']];
        }
        suffixProgress(['phase' => 'fetch', 'page' => $page, 'fetched' => count($rows),
            'checkpoint' => $base]);
    };
    $limit = $startPage + max(1, $maxPages);
    for ($page = $startPage; $page < $limit; $page++) {
        if (suffixStopRequested()) {
            $meta['stopped'] = true; $meta['partial'] = true; $meta['reason'] = 'stopped';
            $meta['page'] = $lastPage; $save($lastPage, $rows, false); break;
        }
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
            'products?per_page=100&status=any&page=' . $page);
        if (empty($r['ok']) || !is_array($r['body'])) {
            $meta['partial'] = true; $meta['reason'] = 'http';
            $meta['error'] = (string)($r['error'] ?? ('HTTP ' . ($r['code'] ?? 0)));
            $meta['page'] = $page; $save($lastPage, $rows, false); break;
        }
        $batch = $r['body'];
        if (!$batch) {
            $meta['complete'] = true; $meta['page'] = $lastPage;
            $save($lastPage, $rows, true); break;
        }
        foreach ($batch as $pr) {
            if (!is_array($pr)) continue;
            $name = trim((string)($pr['name'] ?? ''));
            if ($name === '') continue;
            $rows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name,
                       'wstatus' => (string)($pr['status'] ?? '')];
        }
        $lastPage = $page; $meta['page'] = $page;
        suffixProgress(['log_add' => ['📄 ووکامرس صفحهٔ ' . $page . ': ' . count($batch)
            . ' محصول (مجموع ' . count($rows) . ')'], 'phase' => 'fetch', 'page' => $page,
            'fetched' => count($rows)]);
        if (count($batch) < 100) {
            $meta['complete'] = true; $save($page, $rows, true); break;
        }
        $save($page, $rows, false);
        usleep(150000);
    }
    if (!$meta['complete'] && !$meta['partial']) {
        $meta['partial'] = true; $meta['reason'] = 'max_pages'; $meta['page'] = $lastPage;
        $save($lastPage, $rows, false);
    }
    return $rows;
}

/** نرمال‌سازی امن عنوان/پسوند برای تطبیقِ «کد:ایکس» در انتهای عنوان */
function suffixTextNormalize(string $text): string {
    $text = html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    if (function_exists('persianToEnglish')) $text = persianToEnglish($text);
    $text = str_replace(['ي', 'ى', 'ك', 'ة', 'ۀ', 'أ', 'إ', 'ؤ', '：'],
                        ['ی', 'ی', 'ک', 'ه', 'ه', 'ا', 'ا', 'و', ':'], $text);
    /* فاصلهٔ معمولی و نیم‌فاصله برای این گزارش یکی هستند. */
    $text = preg_replace('~[\x{200c}\x{200d}\x{200e}\x{200f}\x{00a0}\x{feff}]~u', ' ', $text);
    $text = preg_replace('~[\x{064B}-\x{065F}\x{0670}]~u', '', $text);
    $text = preg_replace('~\s*([()\[\]:])\s*~u', '$1', $text);
    $text = preg_replace('~\s+~u', ' ', trim($text));
    return function_exists('mb_strtolower') ? mb_strtolower($text, 'UTF-8') : strtolower($text);
}

/** آیا عنوان دقیقاً با پسوندِ پروفایل تمام می‌شود؟ (نه صرفاً شامل آن باشد) */
function suffixMatches(string $title, string $suffix): bool {
    $t = suffixTextNormalize($title); $x = suffixTextNormalize($suffix);
    if ($x === '' || $t === '') return false;
    $candidates = [$x];
    /* اگر تنظیم فقط «کد:۱» باشد، شکل رایجِ «(کد:۱)» هم معتبر است و برعکس. */
    $first = $x[0] ?? ''; $last = substr($x, -1);
    if (($first === '(' && $last === ')') || ($first === '[' && $last === ']')) {
        $bare = trim(substr($x, 1, -1));
        if ($bare !== '') $candidates[] = $bare;
    } else {
        $candidates[] = '(' . $x . ')';
        $candidates[] = '[' . $x . ']';
    }
    foreach (array_unique($candidates) as $candidate) {
        $n = function_exists('mb_strlen') ? mb_strlen($candidate, 'UTF-8') : strlen($candidate);
        $tn = function_exists('mb_strlen') ? mb_strlen($t, 'UTF-8') : strlen($t);
        if ($n > 0 && $tn >= $n) {
            $tail = function_exists('mb_substr')
                ? mb_substr($t, $tn - $n, $n, 'UTF-8') : substr($t, -$n);
            if ($tail === $candidate) return true;
        }
    }
    return false;
}

/** دستهٔ شمارندهٔ وضعیتِ یک محصول مقصد */
function suffixStatusBucket(array $row, string $target): string {
    if ($target === 'bsl') {
        $st = (int)($row['status'] ?? 0);
        if ($st === 2976) return 'approved';
        if ($st === 3567) return 'rejected';
        if ($st === 3568) return 'pending';
        if ($st === 4184) return 'archived';
        return 'inactive';
    }
    $ws = (string)($row['wstatus'] ?? '');
    if ($ws === 'publish') return 'approved';
    if ($ws === 'pending') return 'pending';
    if ($ws === 'trash') return 'archived';
    return 'inactive';
}

/**
 * آمار هر پسوند را می‌سازد.
 * وضعیت‌های باسلام: 2976 فعال/تأییدشده · 3567 تأیید نشده ·
 * 3568 در انتظار · 3790 غیرفعال · 4184 بایگانی
 *
 * v10.128: هر محصول فقط یک‌بار و با بلندترین پسوند به یک پروفایل نسبت داده
 * می‌شود؛ در صورت نبودن پسوند، دفترچهٔ شناسه fallback است و بقیه در misc می‌آیند.
 */
function suffixReport(array $cn, string $target, ?array $cp = null): array {
    $profs = suffixProfiles();
    if (!$profs) return ['ok' => false, 'error' => 'هیچ پروفایلی پسوند عنوان ندارد'];

    $wanted = [];
    foreach ($profs as $p) {
        if ($target === 'both' || $p['target'] === 'both' || $p['target'] === $target) $wanted[] = $p;
    }
    if (!$wanted) return ['ok' => false, 'error' => 'هیچ پروفایلی با پسوند برای این مقصد نیست'];

    /* پسوندهای هم‌پوشان: «فروشگاه الف» باید قبل از «الف» امتحان شود. */
    usort($wanted, function ($a, $b) {
        return mb_strlen(suffixTextNormalize((string)$b['suffix']), 'UTF-8')
            <=> mb_strlen(suffixTextNormalize((string)$a['suffix']), 'UTF-8');
    });
    suffixProgress(['log_add' => ['🔎 ' . count($wanted) . ' پروفایل با پسوند پیدا شد']]);

    $fetchMeta = [];
    if ($target === 'bsl') {
        $tk = (string)($cn['basalam']['token'] ?? '');
        $vid = (int)($cn['basalam']['vendor_id'] ?? 0);
        if ($tk === '' || $vid <= 0) return ['ok' => false, 'error' => 'تنظیمات باسلام ناقص'];
        $rows = suffixFetchBsl($tk, $vid, 80, $cp, $fetchMeta);
    } else {
        $w = $cn['woocommerce'] ?? [];
        if (empty($w['store_url'])) return ['ok' => false, 'error' => 'تنظیمات ووکامرس ناقص'];
        $rows = suffixFetchWoo($w, 80, $cp, $fetchMeta);
    }
    if (!empty($fetchMeta['partial']) || suffixStopRequested()) {
        $stopped = !empty($fetchMeta['stopped']) || suffixStopRequested();
        return ['ok' => false, 'stopped' => $stopped, 'partial' => true,
                'error' => $stopped ? 'گزارش توسط کاربر متوقف شد'
                    : ('برداشت ناقص ماند در صفحهٔ ' . (int)($fetchMeta['page'] ?? 0)
                       . ($fetchMeta['error'] !== '' ? ': ' . $fetchMeta['error'] : ''))];
    }
    /* مقصد خالی، اگر برداشت واقعاً کامل شده باشد، گزارش معتبرِ صفر است. */
    if (!$rows && empty($fetchMeta['complete'])) return ['ok' => false, 'partial' => true,
        'error' => 'هیچ محصولی از مقصد دریافت نشد و کامل‌بودنِ برداشت تأیید نشد'];

    suffixProgress(['log_add' => ['⚖️ تفکیک بر اساس پسوند (کد:ایکس)...'],
        'phase' => 'match', 'current' => 0, 'total' => count($rows), 'remote' => count($rows),
        'checkpoint' => ['target' => $target, 'phase' => 'match', 'page' => (int)($cp['page'] ?? 0),
            'rows' => $rows, 'notify' => !empty($cp['notify']),
            'started_at' => (int)($cp['started_at'] ?? time())]]);

    // v8.65: عنوانِ تغییرنام‌داده‌شده با شناسهٔ ثبت‌شده هم قابل نسبت‌دادن است.
    $sfxIdMap = remoteMapById($target === 'bsl' ? 'bsl' : 'woo');
    $sfxKeyOwner = [];
    foreach (loadProfiles() as $pk => $pv) {
        foreach (profileOrderedProducts($pv, null, false) as $pp) {
            $kk = trim((string)($pp['key'] ?? ''));
            if ($kk !== '') $sfxKeyOwner[$kk] = $pk;
        }
    }
    $wantedIndex = [];
    foreach ($wanted as $wi => $p) $wantedIndex[(string)$p['key']] = $wi;
    $counts = [];
    foreach ($wanted as $wi => $p) $counts[$wi] = ['approved' => 0, 'rejected' => 0,
        'pending' => 0, 'inactive' => 0, 'archived' => 0];
    $claimed = []; $assigned = []; $byIdTotal = 0; $bySuffixTotal = 0;

    foreach ($rows as $i => $r) {
        if (suffixStopRequested()) {
            return ['ok' => false, 'stopped' => true, 'partial' => true,
                    'error' => 'گزارش توسط کاربر متوقف شد'];
        }
        $which = -1; $method = ''; $matchedSuffix = '';
        foreach ($wanted as $wi => $p) {
            if (suffixMatches((string)($r['title'] ?? ''), (string)$p['suffix'])) {
                $which = $wi; $method = 'suffix'; $matchedSuffix = (string)$p['suffix'];
                break;
            }
        }
        if ($which < 0) {
            $rid = (int)($r['id'] ?? 0);
            $owner = $rid > 0 ? (string)($sfxKeyOwner[$sfxIdMap[$rid] ?? ''] ?? '') : '';
            if ($owner !== '' && isset($wantedIndex[$owner])) {
                $which = (int)$wantedIndex[$owner]; $method = 'id';
                $matchedSuffix = (string)($wanted[$which]['suffix'] ?? '');
                $byIdTotal++;
            }
        }
        if ($which >= 0) {
            $claimed[$i] = true; $assigned[$i] = $which;
            if ($method === 'suffix') $bySuffixTotal++;
            $bucket = suffixStatusBucket($r, $target);
            $counts[$which][$bucket]++;
        }
        if (($i + 1) % 100 === 0 || $i === count($rows) - 1) {
            suffixProgress(['current' => $i + 1, 'total' => count($rows),
                'checkpoint' => ['target' => $target, 'phase' => 'match',
                    'page' => (int)($cp['page'] ?? 0), 'rows' => $rows,
                    'notify' => !empty($cp['notify']), 'started_at' => (int)($cp['started_at'] ?? time())]]);
        }
    }

    $out = [];
    foreach ($wanted as $wi => $p) {
        $c = $counts[$wi]; $total = array_sum($c); $pct = [];
        foreach ($c as $k => $v) $pct[$k] = $total > 0 ? round($v / $total * 100, 1) : 0.0;
        $out[] = ['key' => $p['key'], 'name' => $p['name'], 'suffix' => $p['suffix'],
                  'total' => $total, 'counts' => $c, 'pct' => $pct];
        suffixProgress(['log_add' => ['• ' . $p['name'] . ' («' . $p['suffix'] . '»): ' . $total . ' محصول']]);
    }
    $misc = [];
    foreach ($rows as $i => $r) {
        if (isset($claimed[$i])) continue;
        $misc[] = ['id' => (int)($r['id'] ?? 0), 'title' => (string)($r['title'] ?? ''),
                   'status' => $target === 'bsl' ? (int)($r['status'] ?? 0) : '',
                   'wstatus' => $target === 'woo' ? (string)($r['wstatus'] ?? '') : ''];
    }
    $unmatched = count($misc);
    if ($byIdTotal > 0) suffixProgress(['log_add' => ['🔗 ' . $byIdTotal
        . ' محصول با شناسهٔ ثبت‌شده به پروفایلش وصل شد (پسوند در عنوانشان نبود)']]);
    if ($unmatched > 0) suffixProgress(['log_add' => ['🗂 متفرقه‌ها: ' . $unmatched . ' محصول در جدول گزارش می‌شود']]);
    $rep = ['ok' => true, 'target' => $target, 'remote_total' => count($rows),
            'unmatched' => $unmatched, 'misc_total' => $unmatched,
            'misc' => $misc, 'matched_by_id' => $byIdTotal, 'matched_by_suffix' => $bySuffixTotal, 'profiles' => $out];
    return $rep;
}

/** متن گزارش برای پیام‌رسان‌ها */
function suffixReportMsg(array $rep): string {
    $lbl = ($rep['target'] ?? '') === 'bsl' ? 'باسلام' : 'ووکامرس';
    $lines = ['📊 گزارش محصولات بر اساس پروفایل — ' . $lbl,
              'کل محصولات مقصد: ' . (int)($rep['remote_total'] ?? 0)];
    foreach (($rep['profiles'] ?? []) as $p) {
        $c = $p['counts']; $q = $p['pct'];
        $lines[] = '━━━━━━━━━━';
        $lines[] = '🏷 ' . $p['name'] . '  («' . $p['suffix'] . '»)';
        $lines[] = 'ثبت‌شده: ' . $p['total'];
        if ($p['total'] > 0) {
            $lines[] = '✅ تأیید شده: ' . $c['approved'] . ' (' . $q['approved'] . '٪)';
            if ($c['rejected'] > 0) $lines[] = '❌ تأیید نشده: ' . $c['rejected'] . ' (' . $q['rejected'] . '٪)';
            if ($c['pending']  > 0) $lines[] = '⏳ در انتظار: ' . $c['pending'] . ' (' . $q['pending'] . '٪)';
            if ($c['inactive'] > 0) $lines[] = '⏸ غیرفعال: ' . $c['inactive'] . ' (' . $q['inactive'] . '٪)';
            if ($c['archived'] > 0) $lines[] = '🗑 بایگانی: ' . $c['archived'] . ' (' . $q['archived'] . '٪)';
        }
    }
    if ((int)($rep['unmatched'] ?? 0) > 0) {
        $lines[] = '━━━━━━━━━━';
        $lines[] = '🗂 متفرقه‌ها (بدون پسوند/شناسه): ' . (int)$rep['unmatched'];
        $shown = 0;
        foreach ((array)($rep['misc'] ?? []) as $m) {
            if ($shown++ >= 8) break;
            $lines[] = '  • ' . (string)($m['title'] ?? '');
        }
        if ((int)($rep['unmatched'] ?? 0) > 8) $lines[] = '  … و ' . ((int)$rep['unmatched'] - 8) . ' مورد دیگر';
    }
    return implode("\n", $lines);
}


/**
 * v10.114: آمار خلاصهٔ هر پروفایل — محلی (استخراج‌شده) × ووکامرس × هر غرفهٔ باسلام
 * بدون وابستگی اجباری به پسوند عنوان؛ از remote_map + تطبیق عنوان استفاده می‌کند.
 */
function profileLocalCount(array $profile): int {
    $raw = $profile['products'] ?? [];
    if (!is_array($raw) || !$raw) return 0;
    $order = $profile['productsOrder'] ?? [];
    if (is_array($order) && $order) {
        $map = [];
        foreach ($raw as $entry) {
            if (is_array($entry) && count($entry) >= 2 && is_string($entry[0])) {
                $map[$entry[0]] = true;
            }
        }
        if ($map) {
            $n = 0;
            foreach ($order as $k) if (isset($map[$k])) $n++;
            return $n > 0 ? $n : count($map);
        }
    }
    $n = 0;
    foreach ($raw as $entry) {
        if (is_array($entry) && count($entry) >= 2 && is_string($entry[0]) && is_array($entry[1] ?? null)) $n++;
        elseif (is_array($entry) && (isset($entry['title']) || isset($entry['name']) || isset($entry['price']))) $n++;
    }
    return $n;
}

function profileStatsSummary(array $cn, ?array $cp = null): array {
    @set_time_limit(0);
    $sumCp = is_array($cp) ? $cp : [];
    $sumTarget = in_array((string)($sumCp['target'] ?? ''), ['summary', 'all'], true)
        ? (string)$sumCp['target'] : 'summary';
    $sumStartedAt = (int)($sumCp['started_at'] ?? time());
    suffixProgress(['log_add' => ['📊 ' . ($sumCp ? 'ادامهٔ ساخت جدول خلاصه از checkpoint' : 'ساخت جدول خلاصهٔ پروفایل‌ها') . '...'],
        'phase' => 'start', 'checkpoint' => ['target' => $sumTarget,
            'phase' => 'local', 'woo_rows' => is_array($sumCp['woo_rows'] ?? null) ? $sumCp['woo_rows'] : [],
            'woo_done' => !empty($sumCp['woo_done']),
            'woo_page' => (int)($sumCp['woo_page'] ?? 0),
            'woo_complete' => !empty($sumCp['woo_complete']),
            'shops' => is_array($sumCp['shops'] ?? null) ? $sumCp['shops'] : [],
            'shop_pages' => is_array($sumCp['shop_pages'] ?? null) ? $sumCp['shop_pages'] : [],
            'shop_done' => is_array($sumCp['shop_done'] ?? null) ? $sumCp['shop_done'] : [],
            'started_at' => $sumStartedAt, 'notify' => !empty($sumCp['notify'])]]);

    $profiles = loadProfiles();
    if (!$profiles) {
        return ['ok' => false, 'error' => 'هیچ پروفایلی ذخیره نشده', 'kind' => 'summary'];
    }

    // --- meta columns ---
    $shops = function_exists('bslAllShops') ? bslAllShops($cn) : [];
    $shopMeta = [];
    foreach ($shops as $sh) {
        if (!is_array($sh)) continue;
        $vid = (int)($sh['vendor_id'] ?? 0);
        if ($vid <= 0) continue;
        $shopMeta[] = [
            'vendor_id' => $vid,
            'name' => (string)($sh['shop_name'] ?? ($sh['name'] ?? ('غرفه ' . $vid))),
            'is_default' => !empty($sh['is_default']),
            'token' => (string)($sh['token'] ?? ''),
        ];
    }

    // --- local profile rows ---
    $rows = [];
    $keyOwner = []; // product key => profile key
    $titleOwner = []; // bare title => profile key (first wins)
    $suffixes = [];
    foreach ($profiles as $pk => $pv) {
        if (suffixStopRequested()) return ['ok' => false, 'stopped' => true, 'partial' => true,
            'error' => 'گزارش توسط کاربر متوقف شد', 'kind' => 'summary'];
        if (!is_array($pv)) continue;
        $name = (string)($pv['name'] ?? $pk);
        $sfx = trim((string)($pv['titleSuffix'] ?? ''));
        if ($sfx !== '') $suffixes[] = $sfx;
        $local = profileLocalCount($pv);
        $sc = $pv['syncConfig'] ?? [];
        $rows[$pk] = [
            'key' => (string)$pk,
            'name' => $name,
            'suffix' => $sfx,
            'local' => $local,
            'sync_on' => !empty($sc['enabled']),
            'sync_target' => (string)($sc['target'] ?? ''),
            'woo' => 0,
            'woo_by_map' => 0,
            'woo_by_title' => 0,
            'shops' => [], // vid => count
            'shops_by_map' => [],
            'shops_by_title' => [],
        ];
        foreach ($shopMeta as $sm) {
            $vid = (int)$sm['vendor_id'];
            $rows[$pk]['shops'][$vid] = 0;
            $rows[$pk]['shops_by_map'][$vid] = 0;
            $rows[$pk]['shops_by_title'][$vid] = 0;
        }
        // index keys + bare titles
        try {
            foreach (profileOrderedProducts($pv, null, false) as $pp) {
                if (!is_array($pp)) continue;
                $kk = trim((string)($pp['key'] ?? ''));
                if ($kk !== '' && !isset($keyOwner[$kk])) $keyOwner[$kk] = (string)$pk;
                $t = (string)($pp['title'] ?? ($pp['name'] ?? ''));
                if ($t === '' && $sfx !== '') continue;
                $bare = function_exists('matrixBareTitle')
                    ? matrixBareTitle($t, $sfx !== '' ? [$sfx] : [])
                    : reconNormTitle(function_exists('stripProductCode') ? stripProductCode($t) : $t);
                if ($bare !== '' && !isset($titleOwner[$bare])) $titleOwner[$bare] = (string)$pk;
            }
        } catch (Throwable $e) {
            // fallback: raw products
            foreach ((array)($pv['products'] ?? []) as $entry) {
                $prod = null; $kk = '';
                if (is_array($entry) && count($entry) >= 2 && is_string($entry[0])) {
                    $kk = $entry[0]; $prod = $entry[1];
                } elseif (is_array($entry)) {
                    $prod = $entry; $kk = (string)($entry['key'] ?? '');
                }
                if ($kk !== '' && !isset($keyOwner[$kk])) $keyOwner[$kk] = (string)$pk;
                if (!is_array($prod)) continue;
                $t = (string)($prod['title'] ?? ($prod['name'] ?? ''));
                $bare = reconNormTitle(function_exists('stripProductCode') ? stripProductCode($t) : $t);
                if ($bare !== '' && !isset($titleOwner[$bare])) $titleOwner[$bare] = (string)$pk;
            }
        }
    }
    /* عنوان‌های هم‌پوشان باید همیشه با پسوندِ بلندتر به پروفایل برسند. */
    $suffixProfileOrder = array_keys($rows);
    usort($suffixProfileOrder, function ($a, $b) use ($rows) {
        $sa = suffixTextNormalize((string)($rows[$a]['suffix'] ?? ''));
        $sb = suffixTextNormalize((string)($rows[$b]['suffix'] ?? ''));
        return mb_strlen($sb, 'UTF-8') <=> mb_strlen($sa, 'UTF-8');
    });
    suffixProgress(['log_add' => ['✅ ' . count($rows) . ' پروفایل · ' . count($keyOwner) . ' کلید محصول'], 'phase' => 'local',
        'checkpoint' => ['target' => $sumTarget, 'phase' => 'local',
            'woo_rows' => is_array($sumCp['woo_rows'] ?? null) ? $sumCp['woo_rows'] : [],
            'woo_done' => !empty($sumCp['woo_done']),
            'shops' => is_array($sumCp['shops'] ?? null) ? $sumCp['shops'] : [],
            'started_at' => $sumStartedAt, 'notify' => !empty($sumCp['notify'])]]);

    // --- remote_map ownership (woo + bsl default shard) ---
    $map = function_exists('remoteMapLoad') ? remoteMapLoad() : ['woo' => [], 'bsl' => []];
    foreach ((array)($map['woo'] ?? []) as $k => $v) {
        if (!is_array($v)) continue;
        $owner = trim((string)($v['profile'] ?? ''));
        if ($owner === '' || !isset($rows[$owner])) {
            $owner = $keyOwner[(string)$k] ?? '';
        }
        if ($owner !== '' && isset($rows[$owner])) {
            $rows[$owner]['woo']++;
            $rows[$owner]['woo_by_map']++;
        }
    }
    // basalam map is default shop only in main map - count under default vendor if known
    $defVid = 0;
    foreach ($shopMeta as $sm) {
        if (!empty($sm['is_default'])) { $defVid = (int)$sm['vendor_id']; break; }
    }
    if ($defVid <= 0 && $shopMeta) $defVid = (int)$shopMeta[0]['vendor_id'];
    foreach ((array)($map['bsl'] ?? []) as $k => $v) {
        if (!is_array($v)) continue;
        $owner = trim((string)($v['profile'] ?? ''));
        if ($owner === '' || !isset($rows[$owner])) {
            $owner = $keyOwner[(string)$k] ?? '';
        }
        if ($owner !== '' && isset($rows[$owner]) && $defVid > 0) {
            $rows[$owner]['shops'][$defVid] = (int)($rows[$owner]['shops'][$defVid] ?? 0) + 1;
            $rows[$owner]['shops_by_map'][$defVid] = (int)($rows[$owner]['shops_by_map'][$defVid] ?? 0) + 1;
        }
    }

    // --- fetch live destinations for title match + fill gaps ---
    $w = $cn['woocommerce'] ?? [];
    $wooRows = is_array($sumCp['woo_rows'] ?? null) ? array_values(array_filter($sumCp['woo_rows'], 'is_array')) : [];
    $wooDone = !empty($sumCp['woo_done']);
    $wooErr = (string)($sumCp['woo_error'] ?? '');
    suffixProgress(['log_add' => [$wooDone ? '↻ ووکامرس از checkpoint خوانده شد' : '📥 دریافت ووکامرس...'], 'phase' => 'woo']);
    if (!$wooDone) {
        $wooMeta = [];
        try {
            if (!empty($w['store_url'])) {
                $wooFetchCp = ['target' => 'woo', 'phase' => 'fetch', 'page' => (int)($sumCp['woo_page'] ?? 0),
                    'rows' => $wooRows, 'started_at' => $sumStartedAt, 'notify' => !empty($sumCp['notify'])];
                $wooContext = ['target' => $sumTarget, 'phase' => 'woo_fetch', 'woo_rows' => $wooRows,
                    'woo_done' => false, 'shops' => is_array($sumCp['shops'] ?? null) ? $sumCp['shops'] : [],
                    'shop_pages' => is_array($sumCp['shop_pages'] ?? null) ? $sumCp['shop_pages'] : [],
                    'shop_done' => is_array($sumCp['shop_done'] ?? null) ? $sumCp['shop_done'] : [],
                    'started_at' => $sumStartedAt, 'notify' => !empty($sumCp['notify'])];
                $wooRows = function_exists('suffixFetchWoo')
                    ? suffixFetchWoo($w, 80, $wooFetchCp, $wooMeta, 'summary', $wooContext)
                    : (function_exists('reconFetchWoo') ? reconFetchWoo($w) : []);
                if (empty($wooMeta['complete']) && function_exists('suffixFetchWoo')) {
                    $wooErr = 'برداشت ناقص در صفحهٔ ' . (int)($wooMeta['page'] ?? 0)
                        . ($wooMeta['error'] !== '' ? ': ' . $wooMeta['error'] : '');
                }
            } else {
                $wooErr = 'تنظیمات ووکامرس ناقص';
            }
        } catch (Throwable $e) {
            $wooErr = $e->getMessage();
        }
        $wooDone = $wooErr === '' && (empty($wooMeta) || !empty($wooMeta['complete']));
        $sumCp['woo_rows'] = $wooRows; $sumCp['woo_done'] = $wooDone;
        $sumCp['woo_error'] = $wooErr; $sumCp['woo_page'] = (int)($wooMeta['page'] ?? ($sumCp['woo_page'] ?? 0));
        $sumCp['woo_complete'] = $wooDone;
        suffixProgress(['checkpoint' => ['target' => $sumTarget, 'phase' => $wooDone ? 'woo' : 'woo_fetch',
            'woo_rows' => $wooRows, 'woo_done' => $wooDone, 'woo_complete' => $wooDone,
            'woo_page' => $sumCp['woo_page'], 'woo_error' => $wooErr,
            'shops' => is_array($sumCp['shops'] ?? null) ? $sumCp['shops'] : [],
            'shop_pages' => is_array($sumCp['shop_pages'] ?? null) ? $sumCp['shop_pages'] : [],
            'shop_done' => is_array($sumCp['shop_done'] ?? null) ? $sumCp['shop_done'] : [],
            'started_at' => $sumStartedAt, 'notify' => !empty($sumCp['notify'])]]);
        if (!$wooDone) return ['ok' => false, 'partial' => true, 'stopped' => suffixStopRequested(),
            'error' => suffixStopRequested() ? 'گزارش توسط کاربر متوقف شد' : ($wooErr ?: 'برداشت ووکامرس کامل نشد'),
            'kind' => 'summary'];
    }
    $wooIdMap = function_exists('remoteMapById') ? remoteMapById('woo') : [];
    $claimedWoo = [];
    foreach ($wooRows as $wr) {
        if (!is_array($wr)) continue;
        $rid = (int)($wr['id'] ?? 0);
        $owner = '';
        if ($rid > 0 && isset($wooIdMap[$rid])) {
            $pk = $wooIdMap[$rid];
            $owner = $keyOwner[$pk] ?? '';
            // also try profile field via reverse map entry
            if ($owner === '' && isset($map['woo'][$pk]['profile'])) {
                $owner = (string)$map['woo'][$pk]['profile'];
            }
        }
        if ($owner === '') {
            $bare = function_exists('matrixBareTitle')
                ? matrixBareTitle((string)($wr['title'] ?? ''), $suffixes)
                : reconNormTitle((string)($wr['title'] ?? ''));
            // suffix match first
            if ($owner === '') {
                foreach ($suffixProfileOrder as $pk) {
            $pr = $rows[$pk];
                    $sfx = (string)($pr['suffix'] ?? '');
                    if ($sfx !== '' && function_exists('suffixMatches') && suffixMatches((string)($wr['title'] ?? ''), $sfx)) {
                        $owner = $pk; break;
                    }
                }
            }
            if ($owner === '' && $bare !== '' && isset($titleOwner[$bare])) {
                $owner = $titleOwner[$bare];
            }
            if ($owner !== '' && isset($rows[$owner])) {
                // only count title match if not already in map count for this profile?
                // Use separate title-only bump when not claimed via map id for this remote id
                if ($rid <= 0 || !isset($claimedWoo[$rid])) {
                    // if map already counted this profile's products globally, title match
                    // still useful for products without map — count as title
                    $rows[$owner]['woo_by_title']++;
                    // if map count is 0-ish for coverage, also ensure total includes title-only
                    // Total woo = max(map, map+title_unique). Simpler: total = by_map + title_only_not_in_map
                    // We don't know if this id was in map; if rid in wooIdMap it was map-path.
                    if (!($rid > 0 && isset($wooIdMap[$rid]))) {
                        $rows[$owner]['woo']++;
                    }
                }
            }
        }
        // map-path already counted from remote_map dump; if map empty but id maps to key:
        if ($owner !== '' && isset($rows[$owner]) && $rid > 0 && isset($wooIdMap[$rid])) {
            // already counted in map dump if entry existed; if map dump missed profile field but keyOwner hit:
            // ensure at least 1 — avoid double: only add if this rid not yet attributed
            if (!isset($claimedWoo[$rid])) {
                // map dump already walked all map entries — if this id is in map, it was counted
                // when profile was set. If counted via keyOwner in dump, OK.
                // If dump used profile field empty and keyOwner fixed — dump already used keyOwner.
                $claimedWoo[$rid] = $owner;
            }
        }
    }
    suffixProgress(['log_add' => ['✅ ووکامرس: ' . count($wooRows) . ' محصول' . ($wooErr !== '' ? ' — ' . $wooErr : '')]]);

    // Recalculate woo totals more cleanly: recount from live + map
    foreach ($rows as $pk => $_) {
        $rows[$pk]['woo'] = 0;
        $rows[$pk]['woo_by_map'] = 0;
        $rows[$pk]['woo_by_title'] = 0;
    }
    $seenWooIds = [];
    // 1) map
    foreach ((array)($map['woo'] ?? []) as $k => $v) {
        if (!is_array($v)) continue;
        $owner = trim((string)($v['profile'] ?? ''));
        if ($owner === '' || !isset($rows[$owner])) $owner = $keyOwner[(string)$k] ?? '';
        if ($owner === '' || !isset($rows[$owner])) continue;
        $id = (int)($v['id'] ?? 0);
        if ($id > 0) {
            if (isset($seenWooIds[$id])) continue;
            $seenWooIds[$id] = true;
        }
        $rows[$owner]['woo']++;
        $rows[$owner]['woo_by_map']++;
    }
    // 2) live title for unmapped
    foreach ($wooRows as $wr) {
        $rid = (int)($wr['id'] ?? 0);
        if ($rid > 0 && isset($seenWooIds[$rid])) continue;
        $owner = '';
        $bare = function_exists('matrixBareTitle')
            ? matrixBareTitle((string)($wr['title'] ?? ''), $suffixes)
            : reconNormTitle((string)($wr['title'] ?? ''));
        foreach ($suffixProfileOrder as $pk) {
            $pr = $rows[$pk];
            $sfx = (string)($pr['suffix'] ?? '');
            if ($sfx !== '' && function_exists('suffixMatches') && suffixMatches((string)($wr['title'] ?? ''), $sfx)) {
                $owner = $pk; break;
            }
        }
        if ($owner === '' && $bare !== '' && isset($titleOwner[$bare])) $owner = $titleOwner[$bare];
        if ($owner === '' || !isset($rows[$owner])) continue;
        if ($rid > 0) $seenWooIds[$rid] = true;
        $rows[$owner]['woo']++;
        $rows[$owner]['woo_by_title']++;
    }

    // --- each basalam shop ---
    $bslErr = '';
    $sN = 0; $sTot = max(1, count($shopMeta));
    foreach ($shopMeta as $sm) {
        if (suffixStopRequested()) return ['ok' => false, 'stopped' => true, 'partial' => true,
            'error' => 'گزارش توسط کاربر متوقف شد', 'kind' => 'summary'];
        $sN++;
        $vid = (int)$sm['vendor_id'];
        $tok = (string)$sm['token'];
        $sname = (string)$sm['name'];
        if ($tok === '') {
            // try default token
            $tok = (string)($cn['basalam']['token'] ?? '');
        }
        suffixProgress([
            'log_add' => ['🏪 غرفه ' . $sN . '/' . $sTot . ' — ' . $sname],
            'phase' => 'bsl', 'cur' => $sN, 'cur_total' => $sTot,
        ]);
        $shopDone = is_array($sumCp['shop_done'] ?? null) && !empty($sumCp['shop_done'][(string)$vid]);
        $savedShopRows = is_array($sumCp['shops'] ?? null) && is_array($sumCp['shops'][(string)$vid] ?? null)
            ? $sumCp['shops'][(string)$vid] : [];
        $remote = array_values(array_filter($savedShopRows, 'is_array'));
        $shopMetaFetch = [];
        try {
            if (!$shopDone && $tok !== '' && $vid > 0) {
                $shopFetchCp = ['target' => 'bsl', 'phase' => 'fetch',
                    'page' => (int)($sumCp['shop_pages'][(string)$vid] ?? 0), 'rows' => $remote,
                    'started_at' => $sumStartedAt, 'notify' => !empty($sumCp['notify'])];
                $shopContext = ['target' => $sumTarget, 'phase' => 'bsl_fetch', 'woo_rows' => $wooRows,
                    'woo_done' => $wooDone, 'woo_page' => (int)($sumCp['woo_page'] ?? 0),
                    'woo_error' => $wooErr, 'shops' => is_array($sumCp['shops'] ?? null) ? $sumCp['shops'] : [],
                    'shop_pages' => is_array($sumCp['shop_pages'] ?? null) ? $sumCp['shop_pages'] : [],
                    'shop_done' => is_array($sumCp['shop_done'] ?? null) ? $sumCp['shop_done'] : [],
                    'shop_index' => $sN, 'started_at' => $sumStartedAt, 'notify' => !empty($sumCp['notify'])];
                $remote = function_exists('suffixFetchBsl')
                    ? suffixFetchBsl($tok, $vid, 80, $shopFetchCp, $shopMetaFetch, 'summary', $shopContext)
                    : (function_exists('reconFetchBsl') ? reconFetchBsl($tok, $vid) : []);
            }
        } catch (Throwable $e) {
            $bslErr .= $sname . ': ' . $e->getMessage() . '; ';
        }
        if (!$shopDone && function_exists('suffixFetchBsl')
            && (empty($shopMetaFetch['complete']) || !empty($shopMetaFetch['partial']))) {
            $bslErr .= $sname . ': برداشت ناقص در صفحهٔ ' . (int)($shopMetaFetch['page'] ?? 0)
                . ($shopMetaFetch['error'] !== '' ? ': ' . $shopMetaFetch['error'] : '') . '; ';
        }
        $sumCp['shops'][(string)$vid] = $remote;
        $sumCp['shop_pages'][(string)$vid] = (int)($shopMetaFetch['page'] ?? ($sumCp['shop_pages'][(string)$vid] ?? 0));
        $sumCp['shop_done'][(string)$vid] = !$bslErr || empty($shopMetaFetch) || !empty($shopMetaFetch['complete']);
        suffixProgress(['checkpoint' => ['target' => $sumTarget, 'phase' => $sumCp['shop_done'][(string)$vid] ? 'bsl' : 'bsl_fetch',
            'woo_rows' => $wooRows, 'woo_done' => $wooDone, 'woo_complete' => $wooDone,
            'woo_page' => (int)($sumCp['woo_page'] ?? 0), 'woo_error' => $wooErr, 'shops' => $sumCp['shops'],
            'shop_pages' => $sumCp['shop_pages'], 'shop_done' => $sumCp['shop_done'], 'shop_index' => $sN,
            'started_at' => $sumStartedAt, 'notify' => !empty($sumCp['notify'])]]);
        if (!$sumCp['shop_done'][(string)$vid] || suffixStopRequested()) return ['ok' => false,
            'stopped' => suffixStopRequested(), 'partial' => true,
            'error' => suffixStopRequested() ? 'گزارش توسط کاربر متوقف شد' : ('برداشت غرفهٔ ' . $sname . ' کامل نشد'),
            'kind' => 'summary'];
        $seenIds = [];
        // map counts for default already applied; for extra shops map is in shards with same 'bsl' keys per shard
        // recount live for this shop
        foreach ($rows as $pk => $_) {
            $rows[$pk]['shops'][$vid] = 0;
            $rows[$pk]['shops_by_map'][$vid] = 0;
            $rows[$pk]['shops_by_title'][$vid] = 0;
        }
        // from remote map if default shop
        if (!empty($sm['is_default']) || $vid === $defVid) {
            foreach ((array)($map['bsl'] ?? []) as $k => $v) {
                if (!is_array($v)) continue;
                $owner = trim((string)($v['profile'] ?? ''));
                if ($owner === '' || !isset($rows[$owner])) $owner = $keyOwner[(string)$k] ?? '';
                if ($owner === '' || !isset($rows[$owner])) continue;
                $id = (int)($v['id'] ?? 0);
                if ($id > 0) {
                    if (isset($seenIds[$id])) continue;
                    $seenIds[$id] = true;
                }
                $rows[$owner]['shops'][$vid]++;
                $rows[$owner]['shops_by_map'][$vid]++;
            }
        }
        // live title
        foreach ($remote as $br) {
            if (!is_array($br)) continue;
            $rid = (int)($br['id'] ?? 0);
            if ($rid > 0 && isset($seenIds[$rid])) continue;
            $owner = '';
            $title = (string)($br['title'] ?? '');
            foreach ($suffixProfileOrder as $pk) {
            $pr = $rows[$pk];
                $sfx = (string)($pr['suffix'] ?? '');
                if ($sfx !== '' && function_exists('suffixMatches') && suffixMatches($title, $sfx)) {
                    $owner = $pk; break;
                }
            }
            if ($owner === '') {
                $bare = function_exists('matrixBareTitle')
                    ? matrixBareTitle($title, $suffixes)
                    : reconNormTitle($title);
                if ($bare !== '' && isset($titleOwner[$bare])) $owner = $titleOwner[$bare];
            }
            if ($owner === '' || !isset($rows[$owner])) continue;
            if ($rid > 0) $seenIds[$rid] = true;
            $rows[$owner]['shops'][$vid]++;
            $rows[$owner]['shops_by_title'][$vid]++;
        }
        suffixProgress(['log_add' => ['  ✓ ' . $sname . ': ' . count($remote) . ' محصول']]);
    }

    // totals + coverage
    $list = array_values($rows);
    usort($list, function ($a, $b) {
        return ((int)$b['local'] <=> (int)$a['local']) ?: strcmp((string)$a['name'], (string)$b['name']);
    });
    $totLocal = 0; $totWoo = 0; $totShops = [];
    foreach ($shopMeta as $sm) $totShops[(int)$sm['vendor_id']] = 0;
    foreach ($list as &$r) {
        $totLocal += (int)$r['local'];
        $totWoo += (int)$r['woo'];
        $cov = [];
        if ((int)$r['local'] > 0) {
            $cov['woo'] = round(min(100, ((int)$r['woo'] / max(1, (int)$r['local'])) * 100), 1);
        } else {
            $cov['woo'] = 0.0;
        }
        foreach ($shopMeta as $sm) {
            $vid = (int)$sm['vendor_id'];
            $sc = (int)($r['shops'][$vid] ?? 0);
            $totShops[$vid] = ($totShops[$vid] ?? 0) + $sc;
            $cov['s' . $vid] = ((int)$r['local'] > 0)
                ? round(min(100, ($sc / max(1, (int)$r['local'])) * 100), 1) : 0.0;
        }
        $r['coverage'] = $cov;
        // status chip
        $r['status'] = 'empty';
        if ((int)$r['local'] <= 0) $r['status'] = 'empty';
        elseif ((int)$r['woo'] >= (int)$r['local'] * 0.95) {
            $allShopsOk = true;
            foreach ($shopMeta as $sm) {
                $vid = (int)$sm['vendor_id'];
                if ((int)($r['shops'][$vid] ?? 0) < (int)$r['local'] * 0.9) { $allShopsOk = false; break; }
            }
            $r['status'] = $allShopsOk || !$shopMeta ? 'ok' : 'partial';
        } elseif ((int)$r['woo'] > 0 || array_sum(array_map('intval', $r['shops'] ?? [])) > 0) {
            $r['status'] = 'partial';
        } else {
            $r['status'] = 'local_only';
        }
    }
    unset($r);

    $out = [
        'ok' => true,
        'kind' => 'summary',
        'generated_at' => time(),
        'profiles' => $list,
        'shops' => array_map(function ($s) {
            return ['vendor_id' => $s['vendor_id'], 'name' => $s['name'], 'is_default' => !empty($s['is_default'])];
        }, $shopMeta),
        'totals' => [
            'profiles' => count($list),
            'local' => $totLocal,
            'woo' => $totWoo,
            'shops' => $totShops,
            'woo_remote' => count($wooRows),
        ],
        'woo_error' => $wooErr,
        'bsl_error' => $bslErr,
    ];
    suffixProgress([
        'log_add' => [
            '✅ خلاصه آماده: ' . count($list) . ' پروفایل · محلی ' . $totLocal . ' · WC ' . $totWoo,
        ],
        'phase' => 'done',
    ]);
    return $out;
}

function profileStatsSummaryMsg(array $rep): string {
    $lines = ['📊 آمار خلاصهٔ پروفایل‌ها v' . APP_VERSION];
    $t = $rep['totals'] ?? [];
    $lines[] = 'پروفایل‌ها: ' . (int)($t['profiles'] ?? 0)
        . ' · محلی: ' . (int)($t['local'] ?? 0)
        . ' · ووکامرس: ' . (int)($t['woo'] ?? 0);
    foreach ((array)($rep['shops'] ?? []) as $s) {
        $vid = (int)($s['vendor_id'] ?? 0);
        $lines[] = '🏪 ' . (string)($s['name'] ?? $vid) . ': ' . (int)(($t['shops'][$vid] ?? 0));
    }
    foreach (array_slice((array)($rep['profiles'] ?? []), 0, 15) as $p) {
        $lines[] = '• ' . (string)($p['name'] ?? '') . ' — محلی ' . (int)($p['local'] ?? 0)
            . ' | WC ' . (int)($p['woo'] ?? 0);
    }
    return implode("\n", $lines);
}

/* v8.49: گزارش زندهٔ مغایرت‌گیری */
function reconProgress(array $patch): void {
    $cur = localTaskStateRead(RECON_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $line) {
            $log[] = ['t' => time(), 'm' => (string)$line];
        }
        if (count($log) > 300) $log = array_slice($log, -300);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log;
    $cur['ts'] = time();
    writeProgress(RECON_PROGRESS_FILE, $cur);
}

function reconStopRequested(): bool {
    return is_file(RECON_STOP_FILE) || (defined('SYNC_MATRIX_STOP_FILE') && is_file(SYNC_MATRIX_STOP_FILE));
}
function reconStopClear(): void { @unlink(RECON_STOP_FILE); }

function reconProgressRead(): array {
    return localTaskStateRead(RECON_PROGRESS_FILE, ['running' => false, 'done' => false, 'log' => []]);
}

/**
 * فهرست محصولات نهاییِ پروفایل‌ها برای مقایسه با مقصد.
 *
 * v8.64: تا اینجا فقط پروفایل‌هایی خوانده می‌شدند که «همگام‌سازی دوره‌ای»
 * آن‌ها روشن بود. کسی که محصولاتش را دستی می‌فرستد هیچ‌وقت این تیک را
 * نمی‌زند، پس مغایرت‌گیری برایش با پیام «هیچ پروفایلی پیدا نشد» تمام
 * می‌شد — دقیقاً همان «کار نمی‌کند». حالا $allProfiles=true همهٔ
 * پروفایل‌ها را می‌خواند.
 *
 * $stats اگر داده شود، شرح تفکیکی هر پروفایل داخلش نوشته می‌شود تا در
 * گزارش زنده دیده شود.
 */
function reconExpected(string $target, bool $allProfiles = false, ?array &$stats = null): array {
    $out = [];
    $stats = ['profiles' => [], 'used' => 0, 'skipped' => 0, 'no_products' => 0, 'by_key' => []];
    foreach (loadProfiles() as $key => $profile) {
        $sc = $profile['syncConfig'] ?? [];
        $name = (string)($profile['name'] ?? $key);
        $syncOn = !empty($sc['enabled']);
        $t = (string)($sc['target'] ?? 'woo');
        $targetOk = ($t === 'both' || $t === $target);
        if (!$allProfiles) {
            if (!$syncOn)    { $stats['skipped']++; $stats['profiles'][] = ['name' => $name, 'n' => 0, 'why' => 'همگام‌سازی دوره‌ای خاموش']; continue; }
            if (!$targetOk)  { $stats['skipped']++; $stats['profiles'][] = ['name' => $name, 'n' => 0, 'why' => 'مقصدش این نیست']; continue; }
        }
        $n = 0; $noPrice = 0;
        /* v10.112: قیمت انتظاری مقصد = final_price پروفایل + destAdjust مقصد
           (قبلاً فقط پروفایل بود → احساس «قیمت مبدأ بدون تغییر به WC می‌رود»
           وقتی فقط dest adjust تنظیم شده بود در recon دیده نمی‌شد) */
        static $__destCfgCache = [];
        $__destKey = ($target === 'woo') ? 'woocommerce' : 'basalam';
        if (!isset($__destCfgCache[$__destKey])) {
            $__destCfgCache[$__destKey] = function_exists('destPriceCfg')
                ? destPriceCfg(loadConnections(), $__destKey)
                : ['mode' => 'none', 'val' => 0, 'round' => 0];
        }
        $__dcfg = $__destCfgCache[$__destKey];
        foreach (profileOrderedProducts($profile) as $p) {
            // v8.65: همان رکورد، این بار با کلید محصول — برای تطبیق با شناسهٔ مقصد
            $pk = trim((string)($p['key'] ?? ''));
            $price = (int)($p['final_price'] ?? 0);
            if ($price > 0 && ($__dcfg['mode'] ?? 'none') !== 'none' && function_exists('destAdjustPrice')) {
                $price = destAdjustPrice($price, $__dcfg);
            }
            if ($pk !== '' && !isset($stats['by_key'][$pk])) {
                $stats['by_key'][$pk] = ['price' => $price,
                                         'profile' => $name, 'profile_key' => (string)$key,
                                         'key' => $pk,
                                         'profile_price' => (int)($p['final_price'] ?? 0)];
            }
            $title = reconNormTitle((string)($p['title'] ?? ''));
            if ($title === '') continue;
            if ($price <= 0) $noPrice++;
            $n++;
            if (isset($out[$title]) && (int)$out[$title]['price'] > 0) continue;
            $out[$title] = ['price' => $price, 'profile' => $name,
                            'profile_key' => (string)$key,
                            'key' => (string)($p['key'] ?? ''),
                            'profile_price' => (int)($p['final_price'] ?? 0)];
        }
        if ($n === 0) { $stats['no_products']++; $stats['profiles'][] = ['name' => $name, 'n' => 0, 'why' => 'محصولی ندارد']; continue; }
        $stats['used']++;
        $stats['profiles'][] = ['name' => $name, 'n' => $n, 'no_price' => $noPrice,
                                'why' => $syncOn ? '' : 'بدون همگام‌سازی دوره‌ای'];
    }
    return $out;
}

/** همهٔ محصولات ووکامرس */
/**
 * v10.115: واکشی محصولات ووکامرس از دیتابیس محلی (اتصال مستقیم).
 * وقتی اسکرپر داخل همان وردپرس/ووکامرس لود شود، به‌جای REST API صدها برابر سریع‌تر است.
 * @return list<array{id:int,title:string,price:int,status:string}>
 */
function reconFetchWooDirect(int $max = 0, ?array &$meta = null): array {
    $meta = ['complete' => false, 'partial' => false, 'stopped' => false, 'reason' => '', 'page' => 0];
    $cur = reconFetchCursorLoad('woo', 0);
    $rows = array_values(array_filter((array)($cur['rows'] ?? []), 'is_array'));
    $startPage = max(1, (int)($cur['page'] ?? 0) + 1);
    $limit = $max > 0 ? $max : 50000;
    if (!function_exists('wc_get_products') && !function_exists('get_posts')) {
        $meta['partial'] = true; $meta['reason'] = 'unavailable';
        return $rows;
    }
    if (function_exists('wc_get_products')) {
        $per = 200; $got = 0; $page = $startPage;
        while ($got < $limit) {
            if (reconStopRequested()) {
                $meta['partial'] = true; $meta['stopped'] = true; $meta['reason'] = 'stopped';
                $meta['page'] = max(0, $page - 1); break;
            }
            $batch = wc_get_products([
                'limit' => $per, 'page' => $page,
                'status' => ['publish', 'draft', 'pending', 'private'],
                'orderby' => 'ID', 'order' => 'ASC', 'return' => 'objects']);
            if (!is_array($batch)) {
                $meta['partial'] = true; $meta['reason'] = 'http'; $meta['page'] = $page; break;
            }
            if (!$batch) { $meta['complete'] = true; $meta['page'] = max(0, $page - 1); break; }
            $pageRows = [];
            foreach ($batch as $pr) {
                if (reconStopRequested()) {
                    $meta['partial'] = true; $meta['stopped'] = true; $meta['reason'] = 'stopped'; break 2;
                }
                if (!is_object($pr) || !method_exists($pr, 'get_id')) continue;
                $name = trim((string)$pr->get_name());
                if ($name === '') continue;
                $reg = (string)$pr->get_regular_price();
                if ($reg === '' || $reg === null) $reg = (string)$pr->get_price();
                $pageRows[] = ['id' => (int)$pr->get_id(), 'title' => $name,
                    'price' => (int)preg_replace('~\D~', '', $reg),
                    'status' => (string)$pr->get_status(), 'via' => 'direct'];
                $got++;
                if ($got >= $limit) break;
            }
            if ($pageRows) {
                $rows = array_merge($rows, $pageRows);
                reconFetchCursorAppend('woo', 0, $page, $pageRows);
            }
            $meta['page'] = $page;
            reconProgress(['phase' => 'fetch', 'fetched' => count($rows), 'page' => $page,
                'log_add' => ['⚡ مستقیم WC: ' . count($rows) . ' محصول (صفحه ' . $page . ')']]);
            if (count($batch) < $per) { $meta['complete'] = true; break; }
            $page++;
        }
        if (!$meta['complete'] && !$meta['partial']) {
            $meta['partial'] = true; $meta['reason'] = 'run_limit'; $meta['page'] = $page;
        }
        return $rows;
    }
    /* fallback get_posts: page with offset and the same NDJSON cursor */
    $per = 200; $page = $startPage; $got = 0;
    while ($got < $limit) {
        if (reconStopRequested()) {
            $meta['partial'] = true; $meta['stopped'] = true; $meta['reason'] = 'stopped'; $meta['page'] = max(0, $page - 1); break;
        }
        $raw = get_posts(['post_type' => 'product',
            'post_status' => ['publish', 'draft', 'pending', 'private'],
            'posts_per_page' => $per, 'paged' => $page, 'orderby' => 'ID', 'order' => 'ASC']);
        if (!$raw) { $meta['complete'] = true; $meta['page'] = max(0, $page - 1); break; }
        $pageRows = [];
        foreach ((array)$raw as $post) {
            if (!is_object($post)) continue;
            $pid = (int)$post->ID; $name = trim((string)($post->post_title ?? ''));
            if ($name === '') continue;
            $reg = (string)get_post_meta($pid, '_regular_price', true);
            if ($reg === '') $reg = (string)get_post_meta($pid, '_price', true);
            $pageRows[] = ['id' => $pid, 'title' => $name,
                'price' => (int)preg_replace('~\D~', '', $reg),
                'status' => (string)($post->post_status ?? ''), 'via' => 'direct'];
            $got++; if ($got >= $limit) break;
        }
        if ($pageRows) { $rows = array_merge($rows, $pageRows); reconFetchCursorAppend('woo', 0, $page, $pageRows); }
        $meta['page'] = $page;
        reconProgress(['phase' => 'fetch', 'fetched' => count($rows), 'page' => $page,
            'log_add' => ['⚡ مستقیم WC (posts): ' . count($rows) . ' محصول']]);
        if (count($raw) < $per) { $meta['complete'] = true; break; }
        $page++;
    }
    if (!$meta['complete'] && !$meta['partial']) { $meta['partial'] = true; $meta['reason'] = 'run_limit'; $meta['page'] = $page; }
    return $rows;
}

function reconFetchWoo(array $w, int $maxPages = 0, ?array &$meta = null): array {
    $meta = ['complete' => false, 'partial' => false, 'stopped' => false, 'reason' => '', 'page' => 0];
    /* v10.132: مسیر مستقیم هم با همان cursor صفحه‌ای ادامه‌پذیر است. */
    if (function_exists('wooDirectAvailable') && wooDirectAvailable()) {
        return reconFetchWooDirect($maxPages > 0 ? $maxPages * 100 : 0, $meta);
    }
    if ($maxPages <= 0) $maxPages = (int)RECON_FETCH_MAX_PAGES;
    $rows = [];
    $url = rtrim(trim((string)($w['store_url'] ?? '')), '/');
    $ck = trim((string)($w['consumer_key'] ?? '')); $cs = trim((string)($w['consumer_secret'] ?? ''));
    if ($url === '' || $ck === '' || $cs === '') {
        $meta['partial'] = true; $meta['reason'] = 'config';
        reconProgress(['log_add' => ['⚠️ تنظیمات API ووکامرس ناقص و اتصال مستقیم هم در دسترس نبود']]);
        return $rows;
    }
    $cur = reconFetchCursorLoad('woo', 0);
    $rows = array_values(array_filter((array)($cur['rows'] ?? []), 'is_array'));
    $startPage = max(1, (int)($cur['page'] ?? 0) + 1);
    reconProgress(['log_add' => ['🌐 واکشی ووکامرس از REST API (کندتر از مستقیم)…']]);
    $limit = $startPage + max(1, $maxPages);
    for ($page = $startPage; $page < $limit; $page++) {
        if (reconStopRequested()) { $meta['partial'] = true; $meta['stopped'] = true; $meta['reason'] = 'stopped'; $meta['page'] = $page; break; }
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
            'products?per_page=100&status=any&page=' . $page);
        if (empty($r['ok']) || !is_array($r['body'])) {
            $meta['partial'] = true; $meta['reason'] = 'http'; $meta['page'] = $page;
            reconProgress(['log_add' => ['⚠️ صفحهٔ ' . $page . ' نیامد — checkpoint حفظ شد']]); break;
        }
        $batch = $r['body'];
        if (!$batch) { $meta['complete'] = true; $meta['page'] = max(0, $page - 1); break; }
        $pageRows = [];
        foreach ($batch as $pr) {
            if (!is_array($pr)) continue;
            $name = trim((string)($pr['name'] ?? '')); if ($name === '') continue;
            $pageRows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name,
                'price' => (int)preg_replace('~\D~', '', (string)($pr['regular_price'] ?? '0')),
                'status' => (string)($pr['status'] ?? ''), 'via' => 'api'];
        }
        $rows = array_merge($rows, $pageRows); reconFetchCursorAppend('woo', 0, $page, $pageRows);
        $meta['page'] = $page;
        reconProgress(['phase' => 'fetch', 'fetched' => count($rows), 'page' => $page,
            'log_add' => ['📄 صفحهٔ ' . $page . ': ' . count($batch) . ' محصول (مجموع ' . count($rows) . ')']]);
        if (count($batch) < 100) { $meta['complete'] = true; break; }
        usleep(150000);
    }
    if (!$meta['complete'] && !$meta['partial']) { $meta['partial'] = true; $meta['reason'] = 'max_pages'; $meta['page'] = $page - 1; }
    return $rows;
}

/** همهٔ محصولات فعال باسلام. قیمت باسلام به ریال است. */
/**
 * واکشی محصولات باسلام برای مغایرت‌گیری/ماتریس.
 * $customerVisibleOnly=true ⇒ فقط وضعیت 2976 (فعال و قابل مشاهده برای مشتری)
 *                           — نه غیرفعال/در انتظار/بایگانی.
 * پیش‌فرض false برای سازگاری recon قدیمی (فعال+غیرفعال).
 */
function reconFetchBsl(string $tk, int $vid, int $maxPages = 0, bool $customerVisibleOnly = false): array {
    if ($maxPages <= 0) $maxPages = (int)RECON_FETCH_MAX_PAGES;
    $rows = [];
    $stQ = $customerVisibleOnly ? '&statuses=2976' : '&statuses=2976&statuses=3790';
    for ($page = 1; $page <= $maxPages; $page++) {
        if (reconStopRequested()) break;
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $page
             . '&per_page=100' . $stQ);
        if (empty($r['ok'])) break;
        $batch = $r['body']['data'] ?? [];
        if (!$batch) break;
        foreach ($batch as $pr) {
            if (!is_array($pr)) continue;
            $rev = $pr['revision']['data'] ?? [];
            $name = trim((string)($pr['title'] ?? ($pr['name'] ?? ($rev['title'] ?? ''))));
            if ($name === '') continue;
            $st = (int)(is_array($pr['status'] ?? null) ? ($pr['status']['value'] ?? 0) : ($pr['status'] ?? 0));
            if ($customerVisibleOnly && $st !== 2976 && $st !== 0) { if ($st > 0) continue; }
            $rial = (int)($rev['primary_price'] ?? ($pr['primary_price'] ?? 0));
            $rows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name,
                'price' => $rial, 'price_toman' => (int)round($rial / 10), 'status' => $st];
        }
        reconProgress(['phase' => 'fetch', 'fetched' => count($rows), 'page' => $page,
            'log_add' => ['📄 صفحهٔ ' . $page . ': ' . count($batch) . ' محصول'
                . ($customerVisibleOnly ? ' (فقط فعال 2976)' : '') . ' (مجموع ' . count($rows) . ')']]);
        if (count($batch) < 100) break;
        usleep(150000);
    }
    return $rows;
}

function reconFetchCursorFile(): string { return __DIR__ . '/recon_fetch_cache.ndjson'; }

/** خواندنِ صفحاتِ واکشی‌شدهٔ یک مقصد/غرفه از کشِ NDJSON.
 *  v10.126: کش به ازای هر غرفه (vid) جداست تا مغایرت‌گیریِ چندغرفه‌ای پس از
 *  ادامه، محصولاتِ غرفه‌های مختلف را قاطی نکند و صفحهٔ درستِ هر غرفه از
 *  همان‌جا که قطع شده ادامه یابد. */
function reconFetchCursorLoad(string $target, int $vid = 0): array {
    $f = reconFetchCursorFile();
    if (!is_file($f)) return ['rows' => [], 'page' => 0];
    $rows = []; $page = 0;
    foreach ((array)@file($f, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $ln) {
        $d = json_decode($ln, true);
        if (!is_array($d) || (string)($d['target'] ?? '') !== $target) continue;
        if ((int)($d['vid'] ?? 0) !== $vid) continue;
        foreach ((array)($d['rows'] ?? []) as $r) if (is_array($r)) $rows[] = $r;
        $page = max($page, (int)($d['page'] ?? 0));
    }
    return ['rows' => $rows, 'page' => $page];
}

/** چسباندنِ یک صفحه به کشِ واکشی (با تفکیکِ غرفه) */
function reconFetchCursorAppend(string $target, int $vid, int $page, array $rows): void {
    if (!$rows) return;
    @file_put_contents(reconFetchCursorFile(), json_encode(['target' => $target, 'vid' => $vid, 'page' => $page, 'rows' => $rows], JSON_UNESCAPED_UNICODE) . "\n", FILE_APPEND | LOCK_EX);
}

/** واکشیِ محصولاتِ مقصد، با ادامه از چک‌پوینتِ صفحه‌ایِ موجود */
function reconFetchResumable(string $target, array $w, string $tk, int $vid, ?array &$meta = null, bool $customerVisibleOnly = false): array {
    $meta = ['complete' => false, 'partial' => false, 'stopped' => false, 'reason' => '', 'page' => 0];
    $maxPages = (int)RECON_FETCH_MAX_PAGES;
    $cur = reconFetchCursorLoad($target, $vid);
    $rows = array_values(array_filter((array)($cur['rows'] ?? []), 'is_array'));
    $startPage = max(1, (int)($cur['page'] ?? 0) + 1);
    if ($rows) reconProgress(['log_add' => ['↻ ادامهٔ واکشی از صفحهٔ ' . $startPage . ' — ' . count($rows) . ' محصولِ قبلاً خوانده‌شده']]);
    $limit = $startPage + max(1, $maxPages);
    for ($page = $startPage; $page < $limit; $page++) {
        if (reconStopRequested()) { $meta['partial'] = true; $meta['stopped'] = true; $meta['reason'] = 'stopped'; $meta['page'] = $page; break; }
        if ($target === 'woo') {
            $r = wooReq((string)($w['store_url'] ?? ''), (string)($w['consumer_key'] ?? ''), (string)($w['consumer_secret'] ?? ''), 'GET', 'products?per_page=100&status=any&page=' . $page);
            if (empty($r['ok']) || !is_array($r['body'])) { $meta['partial'] = true; $meta['reason'] = 'http'; $meta['page'] = $page; break; }
            $batch = $r['body'];
            if (!$batch) { $meta['complete'] = true; $meta['page'] = max(0, $page - 1); break; }
            $pageRows = [];
            foreach ($batch as $pr) {
                if (!is_array($pr)) continue;
                $name = trim((string)($pr['name'] ?? '')); if ($name === '') continue;
                $pageRows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name,
                    'price' => (int)preg_replace('~\D~', '', (string)($pr['regular_price'] ?? '0')),
                    'status' => (string)($pr['status'] ?? ''), 'via' => 'api'];
            }
        } else {
            $stQ = $customerVisibleOnly ? '&statuses=2976' : '&statuses=2976&statuses=3790';
            $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $page . '&per_page=100' . $stQ);
            if (empty($r['ok']) || !is_array($r['body']['data'] ?? null)) { $meta['partial'] = true; $meta['reason'] = 'http'; $meta['page'] = $page; break; }
            $batch = $r['body']['data'];
            if (!$batch) { $meta['complete'] = true; $meta['page'] = max(0, $page - 1); break; }
            $pageRows = [];
            foreach ($batch as $pr) {
                if (!is_array($pr)) continue;
                $rev = $pr['revision']['data'] ?? [];
                $name = trim((string)($pr['title'] ?? ($pr['name'] ?? ($rev['title'] ?? '')))); if ($name === '') continue;
                $st = (int)(is_array($pr['status'] ?? null) ? ($pr['status']['value'] ?? 0) : ($pr['status'] ?? 0));
                $rial = (int)($rev['primary_price'] ?? ($pr['primary_price'] ?? 0));
                $pageRows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name, 'price' => $rial,
                    'price_toman' => (int)round($rial / 10), 'status' => $st];
            }
        }
        $rows = array_merge($rows, $pageRows); reconFetchCursorAppend($target, $vid, $page, $pageRows);
        $meta['page'] = $page;
        reconProgress(['phase' => 'fetch', 'fetched' => count($rows), 'page' => $page,
            'log_add' => ['📄 صفحهٔ ' . $page . ': ' . count($batch) . ' محصول (مجموع ' . count($rows) . ')']]);
        if (count($batch) < 100) { $meta['complete'] = true; break; }
        usleep(150000);
    }
    if (!$meta['complete'] && !$meta['partial']) { $meta['partial'] = true; $meta['reason'] = 'max_pages'; $meta['page'] = $limit - 1; }
    return $rows;
}

/**
 * مقایسه و در صورت درخواست، اعمال تغییرات.
 * $mode برای موارد اضافی: off | draft | outofstock | delete
 */

/* =====================================================================
 *  v10.107: مغایرت‌گیری چندغرفه + «در مقصد نیست» + اجرای دوره‌ای
 * ===================================================================== */

/** تنظیمات مغایرت‌گیری دوره‌ای از connections */
function reconAutoCfg(?array $cn = null): array {
    if ($cn === null) $cn = loadConnections();
    $r = is_array($cn['recon_auto'] ?? null) ? $cn['recon_auto'] : [];
    $iv = (int)($r['interval_h'] ?? 6);
    if ($iv < 1) $iv = 1;
    if ($iv > 168) $iv = 168;
    $mode = (string)($r['extra_mode'] ?? 'off');
    if (!function_exists('retireModes') || !isset(retireModes()[$mode])) $mode = 'off';
    return [
        'enabled'       => !empty($r['enabled']),
        'woo'           => !isset($r['woo']) || !empty($r['woo']),
        'bsl'           => !isset($r['bsl']) || !empty($r['bsl']),
        'all_vendors'   => !isset($r['all_vendors']) || !empty($r['all_vendors']),
        'all_profiles'  => !isset($r['all_profiles']) || !empty($r['all_profiles']),
        'fix_price'     => !isset($r['fix_price']) || !empty($r['fix_price']),
        'apply'         => !empty($r['apply']), // پیش‌فرض فقط گزارش
        'extra_mode'    => $mode,
        'interval_h'    => $iv,
        'notify'        => !isset($r['notify']) || !empty($r['notify']),
        'enqueue_missing' => !empty($r['enqueue_missing']), // صف‌کردن محصولاتِ «در مقصد نیست»
        'build_matrix'  => !isset($r['build_matrix']) || !empty($r['build_matrix']), // v10.113
        'matrix_fix'    => !isset($r['matrix_fix']) || !empty($r['matrix_fix']), // v10.121
    ];
}

function reconAutoStateLoad(): array {
    if (!is_file(RECON_AUTO_STATE_FILE)) return [];
    $d = json_decode((string)@file_get_contents(RECON_AUTO_STATE_FILE), true);
    return is_array($d) ? $d : [];
}
function reconAutoStateSave(array $s): void {
    @file_put_contents(RECON_AUTO_STATE_FILE, json_encode($s, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/** تنظیمات اصلاح دوره‌ای دسته با AI + یادگیری */
function catfixAutoCfg(?array $cn = null): array {
    if ($cn === null) $cn = loadConnections();
    $r = is_array($cn['catfix_auto'] ?? null) ? $cn['catfix_auto'] : [];
    $iv = (int)($r['interval_h'] ?? 12);
    if ($iv < 1) $iv = 1;
    if ($iv > 168) $iv = 168;
    $mode = (string)($r['mode'] ?? 'master');
    if (!in_array($mode, ['ai_text', 'master', 'quorum', 'fallback', 'learned'], true)) $mode = 'master';
    return [
        'enabled'     => !empty($r['enabled']),
        'mode'        => $mode,
        'all_vendors' => !isset($r['all_vendors']) || !empty($r['all_vendors']),
        'use_learn'   => !isset($r['use_learn']) || !empty($r['use_learn']),
        'interval_h'  => $iv,
        'quorum'      => max(1, min(8, (int)($r['quorum'] ?? 2))),
        'notify'      => !empty($r['notify']),
    ];
}
function catfixAutoStateLoad(): array {
    if (!is_file(CATFIX_AUTO_STATE_FILE)) return [];
    $d = json_decode((string)@file_get_contents(CATFIX_AUTO_STATE_FILE), true);
    return is_array($d) ? $d : [];
}
function catfixAutoStateSave(array $s): void {
    @file_put_contents(CATFIX_AUTO_STATE_FILE, json_encode($s, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/**
 * یک‌بار مغایرت‌گیری برای یک مقصد/غرفه.
 * $vendorId>0 فقط همان غرفه؛ 0 = غرفه پیش‌فرض (سازگاری عقب‌رو).
 */
function reconRunOne(array $cn, string $target, bool $apply = false,
                     string $mode = 'off', bool $fixPrice = true, bool $allProfiles = false,
                     int $vendorId = 0, string $shopName = '', string $shopToken = '',
                     ?array $cp = null): array {
    $out = ['ok' => true, 'target' => $target, 'apply' => $apply, 'mode' => $mode,
            'all_profiles' => $allProfiles,
            'vendor_id' => $vendorId, 'shop_name' => $shopName,
            'expected' => 0, 'remote' => 0, 'extra' => [], 'price_diff' => [],
            'missing' => [], // v10.107: در مبدأ هست، در مقصد نیست
            'matched' => 0, 'matched_items' => [], 'deleted' => 0, 'repriced' => 0, 'failed' => 0];
    /* v10.129: اعمالِ مغایرت هم محصول‌به‌محصول checkpoint می‌شود؛ واکشیِ
       دوباره فقط داده را می‌سازد و شناسه‌های انجام‌شده دوباره PUT/DELETE نمی‌شوند. */
    $reconPriceDone = array_values(array_filter(array_map('intval', (array)($cp['price_done_ids'] ?? [])), fn($x) => $x > 0));
    $reconExtraDone = array_values(array_filter(array_map('intval', (array)($cp['extra_done_ids'] ?? [])), fn($x) => $x > 0));
    $reconPriceSet = $reconPriceDone ? array_fill_keys($reconPriceDone, true) : [];
    $reconExtraSet = $reconExtraDone ? array_fill_keys($reconExtraDone, true) : [];
    $reconStartedAt = (int)($cp['started_at'] ?? time());
    $saveReconApplyCp = function (string $phase, int $cur, int $total) use (&$reconPriceDone, &$reconExtraDone,
        &$out, $target, $vendorId, $allProfiles, $apply, $mode, $fixPrice, $reconStartedAt): void {
        reconProgress(['checkpoint' => ['target' => $target, 'vendor_id' => $vendorId,
            'all_profiles' => $allProfiles, 'apply' => $apply, 'mode' => $mode, 'fix_price' => $fixPrice,
            'phase' => $phase, 'price_done_ids' => $reconPriceDone, 'extra_done_ids' => $reconExtraDone,
            'repriced' => (int)$out['repriced'], 'deleted' => (int)$out['deleted'],
            'failed' => (int)$out['failed'], 'cur' => $cur, 'cur_total' => $total,
            'started_at' => $reconStartedAt,
            'vendor_index' => (int)($cp['vendor_index'] ?? 0),
            'vendors' => is_array($cp['vendors'] ?? null) ? $cp['vendors'] : [],
            'aggregate' => is_array($cp['aggregate'] ?? null) ? $cp['aggregate'] : null]]);
    };
    $stopRecon = function () use (&$out, $target, $vendorId, $allProfiles, $apply, $mode, $fixPrice,
        $reconStartedAt, &$reconPriceDone, &$reconExtraDone, $cp): array {
        $out['ok'] = false;
        $out['stopped'] = true;
        $out['partial'] = true;
        $out['error'] = 'مغایرت‌گیری توسط کاربر متوقف شد';
        reconProgress(['running' => false, 'done' => true, 'stopped' => true, 'partial' => true,
            'stale' => true, 'phase' => 'stopped', 'error' => $out['error'],
            'checkpoint' => ['target' => $target, 'vendor_id' => $vendorId,
                'all_profiles' => $allProfiles, 'apply' => $apply, 'mode' => $mode, 'fix_price' => $fixPrice,
                'phase' => 'resume', 'price_done_ids' => $reconPriceDone, 'extra_done_ids' => $reconExtraDone,
                'repriced' => (int)$out['repriced'], 'deleted' => (int)$out['deleted'],
                'failed' => (int)$out['failed'], 'started_at' => $reconStartedAt,
                'vendor_index' => (int)($cp['vendor_index'] ?? 0),
                'vendors' => is_array($cp['vendors'] ?? null) ? $cp['vendors'] : [],
                'aggregate' => is_array($cp['aggregate'] ?? null) ? $cp['aggregate'] : null],
            'log_add' => ['⏹ توقف توسط کاربر — checkpoint حفظ شد']]);
        return $out;
    };
    if (reconStopRequested()) return $stopRecon();

    reconProgress(['phase' => 'profiles', 'log_add' => [
        ($shopName !== '' ? ('🏪 غرفه: ' . $shopName . ( $vendorId > 0 ? ' (#' . $vendorId . ')' : '')) : '')
            ?: ($allProfiles ? '🔎 خواندن همهٔ پروفایل‌ها...' : '🔎 خواندن پروفایل‌های دارای همگام‌سازی دوره‌ای...')
    ]]);
    $pstats = null;
    $expected = reconExpected($target, $allProfiles, $pstats);
    $out['expected'] = count($expected);
    $out['profile_stats'] = $pstats;

    $plog = [];
    foreach (($pstats['profiles'] ?? []) as $ps) {
        $plog[] = ($ps['n'] > 0 ? '  ✓ ' : '  ⏭ ') . $ps['name']
            . ($ps['n'] > 0 ? (' — ' . $ps['n'] . ' محصول'
                . (!empty($ps['no_price']) ? ' (' . $ps['no_price'] . ' بدون قیمت)' : '')
                . (!empty($ps['why']) ? ' · ' . $ps['why'] : ''))
              : ' — ' . ($ps['why'] ?? ''));
    }
    $plog[] = '✅ ' . count($expected) . ' عنوان یکتا از '
            . (int)($pstats['used'] ?? 0) . ' پروفایل جمع شد'
            . ((int)($pstats['skipped'] ?? 0) > 0 ? ' · ' . (int)$pstats['skipped'] . ' پروفایل کنار گذاشته شد' : '');
    reconProgress(['phase' => 'profiles', 'expected' => count($expected), 'log_add' => $plog]);

    if (!$expected) {
        $out['ok'] = false;
        $out['error'] = $allProfiles
            ? 'هیچ پروفایلی محصولی برای مقایسه ندارد — اول استخراج کنید'
            : 'هیچ پروفایلی با همگام‌سازی دوره‌ای برای این مقصد پیدا نشد — گزینهٔ «همهٔ پروفایل‌ها» را بزنید';
        $out['hint_all_profiles'] = !$allProfiles && (int)($pstats['skipped'] ?? 0) > 0;
        return $out;
    }

    if (reconStopRequested()) return $stopRecon();
    reconProgress(['phase' => 'fetch', 'log_add' => ['📥 دریافت محصولات '
        . ($target === 'woo' ? 'ووکامرس' : ('باسلام' . ($shopName !== '' ? ' · ' . $shopName : ''))) . '...']]);
    /* v10.126: واکشی همیشه از مسیرِ قابلِ ادامه است تا کشِ صفحه‌ای ساخته شود؛
       فقط مسیرِ DB مستقیمِ ووکامرس (سریع، بدونِ نیاز به کش) وقتی به کار می‌رود
       که ادامه‌ای در کار نباشد. */
    $resumeFetch = (is_array($cp) && (string)($cp['target'] ?? '') === $target
        && is_file(reconFetchCursorFile()));
    $fetchMeta = [];
    if ($target === 'woo') {
        $w = $cn['woocommerce'] ?? [];
        if (empty($w['store_url']) && !(function_exists('wooDirectAvailable') && wooDirectAvailable())) { $out['ok'] = false; $out['error'] = 'تنظیمات ووکامرس ناقص'; return $out; }
        if (function_exists('wooDirectAvailable') && wooDirectAvailable()) {
            $remote = reconFetchWooDirect(0, $fetchMeta);
        } else {
            $remote = reconFetchResumable('woo', $w, '', 0, $fetchMeta);
        }
        $tk = ''; $vid = 0;
    } else {
        $tk = $shopToken !== '' ? $shopToken : (string)($cn['basalam']['token'] ?? '');
        $vid = $vendorId > 0 ? $vendorId : (int)($cn['basalam']['vendor_id'] ?? 0);
        if ($tk === '' || $vid <= 0) { $out['ok'] = false; $out['error'] = 'تنظیمات باسلام ناقص'; return $out; }
        $remote = reconFetchResumable('bsl', [], $tk, $vid, $fetchMeta);
    }
    if (!empty($fetchMeta['partial']) || reconStopRequested()) {
        if (!empty($fetchMeta['stopped']) || reconStopRequested()) return $stopRecon();
        $out['ok'] = false; $out['partial'] = true;
        $out['error'] = 'برداشت مقصد در صفحهٔ ' . (int)($fetchMeta['page'] ?? 0) . ' کامل نشد — checkpoint حفظ شد';
        return $out;
    }
    $out['remote'] = count($remote);
    reconProgress(['phase' => 'compare', 'remote' => count($remote),
        'log_add' => ['✅ ' . count($remote) . ' محصول از مقصد دریافت شد', '⚖️ مقایسه...']]);
    if (!$remote) {
        $out['ok'] = false;
        $out['error'] = 'هیچ محصولی از مقصد دریافت نشد — برای احتیاط کاری انجام نشد';
        return $out;
    }

    $idMap  = remoteMapById($target);
    $byKey  = is_array($pstats['by_key'] ?? null) ? $pstats['by_key'] : [];
    $byIdN  = 0;
    $cmpN = 0; $sampleExtra = []; $sampleDiff = []; $noPriceN = 0;
    $hitTitles = []; // v10.107: عنوان‌های مبدأ که در مقصد پیدا شدند
    $hitKeys = [];

    foreach ($remote as $r) {
        if (reconStopRequested()) return $stopRecon();
        $cmpN++;
        $rid = (int)($r['id'] ?? 0);
        $key = reconNormTitle($r['title']);
        $hit = $expected[$key] ?? null;
        if ($hit === null && $rid > 0 && isset($idMap[$rid]) && isset($byKey[$idMap[$rid]])) {
            $hit = $byKey[$idMap[$rid]];
            $byIdN++;
        }
        if ($hit === null) {
            $out['extra'][] = ['id' => $r['id'], 'title' => $r['title'], 'price' => $r['price'],
                'vendor_id' => $vid, 'shop_name' => $shopName,
                'why' => 'در هیچ پروفایل/مبدأ نیست'];
            if (count($sampleExtra) < 5) $sampleExtra[] = '  🗑 ' . mb_substr($r['title'], 0, 45);
        } else {
            $hitTitles[$key] = true;
            $pk = trim((string)($hit['key'] ?? ''));
            if ($pk !== '') $hitKeys[$pk] = true;
            $want = (int)$hit['price'];
            $have = $target === 'bsl' ? (int)($r['price_toman'] ?? 0) : (int)$r['price'];
            if ($want <= 0) {
                $noPriceN++;
                $out['matched']++;
                if (count($out['matched_items']) < 500) {
                    $out['matched_items'][] = ['id' => $r['id'], 'title' => $r['title'], 'price' => $have,
                        'vendor_id' => $vid, 'shop_name' => $shopName];
                }
            } elseif ($have !== $want) {
                $out['price_diff'][] = ['id' => $r['id'], 'title' => $r['title'],
                    'from' => $have, 'to' => $want, 'profile' => (string)($hit['profile'] ?? ''),
                    'vendor_id' => $vid, 'shop_name' => $shopName,
                    'key' => $pk];
                if (count($sampleDiff) < 5) $sampleDiff[] = '  💰 ' . mb_substr($r['title'], 0, 38)
                    . ' — ' . number_format($have) . ' → ' . number_format($want);
            } else {
                $out['matched']++;
                if (count($out['matched_items']) < 500) {
                    $out['matched_items'][] = ['id' => $r['id'], 'title' => $r['title'], 'price' => $have,
                        'vendor_id' => $vid, 'shop_name' => $shopName];
                }
            }
        }
        if ($cmpN % 25 === 0) {
            reconProgress(['phase' => 'compare', 'cur' => $cmpN, 'cur_total' => count($remote),
                'extra' => count($out['extra']), 'diff' => count($out['price_diff']),
                'matched' => $out['matched'],
                'log_add' => ['⚖️ مقایسه ' . $cmpN . '/' . count($remote)
                    . ' — اضافی ' . count($out['extra'])
                    . '، مغایرت ' . count($out['price_diff'])
                    . '، یکسان ' . $out['matched']]]);
        }
    }

    // v10.107: محصولات مبدأ که در مقصد نیستند → باید سینک شوند
    $missN = 0;
    foreach ($expected as $etitle => $eh) {
        $pk = trim((string)($eh['key'] ?? ''));
        $found = isset($hitTitles[$etitle]) || ($pk !== '' && isset($hitKeys[$pk]));
        if ($found) continue;
        $missN++;
        if (count($out['missing']) < 800) {
            $out['missing'][] = [
                'title' => $etitle,
                'price' => (int)($eh['price'] ?? 0),
                'profile' => (string)($eh['profile'] ?? ''),
                'profile_key' => (string)($eh['profile_key'] ?? ''),
                'key' => $pk,
                'vendor_id' => $vid,
                'shop_name' => $shopName,
                'why' => 'در مبدأ/پروفایل هست ولی در مقصد نیست',
            ];
        }
    }
    $out['missing_total'] = $missN;

    $out['no_src_price'] = $noPriceN;
    $out['matched_by_id'] = $byIdN;
    $out['id_map_size'] = count($idMap);

    $doneLog = ['📊 اضافی (در مبدأ نیست): ' . count($out['extra'])
        . ' · مغایرت قیمت: ' . count($out['price_diff'])
        . ' · یکسان: ' . $out['matched']
        . ' · در مقصد نیست: ' . $missN];
    if ($byIdN > 0) $doneLog[] = '🔗 ' . $byIdN . ' محصول با شناسهٔ ثبت‌شده تطبیق خورد '
        . '(عنوانشان در مقصد عوض شده بود)';
    if ($noPriceN > 0) $doneLog[] = 'ℹ️ ' . $noPriceN . ' محصول در مبدأ قیمت ندارد — قیمتشان مقایسه نشد';
    if ($sampleDiff)  { $doneLog[] = 'نمونهٔ مغایرت قیمت:';  foreach ($sampleDiff as $l) $doneLog[] = $l; }
    if ($sampleExtra) { $doneLog[] = 'نمونهٔ «در مبدأ نیست»:'; foreach ($sampleExtra as $l) $doneLog[] = $l; }
    if (count($out['missing']) > 0) {
        $doneLog[] = 'نمونهٔ «در مقصد نیست» (نیاز به سینک):';
        foreach (array_slice($out['missing'], 0, 5) as $mrow) {
            $doneLog[] = '  📤 ' . mb_substr((string)($mrow['title'] ?? ''), 0, 45)
                . (!empty($mrow['profile']) ? (' · ' . $mrow['profile']) : '');
        }
    }
    if (count($out['extra']) > 0 && count($out['extra']) === count($remote)) {
        $doneLog[] = '⚠️ هیچ محصولی تطبیق نخورد — احتمالاً عنوان‌های مقصد با پروفایل فرق دارند '
                   . '(پسوند پروفایل یا تغییر نام). قبل از «حذف»، فهرست را ببینید.';
    }
    reconProgress(['phase' => $apply ? 'apply' : 'done',
        'extra' => count($out['extra']), 'diff' => count($out['price_diff']),
        'matched' => $out['matched'], 'missing' => $missN, 'cur' => 0, 'cur_total' => 0,
        'log_add' => $doneLog]);

    if (!$apply) return $out;

    // --- اصلاح قیمت ---
    if (reconStopRequested()) return $stopRecon();
    if ($fixPrice && $out['price_diff']) {
        foreach ($out['price_diff'] as $i => $d) {
            if (reconStopRequested()) return $stopRecon();
            $did = (int)($d['id'] ?? 0);
            if ($did > 0 && isset($reconPriceSet[$did])) {
                $out['price_diff'][$i]['done'] = true;
                continue;
            }
            $okRow = false;
            if ($target === 'woo') {
                $r = wooReq($cn['woocommerce']['store_url'], $cn['woocommerce']['consumer_key'],
                    $cn['woocommerce']['consumer_secret'], 'PUT', 'products/' . $d['id'],
                    ['regular_price' => (string)$d['to']]);
                $okRow = !empty($r['ok']);
            } else {
                $bu = ['primary_price' => $d['to'] * 10];
                $r = bslReq($tk, 'PATCH', 'products/' . $d['id'], $bu);
                if ((int)($r['code'] ?? 0) === 404)
                    $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $d['id'], $bu);
                $okRow = !empty($r['ok']);
            }
            if ($okRow) $out['repriced']++; else $out['failed']++;
            $out['price_diff'][$i]['done'] = $okRow;
            /* فقط PUT موفق مصرف شده است؛ خطای موقت باید در checkpoint
               بماند تا اجرای بعدی دوباره همان محصول را امتحان کند. */
            if ($okRow && $did > 0 && !isset($reconPriceSet[$did])) {
                $reconPriceDone[] = $did; $reconPriceSet[$did] = true;
            }
            reconProgress(['phase' => 'apply', 'step' => 'price',
                'repriced' => $out['repriced'], 'failed' => $out['failed'],
                'cur' => $i + 1, 'cur_total' => count($out['price_diff']),
                'log_add' => [($okRow ? '💰 ' : '❌ ') . mb_substr($d['title'], 0, 40)
                    . ' — ' . number_format($d['from']) . ' → ' . number_format($d['to'])]]);
            $saveReconApplyCp('price', $i + 1, count($out['price_diff']));
            usleep(200000);
        }
    }

    // --- حذف/بازنشستگی موارد اضافی (در مبدأ نیست) ---
    if ($mode !== 'off' && $out['extra']) {
        $kept = max(0, count($remote) - count($out['extra']));
        $guard = retireGuard(count($out['extra']), $kept, $cn);
        $out['guard'] = $guard;
        if (empty($guard['allow'])) {
            $out['skipped_delete'] = $guard['reason'];
            reconProgress(['log_add' => ['🛑 حذف انجام نشد: ' . $guard['reason']]]);
            return $out;
        }
        foreach ($out['extra'] as $i => $d) {
            if (reconStopRequested()) return $stopRecon();
            $did = (int)($d['id'] ?? 0);
            if ($did > 0 && isset($reconExtraSet[$did])) {
                $out['extra'][$i]['done'] = true;
                continue;
            }
            $okRow = false;
            if ($target === 'woo') {
                $w = $cn['woocommerce'];
                if ($mode === 'delete') {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'DELETE', 'products/' . $d['id'] . '?force=false');
                } elseif ($mode === 'outofstock') {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'PUT', 'products/' . $d['id'], ['stock_status' => 'outofstock', 'stock_quantity' => 0]);
                } else { // draft
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'PUT', 'products/' . $d['id'], ['status' => 'draft']);
                }
                $okRow = !empty($r['ok']);
            } else {
                // باسلام: بایگانی نزدیک‌ترین معادل حذف
                if ($mode === 'delete' || $mode === 'draft' || $mode === 'outofstock') {
                    $r = bslReq($tk, 'POST', 'products/' . $d['id'] . '/archive');
                    if (empty($r['ok']))
                        $r = bslReq($tk, 'PATCH', 'products/' . $d['id'], ['status' => 3790]);
                    if (empty($r['ok']))
                        $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $d['id'], ['status' => 3790]);
                    $okRow = !empty($r['ok']);
                }
            }
            if ($okRow) $out['deleted']++; else $out['failed']++;
            $out['extra'][$i]['done'] = $okRow;
            /* حذف/بازنشستگی ناموفق مصرف نشده است؛ retry باید در اجرای
               بعدی ممکن بماند و هرگز به‌خاطر یک پاسخ خطا done نشود. */
            if ($okRow && $did > 0 && !isset($reconExtraSet[$did])) {
                $reconExtraDone[] = $did; $reconExtraSet[$did] = true;
            }
            reconProgress(['phase' => 'apply', 'step' => 'extra',
                'deleted' => $out['deleted'], 'failed' => $out['failed'],
                'cur' => $i + 1, 'cur_total' => count($out['extra']),
                'log_add' => [($okRow ? '🗑 ' : '❌ ') . mb_substr($d['title'], 0, 45)]]);
            $saveReconApplyCp('extra', $i + 1, count($out['extra']));
            usleep(200000);
        }
    }

    return $out;
}

/**
 * v10.107: مغایرت‌گیری — پشتیبانی همهٔ غرفه‌های باسلام + گزارش «در مقصد نیست».
 * $allVendors فقط برای target=bsl معنا دارد.
 */
function reconRun(array $cn, string $target, bool $apply = false,
                  string $mode = 'off', bool $fixPrice = true, bool $allProfiles = false,
                  bool $allVendors = false, int $onlyVendorId = 0, ?array $cp = null): array {
    if ($target !== 'bsl' || (!$allVendors && $onlyVendorId <= 0)) {
        // سازگاری: یک غرفه/ووکامرس
        $shopName = ''; $shopTok = ''; $vid = 0;
        if ($target === 'bsl') {
            $vid = $onlyVendorId > 0 ? $onlyVendorId : (int)($cn['basalam']['vendor_id'] ?? 0);
            foreach (bslAllShops($cn) as $sh) {
                if ((int)$sh['vendor_id'] === $vid) {
                    $shopName = (string)$sh['shop_name'];
                    $shopTok = (string)$sh['token'];
                    break;
                }
            }
            if ($shopTok === '') {
                $shopTok = (string)($cn['basalam']['token'] ?? '');
                $shopName = 'غرفهٔ پیش‌فرض';
            }
        }
        return reconRunOne($cn, $target, $apply, $mode, $fixPrice, $allProfiles, $vid, $shopName, $shopTok, $cp);
    }

    $shops = bslAllShops($cn);
    if ($onlyVendorId > 0) {
        $shops = array_values(array_filter($shops, function ($s) use ($onlyVendorId) {
            return (int)($s['vendor_id'] ?? 0) === $onlyVendorId;
        }));
    }
    if (!$shops) {
        return ['ok' => false, 'error' => 'هیچ غرفهٔ فعالی برای مغایرت‌گیری نیست', 'target' => 'bsl'];
    }

    /* v10.129: هر غرفه checkpoint و جمع‌بندیِ مستقل دارد. */
    $seedAgg = is_array($cp['aggregate'] ?? null) ? $cp['aggregate'] : [];
    $agg = array_merge(['ok' => true, 'target' => 'bsl', 'apply' => $apply, 'mode' => $mode,
            'all_profiles' => $allProfiles, 'all_vendors' => true,
            'shops' => [], 'expected' => 0, 'remote' => 0,
            'extra' => [], 'price_diff' => [], 'missing' => [], 'matched' => 0, 'matched_items' => [],
            'deleted' => 0, 'repriced' => 0, 'failed' => 0,
            'missing_total' => 0, 'extra_total' => 0, 'price_diff_total' => 0], $seedAgg);
    $vendorState = is_array($cp['vendors'] ?? null) ? $cp['vendors'] : [];
    $currentCp = is_array($cp) && (int)($cp['vendor_id'] ?? 0) > 0 ? $cp : null;
    reconProgress(['log_add' => ['🚚 مغایرت‌گیری همهٔ غرفه‌ها — ' . count($shops) . ' غرفه']]);

    foreach ($shops as $si => $sh) {
        if (reconStopRequested()) {
            $agg['stopped'] = true; $agg['partial'] = true; $agg['ok'] = false;
            $agg['error'] = 'مغایرت‌گیری توسط کاربر متوقف شد';
            break;
        }
        $vid = (int)$sh['vendor_id'];
        $name = (string)$sh['shop_name'];
        $tok = (string)$sh['token'];
        $vs = is_array($vendorState[(string)$vid] ?? null) ? $vendorState[(string)$vid] : [];
        if (!empty($vs['done'])) continue;
        $oneCp = is_array($vs['checkpoint'] ?? null) ? $vs['checkpoint'] : null;
        if ($oneCp === null && $currentCp !== null && (int)($currentCp['vendor_id'] ?? 0) === $vid) $oneCp = $currentCp;
        reconProgress(['log_add' => ['——— غرفه ' . ($si + 1) . '/' . count($shops) . ': ' . $name . ' (#' . $vid . ') ———']]);
        $childCp = is_array($oneCp) ? $oneCp : [];
        $childCp['vendor_id'] = $vid; $childCp['vendor_index'] = $si;
        $childCp['vendors'] = $vendorState; $childCp['aggregate'] = $agg;
        $one = reconRunOne($cn, 'bsl', $apply, $mode, $fixPrice, $allProfiles, $vid, $name, $tok, $childCp);
        $oneSummary = ['vendor_id' => $vid, 'shop_name' => $name, 'ok' => !empty($one['ok']),
            'error' => (string)($one['error'] ?? ''), 'remote' => (int)($one['remote'] ?? 0),
            'extra' => count($one['extra'] ?? []), 'diff' => count($one['price_diff'] ?? []),
            'missing' => (int)($one['missing_total'] ?? count($one['missing'] ?? [])),
            'matched' => (int)($one['matched'] ?? 0), 'repriced' => (int)($one['repriced'] ?? 0),
            'deleted' => (int)($one['deleted'] ?? 0)];
        $agg['shops'][] = $oneSummary;
        if (empty($one['ok']) && empty($agg['error'])) $agg['error'] = (string)($one['error'] ?? '');
        $agg['remote'] += (int)($one['remote'] ?? 0);
        $agg['expected'] = max($agg['expected'], (int)($one['expected'] ?? 0));
        $agg['matched'] += (int)($one['matched'] ?? 0); $agg['repriced'] += (int)($one['repriced'] ?? 0);
        $agg['deleted'] += (int)($one['deleted'] ?? 0); $agg['failed'] += (int)($one['failed'] ?? 0);
        $agg['missing_total'] += (int)($one['missing_total'] ?? count($one['missing'] ?? []));
        foreach (['extra', 'price_diff', 'missing', 'matched_items'] as $k)
            foreach ((array)($one[$k] ?? []) as $row) if (count($agg[$k]) < 900) $agg[$k][] = $row;
        if (!empty($one['profile_stats']) && empty($agg['profile_stats'])) $agg['profile_stats'] = $one['profile_stats'];
        $agg['matched_by_id'] = (int)($agg['matched_by_id'] ?? 0) + (int)($one['matched_by_id'] ?? 0);
        $agg['no_src_price'] = (int)($agg['no_src_price'] ?? 0) + (int)($one['no_src_price'] ?? 0);
        if (!empty($one['stopped'])) {
            $agg['stopped'] = true; $agg['partial'] = true; $agg['ok'] = false;
            $agg['error'] = (string)($one['error'] ?? 'مغایرت‌گیری توسط کاربر متوقف شد');
            break;
        }
        $vendorState[(string)$vid] = ['done' => true, 'checkpoint' => null, 'summary' => $oneSummary];
        reconProgress(['checkpoint' => ['target' => 'bsl', 'vendor_id' => 0, 'vendor_index' => $si + 1,
            'vendors' => $vendorState, 'aggregate' => $agg, 'started_at' => (int)($cp['started_at'] ?? time())]]);
    }

    $anyOk = false;
    foreach ($agg['shops'] as $shopRow) if (!empty($shopRow['ok'])) { $anyOk = true; break; }
    if (empty($agg['stopped'])) $agg['ok'] = $anyOk;
    else $agg['ok'] = false;
    if (!$agg['ok'] && empty($agg['error'])) $agg['error'] = 'مغایرت‌گیری هیچ غرفه‌ای موفق نبود';
    reconProgress(['log_add' => ['🏁 جمع همهٔ غرفه‌ها: مقصد ' . $agg['remote']
        . ' · اضافی ' . count($agg['extra']) . ' · مغایرت ' . count($agg['price_diff'])
        . ' · در مقصد نیست ' . $agg['missing_total']]]);
    return $agg;
}

/**
 * v10.107: تیک دوره‌ای مغایرت‌گیری داخل cron_run
 */

/**
 * v10.108: محصولات «در مقصد نیست» را از روی پروفایل‌ها به صف ارسال
 * ووکامرس / باسلام می‌گذارد تا سینک پر شود.
 *
 * $missingRows: [{key, title, profile, vendor_id, shop_name, price}, ...]
 * $target: woo|bsl
 *
 * @return array{ok:bool,queued:int,products:int,skipped:int,errors:array,queues:array}
 */
function reconEnqueueMissingProducts(array $cn, string $target, array $missingRows, array $opts = []): array {
    $out = ['ok' => true, 'queued' => 0, 'products' => 0, 'skipped' => 0,
            'errors' => [], 'queues' => [], 'by_profile' => []];
    if ($target !== 'woo' && $target !== 'bsl') {
        return ['ok' => false, 'error' => 'مقصد نامعتبر', 'queued' => 0, 'products' => 0];
    }
    if (!$missingRows) {
        $out['skipped'] = 0;
        $out['msg'] = 'موردی برای صف نیست';
        return $out;
    }

    $maxItems = (int)($opts['max'] ?? 2000);
    if ($maxItems < 1) $maxItems = 2000;
    if ($maxItems > 5000) $maxItems = 5000;

    // group keys by profile name (as stored in missing) AND try match loadProfiles
    $profiles = loadProfiles();
    // map profile display name -> key, and key -> profile
    $byName = [];
    $byKey = [];
    foreach ($profiles as $pk => $pr) {
        if (!is_array($pr)) continue;
        $byKey[$pk] = $pr;
        $nm = trim((string)($pr['name'] ?? $pk));
        if ($nm !== '') $byName[mb_strtolower($nm)] = $pk;
        $byName[mb_strtolower((string)$pk)] = $pk;
    }

    // missing may have key=productKey and profile=name
    $groups = []; // profileKey => [productKey => true]
    $noKey = 0;
    $n = 0;
    foreach ($missingRows as $row) {
        if (!is_array($row)) continue;
        if ($n >= $maxItems) break;
        $prodKey = trim((string)($row['key'] ?? ''));
        if ($prodKey === '') { $noKey++; continue; }
        $pName = trim((string)($row['profile'] ?? ''));
        $pk = trim((string)($row['profile_key'] ?? ''));
        if ($pk !== '' && !isset($byKey[$pk])) $pk = '';
        if ($pk === '' && $pName !== '') {
            $pk = $byName[mb_strtolower($pName)] ?? '';
        }
        // fallback: scan all profiles for this product key
        if ($pk === '') {
            foreach ($byKey as $candPk => $pr) {
                $raw = $pr['products'] ?? [];
                $found = false;
                if (is_array($raw)) {
                    foreach ($raw as $entry) {
                        if (is_array($entry) && isset($entry[0]) && (string)$entry[0] === $prodKey) {
                            $found = true; break;
                        }
                        if (is_string($entry) && $entry === $prodKey) { $found = true; break; }
                    }
                    // also associative map style
                    if (!$found && isset($raw[$prodKey])) $found = true;
                }
                if ($found) { $pk = $candPk; break; }
            }
        }
        if ($pk === '' || !isset($byKey[$pk])) {
            $out['skipped']++;
            continue;
        }
        if (!isset($groups[$pk])) $groups[$pk] = [];
        $groups[$pk][$prodKey] = true;
        $n++;
    }
    if ($noKey > 0) $out['errors'][] = $noKey . ' ردیف بدون کلید محصول نادیده گرفته شد';
    if (!$groups) {
        $out['ok'] = false;
        $out['error'] = 'هیچ محصولی به پروفایل وصل نشد — دفترچه/کلید محصول ناقص است';
        return $out;
    }

    $now = time();
    $onlyVendorId = (int)($opts['vendor_id'] ?? 0);
    $shopNameOpt = trim((string)($opts['shop_name'] ?? ''));

    foreach ($groups as $pk => $keySet) {
        $profile = $byKey[$pk];
        $pName = (string)($profile['name'] ?? $pk);
        $products = profileOrderedProducts($profile, $keySet, true);
        if (!$products) {
            $out['skipped'] += count($keySet);
            $out['by_profile'][] = ['profile' => $pName, 'queued' => 0, 'why' => 'محصول در پروفایل پیدا نشد'];
            continue;
        }
        $out['products'] += count($products);

        if ($target === 'woo') {
            if (!function_exists('wooReadQueue') || !function_exists('wooWriteQueue')) {
                $out['errors'][] = 'صف ووکامرس در دسترس نیست';
                continue;
            }
            $w = $cn['woocommerce'] ?? [];
            if (empty($w['store_url'])) {
                $out['errors'][] = 'تنظیمات ووکامرس ناقص';
                continue;
            }
            $wooSuffix = trim($profile['titleSuffix'] ?? '') ?: trim($cn['basalam']['title_suffix'] ?? '');
            $wooCatId = (int)($profile['wooCategoryId'] ?? 0);
            if ($wooCatId <= 0) $wooCatId = (int)($cn['woocommerce']['default_category'] ?? 0);
            $wooForceAll = true; // missing = must send

            $wooQueue = wooReadQueue();
            $wooDup = function_exists('queueDedupOn') && queueDedupOn($cn)
                ? queueHasProfile($wooQueue['entries'], $pk, queueDedupStale($cn)) : null;
            // Always allow a dedicated recon-missing queue id even if profile has another row
            $wooQueueId = 'recon_miss_woo_' . substr(md5($pk . '_' . $now . '_' . count($products)), 0, 12);
            $wooQFile = __DIR__ . '/woo_queue_products_' . $wooQueueId . '.json';
            if (@file_put_contents($wooQFile, json_encode($products, JSON_UNESCAPED_UNICODE), LOCK_EX) === false) {
                $out['errors'][] = 'ذخیرهٔ فایل صف ووکامرس ناموفق: ' . $pName;
                continue;
            }
            $wooBusy = false;
            foreach ($wooQueue['entries'] as $qe0) {
                if (($qe0['status'] ?? '') === 'running') { $wooBusy = true; break; }
            }
            $wooStatus = $wooBusy ? 'waiting' : 'running';
            if ($wooStatus === 'running' && defined('WOO_PRODUCTS_FILE')) {
                @file_put_contents(WOO_PRODUCTS_FILE, json_encode($products, JSON_UNESCAPED_UNICODE), LOCK_EX);
            }
            $wooQueue['entries'][] = [
                'id' => $wooQueueId,
                'status' => $wooStatus,
                'products_file' => $wooQFile,
                'total' => count($products),
                'sent' => 0, 'updated' => 0, 'skipped' => 0, 'failed' => 0, 'current' => 0,
                'started_at' => $wooStatus === 'running' ? $now : 0,
                'done_at' => 0,
                'profile_key' => $pk,
                'profile_name' => $pName,
                'only_changed' => false,
                'trigger' => 'recon_missing',
                'auto_sync' => true,
                'config' => [
                    'title_suffix' => $wooSuffix,
                    'category_id' => $wooCatId,
                    'force_all' => $wooForceAll,
                ],
            ];
            wooWriteQueue($wooQueue);
            $out['queued']++;
            $out['queues'][] = ['target' => 'woo', 'id' => $wooQueueId, 'n' => count($products), 'profile' => $pName, 'status' => $wooStatus];
            $out['by_profile'][] = ['profile' => $pName, 'queued' => count($products), 'queue_id' => $wooQueueId, 'target' => 'woo'];
        } else {
            // basalam
            if (!function_exists('bslReadQueue') || !function_exists('bslWriteQueue')) {
                $out['errors'][] = 'صف باسلام در دسترس نیست';
                continue;
            }
            $queueId = 'recon_miss_bsl_' . substr(md5($pk . '_' . $now . '_' . count($products)), 0, 12);
            $qFile = __DIR__ . '/bsl_queue_products_' . $queueId . '.json';
            if (@file_put_contents($qFile, json_encode($products, JSON_UNESCAPED_UNICODE), LOCK_EX) === false) {
                $out['errors'][] = 'ذخیرهٔ فایل صف باسلام ناموفق: ' . $pName;
                continue;
            }
            $catId = (int)($cn['basalam']['category_id'] ?? 0);
            $autoCat = !empty($cn['basalam']['auto_category']);
            $titleSuffix = trim($profile['titleSuffix'] ?? '') ?: trim($cn['basalam']['title_suffix'] ?? '');
            $delayMs = max(0, (int)($cn['basalam']['delay_ms'] ?? 500));
            $retryDelayMs = max(0, (int)($cn['basalam']['retry_delay_ms'] ?? 1000));
            $fallbackCats = $cn['basalam']['fallback_cat_ids'] ?? [];
            $profileCatId = (int)($profile['bslCategoryId'] ?? 0);
            if ($profileCatId > 0) $catId = $profileCatId;
            $profileFallbackCats = $profile['bslFallbackCatIds'] ?? [];
            $allFallbackCats = array_values(array_unique(array_merge(
                is_array($profileFallbackCats) ? $profileFallbackCats : [],
                is_array($fallbackCats) ? $fallbackCats : []
            )));
            $queue = bslReadQueue();

            // Prefer specific vendor from missing row if present
            $fanout = [];
            if ($onlyVendorId > 0 && function_exists('bslAllShops')) {
                foreach (bslAllShops($cn) as $sh) {
                    if ((int)$sh['vendor_id'] === $onlyVendorId) {
                        $fanout[] = ['vendor_id' => $onlyVendorId, 'shop_name' => (string)($sh['shop_name'] ?? $shopNameOpt), 'is_default' => !empty($sh['is_default'])];
                        break;
                    }
                }
            }
            // If missing rows carried vendor_ids, collect unique for this batch
            if (!$fanout) {
                $vids = [];
                foreach ($missingRows as $row) {
                    if (!is_array($row)) continue;
                    $rk = trim((string)($row['key'] ?? ''));
                    if ($rk === '' || empty($keySet[$rk])) continue;
                    $vid = (int)($row['vendor_id'] ?? 0);
                    if ($vid > 0) $vids[$vid] = trim((string)($row['shop_name'] ?? ''));
                }
                if ($vids && function_exists('bslAllShops')) {
                    foreach (bslAllShops($cn) as $sh) {
                        $vid = (int)$sh['vendor_id'];
                        if (isset($vids[$vid])) {
                            $fanout[] = ['vendor_id' => $vid, 'shop_name' => (string)$sh['shop_name'], 'is_default' => !empty($sh['is_default'])];
                        }
                    }
                }
            }
            // Default: if send_all_shops, fanout all; else single default entry
            if (!$fanout) {
                if (!empty($cn['basalam']['send_all_shops']) && function_exists('bslFanoutShops')) {
                    $fanout = bslFanoutShops($cn);
                }
            }

            if (count($fanout) > 1) {
                $first = true;
                foreach ($fanout as $sh) {
                    $vid = (int)$sh['vendor_id'];
                    $queue['entries'][] = [
                        'id' => $first ? $queueId : ($queueId . '_s' . $vid),
                        'status' => 'waiting',
                        'products_file' => $qFile,
                        'total' => count($products),
                        'sent' => 0, 'updated' => 0, 'skipped' => 0, 'failed' => 0, 'current' => 0,
                        'started_at' => 0, 'done_at' => 0, 'paused_at' => 0,
                        'only_changed' => false,
                        'config' => [
                            'category_id' => $catId, 'auto_category' => $autoCat,
                            'title_suffix' => $titleSuffix, 'delay_ms' => $delayMs,
                            'retry_delay_ms' => $retryDelayMs, 'fallback_cat_ids' => $allFallbackCats,
                            'send_all_shops' => 0, 'fanout' => 1,
                            'shop_vendor_id' => $vid, 'shop_name' => (string)$sh['shop_name'],
                            'force_all' => true,
                        ],
                        'profile_key' => $pk, 'profile_name' => $pName,
                        'shop_vendor_id' => $vid, 'shop_name' => (string)$sh['shop_name'],
                        'shop_is_default' => !empty($sh['is_default']),
                        'batch_id' => $queueId,
                        'trigger' => 'recon_missing',
                        'auto_sync' => true,
                    ];
                    $first = false;
                    $out['queued']++;
                }
            } else {
                $cfg = [
                    'category_id' => $catId, 'auto_category' => $autoCat,
                    'title_suffix' => $titleSuffix, 'delay_ms' => $delayMs,
                    'retry_delay_ms' => $retryDelayMs, 'fallback_cat_ids' => $allFallbackCats,
                    'send_all_shops' => !empty($cn['basalam']['send_all_shops']),
                    'force_all' => true,
                ];
                if ($fanout) {
                    $cfg['shop_vendor_id'] = (int)$fanout[0]['vendor_id'];
                    $cfg['shop_name'] = (string)$fanout[0]['shop_name'];
                    $cfg['fanout'] = 1;
                    $cfg['send_all_shops'] = 0;
                }
                $entry = [
                    'id' => $queueId, 'status' => 'waiting', 'products_file' => $qFile,
                    'total' => count($products),
                    'sent' => 0, 'updated' => 0, 'skipped' => 0, 'failed' => 0, 'current' => 0,
                    'started_at' => 0, 'done_at' => 0, 'paused_at' => 0,
                    'only_changed' => false,
                    'config' => $cfg,
                    'profile_key' => $pk, 'profile_name' => $pName,
                    'trigger' => 'recon_missing', 'auto_sync' => true,
                ];
                if ($fanout) {
                    $entry['shop_vendor_id'] = (int)$fanout[0]['vendor_id'];
                    $entry['shop_name'] = (string)$fanout[0]['shop_name'];
                }
                $queue['entries'][] = $entry;
                $out['queued']++;
            }
            bslWriteQueue($queue);
            $out['queues'][] = ['target' => 'bsl', 'id' => $queueId, 'n' => count($products), 'profile' => $pName];
            $out['by_profile'][] = ['profile' => $pName, 'queued' => count($products), 'queue_id' => $queueId, 'target' => 'bsl'];
        }
    }

    $out['msg'] = 'صف شد: ' . (int)$out['queued'] . ' ردیف · ' . (int)$out['products'] . ' محصول'
        . ($out['skipped'] ? (' · ردشده ' . (int)$out['skipped']) : '');
    if ($out['queued'] <= 0 && empty($out['errors'])) {
        $out['ok'] = false;
        $out['error'] = $out['msg'] ?: 'صفی ساخته نشد';
    }
    return $out;
}

function reconAutoTick(array $cn, int $now = 0): array {
    if ($now <= 0) $now = time();
    $cfg = reconAutoCfg($cn);
    $out = ['ok' => true, 'ran' => false, 'skipped' => ''];
    if (empty($cfg['enabled'])) { $out['skipped'] = 'disabled'; return $out; }

    $st = reconAutoStateLoad();
    /* v10.130: یک اجرای دوره‌ای که وسط کار مرده، نباید به‌خاطر فاصلهٔ
       زمانیِ تنظیم‌شده تا چند ساعت نادیده بماند یا از صفحهٔ اول شروع شود.
       checkpoint مقصد/غرفه را پیش از نوشتنِ state تازه می‌خوانیم. */
    $oldRecon = function_exists('reconProgressRead') ? reconProgressRead() : [];
    $oldReconCp = is_array($oldRecon['checkpoint'] ?? null) ? $oldRecon['checkpoint'] : null;
    $resumeTarget = (string)($oldRecon['target'] ?? ($oldReconCp['target'] ?? ''));
    $resumeRecon = $oldReconCp !== null && $resumeTarget !== ''
        && (empty($oldRecon['done']) || !empty($oldRecon['stale']));
    $last = (int)($st['last_run'] ?? 0);
    $ivSec = max(3600, (int)$cfg['interval_h'] * 3600);
    if (!$resumeRecon && $last > 0 && ($now - $last) < $ivSec) {
        $out['skipped'] = 'not_due';
        $out['next_in'] = $ivSec - ($now - $last);
        return $out;
    }

    // خودِ flock شاهدِ هم‌پوشانی است؛ mtime/وجودِ فایل به‌تنهایی معتبر نیست.
    $lockFile = __DIR__ . '/recon.lock';

    /* v10.130: the mtime check above is only a fast path; flock is the
       actual protection against a manual/recovery recon starting alongside
       this scheduled run. Hold it through matrix build/fix as well. */
    $reconLockFp = @fopen($lockFile, 'c');
    if (!$reconLockFp || !flock($reconLockFp, LOCK_EX | LOCK_NB)) {
        if ($reconLockFp) @fclose($reconLockFp);
        $out['skipped'] = 'busy'; return $out;
    }
    try {
        $st['last_run'] = $now;
        $st['last_start'] = $now;
        reconAutoStateSave($st);

        $results = [];
    $targets = [];
    if (!empty($cfg['woo'])) $targets[] = 'woo';
    if (!empty($cfg['bsl'])) $targets[] = 'bsl';
    /* اجرای نیمه‌کاره اولویت دارد؛ پس از پایان آن، مقصد بعدی طبق تنظیمات
       اجرا می‌شود. فقط checkpoint همان مقصد به reconRun داده می‌شود. */
    if ($resumeRecon && in_array($resumeTarget, $targets, true)) {
        $targets = array_values(array_unique(array_merge([$resumeTarget], $targets)));
    }

    $reconBlocked = false;
    foreach ($targets as $t) {
        try {
            $reconCp = ($resumeRecon && $resumeTarget === $t) ? $oldReconCp : null;
            reconProgress(['running' => true, 'done' => false, 'target' => $t,
                'apply' => !empty($cfg['apply']), 'started_at' => (int)($reconCp['started_at'] ?? time()),
                'phase' => $reconCp !== null ? 'resume' : 'start', 'checkpoint' => $reconCp ?: [
                    'target' => $t, 'all_profiles' => !empty($cfg['all_profiles']), 'started_at' => time()],
                'log_add' => ['⏰ ' . ($reconCp !== null ? 'ادامه مغایرت‌گیری دوره‌ای — ' : 'مغایرت‌گیری دوره‌ای — ')
                    . ($t === 'woo' ? 'ووکامرس' : 'باسلام')]]);
            /* v10.121: با matrix_fix روشن، apply/قیمت legacy خاموش تا دو بار حذف نشود */
            $_legacyApply = !empty($cfg['apply']) && empty($cfg['matrix_fix']);
            $_legacyFixP = !empty($cfg['fix_price']) && empty($cfg['matrix_fix']);
            $res = reconRun($cn, $t, $_legacyApply, (string)$cfg['extra_mode'],
                $_legacyFixP, !empty($cfg['all_profiles']),
                $t === 'bsl' && !empty($cfg['all_vendors']), 0, $reconCp);
            foreach (['extra', 'price_diff', 'matched_items', 'missing'] as $k) {
                $res[$k . '_total'] = $k === 'missing'
                    ? (int)($res['missing_total'] ?? count($res[$k] ?? []))
                    : count($res[$k] ?? []);
                if (isset($res[$k]) && count($res[$k]) > 300) $res[$k] = array_slice($res[$k], 0, 300);
            }
            $results[$t] = [
                'ok' => !empty($res['ok']),
                'remote' => (int)($res['remote'] ?? 0),
                'extra' => (int)($res['extra_total'] ?? 0),
                'diff' => (int)($res['price_diff_total'] ?? 0),
                'missing' => (int)($res['missing_total'] ?? 0),
                'matched' => (int)($res['matched'] ?? 0),
                'repriced' => (int)($res['repriced'] ?? 0),
                'deleted' => (int)($res['deleted'] ?? 0),
                'shops' => $res['shops'] ?? [],
                'error' => (string)($res['error'] ?? ''),
                'enqueued' => 0,
                'enqueue_products' => 0,
            ];
            /* v10.108: صف خودکار «در مقصد نیست» */
            if (!empty($cfg['enqueue_missing']) && empty($cfg['matrix_fix']) && !empty($res['ok']) && !empty($res['missing'])) {
                try {
                    $eq = reconEnqueueMissingProducts($cn, $t, (array)$res['missing'], ['max' => 2000]);
                    $results[$t]['enqueue'] = [
                        'ok' => !empty($eq['ok']),
                        'queued' => (int)($eq['queued'] ?? 0),
                        'products' => (int)($eq['products'] ?? 0),
                        'msg' => (string)($eq['msg'] ?? ($eq['error'] ?? '')),
                    ];
                    $results[$t]['enqueued'] = (int)($eq['queued'] ?? 0);
                    $results[$t]['enqueue_products'] = (int)($eq['products'] ?? 0);
                    $res['enqueue'] = $results[$t]['enqueue'];
                    reconProgress(['log_add' => [
                        !empty($eq['ok'])
                            ? ('📤 صف خودکار: ' . (int)($eq['products'] ?? 0) . ' محصول در ' . (int)($eq['queued'] ?? 0) . ' ردیف')
                            : ('⚠️ صف خودکار: ' . (string)($eq['error'] ?? $eq['msg'] ?? 'ناموفق'))
                    ]]);
                } catch (\Throwable $e) {
                    $results[$t]['enqueue'] = ['ok' => false, 'error' => mb_substr($e->getMessage(), 0, 160)];
                }
            }
            @file_put_contents(__DIR__ . '/recon_result.json',
                json_encode($res, JSON_UNESCAPED_UNICODE), LOCK_EX);
            $reconFailed = empty($res['ok']);
            if ($reconFailed) $reconBlocked = true;
            $reconEndState = function_exists('reconProgressRead') ? reconProgressRead() : [];
            reconProgress(['running' => false, 'done' => true, 'phase' => $reconFailed ? 'partial' : 'done',
                'stale' => $reconFailed,
                'extra' => (int)$results[$t]['extra'], 'diff' => (int)$results[$t]['diff'],
                'matched' => (int)$results[$t]['matched'], 'missing' => (int)$results[$t]['missing'],
                'result_ok' => !$reconFailed, 'error' => $res['error'] ?? '',
                'checkpoint' => $reconFailed && is_array($reconEndState['checkpoint'] ?? null)
                    ? $reconEndState['checkpoint'] : null,
                'log_add' => [$reconFailed ? ('⚠️ مغایرت‌گیری دوره‌ای ' . $t
                    . ' ناقص ماند — checkpoint حفظ شد') : ('✅ پایان مغایرت‌گیری دوره‌ای ' . $t)]]);
            /* فایل progress فقط یک checkpoint دارد؛ مقصد بعدی نباید checkpoint
               مقصد ناموفق را بپوشاند. کران بعدی همان مقصد را resume می‌کند. */
            if ($reconFailed) break;
        } catch (\Throwable $e) {
            $results[$t] = ['ok' => false, 'error' => mb_substr($e->getMessage(), 0, 200)];
            $errState = function_exists('reconProgressRead') ? reconProgressRead() : [];
            reconProgress(['running' => false, 'done' => true, 'stale' => true,
                'error' => $e->getMessage(),
                'checkpoint' => is_array($errState['checkpoint'] ?? null) ? $errState['checkpoint'] : null,
                'log_add' => ['❌ مغایرت‌گیری دوره‌ای: ' . mb_substr($e->getMessage(), 0, 180)
                    . ' — checkpoint حفظ شد']]);
            break;
        }
    }

    $out['ran'] = true;
    $out['results'] = $results;
    $st['last_finish'] = time();
    $st['last_results'] = $results;
    reconAutoStateSave($st);

    /* v10.121: مسیر اصلی مغایرت دوره‌ای = جدول + matrixFix */
    $wantMatrix = !empty($cfg['build_matrix']) || !empty($cfg['apply']) || !empty($cfg['fix_price'])
        || !empty($cfg['enqueue_missing']) || (isset($cfg['matrix_fix']) ? !empty($cfg['matrix_fix']) : true);
    if (!$reconBlocked && $wantMatrix && function_exists('matrixJobRun')) {
        try {
            reconProgress(['log_add' => ['📊 ساخت جدول مقایسه (مسیر ماتریس)…']]);
            $mx = matrixJobRun(['source' => 'recon_auto', 'background' => false, 'profile' => 'all']);
            $sum = is_array($mx['summary'] ?? null) ? $mx['summary'] : [];
            $out['matrix'] = [
                'ok' => !empty($mx['ok']),
                'total' => (int)($sum['total'] ?? ($mx['row_count'] ?? 0)),
                'mismatch' => (int)($sum['price_mismatch'] ?? 0),
                'missing_woo' => (int)($sum['missing_woo'] ?? 0),
                'missing_bsl' => (int)($sum['missing_bsl'] ?? 0),
                'error' => (string)($mx['error'] ?? ''),
            ];
            $st['last_matrix'] = $out['matrix'];
            $st['last_matrix_at'] = time();
            reconAutoStateSave($st);
            reconProgress(['log_add' => [
                !empty($mx['ok'])
                    ? ('✅ جدول: ' . (int)$out['matrix']['total'] . ' · مغایرت ' . (int)$out['matrix']['mismatch'])
                    : ('⚠️ جدول: ' . (string)($out['matrix']['error'] ?? 'ناموفق')),
            ]]);
        } catch (\Throwable $e) {
            $out['matrix'] = ['ok' => false, 'error' => mb_substr($e->getMessage(), 0, 160)];
        }
    }

    $doFix = !empty($cfg['apply']) || !empty($cfg['fix_price']) || !empty($cfg['enqueue_missing'])
        || !empty($cfg['matrix_fix']);
    if (!$reconBlocked && $doFix && !empty($out['matrix']['ok']) && function_exists('matrixFixRun')) {
        /* recon_auto قبلاً فقط recon.lock داشت و می‌توانست همزمان با دکمهٔ
           «اصلاح جدول» روی همان نتیجه API بزند. مالکیتِ lock خودِ matrix_fix
           را هم بگیر تا Task Manager و cron یک worker مشترک داشته باشند. */
        $fxLockFile = SYNC_MATRIX_FIX_LOCK_FILE;
        $fxLockFp = @fopen($fxLockFile, 'c');
        if (!$fxLockFp || !@flock($fxLockFp, LOCK_EX | LOCK_NB)) {
            if (is_resource($fxLockFp)) @fclose($fxLockFp);
            $out['matrix_fix'] = ['ok' => false, 'running' => true, 'error' => 'یک اصلاح جدول در حال اجراست'];
        } else {
            /* stop قدیمی را زیرِ lock مصرف کن؛ stop تازه‌ای که کاربر بعد از
               این نقطه بفرستد برای matrixFixRun باقی می‌ماند. */
            matrixFixStopClear();
            try {
                $scope = 'all';
                if (!empty($cfg['woo']) && empty($cfg['bsl'])) $scope = 'woo';
                elseif (!empty($cfg['bsl']) && empty($cfg['woo'])) $scope = 'bsl';
                reconProgress(['log_add' => ['🔧 اصلاح از جدول — scope=' . $scope]]);
                $fx = matrixFixRun(['scope' => $scope, 'source' => 'recon_auto', 'delay_ms' => 120]);
                $out['matrix_fix'] = [
                    'ok' => !empty($fx['ok']),
                    'total' => (int)($fx['total'] ?? 0),
                    'ok_n' => (int)($fx['ok_n'] ?? 0),
                    'fail_n' => (int)($fx['fail_n'] ?? 0),
                    'sent' => (int)($fx['sent'] ?? 0),
                    'deleted' => (int)($fx['deleted'] ?? 0),
                    'priced' => (int)($fx['priced'] ?? 0),
                ];
                $st['last_matrix_fix'] = $out['matrix_fix'];
                $st['last_matrix_fix_at'] = time();
                reconAutoStateSave($st);
                reconProgress(['log_add' => [
                    '✅ اصلاح جدول: ✅' . (int)$out['matrix_fix']['ok_n']
                    . ' · ❌' . (int)$out['matrix_fix']['fail_n']
                    . ' · 💰' . (int)$out['matrix_fix']['priced']
                    . ' · 📤' . (int)$out['matrix_fix']['sent']
                    . ' · 🗑' . (int)$out['matrix_fix']['deleted'],
                ]]);
            } catch (\Throwable $e) {
                $out['matrix_fix'] = ['ok' => false, 'error' => mb_substr($e->getMessage(), 0, 160)];
            } finally {
                @flock($fxLockFp, LOCK_UN); @fclose($fxLockFp);
            }
        }
    }

    if (!empty($cfg['notify']) && function_exists('notifSend')) {
        $lines = ['⚖ مغایرت دوره‌ای v' . APP_VERSION . ' (جدول)'];
        foreach ($results as $t => $r) {
            $lbl = $t === 'woo' ? 'ووکامرس' : 'باسلام';
            if (empty($r['ok'])) { $lines[] = "❌ {$lbl}: " . ($r['error'] ?? 'خطا'); continue; }
            $lines[] = "✓ {$lbl}: مقصد " . (int)$r['remote']
                . ' · در مبدأ نیست ' . (int)$r['extra']
                . ' · مغایرت قیمت ' . (int)$r['diff']
                . ' · در مقصد نیست ' . (int)$r['missing']
                . ' · یکسان ' . (int)$r['matched'];
            if (!empty($r['repriced']) || !empty($r['deleted'])) {
                $lines[] = '  اعمال: قیمت ' . (int)$r['repriced'] . ' · حذف/بایگانی ' . (int)$r['deleted'];
            }
            if (!empty($r['enqueue_products']) || !empty($r['enqueued'])) {
                $lines[] = '  📤 صف سینک: ' . (int)($r['enqueue_products'] ?? 0)
                    . ' محصول · ' . (int)($r['enqueued'] ?? 0) . ' ردیف';
            }
        }
        if (!empty($out['matrix'])) {
            $mx = $out['matrix'];
            if (!empty($mx['ok'])) {
                $lines[] = '📊 جدول: ' . (int)($mx['total'] ?? 0) . ' · مغایرت ' . (int)($mx['mismatch'] ?? 0)
                    . ' · نیست WC ' . (int)($mx['missing_woo'] ?? 0)
                    . ' · نیست غرفه ' . (int)($mx['missing_bsl'] ?? 0);
            } else {
                $lines[] = '📊 جدول: خطا — ' . (string)($mx['error'] ?? '');
            }
        }
        if (!empty($out['matrix_fix'])) {
            $fx = $out['matrix_fix'];
            if (!empty($fx['ok'])) {
                $lines[] = '🔧 اصلاح: ✅' . (int)($fx['ok_n'] ?? 0) . ' · ❌' . (int)($fx['fail_n'] ?? 0)
                    . ' · 💰' . (int)($fx['priced'] ?? 0) . ' · 📤' . (int)($fx['sent'] ?? 0)
                    . ' · 🗑' . (int)($fx['deleted'] ?? 0);
            } else {
                $lines[] = '🔧 اصلاح: خطا — ' . (string)($fx['error'] ?? '');
            }
        }
        $lines[] = '🕐 ' . date('Y/m/d H:i');
        try { notifSend($cn, implode("\n", $lines), 'sync'); } catch (\Throwable $e) {}
    }
    return $out;
    } finally {
        @flock($reconLockFp, LOCK_UN); @fclose($reconLockFp);
    }
}

/**
 * v10.107: تیک دوره‌ای اصلاح دسته با AI و/یا حافظهٔ یادگیری
 */
function catfixAutoTick(array $cn, int $now = 0): array {
    if ($now <= 0) $now = time();
    $cfg = catfixAutoCfg($cn);
    $out = ['ok' => true, 'ran' => false, 'skipped' => ''];
    if (empty($cfg['enabled'])) { $out['skipped'] = 'disabled'; return $out; }

    $st = catfixAutoStateLoad();
    $mode = (string)$cfg['mode'];
    $opts = [
        'quorum' => (int)$cfg['quorum'],
        'use_learn' => !empty($cfg['use_learn']),
        'all_vendors' => !empty($cfg['all_vendors']),
        'periodic' => true,
    ];
    // learned-only mode: force use_learn and light AI fallback
    if ($mode === 'learned') {
        $opts['use_learn'] = true;
        $mode = 'master'; // AI fallback when learn misses
        $opts['learn_first'] = true;
    }
    $oldCat = is_file(CATFIX_PROGRESS_FILE)
        ? json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true) : [];
    $oldCatCp = is_array($oldCat['checkpoint'] ?? null) ? $oldCat['checkpoint'] : null;
    $catResume = $oldCatCp !== null && (string)($oldCat['mode'] ?? $mode) === $mode
        && (empty($oldCat['done']) || !empty($oldCat['stale']) || !empty($oldCat['stopped']));
    $last = (int)($st['last_run'] ?? 0);
    $ivSec = max(3600, (int)$cfg['interval_h'] * 3600);
    if (!$catResume && $last > 0 && ($now - $last) < $ivSec) {
        $out['skipped'] = 'not_due';
        $out['next_in'] = $ivSec - ($now - $last);
        return $out;
    }
    /* CATFIX_LOCK_FILE دائمی است؛ فقط flock مالکیت را تعیین می‌کند. */
    /* v10.130: scheduled catfix uses the same exclusive lock and checkpoint
       as the manual endpoint, so a stale manual worker cannot be replaced
       by a fresh periodic run and two category PATCH loops cannot overlap. */
    $catLockFp = @fopen(CATFIX_LOCK_FILE, 'c');
    if (!$catLockFp || !flock($catLockFp, LOCK_EX | LOCK_NB)) {
        if ($catLockFp) @fclose($catLockFp);
        $out['skipped'] = 'busy'; return $out;
    }
    $st['last_run'] = $now;
    catfixAutoStateSave($st);
    $catStartedAt = (int)($oldCatCp['started_at'] ?? time());
    catfixProgress(['running' => true, 'done' => false, 'stale' => false, 'mode' => $mode,
        'started_at' => $catStartedAt, 'phase' => $catResume ? 'resume' : 'start',
        'checkpoint' => $oldCatCp ?: ['started_at' => $catStartedAt],
        'log_add' => [$catResume ? '↻ ادامهٔ خودکار اصلاح دسته از checkpoint' : '⏰ شروع اصلاح دوره‌ای دسته']]);
    /* یک stop قدیمی نباید resume خودکارِ کران بعدی را فوراً متوقف کند. */
    catfixClearStop();

    try {
        if (!function_exists('catfixRun')) {
            $out['ok'] = false; $out['error'] = 'catfixRun missing'; return $out;
        }
        $rep = catfixRun($cn, $mode, $opts, $catResume ? $oldCatCp : null);
        $out['ran'] = true;
        $out['report'] = [
            'ok' => !empty($rep['ok']),
            'fixed' => (int)($rep['fixed'] ?? 0),
            'failed' => (int)($rep['failed'] ?? 0),
            'no_cat' => (int)($rep['no_cat'] ?? 0),
            'total' => (int)($rep['total'] ?? 0),
            'learned_hits' => (int)($rep['learned_hits'] ?? 0),
            'msg' => (string)($rep['msg'] ?? ''),
            'error' => (string)($rep['error'] ?? ''),
        ];
        $st['last_finish'] = time();
        $st['last_report'] = $out['report'];
        catfixAutoStateSave($st);

        if (!empty($cfg['notify']) && function_exists('notifSend') && !empty($rep['ok'])) {
            $msg = "📂 اصلاح دوره‌ای دسته باسلام\n"
                . '✅ اصلاح‌شده: ' . (int)($rep['fixed'] ?? 0)
                . ' · یادگیری: ' . (int)($rep['learned_hits'] ?? 0)
                . ' · ناموفق: ' . (int)($rep['failed'] ?? 0)
                . ' · کل: ' . (int)($rep['total'] ?? 0)
                . "\n🕐 " . date('Y/m/d H:i');
            try { notifSend($cn, $msg, 'sync'); } catch (\Throwable $e) {}
        }
    } catch (\Throwable $e) {
        $out['ok'] = false;
        $out['error'] = mb_substr($e->getMessage(), 0, 200);
        $catErr = is_file(CATFIX_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true) : [];
        catfixProgress(['running' => false, 'done' => true, 'stale' => true,
            'error' => $out['error'],
            'checkpoint' => is_array($catErr['checkpoint'] ?? null) ? $catErr['checkpoint'] : null,
            'log_add' => ['❌ اصلاح دوره‌ای دسته: ' . $out['error'] . ' — checkpoint حفظ شد']]);
    } finally {
        @flock($catLockFp, LOCK_UN); @fclose($catLockFp);
    }
    /* catfixRun itself is also used by the manual endpoint and therefore
       returns a report rather than closing the task card. Close this periodic
       invocation explicitly, retaining a stopped/failed checkpoint. */
    if (isset($rep) && is_array($rep)) {
        $catLast = is_file(CATFIX_PROGRESS_FILE)
            ? json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true) : [];
        $catKeep = empty($rep['ok']) || !empty($rep['stopped']) || !empty($rep['partial']);
        catfixProgress(['running' => false, 'done' => true, 'stale' => $catKeep,
            'stopped' => !empty($rep['stopped']), 'result_ok' => !empty($rep['ok']),
            'checkpoint' => $catKeep && is_array($catLast['checkpoint'] ?? null)
                ? $catLast['checkpoint'] : null]);
    }
    return $out;
}


