send_sse('send_info',['msg'=>!empty($iu['ok'])
?"[$n] 🖼 تصویر وصل شد"
:"[$n] ⚠️ تصویر وصل نشد (HTTP ".(int)($iu['code']??0).") — با «عکس‌دار کردن» قابل تکمیل است"]);
}
$sent++;
send_sse('send_ok',['key'=>$pKey,'remote_id'=>$newId,'title'=>$r['body']['name']??'','edit_url'=>rtrim($w['store_url'],'/').'/wp-admin/post.php?post='.$newId.'&action=edit']);
send_sse('send_info',['msg'=>"[$n] ✅ ایجاد موفق: ID#".$newId." - ".mb_substr($r['body']['name']??'',0,40)]);
}else{
$fail++;
$errBody=$r['body']??[];
$errMsg=mb_substr($errBody['message']??($errBody['error']??($r['error']??json_encode($errBody,JSON_UNESCAPED_UNICODE))),0,150);
send_sse('send_fail',['key'=>$pKey,'error'=>$errMsg,'index'=>$i]);
send_sse('send_info',['msg'=>"[$n] ❌ خطای ایجاد (HTTP {$r['code']}): $errMsg"]);
}
usleep(150000);
}
$totalSkipped=$skipped+$fail;send_sse('send_info',['msg'=>"پایان: $sent جدید, $updated آپدیت, $skipped تکراری, $fail خطا از $total محصول"]);
send_sse('send_complete',['sent'=>$sent,'updated'=>$updated,'skipped'=>$skipped,'failed'=>$fail,'total'=>$total]);send_sse('done',[]);exit;
}

if(isset($_GET['action']) && $_GET['action'] === 'woo_backend'){
set_time_limit(0); ignore_user_abort(true);

$wooLockFile=__DIR__.'/woo_backend.lock';
$wooLockFp=fopen($wooLockFile,'c');
if(!flock($wooLockFp,LOCK_EX|LOCK_NB)){
fclose($wooLockFp);
header('Content-Type: application/json; charset=UTF-8');
echo json_encode(['ok'=>false,'error'=>'woo_backend already running','skipped'=>true],JSON_UNESCAPED_UNICODE);
exit;
}
register_shutdown_function(function()use($wooLockFp,$wooLockFile){@flock($wooLockFp,LOCK_UN);@fclose($wooLockFp);});

/* توقف تازه بدون resume نباید با یک kick معمولی بلعیده شود. */
if (file_exists(WOO_STOP_FILE)) {
    $wooExplicitResume = !empty($_GET['resume']) || !empty($_POST['resume']);
    $wooStopAge = time() - (int)@filemtime(WOO_STOP_FILE);
    if (!$wooExplicitResume && $wooStopAge <= WOO_STOP_HOLD_SEC) {
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok'=>true,'stopped'=>true,'started'=>false,
            'msg'=>'ارسال توسط کاربر متوقف شده — برای ادامه از دکمهٔ ادامه استفاده کنید'],JSON_UNESCAPED_UNICODE);
        exit;
    }
    @unlink(WOO_STOP_FILE);
}

header('Content-Type: application/json; charset=UTF-8');
header('Connection: close');
header('Content-Length: '.strlen(json_encode(['ok'=>true,'msg'=>'woo_backend started'],JSON_UNESCAPED_UNICODE)));
echo json_encode(['ok'=>true,'msg'=>'woo_backend started'],JSON_UNESCAPED_UNICODE);
@ob_flush(); @flush();
if(function_exists('fastcgi_finish_request')){fastcgi_finish_request();}

$startedAt=time();$GLOBALS['startedAt']=$startedAt;
$wooSentList=[];$wooUpdatedList=[];$wooSkippedList=[];$wooFailedList=[];$wooLog=[];

function wooBackendProgress($s,$u,$sk,$f,$t,$c,$lt,$log=null,$extra=[]){
global $wooLog,$wooSentList,$wooUpdatedList,$wooSkippedList,$wooFailedList;
if($log!==null){$wooLog[]=$log;}
$totalLog=count($wooLog);
$recentSlice=$totalLog>200?array_slice($wooLog,-200):$wooLog;
/* v10.104: چک‌پوینت را با current=0 bootstrap پایین نیاور */
$__floor=(int)($GLOBALS['_wooResumeFloor']??0);
$cWrite=max((int)$c,$__floor);
$d=['running'=>true,'sent'=>$s,'updated'=>$u,'skipped'=>$sk,'failed'=>$f,'total'=>$t,'last_title'=>$lt,'current'=>$cWrite,'done'=>false,'started_at'=>$GLOBALS['startedAt'],'last_progress_ts'=>time(),'recent_log'=>$recentSlice,'total_log_count'=>$totalLog,'sent_details'=>$wooSentList,'updated_details'=>$wooUpdatedList,'skipped_details'=>$wooSkippedList,'failed_details'=>$wooFailedList,
   'checkpoint'=>['queue_id'=>(string)($GLOBALS['_wooQueueIdNow']??''),'current'=>(int)$cWrite,'total'=>(int)$t,'sent'=>(int)$s,'updated'=>(int)$u,'skipped'=>(int)$sk,'failed'=>(int)$f,'started_at'=>(int)$GLOBALS['startedAt']]];
/* v10.56 (۷۰): فایلِ پیشرفتِ ووکامرس هم مالکیتِ ردیفِ صف را نشان می‌دهد —
   برای اینکه ادامهٔ بعدی مطمئن باشد چک‌پوینت مالِ همین ردیف است. */
if(!empty($GLOBALS['_wooQueueIdNow']))$d['queue_id']=$GLOBALS['_wooQueueIdNow'];
if(!empty($extra))$d=array_merge($d,$extra);
writeProgress(WOO_PROGRESS_FILE,$d);
clearstatcache();
/* v10.56/v10.104: current فقط بالا می‌رود؛ جزئیات کارت هم در ردیف صف */
if(!empty($GLOBALS['_wooQueueIdNow'])){
try{
$__wq=wooReadQueue();$__wchg=false;
foreach($__wq['entries'] as &$__we){
if($__we['id']===$GLOBALS['_wooQueueIdNow']){
$__prevC=(int)($__we['current']??0);
if($cWrite>$__prevC){($__we['current']=$cWrite);($__wchg=true);}
$__bootZero=((int)$s+(int)$u+(int)$sk+(int)$f)===0 && $__floor>0;
if(!$__bootZero){
$__we['sent']=$s;$__we['updated']=$u;$__we['skipped']=$sk;$__we['failed']=$f;
}
if(is_array($wooSentList)&&count($wooSentList)>0){$__we['sent_details']=$wooSentList;$__wchg=true;}
if(is_array($wooUpdatedList)&&count($wooUpdatedList)>0)$__we['updated_details']=$wooUpdatedList;
if(is_array($wooSkippedList)&&count($wooSkippedList)>0)$__we['skipped_details']=$wooSkippedList;
if(is_array($wooFailedList)&&count($wooFailedList)>0)$__we['failed_details']=$wooFailedList;
break;
}
}
unset($__we);
if($__wchg)wooWriteQueue($__wq);
}catch(Exception $__wex){}
}
}

$cn=loadConnections();$w=$cn['woocommerce']??[];
/* v10.82: مستقیم بدون کلید API مجاز است؛ API به کلید نیاز دارد */
$_wooAttempts = function_exists('wooSyncAttemptOrder') ? wooSyncAttemptOrder($w) : ['api'];
$_wooNeedApi = in_array('api', $_wooAttempts, true);
$_wooNeedDirect = in_array('direct', $_wooAttempts, true);
$_wooApiOk = !empty($w['store_url']) && !empty($w['consumer_key']) && !empty($w['consumer_secret']);
$_wooDirectOk = function_exists('wooDirectAvailable') && wooDirectAvailable();
if ($_wooNeedApi && !$_wooApiOk && !($_wooNeedDirect && $_wooDirectOk)) {
writeProgress(WOO_PROGRESS_FILE,['running'=>false,'done'=>true,'sent'=>0,'updated'=>0,'skipped'=>0,'failed'=>0,'total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ تنظیمات ووکامرس ناقص (برای API: آدرس+کلید؛ برای مستقیم: ووکامرس روی همین سایت)'],'total_log_count'=>1,'sent_details'=>[],'updated_details'=>[],'skipped_details'=>[],'failed_details'=>[]]);
exit;
}
if ($_wooNeedDirect && !$_wooDirectOk && !$_wooApiOk) {
writeProgress(WOO_PROGRESS_FILE,['running'=>false,'done'=>true,'sent'=>0,'updated'=>0,'skipped'=>0,'failed'=>0,'total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ همگام مستقیم ممکن نیست — ووکامرس در این PHP لود نیست و API هم تنظیم نشده'],'total_log_count'=>1,'sent_details'=>[],'updated_details'=>[],'skipped_details'=>[],'failed_details'=>[]]);
exit;
}
wooBackendProgress(0,0,0,0,0,0,'','⚙️ حالت: '.implode(' → ', $_wooAttempts)
  .($_wooDirectOk?' · مستقیم آماده':'')
  .($_wooApiOk?' · API آماده':''));


$raw=@file_get_contents(WOO_PRODUCTS_FILE);
$pd=json_decode($raw?:'[]',true)?:[];
/* v10.56 (۷۰): اگر فایلِ مشترکِ محصولات گم شده باشد (مثلاً بعد از کشتنِ
   فرایند)، از فایلِ اختصاصیِ ردیفِ در حالِ اجرا برگردان — وگرنه ادامه
   بلافاصله با «بدونِ محصول» تمام می‌شد. */
if(empty($pd)){
$__wq0=wooReadQueue();
foreach($__wq0['entries'] as $__qe0){
if(($__qe0['status']??'')==='running'){
$__wf=__DIR__.'/woo_queue_products_'.(string)($__qe0['id']??'').'.json';
if(file_exists($__wf)){$pd=json_decode((string)@file_get_contents($__wf)?:'[]',true)?:[];}
break;
}
}
}
if(empty($pd)){
writeProgress(WOO_PROGRESS_FILE,['running'=>false,'done'=>true,'sent'=>0,'updated'=>0,'skipped'=>0,'failed'=>0,'total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ فایل محصولات خالی'],'total_log_count'=>1,'sent_details'=>[],'updated_details'=>[],'skipped_details'=>[],'failed_details'=>[]]);
exit;
}

$total=count($pd);$sent=0;$updated=0;$skipped=0;$fail=0;
$bslDelayMs=max(0,(int)($cn['basalam']['delay_ms']??500));
// v8.21: Read title_suffix from the running woo queue entry config
// v8.56: دستهٔ همین صف هم از همان‌جا خوانده می‌شود تا هر پروفایل بتواند
// دستهٔ ووکامرس خودش را داشته باشد.
$wooTitleSuffix='';
$wooQueueCatId=-1;
$wooQueueProfileKey='';   // v8.65: برای ثبت در دفترچهٔ شناسه‌ها
$wooForceAllRun=false;    // v10.34 (۴۸ج): ارسالِ کامل بدون مقایسه
$wooContentSync=contentSyncOn($cn);   // v8.69: آپدیت محتوای تازه
$wooQueue=wooReadQueue();
$wooRunId='';
foreach($wooQueue['entries'] as $qe){
if(($qe['status']??'')!=='running')continue;
if(!empty($qe['config']['title_suffix']))$wooTitleSuffix=trim($qe['config']['title_suffix']);
if(isset($qe['config']['category_id']))$wooQueueCatId=(int)$qe['config']['category_id'];
if(!empty($qe['config']['force_all']))$wooForceAllRun=true;
$wooQueueProfileKey=(string)($qe['profile_key']??'');
$wooRunId=(string)($qe['id']??'');
break;
}
/* v10.56 (۷۰): برای مالکیتِ فایلِ پیشرفت (queue_id) در ضربان‌های بعد. */
$GLOBALS['_wooQueueIdNow']=$wooRunId;
if($wooTitleSuffix===''){$wooTitleSuffix=trim($cn['basalam']['title_suffix']??'');}
// v8.87: تعدیل قیمت مخصوص ووکامرس (جدا از تنظیم قیمت پروفایل)
$wooPriceCfg=destPriceCfg($cn,'woocommerce');
if($wooPriceCfg['mode']!=='none'){
wooBackendProgress(0,0,0,0,0,0,'','💰 تعدیل قیمت ووکامرس: '
  .($wooPriceCfg['mode']==='percent'?(($wooPriceCfg['val']>=0?'+':'').$wooPriceCfg['val'].'%'):('×'.$wooPriceCfg['val']))
  .($wooPriceCfg['round']>0?(' · گرد به '.$wooPriceCfg['round']):''));
}
// دستهٔ مؤثر: دستهٔ صف (پروفایل) و در نبودش دستهٔ پیش‌فرض تنظیمات عمومی
$wooSendCatId=$wooQueueCatId>=0?$wooQueueCatId:(int)($w['default_category']??0);
$GLOBALS['_currentProductLink']='';

/* v10.56 (۷۰): چک‌پوینتِ ادامه — فایلِ پیشرفت را پُر از اولینِ ضربانِ تازه
   می‌خوانیم (ضربانِ تازه current=0 می‌نویسد و چک‌پوینت از بین می‌رود).
   معنای start: شمارهٔ ۱‌مبنا از اولینِ محصولی که باید (دوباره) پردازش شود.
   فقط وقتی مبنا می‌شود که queue_idِ فایل مالِ همین ردیف باشد. */
$wooPrevProg=readProgress(WOO_PROGRESS_FILE);
$wooPrevQid=trim((string)($wooPrevProg['queue_id']??''));
$wooResumeStart=0;$wooResumeCounters=false;
if($wooRunId!==''&&$wooPrevQid===$wooRunId){
$wooResumeStart=(int)($wooPrevProg['current']??0);
$wooResumeCounters=isset($wooPrevProg['sent']);
}
$wooPostStart=max(0,(int)($_POST['start_index']??0));
$wooPostQid=trim((string)($_POST['queue_id']??''));
if($wooPostStart>0&&$wooRunId!==''&&($wooPostQid===''||$wooPostQid===$wooRunId))$wooResumeStart=max($wooResumeStart,$wooPostStart);
$wooResumeStart=max(0,min($wooResumeStart,$total+1));
/* v10.104: current ردیف صف هم مبنا */
if($wooRunId!==''){
foreach((array)(wooReadQueue()['entries']??[]) as $__weR){
if((string)($__weR['id']??'')===$wooRunId){
$__ec=max(0,(int)($__weR['current']??0));
if($__ec>$wooResumeStart){$wooResumeStart=$__ec;$wooResumeCounters=true;}
if(empty($wooPrevProg['sent_details'])&&!empty($__weR['sent_details'])){
$wooPrevProg['sent_details']=$__weR['sent_details']??[];
$wooPrevProg['updated_details']=$__weR['updated_details']??[];
$wooPrevProg['skipped_details']=$__weR['skipped_details']??[];
$wooPrevProg['failed_details']=$__weR['failed_details']??[];
if(!isset($wooPrevProg['sent'])){$wooPrevProg['sent']=$__weR['sent']??0;$wooPrevProg['updated']=$__weR['updated']??0;$wooPrevProg['skipped']=$__weR['skipped']??0;$wooPrevProg['failed']=$__weR['failed']??0;$wooResumeCounters=true;}
}
break;
}
}
}
$GLOBALS['_wooResumeFloor']=max(0,(int)$wooResumeStart);
if($wooResumeStart>0&&$wooResumeCounters){
$sent=(int)($wooPrevProg['sent']??0);$updated=(int)($wooPrevProg['updated']??0);
$skipped=(int)($wooPrevProg['skipped']??0);$fail=(int)($wooPrevProg['failed']??0);
if(!empty($wooPrevProg['sent_details'])&&is_array($wooPrevProg['sent_details']))$wooSentList=$wooPrevProg['sent_details'];
if(!empty($wooPrevProg['updated_details'])&&is_array($wooPrevProg['updated_details']))$wooUpdatedList=$wooPrevProg['updated_details'];
if(!empty($wooPrevProg['skipped_details'])&&is_array($wooPrevProg['skipped_details']))$wooSkippedList=$wooPrevProg['skipped_details'];
if(!empty($wooPrevProg['failed_details'])&&is_array($wooPrevProg['failed_details']))$wooFailedList=$wooPrevProg['failed_details'];
}

$__wooStartMsg=$wooResumeStart>0
  ?('✅ [v8.22 woo_backend] ادامه از #'.$wooResumeStart.' — '.$total.' محصول')
  :('✅ [v8.22 woo_backend] شروع — '.$total.' محصول');
wooBackendProgress($sent,$updated,$skipped,$fail,$total,max($wooResumeStart,0),'',[$__wooStartMsg]);

foreach($pd as $i=>$p){
