}

$wp=['name'=>$pTitle,'type'=>'simple','regular_price'=>$pPrice,'status'=>$w['default_status']??'draft','manage_stock'=>!empty($w['manage_stock']),'stock_quantity'=>effectiveStock($p,(int)($w['stock_quantity']??10))];   // v10.21 (۳۴الف)
