/* v10.59 (۷۳): همان بستنِ خودکارِ ردیفِ تمام‌شدهٔ بسته‌نشده برای ووکامرس. */
try { $stW = loadConnections(); queueStallCheck('woo', max(120, (int)($stW['stall_after'] ?? 300))); } catch (Throwable $eW) {}
$wooStatusFp = queueBackendLock('woo');
