if (isset($_GET['bsl_products'])) {
header('Content-Type: application/json; charset=UTF-8');
$cn=loadConnections();$bs=$cn['basalam']??[];
if(empty($bs['token'])||empty($bs['vendor_id'])){echo json_encode(['ok'=>false,'error'=>'تنظیمات باسلام ناقص'],JSON_UNESCAPED_UNICODE);exit;}
$page=max(1,(int)($_GET['page']??1));
$perPage=min(1000,max(10,(int)($_GET['per_page']??50)));
/* v9.47: انتخاب غرفه. مقدار «all» یا خالی یعنی همهٔ غرفه‌های فعال؛
   در غیر این صورت شناسهٔ غرفهٔ مشخص. */
$shopParam=(string)($_GET['shop_id']??'');
$allShops=bslAllShops($cn);
$shops=[];
if($shopParam===''||$shopParam==='all'||$shopParam==='0'){
    $shops=$allShops;
}else{
    foreach($allShops as $sp){ if((int)($sp['vendor_id']??0)===(int)$shopParam){ $shops[]=$sp; break; } }
    if(empty($shops))$shops=$allShops;   // ناشناخته → همه
}
if(empty($shops)){echo json_encode(['ok'=>false,'error'=>'هیچ غرفه‌ای تنظیم نشده'],JSON_UNESCAPED_UNICODE);exit;}
// غرفهٔ فعلی (برای دراپ‌داون) — پیش‌فرض همان غرفهٔ اول یا انتخاب‌شده
$curShopId=$shopParam===''||$shopParam==='all'||$shopParam==='0'?0:(int)$shopParam;

$statusParam=$_GET['status']??'active';
$statusMap=[
'active'=>['2976'],
'approved'=>['2976'],
'inactive'=>['3790'],
'not_approved'=>['3567'],
'pending'=>['3568'],
'archived'=>['4184'],
'all'=>['2976','3790','3567','3568','4184','2977','2978','3248','4221'],
];
$statusValues=$statusMap[$statusParam]??$statusMap['active'];
/* v8.82: جست‌وجو سمت سرور.
   تا حالا فیلتر فقط روی همان ردیف‌هایی بود که در مرورگر نمایش داده شده
   بودند. اگر محصول در صفحهٔ چهارمِ فهرست بود، جست‌وجو پیدایش نمی‌کرد و
   کاربر فکر می‌کرد اصلاً وجود ندارد — دقیقاً همان چیزی که موقع دیدن
   «بازگردانی ناموفق» پیش می‌آمد. */
$q=trim((string)($_GET['q']??''));
$searchId=(int)preg_replace('~[^0-9]~','',$q);

/* v9.47: حلقهٔ روی غرفه‌های انتخاب‌شده — هر محصول با shop/shop_name برچسب می‌خورد
   تا در مودال معلوم باشد مالِ کدام غرفه است. */
$data=[];$totalPage=1;$totalCount=0;$foundBy=$q!==''?'title':'';$cats=[];
$isAll=count($shops)>1;

/* اگر عدد وارد شده، ممکن است شناسهٔ محصول باشد؛ مستقیم بخوانش.
   محصولی که وضعیتش در هیچ‌کدام از سربرگ‌ها نیست، فقط از این راه پیدا می‌شود. */
if($q!==''&&$searchId>0&&mb_strlen($q)<=12&&preg_match('~^\s*\d+\s*$~',$q)){
$foundOne=null;
foreach($shops as $sp){
$sTk=(string)$sp['token'];$sVid=(int)$sp['vendor_id'];
$one=bslReqRead($sTk,'products/'.$searchId);
$row=$one['body']['data']??($one['body']??null);
if(!empty($one['ok'])&&is_array($row)&&(int)($row['id']??0)>0){
if(is_array($row)){$row['shop']=$sVid;$row['shop_name']=(string)($sp['shop_name']??'');}
$foundOne=$row;break;
}
}
if($foundOne){
$cats=bslCatsAll($shops[0]['token']); /* v10.41 (۵۵): از کشِ مشترک */
echo json_encode(['ok'=>true,'products'=>[$foundOne],'page'=>1,'total_page'=>1,'total_count'=>1,'per_page'=>$perPage,'categories'=>$cats,'status'=>$statusParam,'found_by'=>'id','shop_id'=>$curShopId,'shops'=>$allShops],JSON_UNESCAPED_UNICODE);
exit;
}
}

/* فهرست عادی — برای هر غرفهٔ انتخاب‌شده صفحه را می‌گیریم و جمع می‌کنیم.
   در حالت «همه» از هر غرفه همان صفحه را می‌گیریم و برچسب غرفه می‌زنیم.

   v9.83: سه اصلاح مهم اینجا انجام شد، چون فهرست بی‌صدا خالی برمی‌گشت:
   ۱) خواندن با bslReqRead تا سیگنالِ توقفِ ارسال جلوی فهرست را نگیرد.
   ۲) خطای هر غرفه جمع می‌شود و اگر هیچ غرفه‌ای پاسخ نداد، به‌جای
      «صفر محصول»، پیام خطای واقعی (۴۰۱/۴۰۳/شبکه) نشان داده می‌شود.
   ۳) اگر مسیر اصلی خطا داد، مسیر جایگزینِ products?vendor_ids= هم
      امتحان می‌شود. */
$shopErrs=[];$okShops=0;
foreach($shops as $sp){
$sTk=(string)$sp['token'];$sVid=(int)$sp['vendor_id'];
if($sTk===''||$sVid<=0)continue;
$sName=(string)($sp['shop_name']??('#'.$sVid));
$stQ='';foreach($statusValues as $sv){$stQ.='&statuses='.$sv;}
$url='vendors/'.$sVid.'/products?page='.$page.'&per_page='.$perPage.$stQ;
if($q!==''){$url.='&title='.urlencode($q);}
$r=bslReqRead($sTk,$url);
$viaAlt=false;
if(empty($r['ok'])){
// v9.83: مسیر جایگزین — بعضی توکن‌ها فقط روی این مسیر مجوز دارند
$alt='products?vendor_ids='.$sVid.'&page='.$page.'&per_page='.$perPage.$stQ;
if($q!==''){$alt.='&title='.urlencode($q);}
$r2=bslReqRead($sTk,$alt);
if(!empty($r2['ok'])){$r=$r2;$viaAlt=true;}
else{
$shopErrs[]=$sName.': '.bslApiError($r,'دریافت محصولات ناموفق','vendors/{id}/products','vendor.product.read');
continue;
}
}
$okShops++;
$rows=bslRowsOf($r['body']);
/* v9.83: مسیر جایگزین ممکن است پارامتر statuses را نادیده بگیرد. اگر
   فیلترِ سربرگ واقعاً خالی است، نباید محصولاتِ سربرگ‌های دیگر قاطی
   شوند — پس همان‌جا خودمان بر اساس وضعیت فیلتر می‌کنیم. */
if($viaAlt&&$statusParam!=='all'){
$want=array_map('intval',$statusValues);
$rows=array_values(array_filter($rows,function($row)use($want){
if(!is_array($row))return false;
$ps=$row['status']??($row['revision']['data']['status']??0);
$sv=is_array($ps)?(int)($ps['value']??0):(int)$ps;
return in_array($sv,$want,true);
}));
}
foreach($rows as $row){
if(is_array($row)){$row['shop']=$sVid;$row['shop_name']=(string)($sp['shop_name']??'');$data[]=$row;}
}
$totalCount+=$viaAlt?count($rows):bslMetaInt($r['body'],'total_count',count($rows));
$tp=bslMetaInt($r['body'],'total_page',1);
if(!$isAll){$totalPage=max(1,$tp);}
}

/* v9.83: هیچ غرفه‌ای پاسخ نداد → خطا را نشان بده، نه فهرست خالی */
if($okShops===0&&$shopErrs){
echo json_encode(['ok'=>false,'error'=>implode(' | ',array_slice($shopErrs,0,3)),
'errors'=>$shopErrs,'shop_id'=>$curShopId,'shops'=>$allShops],JSON_UNESCAPED_UNICODE);
exit;
}

/* v8.82: فیلتر «title» سمت باسلام تطبیق سادهٔ رشته‌ای است و به نیم‌فاصله،
   ی/ک عربی و پسوند «(کد: ۱)» حساس. مقایسهٔ خودمان همهٔ این‌ها را یکسان
   می‌بیند، پس اگر سرور چیزی برنگرداند خودمان کل غرفه را می‌گردیم.
   محصولی که «بازگردانی ناموفق» خورده دقیقاً همین‌جا گم می‌شد. */
/* v10.44 (۵۸): شرط از «فهرست کاملاً خالی» به «جست‌وجو در جریان است»
   تغییر کرد. تا اینجا اگر صفحهٔ اولِ سرور *یک* تطبیق برمی‌گرداند،
   جست‌وجوی عمیق اصلاً اجرا نمی‌شد و بقیهٔ صفحه‌ها هرگز دیده نمی‌شدند —
   دقیقاً همان چیزی که کاربر گزارش کرد: «جستجو فقط صفحهٔ اول را می‌گردد».
   حالا همیشه کلِ غرفه پیمایش می‌شود و نتیجهٔ صفحهٔ اول هم داخلِ همان
   مجموعه ادغام می‌شود (بدونِ تکرارِ شناسه). */
if($q!==''){
$want=reconNormTitle($q);
$wantBare=reconNormTitle(stripProductCode($q));
$hits=[];$seenIds=[];$deepT0=microtime(true);$deepCut=false;
foreach(($page<=1?$data:[]) as $row){
if(!is_array($row))continue;
$rid=(int)($row['id']??0);
if($rid>0&&isset($seenIds[$rid]))continue;
if($rid>0)$seenIds[$rid]=true;
$hits[]=$row;
}
$allSt='';foreach(bslAllStatuses() as $sv){$allSt.='&statuses='.$sv;}
foreach($shops as $sp){
$sTk=(string)$sp['token'];$sVid=(int)$sp['vendor_id'];
if($sTk===''||$sVid<=0)continue;
for($pg=1;$pg<=DEDUP_SEARCH_MAX_PAGES;$pg++){
$sr=bslReqRead($sTk,'vendors/'.$sVid.'/products?page='.$pg.'&per_page=100'.$allSt);
if(empty($sr['ok']))break;
$rows=bslRowsOf($sr['body']);
if(!$rows)break;
foreach($rows as $row){
if(!is_array($row))continue;
$t=(string)($row['title']??'');
$nt=reconNormTitle($t);
$nb=reconNormTitle(stripProductCode($t));
if($nt===''&&$nb==='')continue;
if($nt===$want||$nb===$wantBare
   ||($want!==''&&mb_strpos($nt,$want)!==false)
   ||($wantBare!==''&&mb_strpos($nb,$wantBare)!==false)){
$rid=(int)($row['id']??0);
if($rid>0&&isset($seenIds[$rid]))continue;   /* v10.44: تکراری نشود */
if($rid>0)$seenIds[$rid]=true;
$row['shop']=$sVid;$row['shop_name']=(string)($sp['shop_name']??'');
$hits[]=$row;
}
}
$tp=bslMetaInt($sr['body'],'total_page',1);
if($pg>=max(1,$tp))break;
/* v10.44 (۵۸): قبلاً همین‌جا با پرشدنِ یک صفحه (perPage) پیمایش قطع
   می‌شد، پس شمارشِ «کل نتایج» هم غلط بود. حالا تا سقفِ امن ادامه
   می‌دهیم و همهٔ تطبیق‌ها را می‌شماریم. سقفِ زمانی هم می‌گذاریم تا
   غرفهٔ خیلی بزرگ باعثِ تایم‌اوتِ درخواست نشود. */
if(count($hits)>=DEDUP_SEARCH_MAX_HITS)break;
if((microtime(true)-$deepT0)>DEDUP_SEARCH_MAX_SEC){$deepCut=true;break;}
}
if($deepCut||count($hits)>=DEDUP_SEARCH_MAX_HITS)break;
}
/* v10.44 (۵۸): صفحه‌بندیِ نتیجه روی *کلِ* تطبیق‌ها انجام می‌شود، نه روی
   صفحهٔ اولِ سرور؛ پس total_count و total_page واقعی‌اند. */
$totalCount=count($hits);
$totalPage=max(1,(int)ceil($totalCount/max(1,$perPage)));
$data=array_slice($hits,max(0,($page-1)*$perPage),$perPage);
$foundBy=$hits?'deep':$foundBy;
if($deepCut&&$shopErrs===[]){$shopErrs[]='جست‌وجو به سقفِ زمانی رسید؛ نتایج ممکن است کامل نباشد';}
}

$cats=[];
$cr=bslReqRead((string)($shops[0]['token']??''),'categories');
if($cr['ok']){$cData=$cr['body']['data']??[];if(is_array($cData)){$cFlat=function($items,$lv=0)use(&$cFlat){$o=[];foreach($items as $c){$t=trim($c['title']??$c['name']??'');$id=(int)($c['id']??0);if($id>0)$o[]=['id'=>$id,'name'=>$t,'level'=>$lv];$ch=$c['children']??[];if(is_array($ch)&&count($ch)>0){foreach($cFlat($ch,$lv+1)as $s)$o[]=$s;}}return $o;};$cats=$cFlat($cData,0);}}
/* v9.83: اگر فهرست خالی بود ولی خطایی هم بوده، پیام را همراه پاسخ بفرست
   تا مودال به‌جای سکوت، دلیلِ خالی بودن را نشان بدهد. */
$warn=((!$data||!empty($deepCut))&&$shopErrs)?implode(' | ',array_slice($shopErrs,0,3)):'';
echo json_encode(['ok'=>true,'products'=>$data,'page'=>$page,'total_page'=>$totalPage,'total_count'=>$totalCount,'per_page'=>$perPage,'categories'=>$cats,'status'=>$statusParam,'q'=>$q,'found_by'=>$foundBy,'warn'=>$warn,'shop_id'=>$curShopId,'shops'=>$allShops],JSON_UNESCAPED_UNICODE);
exit;
}

if (isset($_GET['bsl_rejected_cats'])) {
header('Content-Type: application/json; charset=UTF-8');
$cn=loadConnections();$bs=$cn['basalam']??[];
if(empty($bs['token'])||empty($bs['vendor_id'])){echo json_encode(['ok'=>false,'error'=>'تنظیمات باسلام ناقص'],JSON_UNESCAPED_UNICODE);exit;}
$tk=$bs['token'];$vid=(int)$bs['vendor_id'];
$rejected=[];$cats=[];

for($pg=1;$pg<=20;$pg++){
$r=bslReq($tk,'GET','vendors/'.$vid.'/products?page='.$pg.'&per_page=100&statuses=3567');
if(!$r['ok'])break;
$data=$r['body']['data']??[];
if(empty($data))break;
foreach($data as $p){
$rev=$p['revision']??[];
$revData=$rev['data']??[];
$rawStatus=$p['status']??$revData['status']??0;
$sv=(is_array($rawStatus)&&!empty($rawStatus['value']))?(int)$rawStatus['value']:(int)$rawStatus;
if($sv===3567){
$rejReasons=$rev['rejection_reasons']??[];
$catReject=false;$catMsg='';
foreach($rejReasons as $rr){
if((int)($rr['value']??0)===6046){$catReject=true;$catMsg=$rr['name']??$rr['description']??'دسته‌بندی نادرست';}
}
if($catReject){
$catObj=$revData['category']??$p['category']??null;
$catTitle=is_array($catObj)?($catObj['title']??''):(string)($p['category_id']??'');
$catId=is_array($catObj)?(int)($catObj['id']??0):(int)($p['category_id']??0);
$rejected[]=['id'=>$p['id'],'title'=>$p['title']??$revData['title']??'','status'=>$sv,'cat_reject_msg'=>$catMsg,'current_cat_id'=>$catId,'current_cat_title'=>$catTitle];
}
}
}
if($pg>=2&&count($data)<100)break;
}

$cats=bslCatsAll($tk); /* v10.41 (۵۵): از کشِ مشترک */
echo json_encode(['ok'=>true,'rejected'=>$rejected,'categories'=>$cats],JSON_UNESCAPED_UNICODE);
exit;
}

if(isset($_GET['bsl_fix_ai_cat'])){
