$sse(['type'=>'step','msg'=>'بررسی علل رد محصول...']);

$rejTexts=[];
foreach($rejReasons as $rr){
$rrDesc=trim($rr['description']??'');
if($rrDesc!==''&&mb_strlen($rrDesc,'UTF-8')>5){$aiText.=($aiText?' ':'').$rrDesc;$rejTexts[]=$rrDesc;}
