}
if($aiText===''){
$sse(['type'=>'error','msg'=>'متن بررسی هوش مصنوعی یافت نشد — محصول هیچ توصیه AI یا علت رد ندارد']);exit;
}
$sse(['type'=>'step','msg'=>'متن AI یافت شد: '.mb_substr($aiText,0,200)]);

$sse(['type'=>'step','msg'=>'دریافت دسته‌بندی‌ها از باسلام...']);
$cats=[];
