$prevN=(int)($tr['tried'][(string)$aiCatId]['n']??1);
catTriedRecord($pId,$aiCatId,$catName,'ai_text','skipped',$pName,$curCat);
$sse(['type'=>'item','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'status'=>'skipped','catId'=>$aiCatId,'catName'=>$catName,'msg'=>'رد شد: «'.$catName.'» قبلاً '.aiFaNum($prevN).' بار امتحان و رد شده']);
continue;
}
$sse(['type'=>'progress','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'step'=>'patching','catId'=>$aiCatId,'catName'=>$catName]);

$bu=['category_id'=>$aiCatId,'status'=>3568];
$r2=bslReq($tk,'PATCH','products/'.$pId,$bu);
if($r2['code']===404)$r2=bslReq($tk,'PATCH','vendors/'.$vid.'/products/'.$pId,$bu);
if($r2['ok']&&!empty($r2['body']['id'])){
$fixed++;
catTriedRecord($pId,$aiCatId,$catName,'ai_text','applied',$pName,$curCat);
$sse(['type'=>'item','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'status'=>'fixed','catId'=>$aiCatId,'catName'=>$catName,'msg'=>'اصلاح شد و ارسال به بررسی مجدد: '.$catName.' ('.$aiCatId.')']);
}else{
$failed++;
catTriedRecord($pId,$aiCatId,$catName,'ai_text','failed',$pName,$curCat);
$errDetail=($r2['body']['message']??($r2['body']['error']??''));
$sse(['type'=>'item','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'status'=>'failed','catId'=>$aiCatId,'catName'=>$catName,'msg'=>'PATCH ناموفق: '.$errDetail]);
}
usleep(500000);
}
$sse(['type'=>'done','fixed'=>$fixed,'failed'=>$failed,'no_ai'=>$noAi,'no_cat'=>$noCat,'skipped'=>$skipSame+$skipTried,'skip_same'=>$skipSame,'skip_tried'=>$skipTried,'total'=>$total,'msg'=>'✅ اصلاح شد: '.$fixed.' | بدون AI: '.$noAi.' | دسته یافت نشد: '.$noCat.' | تکراری/همان دسته: '.($skipSame+$skipTried).' | ناموفق: '.$failed.' (از '.$total.' محصول)']);
if(function_exists('fastcgi_finish_request'))fastcgi_finish_request();
exit;
}

/* v9.49: «اصلاح بقیه با مستر» — برای محصولاتِ تأیید نشده (به دلیل دستهٔ
   اشتباه) از مدل مستر (بهترین کاندید از نظر آمار رأی‌ها) می‌پرسد و دستهٔ
   پیشنهادی را اعمال می‌کند؛ هر بار رأی ثبت می‌شود و همان دسته هم در
   حافظهٔ یادگیری می‌نشیند تا دفعهٔ بعد همین انتخاب برای بقیهٔ محصولاتِ
   هم‌کلمه به‌کار برود. SSE مثل bsl_fix_ai_cat_batch. */
if(isset($_GET['bsl_master_fix'])){
header('Content-Type: text/event-stream; charset=UTF-8');
header('Cache-Control: no-cache');
header('Connection: keep-alive');
header('X-Accel-Buffering: no');
set_time_limit(0);ignore_user_abort(true);
$cn=loadConnections();$bs=$cn['basalam']??[];
if(empty($bs['token'])||empty($bs['vendor_id'])){
echo "data: ".json_encode(['type'=>'error','msg'=>'تنظیمات باسلام ناقص'],JSON_UNESCAPED_UNICODE)."\n\n";if(ob_get_level())ob_flush();flush();exit;
}
$tk=$bs['token'];$vid=(int)$bs['vendor_id'];
$sse=function($d){echo "data: ".json_encode($d,JSON_UNESCAPED_UNICODE)."\n\n";if(ob_get_level())ob_flush();flush();};
$sse(['type'=>'step','msg'=>'دریافت مدل مستر و کاندیدها...']);
$cands=aiCandidates();
if(empty($cands)){
$sse(['type'=>'error','msg'=>'هیچ مدل کاندیدی انتخاب نشده — اول در بخش 🤖 چند مدل کاندید اضافه کنید']);exit;
}
$providers=aiProvidersLoad();
$masterKey=aiMasterKey();
$master=null;
foreach($cands as $c){ if($c['key']===$masterKey){$master=$c;break;} }
if($master===null)$master=$cands[0];
$mp=$providers[$master['provider']]??null;
if($mp===null){
$sse(['type'=>'error','msg'=>'ارائه‌دهندهٔ مدل مستر یافت نشد']);exit;
}
$sse(['type'=>'step','msg'=>'مستر: '.$master['providerName'].' / '.$master['model']]);
$net=aiNetCfg();
$candKeys=array_map(function($c){return $c['key'];},$cands);

$sse(['type'=>'step','msg'=>'دریافت دسته‌بندی‌ها از باسلام...']);
$cats=[];
$cats=bslCatsAll($tk); /* v10.41 (۵۵): از کشِ مشترک */
if(empty($cats)){
$sse(['type'=>'error','msg'=>'دسته‌بندی‌ها بارگذاری نشد']);exit;
}
bslSetCatNameMap($cats);
$leafCats=[];
foreach($cats as $c){if(($c['level']??0)>=2)$leafCats[]=$c;}
if(empty($leafCats))$leafCats=$cats;
$catList=aiCatListBuild($leafCats,[]);
$sse(['type'=>'step','msg'=>count($cats).' دسته دریافت شد ('.count($leafCats).' دستهٔ برگ)']);

/* v10.12 (۲۵): حالتِ چندمدلی. اگر بیش از یک کاندید انتخاب شده باشد،
   به‌جای پرسیدنِ ترتیبیِ فقط مستر، از موتورِ اجماع استفاده می‌کنیم:
   موازی‌سازی + توقفِ زودهنگام + رأیِ وزنی + کشِ هم‌کلمه. */
$multi=count($cands)>1&&(($_GET['single'] ?? '')!=='1');
$quorum=max(1,min(count($cands),(int)($_GET['quorum']??2)));
if($multi){
$sse(['type'=>'step','msg'=>'حالت چندمدلی: '.aiFaNum(count($cands)).' مدل کاندید — حدنصابِ مرحلهٔ اول: '.aiFaNum($quorum).' مدل (در صورت توافق، بقیه پرسیده نمی‌شوند)']);
}else{
$sse(['type'=>'step','msg'=>'حالت تک‌مدلی (مستر)']);
}

$sse(['type'=>'step','msg'=>'دریافت محصولات ردشده (تأیید نشده)...']);
$allProducts=[];
for($pg=1;$pg<=20;$pg++){
$r=bslReq($tk,'GET','vendors/'.$vid.'/products?page='.$pg.'&per_page=100&statuses=3567');
if(!$r['ok'])break;
$data=$r['body']['data']??[];
if(empty($data))break;
$tp=max(1,(int)($r['body']['total_page']??1));
foreach($data as $p)$allProducts[]=$p;
if($pg>=$tp)break;
}
$total=count($allProducts);
$sse(['type'=>'start','total'=>$total,'msg'=>'شروع مشورت '.($multi?'چندمدلی':'با مستر').' برای '.count($allProducts).' محصول...']);
$fixed=0;$failed=0;$noCat=0;$idx=0;$skipSame=0;$skipTried=0;$askTotal=0;$cacheHits=0;
/* v10.36 (۴۹ه): همان بافتِ پروفایل که در catfixRun اضافه شد، برای این مسیرِ
   زنده (SSE) هم لازم است — وگرنه دو مسیرِ دسته‌بندی رفتارِ متفاوت پیدا
   می‌کنند و کاربر بسته به اینکه از کدام دکمه آمده، جوابِ متفاوت می‌گیرد. */
$__profOf=catProfileResolver('bsl');
foreach($allProducts as $p){
$idx++;
$pId=(int)($p['id']??0);
$pName=trim($p['title']??$p['name']??'');
$sse(['type'=>'progress','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'step'=>'ask_master']);
if($pName===''){
$failed++;
$sse(['type'=>'item','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'status'=>'failed','msg'=>'عنوان محصول خالی']);continue;
}
/* v10.12 (۲۵): دستهٔ فعلی + همهٔ دسته‌های قبلاً امتحان‌شده از فهرستِ
   کاندیدهای این محصول حذف می‌شوند تا مدل مجبور شود گزینهٔ تازه بدهد. */
$curCat=bslProductCatId($p);
$exclude=catTriedExclude($pId,$curCat);
$triedInfo=[];
$trRow=catTriedRow($pId);
foreach(($trRow['tried']??[]) as $tcid=>$tinfo){$triedInfo[]=['id'=>(int)$tcid,'name'=>(string)($tinfo['name']??'')];}
$__pProf=$__profOf($pId,$pName);            // v10.36 (۴۹ه)
$__pHint=aiCatProfileHint($__pProf);
if($exclude){
$sse(['type'=>'progress','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'step'=>'exclude','excluded'=>count($exclude)]);
}
if($multi){
$con=aiCatConsensus($cands,$providers,$pName,$cats,$leafCats,$exclude,$net,['quorum'=>$quorum,'tried_info'=>$triedInfo,'profile_hint'=>$__pHint]);
$askTotal+=(int)($con['asked']??0);
if(!empty($con['from_cache']))$cacheHits++;
$catId=(int)($con['category_id']??0);
$catName=(string)($con['category_name']??'');
$okRes=!empty($con['ok']);
$errRes=(string)($con['error']??'');
$winKeys=(array)($con['winner_keys']??[]);
if($okRes){
$sse(['type'=>'progress','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'step'=>'consensus','catId'=>$catId,'catName'=>$catName,'agreement'=>(int)($con['agreement']??0),'asked'=>(int)($con['asked']??0),'stages'=>(int)($con['stages']??0),'from_cache'=>!empty($con['from_cache']),'per_model'=>(array)($con['per_model']??[])]);
}
}else{
$res=aiCandidateCategory($mp,$master['model'],$pName,$cats,$leafCats,aiCatListBuild($leafCats,$exclude,24000,$pName),$net,$exclude,$triedInfo,$__pHint);
$askTotal++;
$catId=(int)($res['category_id']??0);
$catName=(string)($res['category_name']??'');
$okRes=!empty($res['ok']);
$errRes=(string)($res['error']??'');
$winKeys=[$masterKey];
}
if(!$okRes||$catId<=0){
$noCat++;
$sse(['type'=>'item','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'status'=>'no_cat','msg'=>($multi?'اجماع به دستهٔ تازه‌ای نرسید':'مستر دستهٔ معتبری نداد').($errRes!==''?' — '.$errRes:''),'err'=>$errRes]);continue;
}
if($curCat>0&&$catId===$curCat){
$skipSame++;
catTriedRecord($pId,$catId,$catName,$multi?'consensus':'master','skipped',$pName,$curCat);
$sse(['type'=>'item','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'status'=>'skipped','catId'=>$catId,'catName'=>$catName,'msg'=>'رد شد: پیشنهاد همان دستهٔ فعلی است']);continue;
}
if(catTriedHas($pId,$catId)){
$skipTried++;
catTriedRecord($pId,$catId,$catName,$multi?'consensus':'master','skipped',$pName,$curCat);
$sse(['type'=>'item','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'status'=>'skipped','catId'=>$catId,'catName'=>$catName,'msg'=>'رد شد: «'.$catName.'» قبلاً امتحان و رد شده']);continue;
}
$sse(['type'=>'progress','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'step'=>'patching','catId'=>$catId,'catName'=>$catName]);
$bu=['category_id'=>$catId,'status'=>3568];
$r2=bslReq($tk,'PATCH','products/'.$pId,$bu);
if($r2['code']===404)$r2=bslReq($tk,'PATCH','vendors/'.$vid.'/products/'.$pId,$bu);
if($r2['ok']&&!empty($r2['body']['id'])){
$fixed++;
/* رأی و یادگیری: در حالتِ چندمدلی برندهٔ اجماع رأی می‌گیرد (نه لزوماً
   مستر)، پس آمار دیگر به‌نفعِ مستر تحریف نمی‌شود. */
foreach(array_unique($winKeys?:[$masterKey]) as $wk)aiVoteRecord('category',$pName,$wk,$candKeys);
catLearnRecord($pName,$catId,$catName);
catTriedRecord($pId,$catId,$catName,$multi?'consensus':'master','applied',$pName,$curCat);
$sse(['type'=>'item','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'status'=>'fixed','catId'=>$catId,'catName'=>$catName,'msg'=>'اصلاح شد و ارسال به بررسی مجدد: '.$catName.' ('.$catId.')']);
}else{
$failed++;
catTriedRecord($pId,$catId,$catName,$multi?'consensus':'master','failed',$pName,$curCat);
$errDetail=($r2['body']['message']??($r2['body']['error']??''));
$sse(['type'=>'item','idx'=>$idx,'total'=>$total,'pId'=>$pId,'pName'=>$pName,'status'=>'failed','catId'=>$catId,'catName'=>$catName,'msg'=>'PATCH ناموفق: '.$errDetail]);
}
usleep(500000);
}
$savedMsg='';
if($multi&&$total>0){
$maxCalls=$total*count($cands);
$saved=$maxCalls-$askTotal;
if($saved>0)$savedMsg=' | صرفه‌جویی: '.aiFaNum($saved).' فراخوانی از '.aiFaNum($maxCalls).' ('.aiFaNum((int)round($saved*100/max(1,$maxCalls))).'٪)';
if($cacheHits>0)$savedMsg.=' | از کش: '.aiFaNum($cacheHits);
}
$sse(['type'=>'done','fixed'=>$fixed,'failed'=>$failed,'no_cat'=>$noCat,'total'=>$total,'skipped'=>$skipSame+$skipTried,'skip_same'=>$skipSame,'skip_tried'=>$skipTried,'asked'=>$askTotal,'cache_hits'=>$cacheHits,'multi'=>$multi,'msg'=>'✅ اصلاح '.($multi?'چندمدلی':'با مستر').' انجام شد: '.$fixed.' | دسته نیافت: '.$noCat.' | تکراری: '.($skipSame+$skipTried).' | ناموفق: '.$failed.' (از '.$total.')'.$savedMsg]);
if(function_exists('fastcgi_finish_request'))fastcgi_finish_request();
exit;
}

if(isset($_GET['bsl_download_ai_texts'])){
$cn=loadConnections();$bs=$cn['basalam']??[];
if(empty($bs['token'])||empty($bs['vendor_id'])){
http_response_code(400);echo 'تنظیمات باسلام ناقص';exit;
}
$tk=$bs['token'];$vid=(int)$bs['vendor_id'];

$allProducts=[];
for($pg=1;$pg<=20;$pg++){
$r=bslReq($tk,'GET','vendors/'.$vid.'/products?page='.$pg.'&per_page=100&statuses=3567');
if(!$r['ok'])break;
$data=$r['body']['data']??[];
if(empty($data))break;
$tp=max(1,(int)($r['body']['total_page']??1));
foreach($data as $p)$allProducts[]=$p;
if($pg>=$tp)break;
}

$lines=[];
$lines[]='========================================';
$lines[]='متن‌های توصیه هوش مصنوعی باسلام — محصولات تأیید نشده';
$lines[]='تعداد محصول: '.count($allProducts);
$lines[]='تاریخ تولید: '.date('Y-m-d H:i:s');
$lines[]='========================================';
$lines[]='';
$idx=0;
foreach($allProducts as $p){
$idx++;
$pId=(int)($p['id']??0);
$pName=trim($p['title']??$p['name']??'');
$rev=$p['revision']??[];
$aiText=trim($rev['metadata']['description']??'');
$rejReasons=$rev['rejection_reasons']??[];
foreach($rejReasons as $rr){$rrDesc=trim($rr['description']??'');if($rrDesc!==''&&mb_strlen($rrDesc,'UTF-8')>5)$aiText.=($aiText?' | ':'').$rrDesc;}
$lines[]='--- محصول #'.$idx.' ---';
$lines[]='شناسه: '.$pId;
$lines[]='نام: '.$pName;
if($aiText!==''){
$lines[]='متن AI:';
$lines[]=$aiText;
}else{
$lines[]='متن AI: (بدون متن)';
}
$lines[]='';
}
$output=implode("\n",$lines);
header('Content-Type: text/plain; charset=UTF-8');
header('Content-Disposition: attachment; filename="basalam_ai_texts_'.date('Ymd_His').'.txt"');
header('Content-Length: '.strlen($output));
echo $output;
exit;
}

// v10.02 (۱۶): اندپوینتِ قدیمیِ ?bsl_find_duplicates=1 حذف شد؛ جایگزینِ آن موتورِ dedup_* است (dedup_start/dedup_status/dedup_result).

if(isset($_GET['bsl_change_status'])){
header('Content-Type: application/json; charset=UTF-8');
$cn=loadConnections();$bs=$cn['basalam']??[];
if(empty($bs['token'])||empty($bs['vendor_id'])){echo json_encode(['ok'=>false,'error'=>'تنظیمات باسلام ناقص'],JSON_UNESCAPED_UNICODE);exit;}
$tk=$bs['token'];$vid=(int)$bs['vendor_id'];
$productId=(int)($_GET['product_id']??0);
$newStatus=(int)($_GET['status']??0);
if($productId<=0||$newStatus<=0){echo json_encode(['ok'=>false,'error'=>'شناسه یا وضعیت نامعتبر'],JSON_UNESCAPED_UNICODE);exit;}
$statusLabels=['2976'=>'فعال','3790'=>'غیرفعال','3568'=>'در انتظار تأیید'];
$label=$statusLabels[$newStatus]??$newStatus;
/* v10.52 (۶۶): هر گام در یک درخواستِ جدا (پارامترِ via) — زنجیرهٔ
   بلندِ v10.51 در پنجرهٔ HTTPِ کوتاه ۵۰۲ می‌گرفت؛ کلاینت با 'next'
   خودکار به گامِ بعد می‌رود. */
$_via=($_GET['via']??'');
$_via=in_array($_via,['simple','full','archive','disable','hide'],true)?$_via:'simple'; /* v10.53 (۶۷): پلکانِ کامل */
$r=bslSetProductStatus($tk,$vid,$productId,$newStatus,$_via);
if($r['ok']&&!empty($r['body']['id'])){
echo json_encode(['ok'=>true,'msg'=>'محصول #'.$productId.' → '.$label.' ('.$newStatus.')'],JSON_UNESCAPED_UNICODE);
}else{
/* v10.49 (۶۳): همان خطای گویا برای تغییر وضعیت */
$_resp=['ok'=>false,'error'=>bslApiError($r,'تغییر وضعیت ناموفق','products/'.$productId)];
if(!empty($r['next']))$_resp['next']=$r['next'];
echo json_encode($_resp,JSON_UNESCAPED_UNICODE);
}
exit;
}
if(isset($_GET['bsl_delete_product'])){
header('Content-Type: application/json; charset=UTF-8');
$cn=loadConnections();$bs=$cn['basalam']??[];
if(empty($bs['token'])||empty($bs['vendor_id'])){echo json_encode(['ok'=>false,'error'=>'تنظیمات باسلام ناقص'],JSON_UNESCAPED_UNICODE);exit;}
$tk=$bs['token'];$vid=(int)$bs['vendor_id'];
$productId=(int)($_GET['product_id']??0);
if($productId<=0){echo json_encode(['ok'=>false,'error'=>'شناسه محصول نامعتبر'],JSON_UNESCAPED_UNICODE);exit;}
// v8.62: باسلام متد DELETE برای محصول ندارد. تا امروز این کد به اندپوینتی
// می‌رفت که وجود ندارد و همیشه ۴۰۴ می‌گرفت، یعنی حذف هیچ‌وقت انجام نمی‌شد.
// معادل واقعی، بایگانی کردن است (وضعیت ۴۱۸۴).
/* v10.52 (۶۶): بایگانیِ دستی گام‌به‌گام — اول فقط-وضعیت (همان
   کارِ سریعِ قدیمی)؛ اگر ۴۲۲/۴۰۳/۴۰۴ داد، کلاینت با 'next' خودکار
   گامِ بعد (پیلودِ کامل، بعد archive) را در درخواستِ تازه می‌زند. */
$_via=($_GET['via']??'');
$_via=in_array($_via,['simple','full','archive','disable','hide'],true)?$_via:'simple'; /* v10.53 (۶۷): پلکانِ کامل */
$r=bslSetProductStatus($tk,$vid,$productId,4184,$_via);
if($r['ok']||$r['code']===204||$r['code']===200){
$_strat=(string)($r['status_strategy']??''); /* v10.53 (۶۷): پیامِ دقیقِ نتیجه */
if($_strat==='disable'){$_delMsg='محصول #'.$productId.' غیرفعال شد (بایگانی ممکن نشد)';}
elseif($_strat==='hide'){$_delMsg='محصول #'.$productId.' ناموجود شد: موجودی و قیمت صفر شد (بایگانی و غیرفعال‌کردن ممکن نشد)';}
else{$_delMsg='محصول #'.$productId.' بایگانی شد (باسلام حذف همیشگی ندارد)';}
echo json_encode(['ok'=>true,'archived'=>in_array($_strat,['simple','full','archive'],true),'msg'=>$_delMsg],JSON_UNESCAPED_UNICODE);
}else{
/* v10.49 (۶۳): خطای گویا — ۴۲۲ یعنی «پارامتر نامعتبر»؛ جزئیاتِ دقیق
   (کدام فیلد، چه مقبول است) را از بدنه بیرون بکشیم که کاربر/ما ببیند. */
$_resp=['ok'=>false,'error'=>bslApiError($r,'بایگانی ناموفق','products/'.$productId)];
if(!empty($r['next']))$_resp['next']=$r['next'];
echo json_encode($_resp,JSON_UNESCAPED_UNICODE);
}
exit;
}

// v10.02 (۱۶): اندپوینتِ قدیمیِ ?bsl_delete_batch=1 حذف شد؛ جایگزینِ آن موتورِ dedup_* است (dedup_start/dedup_status/dedup_result).

if(isset($_GET['bsl_status_overview'])){
header('Content-Type: application/json; charset=UTF-8');
$cn=loadConnections();$bs=$cn['basalam']??[];
if(empty($bs['token'])||empty($bs['vendor_id'])){echo json_encode(['ok'=>false,'error'=>'تنظیمات باسلام ناقص'],JSON_UNESCAPED_UNICODE);exit;}
$tk=$bs['token'];$vid=(int)$bs['vendor_id'];
$counts=['active'=>0,'inactive'=>0,'not_approved'=>0,'pending'=>0,'archived'=>0];
$statusQueries=['active'=>['2976'],'inactive'=>['3790'],'not_approved'=>['3567'],'pending'=>['3568'],'archived'=>['4184']];
