/**
 * v8.58: نام دسته‌بندی‌های یک وظیفهٔ صف باسلام.
 *
 * تا اینجا مودال هر وظیفه فقط آمار و فهرست محصولات را نشان می‌داد و
 * معلوم نبود این وظیفه با کدام دسته ارسال شده. حالا دستهٔ اصلی، حالت
 * «دستهٔ خودکار» و دسته‌های جایگزین با نام برگردانده می‌شوند.
 *
 * درخت دسته‌ها یک بار گرفته و کنار فایل کش می‌شود؛ اگر شبکه در دسترس
 * نبود، همان شناسه‌ها بدون نام برمی‌گردند و مودال باز می‌ماند.
 */
function bslCatNameMapCached(): array {
    static $map = null;
    if ($map !== null) return $map;
    $map = [];
    $cacheFile = __DIR__ . '/bsl_cat_names.json';
    if (is_file($cacheFile) && (time() - (int)@filemtime($cacheFile)) < 86400) {
        $d = json_decode((string)@file_get_contents($cacheFile), true);
        if (is_array($d) && $d) { $map = $d; return $map; }
    }
    $cn = loadConnections();
    $tk = (string)($cn['basalam']['token'] ?? '');
    if ($tk === '') return $map;
    /* v10.41 (۵۵): از کشِ مشترک — نه یک واکشیِ مستقلِ دیگر */
    foreach (bslCatsAll($tk) as $c) {
        $id = (int)($c['id'] ?? 0);
        if ($id > 0) $map[$id] = (string)($c['name'] ?? '');
    }
    if ($map) @file_put_contents($cacheFile, json_encode($map, JSON_UNESCAPED_UNICODE), LOCK_EX);
    return $map;
}

function bslQueueCatInfo(array $cfg): array {
    $names   = bslCatNameMapCached();
    $mainId  = (int)($cfg['category_id'] ?? 0);
    $autoCat = !empty($cfg['auto_category']);
    $label   = function (int $id) use ($names) {
        $n = $names[$id] ?? '';
        return ['id' => $id, 'name' => $n !== '' ? $n : ('#' . $id)];
    };
    $fallback = [];
    foreach ((array)($cfg['fallback_cat_ids'] ?? []) as $fid) {
        $fid = (int)$fid;
        if ($fid > 0) $fallback[] = $label($fid);
    }
    return [
        'main'          => $mainId > 0 ? $label($mainId) : null,
        'auto_category' => $autoCat,
        'fallback'      => $fallback,
        'title_suffix'  => trim((string)($cfg['title_suffix'] ?? '')),
    ];
}

function bslReadQueue(): array {
clearstatcache(true,BSL_QUEUE_FILE);
if(!file_exists(BSL_QUEUE_FILE)) return ['entries'=>[]];
$d=@json_decode(@file_get_contents(BSL_QUEUE_FILE)?:'',true);
return is_array($d)&&isset($d['entries'])?$d:['entries'=>[]];
}
function bslWriteQueue(array $queue): void {
@file_put_contents(BSL_QUEUE_FILE,json_encode($queue,JSON_UNESCAPED_UNICODE),LOCK_EX);
}

/**
 * v8.36: فایل محصولاتِ یک ورودی صف را برمی‌گرداند.
 *
 * چرا لازم است: تا نسخهٔ ۸.۳۵ همهٔ ارسال‌ها از یک فایل مشترک
 * (BSL_PRODUCTS_FILE) می‌خواندند، ولی آن فایل با شروع هر ارسال تازه
 * بازنویسی می‌شد. نتیجه این بود که اگر پروفایل دیگری ارسال می‌شد،
 * محصولات پروفایل قبلی فرستاده می‌شد. حالا هر صف فایل خودش را دارد.
 */
function bslQueueProductsFile(string $queueId): string {
    $queueId=trim($queueId);
    if($queueId!==''){
        // مسیر ثبت‌شده در خود صف مرجع اصلی است
        $q=bslReadQueue();
        foreach(($q['entries']??[]) as $e){
            if(($e['id']??'')===$queueId){
                $f=(string)($e['products_file']??'');
                if($f!==''&&is_file($f)) return $f;
                break;
            }
        }
        $guess=__DIR__.'/bsl_queue_products_'.basename($queueId).'.json';
        if(is_file($guess)) return $guess;
    }
    return BSL_PRODUCTS_FILE;   // سازگاری با مسیرهای قدیمی بدون queue_id
}

/** همان منطق برای ووکامرس */
function wooQueueProductsFile(string $queueId): string {
    $queueId=trim($queueId);
    $q=@json_decode((string)@file_get_contents(WOO_QUEUE_FILE),true);
    $entries=is_array($q['entries']??null)?$q['entries']:[];
    if($queueId!==''){
        foreach($entries as $e){
            if(($e['id']??'')===$queueId){
                $f=(string)($e['products_file']??'');
                if($f!==''&&is_file($f)) return $f;
                break;
            }
        }
        $guess=__DIR__.'/woo_queue_products_'.basename($queueId).'.json';
        if(is_file($guess)) return $guess;
    }
    // فراخوان‌های ووکامرس queue_id نمی‌فرستند؛ پس ردیف در حال اجرا را خودمان پیدا می‌کنیم
    foreach($entries as $e){
        if(($e['status']??'')==='running'){
            $f=(string)($e['products_file']??'');
            if($f!==''&&is_file($f)) return $f;
        }
    }
    return WOO_PRODUCTS_FILE;
}

if(isset($_GET['bsl_queue_status'])){
header('Content-Type: application/json; charset=UTF-8');
/* v10.59 (۷۳): ردیفِ تمام‌شدهٔ بسته‌نشده — وِرکر کشته شده و «current» به
   «total» رسیده (یا progress کامل است) ولی ردیف هنوز «running» است.
   queueStallCheck دقیقاً همین ردیف را فوراً «done» می‌کند؛ پس قبل از
   رندرِ رابط، یک بار بچکش تا کاربر دیگر وظیفهٔ تمام‌شدهٔ «فعال» نبیند. */
try { $stB = loadConnections(); queueStallCheck('bsl', max(120, (int)($stB['stall_after'] ?? 300))); } catch (Throwable $eB) {}
$bslStatusFp = queueBackendLock('bsl');
if (is_resource($bslStatusFp)) register_shutdown_function(function() use ($bslStatusFp) { queueBackendUnlock($bslStatusFp); });
$queue=bslReadQueue();

$progress=readProgress(BSL_PROGRESS_FILE);
$progressQueueId=(string)($progress['queue_id']??'');
foreach($queue['entries'] as &$e){
if($e['status']==='running' && ($progressQueueId==='' || (string)($e['id']??'')===$progressQueueId)){
$e['sent']=$progress['sent']??0;
$e['updated']=$progress['updated']??0;
$e['skipped']=$progress['skipped']??0;
$e['failed']=$progress['failed']??0;
$e['current']=$progress['current']??0;
$e['total']=$progress['total']??$e['total']??0;
$e['done']=$progress['done']??false;
/* v10.23 (۳۶ه): شمارنده‌های تفکیکیِ غرفه‌ها زنده به صف می‌رسند */
if(is_array($progress['shop_stats']??null))$e['shop_stats']=$progress['shop_stats'];

$progressIncomplete=!empty($progress['stopped']) || !empty($progress['partial'])
    || !empty($progress['cancelled']) || !empty($progress['stale']) || !empty($progress['failed_resume']);
if(!empty($progress['paused']) || $progressIncomplete){$e['status']='paused';$e['paused_at']=time();}
else if(!empty($progress['done'])){$e['status']='done';$e['done_at']=time();}
}
}
unset($e);
if (is_resource($bslStatusFp)) bslWriteQueue($queue);
echo json_encode($queue,JSON_UNESCAPED_UNICODE);
exit;
}

