function bslBackendProgress($s,$u,$sk,$f,$t,$c,$lt,$log=null,$extra=[]){
global $bslLog,$bslSentList,$bslUpdatedList,$bslSkippedList,$bslFailedList,$bslQueueId;
if($log!==null){$bslLog[]=$log;}
$totalLog=count($bslLog);
$recentSlice=$totalLog>200?array_slice($bslLog,-200):$bslLog;
/* v10.104: چک‌پوینت را هرگز با ضربانِ bootstrap (current=0) پایین نیاور —
   وگرنه resume از صفر شروع می‌شود و کارت‌های قبلی از بین می‌روند. */
$__floor=(int)($GLOBALS['_bslResumeFloor']??0);
$cWrite=max((int)$c,$__floor);
/* v10.104: در bootstrap بعد از resume، شمارنده‌های ۰ را در progress نگه ندار */
$__sW=(int)$s;$__uW=(int)$u;$__skW=(int)$sk;$__fW=(int)$f;
if($__floor>0 && ($__sW+$__uW+$__skW+$__fW)===0 && !empty($GLOBALS['_bslResumeCounters'])){
$__rc=$GLOBALS['_bslResumeCounters'];
$__sW=(int)($__rc['sent']??0);$__uW=(int)($__rc['updated']??0);
$__skW=(int)($__rc['skipped']??0);$__fW=(int)($__rc['failed']??0);
}
$d=['running'=>true,'sent'=>$__sW,'updated'=>$__uW,'skipped'=>$__skW,'failed'=>$__fW,'total'=>$t,'last_title'=>$lt,'current'=>$cWrite,'done'=>false,'started_at'=>$GLOBALS['startedAt'],'last_progress_ts'=>time(),'recent_log'=>$recentSlice,'total_log_count'=>$totalLog,'sent_details'=>$bslSentList,'updated_details'=>$bslUpdatedList,'skipped_details'=>$bslSkippedList,'failed_details'=>$bslFailedList,
   'checkpoint'=>['queue_id'=>(string)($bslQueueId??''),'current'=>(int)$cWrite,'total'=>(int)$t,'sent'=>(int)$__sW,'updated'=>(int)$__uW,'skipped'=>(int)$__skW,'failed'=>(int)$__fW,'started_at'=>(int)$GLOBALS['startedAt']]];
if($bslQueueId!='')$d['queue_id']=$bslQueueId;
/* v10.23 (۳۶ه): شمارنده‌های هر غرفه در هر ضربانِ پیشرفت هم می‌روند تا صف
   بتواند «زنده» نشانشان بدهد، نه فقط در پایانِ کار. */
$__ss=bslShopStatRows((int)$s,(int)$u,(int)$sk,(int)$f);
if($__ss)$d['shop_stats']=$__ss;
if(!empty($extra))$d=array_merge($d,$extra);
writeProgress(BSL_PROGRESS_FILE,$d);
clearstatcache();
/* v10.56/v10.104: current ردیف صف فقط بالا می‌رود (هرگز رگرس به ۰).
   جزئیات کارت‌ها هم در ردیف صف نگه داشته می‌شود تا گزارش پروفایل زنده بماند. */
if(isset($GLOBALS['_bslQueueIdNow'])){
try{
$__q=bslReadQueue();$__chg=false;
foreach($__q['entries'] as &$__e){
if($__e['id']===$GLOBALS['_bslQueueIdNow']){
$__prevC=(int)($__e['current']??0);
if($cWrite>$__prevC){($__e['current']=$cWrite);($__chg=true);}
/* v10.104: شمارنده‌های bootstrap(۰) را روی ردیف resume ننویس */
$__bootZero=((int)$s+(int)$u+(int)$sk+(int)$f)===0 && $__floor>0;
if(!$__bootZero){
$__e['sent']=$s;$__e['updated']=$u;$__e['skipped']=$sk;$__e['failed']=$f;
}
if(is_array($bslSentList)&&count($bslSentList)>0){$__e['sent_details']=$bslSentList;$__chg=true;}
if(is_array($bslUpdatedList)&&count($bslUpdatedList)>0)$__e['updated_details']=$bslUpdatedList;
if(is_array($bslSkippedList)&&count($bslSkippedList)>0)$__e['skipped_details']=$bslSkippedList;
if(is_array($bslFailedList)&&count($bslFailedList)>0)$__e['failed_details']=$bslFailedList;
break;
}
}
unset($__e);
if($__chg)bslWriteQueue($__q);
}catch(Exception $__ex){}
}
}

/* v10.53 (۶۷): یک وِرکر = صفِ کامل. هر وقت یک ردیف تمام شد و ردیفِ «در انتظار»
   دیگری باشد، همان‌جا ادامه می‌دهد (به نوبت) — دیگر برای هر پروفایل وِرکر
   تازه لازم نیست. سقف (BSL_MAX_ENTRIES_PER_RUN) برای اینکه وِرکر پنجرهٔ هاست
   را رد نکند؛ بقیه را اجرای بعد می‌گیرد. متغیرهای زیر برای هر ردیف از نو
   شروع می‌شوند. */
$bslEntriesDoneThisRun = 0;
for ($bslEntryRound = 0; $bslEntryRound < BSL_MAX_ENTRIES_PER_RUN; $bslEntryRound++) {
if ($bslEntryRound > 0) {
    clearstatcache(true,BSL_STOP_FILE);
    if (file_exists(BSL_STOP_FILE)) {
        writeProgress(BSL_PROGRESS_FILE,['running'=>false,'done'=>true,'cancelled'=>true,'sent'=>0,'updated'=>0,'skipped'=>0,'failed'=>0,'total'=>0,'current'=>0,'started_at'=>$startedAt,'last_progress_ts'=>time(),'recent_log'=>['⏹ Between rows: stop signal — remaining rows will be sent in the next run'],'total_log_count'=>1]);
        @unlink(BSL_PRODUCTS_FILE);
        exit;
    }
}
$bslQueueId=''; $bslSentList=[]; $bslUpdatedList=[]; $bslSkippedList=[]; $bslFailedList=[]; $bslLog=[]; $bslFlatCats=[];
/* v10.23 (۳۶ه): شمارنده‌های تفکیکیِ هر غرفه.
   تا اینجا صفِ ارسال فقط یک مجموعه شمارنده داشت (جدید/آپدیت/تکراری/خطا) که
   جمعِ کورِ همهٔ غرفه‌ها بود. با «ارسال همزمان به همهٔ غرفه‌ها» این عدد عملاً
   بی‌معنی می‌شد: نمی‌شد فهمید کدام غرفه اصلاً چیزی نگرفته یا کدام‌یک همهٔ
   خطاها را داده. حالا هر غرفه ردیفِ شمارندهٔ خودش را دارد.
   کلید = vendor_id، مقدار = ['name','c'(ساخته),'u'(آپدیت),'s'(رد),'f'(خطا)] */
$bslShopStats=[]; $bslDefaultVid=0; $bslDefaultShopName='';

$queue=bslReadQueue();

$progress=readProgress(BSL_PROGRESS_FILE);
foreach($queue['entries'] as &$e){
if($e['status']==='running'&&($progress['done']??false) && empty($_GET['resume']) && empty($_POST['resume'])){
$e['status']='done';
$e['sent']=$progress['sent']??0;$e['updated']=$progress['updated']??0;
$e['skipped']=$progress['skipped']??0;$e['failed']=$progress['failed']??0;
$e['current']=$progress['current']??0;$e['done_at']=time();
}
}
unset($e);

$nextEntry=null;$nextIdx=null;
$now=time();
$progQueueId=$progress['queue_id']??'';
$progRunning=!empty($progress['running']);
foreach($queue['entries'] as $i=>&$e){
if($e['status']==='waiting'){
$nextEntry=$e;$nextIdx=$i;break;
}

if($e['status']==='running'){

$noProgressMatch=($progQueueId!==$e['id'])||(!$progRunning);
if($noProgressMatch){

$nextEntry=$e;$nextIdx=$i;break;
}

$progTs=(int)($progress['last_progress_ts']??0);
$entryStarted=(int)($e['started_at']??0);
$staleSeconds=$progTs>0?($now-$progTs):($entryStarted>0?($now-$entryStarted):9999);
if($staleSeconds>120){
$nextEntry=$e;$nextIdx=$i;break;
}
}
}
unset($e);

if(!$nextEntry){
// v8.57: صف خالی یعنی کاری نیست — تمام.
//
// تا اینجا اگر صف خالی بود، این اندپوینت خودش می‌گشت و از روی پروفایل‌های
// «سینک فعال» یک ورودی می‌ساخت و بلافاصله می‌فرستاد. نتیجه‌اش دقیقاً همان
// چیزی بود که گزارش شد: کاربر ارسال پروفایل الف را می‌زد و پروفایل ب
// می‌رفت، یا با صف خالی ناگهان ارسالی شروع می‌شد که کسی نخواسته بود.
// زمان‌بندی خودکار کار کران‌جاب (cron_run) است، نه کار ارسال‌کننده.
bslWriteQueue($queue);
header('Content-Type: application/json; charset=UTF-8');
echo json_encode(['ok'=>true,'msg'=>'صف خالی — هیچ ورودی برای پردازش نیست','started'=>false,'processed'=>$bslEntriesDoneThisRun],JSON_UNESCAPED_UNICODE);
exit;
}

$bslQueueId=$nextEntry['id'];

/* v10.56 (۷۰): چک‌پوینتِ ادامه — فایلِ پیشرفت را پُر از پاک‌کردن می‌خوانیم:
   موقعِ شروعِ درست (شمارهٔ ۱‌مبنا از اولینِ محصولی که باید پردازش شود) و
   شمارنده‌های اجرأ قبلی، اگر فرایندِ قبلی وسطِ کار مُرده باشد و نگهبان
   (یا «ادامه») ما را دوباره راه انداخته باشد. بدونِ این، هر بارِ شروع از
   محصولِ ۱ از نو — ارسالِ بزرگ یا بسیار طولانی می‌شد یا غیرممکن.
   فایلِ پیشرفت فقط وقتی مبنا می‌شود که queue_id مالِ همین ردیف باشد. */
$bslPrevProg=readProgress(BSL_PROGRESS_FILE);
$bslPrevQid=trim((string)($bslPrevProg['queue_id']??''));
$bslResumeStart=0;$bslResumeCounters=false;
if($bslPrevQid===$bslQueueId){
$bslResumeStart=(int)($bslPrevProg['current']??0);
$bslResumeCounters=isset($bslPrevProg['sent']);
}
/* v10.104: current ردیف صف هم مبنا — حتی اگر progress قبل از POST پاک شده */
$bslEntryCur=max(0,(int)($nextEntry['current']??0));
if($bslEntryCur>$bslResumeStart){$bslResumeStart=$bslEntryCur;$bslResumeCounters=true;}
$bslPostStart=max(0,(int)($_POST['start_index']??0));
$bslPostQid=trim((string)($_POST['queue_id']??''));
if($bslPostStart>0&&($bslPostQid===''||$bslPostQid===$bslQueueId))$bslResumeStart=max($bslResumeStart,$bslPostStart);
$bslResumeStart=max(0,$bslResumeStart);
$GLOBALS['_bslQueueIdNow']=$bslQueueId;
$GLOBALS['_bslResumeFloor']=$bslResumeStart;
/* snapshot جزئیات قبل از unlink — بعد از resume بازیابی می‌شود */
if(empty($bslPrevProg['sent_details'])&&!empty($nextEntry['sent_details'])){
$bslPrevProg['sent_details']=$nextEntry['sent_details']??[];
$bslPrevProg['updated_details']=$nextEntry['updated_details']??[];
$bslPrevProg['skipped_details']=$nextEntry['skipped_details']??[];
$bslPrevProg['failed_details']=$nextEntry['failed_details']??[];
if(!isset($bslPrevProg['sent'])){$bslPrevProg['sent']=$nextEntry['sent']??0;$bslPrevProg['updated']=$nextEntry['updated']??0;$bslPrevProg['skipped']=$nextEntry['skipped']??0;$bslPrevProg['failed']=$nextEntry['failed']??0;$bslResumeCounters=true;}
}
if($bslResumeStart>0){
$GLOBALS['_bslResumeCounters']=[
 'sent'=>(int)($bslPrevProg['sent']??$nextEntry['sent']??0),
 'updated'=>(int)($bslPrevProg['updated']??$nextEntry['updated']??0),
 'skipped'=>(int)($bslPrevProg['skipped']??$nextEntry['skipped']??0),
 'failed'=>(int)($bslPrevProg['failed']??$nextEntry['failed']??0),
];
/* جزئیات را همین‌جا در لیست‌های سراسری بنشان تا bootstrap scard را پاک نکند */
if(!empty($bslPrevProg['sent_details'])&&is_array($bslPrevProg['sent_details']))$bslSentList=$bslPrevProg['sent_details'];
if(!empty($bslPrevProg['updated_details'])&&is_array($bslPrevProg['updated_details']))$bslUpdatedList=$bslPrevProg['updated_details'];
if(!empty($bslPrevProg['skipped_details'])&&is_array($bslPrevProg['skipped_details']))$bslSkippedList=$bslPrevProg['skipped_details'];
if(!empty($bslPrevProg['failed_details'])&&is_array($bslPrevProg['failed_details']))$bslFailedList=$bslPrevProg['failed_details'];
}
localTaskDbForget(BSL_PROGRESS_FILE); @unlink(BSL_PROGRESS_FILE);@unlink(BSL_STOP_FILE);@unlink(BSL_PRODUCTS_FILE);
if(!file_exists($nextEntry['products_file'])){
$queue['entries'][$nextIdx]['status']='failed';
$queue['entries'][$nextIdx]['done_at']=time();
bslWriteQueue($queue);
writeProgress(BSL_PROGRESS_FILE,['running'=>false,'done'=>true,'sent'=>0,'updated'=>0,'skipped'=>0,'failed'=>$nextEntry['total'],'total'=>$nextEntry['total'],'current'=>0,'started_at'=>$startedAt,'queue_id'=>$bslQueueId,'recent_log'=>['❌ فایل محصولات یافت نشد'],'total_log_count'=>1,'sent_details'=>[],'updated_details'=>[],'skipped_details'=>[],'failed_details'=>[]]);
header('Content-Type: application/json; charset=UTF-8');
echo json_encode(['ok'=>false,'error'=>'فایل محصولات یافت نشد','queue_id'=>$bslQueueId],JSON_UNESCAPED_UNICODE);
exit;
}

$copyOk=@copy($nextEntry['products_file'],BSL_PRODUCTS_FILE);
if(!$copyOk){
$queue['entries'][$nextIdx]['status']='failed';$queue['entries'][$nextIdx]['done_at']=time();
bslWriteQueue($queue);
writeProgress(BSL_PROGRESS_FILE,['running'=>false,'done'=>true,'sent'=>0,'updated'=>0,'skipped'=>0,'failed'=>$nextEntry['total'],'total'=>$nextEntry['total'],'current'=>0,'started_at'=>$startedAt,'queue_id'=>$bslQueueId,'recent_log'=>['❌ کپی فایل ناموفک'],'total_log_count'=>1,'sent_details'=>[],'updated_details'=>[],'skipped_details'=>[],'failed_details'=>[]]);
header('Content-Type: application/json; charset=UTF-8');
echo json_encode(['ok'=>false,'error'=>'کپی فایل محصولات ناموفک','queue_id'=>$bslQueueId],JSON_UNESCAPED_UNICODE);
exit;
}

$verifyProducts=json_decode(@file_get_contents(BSL_PRODUCTS_FILE)?:'',true)?:[];
if(empty($verifyProducts)){
$queue['entries'][$nextIdx]['status']='failed';$queue['entries'][$nextIdx]['done_at']=time();
