// v10.02 (۱۶): اندپوینتِ قدیمیِ ?woo_dedup_stream=1 حذف شد؛ جایگزینِ آن موتورِ dedup_* است (dedup_start/dedup_status/dedup_result).
/* =====================================================================
 *  v10.02 (۱۶): موتورِ حذفِ محصولاتِ تکراری — قابل تنظیم و سمتِ سرور
 *
 *  چرا بازنویسی شد؟
 *   ۱) معیارِ «کدام نسخه بماند» سفت‌وسخت بود: ووکامرس همیشه قدیمی‌ترین را
 *      حذف می‌کرد و باسلام هرچه فعال نبود. کاربر می‌خواهد خودش انتخاب کند
 *      (جدیدتر/قدیمی‌تر، ارزان‌تر/گران‌تر، موجودی بیشتر، وضعیت بهتر).
 *   ۲) الگویِ پسوندی که هنگام تشخیصِ هم‌نامی نادیده گرفته می‌شود ثابت و
 *      فقط «(کد:N)» بود. حالا کاربر می‌تواند «#N»، «(code:N)»، پسوندِ
 *      دلخواه یا حتی چند الگو را با هم فعال کند.
 *   ۳) این کار روی غرفه‌ای با چند هزار محصول چند دقیقه طول می‌کشد. تا امروز
 *      روی یک درخواستِ همزمانِ HTTP اجرا می‌شد و مرورگر/هاست وسطِ راه قطع
 *      می‌کرد ⇒ «خطای شبکه». حالا مثل «گزارش پسوند»، درخواست بی‌درنگ پاسخ
 *      می‌گیرد و کار در پس‌زمینه ادامه پیدا می‌کند؛ پیشرفت از فایل خوانده
 *      می‌شود و بستنِ مرورگر هیچ اثری ندارد.
 * ===================================================================== */

/** پیش‌فرضِ تنظیماتِ حذفِ تکراری (هم برای باسلام هم ووکامرس یکسان) */
function dedupDefaultCfg(): array {
    return [
        'keep'          => 'newest',   // newest|oldest|cheapest|expensive|most_stock|best_status
        'tie'           => 'newest',   // معیارِ دوم وقتی معیارِ اول مساوی شد
        'prefer_active' => true,       // پیش از هر معیار، نسخهٔ فعال/منتشرشده را نگه دار
        'strip_code'    => true,       // (کد:۱۲) و (code:12) و [کد ۱۲]
        'strip_hash'    => true,       // #12 در انتهای عنوان
        'strip_paren'   => false,      // (۱۲) خالی در انتها
        'strip_dash'    => false,      // - ۱۲ در انتهای عنوان
        'strip_custom'  => '',         // الگوی دلخواهِ کاربر (چند خطی)
        'ci'            => true,       // بی‌تفاوت به بزرگی/کوچکیِ حروف
        'norm_digits'   => true,       // ارقامِ فارسی/عربی ⇒ لاتین
        'norm_arabic'   => true,       // ي/ك عربی ⇒ ی/ک فارسی و حذف اعراب
        'min_len'       => 3,          // عنوانِ کوتاه‌تر از این نادیده گرفته شود
        /* v10.39 (۵۳) — هر دو فقط برای باسلام معنا دارند */
        'active_only'   => true,       // فقط محصولاتِ فعال (۲۹۷۶) مقایسه شوند
        'skip_multi'    => true,       // عنوانی که در چند غرفه هست، اصلاً دست نخورد
        'all_vendors'   => true,       // همهٔ غرفه‌ها اسکن شوند، نه فقط پیش‌فرض
        'use_cache'     => true,       // از فهرستِ آمادهٔ باسلام استفاده کن
    ];
}

/** تنظیماتِ ذخیره‌شده را با پیش‌فرض ادغام می‌کند */
function dedupCfg(?array $cn = null): array {
    if ($cn === null) $cn = loadConnections();
    $c = is_array($cn['dedup'] ?? null) ? $cn['dedup'] : [];
    $d = dedupDefaultCfg();
    $out = [];
    foreach ($d as $k => $v) {
        if (!array_key_exists($k, $c)) { $out[$k] = $v; continue; }
        if (is_bool($v))      $out[$k] = !empty($c[$k]) && $c[$k] !== 'false' && $c[$k] !== '0';
        elseif (is_int($v))   $out[$k] = (int)$c[$k];
        else                  $out[$k] = (string)$c[$k];
    }
    $valid = ['newest','oldest','cheapest','expensive','most_stock','best_status'];
    if (!in_array($out['keep'], $valid, true)) $out['keep'] = 'newest';
    if (!in_array($out['tie'],  $valid, true)) $out['tie']  = 'newest';
    $out['min_len'] = max(1, min(60, $out['min_len']));
    return $out;
}

/**
 * الگوهای regex ای که باید از انتهای عنوان برداشته شوند.
 * هر الگو یک regex کاملِ آمادهٔ preg_replace است.
 *
 * الگویِ دلخواهِ کاربر: هر خط یک الگو. اگر خط با / شروع و تمام شود، عیناً
 * به‌عنوان regex استفاده می‌شود؛ وگرنه به‌صورتِ متنِ ساده در نظر گرفته
 * می‌شود و «x» یا «X» یا «*» داخلش به معنیِ «یک عددِ چندرقمی» است. مثلاً
 * کاربر می‌نویسد «(کد:x)» یا «#x» یا «-کد x».
 */
function dedupPatterns(array $cfg): array {
    $D = '[0-9۰-۹٠-٩]';                 // رقمِ لاتین/فارسی/عربی
    $pats = [];
    if (!empty($cfg['strip_code'])) {
        // (کد:۱۲) · [code: 12] · (شناسه ۱۲) · (sku:12) — با یا بدون فاصله و دونقطه
        $pats[] = '/\s*[\(\[]\s*(?:کد|کُد|code|sku|شناسه|شناسه\s*کالا)\s*[:：\-]?\s*' . $D . '+\s*[\)\]]\s*$/iu';
        // بدونِ پرانتز: «... کد:۱۲» در انتها
        $pats[] = '/\s*(?:کد|code|sku|شناسه)\s*[:：]\s*' . $D . '+\s*$/iu';
    }
    if (!empty($cfg['strip_hash'])) {
        $pats[] = '/\s*[#＃]\s*' . $D . '+\s*$/u';
        $pats[] = '/\s*[\(\[]\s*[#＃]\s*' . $D . '+\s*[\)\]]\s*$/u';
    }
    if (!empty($cfg['strip_paren'])) {
        $pats[] = '/\s*[\(\[]\s*' . $D . '+\s*[\)\]]\s*$/u';
    }
    if (!empty($cfg['strip_dash'])) {
        $pats[] = '/\s*[\-–—_]\s*' . $D . '+\s*$/u';
    }
    $custom = trim((string)($cfg['strip_custom'] ?? ''));
    if ($custom !== '') {
        foreach (preg_split('/[\r\n]+/u', $custom) as $line) {
            $line = trim($line);
            if ($line === '') continue;
            if (strlen($line) > 2 && $line[0] === '/' && substr($line, -1) === '/') {
                // regex خام؛ فقط اگر معتبر باشد پذیرفته می‌شود
                $rx = $line . 'u';
                if (@preg_match($rx, '') !== false) $pats[] = $rx;
                continue;
            }
            // متنِ ساده ⇒ escape، سپس x/X/* ⇒ عدد، و فاصله‌ها انعطاف‌پذیر
            $q = preg_quote($line, '/');
            $q = str_replace(['x', 'X', '\*'], $D . '+', $q);
            $q = preg_replace('/(\\\\ )+/u', '\\s*', $q);
            $rx = '/\s*' . $q . '\s*$/iu';
            if (@preg_match($rx, '') !== false) $pats[] = $rx;
        }
    }
    return $pats;
}

/** یک الگوی نمونه را روی یک عنوان آزمایش می‌کند (برای پیش‌نمایشِ زندهٔ UI) */
function dedupNormalize(string $title, array $cfg, ?array $pats = null): string {
    if ($pats === null) $pats = dedupPatterns($cfg);
    $t = trim($title);
    if (!empty($cfg['norm_arabic'])) {
        $t = strtr($t, ['ي' => 'ی', 'ك' => 'ک', 'ٱ' => 'ا', 'أ' => 'ا', 'إ' => 'ا',
                        'ة' => 'ه', 'ۀ' => 'ه', 'ؤ' => 'و', 'ئ' => 'ی',
                        "\u{200c}" => ' ', "\u{200f}" => '', "\u{200e}" => '',
                        'ً' => '', 'ٌ' => '', 'ٍ' => '', 'َ' => '', 'ُ' => '',
                        'ِ' => '', 'ّ' => '', 'ْ' => '', 'ٰ' => '']);
    }
    if (!empty($cfg['norm_digits'])) {
        $t = strtr($t, ['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5',
                        '۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9',
                        '٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5',
                        '٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']);
    }
    if (!empty($cfg['ci']) && function_exists('mb_strtolower')) $t = mb_strtolower($t, 'UTF-8');
    $t = preg_replace('/\s+/u', ' ', $t);
    // الگوها ممکن است تودرتو باشند («… (کد:۳) #۷») ⇒ تا وقتی چیزی کم می‌شود تکرار کن
    for ($round = 0; $round < 4; $round++) {
        $before = $t;
        foreach ($pats as $rx) $t = (string)preg_replace($rx, ' ', $t);
        $t = trim(preg_replace('/\s{2,}/u', ' ', $t));
        if ($t === $before) break;
    }
    return trim($t);
}

/** برچسبِ فارسیِ معیارِ نگه‌داری */
function dedupKeepLabel(string $k): string {
    $m = ['newest' => 'جدیدترین', 'oldest' => 'قدیمی‌ترین', 'cheapest' => 'ارزان‌ترین',
          'expensive' => 'گران‌ترین', 'most_stock' => 'بیشترین موجودی',
          'best_status' => 'بهترین وضعیت'];
    return $m[$k] ?? $k;
}

/**
 * رتبهٔ وضعیت — هرچه بزرگ‌تر، «بهتر». برای هر دو مقصد یکدست است تا
 * منطقِ مرتب‌سازی مشترک بماند.
 *   باسلام: 2976 فعال · 3568 در انتظار · 3567 تأییدنشده · 3790 غیرفعال · 4184 بایگانی
 *   ووکامرس: publish · pending · draft · private · trash
 */
function dedupStatusRank(array $p): int {
    $bs = (int)($p['status'] ?? 0);
    if ($bs > 0) {
        $r = [2976 => 100, 3568 => 70, 3567 => 40, 3790 => 25, 4184 => 5];
        return $r[$bs] ?? 10;
    }
    $w = (string)($p['wstatus'] ?? '');
    $r = ['publish' => 100, 'pending' => 70, 'draft' => 40, 'private' => 25, 'trash' => 5];
    return $r[$w] ?? 10;
}

/** آیا این نسخه «فعال/منتشرشده» است؟ */
function dedupIsActive(array $p): bool {
    if ((int)($p['status'] ?? 0) > 0) return (int)$p['status'] === 2976;
    return (string)($p['wstatus'] ?? '') === 'publish';
}

/**
 * مقایسهٔ دو نسخه بر اساس یک معیار.
 * خروجی منفی ⇒ $a «بهتر» است (باید بماند).
 */
function dedupCmpBy(array $a, array $b, string $crit): int {
    switch ($crit) {
        case 'oldest':
            return dedupTs($a) <=> dedupTs($b);
        case 'newest':
            return dedupTs($b) <=> dedupTs($a);
        case 'cheapest':
            $pa = dedupPrice($a); $pb = dedupPrice($b);
            if ($pa <= 0 && $pb > 0) return 1;      // قیمتِ نامعلوم بازنده است
            if ($pb <= 0 && $pa > 0) return -1;
            return $pa <=> $pb;
        case 'expensive':
            return dedupPrice($b) <=> dedupPrice($a);
        case 'most_stock':
            return (int)($b['stock'] ?? 0) <=> (int)($a['stock'] ?? 0);
        case 'best_status':
            return dedupStatusRank($b) <=> dedupStatusRank($a);
    }
    return 0;
}

/** زمانِ ساختِ محصول به‌صورت عدد (۰ = نامعلوم ⇒ بازنده در «جدیدترین») */
function dedupTs(array $p): int {
    if (isset($p['ts']) && (int)$p['ts'] > 0) return (int)$p['ts'];
    $d = trim((string)($p['date_created'] ?? ''));
    if ($d !== '') { $t = strtotime($d); if ($t !== false) return $t; }
    // باسلام تاریخ نمی‌دهد؛ شناسهٔ بزرگ‌تر یعنی محصولِ تازه‌تر
    return (int)($p['id'] ?? 0);
}

/** قیمت به عدد (۰ = نامعلوم) */
function dedupPrice(array $p): int {
    $v = $p['price'] ?? 0;
    if (is_string($v)) { $v = preg_replace('/[^0-9.]/', '', $v); }
    return (int)round((float)$v);
}

/**
 * از یک گروهِ هم‌نام، تصمیم می‌گیرد کدام بماند و کدام‌ها بروند.
 * ترتیبِ تصمیم:
 *   ۱) اگر «ترجیحِ فعال» روشن است و دستِ‌کم یکی فعال است ⇒ فقط بینِ فعال‌ها رقابت
 *   ۲) معیارِ اصلی · ۳) معیارِ دوم (tie) · ۴) شناسهٔ کوچک‌تر (پایداریِ نتیجه)
 */
function dedupPickKeeper(array $items, array $cfg): array {
    $pool = $items;
    if (!empty($cfg['prefer_active'])) {
        $act = array_values(array_filter($items, 'dedupIsActive'));
        if ($act) $pool = $act;
    }
    $keep = $cfg['keep']; $tie = $cfg['tie'];
    usort($pool, function ($a, $b) use ($keep, $tie) {
        $c = dedupCmpBy($a, $b, $keep);
        if ($c !== 0) return $c;
        if ($tie !== $keep) { $c = dedupCmpBy($a, $b, $tie); if ($c !== 0) return $c; }
        return (int)($a['id'] ?? 0) <=> (int)($b['id'] ?? 0);
    });
    $keeper = $pool[0] ?? $items[0];
    $kid = (int)($keeper['id'] ?? 0);
    $drop = [];
    foreach ($items as $it) if ((int)($it['id'] ?? 0) !== $kid) $drop[] = $it;
    return ['keep' => $keeper, 'drop' => $drop];
}

/**
 * گروه‌بندیِ محصولات بر اساس عنوانِ نرمال‌شده.
 *
 * v10.39 (۵۳): اگر ردیف‌ها از چند غرفه آمده باشند (vendor_id دارند)، شناسهٔ
 * غرفه هم واردِ کلید می‌شود. یعنی دو محصولِ هم‌نام در دو غرفهٔ متفاوت هرگز
 * یک گروه نمی‌شوند و «تکراری» شمرده نمی‌شوند — دقیقاً همان چیزی که کاربر
 * خواست: حذف فقط *داخلِ* هر غرفه. جداکنندهٔ \x00 است تا با هیچ عنوانِ
 * واقعی‌ای اشتباه نشود.
 */
function dedupGroup(array $rows, array $cfg): array {
    $pats = dedupPatterns($cfg);
    $g = [];
    foreach ($rows as $r) {
        $name = (string)($r['name'] ?? ($r['title'] ?? ''));
        $n = dedupNormalize($name, $cfg, $pats);
        if ($n === '' || mb_strlen($n, 'UTF-8') < (int)$cfg['min_len']) continue;
        $vid = (int)($r['vendor_id'] ?? 0);
        $g[$vid > 0 ? $n . "\x00" . $vid : $n][] = $r;
    }
    return $g;
}

/** عنوانِ نمایشیِ گروه — پسوندِ غرفه از کلید برداشته می‌شود */
function dedupGroupNorm(string $key): string {
    $p = strpos($key, "\x00");
    return $p === false ? $key : substr($key, 0, $p);
}

/* --------------------- پیشرفتِ کارِ پس‌زمینه --------------------- */

function dedupProgress(array $patch): void {
    $cur = [];
    if (is_file(DEDUP_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(DEDUP_PROGRESS_FILE), true);
        if (is_array($d)) $cur = $d;
    }
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 400) $log = array_slice($log, -400);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['ts'] = time();
    writeProgress(DEDUP_PROGRESS_FILE, $cur);
}

function dedupStopRequested(): bool { return is_file(DEDUP_STOP_FILE); }
function dedupClearStop(): void { @unlink(DEDUP_STOP_FILE); }

/* --------------------- گرفتنِ محصولات از مقصد --------------------- */

/* =====================================================================
 *  v10.18 (۳۱ج): تلاشِ مجددِ صفحه در برداشتِ «حذفِ تکراری»
 *
 *  گزارشِ کاربر: لاگ با «صفحهٔ 1/400: 100 محصول» شروع می‌شد و بلافاصله
 *  «⚠️ صفحهٔ 2 ناموفق (HTTP 500)» می‌آمد و کلِ عملیات با ۱۰۰ محصول از
 *  ۴۰۰ صفحه تمام می‌شد. علت: هر دو تابعِ برداشت در اولین خطای HTTP بی‌درنگ
 *  break می‌کردند — یک خطای گذرای ۵۰۰/۵۰۲/۴۲۹ که چند ثانیه بعد رفع می‌شود
 *  کلِ کار را می‌بست. (bslReq فقط خطای *شبکه* را دوباره می‌زند؛ وقتی سرور
 *  کدِ HTTP برگرداند آن را «پاسخِ گرفته‌شده» می‌داند و تکرار نمی‌کند.)
 *
 *  حالا هر صفحه تا DEDUP_PAGE_TRIES بار با مکثِ فزاینده تکرار می‌شود و
 *  فقط اگر همهٔ تلاش‌ها شکست خورد کار متوقف می‌شود.
 *
 *  $fetch: تابعی که یک بار درخواست را می‌زند و آرایهٔ پاسخ برمی‌گرداند.
 *  خروجی: همان پاسخ (موفق یا آخرین شکست) + کلیدِ tries.
 * ===================================================================== */
function dedupFetchPage(callable $fetch, int $page, string $who): array {
    $tries = max(1, (int)DEDUP_PAGE_TRIES);
    $r = ['ok' => false, 'code' => 0];
    for ($try = 1; $try <= $tries; $try++) {
        if ($try > 1 && dedupStopRequested()) break;
        $r = (array)$fetch();
        if (!empty($r['ok'])) {
            /* موفقیت بعد از شکست را صریح بگو تا کاربر بداند چه شد */
            if ($try > 1) dedupProgress(['log_add' => ['✅ ' . $who . ' صفحهٔ ' . $page
                . ' در تلاشِ ' . $try . 'ام موفق شد']]);
            $r['tries'] = $try;
            return $r;
        }
        if ($try < $tries) {
            /* مکثِ فزاینده: ۲، ۴، ۸ … ثانیه (سقفِ DEDUP_PAGE_WAIT_MAX) */
            $wait = min((int)DEDUP_PAGE_WAIT_MAX, (int)(DEDUP_PAGE_WAIT_BASE * pow(2, $try - 1)));
            dedupProgress(['log_add' => ['↻ ' . $who . ' صفحهٔ ' . $page . ' ناموفق (HTTP '
                . ($r['code'] ?? '?') . ') — تلاشِ ' . ($try + 1) . ' از ' . $tries
                . ' بعد از ' . $wait . ' ثانیه']]);
            sleep($wait);
        }
    }
    $r['tries'] = $tries;
    return $r;
}

/** همهٔ محصولاتِ باسلام برای حذفِ تکراری (با قیمت/موجودی/وضعیت)
 *
 *  v10.23 (۳۶ب): $partial با ارجاع پر می‌شود. قبلاً وقتی برداشت وسطِ کار
 *  می‌شکست (یا کاربر توقف می‌زد) تابع همان چیزی را که تا آن لحظه گرفته بود
 *  برمی‌گرداند و کسی نمی‌فهمید فهرست ناقص است — بعد گروه‌بندی روی نصفِ
 *  محصولات انجام می‌شد و «تکراری‌ها» ناقص گزارش می‌شدند. حالا این پرچم تا
 *  گزارشِ نهایی و رابط بالا می‌آید و در حالتِ حذف، از حذف جلوگیری می‌کند. */
function dedupCursorLoad(string $target, int $vid = 0): array {
    $f = DEDUP_FETCH_CURSOR_FILE;
    if (!is_file($f)) return ['rows' => [], 'page' => 0];
    $rows = []; $page = 0;
    foreach ((array)@file($f, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $line) {
        $d = json_decode($line, true);
        if (!is_array($d) || (string)($d['target'] ?? '') !== $target
            || (int)($d['vid'] ?? 0) !== $vid) continue;
        foreach ((array)($d['rows'] ?? []) as $r) if (is_array($r)) $rows[] = $r;
        $page = max($page, (int)($d['page'] ?? 0));
    }
    return ['rows' => $rows, 'page' => $page];
}

function dedupCursorAppend(string $target, int $vid, int $page, array $rows): void {
    if (!$rows) return;
    @file_put_contents(DEDUP_FETCH_CURSOR_FILE,
        json_encode(['target' => $target, 'vid' => $vid, 'page' => $page, 'rows' => $rows], JSON_UNESCAPED_UNICODE) . "\n",
        FILE_APPEND | LOCK_EX);
}

/** همهٔ محصولاتِ باسلام برای حذفِ تکراری (با قیمت/موجودی/وضعیت)
 *
 *  v10.23 (۳۶ب): $partial با ارجاع پر می‌شود. قبلاً وقتی برداشت وسطِ کار
 *  می‌شکست (یا کاربر توقف می‌زد) تابع همان چیزی را که تا آن لحظه گرفته بود
 *  برمی‌گرداند و کسی نمی‌فهمید فهرست ناقص است — بعد گروه‌بندی روی نصفِ
 *  محصولات انجام می‌شد و «تکراری‌ها» ناقص گزارش می‌شدند. حالا این پرچم تا
 *  گزارشِ نهایی و رابط بالا می‌آید و در حالتِ حذف، از حذف جلوگیری می‌کند. */
function dedupFetchBsl(string $tk, int $vid, int $maxPages = DEDUP_MAX_PAGES, ?array &$partial = null): array {
    $cursor = dedupCursorLoad('bsl', $vid);
    $rows = array_values(array_filter((array)($cursor['rows'] ?? []), 'is_array'));
    $firstPage = max(1, (int)($cursor['page'] ?? 0) + 1);
    $statuses = '&statuses=2976&statuses=3790&statuses=3567&statuses=3568&statuses=4184';
    for ($page = $firstPage; $page < $firstPage + $maxPages; $page++) {
        if (dedupStopRequested()) {
            dedupProgress(['log_add' => ['⏹ توقف در صفحهٔ ' . $page]]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'stopped', 'page' => $page];
            break;
        }
        /* v10.18 (۳۱ج): به‌جای توقفِ فوری، همین صفحه چند بار با مکثِ فزاینده
           دوباره خواسته می‌شود؛ خطای گذرای ۵۰۰ دیگر کلِ برداشت را نمی‌بندد. */
        $r = dedupFetchPage(function () use ($tk, $vid, $page, $statuses) {
            return bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $page . '&per_page=100' . $statuses);
        }, $page, 'باسلام');
        if (empty($r['ok'])) {
            dedupProgress(['log_add' => ['⚠️ صفحهٔ ' . $page . ' بعد از ' . (int)($r['tries'] ?? 1)
                . ' تلاش ناموفق ماند (HTTP ' . ($r['code'] ?? '?') . ') — برداشت با '
                . count($rows) . ' محصول متوقف شد']]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'http',
                'page' => $page, 'code' => (int)($r['code'] ?? 0), 'tries' => (int)($r['tries'] ?? 1)];
            break;
        }
        /* v10.40 (۵۴الف): همان اصلاحِ bslCatalogBuild — ردیف‌ها با bslRowsOf
           (شکل‌های data/products/items) و total_page با bslMetaInt (زیرِ
           meta/pagination هم می‌گردد). با پیش‌فرضِ ۱، برداشت در پایانِ
           صفحهٔ یک می‌شکست بدونِ اینکه ناقص علامت بخورد. */
        $batch = bslRowsOf($r['body']);
        if (!$batch) break;
        $tp = bslMetaInt($r['body'], 'total_page', 0);
        $pageRows = [];
        foreach ($batch as $p) {
            if (!is_array($p)) continue;
            $rev  = $p['revision']['data'] ?? [];
            $name = trim((string)($p['title'] ?? ($p['name'] ?? ($rev['title'] ?? ''))));
            if ($name === '') continue;
            $st = $p['status'] ?? null;
            $pageRows[] = [
                'id'     => (int)($p['id'] ?? 0),
                'name'   => $name,
                'status' => (int)(is_array($st) ? ($st['value'] ?? 0) : $st),
                'price'  => (int)($rev['primary_price'] ?? ($p['price'] ?? 0)),
                'stock'  => (int)($rev['stock'] ?? ($p['stock'] ?? 0)),
                'ts'     => (int)($p['id'] ?? 0),
            ];
        }
        $rows = array_merge($rows, $pageRows);
        dedupCursorAppend('bsl', $vid, $page, $pageRows);
        dedupProgress(['fetched' => count($rows), 'page' => $page, 'pages' => $tp,
            'log_add' => ['📄 باسلام صفحهٔ ' . $page . '/' . ($tp > 0 ? $tp : '?') . ': ' . count($batch)
                . ' محصول (مجموع ' . count($rows) . ')']]);
        /* صفحهٔ ناقص قطعی‌ترین نشانهٔ پایان است؛ total_page فقط وقتی
           معتبر است که واقعاً آمده باشد. */
        if (count($batch) < 100) break;
        if ($tp > 0 && $page >= $tp) break;
        /* v10.23 (۳۶ب): رسیدن به سقفِ صفحات هم «برداشتِ ناقص» است */
        if ($page >= $firstPage + $maxPages - 1) {
            dedupProgress(['log_add' => ['⚠️ سقفِ ' . $maxPages . ' صفحه پر شد ولی فروشگاه '
                . ($tp > 0 ? $tp : 'بیش از این') . ' صفحه دارد — فهرست ناقص است']]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'max_pages',
                'page' => $page, 'pages' => $tp];
        }
        usleep(150000);
    }
    if ($page >= $firstPage + $maxPages && $partial !== null && empty($partial)) {
        $partial = ['partial' => true, 'reason' => 'max_pages', 'page' => $page - 1];
        dedupProgress(['log_add' => ['⚠️ سقفِ برداشتِ باسلام رسید — checkpoint صفحهٔ ' . ($page - 1) . ' حفظ شد']]);
    }
    return $rows;
}

/* =====================================================================
 *  v10.39 (۵۳): برداشتِ چندغرفه‌ایِ باسلام برای حذفِ تکراری
 *
 *  سه تغییرِ خواستهٔ کاربر، همه اینجا جمع‌اند:
 *
 *  ۱) «فقط در محصولات فعال جستجو کند» — تا ۱۰.۳۸ پنج وضعیت پرس‌وجو
 *     می‌شد (فعال، غیرفعال، تأییدنشده، در انتظار، بایگانی) و بعد همه با هم
 *     مقایسه می‌شدند. یعنی یک محصولِ فعال می‌توانست به بهانهٔ هم‌نامیِ یک
 *     نسخهٔ بایگانی حذف شود. حالا فیلترِ 2976 پیش از گروه‌بندی اعمال
 *     می‌شود.
 *
 *  ۲) «اگر محصول در دو یا چند غرفه باشد نادیده گرفته شود» — عنوانی که در
 *     بیش از یک غرفه دیده شود کلاً از گروه‌بندی کنار می‌رود. این عمداً
 *     محافظه‌کارانه است: چنین عنوانی معمولاً همان محصول است که به چند غرفه
 *     ارسال شده، نه یک تکراریِ اشتباهی. تکراریِ *داخلِ* یک غرفه همچنان
 *     حذف می‌شود (انتخابِ صریحِ کاربر).
 *
 *  ۳) «فهرستِ آماده» — به‌جای برداشتِ زنده از سرورِ باسلام، از کشِ
 *     کاتالوگ خوانده می‌شود که هر چند ساعت یک‌بار ساخته می‌شود.
 * ===================================================================== */
function dedupFetchBslAll(array $cn, array $cfg, ?array &$partial = null): array {
    $shops = bslAllShops($cn);
    if (empty($cfg['all_vendors'])) {
        /* فقط غرفهٔ پیش‌فرض — رفتارِ نسخه‌های قبل */
        $shops = array_values(array_filter($shops, function ($s) { return !empty($s['is_default']); }));
        if (!$shops) $shops = array_slice(bslAllShops($cn), 0, 1);
    }
    if (!$shops) return [];

    $useCache = !empty($cfg['use_cache']);
    $rows = []; $byTitleVendors = []; $anyPartial = false; $reason = '';
    /* الگوها یک‌بار ساخته می‌شوند؛ dedupNormalize بدونِ این آرگومان هر بار
       برای *هر ردیف* دوباره regexها را می‌سازد و روی چند هزار محصول
       به‌شدت کند می‌شود. */
    $pats = dedupPatterns($cfg);

    foreach ($shops as $sh) {
        if (dedupStopRequested()) {
            $anyPartial = true; $reason = 'stopped'; break;
        }
        $vid = (int)($sh['vendor_id'] ?? 0);
        $tk  = (string)($sh['token'] ?? '');
        if ($vid <= 0 || $tk === '') continue;
        $nm = (string)($sh['shop_name'] ?? ('غرفهٔ ' . $vid));

        if ($useCache) {
            $got  = bslCatalogRows($tk, $vid, true);
            $vr   = $got['rows'];
            if (!empty($got['partial'])) { $anyPartial = true; if ($reason === '') $reason = 'cache_partial'; }
            $age  = $got['at'] > 0 ? max(0, time() - (int)$got['at']) : 0;
            dedupProgress(['log_add' => ['🗂 ' . $nm . ': ' . count($vr) . ' محصول از '
                . ($got['from'] === 'network' ? 'فهرستِ تازه‌ساخته' : 'فهرستِ آماده')
                . ($got['from'] === 'cache' ? ' (' . dedupAgeFa($age) . ' پیش)' : '')]]);
        } else {
            $vp = [];
            $vr = dedupFetchBsl($tk, $vid, DEDUP_MAX_PAGES, $vp);
            if (!empty($vp['partial'])) {
                $anyPartial = true;
                if ($reason === '') $reason = (string)($vp['reason'] ?? 'http');
            }
        }

        foreach ($vr as $r) {
            if (!is_array($r)) continue;
            /* فیلترِ «فقط فعال» — پیش از هر مقایسه‌ای */
            if (!empty($cfg['active_only']) && (int)($r['status'] ?? 0) !== 2976) continue;
            $r['vendor_id']   = $vid;
            $r['vendor_name'] = $nm;
            $rows[] = $r;
            $n = dedupNormalize((string)($r['name'] ?? ''), $cfg, $pats);
            if ($n !== '') $byTitleVendors[$n][$vid] = true;
        }
    }

    /* گامِ «نادیده‌گرفتنِ محصولاتِ چندغرفه‌ای» */
    $skipped = 0; $skipTitles = 0;
    if (!empty($cfg['skip_multi'])) {
        $keep = [];
        foreach ($rows as $r) {
            $n = dedupNormalize((string)($r['name'] ?? ''), $cfg, $pats);
            if ($n !== '' && count($byTitleVendors[$n] ?? []) > 1) { $skipped++; continue; }
            $keep[] = $r;
        }
        foreach ($byTitleVendors as $vs) if (count($vs) > 1) $skipTitles++;
        $rows = $keep;
    }

    dedupProgress(['multi_skipped' => $skipped, 'multi_titles' => $skipTitles,
        'vendors' => count($shops), 'fetched' => count($rows),
        'log_add' => ['✅ مجموعاً ' . count($rows) . ' محصول'
            . (!empty($cfg['active_only']) ? ' (فقط فعال)' : '')
            . ' از ' . count($shops) . ' غرفه'
            . ($skipped > 0 ? ' — ' . $skipTitles . ' عنوان که در چند غرفه بود ('
                . $skipped . ' محصول) نادیده گرفته شد' : '')]]);

    if ($anyPartial && $partial !== null) $partial = ['partial' => true, 'reason' => $reason ?: 'http'];
    return $rows;
}

/** سنِ خوانا برای گزارشِ فهرستِ آماده */
function dedupAgeFa(int $sec): string {
    if ($sec < 60)   return 'کمتر از یک دقیقه';
    if ($sec < 3600) return (int)round($sec / 60) . ' دقیقه';
    return round($sec / 3600, 1) . ' ساعت';
}

/** همهٔ محصولاتِ ووکامرس برای حذفِ تکراری (v10.23 (۳۶ب): با پرچمِ ناقص‌بودن) */
function dedupFetchWoo(array $w, int $maxPages = DEDUP_MAX_PAGES, ?array &$partial = null): array {
    $cursor = dedupCursorLoad('woo', 0);
    $rows = array_values(array_filter((array)($cursor['rows'] ?? []), 'is_array'));
    $firstPage = max(1, (int)($cursor['page'] ?? 0) + 1);
    for ($page = $firstPage; $page < $firstPage + $maxPages; $page++) {
        if (dedupStopRequested()) {
            dedupProgress(['log_add' => ['⏹ توقف در صفحهٔ ' . $page]]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'stopped', 'page' => $page];
            break;
        }
        /* v10.18 (۳۱ج): همان تلاشِ مجددِ باسلام برای ووکامرس */
        $r = dedupFetchPage(function () use ($w, $page) {
            $rr = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
                'products?per_page=100&status=any&orderby=id&order=asc&page=' . $page);
            if (!is_array($rr['body'] ?? null)) $rr['ok'] = false;
            return $rr;
        }, $page, 'ووکامرس');
        if (empty($r['ok']) || !is_array($r['body'])) {
            dedupProgress(['log_add' => ['⚠️ صفحهٔ ' . $page . ' بعد از ' . (int)($r['tries'] ?? 1)
                . ' تلاش ناموفق ماند (HTTP ' . ($r['code'] ?? '?') . ') — برداشت با '
                . count($rows) . ' محصول متوقف شد']]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'http',
                'page' => $page, 'code' => (int)($r['code'] ?? 0), 'tries' => (int)($r['tries'] ?? 1)];
            break;
        }
        $batch = $r['body'];
        if (!$batch) break;
        $pageRows = [];
        foreach ($batch as $p) {
            if (!is_array($p)) continue;
            $name = trim((string)($p['name'] ?? ''));
            if ($name === '') continue;
            $pr = $p['regular_price'] ?? '';
            if ($pr === '' || $pr === null) $pr = $p['price'] ?? '';
            $pageRows[] = [
                'id'      => (int)($p['id'] ?? 0),
                'name'    => $name,
                'wstatus' => (string)($p['status'] ?? ''),
                'price'   => $pr,
                'stock'   => (int)($p['stock_quantity'] ?? 0),
                'date_created' => (string)($p['date_created'] ?? ''),
                'sku'     => (string)($p['sku'] ?? ''),
            ];
        }
        $rows = array_merge($rows, $pageRows);
        dedupCursorAppend('woo', 0, $page, $pageRows);
        dedupProgress(['fetched' => count($rows), 'page' => $page,
            'log_add' => ['📄 ووکامرس صفحهٔ ' . $page . ': ' . count($batch)
                . ' محصول (مجموع ' . count($rows) . ')']]);
        if (count($batch) < 100) break;
        if ($page >= $firstPage + $maxPages - 1) {
            dedupProgress(['log_add' => ['⚠️ سقفِ ' . $maxPages . ' صفحه پر شد و صفحهٔ پُر هم آمد — فهرست ناقص است']]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'max_pages', 'page' => $page];
        }
        usleep(150000);
    }
    if ($page >= $firstPage + $maxPages && $partial !== null && empty($partial)) {
        $partial = ['partial' => true, 'reason' => 'max_pages', 'page' => $page - 1];
        dedupProgress(['log_add' => ['⚠️ سقفِ برداشتِ ووکامرس رسید — checkpoint صفحهٔ ' . ($page - 1) . ' حفظ شد']]);
    }
    return $rows;
}

/**
 * کارِ کاملِ حذفِ تکراری — این تابع می‌تواند چند دقیقه طول بکشد و فقط از
 * مسیرِ پس‌زمینه صدا زده می‌شود.
 *
 * $mode: 'scan' فقط گزارش · 'delete' واقعاً حذف/بایگانی کن
 */
function dedupRun(array $cn, string $target, array $cfg, string $mode, ?array $cp = null): array {
    $t0 = microtime(true);
    dedupProgress(['phase' => 'fetch', 'log_add' => ['🔍 دریافتِ فهرستِ محصولات...']]);

    /* v10.23 (۳۶ب): پرچمِ «برداشتِ ناقص» — با ارجاع پر می‌شود */
    $partial = [];
    if ($target === 'bsl') {
        $bs = $cn['basalam'] ?? [];
        if (empty($bs['token']) || empty($bs['vendor_id'])) return ['ok' => false, 'error' => 'تنظیمات باسلام ناقص است'];
        /* v10.39 (۵۳): چندغرفه‌ای + فقط فعال + از فهرستِ آماده */
        $rows = dedupFetchBslAll($cn, $cfg, $partial);
    } else {
        $w = $cn['woocommerce'] ?? [];
        if (empty($w['store_url'])) return ['ok' => false, 'error' => 'تنظیمات ووکامرس ناقص است'];
        $rows = dedupFetchWoo($w, DEDUP_MAX_PAGES, $partial);
    }
    $cpStartedAt = (is_array($cp) ? (int)($cp['started_at'] ?? 0) : 0);
    if (!$rows) {
        if (!empty($partial['partial'])) {
            $fetchCp = ['phase' => 'fetch', 'target' => $target, 'mode' => $mode,
                'done_ids' => (array)($cp['done_ids'] ?? []), 'deleted' => (int)($cp['deleted'] ?? 0),
                'failed' => (int)($cp['failed'] ?? 0), 'started_at' => $cpStartedAt > 0 ? $cpStartedAt : time()];
            dedupProgress(['running' => false, 'done' => true, 'partial' => true, 'stale' => true,
                'checkpoint' => $fetchCp, 'log_add' => ['⚠️ برداشت هنوز محصولی برنگردانده؛ checkpoint حفظ شد']]);
            return ['ok' => false, 'partial' => true, 'error' => 'برداشت محصول ناقص ماند؛ در اجرای بعدی ادامه می‌یابد'];
        }
        return ['ok' => false, 'error' => 'هیچ محصولی دریافت نشد'];
    }

    /* v10.23 (۳۶ب): اگر فهرست ناقص باشد، حذف بسیار خطرناک است — «تنها نسخهٔ
       باقی‌مانده» ممکن است در صفحه‌ای باشد که اصلاً دریافت نشده و آن‌وقت
       نسخه‌ای که اینجا «تکراری» دیده می‌شود در واقع تنها نسخهٔ موجود است.
       پس در حالتِ حذف فقط گزارش می‌دهیم و صریح می‌گوییم چرا. */
    $partialReason = [
        'stopped'   => 'کاربر وسطِ برداشت توقف زد',
        'http'      => 'یک صفحه بعد از چند تلاش هم نیامد',
        'max_pages' => 'سقفِ صفحاتِ برداشت پر شد',
    ];
    $isPartial = !empty($partial['partial']);
    if ($isPartial) {
        dedupProgress(['partial' => true,
            'partial_reason' => (string)($partial['reason'] ?? ''),
            'log_add' => ['⚠️ فهرست ناقص است ('
                . ($partialReason[(string)($partial['reason'] ?? '')] ?? 'نامعلوم')
                . ') — فقط ' . count($rows) . ' محصول دریافت شد'
                . ($mode === 'delete' ? '؛ برای ایمنی حذف انجام نمی‌شود' : '')]]);
        if ($mode === 'delete') $mode = 'scan';
        $fetchCp = ['phase' => 'fetch', 'target' => $target, 'mode' => $mode,
            'done_ids' => (array)($cp['done_ids'] ?? []), 'deleted' => (int)($cp['deleted'] ?? 0),
            'failed' => (int)($cp['failed'] ?? 0), 'started_at' => $cpStartedAt > 0 ? $cpStartedAt : time(),
            'fetch_page' => (int)($partial['page'] ?? 0), 'fetch_reason' => (string)($partial['reason'] ?? '')];
        dedupProgress(['checkpoint' => $fetchCp]);
    }

    /* v10.126: ادامهٔ واقعی — شناسه‌هایی که در اجرای قبلی حذف/بایگانی شده‌اند
       (done_ids) از فهرست کنار می‌روند تا دوباره پردازش نشوند. باسلام بایگانی
       را حذف نمی‌کند و همین شناسه‌ها در واکشیِ بعدی هم برمی‌گردند. */
    $cpDoneIds = [];
    if (is_array($cp)) {
        $cpDoneIds = array_values(array_filter(array_map('intval', (array)($cp['done_ids'] ?? [])), function ($x) { return $x > 0; }));
        if ($cpDoneIds) {
            $doneSet = array_fill_keys($cpDoneIds, true);
            $before = count($rows);
            $rows = array_values(array_filter($rows, function ($r) use ($doneSet) {
                return !isset($doneSet[(int)($r['id'] ?? 0)]);
            }));
            if (count($rows) !== $before) {
                dedupProgress(['log_add' => ['↻ ' . ($before - count($rows))
                    . ' موردِ ازقبل‌پردازش‌شده از چک‌پوینت رد شد']]);
            }
        }
    }

    dedupProgress(['phase' => 'group', 'total' => count($rows),
        'log_add' => ['🧮 ' . count($rows) . ' محصول دریافت شد؛ گروه‌بندی بر اساس عنوان...']]);

    $groups = dedupGroup($rows, $cfg);
    $dupGroups = []; $dupCount = 0;
    foreach ($groups as $norm => $items) {
        if (count($items) < 2) continue;
        $pick = dedupPickKeeper($items, $cfg);
        $dupCount += count($pick['drop']);
        $dupGroups[] = ['norm' => dedupGroupNorm((string)$norm), 'count' => count($items),
                        'vendor_id'   => (int)($items[0]['vendor_id'] ?? 0),
                        'vendor_name' => (string)($items[0]['vendor_name'] ?? ''),
                        'keep' => $pick['keep'], 'drop' => $pick['drop']];
    }
    usort($dupGroups, function ($a, $b) { return $b['count'] <=> $a['count']; });

    dedupProgress(['phase' => $mode === 'delete' ? 'delete' : 'done',
        'groups' => count($dupGroups), 'dups' => $dupCount,
        'log_add' => ['🔎 ' . count($dupGroups) . ' گروهِ هم‌نام با مجموعاً ' . $dupCount
            . ' نسخهٔ اضافی — معیارِ نگه‌داری: ' . dedupKeepLabel($cfg['keep'])]]);

    /* v10.126: شمارنده‌ها از چک‌پوینت شروع می‌شوند تا جمعِ کل (نه فقط این
       اجرا) دیده شود و امضای پیشرفتِ v10.125 هم یکنوا بالا برود. */
    $deleted = (int)($cp['deleted'] ?? 0);
    $failed  = (int)($cp['failed'] ?? 0);
    $errors  = [];
    $stopDuringDelete = false;
    if ($mode === 'delete' && $dupCount > 0) {
        $done = (int)($cp['done'] ?? 0);
        foreach ($dupGroups as $gi => $g) {
            if (dedupStopRequested()) { $stopDuringDelete = true; dedupProgress(['log_add' => ['⏹ حذف با درخواستِ کاربر متوقف شد']]); break; }
            foreach ($g['drop'] as $d) {
                if (dedupStopRequested()) { $stopDuringDelete = true; break; }
                $did = (int)($d['id'] ?? 0);
                if ($did <= 0) continue;
                /* v10.23 (۳۶ب): خودِ حذف/بایگانی هم تلاشِ مجدد دارد. تا اینجا
                   فقط *برداشتِ* صفحات retry داشت؛ خودِ عملیات یک‌باره بود و
                   یک ۵۰۰/۴۲۹ گذرا محصول را برای همیشه در ستونِ «ناموفق»
                   می‌نشاند. مکث فزاینده است تا ریت‌لیمیت هم فرصت بازیابی بگیرد. */
                $ok = false; $em = ''; $dTries = 0;
                for ($dt = 1; $dt <= (int)DEDUP_DEL_TRIES; $dt++) {
                    $dTries = $dt;
                    if ($dt > 1 && dedupStopRequested()) break;
                    if ($target === 'bsl') {
                        /* v10.39 (۵۳): با اسکنِ چندغرفه‌ای، محصول لزوماً مالِ
                           غرفهٔ پیش‌فرض نیست. توکن/شناسهٔ خودِ همان غرفه باید
                           استفاده شود وگرنه باسلام ۴۰۳ می‌دهد.
                           v10.42 (۵۶): همان منطق حالا در bslArchiveSmart جمع
                           شده تا این مسیر و مسیرِ dedup_delete_ids دقیقاً یک
                           رفتار داشته باشند (قبلاً فقط این یکی درست بود) و
                           متنِ خطا هم به‌جای «HTTP ?» گویا باشد. */
                        $dVid = (int)($d['vendor_id'] ?? ($g['vendor_id'] ?? 0));
                        $r  = bslArchiveSmart($cn, $did, $dVid);
                        $ok = !empty($r['ok']);
                        $em = (string)($r['msg'] ?? '');
                    } else {
                        $w = $cn['woocommerce'] ?? [];
                        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                            'DELETE', 'products/' . $did . '?force=true');
                        $ok = !empty($r['ok']);
                        $em = $r['body']['message'] ?? ('HTTP ' . ($r['code'] ?? '?'));
                    }
                    if ($ok) break;
                    /* ۴۰۴/۴۰۳ یعنی «دیگر نیست یا اجازه نداریم» — تکرارش بی‌فایده است */
                    $code = (int)($r['code'] ?? 0);
                    if (in_array($code, [400, 401, 403, 404], true)) break;
                    if ($dt < (int)DEDUP_DEL_TRIES) {
                        $wait = min((int)DEDUP_PAGE_WAIT_MAX, (int)(DEDUP_DEL_WAIT_BASE * pow(2, $dt - 1)));
                        dedupProgress(['log_add' => ['↻ #' . $did . ' ناموفق (HTTP ' . ($code ?: '?')
                            . ') — تلاشِ ' . ($dt + 1) . ' از ' . DEDUP_DEL_TRIES . ' بعد از ' . $wait . ' ثانیه']]);
                        sleep($wait);
                    }
                }
                $done++;
                if ($ok) {
                    $deleted++;
                    dedupProgress(['deleted' => $deleted, 'failed' => $failed, 'processed' => $done,
                        'log_add' => ['✅ ' . ($target === 'bsl' ? 'بایگانی' : 'حذف') . ' #' . $did
                            . ($dTries > 1 ? (' (تلاشِ ' . $dTries . 'ام)') : '')
                            . ' — ' . mb_substr((string)$d['name'], 0, 45, 'UTF-8')]]);
                } else {
                    $failed++;
                    if (count($errors) < 30) $errors[] = ['id' => $did, 'msg' => (string)$em];
                    dedupProgress(['deleted' => $deleted, 'failed' => $failed, 'processed' => $done,
                        'log_add' => ['❌ #' . $did . ' — ' . mb_substr((string)$em, 0, 70, 'UTF-8')]]);
                }
                /* v10.126: چک‌پوینت پس از هر مورد — اگر پردازه همین‌جا کشته
                   شود، ادامهٔ بعدی از این شناسه‌ها می‌گذرد و شمارنده‌ها حفظ
                   می‌شوند. */
                if ($ok) $cpDoneIds[] = $did;
                dedupProgress(['checkpoint' => [
                    'done_ids' => $cpDoneIds, 'deleted' => $deleted, 'failed' => $failed,
                    'done' => $done, 'started_at' => ($cpStartedAt > 0 ? $cpStartedAt : time())]]);
                usleep(250000);
            }
            if ($gi % 10 === 9) dedupProgress(['log_add' => ['— ' . ($gi + 1) . ' گروه پردازش شد —']]);
        }
    }

    // فقط بخشی از گروه‌ها را در نتیجه نگه می‌داریم تا فایل غول‌آسا نشود
    $out = [];
    foreach (array_slice($dupGroups, 0, DEDUP_MAX_GROUPS) as $g) {
        /* v10.42 (۵۶): vendor_id هر ردیف هم در گزارش می‌ماند. بدونِ آن،
           هندلرِ dedup_delete_ids (که فقط فهرستِ id می‌گیرد) نمی‌دانست هر
           محصول مالِ کدام غرفه است و همه را با توکنِ غرفهٔ پیش‌فرض بایگانی
           می‌کرد ⇒ ۴۰۳ برای هرچه مالِ غرفهٔ دیگری بود. */
        $mk = function (array $p) use ($g) {
            return ['id' => (int)($p['id'] ?? 0), 'name' => (string)($p['name'] ?? ''),
                    'price' => dedupPrice($p), 'stock' => (int)($p['stock'] ?? 0),
                    'status' => (int)($p['status'] ?? 0), 'wstatus' => (string)($p['wstatus'] ?? ''),
                    'vendor_id' => (int)($p['vendor_id'] ?? ($g['vendor_id'] ?? 0)),
                    'ts' => dedupTs($p), 'date_created' => (string)($p['date_created'] ?? '')];
        };
        /* v10.39 (۵۳): نامِ غرفه هم می‌رود تا در گزارشِ چندغرفه‌ای معلوم باشد
           هر گروه مالِ کدام غرفه است */
        $out[] = ['normalized' => $g['norm'], 'count' => $g['count'],
                  'vendor_id'   => (int)($g['vendor_id'] ?? 0),
                  'vendor_name' => (string)($g['vendor_name'] ?? ''),
                  'keep' => $mk($g['keep']), 'drop' => array_map($mk, $g['drop'])];
    }

    return ['ok' => true, 'target' => $target, 'mode' => $mode, 'cfg' => $cfg,
            'total' => count($rows), 'groups' => count($dupGroups), 'duplicates' => $dupCount,
            'deleted' => $deleted, 'failed' => $failed, 'errors' => $errors,
            'partial' => $isPartial || $stopDuringDelete,
            'stopped' => $stopDuringDelete,
            'partial_reason' => $isPartial ? (string)($partial['reason'] ?? '') : ($stopDuringDelete ? 'stopped' : ''),
            'partial_msg' => $isPartial
                ? ('فهرست ناقص دریافت شد — ' . ($partialReason[(string)($partial['reason'] ?? '')] ?? 'علتِ نامعلوم')
                   . '. گروه‌بندی روی همین ' . count($rows) . ' محصول انجام شد و برای ایمنی حذفی صورت نگرفت.')
                : '',
            'truncated' => count($dupGroups) > DEDUP_MAX_GROUPS,
            'took' => round(microtime(true) - $t0, 1), 'at' => time(),
            'duplicates_list' => $out];
}

/* =====================================================================
 *  v10.23 (۳۶د): «اصلاح دسته‌بندی محصولات باسلام» — موتورِ پس‌زمینه
 *
 *  چه چیزی عوض شد و چرا:
 *
 *  تا نسخهٔ ۱۰٫۲۲ هر سه مسیرِ این جریان (اصلاح با متنِ AIِ خودِ باسلام،
 *  اصلاح با مدلِ مستر، و اجماعِ چندمدلی) فقط «رویدادِ زنده» (SSE) بودند.
 *  یعنی کار در همان درخواستِ مرورگر می‌دوید. عوارضش دقیقاً همان چیزهایی
 *  بود که کاربر گزارش کرد:
 *
 *    • بستنِ تب یا رفتنِ گوشی به حالتِ خواب ⇒ کار وسطِ راه می‌مرد و
 *      محصولاتِ بعدی هیچ‌وقت اصلاح نمی‌شدند.
 *    • هیچ قفلی نبود ⇒ دو تبِ باز = دو اجرای موازی روی یک غرفه؛ هر دو
 *      همان محصول را PATCH می‌کردند و سهمیهٔ API دوبرابر می‌سوخت.
 *    • هیچ دکمهٔ توقفی وجود نداشت؛ تنها راه، بستنِ پنجره بود.
 *    • و مهم‌تر از همه: در «مدیر وظیفه» اصلاً دیده نمی‌شد. کاربر نمی‌دانست
 *      چنین کاری اصلاً در جریان است.
 *
 *  حالا عیناً همان الگویِ dedup/ایجنت را دارد: قفلِ انحصاری، پاسخِ زودهنگام
 *  و ادامهٔ کار در پس‌زمینهٔ سرور، فایلِ پیشرفت با لاگ و درصد، فایلِ نتیجه،
 *  فایلِ سیگنالِ توقف — و یک ردیف در رجیستریِ مدیر وظیفه.
 * ===================================================================== */

function catfixProgress(array $patch): void {
    $cur = [];
    if (is_file(CATFIX_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true);
        if (is_array($d)) $cur = $d;
    }
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 400) $log = array_slice($log, -400);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['ts'] = time();
    writeProgress(CATFIX_PROGRESS_FILE, $cur);
}

function catfixStopRequested(): bool { return is_file(CATFIX_STOP_FILE); }
function catfixClearStop(): void { @unlink(CATFIX_STOP_FILE); }

/** برچسبِ خوانای حالت‌های اجرا */
function catfixModeLabel(string $mode): string {
    /* v10.71 (85): روشِ چهارم — زنجیرهٔ پشتیبان */
    $m = ['ai_text' => 'متنِ بررسیِ باسلام', 'master' => 'مدلِ مستر', 'quorum' => 'اجماعِ چندمدلی',
          'fallback' => 'زنجیرهٔ پشتیبان (مستر ← کاندیدها)'];
    return $m[$mode] ?? $mode;
}

/** درختِ دسته‌بندیِ باسلام را تخت می‌کند — همان تابعِ درون‌خطیِ چهار اندپوینتِ قبلی */
function catfixFlatCats(string $tk): array {
    /* v10.41 (۵۵): از کشِ مشترک — دیگر هر بار از باسلام گرفته نمی‌شود */
    return bslCatsAll($tk);
}

/** فهرستِ محصولاتِ ردشده (وضعیت ۳۵۶۷) — با پرچمِ ناقص‌بودن، مثلِ dedup */
function catfixCursorLoad(int $vid): array {
    if (!is_file(CATFIX_FETCH_CURSOR_FILE)) return ['rows' => [], 'page' => 0];
    $rows = []; $page = 0;
    foreach ((array)@file(CATFIX_FETCH_CURSOR_FILE, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $line) {
        $d = json_decode($line, true);
        if (!is_array($d) || (int)($d['vid'] ?? 0) !== $vid) continue;
        foreach ((array)($d['rows'] ?? []) as $r) if (is_array($r)) $rows[] = $r;
        $page = max($page, (int)($d['page'] ?? 0));
    }
    return ['rows' => $rows, 'page' => $page];
}
function catfixCursorAppend(int $vid, int $page, array $rows): void {
    if (!$rows) return;
    @file_put_contents(CATFIX_FETCH_CURSOR_FILE,
        json_encode(['vid' => $vid, 'page' => $page, 'rows' => $rows], JSON_UNESCAPED_UNICODE) . "\n",
        FILE_APPEND | LOCK_EX);
}

/** فهرستِ محصولاتِ ردشده (وضعیت ۳۵۶۷) — با cursor صفحه‌ای و پرچمِ ناقص‌بودن */
function catfixFetchRejected(string $tk, int $vid, ?array &$partial = null, ?array &$meta = null): array {
    $meta = ['complete' => false, 'partial' => false, 'stopped' => false, 'reason' => '', 'page' => 0];
    $cursor = catfixCursorLoad($vid);
    $all = array_values(array_filter((array)($cursor['rows'] ?? []), 'is_array'));
    $firstPage = max(1, (int)($cursor['page'] ?? 0) + 1);
    for ($pg = $firstPage; $pg < $firstPage + CATFIX_MAX_PAGES; $pg++) {
        if (catfixStopRequested()) {
            $meta['partial'] = true; $meta['stopped'] = true; $meta['reason'] = 'stopped'; $meta['page'] = $pg;
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'stopped', 'page' => $pg];
            catfixProgress(['log_add' => ['⏹ توقف هنگام دریافتِ صفحهٔ ' . $pg . ' — checkpoint حفظ شد']]);
            break;
        }
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $pg . '&per_page=100&statuses=3567');
        if (empty($r['ok'])) {
            $meta['partial'] = true; $meta['reason'] = 'http'; $meta['page'] = $pg;
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'http', 'page' => $pg, 'code' => (int)($r['code'] ?? 0)];
            catfixProgress(['log_add' => ['⚠️ صفحهٔ ' . $pg . ' نیامد (HTTP ' . ($r['code'] ?? '?') . ') — checkpoint حفظ شد']]);
            break;
        }
        $data = bslRowsOf($r['body']);
        if (!$data) { $meta['complete'] = true; $meta['page'] = max(0, $pg - 1); break; }
        $tp = bslMetaInt($r['body'], 'total_page', 0);
        $pageRows = [];
        foreach ($data as $item) if (is_array($item)) $pageRows[] = $item;
        $all = array_merge($all, $pageRows);
        catfixCursorAppend($vid, $pg, $pageRows);
        $meta['page'] = $pg;
        catfixProgress(['fetched' => count($all), 'page' => $pg, 'pages' => $tp,
            'log_add' => ['📄 صفحهٔ ' . $pg . '/' . ($tp > 0 ? $tp : '?') . ' — مجموعاً ' . count($all) . ' محصولِ ردشده']]);
        if (count($data) < 100 || ($tp > 0 && $pg >= $tp)) { $meta['complete'] = true; break; }
        usleep(120000);
    }
    if (!$meta['complete'] && !$meta['partial']) {
        $meta['partial'] = true; $meta['reason'] = 'max_pages'; $meta['page'] = $firstPage + CATFIX_MAX_PAGES - 1;
        if ($partial !== null) $partial = ['partial' => true, 'reason' => 'max_pages', 'page' => $meta['page']];
        catfixProgress(['log_add' => ['⚠️ سقفِ برداشت رسید — checkpoint صفحهٔ ' . $meta['page'] . ' حفظ شد']]);
    }
    return $all;
}

/**
 * اجرای کاملِ اصلاحِ دسته — می‌تواند چند دقیقه طول بکشد و فقط از مسیرِ
 * پس‌زمینه صدا زده می‌شود.
 *
 * $mode: 'ai_text' متنِ بررسیِ خودِ باسلام · 'master' فقط مدلِ مستر ·
 *        'quorum' اجماعِ چند مدلِ کاندید
 * $opts: ['quorum'=>int, 'product_id'=>int (فقط همین یک محصول)]
 */
function catfixRun(array $cn, string $mode, array $opts = [], ?array $cp = null): array {
    $t0 = microtime(true);
    $bs = $cn['basalam'] ?? [];
    if (empty($bs['token']) || empty($bs['vendor_id']))
        return ['ok' => false, 'error' => 'تنظیمات باسلام ناقص است'];
    $tk = (string)$bs['token']; $vid = (int)$bs['vendor_id'];
    /* v10.107: چندغرفه + اولویت یادگیری */
    $useLearn = !isset($opts['use_learn']) || !empty($opts['use_learn']);
    $learnFirst = !empty($opts['learn_first']) || !empty($opts['periodic']);
    $allVendors = !empty($opts['all_vendors']);
    $onlyVid = (int)($opts['vendor_id'] ?? 0);
    $learnedHits = 0;

    if ($allVendors && empty($opts['product_id'])) {
        $shops = function_exists('bslAllShops') ? bslAllShops($cn) : [];
        if (count($shops) > 1) {
            /* v10.129: checkpointِ چندغرفه‌ای یک‌جا برای همهٔ غرفه‌ها نیست.
               هر غرفه وضعیتِ مستقلِ خود (done_ids و شمارنده‌ها) دارد؛ بنابراین
               قطع وسطِ غرفهٔ دوم نه غرفهٔ اول را دوباره PATCH می‌کند و نه باعث
               می‌شود غرفهٔ دوم از اولِ فهرست شروع شود. */
            $seedAgg = is_array($cp['aggregate'] ?? null) ? $cp['aggregate'] : [];
            $agg = array_merge(['ok' => true, 'mode' => $mode, 'total' => 0, 'fixed' => 0, 'failed' => 0,
                    'no_ai' => 0, 'no_cat' => 0, 'skip_same' => 0, 'skip_tried' => 0,
                    'asked' => 0, 'cache_hits' => 0, 'learned_hits' => 0, 'items' => [],
                    'shops' => [], 'took' => 0, 'at' => time()], $seedAgg);
            $vendorState = is_array($cp['vendors'] ?? null) ? $cp['vendors'] : [];
            $addVendor = function (array $one, array $sh) use (&$agg): void {
                $vid0 = (int)($sh['vendor_id'] ?? 0);
                $nm0 = (string)($sh['shop_name'] ?? ('غرفهٔ ' . $vid0));
                $agg['shops'][] = ['vendor_id' => $vid0, 'shop_name' => $nm0,
                    'ok' => !empty($one['ok']), 'fixed' => (int)($one['fixed'] ?? 0),
                    'total' => (int)($one['total'] ?? 0), 'failed' => (int)($one['failed'] ?? 0),
                    'learned_hits' => (int)($one['learned_hits'] ?? 0)];
                foreach (['total','fixed','failed','no_ai','no_cat','skip_same','skip_tried','asked','cache_hits','learned_hits'] as $k)
                    $agg[$k] += (int)($one[$k] ?? 0);
                foreach ((array)($one['items'] ?? []) as $it) {
                    if (count($agg['items']) >= 500) break;
                    $it['shop_name'] = $nm0; $it['vendor_id'] = $vid0; $agg['items'][] = $it;
                }
                if (empty($one['ok']) && empty($agg['error'])) $agg['error'] = (string)($one['error'] ?? '');
            };
            $currentCp = is_array($cp) && (int)($cp['vendor_id'] ?? 0) > 0 ? $cp : null;
            foreach ($shops as $shopIndex => $sh) {
                if (!is_array($sh)) continue;
                $vid0 = (int)($sh['vendor_id'] ?? 0);
                $tok0 = trim((string)($sh['token'] ?? ''));
                if ($vid0 <= 0 || $tok0 === '') continue;
                $state0 = is_array($vendorState[(string)$vid0] ?? null) ? $vendorState[(string)$vid0] : [];
                if (!empty($state0['done'])) continue; // already included in aggregate
                $vendorCp = is_array($state0['checkpoint'] ?? null) ? $state0['checkpoint'] : null;
                if ($vendorCp === null && $currentCp !== null && (int)($currentCp['vendor_id'] ?? 0) === $vid0)
                    $vendorCp = $currentCp;
                $ov = $opts;
                $ov['all_vendors'] = false; $ov['vendor_id'] = $vid0;
                $ov['_shop_token'] = $tok0; $ov['_shop_name'] = (string)($sh['shop_name'] ?? '');
                $ov['_vendor_index'] = (int)$shopIndex;
                $ov['_parent_vendors'] = $vendorState;
                $ov['_parent_aggregate'] = $agg;
                catfixProgress(['log_add' => ['——— ' . ($sh['shop_name'] ?? ('غرفهٔ ' . $vid0)) . ' (#' . $vid0 . ') ———']]);
                $cn2 = $cn;
                $cn2['basalam'] = is_array($cn['basalam'] ?? null) ? $cn['basalam'] : [];
                $cn2['basalam']['token'] = $tok0; $cn2['basalam']['vendor_id'] = $vid0;
                $one = catfixRun($cn2, $mode, $ov, $vendorCp);
                $isDone = !empty($one['ok']) && empty($one['stopped']) && empty($one['partial']);
                if ($isDone) {
                    $addVendor($one, $sh);
                    $vendorState[(string)$vid0] = ['done' => true, 'checkpoint' => null,
                        'summary' => ['ok' => !empty($one['ok']), 'total' => (int)($one['total'] ?? 0),
                            'fixed' => (int)($one['fixed'] ?? 0), 'failed' => (int)($one['failed'] ?? 0),
                            'learned_hits' => (int)($one['learned_hits'] ?? 0)]];
                } else {
                    /* فرزند آخرین checkpoint خود را در فایل نوشته است؛ همان را
                       زیرِ شناسهٔ غرفه نگه می‌داریم تا resume دقیقاً همان‌جا باشد. */
                    $curCat = json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true);
                    $childCp = is_array($curCat['checkpoint'] ?? null) ? $curCat['checkpoint'] : null;
                    $vendorState[(string)$vid0] = ['done' => false, 'checkpoint' => $childCp,
                        'summary' => ['total' => (int)($one['total'] ?? 0), 'fixed' => (int)($one['fixed'] ?? 0),
                            'failed' => (int)($one['failed'] ?? 0)]];
                    $agg['partial'] = true;
                    $agg['stopped'] = !empty($one['stopped']);
                    break;
                }
                $parentCp = ['phase' => 'vendors', 'vendor_id' => 0, 'vendor_index' => $shopIndex + 1,
                    'vendors' => $vendorState, 'aggregate' => $agg, 'started_at' => (int)($cp['started_at'] ?? time())];
                catfixProgress(['checkpoint' => $parentCp]);
            }
            $agg['took'] = round(microtime(true) - $t0, 1);
            $agg['msg'] = 'اصلاح چندغرفه: ' . (int)$agg['fixed'] . ' از ' . (int)$agg['total']
                . ' · یادگیری ' . (int)$agg['learned_hits'];
            return $agg;
        }
    }
    if ($onlyVid > 0 && !empty($opts['_shop_token'])) {
        $tk = (string)$opts['_shop_token'];
        $vid = $onlyVid;
    } elseif ($onlyVid > 0 && function_exists('bslAllShops')) {
        foreach (bslAllShops($cn) as $sh) {
            if ((int)$sh['vendor_id'] === $onlyVid) {
                $tk = (string)$sh['token']; $vid = $onlyVid; break;
            }
        }
    }

    catfixProgress(['phase' => 'cats', 'log_add' => ['📂 دریافتِ درختِ دسته‌بندی‌های باسلام...']]);
    $cats = catfixFlatCats($tk);
    if (!$cats) return ['ok' => false, 'error' => 'دسته‌بندی‌ها بارگذاری نشد'];
    bslSetCatNameMap($cats);
    $leafCats = [];
    foreach ($cats as $c) if ((int)($c['level'] ?? 0) >= 2) $leafCats[] = $c;
    if (!$leafCats) $leafCats = $cats;
    catfixProgress(['log_add' => [count($cats) . ' دسته دریافت شد (' . count($leafCats) . ' دستهٔ برگ)']]);

    /* --- آماده‌سازیِ مدل‌ها فقط در حالت‌های هوش مصنوعی --- */
    $cands = []; $providers = []; $master = null; $mp = null; $masterKey = ''; $net = []; $candKeys = [];
    $quorum = 2;
    /* v10.71 (85): روشِ چهارم (زنجیرهٔ پشتیبان) هم مثلِ مستر به مدل‌ها نیاز دارد */
    if (in_array($mode, ['master', 'quorum', 'fallback'], true)) {
        $cands = aiCandidates();
        if (!$cands) return ['ok' => false, 'error' => 'هیچ مدل کاندیدی انتخاب نشده — اول در بخش 🤖 چند مدل کاندید اضافه کنید'];
        $providers = aiProvidersLoad();
        $masterKey = aiMasterKey();
        foreach ($cands as $c) if ($c['key'] === $masterKey) { $master = $c; break; }
        if ($master === null) $master = $cands[0];
        $mp = $providers[$master['provider']] ?? null;
        if ($mp === null) return ['ok' => false, 'error' => 'ارائه‌دهندهٔ مدل مستر یافت نشد'];
        $net = aiNetCfg();
        $candKeys = array_map(function ($c) { return $c['key']; }, $cands);
        $quorum = max(1, min(count($cands), (int)($opts['quorum'] ?? 2)));
        catfixProgress(['log_add' => ['🧠 مستر: ' . $master['providerName'] . ' / ' . $master['model']
            . ($mode === 'quorum'
               ? (' · اجماع با ' . aiFaNum(count($cands)) . ' مدل، حدنصابِ مرحلهٔ اول: ' . aiFaNum($quorum))
               : ($mode === 'fallback'
                  ? (' · زنجیرهٔ پشتیبان — اگر مستر نداد، ' . aiFaNum(max(0, count($cands) - 1)) . ' کاندید به‌ترتیب')
                  : ' · حالتِ تک‌مدلی'))]]);   // v10.71 (85)
        if ($mode === 'quorum' && count($cands) < 2) {
            $mode = 'master';
            catfixProgress(['log_add' => ['ℹ️ فقط یک کاندید هست — به حالتِ تک‌مدلی برگشت']]);
        }
        if ($mode === 'fallback' && count($cands) < 2) {
            catfixProgress(['log_add' => ['ℹ️ فقط یک کاندید هست — زنجیرهٔ پشتیبان عملاً حالتِ مستر است']]);   // v10.71 (85)
        }
    }

    /* --- فهرستِ محصولات --- */
    $onlyId = (int)($opts['product_id'] ?? 0);
    $partial = []; $fetchMeta = [];
    if ($onlyId > 0) {
        catfixProgress(['phase' => 'fetch', 'log_add' => ['🔎 دریافتِ محصول #' . $onlyId]]);
        $rg = bslReq($tk, 'GET', 'products/' . $onlyId);
        if (empty($rg['ok'])) $rg = bslReq($tk, 'GET', 'vendors/' . $vid . '/products/' . $onlyId);
        if (empty($rg['ok'])) return ['ok' => false, 'error' => 'محصول یافت نشد (HTTP ' . ($rg['code'] ?? '?') . ')'];
        $products = [(array)($rg['body'] ?? [])];
    } else {
        catfixProgress(['phase' => 'fetch', 'log_add' => ['🔎 دریافتِ محصولاتِ ردشده (وضعیت ۳۵۶۷)...']]);
        $products = catfixFetchRejected($tk, $vid, $partial, $fetchMeta);
    }
    if (!empty($partial['partial']) || (!empty($fetchMeta) && empty($fetchMeta['complete']))) {
        $fetchCp = ['phase' => 'fetch', 'vendor_id' => $vid, 'fetch_page' => (int)($fetchMeta['page'] ?? ($partial['page'] ?? 0)),
            'fetch_reason' => (string)($fetchMeta['reason'] ?? ($partial['reason'] ?? 'http')),
            'done_ids' => (array)($cp['done_ids'] ?? []), 'fixed' => (int)($cp['fixed'] ?? 0),
            'failed' => (int)($cp['failed'] ?? 0), 'no_ai' => (int)($cp['no_ai'] ?? 0),
            'no_cat' => (int)($cp['no_cat'] ?? 0), 'skip_same' => (int)($cp['skip_same'] ?? 0),
            'skip_tried' => (int)($cp['skip_tried'] ?? 0), 'asked' => (int)($cp['asked'] ?? 0),
            'cache_hits' => (int)($cp['cache_hits'] ?? 0), 'learned_hits' => (int)($cp['learned_hits'] ?? 0),
            'idx' => (int)($cp['idx'] ?? 0), 'items' => is_array($cp['items'] ?? null) ? $cp['items'] : [],
            'started_at' => (int)($cp['started_at'] ?? time()),
            'vendor_index' => (int)($opts['_vendor_index'] ?? 0),
            'vendors' => is_array($opts['_parent_vendors'] ?? null) ? $opts['_parent_vendors'] : [],
            'aggregate' => is_array($opts['_parent_aggregate'] ?? null) ? $opts['_parent_aggregate'] : null];
        catfixProgress(['running' => false, 'done' => true, 'stale' => true, 'partial' => true,
            'phase' => 'fetch', 'checkpoint' => $fetchCp,
            'log_add' => ['⏸ فهرستِ محصولات کامل نشد — هیچ PATCHای انجام نشد و checkpoint حفظ شد']]);
        return ['ok' => false, 'partial' => true, 'stopped' => !empty($fetchMeta['stopped']),
            'error' => !empty($fetchMeta['stopped']) ? 'اصلاح با درخواست کاربر متوقف شد' : 'فهرست محصولات کامل دریافت نشد',
            'mode' => $mode, 'total' => count($products), 'fixed' => (int)($cp['fixed'] ?? 0),
            'failed' => (int)($cp['failed'] ?? 0), 'items' => is_array($cp['items'] ?? null) ? $cp['items'] : []];
    }
    $total = count($products);
    if ($total === 0) {
        /* v10.126: در ادامهٔ چک‌پوینت، جمعِ قبلی حفظ می‌شود (نه صفر) */
        return ['ok' => true, 'mode' => $mode, 'total' => 0,
                'fixed' => (int)($cp['fixed'] ?? 0), 'failed' => (int)($cp['failed'] ?? 0),
                'no_ai' => (int)($cp['no_ai'] ?? 0), 'no_cat' => (int)($cp['no_cat'] ?? 0),
                'skip_same' => (int)($cp['skip_same'] ?? 0), 'skip_tried' => (int)($cp['skip_tried'] ?? 0),
                'asked' => (int)($cp['asked'] ?? 0), 'cache_hits' => (int)($cp['cache_hits'] ?? 0),
                'learned_hits' => (int)($cp['learned_hits'] ?? 0),
                'items' => is_array($cp['items'] ?? null) ? $cp['items'] : [],
                'partial' => !empty($partial['partial']),
                'took' => round(microtime(true) - $t0, 1), 'at' => time(),
                'msg' => 'هیچ محصولِ ردشده‌ای پیدا نشد'];
    }
    catfixProgress(['phase' => 'run', 'total' => $total, 'current' => 0,
        'log_add' => ['🚀 شروعِ اصلاح — ' . aiFaNum($total) . ' محصول · روش: ' . catfixModeLabel($mode)]]);

    /* v10.126: ادامهٔ واقعی — شمارنده‌ها و اقلامِ گزارش از چک‌پوینت می‌آیند */
    $fixed = (int)($cp['fixed'] ?? 0);
    $failed = (int)($cp['failed'] ?? 0);
    $noAi = (int)($cp['no_ai'] ?? 0);
    $noCat = (int)($cp['no_cat'] ?? 0);
    $skipSame = (int)($cp['skip_same'] ?? 0);
    $skipTried = (int)($cp['skip_tried'] ?? 0);
    $asked = (int)($cp['asked'] ?? 0);
    $cacheHits = (int)($cp['cache_hits'] ?? 0);
    $idx = (int)($cp['idx'] ?? 0);
    $items = is_array($cp['items'] ?? null) ? $cp['items'] : [];
    $learnedHits = (int)($cp['learned_hits'] ?? 0);
    $stopped = false;
    $fbRescued = 0;   // v10.71 (85): چند محصول با زنجیرهٔ پشتیبان نجات یافت
    $cpStartedAt = (is_array($cp) ? (int)($cp['started_at'] ?? 0) : 0);
    /* v10.36 (۴۹ه): نامِ پروفایلِ هر محصول به‌عنوان بافت به مدل داده می‌شود.
       یک بار ساخته می‌شود و در حلقه هزینه‌ای ندارد. */
    $profOf = catProfileResolver('bsl');
    $profHits = (int)($cp['prof_hits'] ?? 0);

    /* v10.126: شناسه‌هایِ ازقبل‌پردازش‌شده برای رد شدن در حلقه + ثبتِ چک‌پوینت */
    $cpDoneIds = [];
    if (is_array($cp)) {
        $cpDoneIds = array_values(array_filter(array_map('intval', (array)($cp['done_ids'] ?? [])), function ($x) { return $x > 0; }));
    }
    $cpDoneSet = $cpDoneIds ? array_fill_keys($cpDoneIds, true) : [];
    $cpSave = function () use (&$cpDoneIds, &$fixed, &$failed, &$noAi, &$noCat,
        &$skipSame, &$skipTried, &$asked, &$cacheHits, &$learnedHits, &$profHits,
        &$idx, &$items, $cpStartedAt) {
        catfixProgress(['checkpoint' => [
            'done_ids' => $cpDoneIds, 'fixed' => $fixed, 'failed' => $failed,
            'no_ai' => $noAi, 'no_cat' => $noCat, 'skip_same' => $skipSame,
            'skip_tried' => $skipTried, 'asked' => $asked, 'cache_hits' => $cacheHits,
            'learned_hits' => $learnedHits, 'prof_hits' => $profHits, 'idx' => $idx,
            'items' => $items, 'started_at' => ($cpStartedAt > 0 ? $cpStartedAt : time()),
            /* چندغرفه‌ای: والد و وضعیت غرفه‌های تمام‌شده را در همان checkpoint
               نگه دار تا اگر child وسط کار کشته شد، parent هم قابل‌بازیابی باشد. */
            'vendor_id' => (int)($opts['vendor_id'] ?? 0),
            'vendor_index' => (int)($opts['_vendor_index'] ?? 0),
            'vendors' => is_array($opts['_parent_vendors'] ?? null) ? $opts['_parent_vendors'] : [],
            'aggregate' => is_array($opts['_parent_aggregate'] ?? null) ? $opts['_parent_aggregate'] : null]]);
    };

    foreach ($products as $p) {
        $idx++;
        if (catfixStopRequested()) {
            $stopped = true;
            catfixProgress(['log_add' => ['⏹ توقف با درخواستِ کاربر — ' . aiFaNum($idx - 1) . ' محصول پردازش شده بود']]);
            break;
        }
        $pId   = (int)($p['id'] ?? 0);
        /* v10.126: محصولِ ازقبل‌پردازش‌شده رد می‌شود. شناسه فقط بعد از
           پایانِ امنِ این محصول به done_ids می‌رود؛ ثبتِ آن پیش از PATCH
           باعث می‌شد قطع‌شدنِ پردازه بین checkpoint و درخواست، محصول را
           برای همیشه جا بیندازد. */
        if ($pId > 0 && isset($cpDoneSet[$pId])) continue;
        $pName = trim((string)($p['title'] ?? ($p['name'] ?? '')));
        $rev   = $p['revision'] ?? [];
        $curCat = bslProductCatId($p);
        $push = function (string $status, string $msg, int $catId = 0, string $catName = '') use (&$items, $pId, $pName) {
            if (count($items) < 500)
                $items[] = ['id' => $pId, 'title' => $pName, 'status' => $status,
                            'cat_id' => $catId, 'cat_name' => $catName, 'msg' => $msg];
        };
        $cpMark = function () use (&$cpDoneIds, &$cpDoneSet, $pId, &$cpSave): void {
            if ($pId > 0 && !isset($cpDoneSet[$pId])) {
                $cpDoneIds[] = $pId;
                $cpDoneSet[$pId] = true;
            }
            $cpSave();
        };
        catfixProgress(['current' => $idx, 'last_title' => mb_substr($pName, 0, 50, 'UTF-8'),
            'fixed' => $fixed, 'failed' => $failed, 'no_ai' => $noAi, 'no_cat' => $noCat,
            'skip_same' => $skipSame, 'skip_tried' => $skipTried, 'asked' => $asked,
            'learned_hits' => $learnedHits]);

        if ($pName === '' && $mode !== 'ai_text') {
            $failed++; $push('failed', 'عنوانِ محصول خالی است');
            catfixProgress(['log_add' => ['❌ [' . $idx . '/' . $total . '] عنوانِ خالی — #' . $pId]]);
            $cpSave();
            continue;
        }

        $catId = 0; $catName = ''; $winKeys = [];

        /* v10.107: اول حافظهٔ یادگیری (با نظارت AI قبلی/دستی)، بعد مدل */
        if ($useLearn && $pName !== '' && function_exists('catLearnLookup')) {
            $lid = (int)catLearnLookup($pName);
            if ($lid > 0) {
                $lname = '';
                if (function_exists('bslCatName')) $lname = (string)bslCatName($lid);
                if ($lname === '' && !empty($cats)) {
                    foreach ($cats as $c) {
                        if ((int)($c['id'] ?? 0) === $lid) { $lname = (string)($c['title'] ?? $c['name'] ?? ''); break; }
                    }
                }
                $catId = $lid;
                $catName = $lname !== '' ? $lname : ('#' . $lid);
                $learnedHits++;
                // اگر learn_first و دسته پیدا شد، مستقیم برو برای apply (پایین حلقه)
                if ($learnFirst || $mode === 'learned') {
                    // fall through to same-cat / apply logic below by skipping AI fetch
                    goto CATFIX_AFTER_AI_PICK;
                }
            }
        }

        if ($mode === 'ai_text') {
            /* متنِ توصیهٔ خودِ باسلام + علتِ ردها */
            $aiText = trim((string)($rev['metadata']['description'] ?? ''));
            foreach ((array)($rev['rejection_reasons'] ?? []) as $rr) {
                $d = trim((string)($rr['description'] ?? ''));
                if ($d !== '' && mb_strlen($d, 'UTF-8') > 5) $aiText .= ($aiText ? ' ' : '') . $d;
            }
            if ($aiText === '') {
                $noAi++; $push('no_ai', 'متنِ بررسیِ باسلام برای این محصول وجود ندارد');
                catfixProgress(['log_add' => ['⚠️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — متنِ AI ندارد']]);
                $cpSave();
                continue;
            }
            $res = extractAiCategoryFromTextEx($aiText, $cats);
            $catId = (int)($res['catId'] ?? 0);
            if ($catId <= 0) {
                $noCat++; $push('no_cat', 'از متنِ بررسی هیچ دسته‌ای استخراج نشد');
                catfixProgress(['log_add' => ['⚠️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — دسته از متن درنیامد']]);
                $cpSave();
                continue;
            }
            $catId = findLeafCategory($catId, $cats);
            $catName = bslCatNameById($catId);
        } else {
            $exclude   = catTriedExclude($pId, $curCat);
            $triedInfo = [];
            $trRow = catTriedRow($pId);
            foreach ((array)($trRow['tried'] ?? []) as $tcid => $tinfo)
                $triedInfo[] = ['id' => (int)$tcid, 'name' => (string)($tinfo['name'] ?? '')];
            /* v10.36 (۴۹ه): نامِ پروفایلِ همین محصول — سرنخی که عنوانِ مبهم
               را معنادار می‌کند («ست ۳ تکه» در «لوازم آشپزخانه» ≠ در «پوشاک»). */
            $pProf = $profOf($pId, $pName);
            $pHint = aiCatProfileHint($pProf);
            if ($pProf !== '') $profHits++;
            if ($mode === 'quorum') {
                $con = aiCatConsensus($cands, $providers, $pName, $cats, $leafCats, $exclude, $net,
                    ['quorum' => $quorum, 'tried_info' => $triedInfo, 'profile_hint' => $pHint]);
                $asked += (int)($con['asked'] ?? 0);
                if (!empty($con['from_cache'])) $cacheHits++;
                $catId   = (int)($con['category_id'] ?? 0);
                $catName = (string)($con['category_name'] ?? '');
                $ok      = !empty($con['ok']);
                $err     = (string)($con['error'] ?? '');
                $winKeys = (array)($con['winner_keys'] ?? []);
                if ($ok) catfixProgress(['log_add' => ['🗳️ [' . $idx . '/' . $total . '] اجماع: ' . $catName
                    . ' (' . $catId . ') — ' . aiFaNum((int)($con['agreement'] ?? 0)) . ' رأی از '
                    . aiFaNum((int)($con['asked'] ?? 0)) . ' مدل' . (!empty($con['from_cache']) ? ' · از کش ⚡' : '')
                    . ($pProf !== '' ? ' · بافت: ' . $pProf : '')]]);   // v10.36 (۴۹ه)
            } elseif ($mode === 'fallback') {
                /* v10.71 (85): روشِ چهارم — زنجیرهٔ پشتیبان.
                   «جوابِ معتبر» یعنی مدل بی‌خطا جواب داده باشد و دستهٔ موجود
                   در درخت (category_id > 0) برگردانده باشد. اگر مستر خطا داد
                   یا دستهٔ معتبر نداد، کاندیدهایِ دیگر به‌ترتیب امتحان
                   می‌شوند تا اولین جوابِ معتبر. نگهبان‌هایِ همان‌دسته/امتحان‌شدهٔ
                   پایین مثلِ روش‌هایِ دیگر بر دستهٔ برگزیده حاکم می‌مانند. */
                $res = aiCandidateCategory($mp, $master['model'], $pName, $cats, $leafCats,
                    aiCatListBuild($leafCats, $exclude, 24000, $pName), $net, $exclude, $triedInfo, $pHint);
                $asked++;
                $catId   = (int)($res['category_id'] ?? 0);
                $catName = (string)($res['category_name'] ?? '');
                $ok      = !empty($res['ok']);
                $err     = (string)($res['error'] ?? '');
                $winKeys = [$masterKey];
                if (!$ok || $catId <= 0) {
                    $fbChain = '🛟 زنجیرهٔ پشتیبان — مستر: ' . ($err !== '' ? $err : 'دستهٔ معتبر نداد');
                    foreach ($cands as $fc) {
                        if (catfixStopRequested()) break;
                        if (($fc['key'] ?? '') === $masterKey) continue;
                        $fcp = $providers[$fc['provider']] ?? null;
                        if ($fcp === null) continue;
                        $fres = aiCandidateCategory($fcp, $fc['model'], $pName, $cats, $leafCats,
                            aiCatListBuild($leafCats, $exclude, 24000, $pName), $net, $exclude, $triedInfo, $pHint);
                        $asked++;
                        if (!empty($fres['ok']) && (int)($fres['category_id'] ?? 0) > 0) {
                            $catId   = (int)$fres['category_id'];
                            $catName = (string)($fres['category_name'] ?? '');
                            $ok      = true;
                            $err     = '';
                            $winKeys = [(string)$fc['key']];
                            $fbChain .= ' → ' . ($fc['providerName'] ?? $fc['provider']) . '/' . $fc['model'] . ' ✓';
                            $fbRescued++;
                            break;
                        }
                        $fbChain .= ' → ' . ($fc['providerName'] ?? $fc['provider']) . '/' . $fc['model'] . ' ✗';
                    }
                    catfixProgress(['log_add' => [$fbChain]]);
                }
            } else {
                $res = aiCandidateCategory($mp, $master['model'], $pName, $cats, $leafCats,
                    aiCatListBuild($leafCats, $exclude, 24000, $pName), $net, $exclude, $triedInfo, $pHint);
                $asked++;
                $catId   = (int)($res['category_id'] ?? 0);
                $catName = (string)($res['category_name'] ?? '');
                $ok      = !empty($res['ok']);
                $err     = (string)($res['error'] ?? '');
                $winKeys = [$masterKey];
            }
            if (!$ok || $catId <= 0) {
                $noCat++;
                /* v10.71 (85): پیامِ روشِ چهارم هم جدا */
                $m = ($mode === 'quorum' ? 'اجماع به دستهٔ تازه‌ای نرسید'
                    : ($mode === 'fallback' ? 'زنجیرهٔ پشتیبان به دستهٔ تازه‌ای نرسید' : 'مستر دستهٔ معتبری نداد'))
                     . ($err !== '' ? ' — ' . $err : '');
                $push('no_cat', $m);
                catfixProgress(['log_add' => ['⚠️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — ' . $m]]);
                $cpSave();
                continue;
            }
        }

        /* --- دو نگهبانِ همیشگی: همان دستهٔ فعلی، و دستهٔ قبلاً امتحان‌شده --- */
        CATFIX_AFTER_AI_PICK:

        if ($curCat > 0 && $catId === $curCat) {
            $skipSame++;
            catTriedRecord($pId, $catId, $catName, $mode, 'skipped', $pName, $curCat);
            $push('skipped', 'پیشنهاد همان دستهٔ فعلی است («' . $catName . '»)', $catId, $catName);
            catfixProgress(['log_add' => ['⏭️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — همان دستهٔ فعلی']]);
            $cpMark();
            continue;
        }
        if (catTriedHas($pId, $catId)) {
            $skipTried++;
            catTriedRecord($pId, $catId, $catName, $mode, 'skipped', $pName, $curCat);
            $push('skipped', '«' . $catName . '» قبلاً برای این محصول امتحان و رد شده', $catId, $catName);
            catfixProgress(['log_add' => ['⏭️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — «' . $catName . '» قبلاً امتحان شده']]);
            $cpMark();
            continue;
        }

        /* --- اعمال: دسته + ارسال به بررسیِ مجدد --- */
        $bu = ['category_id' => $catId, 'status' => 3568];
        $r2 = bslReq($tk, 'PATCH', 'products/' . $pId, $bu);
        if ((int)($r2['code'] ?? 0) === 404) $r2 = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $pId, $bu);
        if (!empty($r2['ok']) && !empty($r2['body']['id'])) {
            $fixed++;
            if ($mode !== 'ai_text') {
                foreach (array_unique($winKeys ?: [$masterKey]) as $wk) aiVoteRecord('category', $pName, $wk, $candKeys);
                catLearnRecord($pName, $catId, $catName);
            }
            catTriedRecord($pId, $catId, $catName, $mode, 'applied', $pName, $curCat);
            $push('fixed', 'اصلاح شد و به بررسیِ مجدد رفت', $catId, $catName);
            catfixProgress(['log_add' => ['✅ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8')
                . ' → ' . $catName . ' (' . $catId . ')']]);
        } else {
            $failed++;
            /* خطای PATCH گذراست؛ آن را در «دسته‌های امتحان‌شده» ثبت نکن
               و در done_ids هم نگذار تا اجرای بعدی واقعاً دوباره امتحان کند. */
            $err = (string)($r2['body']['message'] ?? ($r2['body']['error'] ?? ('HTTP ' . ($r2['code'] ?? '?'))));
            $push('failed', 'PATCH ناموفق: ' . $err, $catId, $catName);
            catfixProgress(['log_add' => ['❌ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8')
                . ' — ' . mb_substr($err, 0, 70, 'UTF-8')]]);
        }
        if (!empty($r2['ok']) && !empty($r2['body']['id'])) $cpMark();
        else $cpSave();
        usleep(500000);
    }

    $savedMsg = '';
    if ($mode === 'quorum' && $total > 0 && $cands) {
        $maxCalls = $total * count($cands);
        $saved = $maxCalls - $asked;
        if ($saved > 0) $savedMsg = ' | صرفه‌جویی: ' . aiFaNum($saved) . ' فراخوانی از ' . aiFaNum($maxCalls);
        if ($cacheHits > 0) $savedMsg .= ' | از کش: ' . aiFaNum($cacheHits);
    }
    // v10.36 (۴۹ه): سهمِ بافتِ پروفایل هم در خلاصه دیده شود
    if ($mode !== 'ai_text' && $profHits > 0)
        $savedMsg .= ' | با بافتِ پروفایل: ' . aiFaNum($profHits);
    $msg = '✅ اصلاح: ' . $fixed . ' | دسته نیافت: ' . $noCat
         . ($mode === 'ai_text' ? (' | بدون متنِ AI: ' . $noAi) : '')
         . ' | تکراری/همان دسته: ' . ($skipSame + $skipTried)
         . ' | ناموفق: ' . $failed . ' (از ' . $total . ')' . $savedMsg
         . (($mode === 'fallback' && $fbRescued > 0) ? (' | نجات‌یافته با زنجیره: ' . $fbRescued) : '');

    return ['ok' => true, 'mode' => $mode, 'total' => $total, 'processed' => $idx,
            'fixed' => $fixed, 'failed' => $failed, 'no_ai' => $noAi, 'no_cat' => $noCat,
            'skip_same' => $skipSame, 'skip_tried' => $skipTried,
            'skipped' => $skipSame + $skipTried, 'asked' => $asked, 'cache_hits' => $cacheHits, 'learned_hits' => $learnedHits,
            'stopped' => $stopped, 'partial' => !empty($partial['partial']),
            /* v10.36 (۴۹ه): چند محصول توانستند بافتِ پروفایل بگیرند — اگر
               این عدد صفر باشد یعنی نه دفترچه شناسه‌ای دارد نه پسوندی
               تعریف شده، و کاربر باید بداند چرا بافت اثری نداشته. */
            'profile_hints' => $profHits,
            'items' => $items, 'took' => round(microtime(true) - $t0, 1), 'at' => time(),
            'msg' => $msg];
}

/* =====================================================================
 *  v10.03 (۱۷): محیطِ آزمایشیِ «ایجنتِ مدیریت محصولات»
 *
 *  ایده: به‌جای اینکه برای هر کار یک دکمه و یک تابعِ جدا بنویسیم، به مدل
 *  یک جعبه‌ابزار می‌دهیم و می‌گذاریم خودش تصمیم بگیرد کدام ابزار را با چه
 *  ورودی صدا بزند. این همان «فراخوانیِ ابزار» (tool calling) است که
 *  مدل‌های Mistral / Gemini / Groq / GPT-OSS و... پشتیبانی می‌کنند.
 *
 *  چرخهٔ کار:
 *    ۱) پیامِ کاربر + فهرستِ ابزارها (JSON Schema) به مدل فرستاده می‌شود.
 *    ۲) مدل به‌جای متن، یک یا چند tool_call برمی‌گرداند.
 *    ۳) ما ابزار را واقعاً اجرا می‌کنیم و نتیجه را با نقشِ "tool" و
 *       همان tool_call_id به مدل پس می‌دهیم.
 *    ۴) تکرار تا وقتی مدل «تمام شد» بگوید یا به سقفِ گام‌ها برسیم.
 *
 *  سه حالتِ اجرا (مهم‌ترین بخشِ «آزمایشی بودن»):
 *    sim  — هیچ تماسِ شبکه‌ای؛ دادهٔ نمونهٔ داخلی. برای دیدنِ رفتارِ مدل.
 *    dry  — دادهٔ واقعی خوانده می‌شود، ولی هیچ نوشتنی انجام نمی‌شود.
 *    live — واقعی؛ قیمت و موجودی واقعاً در باسلام/ووکامرس نوشته می‌شود.
 *
 *  پیش‌فرض همیشه dry است تا یک اشتباهِ مدل به فروشگاه آسیب نزند.
 * ===================================================================== */

/** پیشرفتِ زندهٔ ایجنت (همان الگوی dedupProgress) */
function agentProgress(array $patch): void {
    $cur = localTaskStateRead(AGENT_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 500) $log = array_slice($log, -500);
        unset($patch['log_add']);
    }
    $steps = is_array($cur['steps'] ?? null) ? $cur['steps'] : [];
    if (isset($patch['step_add'])) {
        foreach ((array)$patch['step_add'] as $s) $steps[] = $s;
        if (count($steps) > 300) $steps = array_slice($steps, -300);
        unset($patch['step_add']);
    }
    /* v10.26 (۳۹ب): جریانِ «گفتگو». تا اینجا فقط یک لاگِ خلاصه داشتیم
       («گامِ ۳ — پرسش از مدل…») که نمی‌گفت مدل واقعاً چه گفت و ابزار چه
       برگرداند. حالا خودِ پیام‌ها هم ذخیره می‌شوند تا کاربر بتواند زنده
       ببیند چه در جریان است — به‌ویژه در اجراهای چنددقیقه‌ای. */
    $convo = is_array($cur['convo'] ?? null) ? $cur['convo'] : [];
    if (isset($patch['convo_add'])) {
        foreach ((array)$patch['convo_add'] as $c) {
            if (!is_array($c)) continue;
            $c['t'] = time();
            $convo[] = $c;
        }
        if (count($convo) > 240) $convo = array_slice($convo, -240);
        unset($patch['convo_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['steps'] = $steps; $cur['convo'] = $convo; $cur['ts'] = time();
    writeProgress(AGENT_PROGRESS_FILE, $cur);
}

/* =====================================================================
 *  v10.26 (۳۹ب): ابزارهای مشترکِ «گفتگوی زنده»
 *  ---------------------------------------------------------------------
 *  هر دو ایجنت (مدیریتِ محصولات و کشفِ سلکتور) و کارهای اتوماسیون از
 *  همین دو تابع استفاده می‌کنند تا شکلِ پیام‌ها یکی باشد و فرانت فقط یک
 *  رندرکننده لازم داشته باشد.
 *
 *  ساختارِ هر پیام:
 *    ['role' => system|user|assistant|tool, 'text' => '…',
 *     'calls' => [ ['name'=>..,'args'=>'json'], … ],   (فقط assistant)
 *     'name'  => 'نامِ ابزار', 'ok' => true|false]     (فقط tool)
 * ===================================================================== */

/** متنِ بلند را برای ذخیره در فایلِ پیشرفت کوتاه می‌کند.
 *  بدونِ این، یک پاسخِ ۴۰ کیلوبایتی مدل فایلِ JSON را باد می‌کند و هر
 *  نظرسنجیِ ۱٫۲ ثانیه‌ای همان حجم را روی شبکه می‌فرستد. */
function agentConvoTrim(string $s, int $max = 1400): string {
    $s = trim($s);
    if ($s === '') return '';
    if (mb_strlen($s) <= $max) return $s;
    return mb_substr($s, 0, $max) . ' … [' . aiFaNum(mb_strlen($s) - $max) . ' نویسهٔ دیگر بریده شد]';
}

/** پیامِ assistant را از متن و فهرستِ tool_call ها می‌سازد. */
function agentConvoAssistant(string $text, array $tcs): array {
    $calls = [];
    foreach ($tcs as $c) {
        $calls[] = ['name' => (string)($c['name'] ?? '?'),
                    'args' => agentConvoTrim(json_encode($c['args'] ?? [], JSON_UNESCAPED_UNICODE) ?: '{}', 600)];
    }
    return ['role' => 'assistant', 'text' => agentConvoTrim($text), 'calls' => $calls];
}

/** پیامِ نتیجهٔ یک ابزار. */
function agentConvoTool(string $name, array $res): array {
    return ['role' => 'tool', 'name' => $name, 'ok' => !empty($res['ok']),
            'text' => agentConvoTrim(json_encode($res, JSON_UNESCAPED_UNICODE) ?: '', 800)];
}
function agentStopRequested(): bool { return is_file(AGENT_STOP_FILE); }
function agentClearStop(): void { @unlink(AGENT_STOP_FILE); }

/** برچسبِ فارسیِ حالتِ اجرا */
function agentModeLabel(string $m): string {
    if ($m === 'live') return 'اجرای واقعی';
    if ($m === 'sim')  return 'شبیه‌سازیِ کامل';
    return 'آزمایشی (بدون نوشتن)';
}

/* ---------------------------------------------------------------------
 *  استخراجِ tool_call از پاسخِ مدل
 * ------------------------------------------------------------------- */

/**
 * tool_call ها را از پاسخِ سازگارِ OpenAI بیرون می‌کشد.
 * خروجی: [ ['id'=>..,'name'=>..,'args'=>[..]] , ... ]
 */
function aiExtractToolCalls($body): array {
    if (!is_array($body)) return [];
    $out = [];
    $raw = [];
    // OpenAI / Mistral / Groq / Together / OpenRouter
    foreach (($body['choices'] ?? []) as $ch) {
        if (!is_array($ch)) continue;
        $tc = $ch['message']['tool_calls'] ?? ($ch['delta']['tool_calls'] ?? null);
        if (is_array($tc)) foreach ($tc as $t) $raw[] = $t;
        // فرمتِ قدیمیِ function_call (تک‌تایی)
        $fc = $ch['message']['function_call'] ?? null;
        if (is_array($fc) && ($fc['name'] ?? '') !== '') {
            $raw[] = ['id' => 'call_legacy_' . count($raw), 'function' => $fc];
        }
    }
    // پاسخ‌های Responses-style: output[] با type=function_call
    foreach (($body['output'] ?? []) as $it) {
        if (!is_array($it)) continue;
        if (($it['type'] ?? '') === 'function_call' || isset($it['arguments'])) {
            $raw[] = ['id' => (string)($it['call_id'] ?? ($it['id'] ?? '')),
                      'function' => ['name' => (string)($it['name'] ?? ''),
                                     'arguments' => $it['arguments'] ?? '{}']];
        }
    }
    foreach ($raw as $i => $t) {
        if (!is_array($t)) continue;
        $fn = $t['function'] ?? $t;
        $name = trim((string)($fn['name'] ?? ''));
        if ($name === '') continue;
        $a = $fn['arguments'] ?? ($t['input'] ?? []);
        if (is_string($a)) {
            $dec = json_decode($a, true);
            $a = is_array($dec) ? $dec : [];
        }
        if (!is_array($a)) $a = [];
        $id = trim((string)($t['id'] ?? ''));
        if ($id === '') $id = 'call_' . $i . '_' . substr(md5($name . $i), 0, 8);
        $out[] = ['id' => $id, 'name' => $name, 'args' => $a];
    }
    return $out;
}

/**
 * پشتیبانِ متنی: مدل‌هایی که tool calling بومی ندارند معمولاً بلوکِ JSON
 * برمی‌گردانند. اگر متن دقیقاً شکلِ {"tool":"...","args":{...}} داشت،
 * همان را به‌عنوان فراخوانیِ ابزار می‌پذیریم تا این محیط با مدل‌های
 * بیشتری کار کند.
 */
function agentParseTextCall(string $text): array {
    $t = trim($text);
    if ($t === '') return [];
    if (preg_match('~```(?:json)?\s*(.+?)\s*```~s', $t, $m)) $t = trim($m[1]);
    $s = strpos($t, '{');
    $e = strrpos($t, '}');
    if ($s === false || $e === false || $e <= $s) return [];
    $d = json_decode(substr($t, $s, $e - $s + 1), true);
    if (!is_array($d)) return [];
    $name = trim((string)($d['tool'] ?? ($d['name'] ?? ($d['function'] ?? ''))));
    if ($name === '') return [];
    $args = $d['args'] ?? ($d['arguments'] ?? ($d['parameters'] ?? []));
    if (is_string($args)) { $dd = json_decode($args, true); $args = is_array($dd) ? $dd : []; }
    if (!is_array($args)) $args = [];
    return [['id' => 'call_text_' . substr(md5($name . $t), 0, 8), 'name' => $name, 'args' => $args]];
}

/** پیامِ خامِ assistant (با tool_calls) را از پاسخ بیرون می‌کشد */
function aiAssistantMessage($body): ?array {
    if (!is_array($body)) return null;
    foreach (($body['choices'] ?? []) as $ch) {
        if (is_array($ch) && is_array($ch['message'] ?? null)) return $ch['message'];
    }
    return null;
}

