$cn=loadConnections();$sync=$cn['sync']??[];$w=$cn['woocommerce']??[];$bs=$cn['basalam']??[];
$target=$sync['target']??'woo';
send_sse('sync_info',['msg'=>'شروع سینک خودکار...','phase'=>'start']);

