send_sse('sync_info',['msg'=>'در انتظار داده از کلاینت...','phase'=>'waiting']);
send_sse('done',[]);exit;
}
// v10.95: بارگذاری به عنوان ماژول بدون رندر HTML توسط افزونه یا سایر اسکریپت‌ها
if (defined('SCRAPER4_NO_RENDER') && SCRAPER4_NO_RENDER) {
