// ========== Import State ==========
let importProducts = [];
let importFile = '';
let importHeaders = [];
let importMapping = {};

// ========== Woo/Bsl Retry State ==========

let profiles =<?=json_encode($initialProfiles, JSON_UNESCAPED_UNICODE)?>;
let currentProfileKey = null;
let isDirty = false;
let saveTimer = null;
let urlChangeTimer = null;
let testTimers = {};

const toFa=n=>String(n).replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]);
const toEn=s=>(s||'').replace(/[۰-۹]/g,d=>'0123456789'['۰۱۲۳۴۵۶۷۸۹'.indexOf(d)]).replace(/[٠-٩]/g,d=>'0123456789'['٠١٢٣٤٥٦٧٨٩'.indexOf(d)]);

function showToast(msg, isError=false) {
    const t = $('toast');
    t.textContent = msg;
    t.className = 'toast show' + (isError ? ' error' : '');
    setTimeout(() => t.className = 'toast' + (isError ? ' error' : ''), 2500);
}

function markDirty() {
    isDirty = true;
    const s = $('profileStatus');
    s.textContent = 'تغییرات';
    s.className = 'profile-indicator unsaved';
}

function markClean(key) {
    isDirty = false;
    currentProfileKey = key;
    const s = $('profileStatus');
    s.textContent = 'ذخیره';
    s.className = 'profile-indicator saved';
}

function scheduleSave() {
    if (!$('url').value.trim()) return;
    markDirty();
    clearTimeout(saveTimer);
    saveTimer = setTimeout(saveProfileSilent, 2000);
    // v7.66: Update auto-extract button based on selector state
    if(sel.container && sel.title){
        $('startBtn').textContent='▶ استخراج اتوماتیک ✓ ('+sel.container+')';
        $('startBtn').style.background='#22c55e';
        $('startBtn').style.color='#fff';
    }else{
        $('startBtn').textContent='▶ استخراج اتوماتیک';
        $('startBtn').style.background='';
        $('startBtn').style.color='';
    }
}

/* =====================================================================
 *  v9.91: آخرین تبِ باز بعد از رفرش برمی‌گردد
 *
 *  تا اینجا با هر رفرش، تب «شروع» باز می‌شد (یا اگر پروفایلی بازیابی
 *  می‌شد، تب «نتایج»). آدرسِ هش (#results) نوشته می‌شد ولی دو چیز آن را
 *  بی‌اثر می‌کرد: ۱) اگر کاربر هیچ تبی را دستی کلیک نکرده بود هشی وجود
 *  نداشت، ۲) بازیابیِ خودکارِ آخرین پروفایل بعد از آن اجرا می‌شد و
 *  زورکی به «نتایج» می‌پرید. حالا نامِ تب در همین مرورگر ذخیره می‌شود و
 *  بازیابیِ پروفایل دیگر تب را عوض نمی‌کند. */
const MAIN_TABS = ['start','settings','selectors','results','send','import'];
const LAST_TAB_KEY = 'scraper_last_main_tab';
function rememberMainTab(name){
    try { if (MAIN_TABS.includes(name)) localStorage.setItem(LAST_TAB_KEY, name); } catch(e) {}
}
function lastMainTab(){
    try { const v = localStorage.getItem(LAST_TAB_KEY) || ''; return MAIN_TABS.includes(v) ? v : ''; }
    catch(e) { return ''; }
}

function switchMainTab(name) {
    document.querySelectorAll('.main-tab').forEach(t => t.classList.toggle('active', t.dataset.tab === name));
    // v9.65: اگر پنلِ درخواست‌شده وجود نداشته باشد (مثلاً نامِ اشتباه)، هیچ پنلی را
    // خالی نکن. قبلاً switchMainTab('profiles') همهٔ پنل‌ها را deactivate می‌کرد
    // چون پنلی به نام pane-profiles وجود ندارد → کل محتوای تب‌ها خالی دیده می‌شد.
    const target=document.getElementById('pane-'+name);
    if(target){
        document.querySelectorAll('.tab-pane').forEach(p => p.classList.toggle('active', p === target));
    }
    // v8.88: روی موبایل صفحه را به بالا نپران
    softScrollTo({top:0,behavior:'smooth'});
    try { history.replaceState(null, '', '#' + name); } catch(e) {}
    rememberMainTab(name);   // v9.91: تا رفرشِ بعدی همین‌جا باز شود
    /* v10.31 (۴۴): نتایج تا لحظهٔ دیده‌شدن ساخته نمی‌شوند. ورود به تب
       همان لحظه است — پس اگر نمای جاری کهنه است، همین‌جا ساختش. */
    if (name === 'results' && typeof rvEnsure === 'function') rvEnsure(rvCurView);
}
// v8.17: Settings panel toggle
function toggleSettingsPanel(){
  const p=document.getElementById('settingsPanel');
  const o=document.getElementById('settingsOverlay');
  const b=document.getElementById('hamburgerBtn');
  const fb=document.getElementById('fullBtn');
  if(!p)return;
  if(p.classList.contains('open')){
    p.classList.remove('open');
    if(o)o.classList.remove('open');
    if(b)b.classList.remove('active');
    document.body.classList.remove('spanel-open');
  }else{
    p.classList.add('open');
    if(o)o.classList.add('open');
    if(b)b.classList.add('active');
    document.body.classList.add('spanel-open');
    try{
      if(localStorage.getItem('amphp_spanel_full')==='1'){
        p.classList.add('full');
        if(fb)fb.classList.add('active');
      }
    }catch(e){}
    syncSmenuStickyOffsets();
  }
  document.body.classList.toggle('spanel-full', p.classList.contains('full') && p.classList.contains('open'));
}
/* v9.94 (۸ب): ارتفاعِ واقعیِ سربرگِ پنل و یک سربخشِ نمونه را اندازه می‌گیریم و
   داخل متغیرهای CSS می‌گذاریم. با این کار سربخش‌های چسبان دقیقاً زیرِ سربرگ
   می‌نشینند، حتی اگر فونتِ انتخابیِ کاربر ارتفاع‌ها را عوض کرده باشد. */
function syncSmenuStickyOffsets(){
  const p=document.getElementById('settingsPanel');if(!p)return;
  const head=p.querySelector('.settings-panel-head');
  const hdr=p.querySelector('.smenu-hdr');
  const hh=head?Math.round(head.getBoundingClientRect().height):0;
  const sh=hdr?Math.round(hdr.getBoundingClientRect().height):0;
  if(hh>0)p.style.setProperty('--spanel-head-h',hh+'px');
  if(sh>0)p.style.setProperty('--smenu-hdr-h',sh+'px');
}
// v9.61: تمام‌عرض کردن پنل تنظیمات (منو و محتویاتش). اگر منو بسته باشد اول باز
// می‌شود؛ کلاس .full روی پنل عرض را به 100vw و سقف‌های .smenu-body را بی‌سقف می‌کند
// تا هیچ بخشی گیر و بریده نماند.
function toggleFullSettings(){
  const p=document.getElementById('settingsPanel');
  const b=document.getElementById('fullBtn');
  if(!p)return;
  if(!p.classList.contains('open')){
    toggleSettingsPanel();
  }
  const full=p.classList.toggle('full');
  if(b)b.classList.toggle('active', full);
  document.body.classList.toggle('spanel-full', full && p.classList.contains('open'));
  try{ localStorage.setItem('amphp_spanel_full', full ? '1' : '0'); }catch(e){}
  syncSmenuStickyOffsets();
}
(function(){
  try{
    if(localStorage.getItem('amphp_spanel_full')==='1'){
      const p=document.getElementById('settingsPanel');
      const b=document.getElementById('fullBtn');
      if(p)p.classList.add('full');
      if(b)b.classList.add('active');
    }
  }catch(e){}
  /* Escape می‌بندد؛ overlay از قبل onclick="toggleSettingsPanel()" دارد */
  document.addEventListener('keydown', function(ev){
    if(ev.key!=='Escape')return;
    const p=document.getElementById('settingsPanel');
    if(p && p.classList.contains('open')) toggleSettingsPanel();
  });
})();
/* v9.94 (۸ب): بعد از پایانِ ترنزیشنِ باز شدن، کلاس smenu-done می‌گیرد تا سقفِ
   max-height برداشته و overflow باز شود؛ موقعِ بستن اول برمی‌گردد به حالتِ
   سقف‌دار وگرنه انیمیشنِ بسته‌شدن اصلاً دیده نمی‌شود. */
function toggleSmenu(hdr){
  const isOpen=hdr.classList.contains('open');
  hdr.classList.toggle('open');
  const body=hdr.nextElementSibling;
  if(body){
    if(isOpen){
      body.classList.remove('smenu-done');
      void body.offsetHeight;          /* فورس رفلو تا ترنزیشن از ارتفاع واقعی شروع شود */
      body.classList.remove('open');
    }else{
      body.classList.add('open');
      clearTimeout(body.__smenuT);
      body.__smenuT=setTimeout(function(){if(body.classList.contains('open'))body.classList.add('smenu-done');},320);
    }
  }
  syncSmenuStickyOffsets();
}
// v8.17: Per-profile fallback categories
