      if(box&&d.detail){
        let h='<div style="font-weight:700;color:#94a3b8;margin-bottom:3px">📡 نتیجهٔ ارسال (هر اشتراک، با مسیری که جواب داد):</div>';
        Object.keys(d.detail).forEach(function(ep){
