      if(!dg.support){
        alert('مرورگرِ شما اعلانِ سیستمی (Web Notification) را پشتیبانی نمی‌کند.'+
              (!dg.secure?'\n\nهمچنین صفحه باید از طریقِ HTTPS باز شود.':'')+
              '\n\nنکته: برای این کار فایلِ sw.js لازم نیست — خودِ صفحه اعلان را می‌سازد.\nبا کروم/فایرفاکسِ دسکتاپ روی HTTPS امتحان کنید.');
        return;
      }
      let p=dg.perm;
      if(p==='default'){try{p=await Notification.requestPermission();}catch(e){}}
      mrSysDiagRender();
      if(p!=='granted'){
        alert('دسترسیِ اعلان داده نشد (وضعیت: '+p+').'+
              (p==='denied'?'\nروی آیکونِ قفلِ کنارِ آدرس بزنید ← Site settings/Permissions ← Notifications = Allow، بعد صفحه را تازه کنید.'
                           :'\nدر پنجرهٔ کوچکِ ظاهرشده Allow را بزنید، بعد دوباره تست کنید.')+
              '\n\nنکته: برای این کار فایلِ sw.js لازم نیست.');
        return;
      }
      mrLiveSysNotif('🔔 تستِ اعلانِ سیستم','اگر این پیام را در گوشهٔ صفحه (اعلان‌هایِ سیستم) دیدید، همه‌چیز درست است — از این‌به‌بعد همهٔ رویدادها اینجا هم می‌آیند.');
      try{
        const el=$('lnSysDiag');
        if(el)el.innerHTML='✅ اعلان از مسیرِ '+(mrSwState==='ok'?'<b>سرویس‌ورکر</b>':'معمولیِ صفحه')+' فرستاده شد. اگر در سیستم نمایش داده نشد: تنظیماتِ <b>سیستم‌عامل</b> را بررسی کنید — ویندوز (Settings ← System ← Notifications و Focus Assist خاموش)، macOS (System Settings ← Notifications)، اندروید (Settings ← Apps ← Chrome ← Notifications). در اندروید یک لایهٔ دیگر هم هست: در خودِ کروم، Settings ← Site settings ← Notifications برای همین سایت باید <b>Allow</b> باشد.';
      }catch(e){}
    }catch(e){alert('تست نشد: '+e);}
  })();
}
/* v10.66 (۸۰): تنظیماتِ بخشِ «اعلان‌ها» — بارگذاری و سیم‌کشیِ آنی */
function mrLiveSettingsLoad(){
  try{
    const g=id=>$(id);
    if(g('lnCards'))g('lnCards').checked=localStorage.getItem('mr_live_cards')!=='0';
    if(g('lnSys'))g('lnSys').checked=mrLiveCfg().sys;
    if(g('lnPoll'))g('lnPoll').value=String(mrLiveCfg().poll);
    if(g('lnTtl'))g('lnTtl').value=String(mrLiveCfg().ttl);
    if(g('lnSound'))g('lnSound').checked=localStorage.getItem('mr_live_sound')!=='0';
    const elC=g('lnCards'); if(elC)elC.addEventListener('change',()=>{try{localStorage.setItem('mr_live_cards',elC.checked?'1':'0');}catch(e){}});
    const elS=g('lnSys');
    if(elS)elS.addEventListener('change',async()=>{
      try{
        if(elS.checked){
          if(typeof Notification!=='undefined'&&Notification.permission==='default'){try{await Notification.requestPermission();}catch(e){}}
          if(typeof Notification==='undefined'||Notification.permission!=='granted'){elS.checked=false;showToast('دسترسیِ اعلان داده نشد',1);return;}
          localStorage.setItem('mr_sys_notif','1');
          mrLiveSysNotif('🔔 اعلانِ سیستم روشن شد','از این‌به‌بعد همهٔ رویدادها در اعلان‌هایِ سیستمی هم می‌آیند.');
          mrSysDiagRender();
        } else {localStorage.setItem('mr_sys_notif','0');mrSysDiagRender();}
      }catch(e){}
    });
    const elP=g('lnPoll'); if(elP)elP.addEventListener('change',()=>{try{localStorage.setItem('mr_live_poll',String(Math.max(3,parseInt(elP.value,10)||5)));}catch(e){}});
    const elT=g('lnTtl'); if(elT)elT.addEventListener('change',()=>{try{localStorage.setItem('mr_live_ttl',String(Math.max(5,parseInt(elT.value,10)||30)));}catch(e){}});
    const elSd=g('lnSound'); if(elSd)elSd.addEventListener('change',()=>{try{localStorage.setItem('mr_live_sound',elSd.checked?'1':'0');}catch(e){}});
    /* v10.72 (86): سیم‌کشیِ کلیدِ اعلانِ Push */
    const elPs=g('lnPush');
    if(elPs){
      elPs.checked=localStorage.getItem('mr_push_on')==='1';
      elPs.addEventListener('change',async()=>{
        try{
          if(elPs.checked){
            if(typeof Notification==='undefined'){elPs.checked=false;mrPushStatusRender('none');showToast('این مرورگر اعلانِ Push را پشتیبانی نمی‌کند (فقط HTTPS)',1);return;}
            if(Notification.permission!=='granted'){try{await Notification.requestPermission();}catch(e){}}
            if(Notification.permission!=='granted'){elPs.checked=false;mrPushStatusRender('deny');showToast('دسترسیِ اعلان را بدهید',1);return;}
            localStorage.setItem('mr_push_on','1');
            const sub=await mrPushSub();
            if(sub){mrPushStatusRender('on');mrLiveTestPush();}
            else{elPs.checked=false;localStorage.setItem('mr_push_on','0');mrPushStatusRender('err',mrPushLastErr||'ثبتِ اشتراک ممکن نشد — «🔁 ثبتِ دوبارهٔ اشتراک» را بزنید');}
          }else{
            localStorage.setItem('mr_push_on','0');
            await mrPushUnsub();
            mrPushStatusRender('off');
            showToast('📡 اعلانِ Push خاموش شد',0);
          }
        }catch(e){}
      });
    }
    mrSysDiagRender();   // v10.68 (82): خطِ تشخیص همان لحظهٔ بارگذاری هم دیده شود
  }catch(e){}
}
/* v10.60 (۷۴): ضربان — فاصله از تنظیماتِ «اعلان‌ها» خوانده می‌شود (v10.66) */
setTimeout(mrNotifPoll,2500);
mrLiveSettingsLoad();
mrPushRouteLoad();   // v10.74 (88): مسیرهایِ جایگزینِ Push بارگذاری شوند
mrSwReady();   // v10.69 (83): سرویس‌ورکر همان لحظهٔ بارگذاری صفحه ثبت می‌شود
setTimeout(()=>{ try{ if(localStorage.getItem('mr_push_on')==='1') mrPushEnsure(); }catch(e){} }, 4000);   // v10.72 (86)
(function mrNotifLoop(){
  try{ setTimeout(mrNotifPoll, Math.max(3000, mrLiveCfg().poll*1000)); }
  catch(e){ setTimeout(mrNotifPoll, 5000); }
  try{ mrLiveEventPoll(); }catch(e){}
})();

function arRenderRules(){
  const box=$('arRules'); if(!box)return;
  if(!arRules.length){box.innerHTML='<div style="color:#64748b;font-size:11px;padding:8px;text-align:center">قاعده‌ای نیست — «قاعدهٔ جدید» را بزنید</div>';arBadge();return;}
  const sorted=arRules.map((r,i)=>({r,i})).sort((a,b)=>(a.r.priority||50)-(b.r.priority||50));
  let h='';
  sorted.forEach(({r,i})=>{
    const isAlways=r.match==='always';
    h+='<div style="background:#0f172a;border:1px solid '+(r.on?'#22c55e55':'#334155')+';border-radius:8px;padding:8px;margin-bottom:7px">';
    h+='<div style="display:flex;gap:6px;align-items:center;margin-bottom:5px">';
    h+='<label class="switch" style="flex:0 0 auto"><input type="checkbox" '+(r.on?'checked':'')
      +' onchange="arSetRule('+i+',\'on\',this.checked)"><span class="slider"></span></label>';
    h+='<select onchange="arSetRule('+i+',\'match\',this.value)" style="flex:1;font-size:10.5px;padding:3px">';
    for(const k in AR_MATCH)h+='<option value="'+k+'"'+(r.match===k?' selected':'')+'>'+AR_MATCH[k]+'</option>';
    h+='</select>';
    h+='<input type="number" value="'+(r.priority||50)+'" min="1" max="999" title="اولویت — کمتر یعنی زودتر بررسی می‌شود" '
      +'onchange="arSetRule('+i+',\'priority\',this.value)" style="flex:0 0 52px;font-size:10.5px;padding:3px">';
    h+='<button class="btn btn-red" onclick="arDelRule('+i+')" style="flex:0 0 auto;font-size:10px;padding:3px 7px">🗑</button>';
    h+='</div>';
    if(!isAlways){
      h+='<textarea rows="2" placeholder="محرک‌ها — هر کدام در یک خط" oninput="arSetRule('+i+',\'triggers\',this.value)" '
        +'style="width:100%;background:#111c31;border:1px solid #475569;color:#e2e8f0;padding:5px;border-radius:6px;font-size:11px;direction:rtl;margin-bottom:4px">'
        +esc(r.triggers||'')+'</textarea>';
    }else{
      h+='<div style="font-size:10px;color:#fbbf24;margin-bottom:4px">این قاعده وقتی هیچ قاعدهٔ دیگری نخورد اجرا می‌شود — اولویتش را بالا (عدد بزرگ) بگذارید.</div>';
    }
    h+='<textarea rows="2" placeholder="پاسخ خودکار" oninput="arSetRule('+i+',\'reply\',this.value)" '
      +'style="width:100%;background:#111c31;border:1px solid #a855f7;color:#e9d5ff;padding:5px;border-radius:6px;font-size:11px;direction:rtl">'
      +esc(r.reply||'')+'</textarea>';
    h+='<div style="display:flex;gap:6px;align-items:center;margin-top:4px;font-size:10px;color:#64748b">'
      +'<span>سقف روزانه:</span><input type="number" value="'+(r.daily_max!==undefined?r.daily_max:50)+'" min="0" max="1000" '
      +'onchange="arSetRule('+i+',\'daily_max\',this.value)" style="width:64px;font-size:10px;padding:2px">'
      +'<span style="color:#475569">۰ = بی‌نهایت</span></div>';
    h+='</div>';
  });
  box.innerHTML=h;
  arBadge();
}

function arSetRule(i,field,val){
  if(!arRules[i])return;
  if(field==='priority'||field==='daily_max')val=parseInt(val)||0;
  arRules[i][field]=val;
  if(field==='on'||field==='match')arRenderRules();
  else arBadge();
}

function arAddRule(){
  arRules.push({id:'r'+Date.now().toString(36),on:true,match:'contains',
                triggers:'',reply:'',priority:50,daily_max:50});
  arRenderRules();
}

function arDelRule(i){
  if(!arRules[i])return;
  if(!confirm('این قاعده حذف شود؟'))return;
  arRules.splice(i,1);
  arRenderRules();
}

function arResetRules(){
  if(!confirm('همهٔ قواعد به حالت پیش‌فرض برگردند؟ (تغییرات ذخیره‌نشده از بین می‌رود)'))return;
  fetch('?ar_rules=1&defaults=1').then(r=>r.json()).then(d=>{
    if(!d.ok){showToast('خطا',true);return;}
    arRules=d.rules||[];
    arRenderRules();
    showToast('✓ پیش‌فرض‌ها بارگذاری شد — برای ثبت، «ذخیرهٔ قواعد» را بزنید');
  }).catch(()=>showToast('خطا در ارتباط',true));
}

function arSaveRules(){
  const bad=arRules.filter(r=>r.on&&!(r.reply||'').trim());
  if(bad.length){showToast('قاعدهٔ فعال بدون پاسخ وجود دارد',true);return;}
  const fd=new FormData();
  fd.append('action','ar_save_rules');
  fd.append('rules',JSON.stringify(arRules));
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    showToast(d.ok?('✓ '+toFa(d.count)+' قاعده ذخیره شد'):('خطا: '+(d.error||'')),!d.ok);
    if(d.ok)arSaveCfg();
  }).catch(()=>showToast('خطا در ارتباط',true));
}

function arTest(){
  const t=($('arTestText')||{}).value||'';
  const box=$('arR');
  if(!t.trim()){showToast('یک متن بنویسید',true);return;}
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ بررسی طبق ترتیبِ انتخابی...</div>';
  fetch('?ar_test=1&text='+encodeURIComponent(t)).then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const ord=d.order||'rules_first';
    const rulesFirst=(ord==='rules_first'||ord==='rules_only');
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px;line-height:1.9">';
    if(d.source==='ai'){
      h+='<div style="color:#67e8f9;font-weight:700">🤖 پاسخ با هوش مصنوعی</div>';
      h+='<div style="background:#111c31;border-right:3px solid #3b82f6;padding:6px 8px;border-radius:6px;margin-top:5px;color:#bfdbfe;white-space:pre-wrap">'+esc(d.reply)+'</div>';
    }else if(d.source==='rule'){
      const why=rulesFirst
        ? 'قاعدهٔ «'+esc(d.rule)+'» جواب داد'
        : ('هوش مصنوعی نتوانست ('+esc(d.ai_error||'خطا')+') → قاعدهٔ «'+esc(d.rule)+'» جواب داد');
      h+='<div style="color:#fbbf24;font-weight:700">📋 '+why+'</div>';
      h+='<div style="background:#111c31;border-right:3px solid #a855f7;padding:6px 8px;border-radius:6px;margin-top:5px;color:#e9d5ff;white-space:pre-wrap">'+esc(d.reply)+'</div>';
    }else{
      let why;
      if(ord==='rules_only')why='هیچ قاعده‌ای نخورد — پاسخی فرستاده نمی‌شود';
      else if(ord==='ai_only')why='هوش مصنوعی نتوانست ('+esc(d.ai_error||'خطا')+') — پاسخی فرستاده نمی‌شود';
      else why='هوش مصنوعی نتوانست ('+esc(d.ai_error||'خطا')+') و هیچ قاعده‌ای هم نخورد — پاسخی فرستاده نمی‌شود';
      h+='<div style="color:#f87171">✖ '+why+'</div>';
    }
    h+='<div style="color:#64748b;font-size:10px;margin-top:5px">متن نرمال‌شده: '+esc(d.normalized||'')+'</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

/* ============ v9.36: محیط چتِ آزمایش پاسخ خودکار (مودال) ============ */
let arChatBusy=false;
function arOpenChatTest(){
  let m=document.getElementById('arChatModal');if(m)m.remove();
  m=document.createElement('div');
  m.id='arChatModal';
  m.className='bsl-modal-overlay';
  m.innerHTML='<div class="bsl-modal" style="width:820px">'
    +'<div class="bsl-modal-head"><h2>💬 آزمایش پاسخ خودکار</h2>'
    +'<div style="display:flex;gap:6px;align-items:center">'
    +'<span id="arChatStat" style="font-size:11px;color:#64748b"></span>'
    +'<button class="btn btn-red" onclick="arChatClear()" style="font-size:11px;padding:4px 9px">🗑 پاک کردن</button>'
    +'<button class="btn btn-gray" onclick="arCloseChatTest()" style="font-size:11px;padding:4px 9px">✕</button>'
    +'</div></div>'
    +'<div class="bsl-modal-body" id="arChatBody" style="min-height:380px;max-height:55vh;overflow:auto;padding:14px;display:flex;flex-direction:column;gap:10px"></div>'
    +'<div style="padding:10px 14px;background:#1e293b;border-top:1px solid #334155">'
    +'<div style="display:flex;gap:8px;align-items:center">'
    +'<input type="text" id="arChatInput" placeholder="پیام مشتری را بنویسید و Enter بزنید…" '
    +'onkeydown="if(event.key===\'Enter\')arChatSend()" style="flex:1;background:#0f172a;color:#e2e8f0;border:1px solid #334155;border-radius:8px;padding:9px 12px;font-size:13px">'
    +'<button class="btn btn-green" onclick="arChatSend()" style="font-size:12px;padding:9px 16px">➤ ارسال</button>'
    +'</div>'
    +'<div style="display:flex;gap:6px;margin-top:6px;align-items:center;flex-wrap:wrap">'
    +'<span style="font-size:10px;color:#64748b">الگوی پاسخ:</span>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'سلام، این محصول موجوده؟\')" style="font-size:10px;padding:3px 8px">سلام</button>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'قیمت این چنده؟\')" style="font-size:10px;padding:3px 8px">قیمت</button>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'ممنونم\')" style="font-size:10px;padding:3px 8px">تشکر</button>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'ارسال چند روزه است؟\')" style="font-size:10px;padding:3px 8px">ارسال</button>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'یک سوال کاملاً جدید و بی‌ربط\')" style="font-size:10px;padding:3px 8px">بی‌ربط</button>'
    +'</div></div></div>';
  m.addEventListener('click',function(e){if(e.target===m)arCloseChatTest();});
  document.body.appendChild(m);
  const body=$('arChatBody');
  if(body)body.innerHTML='<div style="color:#64748b;font-size:11px;text-align:center;padding:30px">یک پیام بنویسید تا ببینید پاسخ‌خودکار چگونه جواب می‌دهد.</div>';
  setTimeout(()=>{const i=$('arChatInput');if(i)i.focus();},50);
}
function arCloseChatTest(){const m=document.getElementById('arChatModal');if(m)m.remove();}
function arChatFill(t){const i=$('arChatInput');if(i){i.value=t;i.focus();}}
function arChatClear(){
  const body=$('arChatBody');if(body)body.innerHTML='<div style="color:#64748b;font-size:11px;text-align:center;padding:30px">یک پیام بنویسید تا ببینید پاسخ‌خودکار چگونه جواب می‌دهد.</div>';
  if($('arChatStat'))$('arChatStat').textContent='';
}
function arChatBubble(role,html,meta){
  const body=$('arChatBody');if(!body)return;
  const d=document.createElement('div');
  d.style.cssText='max-width:80%;padding:9px 12px;border-radius:12px;font-size:13px;line-height:1.7;white-space:pre-wrap;word-break:break-word;align-self:'+(role==='user'?'flex-end':'flex-start');
  d.style.background=role==='user'?'#1e3a5f':'#1e293b';
  d.style.border=role==='user'?'1px solid #2563eb':'1px solid #334155';
  d.style.color=role==='user'?'#bfdbfe':'#e2e8f0';
  if(meta)d.style.borderTop=(role==='user'?'2px':'0')+' solid transparent';
  d.innerHTML=html;
  if(meta){
    const mt=document.createElement('div');
    mt.style.cssText='font-size:10px;color:#64748b;margin-top:6px;display:flex;gap:8px;flex-wrap:wrap;align-items:center';
    mt.innerHTML=meta;
    d.appendChild(mt);
  }
  body.appendChild(d);
  body.scrollTop=body.scrollHeight;
}
function arChatTyping(){
  const body=$('arChatBody');if(!body)return;
  const d=document.createElement('div');
  d.id='arChatTyping';
  d.style.cssText='max-width:60%;padding:9px 14px;border-radius:12px;font-size:12px;background:#111c31;border:1px solid #334155;color:#94a3b8;align-self:flex-start';
  d.textContent='⏳ در حال بررسی...';
  body.appendChild(d);
  body.scrollTop=body.scrollHeight;
}
function arChatSend(){
  if(arChatBusy)return;
  const inp=$('arChatInput');if(!inp)return;
  const t=inp.value.trim();if(!t){inp.focus();return;}
  inp.value='';
  arChatBubble('user',esc(t),'<span style="color:#93c5fd">👤 مشتری</span>');
  arChatTyping();
  arChatBusy=true;
  if($('arChatStat'))$('arChatStat').textContent='⏳ در حال پاسخ...';
  fetch('?ar_chat=1&msg='+encodeURIComponent(t)).then(r=>r.json()).then(d=>{
    const ty=$('arChatTyping');if(ty)ty.remove();
    arChatBusy=false;
    if($('arChatStat'))$('arChatStat').textContent='';
    if(!d.ok){arChatBubble('bot','<span style="color:#f87171">✗ '+esc(d.error||'خطا')+'</span>');return;}
    const src=d.source||'none';
    const ord=d.order||'rules_first';
    let icon,color,label;
    if(src==='ai'){icon='🤖';color='#67e8f9';label='هوش مصنوعی'+(d.model?' · <span dir="ltr">'+esc(d.model)+'</span>':'');}
    else if(src==='rule'){
      icon='📋';color='#fbbf24';
      label=(ord==='rules_first'||ord==='rules_only')
        ? 'قاعدهٔ «'+esc(d.rule)+'» جواب داد'
        : 'قاعدهٔ «'+esc(d.rule)+'» (هوش مصنوعی خطا داد)';
    }
    else{
      icon='🚫';color='#f87171';
      label=(ord==='rules_only')
        ? 'بدون پاسخ — هیچ قاعده‌ای نخورد'
        : ((ord==='ai_only')
          ? 'بدون پاسخ — هوش مصنوعی پاسخ نداد'
          : 'بدون پاسخ — هوش مصنوعی خطا داد و قاعده‌ای نخورد');
    }
    const replyHtml = d.reply ? esc(d.reply)
        : '<span style="color:#f87171">پاسخی ارسال نشد — '+esc(d.ai_error||'')+'</span>';
    arChatBubble('bot','<div style="font-weight:700;color:'+color+';font-size:12px;margin-bottom:4px">'+icon+' '+label+'</div>'+replyHtml,
      '<span style="color:#64748b">⏱ '+toFa(d.latency_ms||0)+'ms</span>'
      +(d.ai_error?'<span style="color:#f87171" title="'+esc(d.ai_error)+'">⚠️ خطای AI</span>':''));
  }).catch(e=>{
    const ty=$('arChatTyping');if(ty)ty.remove();
    arChatBusy=false;
    if($('arChatStat'))$('arChatStat').textContent='';
    arChatBubble('bot','<span style="color:#f87171">✗ خطای شبکه: '+esc(e.message)+'</span>');
  });
}

function arRun(dry){
  const box=$('arR');
  if(!dry&&!confirm('پاسخ خودکار همین حالا روی گفتگوهای واقعی اجرا شود؟\nپیام‌ها واقعاً ارسال می‌شوند.'))return;
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ '+(dry?'پیش‌نمایش':'اجرا')+'...</div>';
  fetch('?ar_run=1'+(dry?'&dry=1':'&now=1')).then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">🤖 '+(d.dry?'پیش‌نمایش — چیزی ارسال نشد':'اجرا شد')+'</div>';
    h+='<div>بررسی‌شده: <b>'+toFa(d.checked||0)+'</b>'
      +' · '+(d.dry?'ارسال می‌شد':'پاسخ داده شد')+': <b style="color:#4ade80">'+toFa(d.replied||0)+'</b>'
      +' · رد شد: <b style="color:#94a3b8">'+toFa(d.skipped||0)+'</b>'
      +((d.failed||0)?' · خطا: <b style="color:#f87171">'+toFa(d.failed)+'</b>':'')+'</div>';
    if(d.skipped_all)h+='<div style="color:#fbbf24">⏸ '+esc(d.skipped_all)+'</div>';
    (d.items||[]).slice(0,20).forEach(it=>{
      h+='<div style="border-top:1px solid #1e293b;padding-top:4px;margin-top:4px">'
        +'<div style="color:#e2e8f0">👤 '+esc(it.who||'')+' <span style="color:#64748b;font-size:10px">#'+toFa(it.chat_id||0)+'</span></div>'
        +'<div style="color:#94a3b8;font-size:10px">💬 '+esc(it.text||'')+'</div>';
      if(it.rule)h+='<div style="color:#a78bfa;font-size:10px">↳ «'+esc(it.rule)+'» — '+esc(it.status||'')+'</div>';
      else if(it.skip)h+='<div style="color:#64748b;font-size:10px">⏭ '+esc(it.skip)+'</div>';
      h+='</div>';
    });
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

function arShowLog(){
  const box=$('arR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ ...</div>';
  fetch('?ar_log=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    const rows=d.log||[];
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">📜 پاسخ‌های خودکار اخیر ('+toFa(rows.length)+')</div>';
    if(d.last_run)h+='<div style="color:#64748b;font-size:10px">آخرین اجرا: '+esc(new Date(d.last_run*1000).toLocaleString('fa-IR'))+'</div>';
    if(!rows.length)h+='<div style="color:#64748b;padding:8px 0">هنوز پاسخ خودکاری فرستاده نشده</div>';
    rows.forEach(l=>{
      h+='<div style="border-top:1px solid #1e293b;padding-top:4px;margin-top:4px">'
        +'<div style="color:#e2e8f0">👤 '+esc(l.who||'')+' <span style="color:#64748b;font-size:10px">'
        +esc(new Date((l.at||0)*1000).toLocaleString('fa-IR'))+'</span></div>'
        +'<div style="color:#94a3b8;font-size:10px">💬 '+esc(l.in||'')+'</div>'
        +'<div style="color:#a78bfa;font-size:10px">↳ '+esc(l.out||'')+' <span style="color:#475569">«'+esc(l.rule||'')+'»</span></div>'
        +'</div>';
    });
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

/* =====================================================================
 *  v8.53: آمار محصولات هر پروفایل بر اساس پسوند
 * ===================================================================== */
var sfxTimer=null, sfxSeen=0, sfxLast=null;

const SFX_SLICES=[
  {k:'approved',label:'تأیید شده',color:'#22c55e'},
  {k:'rejected',label:'تأیید نشده',color:'#ef4444'},
  {k:'pending', label:'در انتظار', color:'#f59e0b'},
  {k:'inactive',label:'غیرفعال',   color:'#64748b'},
  {k:'archived',label:'بایگانی',   color:'#7c3aed'}
];

function sfxRun(target){
  const notify=($('sfxNotify')||{}).checked?1:0;
  const box=$('sfxR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ شروع...</div>';
  fetch('?suffix_report=1&target='+encodeURIComponent(target)+'&notify='+notify)
    .then(r=>r.json()).then(d=>{
      if(!d.ok){
        if(box)box.innerHTML='<div style="color:#fca5a5;font-size:11px;background:#7f1d1d20;'
          +'padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';
        return;
      }
      sfxWatch(target);
    }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

function sfxWatch(target){
  if(sfxTimer)clearInterval(sfxTimer);
  sfxSeen=0;
  const box=$('sfxR');
  if(box)box.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px">'
    +'<div id="sfxHead" style="color:#93c5fd;margin-bottom:5px">⏳ در حال اجرا...</div>'
    +'<div id="sfxLog" style="max-height:150px;overflow:auto;font-family:ui-monospace,monospace;'
    +'font-size:10.5px;line-height:1.8;background:#111c31;border-radius:6px;padding:6px"></div></div>';
  const tick=()=>{
    fetch('?suffix_status=1&since='+sfxSeen).then(r=>r.json()).then(st=>{
      const lg=$('sfxLog');
      if(lg&&st.log&&st.log.length){
        st.log.forEach(l=>{const d=document.createElement('div');d.style.color='#cbd5e1';
          d.textContent=l.m;lg.appendChild(d);});
        lg.scrollTop=lg.scrollHeight;
      }
      sfxSeen=st.log_total||sfxSeen;
      if(st.done){
        clearInterval(sfxTimer);sfxTimer=null;
        fetch('?suffix_result=1').then(r=>r.json()).then(rep=>{
          sfxLast=rep;
          const b=$('sfxR');
          if(!b)return;
          if(!rep.ok){b.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(rep.error||'خطا')+'</div>';return;}
          b.innerHTML=sfxRender(rep,target);
        }).catch(()=>{});
      }
    }).catch(()=>{});
  };
  tick();
  sfxTimer=setInterval(tick,1000);
}

/** نمودار دایره‌ای با SVG — بدون کتابخانهٔ بیرونی */
function sfxPie(counts,total,size){
  const R=size/2, r=R-2;
  if(!total)return '<svg width="'+size+'" height="'+size+'"><circle cx="'+R+'" cy="'+R+'" r="'+r
    +'" fill="none" stroke="#334155" stroke-width="3"/></svg>';
  let a=-Math.PI/2, out='';
  SFX_SLICES.forEach(s=>{
    const v=counts[s.k]||0;
    if(!v)return;
    const frac=v/total, ang=frac*Math.PI*2;
    if(frac>=0.999){
      out+='<circle cx="'+R+'" cy="'+R+'" r="'+r+'" fill="'+s.color+'"/>';
      return;
    }
    const x1=R+r*Math.cos(a), y1=R+r*Math.sin(a);
    a+=ang;
    const x2=R+r*Math.cos(a), y2=R+r*Math.sin(a);
    out+='<path d="M '+R+' '+R+' L '+x1.toFixed(2)+' '+y1.toFixed(2)
      +' A '+r+' '+r+' 0 '+(ang>Math.PI?1:0)+' 1 '+x2.toFixed(2)+' '+y2.toFixed(2)
      +' Z" fill="'+s.color+'"/>';
  });
  return '<svg width="'+size+'" height="'+size+'" viewBox="0 0 '+size+' '+size+'">'+out+'</svg>';
}


function sfxBar(pct, color){
  pct=Math.max(0,Math.min(100,Number(pct)||0));
  return '<div style="height:6px;background:#1e293b;border-radius:99px;overflow:hidden;margin-top:4px">'
    +'<div style="height:100%;width:'+pct+'%;background:'+color+';border-radius:99px"></div></div>';
}
function sfxStatusChip(st){
  const m={ok:['✓ همگام','#166534','#bbf7d0'],partial:['◐ ناقص','#854d0e','#fde68a'],
    local_only:['فقط محلی','#1e3a8a','#bfdbfe'],empty:['خالی','#334155','#cbd5e1']};
  const x=m[st]||m.empty;
  return '<span style="display:inline-block;padding:2px 8px;border-radius:999px;font-size:10px;font-weight:800;background:'
    +x[1]+';color:'+x[2]+'">'+x[0]+'</span>';
}
function sfxRenderSummary(rep){
  const shops=rep.shops||[];
  const tot=rep.totals||{};
  let h='<div class="sfx-summary-wrap" style="background:linear-gradient(160deg,#0f172a 0%,#1e1b4b 100%);border:1px solid #6d28d9;border-radius:14px;padding:12px;font-size:11px">';
  h+='<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:12px">';
  h+='<b style="color:#e9d5ff;font-size:13px">📋 آمار خلاصهٔ پروفایل‌ها</b>';
  h+='<span style="flex:1"></span>';
  h+='<button class="btn btn-gray" onclick="sfxSend()" style="font-size:10px;padding:3px 8px">📤 پیام‌رسان</button>';
  h+='</div>';
  // KPI cards
  h+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px;margin-bottom:12px">';
  const kpis=[
    ['پروفایل‌ها', tot.profiles||0, '#7c3aed'],
    ['محصول محلی', tot.local||0, '#2563eb'],
    ['ووکامرس', tot.woo||0, '#8b5cf6'],
  ];
  shops.forEach(s=>{
    kpis.push(['🏪 '+(s.name||s.vendor_id), (tot.shops&&tot.shops[s.vendor_id])||0, '#0891b2']);
  });
  kpis.forEach(k=>{
    h+='<div style="background:#0f172a;border:1px solid #334155;border-radius:12px;padding:10px 8px;text-align:center">';
    h+='<div style="font-size:18px;font-weight:900;color:'+k[2]+'">'+toFa(k[1])+'</div>';
    h+='<div style="font-size:10px;color:#94a3b8;margin-top:2px">'+esc(k[0])+'</div></div>';
  });
  h+='</div>';
  if(rep.woo_error) h+='<div style="color:#fca5a5;margin-bottom:6px;font-size:10.5px">⚠️ WC: '+esc(rep.woo_error)+'</div>';
  if(rep.bsl_error) h+='<div style="color:#fca5a5;margin-bottom:6px;font-size:10.5px">⚠️ BSL: '+esc(rep.bsl_error)+'</div>';

  h+='<div style="overflow:auto;max-height:min(70vh,560px);border-radius:10px;border:1px solid #334155">';
  h+='<table style="width:100%;border-collapse:collapse;min-width:640px;font-size:11px">';
  h+='<thead style="position:sticky;top:0;z-index:2"><tr style="background:#1e293b">';
  h+='<th style="padding:9px 10px;text-align:right;color:#94a3b8;font-weight:700">#</th>';
  h+='<th style="padding:9px 10px;text-align:right;color:#e2e8f0;font-weight:800">پروفایل</th>';
  h+='<th style="padding:9px 10px;text-align:center;color:#93c5fd;font-weight:800">📦 محلی</th>';
  h+='<th style="padding:9px 10px;text-align:center;color:#c4b5fd;font-weight:800">🛒 ووکامرس</th>';
  shops.forEach(s=>{
    h+='<th style="padding:9px 10px;text-align:center;color:#67e8f9;font-weight:800">🏪 '+esc(s.name||('#'+s.vendor_id))+'</th>';
  });
  h+='<th style="padding:9px 10px;text-align:center;color:#94a3b8">وضعیت</th>';
  h+='</tr></thead><tbody>';

  (rep.profiles||[]).forEach((p,i)=>{
    const loc=p.local||0, woo=p.woo||0, cov=p.coverage||{};
    const bg = i%2 ? '#0b1220' : '#0f172a';
    h+='<tr style="background:'+bg+';border-top:1px solid #1e293b">';
    h+='<td style="padding:10px;color:#64748b">'+toFa(i+1)+'</td>';
    h+='<td style="padding:10px"><div style="font-weight:800;color:#f1f5f9">'+esc(p.name||'')+'</div>';
    if(p.suffix) h+='<div style="font-size:9.5px;color:#a78bfa;margin-top:2px">پسوند «'+esc(p.suffix)+'»</div>';
    if(p.sync_on) h+='<div style="font-size:9px;color:#4ade80;margin-top:2px">🔄 سینک · '+(p.sync_target||'')+'</div>';
    h+='</td>';
    // local
    h+='<td style="padding:10px;text-align:center"><div style="font-size:16px;font-weight:900;color:#60a5fa">'+toFa(loc)+'</div></td>';
    // woo
    const wPct=cov.woo||0;
    const wColor = wPct>=95?'#22c55e':(wPct>=50?'#f59e0b':(woo>0?'#f97316':'#64748b'));
    h+='<td style="padding:10px;text-align:center;min-width:88px">';
    h+='<div style="font-size:15px;font-weight:900;color:'+wColor+'">'+toFa(woo)+'</div>';
    if(loc>0) h+='<div style="font-size:9px;color:#94a3b8">'+toFa(wPct)+'٪</div>'+sfxBar(wPct,wColor);
    h+='</td>';
    shops.forEach(s=>{
      const vid=s.vendor_id;
      const sc=(p.shops&&p.shops[vid])||0;
      const sp=cov['s'+vid]||0;
      const col = sp>=95?'#22c55e':(sp>=50?'#f59e0b':(sc>0?'#06b6d4':'#64748b'));
      h+='<td style="padding:10px;text-align:center;min-width:88px">';
      h+='<div style="font-size:15px;font-weight:900;color:'+col+'">'+toFa(sc)+'</div>';
      if(loc>0) h+='<div style="font-size:9px;color:#94a3b8">'+toFa(sp)+'٪</div>'+sfxBar(sp,col);
      h+='</td>';
    });
    h+='<td style="padding:10px;text-align:center">'+sfxStatusChip(p.status||'empty')+'</td>';
    h+='</tr>';
  });
  // totals row
  h+='<tr style="background:#1e293b;border-top:2px solid #7c3aed">';
  h+='<td style="padding:10px"></td><td style="padding:10px;font-weight:900;color:#e9d5ff">جمع</td>';
  h+='<td style="padding:10px;text-align:center;font-weight:900;color:#93c5fd;font-size:15px">'+toFa(tot.local||0)+'</td>';
  h+='<td style="padding:10px;text-align:center;font-weight:900;color:#c4b5fd;font-size:15px">'+toFa(tot.woo||0)+'</td>';
  shops.forEach(s=>{
    h+='<td style="padding:10px;text-align:center;font-weight:900;color:#67e8f9;font-size:15px">'+toFa((tot.shops&&tot.shops[s.vendor_id])||0)+'</td>';
  });
  h+='<td></td></tr>';
  h+='</tbody></table></div>';
  h+='<div style="margin-top:8px;font-size:10px;color:#64748b;line-height:1.7">تطبیق: remote_map + پسوند عنوان + عنوان بدون پسوند. پوشش ٪ = مقصد ÷ محلی (سقف ۱۰۰).</div>';
  if(rep.delivery) h+='<div style="color:#4ade80;margin-top:6px">✅ گزارش فرستاده شد</div>';
  return h+'</div>';
}
function sfxRemoteStatus(r,target){
  r=r||{};
  if(target==='bsl'){
    const code=Number(r.status||0);
    const m={2976:['فعال / تأییدشده','#166534','#bbf7d0'],3567:['تأیید نشده','#7f1d1d','#fecaca'],
      3568:['در انتظار','#854d0e','#fde68a'],3790:['غیرفعال','#334155','#cbd5e1'],4184:['بایگانی','#4c1d95','#e9d5ff']};
    const x=m[code]||['نامشخص'+(code?' ('+code+')':''),'#334155','#cbd5e1'];
    return '<span style="display:inline-block;padding:2px 7px;border-radius:999px;font-size:10px;font-weight:800;background:'+x[1]+';color:'+x[2]+'">'+x[0]+'</span>';
  }
  const st=String(r.wstatus||'');
  const m={publish:['منتشر','#166534','#bbf7d0'],pending:['در انتظار','#854d0e','#fde68a'],draft:['پیش‌نویس','#334155','#cbd5e1'],trash:['بایگانی/زباله‌دان','#4c1d95','#e9d5ff']};
  const x=m[st]||['نامشخص'+(st?' ('+esc(st)+')':''),'#334155','#cbd5e1'];
  return '<span style="display:inline-block;padding:2px 7px;border-radius:999px;font-size:10px;font-weight:800;background:'+x[1]+';color:'+x[2]+'">'+x[0]+'</span>';
}
function sfxRenderMisc(rep,target){
  const rows=Array.isArray(rep.misc)?rep.misc:[];
  if(!rows.length) return (Number(rep.unmatched||0)>0
    ?'<div style="color:#fbbf24;font-size:10.5px;margin:8px 0">⚠️ فهرست متفرقه‌ها از سرور دریافت نشد.</div>':'');
  let h='<details open style="margin:8px 0 10px;border:1px solid #92400e;border-radius:9px;background:#1c1917">';
  h+='<summary style="cursor:pointer;padding:8px 10px;color:#fbbf24;font-weight:900">🗂 متفرقه‌ها ('+toFa(rows.length)+') — بدون پسوند/شناسهٔ قابل‌تطبیق</summary>';
  h+='<div style="overflow:auto;max-height:300px;border-top:1px solid #78350f">';
  h+='<table style="width:100%;border-collapse:collapse;min-width:500px;font-size:10.5px">';
  h+='<thead style="position:sticky;top:0;background:#292524;z-index:1"><tr>';
  h+='<th style="padding:7px;text-align:right;color:#a8a29e">#</th><th style="padding:7px;text-align:right;color:#e7e5e4">عنوان</th>';
  h+='<th style="padding:7px;text-align:center;color:#d6d3d1">شناسه</th><th style="padding:7px;text-align:center;color:#fbbf24">وضعیت</th></tr></thead><tbody>';
  rows.forEach((r,i)=>{
    h+='<tr style="border-top:1px solid #44403c">';
    h+='<td style="padding:7px;color:#78716c">'+toFa(i+1)+'</td>';
    h+='<td style="padding:7px;color:#f5f5f4;word-break:break-word">'+esc(r.title||'—')+'</td>';
    h+='<td style="padding:7px;text-align:center;color:#a8a29e;direction:ltr">'+toFa(r.id||0)+'</td>';
    h+='<td style="padding:7px;text-align:center">'+sfxRemoteStatus(r,target)+'</td></tr>';
  });
  h+='</tbody></table></div></details>';
  return h;
}
function sfxRender(rep,target){
  if(rep && (rep.kind==='summary' || target==='summary' || target==='all')) return sfxRenderSummary(rep);
  const lbl=target==='woo'?'ووکامرس':'باسلام';

  let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px">';
  h+='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px">'
   +'<b style="color:#e2e8f0">📊 آمار '+esc(lbl)+'</b>'
   +'<span style="color:#94a3b8">کل مقصد: '+toFa(rep.remote_total||0)+'</span>'
   +((rep.unmatched||0)>0?'<span style="color:#fbbf24">🗂 متفرقه‌ها: '+toFa(rep.misc_total||rep.unmatched)+'</span>':'')
   +'<span style="flex:1"></span>'
   +'<button class="btn btn-gray" onclick="sfxSend()" style="font-size:10px;padding:3px 8px">📤 ارسال به پیام‌رسان</button>'
   +'</div>';
  if(rep.delivery)h+='<div style="color:#4ade80;margin-bottom:6px">✅ گزارش فرستاده شد</div>';
  if(rep.notify_error)h+='<div style="color:#fca5a5;margin-bottom:6px">⚠️ '+esc(rep.notify_error)+'</div>';
  h+=sfxRenderMisc(rep,target);
  (rep.profiles||[]).forEach(p=>{
    const c=p.counts||{}, q=p.pct||{};
    h+='<div class="sfx-card">';
    h+='<div class="sfx-pie">'+sfxPie(c,p.total||0,86)+'</div>';
    h+='<div class="sfx-info">';
    h+='<div class="sfx-name">🏷 '+esc(p.name)+' <span class="sfx-sfx">«'+esc(p.suffix)+'»</span></div>';
    h+='<div class="sfx-total">ثبت‌شده: <b>'+toFa(p.total||0)+'</b></div>';
    if(p.total>0){
      SFX_SLICES.forEach(s=>{
        const v=c[s.k]||0; if(!v)return;
        h+='<div class="sfx-row"><i style="background:'+s.color+'"></i>'
          +'<span>'+s.label+'</span><b>'+toFa(v)+'</b>'
          +'<span class="sfx-pct">'+toFa(q[s.k]||0)+'٪</span></div>';
      });
    }else{
      h+='<div style="color:#64748b">هیچ محصولی با این پسوند پیدا نشد</div>';
    }
    h+='</div></div>';
  });
  if(!(rep.profiles||[]).length)h+='<div style="color:#64748b">پروفایلی با پسوند نبود</div>';
  return h+'</div>';
}

function sfxSend(){
  fetch('?suffix_notify=1').then(r=>r.json()).then(d=>{
    if(!d.ok){showToast(d.error||'ارسال ناموفق',1);return;}
    const bad=Object.keys(d.delivery||{}).filter(k=>d.delivery[k]!=='sent');
    showToast(bad.length?('⚠ ناموفق: '+bad.join('، ')):'✓ گزارش فرستاده شد',bad.length?1:0);
  }).catch(()=>showToast('خطا شبکه',1));
}

