/* v8.87: پیش‌نمایش زندهٔ تعدیل قیمت مقصد.
   روی یک قیمت نمونه نشان می‌دهد نتیجه چه می‌شود، تا قبل از ذخیره معلوم
   باشد درصد درست وارد شده یا نه (مثلاً ۲۰- به‌جای ۲۰). */
function destAdjustPreviewNum(base,mode,val,round){
  if(!(base>0))return 0;
  let out=base;
  if(mode==='percent')out=base*(1+(val/100));
  else if(mode==='multiplier')out=val>0?base*val:base;
  out=Math.round(out);
  if(round>0)out=Math.round(out/round)*round;
  return out>0?out:base;
}
function syncWcPriceUi(from){
  /* v10.112: همگام فیلدهای تعدیل WC در همبرگر و تب تنظیمات */
  const pairs=[['wcPMode','wcPModeHb'],['wcPVal','wcPValHb'],['wcPRound','wcPRoundHb']];
  pairs.forEach(function(pr){
    const a=$(pr[0]), b=$(pr[1]);
    if(!a||!b)return;
    if(from==='hb'){ a.value=b.value; }
    else { b.value=a.value; }
  });
}
function destPricePreview(pre){
  if(pre==='wc'){
    /* اگر از همبرگر پر شده، اول همگام کن */
    try{ if($('wcPModeHb')&&$('wcPMode')) syncWcPriceUi(document.activeElement&&(document.activeElement.id||'').indexOf('Hb')>=0?'hb':'main'); }catch(e){}
  }
  const mEl=$(pre+'PMode'),vEl=$(pre+'PVal'),rEl=$(pre+'PRound'),out=$(pre+'PPrev');
  const outHb = pre==='wc' ? $('wcPPrevHb') : null;
  if(!mEl)return;
  const mode=mEl.value,val=parseFloat(vEl&&vEl.value)||0,round=parseInt(rEl&&rEl.value)||0;
  function paint(el){
    if(!el)return;
    if(mode==='none'){el.textContent='بدون تغییر — همان قیمت پروفایل به مقصد می‌رود';el.style.color='#94a3b8';return;}
    const sample=250000;
    const res=destAdjustPreviewNum(sample,mode,val,round);
    const diff=res-sample;
    const pct=sample>0?Math.round(diff/sample*1000)/10:0;
    el.style.color=diff>0?'#4ade80':(diff<0?'#fbbf24':'#94a3b8');
    el.textContent='نمونه پروفایل: '+toFa(sample.toLocaleString('en-US'))+' → مقصد: '
      +toFa(res.toLocaleString('en-US'))
      +'  ('+(diff>=0?'+':'')+toFa(pct)+'٪)';
  }
  paint(out); paint(outHb);
}


/* v10.113: جدول مقایسه — سرورساید + progress + فقط خواندن صفحه */
window._smPage = 1;
window._smPoll = null;
function smFa(n){ try{ return toFa(String(n)); }catch(e){ return String(n); } }
function smMoney(n){
  n=parseInt(n)||0; if(n<=0) return '—';
  try{ return toFa(n.toLocaleString('en-US')); }catch(e){ return String(n); }
}
function smToneBg(t){
  return ({ok:'#14532d',warn:'#713f12',bad:'#7f1d1d',missing_dst:'#1e3a8a',extra:'#334155',no_src:'#3f3f46',na:'#0f172a'})[t]||'#0f172a';
}
function smToneFg(t){
  return ({ok:'#bbf7d0',warn:'#fde68a',bad:'#fecaca',missing_dst:'#bfdbfe',extra:'#e2e8f0',no_src:'#d4d4d8',na:'#64748b'})[t]||'#94a3b8';
}
function smCell(html, tone){
  const bg=smToneBg(tone), fg=smToneFg(tone);
  return '<td style="padding:7px 8px;border-bottom:1px solid #1e293b;background:'+bg+';color:'+fg+';vertical-align:top;line-height:1.55">'+html+'</td>';
}
function smShowJob(on){
  const bar=$('smJobBar'); if(bar) bar.style.display=on?'block':'none';
}
function smPaintProgress(p){
  p=p||{};
  smShowJob(true);
  const pct=Math.max(0,Math.min(100,parseInt(p.pct)||0));
  if($('smJobPct')) $('smJobPct').textContent=smFa(pct)+'٪';
  if($('smJobFill')) $('smJobFill').style.width=pct+'%';
  if($('smJobLabel')){
    const ph=p.phase||'';
    $('smJobLabel').textContent = p.running ? ('⏳ '+(ph||'در حال ساخت')+'…') : (p.done ? (p.error?'❌ خطا':'✅ تمام') : '—');
  }
  if($('smJobLog') && Array.isArray(p.log)){
    const lines=p.log.slice(-80).map(x=> (x&&x.m)?x.m:String(x));
    const el=$('smJobLog');
    el.innerHTML=lines.map(l=>'<div style="border-bottom:1px solid #1e293b;padding:2px 0">'+esc(l)+'</div>').join('');
    try{ el.scrollTop = el.scrollHeight; }catch(e){}
  }
  const stopBtn=$('smFixStopBtn');
  if(stopBtn) stopBtn.style.display = (p.running && (p.job==='fix' || p.phase==='woo_fix' || p.phase==='bsl_fix' || p.phase==='queued' || (p.ok_n!=null))) ? '' : (p.running && p.job==='fix' ? '' : stopBtn.style.display);
  if(stopBtn && p.running && (String(p.phase||'').indexOf('fix')>=0 || p.job==='fix' || p.ok_n!=null || p.phase==='woo_fix' || p.phase==='bsl_fix' || p.phase==='queued')){
    stopBtn.style.display='';
  }
  if(stopBtn && !p.running) stopBtn.style.display='none';
  const ban=$('smFixBanner');
  if(ban && (p.ok_n!=null || p.job==='fix' || String(p.phase||'').indexOf('fix')>=0 || String(p.phase||'').indexOf('send')>=0 || String(p.phase||'').indexOf('del')>=0 || p.phase==='queued' || p.phase==='start')){
    ban.style.display='block';
    ban.innerHTML = (p.running?'⏳ در حال مغایرت‌گیری… ':'')
      +'✅ '+smFa(p.ok_n||0)+' · ❌ '+smFa(p.fail_n||0)
      +' · '+smFa(p.cur||0)+'/'+smFa(p.total||0)
      +' · 💰'+smFa(p.price_n||0)+' · 📤'+smFa(p.sent_n||0)+' · 🗑'+smFa(p.del_n||0)
      +(p.phase?(' · '+esc(String(p.phase))):'');
  }
}
function syncMatrixStart(){
  smShowJob(true);
  if($('smJobLabel')) $('smJobLabel').textContent='🚀 ارسال جاب به سرور…';
  if($('smBody')) $('smBody').innerHTML='<tr><td style="padding:16px;text-align:center;color:#a5b4fc">ساخت روی سرور شروع شد — می‌توانید این صفحه را باز بگذارید</td></tr>';
  const fd=new FormData();
  fd.append('action','sync_matrix_start');
  fd.append('source','manual');
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    if(!d||!d.ok){
      showToast((d&&d.error)||'شروع ناموفق',1);
      if(d&&d.running) syncMatrixPoll();
      return;
    }
    showToast('ساخت روی سرور آغاز شد');
    syncMatrixPoll();
  }).catch(e=>showToast('خطا: '+e,1));
}
function syncMatrixPoll(){
  if(window._smPoll) clearInterval(window._smPoll);
  const tick=()=>{
    const fd=new FormData(); fd.append('action','sync_matrix_status');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
      if(!d||!d.ok)return;
      const p = d.progress || {};
      if(d.fix_running && d.fix_progress) smPaintProgress(d.fix_progress);
      else smPaintProgress(p);
      if(d.running || d.fix_running || d.build_running){
        /* while fixing, refresh table every few ticks so cells update live */
        if(d.fix_running){
          window._smFixTick = (window._smFixTick||0)+1;
          if(window._smFixTick % 3 === 0){
            try{ syncMatrixLoad(window._smPage||1, true); }catch(e){}
          }
        }
      } else {
        if(window._smPoll){ clearInterval(window._smPoll); window._smPoll=null; }
        if(d.has_result){
          /* بعد از اصلاح: برو آخرین صفحه تا ردیف گزارش دیده شود + باکس گزارش */
          setTimeout(()=>{
            const last = window._smLastPages || 1;
            const go = (d.job==='fix' || (d.fix_progress&&d.fix_progress.done)) ? last : 1;
            syncMatrixLoad(go);
          }, 500);
        }
      }
    }).catch(()=>{});
  };
  tick();
  window._smPoll=setInterval(tick, 1500);
}
/* v10.117: اصلاح مغایرت از روی جدول */
function syncMatrixFixStart(scope){
  scope = scope || 'all';
  if(!confirm('مغایرت‌گیری کامل از روی جدول؟\n• اصلاح قیمت ناهماهنگ\n• ارسال (در پروفایل هست / در مقصد نیست)\n• حذف/بایگانی (فقط در مقصد)\nمحدوده: '+(scope==='woo'?'فقط ووکامرس':(scope==='bsl'?'فقط غرفه‌های باسلام':'همه'))+'\nدو ردیف گزارش به انتهای جدول اضافه می‌شود.')) return;
  smShowJob(true);
  if($('smJobLabel')) $('smJobLabel').textContent='🔧 شروع اصلاح…';
  if($('smFixStopBtn')) $('smFixStopBtn').style.display='';
  if($('smJobLog')) $('smJobLog').innerHTML='';
  const fd=new FormData();
  fd.append('action','sync_matrix_fix_start');
  fd.append('scope', scope);
  fd.append('source','manual');
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    if(!d||!d.ok){
      showToast((d&&d.error)||'شروع اصلاح ناموفق',1);
      if(d&&d.running) syncMatrixPoll();
      return;
    }
    showToast('اصلاح مغایرت روی سرور آغاز شد');
    window._smFixTick=0;
    syncMatrixPoll();
  }).catch(e=>showToast('خطا: '+e,1));
}
function syncMatrixFixStop(){
  const fd=new FormData(); fd.append('action','sync_matrix_fix_stop');
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    showToast(d&&d.ok?'درخواست توقف ثبت شد':'توقف ناموفق', !(d&&d.ok));
  }).catch(()=>{});
}
window._smFixDestLists=[];
function smFixOperationLabel(kind){
  return ({price:'اصلاح قیمت',send:'ارسال محصول',delete:'حذف / بایگانی'})[kind]||kind||'اصلاح';
}
function smOpenFixDestination(index){
  const group=window._smFixDestLists[index];
  if(!group)return;
  let modal=document.getElementById('smFixDestModal');
  if(!modal){
    modal=document.createElement('div');
    modal.id='smFixDestModal';
    modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.72);z-index:100001;display:flex;align-items:center;justify-content:center;padding:12px';
    modal.onclick=function(e){if(e.target===modal)smCloseFixDestination();};
    document.body.appendChild(modal);
  }
  let h='<div style="background:#0f172a;border:1px solid #475569;border-radius:12px;width:min(850px,96vw);max-height:90vh;display:flex;flex-direction:column;overflow:hidden;direction:rtl">';
  h+='<div style="padding:11px 14px;background:#1e293b;border-bottom:1px solid #334155;display:flex;align-items:center;justify-content:space-between;gap:8px">';
  h+='<b style="color:#bbf7d0;font-size:13px">✅ اصلاحات انجام‌شده در '+esc(group.label)+'</b>';
  h+='<button class="btn btn-gray" type="button" onclick="smCloseFixDestination()" style="padding:3px 10px">✕</button></div>';
  h+='<div style="padding:10px 12px;overflow:auto"><table style="width:100%;border-collapse:collapse;min-width:560px;font-size:11px">';
  h+='<thead style="position:sticky;top:0;background:#1e293b;z-index:1"><tr><th style="padding:8px;text-align:right">#</th><th style="padding:8px;text-align:right">محصول</th><th style="padding:8px;text-align:center">نوع اصلاح</th><th style="padding:8px;text-align:center">شناسه مقصد</th><th style="padding:8px;text-align:center">نتیجه</th></tr></thead><tbody>';
  group.items.forEach(function(item,i){
    h+='<tr style="border-top:1px solid #334155"><td style="padding:7px;color:#94a3b8">'+smFa(i+1)+'</td>';
    h+='<td style="padding:7px;color:#e2e8f0;word-break:break-word">'+esc(item.title||item.label||'—')+'</td>';
    h+='<td style="padding:7px;text-align:center;color:#c4b5fd">'+esc(smFixOperationLabel(item.kind))+'</td>';
    h+='<td style="padding:7px;text-align:center;color:#67e8f9;direction:ltr">'+(item.id?smFa(item.id):'—')+'</td>';
    h+='<td style="padding:7px;text-align:center;color:#86efac">✅ موفق</td></tr>';
  });
  h+='</tbody></table></div></div>';
  modal.innerHTML=h; modal.style.display='flex';
}
function smCloseFixDestination(){
  const modal=document.getElementById('smFixDestModal');if(modal)modal.style.display='none';
}
function smFixDestinationGroups(st){
  const groups={};
  (st&&Array.isArray(st.details)?st.details:[]).forEach(function(d){
    if(!d||!d.ok||!d.target)return;
    const target=String(d.target)==='woo'?'woo':('bsl_'+String(d.vendor_id||d.destination||'default'));
    const label=String(d.destination|| (d.target==='woo'?'ووکامرس':'باسلام'));
    if(!groups[target])groups[target]={label:label,items:[]};
    groups[target].items.push(d);
  });
  const order=Object.keys(groups).sort(function(a,b){return a==='woo'?-1:(b==='woo'?1:a.localeCompare(b));});
  window._smFixDestLists=order.map(function(k){return groups[k];});
  return window._smFixDestLists;
}

function smPaintReports(d){
  const box = $('smFixReport');
  if(!box) return;
  const reps = (d && d.reports) ? d.reports : [];
  const st = (d && d.fix_stats) ? d.fix_stats : null;
  if((!reps || !reps.length) && !st){ box.style.display='none'; box.innerHTML=''; return; }
  let html = '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px">'
    +'<div style="font-weight:900;color:#fde68a;font-size:13px">📋 گزارش آخرین مغایرت‌گیری'
    +(d.fix_at?(' <span style="font-weight:600;color:#94a3b8;font-size:10px">· '+new Date(d.fix_at*1000).toLocaleString('fa-IR')+'</span>'):'')
    +'</div>'
    +'<button type="button" class="btn btn-gray" style="font-size:10px;padding:3px 8px" onclick="$(\'smFixReport\').style.display=\'none\'">بستن</button>'
    +'</div>';
  if(st){
    html += '<div style="font-size:12px;color:#bbf7d0;margin-bottom:8px;font-weight:700">'
      + (st.stopped?'⏹ متوقف — ':'✅ ')
      +'موفق '+smFa(st.ok||0)+' · ناموفق '+smFa(st.fail||0)+' از '+smFa(st.total||0)
      +' · 💰'+smFa(st.priced||0)+' · 📤'+smFa(st.sent||0)+' · 🗑'+smFa(st.deleted||0)
      +' · محدوده '+(st.scope||'all')
      +'</div>';
  }
  const destinationGroups=smFixDestinationGroups(st);
  if(destinationGroups.length){
    html += '<div style="margin:8px 0 10px;padding:8px 10px;background:#0b1220;border:1px solid #334155;border-radius:8px">';
    html += '<div style="font-size:11px;color:#67e8f9;font-weight:900;margin-bottom:6px">📍 فهرست اصلاحات بر اساس مقصد — برای دیدن محصولات کلیک کنید</div>';
    html += '<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center">';
    destinationGroups.forEach(function(g,i){
      html += '<button type="button" class="btn btn-gray" onclick="smOpenFixDestination('+i+')" style="font-size:10.5px;padding:5px 9px;border-color:#22c55e88;color:#bbf7d0">✅ '+esc(g.label)+' · '+smFa(g.items.length)+' اصلاح</button>';
    });
    const allFixed=destinationGroups.reduce(function(n,g){return n+g.items.length;},0);
    html += '<span style="font-size:10px;color:#94a3b8">جمع: '+smFa(allFixed)+'</span></div></div>';
  }
  (reps||[]).forEach(r=>{
    if(!r) return;
    const bg = r.report_type==='work' ? 'rgba(30,58,95,.55)' : 'rgba(20,83,45,.55)';
    html += '<div style="background:'+bg+';border:1px solid #334155;border-radius:8px;padding:8px 10px;margin-bottom:6px">';
    html += '<div style="font-weight:800;color:#fde68a;margin-bottom:4px">'+esc(r.title||'گزارش')+'</div>';
    if(r.report_text) html += '<div style="font-size:11px;color:#bbf7d0;margin-bottom:4px">'+esc(r.report_text)+'</div>';
    const lines = r.report_lines||[];
    if(lines.length){
      html += '<div style="font-size:10.5px;line-height:1.75;max-height:180px;overflow:auto;direction:rtl">';
      lines.forEach(x=>{ html += '<div style="border-bottom:1px solid #33415544;padding:2px 0">'+esc(String(x))+'</div>'; });
      html += '</div>';
    }
    html += '</div>';
  });
  if(st && st.total===0){
    html += '<div style="font-size:11px;color:#fbbf24;margin-top:4px">⚠️ کاری برای اجرا پیدا نشد. اگر جدول مغایرت نشان می‌دهد، یک‌بار «🚀 ساخت روی سرور» بزنید و دوباره اصلاح کنید. جزئیات در باکس بالا.</div>';
  }
  box.innerHTML = html;
  box.style.display = 'block';
  try{ box.scrollIntoView({behavior:'smooth',block:'nearest'}); }catch(e){}
}
function syncMatrixLoad(page, silent){
  page = page || 1; window._smPage = page;
  silent = !!silent;
  const body = $('smBody'), sum=$('smSummary'), meta=$('smMeta'), pager=$('smPager'), head=$('smHead');
  if(body && !silent) body.innerHTML='<tr><td style="padding:16px;text-align:center;color:#67e8f9">📖 خواندن صفحه از فایل سرور…</td></tr>';
  const fd = new FormData();
  fd.append('action','sync_matrix');
  fd.append('page', String(page));
  fd.append('per_page', String(($('smPer')||{}).value||50));
  fd.append('q', ($('smQ')||{}).value||'');
  if(($('smOnlyMis')||{}).checked) fd.append('only_mismatch','1');
  if(($('smOnlyMiss')||{}).checked) fd.append('only_missing','1');
  if(($('smOnlyDup')||{}).checked) fd.append('only_dup','1');
  fetch('', {method:'POST', body:fd}).then(r=>r.json()).then(d=>{
    if(d && d.progress) smPaintProgress(d.progress);
    if(d && d.running){ syncMatrixPoll(); }
    if(!d || !d.ok){
      if(d && d.need_build){
        if(body) body.innerHTML='<tr><td style="padding:16px;text-align:center;color:#fbbf24">هنوز جدولی روی سرور نیست. «🚀 ساخت روی سرور» را بزنید'
          +(d.running?' (در حال ساخت…)':'')+'</td></tr>';
        if(d.running) syncMatrixPoll();
        return;
      }
      if(body) body.innerHTML='<tr><td style="padding:12px;color:#f87171">خطا: '+(d&&d.error?d.error:'ناموفق')+'</td></tr>';
      return;
    }
    if(d.done || (d.progress&&d.progress.done)) smShowJob(!!(d.progress&&d.progress.running));
    const shops = d.shops||[];
    let h = '<th style="padding:8px;text-align:right;border-bottom:1px solid #475569">#</th>'
      +'<th style="padding:8px;text-align:right;border-bottom:1px solid #475569">عنوان (بدون پسوند)</th>'
      +'<th style="padding:8px;text-align:right;border-bottom:1px solid #475569">پروفایل</th>'
      +'<th style="padding:8px;text-align:right;border-bottom:1px solid #475569">مبدأ</th>'
      +'<th style="padding:8px;text-align:right;border-bottom:1px solid #475569">قیمت پروفایل</th>'
      +'<th style="padding:8px;text-align:right;border-bottom:1px solid #475569">WC انتظار</th>'
      +'<th style="padding:8px;text-align:right;border-bottom:1px solid #475569">WC واقعی</th>';
    shops.forEach(s=>{
      h += '<th style="padding:8px;text-align:right;border-bottom:1px solid #475569">🏪 '+(s.name||('#'+s.vendor_id))+'</th>';
    });
    h += '<th style="padding:8px;text-align:right;border-bottom:1px solid #475569">وضعیت</th>';
    if(head) head.innerHTML = h;

    const s = d.summary||{};
    if(sum){
      const chip=(lab,val,bg)=>'<span style="background:'+bg+';color:#fff;padding:4px 8px;border-radius:8px;font-weight:800">'+lab+': '+smFa(val||0)+'</span>';
      sum.innerHTML = chip('کل فایل',d.row_count_all||s.total,'#4c1d95')+chip('این فیلتر',d.total,'#5b21b6')+chip('یکسان',s.ok,'#166534')+chip('مغایرت',s.price_mismatch,'#b91c1c')
        +chip('نیست در WC',s.missing_woo,'#1d4ed8')+chip('نیست در غرفه',s.missing_bsl,'#0369a1')
        +chip('تکراری پروفایل',s.dup_profile,'#7c3aed');
    }
    const wc = d.woo_cfg||{}, bc=d.bsl_cfg||{};
    const when = d.generated_at ? new Date(d.generated_at*1000).toLocaleString('fa-IR') : '—';
    window._smLastPages = d.pages||1;
    if(meta){
      meta.innerHTML = '📖 از فایل سرور · '+when+' · منبع '+(d.source||'—')
        +' · صفحه '+smFa(d.page)+'/'+smFa(d.pages)+' · نمایش '+smFa(d.total)+' ردیف فیلترشده'
        +' · WC: '+smFa(d.woo_count||0)
        +' · dest WC: '+(wc.mode||'none')+(wc.mode&&wc.mode!=='none'?(' '+wc.val):'')
        +(d.woo_error?(' · ⚠️ WC: '+d.woo_error):'')
        +(d.bsl_error?(' · ⚠️ BSL: '+d.bsl_error):'');
    }
    try{ smPaintReports(d); }catch(e){}
    const rows = d.rows||[];
    if(!rows.length){
      if(body) body.innerHTML='<tr><td colspan="20" style="padding:16px;text-align:center;color:#94a3b8">ردیفی در این فیلتر/صفحه نیست</td></tr>';
    } else if(body){
      const start = ((d.page||1)-1)*(d.per_page||50);
      body.innerHTML = rows.map((r,i)=>{
        if(r && (r.is_report || (r.bare||'').indexOf('__report_')===0)){
          const lines=(r.report_lines||[]).map(x=>'<div style="padding:2px 0;border-bottom:1px solid #33415544">'+esc(String(x))+'</div>').join('');
          const bg = (r.report_type==='work') ? '#1e3a5f' : '#14532d';
          let tr='<tr style="background:'+bg+'">';
          tr += smCell(smFa(start+i+1),'na');
          tr += '<td colspan="'+ (6 + (shops.length||0) + 1) +'" style="padding:10px 12px;border-bottom:1px solid #334155;color:#e2e8f0;vertical-align:top">';
          tr += '<div style="font-weight:900;font-size:12px;margin-bottom:6px;color:#fde68a">'+esc(r.title||'گزارش')+'</div>';
          tr += '<div style="font-size:11px;color:#bbf7d0;margin-bottom:6px">'+esc(r.report_text||'')+'</div>';
          tr += '<div style="font-size:10.5px;line-height:1.7;max-height:160px;overflow:auto">'+lines+'</div>';
          tr += '</td></tr>';
          return tr;
        }
        const stMap={ok:['✅ یکسان','ok'],mismatch:['❌ مغایرت','bad'],missing:['📤 ناقص','missing_dst'],only_profile:['📘 فقط مبدأ','missing_dst'],only_dest:['📦 فقط مقصد','extra'],partial:['➖ ناقص','warn'],removed:['🗑 حذف‌شد','extra'],only_dest_removed:['🗑 حذف‌شد','extra'],report:['📋 گزارش','na']};
        const st=stMap[r.status]||['?','na'];
        let flags='';
        (r.flags||[]).forEach(f=>{
          if(String(f).indexOf('dup')===0) flags+=' <span style="background:#6d28d9;color:#fff;border-radius:4px;padding:0 5px;font-size:10px">تکراری</span>';
        });
        if((r.profile_hits||0)>1) flags+=' <span style="color:#e9d5ff;font-size:10px">×'+smFa(r.profile_hits)+' پروفایل</span>';
        let tr = '<tr>';
        tr += smCell(smFa(start+i+1),'na');
        tr += smCell('<div style="font-weight:700;max-width:220px">'+esc(r.title||r.bare||'')+'</div><div style="font-size:9px;opacity:.7;direction:ltr">'+esc(r.bare||'')+'</div>','na');
        tr += smCell(esc(r.profile||'—')+(r.profile_key?' <span style="opacity:.6">('+esc(r.profile_key)+')</span>':''),'na');
        tr += smCell(smMoney(r.src_price), r.src_price>0?'na':'no_src');
        tr += smCell(smMoney(r.profile_price), r.profile_price>0?'na':'no_src');
        tr += smCell(smMoney(r.woo_expect), r.woo_expect>0?'na':'no_src');
        if(r.woo){
          tr += smCell(smMoney(r.woo.price)+'<div style="font-size:9px;opacity:.75">#'+smFa(r.woo.id)+' · '+esc(r.woo.status||'')+'</div>', r.woo_tone||'na');
        } else {
          tr += smCell(r.profile_hits?'نیست':'—', r.profile_hits?'missing_dst':'na');
        }
        shops.forEach(s=>{
          const cell = (r.shops&&r.shops[s.vendor_id]) ? r.shops[s.vendor_id] : null;
          if(cell){
            const exp = cell.expect||r.bsl_expect||0;
            tr += smCell(smMoney(cell.price)+'<div style="font-size:9px;opacity:.75">انتظار '+smMoney(exp)+' · #'+smFa(cell.id)+'</div>'+(cell.dup?' <b>تکراری</b>':''), cell.tone||'na');
          } else {
            tr += smCell(r.profile_hits?'نیست':'—', r.profile_hits?'missing_dst':'na');
          }
        });
        tr += smCell(st[0]+flags, st[1]);
        tr += '</tr>';
        return tr;
      }).join('');
    }
    if(pager){
      let pg='';
      const mk=(lab,p,dis)=>'<button class="btn '+(p===d.page?'btn-purple':'btn-gray')+'" '+(dis?'disabled':'')+' onclick="syncMatrixLoad('+p+')" style="font-size:11px;padding:5px 10px">'+lab+'</button>';
      pg += mk('«', Math.max(1,d.page-1), d.page<=1);
      const a=Math.max(1,d.page-2), b=Math.min(d.pages,d.page+2);
      for(let p=a;p<=b;p++) pg += mk(smFa(p), p, false);
      pg += mk('»', Math.min(d.pages,d.page+1), d.page>=d.pages);
      pager.innerHTML = pg;
    }
  }).catch(e=>{
    if(body) body.innerHTML='<tr><td style="padding:12px;color:#f87171">خطای شبکه: '+esc(String(e))+'</td></tr>';
  });
}
/* هنگام باز شدن صفحه، اگر نتیجهٔ سرور هست یک‌بار بخوان؛ اگر جاب running است poll کن */
document.addEventListener('DOMContentLoaded', function(){
  try{
    const fd=new FormData(); fd.append('action','sync_matrix_status');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
      if(!d||!d.ok)return;
      if(d.running){ smPaintProgress(d.progress||{}); syncMatrixPoll(); }
      else if(d.has_result){ /* silent */ }
    }).catch(()=>{});
  }catch(e){}
});

