}
/* v9.60: تب‌بندیِ بخش هوش مصنوعی — هر تب یک پنل را نشان می‌دهد تا همه‌چیز
   منظم و قابل‌دسترس باشد (قبلاً یک ستونِ بلند بود و بخش‌های پایین مثل «روش
   اتصال» یا «تست دسته» بریده می‌شدند). */
function aiTab(tab){
    const btns=document.querySelectorAll('.ai-tab-btn');
    btns.forEach(b=>{b.classList.toggle('active', b.getAttribute('data-ai-tab')===tab);});
    const panels=document.querySelectorAll('.ai-tab-panel');
    // v9.61: قبلاً اینجا برای تبِ انتخاب‌شده display='' می‌گذاشتیم که یعنی
    // «استایل درون‌خطی را بردار». ولی فقط تبِ «ارائه‌دهنده‌ها» کلاس .active را
    // دارد (CSS آن را display:block می‌کند)؛ بقیهٔ تب‌ها چنین کلاسی ندارند و با
    // CSS پایه display:none می‌ماندند. نتیجه: با کلیک روی «تست/مدل‌ها/کاندید/
    // اتصال» هیچ محتوایی دیده نمی‌شد (تب‌ها خالی). حالا برای تبِ انتخاب‌شده
    // صریحاً display:block می‌گذاریم تا حتی تب‌های بدون کلاس .active هم باز شوند.
    panels.forEach(p=>{p.style.display=(p.getAttribute('data-ai-panel')===tab)?'block':'none';});
    // v10.05: تبِ اتوماسیون در نخستین باز شدن، کاتالوگ/کارها/وضعیتِ کران را می‌گیرد
    if(tab==='autopilot'){ apLoadCatalog(); apLoadJobs(); apCronState(); }
    // v10.10 (۲۳): تبِ ایجنت هم کاتالوگِ مدل‌ها و وضعیتِ مدلِ فعال را می‌گیرد
    if(tab==='agent'){ agLoadCatalog(); agLoadTools(); }
    // v10.11 (۲۴): تبِ چت هم در نخستین باز شدن فهرستِ مدل‌ها را می‌گیرد
    if(tab==='chat'){ chLoadCatalog(); }
}

/* ═══════════════════════════════════════════════════════════════════
 *  v10.11 (۲۴): لایهٔ مشترکِ «فهرستِ مدل‌ها» برای همهٔ انتخاب‌گرها
 *
 *  چرا نوشته شد: تا ۱۰٫۱۰ هر پنل خودش fetch می‌زد و انتهایش
 *  «.catch(()=>{})» داشت. یعنی اگر درخواست ۵۰۰ می‌داد، یا هاست
 *  به‌جای JSON یک صفحهٔ خطای HTML برمی‌گرداند، یا شبکه قطع بود،
 *  هیچ اتفاقی نمی‌افتاد: منویِ مدل خالی می‌ماند و کاربر فقط
 *  می‌دید «مدل‌ها لود نمی‌شوند» بدون یک کلمه توضیح.
 *
 *  حالا یک بارگذارِ مشترک داریم که سه حالت را صریح نشان می‌دهد:
 *  «در حالِ بارگذاری» · «خطا + کدِ HTTP + دکمهٔ تلاش دوباره» · «خالی».
 * ═══════════════════════════════════════════════════════════════════ */

let aiMdlData = null;     // آخرین پاسخِ موفقِ ?ai_model_index
let aiMdlBusy = false;    // درخواستی در جریان است؟
let aiMdlErr  = '';       // متنِ آخرین خطا (خالی = بی‌خطا)
const aiMdlHosts = [];    // انتخاب‌گرهایی که باید پس از بارگذاری پر شوند

/** یک انتخاب‌گر را ثبت می‌کند تا با هر بارگذاری/خطا به‌روز شود */
function aiMdlRegister(host){
    for(let i=0;i<aiMdlHosts.length;i++){ if(aiMdlHosts[i].err===host.err) return; }
    aiMdlHosts.push(host);
}

/** جعبهٔ وضعیت/خطای زیرِ یک انتخاب‌گر */
function aiMdlSetBox(errId, html){
    const b = $(errId);
    if(!b) return;
    if(!html){ b.classList.add('hidden'); b.innerHTML=''; return; }
    b.classList.remove('hidden');
    b.innerHTML = html;
}

/** پیامِ خطا را با کدِ HTTP و دکمهٔ تلاشِ دوباره می‌سازد */
function aiMdlErrHtml(){
    return '<b>فهرستِ مدل‌ها بارگذاری نشد.</b><br>' + esc(aiMdlErr)
        + '<br><button class="btn btn-gray" onclick="aiMdlLoad(true)">🔄 تلاشِ دوباره</button>';
}

/** همهٔ انتخاب‌گرهای ثبت‌شده را با وضعیتِ فعلی هم‌گام می‌کند */
function aiMdlSync(){
    aiMdlHosts.forEach(function(h){
        if(aiMdlBusy){ aiMdlSetBox(h.err, '⏳ در حالِ بارگذاریِ فهرستِ مدل‌ها…'); return; }
        if(aiMdlErr){ aiMdlSetBox(h.err, aiMdlErrHtml()); return; }
        if(aiMdlData && !aiMdlData.models.length){
            aiMdlSetBox(h.err, 'هیچ مدلی پیدا نشد. در تبِ «ارائه‌دهنده‌ها» یک اتصال ثبت کنید.');
        } else {
            aiMdlSetBox(h.err, '');
        }
        if(typeof h.fill === 'function') h.fill();
    });
}

/**
 * فهرستِ مدل‌ها را می‌گیرد. برخلافِ نسخهٔ قبل هیچ خطایی را قورت نمی‌دهد:
 * کدِ HTTP، پاسخِ غیرJSON و خطای شبکه هرکدام پیامِ خودشان را دارند.
 */
function aiMdlLoad(force){
    if(aiMdlBusy) return;
    if(aiMdlData && !force){ aiMdlSync(); return; }
    aiMdlBusy = true; aiMdlErr = '';
    aiMdlSync();
    let code = 0;
    fetch('?ai_model_index=1', {headers:{'Accept':'application/json'}})
      .then(function(r){ code = r.status; return r.text(); })
      .then(function(txt){
        if(code < 200 || code >= 300) throw new Error('پاسخِ سرور: HTTP ' + toFa(code));
        let d;
        /* هاست‌هایی که صفحهٔ خطا یا بنرِ تبلیغاتی به پاسخ می‌چسبانند، JSON را
           خراب می‌کنند. به‌جای «Unexpected token» گنگ، صریح می‌گوییم چه شد. */
        try { d = JSON.parse(txt); }
        catch(e){
            const head = txt.replace(/\s+/g,' ').slice(0,90);
            throw new Error('پاسخ JSON نبود (HTTP ' + toFa(code) + '). آغازِ پاسخ: ' + head);
        }
        if(!d || !d.ok) throw new Error(String((d && d.error) || 'پاسخِ نامعتبر از سرور'));
        aiMdlData = d; aiMdlBusy = false; aiMdlErr = '';
        aiMdlSync();
      })
      .catch(function(e){
        aiMdlBusy = false;
        aiMdlErr  = (e && e.message) ? e.message
                  : 'ارتباط با سرور برقرار نشد (شبکه یا فایروال).';
        aiMdlSync();
      });
}

/** فهرستِ مدل‌ها پس از اعمالِ فیلترِ قابلیت، ارائه‌دهنده و جست‌وجو */
function aiMdlPick(cap, group, q){
    if(!aiMdlData) return [];
    const needle = String(q||'').trim().toLowerCase();
    return aiMdlData.models.filter(function(m){
        if(cap === 'chat'      && !m.chat)      return false;
        if(cap === 'tools'     && !m.tools)     return false;
        if(cap === 'reasoning' && !m.reasoning) return false;
        if(group && m.group !== group) return false;
        if(needle){
            const hay = (m.id + ' ' + m.name + ' ' + m.provider).toLowerCase();
            if(hay.indexOf(needle) === -1) return false;
        }
        return true;
    });
}

/** منویِ ارائه‌دهنده — گزینهٔ نخست همیشه «همهٔ ارائه‌دهنده‌ها» */
function aiMdlFillProv(provId, cap){
    const sel = $(provId);
    if(!sel || !aiMdlData) return;
    const keep = sel.value;
    const rows = aiMdlPick(cap, '', '');
    const n = {};
    rows.forEach(function(m){ n[m.group] = (n[m.group]||0)+1; });
    let h = '<option value="">همهٔ ارائه‌دهنده‌ها (' + toFa(rows.length) + ' مدل)</option>';
    Object.keys(aiMdlData.groups).forEach(function(g){
        if(!n[g]) return;
        h += '<option value="'+esc(g)+'">'+esc(aiMdlData.groups[g])+' ('+toFa(n[g])+')</option>';
    });
    sel.innerHTML = h;
    sel.value = keep;
    if(sel.value !== keep) sel.value = '';   // ارائه‌دهنده دیگر مدلی ندارد
}

/** نشانه‌های کوتاهِ کنارِ نامِ مدل */
function aiMdlIcons(m){
    let t = m.ready ? '✅' : '💡';
    if(m.tools)     t += '🤖';
    if(m.reasoning) t += '🧠';
    if(!m.chat)     t += '🚫';
    return t;
}

/**
 * منویِ مدل را می‌سازد. مقدارِ قبلی حفظ می‌شود؛ اگر مدلِ انتخابیِ کاربر
 * از فیلتر بیرون افتاد، به‌جای پاک‌شدنِ بی‌صدا به‌عنوان گزینهٔ اضافه می‌ماند.
 */
function aiMdlFillModels(o){
    const sel = $(o.model);
    if(!sel) return;
    const keep = sel.value;
    if(!aiMdlData){
        sel.innerHTML = '<option value="">' + (aiMdlBusy ? '⏳ در حالِ بارگذاری…'
                                                         : '— فهرست بارگذاری نشده —') + '</option>';
        return;
    }
    const group = ($(o.prov)||{value:''}).value;
    const q     = ($(o.search)||{value:''}).value;
    const rows  = aiMdlPick(o.cap, group, q);

    let h = o.blank ? '<option value="">'+esc(o.blank)+'</option>' : '';
    if(!rows.length){
        h += '<option value="" disabled>— هیچ مدلی با این فیلتر پیدا نشد —</option>';
    }
    const byG = {};
    rows.forEach(function(m){ (byG[m.group] = byG[m.group] || []).push(m); });
    Object.keys(byG).forEach(function(g){
        h += '<optgroup label="'+esc(aiMdlData.groups[g]||g)+'">';
        byG[g].forEach(function(m){
            const star = m.quality ? ' — ' + '★'.repeat(m.quality) : '';
            h += '<option value="'+esc(m.id)+'">'+aiMdlIcons(m)+' '+esc(m.name)+star+'</option>';
        });
        h += '</optgroup>';
    });
    sel.innerHTML = h;
    sel.value = keep;
    /* مدلِ انتخابیْ قربانیِ فیلتر نشود: برش می‌گردانیم و علامت می‌زنیم */
    if(keep && sel.value !== keep){
        const all = (aiMdlData.models.filter(function(x){return x.id===keep;})[0]);
        sel.insertAdjacentHTML('beforeend',
            '<optgroup label="خارج از فیلترِ فعلی"><option value="'+esc(keep)+'">'
            + esc(all ? all.name : keep) + '</option></optgroup>');
        sel.value = keep;
    }
    if(typeof o.after === 'function') o.after();
}

/** متنِ راهنمای زیرِ منو برای مدلِ انتخاب‌شده */
function aiMdlHintHtml(id, blankMsg){
    if(!id) return blankMsg;
    const m = aiMdlData ? aiMdlData.models.filter(function(x){return x.id===id;})[0] : null;
    if(!m) return '<span style="color:#fbbf24">این مدل در فهرستِ فعلی نیست — شاید اتصالش حذف شده باشد.</span>';
    const caps = [];
    if(m.chat)      caps.push('💬 چت');
    if(m.tools)     caps.push('🤖 ابزار');
    if(m.reasoning) caps.push('🧠 استدلالی');
    let h = '<b style="color:#93c5fd">'+esc(m.provider)+'</b>';
    if(m.context) h += ' · 📊 ' + toFa(Math.round(m.context/1000)) + 'K حافظه';
    if(caps.length) h += ' · ' + caps.join(' · ');
    if(m.note) h += '<br>💡 ' + esc(m.note);
    if(!m.chat && m.why) h += '<br><span style="color:#f87171">⚠️ ' + esc(m.why) + '</span>';
    if(!m.ready) h += '<br><span style="color:#fbbf24">⚠️ اتصالِ این مدل ثبت نشده — اول در تبِ «ارائه‌دهنده‌ها» کلیدش را وارد کنید.</span>';
    return h;
}

/* ===== v10.05 (۱۹): اتوماسیونِ ایجنتی — کارهای زمان‌بندی‌شده ===== */

let apCatalog = null;      // کاتالوگِ مدل‌ها/کارها/دوره‌ها (یک‌بار بارگذاری)
let apJobsCache = [];      // آخرین فهرستِ کارها
let apModelsCache = [];    // v10.08: کاتالوگِ مدل‌های ابزاردار
let apTagsCache = {};      // v10.08: برچسب‌های جنسِ مدل
let apProvCache = {};      // v10.08: اطلاعاتِ ارائه‌دهنده‌ها
let apModelTag = 'all';    // v10.10: برچسبِ فعالِ فیلترِ مدل‌ها
let apJobView  = 'all';    // v10.10: نمای فعالِ فهرستِ کارها (all|on|off|due|fail)
let apJobsMeta = null;     // v10.10: آخرین پاسخِ ?auto_jobs (برای رندرِ دوباره بدون fetch)

/** انتخابِ یک مدل از فهرست ⇒ نشستن در منویِ فرمِ کار */
function apPickModel(id){
    const sel = $('apModel');
    if(!sel) return;
    /* اگر شناسه در منو نباشد مرورگر value را خالی می‌کند و انتخابِ قبلیِ
       کاربر بی‌سروصدا پاک می‌شود؛ پس قبلش نگه می‌داریم و برمی‌گردانیم. */
    const prev = sel.value;
    sel.value = id;
    if(sel.value !== id){ sel.value = prev; showToast('این مدل در فهرست نیست',true); return; }
    apModelHint();
    fxOkFlash('apModel');
    const m = apModelsCache.filter(function(x){return x.id===id;})[0];
    /* v10.10: اگر فرم در حالتِ ویرایش است بگو مدل روی کدام کار می‌نشیند —
       قبلاً کاربر نمی‌فهمید انتخابش به کارِ در حالِ ویرایش خورده یا کارِ تازه. */
    const jid = ($('apJobId')||{value:''}).value;
    const jb  = jid ? apJobsCache.filter(function(x){return x.id===jid;})[0] : null;
    showToast('مدل انتخاب شد: ' + (m ? m.name : id)
        + (jb ? ' — برای کارِ «'+jb.title+'» (هنوز ذخیره نشده)' : ''));
    softScrollIntoView(sel,{behavior:'smooth',block:'center'});
}
let apLogTimer = null;     // تایمرِ نوسازیِ مودالِ لاگ
let apConvoTimer = null;   // v10.26 (۳۹ب): تایمرِ گفتگوی زنده
let apConvo = [], apCSince = 0;

/** کاتالوگ را یک‌بار می‌گیرد و بخش‌های ثابتِ تب را می‌سازد */
function apLoadCatalog(force){
    /* v10.11 (۲۴): منویِ مدل از فهرستِ مشترک پر می‌شود (با نمایشِ خطا)،
       ولی دوره‌ها/کارهای آماده هنوز از کاتالوگِ اتوماسیون می‌آیند. */
    aiMdlRegister({err:'apModelErr', fill:apFillModelSelect});
    aiMdlLoad(!!force);
    if(apCatalog && !force){ apRenderCatalog(); return; }
    let code = 0;
    fetch('?auto_catalog=1', {headers:{'Accept':'application/json'}})
      .then(function(r){ code = r.status; return r.text(); })
      .then(function(txt){
        if(code < 200 || code >= 300) throw new Error('HTTP ' + toFa(code));
        let d;
        try { d = JSON.parse(txt); }
        catch(e){ throw new Error('پاسخ JSON نبود (HTTP ' + toFa(code) + ')'); }
        if(!d || !d.ok) throw new Error(String(d && d.error || 'پاسخِ نامعتبر'));
        apCatalog = d;
        apRenderCatalog();
      })
      .catch(function(e){
        /* دیگر بی‌صدا نیست: کاربر می‌فهمد چرا فهرستِ کارهای آماده خالی است */
        const t = $('apTaskList');
        if(t) t.innerHTML = '<span style="color:#f87171">کاتالوگِ کارها بارگذاری نشد — '
            + esc((e && e.message) || 'خطای شبکه')
            + ' <button class="btn btn-gray" onclick="apLoadCatalog(true)" '
            + 'style="font-size:9px;padding:2px 7px">🔄 تلاشِ دوباره</button></span>';
      });
}

function apRenderCatalog(){
    const d = apCatalog; if(!d) return;

    // ── دوره‌ها ──
    const sel = $('apEvery');
    if(sel && !sel.options.length){
        sel.innerHTML = d.intervals.map(function(i){
            return '<option value="'+i.m+'"'+(i.m===1440?' selected':'')+'>'+esc(i.label)+'</option>';
        }).join('');
    }

    // ── دکمه‌های آماده ──
    const pre = $('apPresets');
    if(pre){
        pre.innerHTML = d.tasks.filter(function(t){return t.key!=='custom';}).map(function(t){
            return '<button class="btn btn-gray" onclick="apUsePreset(\''+t.key+'\')" '
                 + 'title="'+esc(t.desc)+'" style="flex:0;font-size:9.5px;padding:3px 7px">'
                 + esc(t.title)+'</button>';
        }).join('');
    }

    // ── مدل‌های رایگانِ ابزاردار ──
    apModelsCache = d.models || [];
    apTagsCache   = d.tags || {};
    apProvCache   = d.providers || {};
    apFillModelSelect();
    apRenderModelFilter();
    apRenderModelList();

    // ── کارهای ممکن ──
    const tl = $('apTaskList');
    if(tl){
        let h = '';
        [['site','🏪 مخصوصِ این فروشگاه','#34d399'],
         ['general','🌍 عمومی','#60a5fa']].forEach(function(g){
            const rows = d.tasks.filter(function(t){return t.cat===g[0] && t.key!=='custom';});
            if(!rows.length) return;
            h += '<div style="font-size:10.5px;color:'+g[2]+';font-weight:700;margin:6px 0 3px">'+g[1]+'</div>';
            rows.forEach(function(t){
                h += '<div onclick="apUsePreset(\''+t.key+'\')" style="background:#0f172a;border:1px solid #1e293b;'
                  +  'border-radius:6px;padding:6px 8px;margin-bottom:3px;cursor:pointer" '
                  +  'onmouseover="this.style.borderColor=\'#475569\'" onmouseout="this.style.borderColor=\'#1e293b\'">'
                  +  '<b style="color:#e2e8f0;font-size:10.5px">'+esc(t.title)+'</b>'
                  +  '<div style="font-size:9.5px;color:#64748b;margin-top:2px;line-height:1.7">'+esc(t.desc)+'</div>'
                  +  '</div>';
            });
        });
        tl.innerHTML = h;
    }
}

/** پر کردنِ منویِ انتخابِ مدل در فرمِ کار */
function apFillModelSelect(){
    const sel = $('apModel');
    if(!sel) return;
    /* کارهای زمان‌بندی‌شده ابزار صدا می‌زنند ⇒ فقط مدل‌های ابزاردار */
    aiMdlFillProv('apProvSel', 'tools');
    aiMdlFillModels({model:'apModel', prov:'apProvSel', search:'apModelPick',
                     cap:'tools', blank:'🔗 مدلِ پیش‌فرضِ اتصالات', after:apModelHint});
    sel.onchange = apModelHint;
}

/** تغییرِ ارائه‌دهنده ⇒ فهرستِ مدل‌ها فیلتر می‌شود */
function apProvChange(){ apFillModelSelect(); }

/** توضیحِ زیرِ منو: سقف و ویژگیِ مدلِ انتخاب‌شده */
function apModelHint(){
    const sel = $('apModel'), hint = $('apModelHint');
    if(!sel || !hint) return;
    hint.innerHTML = aiMdlHintHtml(sel.value,
        'مدلِ پیش‌فرضِ اتصالات استفاده می‌شود — اگر مدلی انتخاب کنید باید کلیدش در بخشِ «اتصالات» ثبت شده باشد.');
}

/** دکمه‌های فیلترِ جنسِ مدل */
function apRenderModelFilter(){
    const f = $('apModelFilter');
    if(!f) return;
    const counts = {};
    apModelsCache.forEach(function(m){ counts[m.tag] = (counts[m.tag]||0)+1; });
    /* v10.10: دکمهٔ فیلترِ فعال باید دیده شود؛ قبلاً همه خاکستری می‌ماندند و
       کاربر نمی‌دانست فهرستِ زیرش فیلترشده است یا کامل. */
    const cls = function(k){ return apModelTag===k ? 'btn btn-blue' : 'btn btn-gray'; };
    let h = '<button class="'+cls('all')+'" onclick="apRenderModelList(\'all\')" '
          + 'style="flex:0;font-size:9px;padding:2px 7px">همه ('+toFa(apModelsCache.length)+')</button>';
    Object.keys(apTagsCache).forEach(function(k){
        if(!counts[k]) return;
        const t = apTagsCache[k];
        h += '<button class="'+cls(k)+'" onclick="apRenderModelList(\''+k+'\')" '
          +  'style="flex:0;font-size:9px;padding:2px 7px">'+t.icon+' '+esc(t.label)
          +  ' ('+toFa(counts[k])+')</button>';
    });
    f.innerHTML = h;
}

/** فهرستِ کارتیِ مدل‌ها با دکمهٔ انتخاب */
function apRenderModelList(tag){
    const ml = $('apModelList');
    if(!ml) return;
    if(tag !== undefined && tag !== null){ apModelTag = tag; apRenderModelFilter(); }
    const t = apModelTag;
    const q = (($('apModelSearch')||{value:''}).value||'').trim().toLowerCase();
    let rows = (t==='all') ? apModelsCache
             : apModelsCache.filter(function(m){return m.tag===t;});
    if(q) rows = rows.filter(function(m){
        const pn = (apProvCache[m.provider]||{name:m.provider}).name || '';
        return (m.name+' '+m.id+' '+m.provider+' '+pn+' '+(m.note||'')).toLowerCase().indexOf(q) >= 0;
    });
    const byProv = {};
    rows.forEach(function(m){ (byProv[m.provider] = byProv[m.provider] || []).push(m); });
    let h = '';
    Object.keys(byProv).forEach(function(p){
            const info = apProvCache[p] || {name:p, key:'', card:false};
            h += '<div style="margin-bottom:8px">'
              +  '<div style="font-size:10.5px;color:#93c5fd;font-weight:700;margin-bottom:3px">'
              +  esc(info.name)
              +  ' <span style="font-size:9px;color:#64748b;font-weight:400">'+esc(info.key)+'</span>'
              +  (info.card ? '' : ' <span style="font-size:8.5px;background:#065f46;color:#6ee7b7;padding:1px 5px;border-radius:4px">بدون کارت</span>')
              +  '</div>';
            byProv[p].forEach(function(m){
                const stars = '★'.repeat(m.quality) + '☆'.repeat(5-m.quality);
                const tg = apTagsCache[m.tag] || {icon:'',label:''};
                h += '<div style="background:#0f172a;border:1px solid #1e293b;border-radius:6px;padding:6px 8px;margin-bottom:3px">'
                  +  '<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">'
                  +  '<b style="color:#e2e8f0;font-size:10.5px">'+esc(m.name)+'</b>'
                  +  '<code style="font-size:9px;color:#64748b;background:#111c31;padding:1px 5px;border-radius:4px">'+esc(m.id)+'</code>'
                  +  '<span style="font-size:9px;color:#fbbf24;margin-right:auto">'+stars+'</span>'
                  +  '<button class="btn btn-blue" onclick="apPickModel(\''+jsAttr(m.id)+'\')" '
                  +  'style="flex:0;font-size:9px;padding:2px 8px">انتخاب</button>'
                  +  '</div>'
                  +  '<div style="font-size:9.5px;color:#64748b;margin-top:3px;line-height:1.7">'
                  +  (tg.icon ? tg.icon+' '+esc(tg.label)+' · ' : '')
                  +  '📊 '+toFa(Math.round(m.context/1000))+'K حافظه · ⏱ '+esc(m.limit)
                  +  '<br>💡 '+esc(m.note)+'</div>'
                  +  '</div>';
            });
        h += '</div>';
    });
    ml.innerHTML = h || '<div style="color:#64748b;font-size:10px">موردی با این فیلتر/جست‌وجو پیدا نشد</div>';
}

/** پر کردنِ فرم از روی یک کارِ آماده */
function apUsePreset(key){
    if(!apCatalog) return;
    const t = apCatalog.tasks.find(function(x){return x.key===key;});
    if(!t) return;
    apResetForm();
    $('apTitle').value  = t.title;
    $('apPrompt').value = t.prompt;
    const sel = $('apEvery');
    if(sel) for(let i=0;i<sel.options.length;i++){
        if(+sel.options[i].value === +t.every){ sel.selectedIndex = i; break; }
    }
    /* v10.10: تا ۱۰٫۰۹ هر دو شاخهٔ این شرط 'dry' بود (کدِ مرده) و readOnly
       هیچ اثری نداشت. کارهای فقط‌خواندنی می‌توانند بی‌خطر در «شبیه‌سازی» هم
       دیده شوند، ولی چیزی که کاربر واقعاً لازم دارد آگاهی از خطرِ کار است:
       کارهای نویسنده را در «آزمایشی» نگه می‌داریم و صریح هشدار می‌دهیم. */
    const writes = /اصلاح|صفر کن|تغییر بده|به‌روزرسانی|بروزرسانی|هم‌ترازی|همترازی/.test(t.prompt);
    $('apMode').value = 'dry';
    apModeHint();
    $('apTitle').focus();
    softScrollIntoView($('apTitle'),{behavior:'smooth',block:'center'});
    showToast('«'+t.title+'» در فرم نشست — '
        + (writes ? 'این کار می‌تواند بنویسد؛ فعلاً روی «آزمایشی» است'
                  : 'کارِ فقط‌گزارشی است')
        + ' — در صورت نیاز ویرایش و ذخیره کنید');
}

/** خالی کردنِ فرم و بازگشت به حالتِ «کارِ تازه» */
function apResetForm(){
    $('apJobId').value  = '';
    $('apTitle').value  = '';
    $('apPrompt').value = '';
    $('apMode').value   = 'dry';
    const ms = $('apModel'); if(ms){ ms.value = ''; apModelHint(); }
    $('apEnabled').checked = true;
    const sel = $('apEvery');
    if(sel) for(let i=0;i<sel.options.length;i++){
        if(+sel.options[i].value === 1440){ sel.selectedIndex = i; break; }
    }
    const ft = $('apFormTitle'); if(ft) ft.textContent = '➕ کارِ تازه';
    const cb = $('apCancelBtn'); if(cb) cb.classList.add('hidden');
    const eb = $('apEditBadge'); if(eb) eb.classList.add('hidden');
    const sb = $('apSaveBtn');   if(sb) sb.textContent = '💾 ذخیرهٔ کار';
    apModeHint();
}

/** v10.10: هشدارِ زندهٔ حالتِ اجرا — «واقعی» باید قبل از ذخیره به چشم بیاید */
function apModeHint(){
    const sel = $('apMode'); if(!sel) return;
    const box = $('apModeHint');
    if(!box) return;
    if(sel.value === 'live'){
        box.innerHTML = '<span style="color:#f87171">🔥 در این حالت قیمت و موجودی واقعاً تغییر می‌کند و برگشت‌پذیر نیست.</span>';
    } else if(sel.value === 'sim'){
        box.innerHTML = 'دادهٔ نمونه؛ به هیچ سرویسی وصل نمی‌شود — برای آزمودنِ متنِ دستور خوب است.';
    } else {
        box.innerHTML = 'می‌خواند و گزارش می‌دهد ولی چیزی نمی‌نویسد — امن‌ترین حالت برای شروع.';
    }
}

/** ذخیرهٔ کارِ تازه یا ویرایشِ کارِ موجود */
function apSaveJob(){
    const title  = ($('apTitle').value||'').trim();
    const prompt = ($('apPrompt').value||'').trim();
    if(!title)  { showToast('عنوانِ کار را بنویسید',true);  return; }
    if(!prompt) { showToast('دستورِ کار را بنویسید',true); return; }

    const fd = new FormData();
    fd.append('id',      $('apJobId').value||'');
    fd.append('title',   title);
    fd.append('prompt',  prompt);
    fd.append('mode',    $('apMode').value);
    fd.append('model',   ($('apModel')||{value:''}).value);
    fd.append('every',   $('apEvery').value);
    fd.append('enabled', $('apEnabled').checked ? '1' : '0');

    fetch('?auto_save=1',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){ showToast((d&&d.error)||'ذخیره ناموفق بود',true); return; }
        showToast(d.edited ? 'کار به‌روزرسانی شد' : 'کارِ تازه ساخته شد');
        apResetForm();
        apLoadJobs();
    }).catch(()=>showToast('خطای شبکه',true));
}

/** بارگذاریِ فهرستِ کارها */
function apLoadJobs(){
    fetch('?auto_jobs=1').then(r=>r.json()).then(d=>{
        if(!d||!d.ok) return;
        apJobsCache = d.jobs||[];
        apJobsMeta  = d;
        apRenderJobs(d);
    }).catch(()=>{});
}

/** v10.10: دکمه‌های نمای فهرستِ کارها (همه/فعال/خاموش/سررسید/خطادار) */
function apRenderJobFilter(all){
    const f = $('apJobFilter'); if(!f) return;
    const cnt = {
        all:  all.length,
        on:   all.filter(function(j){return j.enabled;}).length,
        off:  all.filter(function(j){return !j.enabled;}).length,
        due:  all.filter(function(j){return j.due && j.enabled;}).length,
        fail: all.filter(function(j){return j.fails>0;}).length
    };
    const defs = [['all','همه'],['on','▶ فعال'],['off','⏸ خاموش'],['due','⏰ سررسید'],['fail','⚠️ خطادار']];
    f.innerHTML = defs.map(function(d){
        return '<button class="btn '+(apJobView===d[0]?'btn-blue':'btn-gray')+'" '
             + 'onclick="apJobFilterSet(\''+d[0]+'\')" style="flex:0;font-size:9px;padding:2px 7px">'
             + d[1]+' ('+toFa(cnt[d[0]])+')</button>';
    }).join('');
}

function apJobFilterSet(v){ apJobView = v; apRenderJobs(); }

/** v10.10: نامِ خوانای مدل از کاتالوگ (اگر نبود، خودِ شناسه) */
function apModelName(id){
    const m = apModelsCache.filter(function(x){return x.id===id;})[0];
    return m ? m.name : id;
}

function apRenderJobs(d){
    const box = $('apJobList'); if(!box) return;
    /* v10.10: بدون آرگومان هم کار کند تا جست‌وجو/فیلتر بدون رفت‌وبرگشت به
       سرور فهرست را دوباره بسازد. */
    if(!d) d = apJobsMeta;
    if(!d) return;
    const all = d.jobs||[];

    // ── شمارنده‌های بالا (همیشه رویِ کلِ کارها، نه فهرستِ فیلترشده) ──
    let on=0, runs=0, ch=0, fails=0;
    all.forEach(function(j){ if(j.enabled) on++; runs+=j.runs; ch+=j.changes; fails+=j.fails; });
    if($('apStatJobs'))    $('apStatJobs').textContent    = toFa(all.length);
    if($('apStatOn'))      $('apStatOn').textContent      = toFa(on);
    if($('apStatRuns'))    $('apStatRuns').textContent    = toFa(runs);
    if($('apStatChanges')) $('apStatChanges').textContent = toFa(ch);
    if($('apStatFails'))   $('apStatFails').textContent   = toFa(fails);

    apRenderJobFilter(all);

    if(!all.length){
        if($('apJobCount')) $('apJobCount').textContent = '';
        box.innerHTML = '<div style="background:#0f172a;border:1px dashed #334155;border-radius:8px;padding:14px;'
            + 'text-align:center;color:#64748b;font-size:10.5px;line-height:1.9">'
            + 'هنوز کاری تعریف نشده است.<br>یکی از دکمه‌های آمادهٔ بالا را بزنید یا دستورِ خودتان را بنویسید.</div>';
        return;
    }

    const q = (($('apJobSearch')||{value:''}).value||'').trim().toLowerCase();
    let jobs = all.filter(function(j){
        if(apJobView==='on'   && !j.enabled) return false;
        if(apJobView==='off'  &&  j.enabled) return false;
        if(apJobView==='due'  && !(j.due && j.enabled)) return false;
        if(apJobView==='fail' && !(j.fails>0)) return false;
        if(q && ((j.title||'')+' '+(j.prompt||'')+' '+(j.model||'')).toLowerCase().indexOf(q) < 0) return false;
        return true;
    });

    if($('apJobCount')) $('apJobCount').textContent =
        (jobs.length===all.length) ? '('+toFa(all.length)+')'
                                   : '('+toFa(jobs.length)+' از '+toFa(all.length)+')';

    if(!jobs.length){
        box.innerHTML = '<div style="background:#0f172a;border:1px dashed #334155;border-radius:8px;padding:12px;'
            + 'text-align:center;color:#64748b;font-size:10.5px">هیچ کاری با این فیلتر/جست‌وجو پیدا نشد.</div>';
        return;
    }

    /* v10.10: mode ممکن است از فایلِ قدیمی مقدارِ ناشناخته داشته باشد ⇒ fallback
       تا به‌جای «undefined» چیزی معنادار دیده شود. */
    const modeLbl = {sim:'🧪 شبیه‌سازی', dry:'🔍 آزمایشی', live:'🔥 واقعی'};
    const modeCol = {sim:'#94a3b8', dry:'#60a5fa', live:'#f87171'};
    const mLbl = function(m){ return modeLbl[m] || ('❔ '+(m||'نامشخص')); };
    const mCol = function(m){ return modeCol[m] || '#64748b'; };

    box.innerHTML = jobs.map(function(j){
        const st = (j.last_ok===null||j.last_ok===undefined) ? {t:'—',c:'#64748b'}
                 : (j.last_ok ? {t:'✅ موفق',c:'#34d399'} : {t:'❌ ناموفق',c:'#f87171'});
        return '<div style="background:#0f172a;border:1px solid '+(j.enabled?'#334155':'#1e293b')
          + ';border-radius:8px;padding:8px;margin-bottom:6px'+(j.enabled?'':';opacity:.6')+'">'
          + '<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:5px">'
          +   '<b style="color:#e2e8f0;font-size:11.5px">'+esc(j.title)+'</b>'
          +   '<span style="font-size:9px;color:'+mCol(j.mode)+';background:#111c31;padding:1px 6px;border-radius:4px">'+esc(mLbl(j.mode))+'</span>'
          +   (j.model ? '<span style="font-size:9px;color:#a78bfa;background:#111c31;padding:1px 6px;border-radius:4px" title="'+esc(j.model)+'">🧠 '+esc(apModelName(j.model))+'</span>' : '')
          +   (j.due&&j.enabled ? '<span style="font-size:9px;color:#facc15;background:#422006;padding:1px 6px;border-radius:4px">سررسید</span>' : '')
          +   '<span style="margin-right:auto;font-size:9.5px;color:#64748b">🕒 '+esc(j.next_label)+'</span>'
          + '</div>'
          + '<div style="font-size:10px;color:#64748b;line-height:1.7;margin-bottom:5px;'
          +   'white-space:nowrap;overflow:hidden;text-overflow:ellipsis">💬 '+esc(j.prompt)+'</div>'
          + '<div style="display:flex;gap:8px;flex-wrap:wrap;font-size:9.5px;color:#64748b;margin-bottom:6px">'
          +   '<span>🔁 '+toFa(j.runs)+' اجرا</span>'
          +   '<span>✏️ '+toFa(j.changes)+' تغییر</span>'
          +   (j.fails ? '<span style="color:#f87171">⚠️ '+toFa(j.fails)+' خطا</span>' : '')
          +   '<span style="color:'+st.c+'">'+st.t+'</span>'
          + '</div>'
          + (j.last_msg ? '<div style="font-size:9.5px;color:#94a3b8;background:#111c31;border-radius:5px;'
          +   'padding:4px 6px;margin-bottom:6px;line-height:1.7">'+esc(j.last_msg.substring(0,180))+'</div>' : '')
          + '<div class="cact" style="gap:4px">'
          +   '<button class="btn '+(j.enabled?'btn-gray':'btn-green')+'" onclick="apToggle(\''+j.id+'\')" style="flex:0;font-size:9.5px;padding:3px 8px">'
          +     (j.enabled?'⏸ خاموش':'▶ روشن')+'</button>'
          +   '<button class="btn btn-purple" onclick="apRunNow(\''+j.id+'\')" style="flex:0;font-size:9.5px;padding:3px 8px">⚡ اجرای فوری</button>'
          +   '<button class="btn btn-blue" onclick="apShowLog(\''+j.id+'\')" style="flex:0;font-size:9.5px;padding:3px 8px">📋 لاگ'
          +     (j.log_count?' ('+toFa(j.log_count)+')':'')+'</button>'
          +   '<button class="btn btn-gray" onclick="apEditJob(\''+j.id+'\')" style="flex:0;font-size:9.5px;padding:3px 8px">✏️</button>'
          +   '<button class="btn btn-red" onclick="apDeleteJob(\''+j.id+'\')" style="flex:0;font-size:9.5px;padding:3px 8px">🗑</button>'
          + '</div>'
          + '</div>';
    }).join('');
}

/** بردنِ یک کار به فرم برای ویرایش */
function apEditJob(id){
    const j = apJobsCache.find(function(x){return x.id===id;});
    if(!j) return;
    $('apJobId').value  = j.id;
    $('apTitle').value  = j.title;
    $('apPrompt').value = j.prompt;
    $('apMode').value   = j.mode;
    const ms = $('apModel'); if(ms){ ms.value = j.model || ''; apModelHint(); }
    $('apEnabled').checked = !!j.enabled;
    const sel = $('apEvery');
    if(sel) for(let i=0;i<sel.options.length;i++){
        if(+sel.options[i].value === +j.every){ sel.selectedIndex = i; break; }
    }
    const ft = $('apFormTitle'); if(ft) ft.textContent = '✏️ ویرایشِ «'+j.title+'»';
    const cb = $('apCancelBtn'); if(cb) cb.classList.remove('hidden');
    const eb = $('apEditBadge'); if(eb) eb.classList.remove('hidden');
    const sb = $('apSaveBtn');   if(sb) sb.textContent = '💾 ذخیرهٔ تغییرات';
    apModeHint();
    softScrollIntoView($('apTitle'),{behavior:'smooth',block:'center'});
}

/** روشن/خاموشِ سریع */
function apToggle(id){
    const fd = new FormData(); fd.append('id',id);
    fetch('?auto_toggle=1',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){ showToast((d&&d.error)||'ناموفق',true); return; }
        showToast(d.enabled?'کار فعال شد':'کار خاموش شد');
        apLoadJobs();
    }).catch(()=>showToast('خطای شبکه',true));
}

/** حذفِ کار */
function apDeleteJob(id){
    const j = apJobsCache.find(function(x){return x.id===id;});
    if(!confirm('کارِ «'+(j?j.title:id)+'» و کلِ لاگش حذف شود؟')) return;
    const fd = new FormData(); fd.append('id',id);
    fetch('?auto_delete=1',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){ showToast((d&&d.error)||'حذف ناموفق',true); return; }
        showToast('کار حذف شد');
        apLoadJobs();
    }).catch(()=>showToast('خطای شبکه',true));
}

/** اجرای فوریِ یک کار — بدون منتظرِ کران ماندن */
function apRunNow(id){
    const j = apJobsCache.find(function(x){return x.id===id;});
    if(j && j.mode==='live' && !confirm('این کار در حالتِ «اجرای واقعی» است و قیمت/موجودی را تغییر می‌دهد. مطمئنید؟')) return;
    const fd = new FormData(); fd.append('id',id);
    fetch('?auto_run_now=1',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){ showToast((d&&d.error)||'اجرا ناموفق',true); return; }
        showToast('اجرا شروع شد — پیشرفت در تبِ ایجنت دیده می‌شود');
        // لاگ را باز نگه دار تا کاربر نتیجه را زنده ببیند
        apShowLog(id, true);
    }).catch(()=>showToast('خطای شبکه',true));
}

/** تیکِ دستیِ زمان‌بند */
function apTick(){
    showToast('در حالِ اجرای تیک…');
    fetch('?auto_tick=1').then(r=>r.json()).then(d=>{
        if(!d||!d.ok){ showToast('تیک ناموفق',true); return; }
        if(d.locked)    showToast('یک تیکِ دیگر در جریان است');
        else if(!d.ran) showToast('هیچ کاری سررسید نشده بود');
        else            showToast(toFa(d.ran)+' کار اجرا شد');
        apLoadJobs();
    }).catch(()=>showToast('خطای شبکه',true));
}

/* ===== مودالِ لاگِ هر کار ===== */

/** باز کردنِ مودالِ لاگ. live=true یعنی تا پایانِ اجرا خودش نو شود. */
function apShowLog(id, live){
    let m = $('apLogModal');
    if(!m){
        m = document.createElement('div');
        m.id = 'apLogModal';
        m.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;z-index:99999;'
                        + 'background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center';
        document.body.appendChild(m);
    }
    m.style.display = 'flex';
    m.dataset.jobId = id;
    m.innerHTML = '<div style="background:#1e293b;border:1px solid #475569;border-radius:12px;padding:16px;'
        + 'width:90%;max-width:720px;max-height:85vh;overflow-y:auto;color:#e2e8f0">'
        + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">'
        +   '<span style="font-weight:700;font-size:14px;color:#60a5fa">📋 لاگِ اجراها</span>'
        +   '<div style="display:flex;gap:4px">'
        +     '<button class="btn btn-gray" onclick="apLoadLog()" style="font-size:10px;padding:4px 8px">🔄</button>'
        +     '<button class="btn btn-red" onclick="apClearLog()" style="font-size:10px;padding:4px 8px">🗑 پاک‌کردن</button>'
        +     '<button class="btn btn-gray" onclick="apCloseLog()" style="font-size:10px;padding:4px 8px">✕</button>'
        +   '</div>'
        + '</div>'
        /* v10.26 (۳۹ب): گفتگوی زندهٔ همین اجرا، داخلِ همین پنجره. تا اینجا
           کاربر بعد از «⚡ اجرای فوری» فقط یک لاگِ پس از پایان می‌دید و در
           تمامِ مدتِ اجرا بی‌خبر بود. */
        + '<details class="cvo hidden" id="apConvo">'
        +   '<summary><span>💬 گفتگوی زندهٔ این اجرا</span>'
        +     '<span class="cvo-live hidden" id="apConvoLive">در جریان</span>'
        +     '<span class="cvo-n" id="apConvoN">۰ پیام</span></summary>'
        +   '<div class="cvo-bd" id="apConvoBody"></div>'
        + '</details>'
        + '<div id="apLogBody" style="font-size:11px;margin-top:10px">در حالِ بارگذاری…</div>'
        + '</div>';
    apLoadLog();
    if(apLogTimer){ clearInterval(apLogTimer); apLogTimer = null; }
    if(live) apLogTimer = setInterval(apLoadLog, 3000);
    /* گفتگو را تندتر از لاگ نو کن (لاگ فقط بعد از پایانِ اجرا پر می‌شود،
       ولی گفتگو همان لحظه معنا دارد). */
    apConvo = []; apCSince = 0;
    cvoRender('apConvo', [], !!live);
    if(apConvoTimer){ clearInterval(apConvoTimer); apConvoTimer = null; }
    apConvoTick();
    apConvoTimer = setInterval(apConvoTick, 1500);
}

/** v10.26 (۳۹ب): نظرسنجیِ گفتگوی ایجنت برای مودالِ اتوماسیون.
 *  کارهای اتوماسیون از همان agentRun می‌گذرند، پس همان فایلِ پیشرفت را
 *  می‌خوانیم — نیازی به اندپوینتِ تازه نیست. */
function apConvoTick(){
    const m = $('apLogModal');
    if(!m || m.style.display === 'none'){ if(apConvoTimer){ clearInterval(apConvoTimer); apConvoTimer = null; } return; }
    fetch('?agent_status&since=99999&csince=' + apCSince).then(r=>r.json()).then(p=>{
        if(!p) return;
        if(p.convo && p.convo.length){
            p.convo.forEach(function(x){ apConvo.push(x); });
            apCSince = p.convo_total || apConvo.length;
        } else if(typeof p.convo_total === 'number'){
            apCSince = p.convo_total;
        }
        cvoRender('apConvo', apConvo, !p.done && !!p.running);
        if(p.done && apConvoTimer){ clearInterval(apConvoTimer); apConvoTimer = null; }
    }).catch(()=>{});
}

function apCloseLog(){
    const m = $('apLogModal');
    if(m) m.style.display = 'none';
    if(apLogTimer){ clearInterval(apLogTimer); apLogTimer = null; }
    if(apConvoTimer){ clearInterval(apConvoTimer); apConvoTimer = null; }   // v10.26 (۳۹ب)
    apLoadJobs();
}

function apClearLog(){
    const m = $('apLogModal'); if(!m) return;
    if(!confirm('کلِ لاگِ این کار پاک شود؟')) return;
    const fd = new FormData(); fd.append('id', m.dataset.jobId);
    fetch('?auto_log_clear=1',{method:'POST',body:fd}).then(()=>{
        showToast('لاگ پاک شد');
        apLoadLog();
    }).catch(()=>{});
}

function apLoadLog(){
    const m = $('apLogModal');
    if(!m || m.style.display === 'none') return;
    fetch('?auto_log='+encodeURIComponent(m.dataset.jobId)).then(r=>r.json()).then(d=>{
        const b = $('apLogBody'); if(!b) return;
        if(!d||!d.ok){ b.innerHTML = '<div style="color:#f87171">'+esc((d&&d.error)||'خطا')+'</div>'; return; }
        apRenderLog(b, d);
    }).catch(()=>{});
}

function apRenderLog(b, d){
    const j = d.job, s = d.stat, rows = d.entries||[];
    let h = '<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;margin-bottom:10px">'
        + '<b style="color:#e2e8f0;font-size:12px">'+esc(j.title)+'</b>'
        + '<div style="font-size:10px;color:#64748b;margin-top:4px;line-height:1.8">💬 '+esc(j.prompt)+'</div>'
        + '<div style="display:flex;gap:10px;flex-wrap:wrap;font-size:10px;color:#94a3b8;margin-top:6px">'
        +   '<span>📊 '+toFa(s.total)+' اجرا</span>'
        +   '<span style="color:#34d399">✅ '+toFa(s.ok)+'</span>'
        +   '<span style="color:#f87171">❌ '+toFa(s.fail)+'</span>'
        +   '<span style="color:#facc15">✏️ '+toFa(s.changes)+' تغییر</span>'
        + '</div></div>';

    if(!rows.length){
        h += '<div style="background:#0f172a;border:1px dashed #334155;border-radius:8px;padding:14px;'
          +  'text-align:center;color:#64748b;font-size:10.5px">هنوز اجرایی ثبت نشده است.</div>';
        b.innerHTML = h; return;
    }

    rows.forEach(function(e){
        const dt = new Date(e.t*1000);
        const when = toFa(dt.getHours())+':'+toFa(('0'+dt.getMinutes()).slice(-2))
                   + ' — ' + toFa(dt.getDate())+'/'+toFa(dt.getMonth()+1);
        h += '<div style="background:#0f172a;border:1px solid '+(e.ok?'#1e3a2f':'#3f1d1d')+';'
          +  'border-radius:8px;padding:8px;margin-bottom:5px">'
          +  '<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:4px">'
          +    '<span style="font-size:11px;color:'+(e.ok?'#34d399':'#f87171')+';font-weight:700">'
          +      (e.ok?'✅ موفق':'❌ ناموفق')+'</span>'
          +    (e.manual?'<span style="font-size:9px;color:#c084fc;background:#2e1065;padding:1px 5px;border-radius:4px">دستی</span>':'')
          +    '<span style="font-size:9px;color:#64748b;background:#111c31;padding:1px 5px;border-radius:4px">'+esc(e.mode||'')+'</span>'
          +    '<span style="margin-right:auto;font-size:9.5px;color:#64748b">🕒 '+when+'</span>'
          +  '</div>'
          +  '<div style="display:flex;gap:8px;flex-wrap:wrap;font-size:9.5px;color:#64748b;margin-bottom:4px">'
          +    '<span>🔧 '+toFa(e.calls||0)+' فراخوانی</span>'
          +    '<span>✏️ '+toFa(e.changes||0)+' تغییر</span>'
          +    (e.applied?'<span style="color:#facc15">🔥 '+toFa(e.applied)+' واقعی</span>':'')
          +    '<span>⏱ '+toFa(e.took||0)+' ثانیه</span>'
          +  '</div>';
        if(e.summary) h += '<div style="font-size:10.5px;color:#cbd5e1;line-height:1.9;background:#111c31;'
                        +  'border-radius:5px;padding:5px 7px">'+esc(e.summary)+'</div>';
        if(e.error)   h += '<div style="font-size:10px;color:#fca5a5;line-height:1.8;background:#1f1414;'
                        +  'border-radius:5px;padding:5px 7px">⚠️ '+esc(e.error)+'</div>';
        if(e.detail && e.detail.length){
            h += '<div style="margin-top:5px;font-size:9.5px;color:#94a3b8">';
            e.detail.forEach(function(c){
                const bits = [];
                if(c.price !== null && c.price !== undefined) bits.push('قیمت: '+toFa(c.price));
                if(c.stock !== null && c.stock !== undefined) bits.push('موجودی: '+toFa(c.stock));
                h += '<div style="padding:2px 0;border-top:1px solid #1e293b">'
                  +  '• '+esc(String(c.target||''))+' #'+toFa(c.id||'')+' — '+esc(bits.join(' · '))
                  +  (c.applied?' <span style="color:#34d399">اعمال شد</span>':' <span style="color:#64748b">شبیه‌سازی</span>')
                  +  (c.reason?' <span style="color:#64748b">('+esc(c.reason)+')</span>':'')
                  +  '</div>';
            });
            h += '</div>';
        }
        h += '</div>';
    });
    b.innerHTML = h;
}

/** وضعیتِ کران را نشان می‌دهد تا کاربر بفهمد کارها اصلاً اجرا می‌شوند یا نه */
function apCronState(){
    const el = $('apCronState'); if(!el) return;
    fetch('?cron_last').then(r=>r.json()).then(d=>{
        if(!d || !d.at){
            el.innerHTML = '<span style="color:#f87171">⚠️ هنوز هیچ اجرای کرانی ثبت نشده — '
                + 'تا کران فعال نشود کارها خودکار اجرا نمی‌شوند</span>';
            return;
        }
        const ago = Math.max(0, Math.floor(Date.now()/1000) - d.at);
        const txt = ago < 3600 ? (toFa(Math.floor(ago/60))+' دقیقه پیش')
                  : ago < 86400 ? (toFa(Math.floor(ago/3600))+' ساعت پیش')
                  : (toFa(Math.floor(ago/86400))+' روز پیش');
        const stale = ago > 7200;
        el.innerHTML = '<span style="color:'+(stale?'#facc15':'#34d399')+'">'
            + (stale?'⚠️':'✅')+' آخرین اجرای کران: '+txt+'</span>';
    }).catch(function(){
        el.innerHTML = '<span style="color:#64748b">وضعیتِ کران نامشخص</span>';
    });
}
function updateAiNetBadge(){
    const el=$('aiS'),m=($('aiNetMode')||{}).value||'direct';
    if(!el)return;
    if(el.textContent==='✓'||el.textContent==='✗')return;   // نتیجهٔ تست را پاک نکن
    const names={direct:'مستقیم',doh:'DoH',dns:'IP دستی',worker:'Worker',gateway:'درگاه',proxy:'پروکسی'};
    el.textContent=names[m]||m;
}
function getAiNet(){
    return {
        mode:($('aiNetMode')||{}).value||'direct',
        resolve_ip:(($('aiNetResolveIp')||{}).value||'').trim(),
        doh_url:($('aiNetDohUrl')||{}).value||'https://cloudflare-dns.com/dns-query',
        worker_url:(($('aiNetWorkerUrl')||{}).value||'').trim(),
        proxy:(($('aiNetProxyUrl')||{}).value||'').trim(),
        proxy_type:($('aiNetProxyType')||{}).value||'http',
        proxy_auth:(($('aiNetProxyAuth')||{}).value||'').trim(),
        timeout:parseInt(($('aiNetTimeout')||{}).value)||25,
        ipv4:1,
        fallback:($('aiNetFallback')||{}).checked?1:0
    };
}
function applyAiNet(n){
    n=n||{};
    if($('aiNetMode'))$('aiNetMode').value=n.mode||'direct';
    if($('aiNetResolveIp'))$('aiNetResolveIp').value=n.resolve_ip||'';
    if($('aiNetDohUrl')&&n.doh_url)$('aiNetDohUrl').value=n.doh_url;
    if($('aiNetWorkerUrl'))$('aiNetWorkerUrl').value=n.worker_url||'';
    if($('aiNetProxyUrl'))$('aiNetProxyUrl').value=n.proxy||'';
    if($('aiNetProxyType'))$('aiNetProxyType').value=n.proxy_type||'http';
    if($('aiNetProxyAuth'))$('aiNetProxyAuth').value=n.proxy_auth||'';
    if($('aiNetTimeout'))$('aiNetTimeout').value=n.timeout||25;
    if($('aiNetFallback'))$('aiNetFallback').checked=!!n.fallback;
    aiNetToggle();
}
/* عیب‌یابی: همهٔ روش‌ها را می‌سنجد و می‌گوید کدام کار می‌کند */
function aiProbe(){
    const r=$('aiTR');
    r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">🩺 در حال سنجش روش‌ها... (تا یک دقیقه)</div>';
    const n=getAiNet();
    // v9.27: base_url دیگر از فیلد حذف‌شده فرستاده نمی‌شود؛ سمت سرور از ارائه‌دهندهٔ فعال می‌گیرد
    const q=new URLSearchParams({ai_probe:'1',
        net_mode:n.mode,net_resolve_ip:n.resolve_ip,net_doh_url:n.doh_url,
        net_worker_url:n.worker_url,net_proxy:n.proxy,net_proxy_type:n.proxy_type,net_proxy_auth:n.proxy_auth});
    fetch('?'+q.toString()).then(x=>x.json()).then(d=>{
        if(!d.ok){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
        let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px;line-height:2">';
        h+='<div style="color:#67e8f9;font-weight:700;margin-bottom:6px">🩺 نتیجهٔ عیب‌یابی — '+esc(d.host||'')+'</div>';
        if(d.provider_name)h+='<div style="color:#94a3b8;margin-bottom:6px">ارائه‌دهنده: '+esc(d.provider_name)+' · مدل: <span dir="ltr">'+esc(d.model||'')+'</span></div>';
        (d.steps||[]).forEach(st=>{
            h+='<div>'+(st.ok?'🟢':'🔴')+' '+esc(st.name)+' — <span style="color:#94a3b8">'+esc(st.detail||'')+'</span>'
              +(st.ms!==undefined?' <span style="color:#64748b">('+toFa(st.ms)+'ms)</span>':'')+'</div>';
        });
        if((d.modes||[]).length){
            h+='<div style="color:#fbbf24;font-weight:700;margin:8px 0 4px">روش‌های عبور:</div>';
            const names={direct:'مستقیم',doh:'DoH',dns:'IP دستی',worker:'Worker',gateway:'درگاه',proxy:'پروکسی'};
            d.modes.forEach(m=>{
                h+='<div>'+(m.reached?'🟢':'🔴')+' <b>'+esc(names[m.mode]||m.mode)+'</b> — '+esc(m.note||'')
                  +' <span style="color:#64748b">('+toFa(m.ms)+'ms)</span></div>';
            });
        }
        h+='<div style="margin-top:8px;padding-top:6px;border-top:1px solid #334155;color:'+((d.working||[]).length?'#4ade80':'#fca5a5')+'">'+esc(d.summary||'')+'</div>';
        if(d.recommended){
            h+='<button class="btn btn-green" style="margin-top:8px;font-size:11px;padding:5px 10px" onclick="aiUseMode(\''+d.recommended+'\')">✓ استفاده از روش پیشنهادی</button>';
        }
        h+='</div>';
        r.innerHTML=h;
    }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function aiUseMode(m){
    if($('aiNetMode')){$('aiNetMode').value=m;aiNetToggle();}
    saveConn();
    showToast('✓ روش «'+m+'» انتخاب و ذخیره شد');
}
/* کد آمادهٔ Cloudflare Worker — کاربر کپی می‌کند و در حساب رایگان خودش می‌گذارد */
function aiShowWorkerCode(){
    const code=[
"// Cloudflare Worker — واسط رساندن درخواست به سرویس هوش مصنوعی",
"// ۱) وارد dash.cloudflare.com شوید → Workers → Create Worker",
"// ۲) این کد را جایگزین کنید → Deploy",
"// ۳) آدرس xxx.workers.dev را در تنظیمات این برنامه بگذارید",
"export default {",
"  async fetch(request) {",
"    const cors = {",
"      'Access-Control-Allow-Origin': '*',",
"      'Access-Control-Allow-Headers': '*',",
"      'Access-Control-Allow-Methods': 'GET,POST,OPTIONS'",
"    };",
"    if (request.method === 'OPTIONS') return new Response(null, { headers: cors });",
"",
"    // آدرس مقصد: از هدر X-Target-URL یا از مسیر بعد از /",
"    let target = request.headers.get('X-Target-URL');",
"    if (!target) {",
"      const u = new URL(request.url);",
"      target = u.pathname.slice(1) + u.search;",
"      if (target.startsWith('https:/') && !target.startsWith('https://'))",
"        target = target.replace('https:/', 'https://');",
"      if (target.startsWith('http:/') && !target.startsWith('http://'))",
"        target = target.replace('http:/', 'http://');",
"    }",
"    if (!/^https?:\\/\\//.test(target))",
"      return new Response('bad target', { status: 400, headers: cors });",
"",
"    const h = new Headers(request.headers);",
"    h.delete('X-Target-URL');",
"    h.delete('Host');",
"",
"    const resp = await fetch(target, {",
"      method: request.method,",
"      headers: h,",
"      body: ['GET','HEAD'].includes(request.method) ? undefined : await request.arrayBuffer()",
"    });",
"    const out = new Headers(resp.headers);",
"    Object.entries(cors).forEach(([k,v]) => out.set(k,v));",
"    return new Response(resp.body, { status: resp.status, headers: out });",
"  }",
"};"
    ].join('\n');
    const r=$('aiTR');
    r.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px">'
      +'<div style="color:#67e8f9;font-weight:700;font-size:11px;margin-bottom:6px">📄 کد Cloudflare Worker</div>'
      +'<textarea id="aiWorkerCode" readonly style="width:100%;height:220px;font-family:ui-monospace,monospace;font-size:10px;direction:ltr;text-align:left;background:#111c31;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:8px"></textarea>'
      +'<button class="btn btn-cyan" style="margin-top:6px;font-size:11px;padding:5px 10px" onclick="aiCopyWorkerCode()">📋 کپی</button>'
      +'<div style="font-size:10px;color:#64748b;margin-top:6px;line-height:1.8">حساب رایگان Cloudflare روزانه ۱۰۰٬۰۰۰ درخواست می‌دهد که برای این کار کافی است.</div>'
      +'</div>';
    $('aiWorkerCode').value=code;
}
function aiCopyWorkerCode(){
    const t=$('aiWorkerCode');if(!t)return;
    t.select();
    try{document.execCommand('copy');showToast('✓ کد کپی شد');}
    catch(e){if(navigator.clipboard){navigator.clipboard.writeText(t.value);showToast('✓ کد کپی شد');}}
}
function testAi(){const s=$('aiS'),r=$('aiTR');const pid=$('aiProviderSel')?$('aiProviderSel').value:'',mid=$('aiModelSel')?$('aiModelSel').value:'';if(!pid||!mid){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ ابتدا یک ارائه‌دهنده و مدل فعال انتخاب کنید</div>';return;}s.textContent='تست...';s.className='cst tg';r.innerHTML='';const fd=new FormData();fd.append('action','test_ai');fd.append('provider_id',pid);fd.append('model_id',mid);const _n=getAiNet();fd.append('net_mode',_n.mode);fd.append('net_resolve_ip',_n.resolve_ip);fd.append('net_doh_url',_n.doh_url);fd.append('net_worker_url',_n.worker_url);fd.append('net_proxy',_n.proxy);fd.append('net_proxy_type',_n.proxy_type);fd.append('net_proxy_auth',_n.proxy_auth);fd.append('net_fallback',_n.fallback);fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{if(d.ok){s.textContent='✓';s.className='cst on';r.innerHTML='<div class="alert alert-success" style="padding:8px;font-size:11px">✓ '+esc(d.message)+' | مدل: '+esc(d.model)+' | پاسخ: '+esc(d.response||'')+(d.via?' | مسیر: <b>'+esc(d.via)+'</b>':'')+'</div>';aiTestOne(pid,mid);}else{s.textContent='✗';s.className='cst off';let _t='';if(d.tried&&d.tried.length>1){_t='<div style="margin-top:4px;font-size:10px;color:#fca5a5">تلاش‌ها: '+d.tried.map(x=>esc(x.mode)+'='+(x.code||'✗')).join(' · ')+'</div>';}
r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+_t+(d.cf_detail?'<div style="margin-top:4px;font-size:10px;color:#fbbf24;direction:ltr;text-align:left">'+esc(d.cf_detail)+'</div>':'')+'<div style="margin-top:6px"><button class="btn btn-orange" style="font-size:10px;padding:4px 8px" onclick="aiProbe()">🩺 عیب‌یابی روش‌ها</button></div></div>';}}).catch(()=>{s.textContent='✗';s.className='cst off';});}
/* ============ v9.20: مدیریت چند-ارائه‌دهندهٔ هوش مصنوعی ============ */
let aiProvData={providers:[],selected:{provider:'',model:''}};
function aiLoadProviders(){fetch('?ai_providers_status=1').then(r=>r.json()).then(d=>{if(d&&d.ok){aiProvData=d;aiRenderProviders();}else{if(d&&d.error)showToast('خطا: '+d.error,1);}}).catch(()=>{});aiCandRender();}
/* ============ v9.38: مدل‌های کاندید + مدل مستر + پایگاه رای ============ */
var aiCandData=null;
var aiCandCtx={task:'category',input:'',keys:[],items:[]};
function aiCandLoad(cb){
  fetch('?ai_candidates=1').then(r=>r.json()).then(d=>{aiCandData=d||{candidates:[],master:'',pin:'',history:[]};if(cb)cb(aiCandData);}).catch(()=>{});
}
function aiCandSave(addKey,removeKey,isPin,removeKeys){
  fetch('?ai_candidates=1').then(r=>r.json()).then(d=>{
    let list=((d&&d.candidates)||[]).map(c=>({provider:c.provider,model:c.model}));
    if(addKey){
      const i=addKey.indexOf('::');
      if(i>0){const pp=addKey.slice(0,i),mm=addKey.slice(i+2);if(!list.find(x=>x.provider===pp&&x.model===mm))list.push({provider:pp,model:mm});}
    }
    const rmKeys=removeKeys&&removeKeys.length?removeKeys:(removeKey?[removeKey]:[]);
    if(rmKeys.length){
      const rmSet=new Set(rmKeys);
      list=list.filter(x=>!rmSet.has(x.provider+'::'+x.model));
    }
    const fd=new FormData();
    fd.append('action','ai_candidates_save');
    fd.append('candidates',JSON.stringify(list));
    if(isPin)fd.append('pin',($('aiMasterPin')||{}).value||'');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(res=>{
      if(res&&res.ok){showToast(isPin?'✓ مدل مستر ثبت شد':'✓ کاندیدها ذخیره شد');aiCandRender();}
      else showToast('خطا: '+((res&&res.error)||'نامشخص'),true);
    }).catch(()=>showToast('خطا در ارتباط',true));
  }).catch(()=>showToast('خطا در ارتباط',true));
}
function aiCandAddFromSel(){
  const pid=($('aiProviderSel')||{}).value||'';
  const mid=($('aiModelSel')||{}).value||'';
  if(!pid||!mid){showToast('اول از بالای همین بخش یک ارائه‌دهنده و مدل فعال انتخاب کنید',1);return;}
  aiCandSave(pid+'::'+mid,null,false);
}
/* v9.55: همهٔ مدل‌هایی که تیک سبز (available/در دسترس) گرفته‌اند را یک‌جا
   به فهرست کاندیدها اضافه می‌کند. */
function aiCandAddAvailable(){
  const add=[];
  ((aiProvData&&aiProvData.providers)||[]).forEach(p=>{
    (p.models||[]).forEach(m=>{
      if(m&&m.available && m.id && p.id) add.push(p.id+'::'+m.id);
    });
  });
  if(!add.length){showToast('هیچ مدلِ در دسترسی نیست — اول مدل‌ها را تست کنید',1);return;}
  fetch('?ai_candidates=1').then(r=>r.json()).then(d=>{
    let list=((d&&d.candidates)||[]).map(c=>({provider:c.provider,model:c.model}));
    let added=0;
    add.forEach(k=>{
      const i=k.indexOf('::');
      if(i<=0)return;
      const pp=k.slice(0,i), mm=k.slice(i+2);
      if(!list.find(x=>x.provider===pp&&x.model===mm)){list.push({provider:pp,model:mm});added++;}
    });
    if(!added){showToast('همهٔ مدل‌های در دسترس از قبل کاندید هستند',0);return;}
    const fd=new FormData();
    fd.append('action','ai_candidates_save');
    fd.append('candidates',JSON.stringify(list));
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(res=>{
      showToast(res&&res.ok?('✓ '+added+' مدلِ در دسترس به کاندیدها اضافه شد'):('خطا: '+((res&&res.error)||'نامشخص')),!(res&&res.ok));
      aiCandRender();
    }).catch(()=>showToast('خطا در ارتباط',1));
  }).catch(()=>showToast('خطا در ارتباط',1));
}
/* v9.38: دراپ‌داون‌های اختصاصی افزودن کاندید (ارائه‌دهنده + مدل) */
function aiCandFillSel(){
  const ps=$('aiCandProvSel'); if(!ps)return;
  const cur=ps.value||((aiProvData&&aiProvData.selected&&aiProvData.selected.provider)||'');
  ps.innerHTML='<option value="">— انتخاب —</option>';
  ((aiProvData&&aiProvData.providers)||[]).forEach(p=>{
    const n=(p.models||[]).length;
    ps.add(new Option(esc(p.name)+(n?' ('+toFa(n)+' مدل)':''),esc(p.id)));
  });
  if(cur&&[...ps.options].some(o=>o.value===cur))ps.value=cur;
  aiCandFillModels();
}
function aiCandFillModels(){
  const ms=$('aiCandModelSel'); if(!ms)return;
  const pid=($('aiCandProvSel')||{}).value||'';
  const p=((aiProvData&&aiProvData.providers)||[]).find(x=>x.id===pid);
  ms.innerHTML='<option value="">—</option>';
  if(!p)return;
  (p.models||[]).forEach(m=>ms.add(new Option(esc(m.name||m.id),esc(m.id))));
  // مدل فعالِ همین ارائه‌دهنده را پیش‌فرض بگذار
  if(aiProvData&&aiProvData.selected&&aiProvData.selected.provider===pid&&aiProvData.selected.model)
    ms.value=aiProvData.selected.model;
}
function aiCandProvChange(){aiCandFillModels();}
function aiCandAddSel(){
  const pid=($('aiCandProvSel')||{}).value||'';
  const mid=($('aiCandModelSel')||{}).value||'';
  if(!pid||!mid){showToast('ارائه‌دهنده و مدل کاندید را انتخاب کنید',1);return;}
  aiCandSave(pid+'::'+mid,null,false);
}
function aiCandRemove(key){if(confirm('این مدل از کاندیدها حذف شود؟'))aiCandSave(null,key,false);}
function aiCandSetPin(){aiCandSave(null,null,true);}
/* v9.55: تیک زدن/برداشتن همهٔ کاندیدها + حذف کاندیدهایِ تیک‌خورده */
let aiCandSelectedKeys=new Set();
function aiCandToggleSelAll(checked){
  aiCandSelectedKeys.clear();
  const rows=document.querySelectorAll('.aiCandRow');
  rows.forEach(r=>{
    const key=r.getAttribute('data-key');
    const cb=r.querySelector('.aiCandCb');
    if(!key||!cb)return;
    cb.checked=checked;
    if(checked)aiCandSelectedKeys.add(key);
  });
  aiCandUpdateSelUI();
}
function aiCandRowCheck(cb,key){
  if(!key)return;
  if(cb.checked)aiCandSelectedKeys.add(key); else aiCandSelectedKeys.delete(key);
  const all=$('aiCandSelAll');
  const rows=document.querySelectorAll('.aiCandRow');
  if(all){all.checked=aiCandSelectedKeys.size>0&&aiCandSelectedKeys.size===rows.length;}
  aiCandUpdateSelUI();
}
function aiCandUpdateSelUI(){
  const cnt=$('aiCandSelCount');
  if(cnt)cnt.textContent=toFa(aiCandSelectedKeys.size)+' انتخاب';
}
function aiCandRemoveSelected(){
  if(!aiCandSelectedKeys.size){showToast('هیچ کاندیدی انتخاب نشده',1);return;}
  const keys=[...aiCandSelectedKeys];
  if(!confirm(keys.length+' کاندید انتخاب‌شده حذف شود؟'))return;
  aiCandSave(null,null,false,keys);
}
function aiCandRender(){
  aiCandLoad(d=>{
    aiCandFillSel();
    const box=$('aiCandList'); if(!box)return;
    const c=d.candidates||[];
    aiCandSelectedKeys.clear();
    if(!c.length){box.innerHTML='<div style="padding:8px;color:#64748b;font-size:11px">کاندیدی نیست — مدل فعال را انتخاب و «➕ افزودن» بزنید.</div>';}
    else{
      let h='';
      c.forEach(x=>{
        const isM=(x.key===d.master);
        h+='<div class="aiCandRow" data-key="'+esc(x.key)+'" style="display:flex;gap:6px;align-items:center;padding:6px 8px;border-bottom:1px solid #1e293b;font-size:11px">'
          +'<input type="checkbox" class="aiCandCb" style="width:14px;height:14px;flex:0 0 auto" onchange="aiCandRowCheck(this,\''+esc(x.key)+'\')">'
          +'<span style="flex:1;color:'+(isM?'#4ade80':'#e2e8f0')+'">'+esc(x.providerName)+' · <span dir="ltr">'+esc(x.modelName||x.model)+'</span>'
          +(isM?' <span style="color:#fbbf24;font-size:9px">⭐ مستر</span>':'')
          +'<span style="color:#64748b;font-size:9px"> | '+(x.votes?('🏅 '+toFa(x.wins)+'/'+toFa(x.votes)+' ('+Math.round(x.score*100)+'٪)'):'بدون رای')+'</span></span>'
          +'<button class="btn btn-red" onclick="aiCandRemove(\''+esc(x.key)+'\')" style="font-size:10px;padding:2px 6px">🗑</button></div>';
      });
      box.innerHTML=h;
    }
    const all=$('aiCandSelAll'); if(all)all.checked=false;
    aiCandUpdateSelUI();
    const ms=$('aiMasterPin');
    if(ms){
      let o='<option value="">خودکار (بهترین آمار)</option>';
      c.forEach(x=>{o+='<option value="'+esc(x.key)+'"'+(d.pin===x.key?' selected':'')+'>'+esc(x.providerName+' / '+(x.modelName||x.model))+'</option>';});
      ms.innerHTML=o;
    }
    const mi=$('aiMasterInfo');
    if(mi){
      if(d.master){
        const m=c.find(x=>x.key===d.master);
        mi.innerHTML='⭐ مدل مستر: <b>'+esc(m?(m.providerName+' / '+(m.modelName||m.model)):d.master)+'</b>'
          +(d.pin?' (سنجاق دستی)':' — به‌صورت خودکار از بهترین آمار')
          +' — در آزمون‌ها، پاسخِ مستر به‌عنوان مرجعِ مقایسه نشان داده می‌شود.';
      }else{mi.innerHTML='هنوز مستری نیست — با آزمون‌ها به‌صورت خودکار مشخص می‌شود.';}
    }
  });
}
function aiCandVote(task,idx){
  const it=(aiCandCtx.items||[])[idx];
  if(!it)return;
  const fd=new FormData();
  fd.append('action','ai_vote');
  fd.append('task',task);
  fd.append('input',aiCandCtx.input||'');
  fd.append('winner',it.key);
  fd.append('candidates',JSON.stringify(aiCandCtx.keys||[]));
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    showToast(d&&d.ok?('✓ رأی ثبت شد — مستر: '+((d.master||'').split('::')[1]||d.master||'?')):('خطا: '+((d&&d.error)||'نامشخص')),!d||!d.ok);
    if(d&&d.ok)aiCandRender();
  }).catch(()=>showToast('خطا در ثبت رأی',true));
}
/* v9.49: نتیجهٔ «تست دستهٔ همهٔ کاندیدها» حالا در یک مودال نشان داده می‌شود
   (نه داخل همان بخش که در موبایل جایی نداشت). برگزیدنِ هر پاسخ هم رأیِ مدل
   مستر را ثبت می‌کند و هم دسته را در حافظهٔ یادگیری می‌نشاند. */
function aiCandCategoryTest(){
  let m=document.getElementById('aiCandCatModal');if(m)m.remove();
  m=document.createElement('div');m.id='aiCandCatModal';m.className='bsl-modal-overlay';
  m.innerHTML='<div class="bsl-modal" style="width:880px">'
    +'<div class="bsl-modal-head"><h2>🏷️ تست دسته‌بندی همهٔ کاندیدها</h2>'
    +'<button class="btn btn-gray" onclick="aiCandCatClose()" style="font-size:11px;padding:4px 9px">✕</button></div>'
    +'<div style="padding:10px 14px;background:#1e293b;border-bottom:1px solid #334155;display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
    +'<input type="text" id="aiCandCatInput" placeholder="عنوان محصول را بنویسید... (مثلاً: کفش ورزشی مردانه)" '
    +'onkeydown="if(event.key===\'Enter\')aiCandCatRun()" style="flex:1;min-width:220px;background:#0f172a;color:#e2e8f0;border:1px solid #334155;border-radius:8px;padding:9px 12px;font-size:13px;direction:rtl">'
    +'<button class="btn btn-green" onclick="aiCandCatRun()" style="font-size:12px;padding:9px 16px">➤ مقایسه</button></div>'
    +'<div class="bsl-modal-body" id="aiCandCatBody" style="min-height:300px;max-height:62vh;overflow:auto;padding:12px"></div></div>';
  m.addEventListener('click',function(e){if(e.target===m)aiCandCatClose();});
  document.body.appendChild(m);
  setTimeout(()=>{const i=$('aiCandCatInput');if(i)i.focus();},50);
}
function aiCandCatClose(){const m=document.getElementById('aiCandCatModal');if(m)m.remove();}
function aiCandCatRun(){
  const inp=$('aiCandCatInput');const title=(inp?inp.value:'').trim();if(!title){if(inp)inp.focus();return;}
  const body=$('aiCandCatBody'); if(!body)return;
  body.innerHTML='<div style="color:#93c5fd;font-size:11px">🔄 در حال تحلیل «'+esc(title)+'» با همهٔ کاندیدها...</div>';
  fetch('?ai_candidates_category=1&title='+encodeURIComponent(title)).then(rr=>rr.json()).then(d=>{
    if(!body)return;
    if(!d||!d.ok){body.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc((d&&d.error)||'خطا')+'</div>';return;}
    const items=d.items||[];
    aiCandCtx={task:'category',input:title,keys:items.map(x=>x.key),items:items};
    let h='<div style="color:#67e8f9;font-weight:700;font-size:12px;margin-bottom:6px">🏷️ دسته‌بندی «'+esc(d.title)+'» توسط '+toFa(items.length)+' کاندید</div>'
      +'<div style="color:#94a3b8;font-size:10px;margin-bottom:8px">پاسخی که دسته‌اش درست‌تر بود را «برگزیدن + یادگیری» بزنید؛ هم رأیِ مستر ثبت می‌شود و هم این دسته برای محصولات هم‌کلمه آموخته می‌شود.</div>';
    items.forEach((it,idx)=>{
      const isM=(it.key===d.master);
      h+='<div style="border:1px solid '+(isM?'#fbbf24':'#334155')+';border-radius:8px;padding:7px;margin-bottom:6px;background:#111c31">'
        +'<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap">'
        +'<span style="color:'+(isM?'#fbbf24':'#e2e8f0')+';font-weight:700">'+(idx+1)+'. '+esc(it.providerName)+(isM?' <span style="color:#fbbf24;font-size:9px">⭐ مستر</span>':'')+'</span>'
        +'<span style="color:#64748b;font-size:9px" dir="ltr">'+esc(it.model)+' · '+toFa(it.latency||0)+'ms</span></div>'
        +'<div style="margin-top:4px">'+((it.ok&&it.category_name)
            ? '✅ دسته: <b style="color:#4ade80">'+esc(it.category_name)+'</b> (#'+it.category_id+')'
            : '<span style="color:#f87171">✗ '+(it.error||'پاسخ نامعتبر')+'</span>')+'</div>'
        +(it.ai_text?'<div style="color:#94a3b8;font-size:10px;direction:ltr;text-align:left;white-space:pre-wrap;margin-top:3px">'+esc(it.ai_text)+'</div>':'')
        +'<button class="btn btn-green" style="margin-top:6px;font-size:10px;padding:3px 10px" onclick="aiCandCatVote('+idx+')">✓ برگزیدن + یادگیری</button>'
        +'</div>';
    });
    h+='<div style="color:#64748b;font-size:10px;margin-top:6px">⭐ = مدل مستر (مرجع مقایسه). انتخاب شما همان رایِ مستر را به‌روز می‌کند.</div>';
    body.innerHTML=h;
  }).catch(()=>{if(body)body.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا شبکه</div>';});
}
function aiCandCatVote(idx){
  const it=(aiCandCtx.items||[])[idx];
  if(!it){showToast('نتیجهٔ کاندید یافت نشد',1);return;}
  const fd=new FormData();
  fd.append('action','ai_vote');
  fd.append('task','category');
  fd.append('input',aiCandCtx.input||'');
  fd.append('winner',it.key);
  fd.append('candidates',JSON.stringify(aiCandCtx.keys||[]));
  fd.append('cat_id',String(it.category_id||0));
  fd.append('cat_name',it.category_name||'');
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    showToast(d&&d.ok?('✓ رأی ثبت شد — مستر: '+((d.master||'').split('::')[1]||d.master||'?')):('خطا: '+((d&&d.error)||'نامشخص')),!d||!d.ok);
    if(d&&d.ok)aiCandRender();
  }).catch(()=>showToast('خطا در ثبت رأی',true));
}
function aiCandReplyTest(){
  let m=document.getElementById('aiCandReplyModal');if(m)m.remove();
  m=document.createElement('div');m.id='aiCandReplyModal';m.className='bsl-modal-overlay';
  m.innerHTML='<div class="bsl-modal" style="width:860px">'
    +'<div class="bsl-modal-head"><h2>💬 تست پاسخ همهٔ کاندیدها</h2>'
    +'<button class="btn btn-gray" onclick="aiCandReplyClose()" style="font-size:11px;padding:4px 9px">✕</button></div>'
    +'<div style="padding:10px 14px;background:#1e293b;border-bottom:1px solid #334155;display:flex;gap:8px;align-items:center">'
    +'<input type="text" id="aiCandReplyInput" placeholder="پیام مشتری را بنویسید…" '
    +'onkeydown="if(event.key===\'Enter\')aiCandReplyRun()" style="flex:1;background:#0f172a;color:#e2e8f0;border:1px solid #334155;border-radius:8px;padding:9px 12px;font-size:13px">'
    +'<button class="btn btn-green" onclick="aiCandReplyRun()" style="font-size:12px;padding:9px 16px">➤ مقایسه</button></div>'
    +'<div class="bsl-modal-body" id="aiCandReplyBody" style="min-height:300px;max-height:60vh;overflow:auto;padding:12px"></div></div>';
  m.addEventListener('click',function(e){if(e.target===m)aiCandReplyClose();});
  document.body.appendChild(m);
  setTimeout(()=>{const i=$('aiCandReplyInput');if(i)i.focus();},50);
}
function aiCandReplyClose(){const m=document.getElementById('aiCandReplyModal');if(m)m.remove();}

/* ==================================================================
 *  v10.19 (۳۲): مدیر وظیفه — رابطِ کاربری
 *
 *  یک پنجرهٔ واحد که همهٔ کارهای پس‌زمینه را نشان می‌دهد و می‌گذارد
 *  متوقف/پاک/مرتب‌شان کنی. دو بخش دارد: «کارهای الان» (وضعیتِ زندهٔ
 *  ۱۰ کارِ رجیستری) و «کارهای زمان‌بندی‌شده» (صفِ ایجنتِ خودکار که
 *  ترتیبش واقعاً روی نوبتِ اجرا اثر دارد).
 *
 *  نکتهٔ طراحی: نبضِ دکمهٔ هدر مستقل از باز بودنِ پنجره کار می‌کند و
 *  کند (هر ۱۵ ثانیه) است؛ وقتی پنجره باز است تندتر (هر ۲.۵ ثانیه)
 *  می‌شود. هدف این است که پولینگِ دائمی روی هاستِ اشتراکی بار نیندازد
 *  ولی کاربر همیشه بداند چیزی در حال اجراست.
 * ================================================================== */
let tmTimer=null, tmPulseTimer=null, tmData=null, tmBusy=false, tmOnlyActive=false;

/** فاصلهٔ زمانی را خوانا می‌کند: «۴۲ ثانیه»، «۳ دقیقه»، «۲ ساعت» */
function tmAgo(sec){
  sec=Math.max(0,parseInt(sec)||0);
  if(sec<60)   return toFa(sec)+' ثانیه';
  if(sec<3600) return toFa(Math.floor(sec/60))+' دقیقه';
  if(sec<86400)return toFa(Math.floor(sec/3600))+' ساعت';
  return toFa(Math.floor(sec/86400))+' روز';
}

/** نبضِ دکمهٔ هدر — سبک‌ترین درخواستِ ممکن، فقط برای شمارشِ کارهای فعال */
function tmPulse(){
  fetch('?tasks_list=1').then(r=>r.json()).then(d=>{
    if(!d||!d.ok)return;
    tmData=d;
    tmPaintBtn(d);
    if(document.getElementById('tmModal')) tmRender();
  }).catch(()=>{});
}

/** ظاهرِ دکمه: سبزِ نبض‌دار = کاری در حال اجرا، نارنجی = کارِ رهاشده */
function tmPaintBtn(d){
  const b=document.getElementById('tasksBtn'), n=document.getElementById('tasksBadge');
  if(!b||!n)return;
  const run=parseInt(d.running)||0, st=parseInt(d.stale)||0;
  b.classList.toggle('busy', run>0);
  b.classList.toggle('warn', run===0 && st>0);
  n.textContent=toFa(run>0?run:st);
  if(n.style)n.style.display=(run>0||st>0)?'flex':'none';
  b.title = run>0 ? (toFa(run)+' کار در حال اجرا — مدیر وظیفه')
          : st>0  ? (toFa(st)+' کارِ رهاشده — مدیر وظیفه')
                  : 'مدیر وظیفه — کارهای پس‌زمینه';
  /* v10.20 (۳۳ج): زیرنویسِ دکمه هم خبر می‌دهد — تا حالا فقط رنگ و عدد بود
     و کاربر باید حدس می‌زد عددِ کنارِ 🗂 یعنی چه. */
  const sub=document.getElementById('tasksSub');
  if(sub) sub.textContent = run>0 ? (toFa(run)+' کار در حال اجرا')
                          : st>0  ? (toFa(st)+' کارِ رهاشده')
                                  : 'کارهای پس‌زمینه';
}

function tmOpen(){
  let m=document.getElementById('tmModal'); if(m){tmClose();return;}
  m=document.createElement('div'); m.id='tmModal'; m.className='bsl-modal-overlay';
  m.innerHTML='<div class="bsl-modal" style="width:900px;max-width:96vw">'
    +'<div class="bsl-modal-head"><h2>🗂 مدیر وظیفه</h2>'
    +'<div style="display:flex;gap:6px;align-items:center">'
    +'<label style="font-size:10px;color:#94a3b8;display:flex;gap:4px;align-items:center;cursor:pointer">'
    +'<input type="checkbox" id="tmOnlyActive" onchange="tmToggleFilter()"> فقط فعال‌ها</label>'
    +'<button class="btn btn-gray" onclick="tmClearAll()" style="font-size:10px;padding:4px 9px" title="پاک‌کردنِ ردِ همهٔ کارهای تمام‌شده">🧽 پاک‌سازی</button>'
    +'<button class="btn btn-gray" onclick="tmClose()" style="font-size:11px;padding:4px 9px">✕</button></div></div>'
    +'<div class="bsl-modal-body" id="tmBody" style="min-height:320px;max-height:72vh;overflow:auto;padding:12px">'
    +'<div style="color:#93c5fd;font-size:11px">⏳ در حال خواندنِ وضعیت…</div></div></div>';
  m.addEventListener('click',function(e){if(e.target===m)tmClose();});
  document.body.appendChild(m);
  document.body.classList.add('modal-open');
  const b=document.getElementById('tasksBtn'); if(b)b.classList.add('active');
  const c=document.getElementById('tmOnlyActive'); if(c)c.checked=tmOnlyActive;
  if(tmData)tmRender();
  tmPulse();
  if(tmTimer)clearInterval(tmTimer);
  tmTimer=setInterval(tmPulse,2500);
}

function tmClose(){
  const m=document.getElementById('tmModal'); if(m)m.remove();
  document.body.classList.remove('modal-open');
  const b=document.getElementById('tasksBtn'); if(b)b.classList.remove('active');
  if(tmTimer){clearInterval(tmTimer);tmTimer=null;}
}

function tmToggleFilter(){
  const c=document.getElementById('tmOnlyActive');
  tmOnlyActive=!!(c&&c.checked);
  tmRender();
}

/* ═══════════════════════════════════════════════════════════════════
 *  v10.23 (۳۶الف): پرشِ کلیکی از کارتِ مدیر وظیفه به خانهٔ همان کار
 *
 *  گزارشِ کاربر: «کلیک روی کارت هیچ کاری نمی‌کند». درست بود — فیلدِ tab
 *  فقط یک برچسبِ متنی بود و هیچ ناوبری‌ای پشتش نبود. حالا بک‌اند برای هر
 *  کار می‌گوید کجا باید برویم (pane/smenu/ai/el/open) و این تابع همان
 *  مسیر را طی می‌کند: تبِ اصلی ⇒ (در صورت لزوم) پنلِ تنظیمات و بازکردنِ
 *  آکاردئونِ مربوط ⇒ زیرتبِ هوش مصنوعی ⇒ بازکردنِ پنجرهٔ اصلی یا اسکرول
 *  و برجسته‌سازیِ عنصرِ هدف.
 * ═══════════════════════════════════════════════════════════════════ */

/** آکاردئونِ پنلِ تنظیمات را با تکه‌ای از عنوانش پیدا و باز می‌کند */
function tmOpenSmenu(titlePart){
  if(!titlePart)return null;
  const hdrs=document.querySelectorAll('#settingsPanel .smenu-hdr');
  for(let i=0;i<hdrs.length;i++){
    const h3=hdrs[i].querySelector('h3');
    if(!h3)continue;
    if(h3.textContent.indexOf(titlePart)>=0){
      if(!hdrs[i].classList.contains('open'))toggleSmenu(hdrs[i]);
      return hdrs[i];
    }
  }
  return null;
}

/** عنصر را وسطِ دید می‌آورد و چند لحظه برجسته می‌کند تا گم نشود.
 *  اسکرول از نگهبانِ softScrollIntoView رد می‌شود تا تنظیمِ «پرشِ خودکارِ
 *  صفحه» کاربر (که روی موبایل پیش‌فرض خاموش است) محترم بماند. */
function tmSpot(el){
  if(!el)return;
  softScrollIntoView(el,{behavior:'smooth',block:'center'});
  const old=el.style.boxShadow, oldT=el.style.transition;
  el.style.transition='box-shadow .25s';
  el.style.boxShadow='0 0 0 2px #22d3ee, 0 0 18px #22d3ee66';
  setTimeout(function(){el.style.boxShadow=old;el.style.transition=oldT;},2200);
}

/** پرش به خانهٔ یک کار */
function tmGo(key){
  const t=((tmData&&tmData.tasks)||[]).find(x=>x.key===key);
  if(!t){showToast('این کار پیدا نشد',1);return;}
  if(!t.pane&&!t.open){showToast('برای این کار پنجرهٔ اختصاصی ثبت نشده',1);return;}
  tmClose();
  if(t.pane==='settings'){
    const p=document.getElementById('settingsPanel');
    if(p&&!p.classList.contains('open'))toggleSettingsPanel();
  }else if(t.pane){
    /* اگر پنلِ تنظیمات باز مانده باشد روی تبِ اصلی می‌افتد و کاربر فکر
       می‌کند کلیک بی‌اثر بوده — پس اول بسته می‌شود. */
    const p=document.getElementById('settingsPanel');
    if(p&&p.classList.contains('open'))toggleSettingsPanel();
    switchMainTab(t.pane);
  }
  setTimeout(function(){
    if(t.smenu)tmOpenSmenu(t.smenu);
    if(t.ai&&typeof aiTab==='function')aiTab(t.ai);
    setTimeout(function(){
      if(t.open&&typeof window[t.open]==='function'){ try{ window[t.open](); }catch(e){} }
      if(t.el)tmSpot(document.getElementById(t.el));
      else if(t.smenu){const hd=tmOpenSmenu(t.smenu);if(hd)tmSpot(hd);}
    },260);
  },160);
}

/** کارتِ یک کارِ پس‌زمینه */
/* ═══════════════════════════════════════════════════════════════════════
   v10.37 (۵۰ب): وضعیتِ باز/بستهٔ کارت‌های مدیرِ وظیفه.

   جدولِ کارت‌ها هر ۲.۵ ثانیه کاملاً از نو ساخته می‌شود، پس وضعیتِ باز
   بودن نمی‌تواند داخلِ DOM بماند — با اولین به‌روزرسانی پاک می‌شد. اینجا
   بیرون از DOM نگه داشته می‌شود و tmCard در هر رندر از آن می‌پرسد.

   پیش‌فرض: همه بسته. عمداً هیچ کارتی — حتی «در حال اجرا» — خودکار باز
   نمی‌شود؛ خواستهٔ صریحِ کاربر «در ابتدا بسته» بود و باز شدنِ خودکارِ
   کارِ در حال اجرا دوباره همان دیوارِ بلند را می‌ساخت.
   ═══════════════════════════════════════════════════════════════════════ */
const tmOpenCards={};

function tmIsOpen(k){ return !!tmOpenCards[k]; }

function tmToggleCard(k){
  if(tmOpenCards[k]) delete tmOpenCards[k];
  else tmOpenCards[k]=1;
  tmRender();          // بازسازیِ فوری، بدونِ انتظار برای تیکِ بعدی
}

/* دکمهٔ جمعی: اگر حتی یکی باز است همه را ببند، وگرنه همه را باز کن */
function tmToggleAllCards(){
  const tasks=(tmData&&tmData.tasks)||[];
  const anyOpen=tasks.some(t=>tmIsOpen(t.key));
  Object.keys(tmOpenCards).forEach(k=>{delete tmOpenCards[k];});
  if(!anyOpen) tasks.forEach(t=>{tmOpenCards[t.key]=1;});
  tmRender();
}

function tmCard(t){
  const lbl={running:'در حال اجرا',stale:'رهاشده',done:'تمام‌شده',idle:'بی‌کار'}[t.state]||t.state;
  const cls={running:'run',stale:'stale',done:'done',idle:'idle'}[t.state]||'idle';
  const bcl={running:'tmb-run',stale:'tmb-stale',done:'tmb-done',idle:'tmb-idle'}[t.state]||'tmb-idle';
  /* v10.23 (۳۶الف): خودِ کارت کلیک‌پذیر است، ولی دکمه‌های داخلش نه — پس
     روی هر دکمه event.stopPropagation می‌گذاریم وگرنه «توقف» هم کاربر را
     از پنجره بیرون می‌برد. */
  const nav=!!(t.pane||t.open);
  /* v10.37 (۵۰ب): کارت کشویی است و پیش‌فرض بسته. تا v10.36 هر کارت کلِ
     جزئیاتش (نوارِ پیشرفت، آمار، هشدار، لاگ) را همیشه باز نشان می‌داد و
     با چند کارِ همزمان، پنجرهٔ مدیرِ وظیفه یک دیوارِ بلندِ اسکرول می‌شد.
     حالا فقط سربرگ دیده می‌شود و جزئیات با کلیک باز می‌شود. */
  const opened=tmIsOpen(t.key);
  /* v10.24 (۳۷الف): ستونِ اولویت در ابتدای کارت — همان الگویِ ▲▼ کارهای
     زمان‌بندی‌شده، ولی برای کارهای پس‌زمینه. رتبه هم کنارش نوشته می‌شود
     وگرنه کاربر نمی‌فهمد این دکمه‌ها چه چیزی را جابه‌جا می‌کنند. */
  const first=(t.rank<=1), last=!!(tmData&&t.rank>=((tmData.tasks||[]).length));
  /* کلیک روی سربرگ = باز/بستنِ همین کارت. تا v10.36 کلیکِ روی کارت کاربر
     را به تبِ دیگری می‌برد؛ حالا آن کار فقط با دکمهٔ صریحِ «پنجرهٔ اصلی»
     انجام می‌شود، وگرنه باز کردنِ یک کارت کاربر را از پنجره بیرون می‌انداخت. */
  let h='<div class="tmc '+cls+(opened?' open':'')+'" data-tmkey="'+jsAttr(t.key)+'">'
    +'<div class="tmc-head" onclick="tmToggleCard(\''+jsAttr(t.key)+'\')" style="cursor:pointer"'
    +' title="'+(opened?'کلیک: بستنِ جزئیات':'کلیک: نمایشِ جزئیاتِ این کار')+'">'
    +'<span class="tmchev" aria-hidden="true">'+(opened?'▾':'▸')+'</span>'
    +'<span class="tmord" onclick="event.stopPropagation()" style="margin-left:2px">'
    + '<button onclick="event.stopPropagation();tmOrder(\''+jsAttr(t.key)+'\',\'up\')" '+(first?'disabled':'')+' title="یک پله بالاتر — زودتر بازیابی می‌شود">▲</button>'
    + '<button onclick="event.stopPropagation();tmOrder(\''+jsAttr(t.key)+'\',\'down\')" '+(last?'disabled':'')+' title="یک پله پایین‌تر">▼</button></span>'
    +'<span class="tmrank" onclick="event.stopPropagation();tmOrder(\''+jsAttr(t.key)+'\',\'top\')" '
    + 'style="cursor:pointer" title="کلیک: بردن به ابتدای صف">'+toFa(t.rank||0)+'</span>'
    +'<span style="font-size:15px">'+esc(t.icon)+'</span>'
    +'<span class="tmc-t">'+esc(t.title)+'</span>'
    +'<span class="tmc-tab">'+esc(t.tab)+(nav?' ↗':'')+'</span>'
    +'<span class="tmc-badge '+bcl+'">'+esc(lbl)+'</span>';
  if(t.cancelled) h+='<span class="tmc-badge tmb-stale">لغو شده</span>';
  h+='<span style="flex:1"></span>';
  /* v10.25 (۳۸الف): دکمهٔ صریحِ «پنجرهٔ اصلی». تا v10.24 خودِ کارت کلیک‌پذیر
     بود، ولی چون هیچ نشانهٔ دیداریِ دکمه‌مانندی نداشت خیلی از کاربران اصلاً
     نمی‌دانستند می‌شود از اینجا به پنجرهٔ اورجینالِ کار پرید. حالا کنارِ
     «توقف/ادامه» یک دکمهٔ مستقل هست که دقیقاً همان tmGo را صدا می‌زند. */
  if(nav)
    h+='<button class="btn btn-blue" style="font-size:10px;padding:3px 10px" onclick="event.stopPropagation();tmGo(\''+jsAttr(t.key)+'\')" title="رفتن به تبِ «'+jsAttr(t.tab)+'» و بازکردنِ پنجرهٔ اصلیِ همین کار">↗ پنجرهٔ اصلی</button>';
  if(t.stoppable)
    h+='<button class="btn btn-red" style="font-size:10px;padding:3px 10px" onclick="event.stopPropagation();tmStop(\''+jsAttr(t.key)+'\')">⏹ توقف</button>';
  /* v10.23 (۳۶ج): «▶ ادامه» — همان اندپوینتِ شروعِ اصلیِ کار، با پارامترهای
     اجرای قبلی. برای کارِ رهاشده حیاتی است؛ برای کارِ تمام‌شده هم «اجرای
     دوباره» است. */
  if(t.resumable&&t.state!=='running'){
    const isStale=(t.state==='stale');
    h+='<button class="btn '+(isStale?'btn-green':'btn-gray')+'" style="font-size:10px;padding:3px 10px"'
      +' onclick="event.stopPropagation();tmResume(\''+jsAttr(t.key)+'\')"'
      +' title="'+(isStale?'قفل و ردِ کارِ گیرکرده پاک می‌شود و همان کار دوباره شروع می‌شود'
                          :'همین کار با تنظیماتِ اجرای قبلی دوباره اجرا می‌شود')+'">'
      +(isStale?'▶ ادامه':'▶ اجرای دوباره')+'</button>';
  }
  if(t.clearable)
    h+='<button class="btn btn-gray" style="font-size:10px;padding:3px 10px" onclick="event.stopPropagation();tmClear(\''+jsAttr(t.key)+'\')" title="حذفِ ردِ این کار">🗑 پاک</button>';
  h+='</div>';

  /* ── بدنهٔ کشویی ───────────────────────────────────────────────────
     وقتی بسته است اصلاً رندر نمی‌شود (نه اینکه فقط پنهان شود)، تا با ده‌ها
     کار، هر تیکِ ۲.۵ ثانیه‌ای گره‌های بی‌مصرف نسازد. اما یک خطِ خلاصه در
     سربرگ می‌ماند تا کاربر بدونِ باز کردن هم بداند کار کجاست. */
  if(!opened){
    const sum=[];
    if(t.phase) sum.push(esc(t.phase));
    if(t.total>0) sum.push(toFa(t.current)+' از '+toFa(t.total)+(t.percent>=0?' ('+toFa(t.percent)+'٪)':''));
    else if(t.current>0) sum.push(toFa(t.current));
    if(t.ts>0) sum.push(tmAgo(t.age)+' پیش');
    if(sum.length) h+='<div class="tmc-sum">'+sum.join(' · ')+'</div>';
    /* نوارِ پیشرفتِ باریک حتی در حالتِ بسته — «زنده بودن» مهم‌ترین چیزی
       است که کاربر با یک نگاه می‌خواهد بفهمد. */
    if(t.state==='running'||t.state==='stale'){
      if(t.percent>=0) h+='<div class="tmbar mini"><i style="width:'+t.percent+'%"></i></div>';
      else             h+='<div class="tmbar mini ind"><i></i></div>';
    }
    return h+'</div>';
  }

  h+='<div class="tmc-body">';

  /* خطِ توضیح: مرحله، پیشرفتِ عددی، آخرین به‌روزرسانی */
  const bits=[];
  if(t.phase) bits.push(esc(t.phase));
  if(t.total>0) bits.push(toFa(t.current)+' از '+toFa(t.total));
  if(t.ts>0) bits.push('آخرین خبر: '+tmAgo(t.age)+' پیش');
  if(bits.length) h+='<div style="font-size:10px;color:#94a3b8;margin-top:5px">'+bits.join(' · ')+'</div>';
  if(t.last) h+='<div style="font-size:10px;color:#64748b;margin-top:3px" dir="auto">↳ '+esc(t.last)+'</div>';

  /* نوارِ پیشرفت — percent = -1 یعنی «کل نامعلوم است» */
  if(t.state==='running'||t.state==='stale'){
    if(t.percent>=0) h+='<div class="tmbar"><i style="width:'+t.percent+'%"></i></div>';
    else             h+='<div class="tmbar ind"><i></i></div>';
  }
  if((t.stats||[]).length){
    h+='<div class="tmstat">';
    t.stats.forEach(x=>{h+='<span>'+esc(x.k)+' <b>'+toFa(x.v)+'</b></span>';});
    h+='</div>';
  }
  if(t.state==='stale')
    h+='<div style="font-size:10px;color:#fcd34d;margin-top:6px">⚠ این کار مدت‌هاست خبری نداده — احتمالاً پردازه‌اش وسطِ کار قطع شده. '
      +(t.resumable
        ? 'با «▶ ادامه» قفلش برداشته و همان کار دوباره شروع می‌شود؛ یا با «پاک» فقط ردش را ببرید.'
        : 'با «پاک» آزادش کنید تا بتوانید از تبِ خودش دوباره شروع کنید.')+'</div>';
  if((t.log||[]).length){
    if(t.key==='aicontent'){
      h+='<div class="tmlog" style="display:flex;flex-direction:column;gap:4px">';
      t.log.forEach(l=>{
        const s=String(l||'');
        const m=s.match(/🔎([\w-]+)/);
        if(m){
          h+='<button type="button" onclick="event.stopPropagation();aicontentShowItem(\''+jsAttr(m[1])+'\')" '
            +'style="text-align:right;background:#111c31;border:1px solid #334155;border-radius:6px;padding:5px 8px;color:#e2e8f0;font-size:10.5px;cursor:pointer">'
            +esc(s.replace(/\s·\s🔎[\w-]+/,''))+' <span style="color:#67e8f9">جزئیات</span></button>';
        } else h+='<div style="font-size:10.5px;color:#94a3b8">'+esc(s)+'</div>';
      });
      h+='</div>';
      h+='<button type="button" class="btn btn-blue" style="margin-top:8px;font-size:10px;padding:4px 10px" onclick="event.stopPropagation();aicontentOpen()">📋 صف کارت‌های محصول</button>';
    } else {
      h+='<div class="tmlog">'+t.log.map(l=>esc(l)).join('\n')+'</div>';
    }
  }
  return h+'</div></div>';   /* بستنِ .tmc-body و .tmc */
}

/** ردیفِ یک کارِ زمان‌بندی‌شده با دکمه‌های اولویت */
function tmJobRow(j,i,n){
  const first=(i===0), last=(i===n-1);
  const modeLbl={sim:'شبیه‌سازی',dry:'آزمایشی',live:'واقعی'}[j.mode]||j.mode||'';
  let h='<div class="tmrow'+(j.enabled?'':' off')+'">'
    +'<div class="tmord">'
    +'<button onclick="tmMove(\''+jsAttr(j.id)+'\',\'up\')" '+(first?'disabled':'')+' title="یک پله بالا">▲</button>'
    +'<button onclick="tmMove(\''+jsAttr(j.id)+'\',\'down\')" '+(last?'disabled':'')+' title="یک پله پایین">▼</button></div>'
    +'<div class="tmrank" title="نوبتِ اجرا">'+toFa(i+1)+'</div>'
    +'<div style="flex:1;min-width:0">'
    +'<div style="font-size:11.5px;color:'+(j.enabled?'#e2e8f0':'#64748b')+';font-weight:700">'+esc(j.title||j.id)+'</div>'
    +'<div style="font-size:9.5px;color:#64748b;margin-top:2px">'
    +esc(modeLbl)+' · '+(j.due?'<span style="color:#86efac">اکنون نوبتش است</span>':esc(j.next_label||''))
    +(parseInt(j.runs)>0?' · '+toFa(j.runs)+' اجرا':'')
    +(parseInt(j.fails)>0?' · <span style="color:#f87171">'+toFa(j.fails)+' خطا</span>':'')
    +'</div></div>'
    +'<button class="btn btn-gray" style="font-size:9px;padding:3px 8px" onclick="tmMove(\''+jsAttr(j.id)+'\',\'top\')" '+(first?'disabled':'')+' title="بردن به ابتدای صف">⤒ اول</button>'
    +'</div>';
  return h;
}

function tmRender(){
  const body=document.getElementById('tmBody'); if(!body||!tmData)return;
  const d=tmData;
  let tasks=(d.tasks||[]);
  if(tmOnlyActive) tasks=tasks.filter(t=>t.state==='running'||t.state==='stale');
  const run=parseInt(d.running)||0, st=parseInt(d.stale)||0;

  /* v10.24 (۳۷ج): چند کارِ گیرکرده معمولاً با هم می‌میرند (یک ری‌استارتِ
     هاست)، پس دکمهٔ جمعی کنارِ شمارندهٔ «رهاشده» می‌نشیند. */
  const staleResumable=(d.tasks||[]).filter(t=>t.state==='stale'&&t.resumable).length;
  let h='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">'
    +'<span class="tmc-badge '+(run>0?'tmb-run':'tmb-idle')+'">'+toFa(run)+' در حال اجرا</span>'
    +(st>0?'<span class="tmc-badge tmb-stale">'+toFa(st)+' رهاشده</span>':'')
    +'<span class="tmc-badge tmb-done">'+toFa((d.jobs||[]).length)+' کارِ زمان‌بندی‌شده</span>'
    +(staleResumable>0?'<button class="btn btn-green" style="font-size:10px;padding:3px 10px" '
      +'onclick="tmResumeAll()" title="همهٔ کارهای گیرکرده را به ترتیبِ اولویت دوباره شروع کن">'
      +'▶▶ ادامهٔ همه ('+toFa(staleResumable)+')</button>':'')
    +'<span style="flex:1"></span>'
    +'<span style="font-size:9.5px;color:#64748b;align-self:center">به‌روزرسانیِ خودکار هر ۲.۵ ثانیه</span></div>';

  // v10.37 (۵۰ب): برچسبِ دکمهٔ جمعی از وضعیتِ فعلی خوانده می‌شود
  const anyOpen=tasks.some(t=>tmIsOpen(t.key));
  h+='<div style="display:flex;align-items:center;gap:6px;margin:4px 0 3px">'
    +'<span style="font-size:11px;color:#67e8f9;font-weight:700">▸ کارهای پس‌زمینه — اولویت با ترتیبِ صف</span>'
    +'<span style="flex:1"></span>'
    +'<button class="btn btn-gray" style="font-size:9px;padding:2px 8px" onclick="tmToggleAllCards()" '
    +'title="'+(anyOpen?'بستنِ جزئیاتِ همهٔ کارت‌ها':'نمایشِ جزئیاتِ همهٔ کارت‌ها')+'">'
    +(anyOpen?'▴ بستنِ همه':'▾ بازکردنِ همه')+'</button>'
    +'<button class="btn btn-gray" style="font-size:9px;padding:2px 8px" onclick="tmOrderReset()" '
    +'title="بازگرداندنِ ترتیب به حالتِ پیش‌فرض">↩ ترتیبِ پیش‌فرض</button></div>'
    +'<div style="font-size:9.5px;color:#64748b;margin-bottom:7px">روی هر کارت کلیک کنید تا جزئیاتش باز شود. با ▲▼ ترتیب را بچینید؛ همین ترتیب در «ادامهٔ همه» و بازیابیِ خودکارِ کارهای گیرکرده هم رعایت می‌شود.</div>';
  if(!tasks.length) h+='<div style="color:#64748b;font-size:11px;padding:14px;text-align:center">'+(tmOnlyActive?'هیچ کارِ فعالی نیست.':'کاری ثبت نشده.')+'</div>';
  else tasks.forEach(t=>{h+=tmCard(t);});

  const jobs=d.jobs||[];
  h+='<div style="font-size:11px;color:#c084fc;font-weight:700;margin:14px 0 4px">▸ کارهای زمان‌بندی‌شده — اولویت با ترتیبِ صف</div>'
    +'<div style="font-size:9.5px;color:#64748b;margin-bottom:7px">در هر تیک فقط چند کارِ اولِ صف اجرا می‌شوند، پس کارِ بالاتر زودتر نوبت می‌گیرد.</div>';
  if(!jobs.length) h+='<div style="color:#64748b;font-size:11px;padding:12px;text-align:center">کارِ زمان‌بندی‌شده‌ای تعریف نشده.</div>';
  else jobs.forEach((j,i)=>{h+=tmJobRow(j,i,jobs.length);});

  body.innerHTML=h;
}

function tmStop(key){
  if(tmBusy)return; tmBusy=true;
  fetch('?tasks_stop=1&key='+encodeURIComponent(key)).then(r=>r.json()).then(d=>{
    tmBusy=false;
    if(d&&d.ok) showToast('⏹ درخواستِ توقف ثبت شد — کار پس از مرحلهٔ جاری می‌ایستد');
    else showToast('✗ '+((d&&d.error)||'توقف ناموفق'),true);
    tmPulse();
  }).catch(()=>{tmBusy=false;showToast('✗ خطا شبکه',true);});
}

/* v10.24 (۳۷الف): جابه‌جاییِ اولویتِ یک کارِ پس‌زمینه.
   ترتیب فوراً و بدونِ انتظار برای پاسخِ سرور روی صفحه اعمال می‌شود، وگرنه
   کاربر روی هاستِ کند دو بار پشتِ‌هم می‌زند و کار دو پله می‌پرد. */
function tmOrder(key,dir){
  if(tmBusy)return;
  if(tmData&&tmData.tasks){
    const arr=tmData.tasks, i=arr.findIndex(x=>x.key===key);
    if(i>=0){
      let to=i;
      if(dir==='up')to=Math.max(0,i-1);
      else if(dir==='down')to=Math.min(arr.length-1,i+1);
      else if(dir==='top')to=0;
      else if(dir==='bottom')to=arr.length-1;
      if(to!==i){
        const row=arr.splice(i,1)[0];
        arr.splice(to,0,row);
        arr.forEach((x,n)=>{x.rank=n+1;});
        tmRender();
      }
    }
  }
  tmBusy=true;
  fetch('?tasks_order=1&key='+encodeURIComponent(key)+'&dir='+encodeURIComponent(dir))
    .then(r=>r.json()).then(d=>{
      tmBusy=false;
      if(!d||!d.ok){showToast('✗ '+((d&&d.error)||'جابه‌جایی ناموفق'),true);tmPulse();}
    }).catch(()=>{tmBusy=false;showToast('✗ خطا شبکه',true);tmPulse();});
}

/* v10.24 (۳۷الف): بازگرداندنِ ترتیب به حالتِ پیش‌فرضِ رجیستری */
function tmOrderReset(){
  if(tmBusy)return;
  if(!confirm('ترتیبِ اولویتِ کارهای پس‌زمینه به حالتِ پیش‌فرض برگردد؟'))return;
  tmBusy=true;
  fetch('?tasks_order=1&dir=reset').then(r=>r.json()).then(d=>{
    tmBusy=false;
    if(d&&d.ok)showToast('↩ ترتیب به پیش‌فرض برگشت');
    tmPulse();
  }).catch(()=>{tmBusy=false;showToast('✗ خطا شبکه',true);});
}

/* v10.24 (۳۷ج): ادامهٔ همهٔ کارهای گیرکرده، به ترتیبِ اولویت */
function tmResumeAll(){
  if(tmBusy)return;
  const stale=((tmData&&tmData.tasks)||[]).filter(t=>t.state==='stale'&&t.resumable);
  if(!stale.length){showToast('کارِ رهاشده‌ای برای ادامه نیست');return;}
  if(!confirm(toFa(stale.length)+' کارِ گیرکرده به ترتیبِ اولویت دوباره شروع شوند؟\n'
     +stale.map((t,i)=>'  '+toFa(i+1)+'. '+t.title).join('\n')))return;
  tmBusy=true;
  showToast('⏳ در حال راه‌اندازی '+toFa(stale.length)+' کار...');
  fetch('?tasks_resume_all=1&only=stale').then(r=>r.json()).then(d=>{
    tmBusy=false;
    if(d&&d.ok){
      showToast('▶ '+toFa(d.count||0)+' کار دوباره شروع شد'
        +((d.skipped||[]).length?(' · '+toFa(d.skipped.length)+' مورد رد شد'):''));
    }else showToast('✗ '+((d&&d.error)||'ناموفق'),true);
    setTimeout(tmPulse,1500); tmPulse();
  }).catch(()=>{tmBusy=false;showToast('✗ خطا شبکه',true);});
}

/* v10.23 (۳۶ج): ادامه/اجرای دوبارهٔ یک کار از داخلِ مدیر وظیفه */
function tmResume(key){
  if(tmBusy)return;
  const t=((tmData&&tmData.tasks)||[]).find(x=>x.key===key);
  const isStale=!!(t&&t.state==='stale');
  const q=isStale
    ? 'کارِ گیرکردهٔ «'+((t&&t.title)||key)+'» دوباره شروع شود؟\nقفل و ردِ اجرای قبلی پاک می‌شود.'
    : 'کارِ «'+((t&&t.title)||key)+'» با تنظیماتِ اجرای قبلی دوباره اجرا شود؟';
  if(!confirm(q))return;
  tmBusy=true;
  fetch('?tasks_resume=1&key='+encodeURIComponent(key)).then(r=>r.json()).then(d=>{
    tmBusy=false;
    if(d&&d.ok) showToast('▶ شروع شد — چند لحظه بعد وضعیتش اینجا به‌روز می‌شود');
    else showToast('✗ '+((d&&d.error)||'شروع نشد'),true);
    setTimeout(tmPulse,1500);
    tmPulse();
  }).catch(()=>{tmBusy=false;showToast('✗ خطا شبکه',true);});
}

function tmClear(key){
  if(tmBusy)return; tmBusy=true;
  fetch('?tasks_clear=1&key='+encodeURIComponent(key)).then(r=>r.json()).then(d=>{
    tmBusy=false;
    if(d&&d.ok) showToast('🗑 ردِ کار پاک شد');
    else showToast('✗ '+((d&&d.error)||'پاک‌سازی ناموفق'),true);
    tmPulse();
  }).catch(()=>{tmBusy=false;showToast('✗ خطا شبکه',true);});
}

function tmClearAll(){
  if(!confirm('ردِ همهٔ کارهای تمام‌شده و رهاشده پاک شود؟ کارهای در حال اجرا دست نمی‌خورند.'))return;
  if(tmBusy)return; tmBusy=true;
  fetch('?tasks_clear=1&key=all').then(r=>r.json()).then(d=>{
    tmBusy=false;
