if(d.vendor_activated_at)html+='<div><span style="color:#94a3b8">\u0641\u0639\u0627\u0644\u200c\u0633\u0627\u0632\u06cc:</span> <b>'+esc(d.vendor_activated_at||'')+'</b></div>';
