/**
 * v8.92: «اجرای الان» هم دقیقاً الگوی دکمهٔ «استخراج بک‌اند» را دارد.
 *
 * تا ۸.۹۱ این دکمه درخواست را می‌فرستاد و تا پایانِ کل کران منتظر
 * پاسخ می‌ماند — استخراج، بازنشستگی، ارسال و اعلان‌ها همه در یک
 * درخواست. روی پروفایل بزرگ چند دقیقه طول می‌کشید و در تمام آن مدت
 * پنل پیشرفت خالی بود؛ اگر هاست یا مرورگر وسط راه قطع می‌کرد، به نظر
 * می‌رسید دکمه هیچ کاری نکرده، در حالی که کار روی سرور ادامه داشت.
 *
 * حالا با bg=1 پاسخ فوری می‌آید، کار در پس‌زمینه ادامه پیدا می‌کند و
 * پیشرفت از همان فایل و همان صفی خوانده می‌شود که دکمهٔ بک‌اند
 * استفاده می‌کند. خلاصهٔ نهایی از cron_last خوانده می‌شود.
 */
/* v9.00: تنظیمات ذخیره‌شدهٔ اتصال مبدأ را در فرم می‌نشاند */
function srcNetApply(sn){
    sn=sn||{};
    const set=(id,v)=>{const e=$(id);if(e)e.value=v;};
    set('srcNetMode',      sn.mode||'direct');
    set('srcNetGap',       sn.gap_ms||0);
    set('srcNetIp',        sn.resolve_ip||'');
    set('srcNetDoh',       sn.doh_url||'');
    set('srcNetProxy',     sn.proxy||'');
    set('srcNetProxyType', sn.proxy_type||'http');
    set('srcNetProxyAuth', sn.proxy_auth||'');
    set('srcNetWorker',    sn.worker_url||'');
    set('srcNetHosts',     sn.hosts||'');
    // v9.77: تیکِ «استفاده از روش‌های جایگزین در صورت شکست»
    if($('srcNetFallback'))$('srcNetFallback').checked=!!sn.fallback;
}

/* v9.00: تنظیمات اتصال به سایت مبدأ را از فرم می‌خواند */
function srcNetCollect(){
    const g=id=>$(id)||{};
    return {
        mode:       g('srcNetMode').value||'direct',
        gap_ms:     parseInt(g('srcNetGap').value||'0')||0,
        resolve_ip: (g('srcNetIp').value||'').trim(),
        doh_url:    (g('srcNetDoh').value||'').trim(),
        proxy:      (g('srcNetProxy').value||'').trim(),
        proxy_type: g('srcNetProxyType').value||'http',
        proxy_auth: (g('srcNetProxyAuth').value||'').trim(),
        worker_url: (g('srcNetWorker').value||'').trim(),
        hosts:      (g('srcNetHosts').value||'').trim(),
        // v9.77: استفاده از روش‌های جایگزین در صورت شکستِ روش اصلی
        fallback:   !!(g('srcNetFallback')&&$('srcNetFallback').checked)
    };
}

/* v9.00: آزمایش اتصال به سایت مبدأ با تنظیمات فعلی */
function srcNetTest(){
    const box=$('srcNetResult'); if(!box)return;
    const url=($('url')&&$('url').value.trim())
            ||($('profileSelect')&&$('profileSelect').value.trim())||'';
    if(!url){box.innerHTML='<span style="color:#f87171">اول آدرس پروفایل را وارد کنید</span>';return;}
    box.innerHTML='<span style="color:#94a3b8">⏳ در حال آزمایش...</span>';
    // اول تنظیمات را ذخیره کن تا آزمایش با همین مقادیر انجام شود
    if(typeof saveConn==='function')saveConn();
    setTimeout(()=>{
        fetch('?src_probe=1&url='+encodeURIComponent(url)).then(r=>r.json()).then(d=>{
            if(!d){box.innerHTML='<span style="color:#f87171">پاسخی نیامد</span>';return;}
            const okc=d.ok?'#4ade80':'#f87171';
            let h='<div style="padding:8px;background:#1e293b;border-radius:8px;line-height:1.9">';
            h+='<b style="color:'+okc+'">'+(d.ok?'✅ موفق':'❌ ناموفق')+'</b>';
            if(d.code)h+=' <span style="color:#94a3b8">— کد '+toFa(d.code)+'</span>';
            if(d.ms)h+=' <span style="color:#64748b">· '+toFa(d.ms)+'ms</span>';
            h+='<br><span style="color:#cbd5e1">'+esc(d.diagnosis||'')+'</span>';
            h+='<br><span style="color:#64748b;font-size:10px">روش: '+esc(d.mode||'direct')
             +(d.applies?' (اعمال شد)':' (اعمال نشد)')
             +' · فاصله: '+toFa(d.gap_ms||0)+'ms · حجم: '+toFa(d.bytes||0)+' بایت</span>';
            h+='</div>';
            box.innerHTML=h;
        }).catch(()=>{box.innerHTML='<span style="color:#f87171">خطای شبکه</span>';});
    },600);
}

function runSyncNow(){
    $('syncStatus').textContent='🔄 در حال اجرای کران جاب...';
    $('syncStatus').style.color='#67e8f9';
    openExtractPanel('🔄 اجرای کران جاب — استخراج و ارسال');
    watchExtractProgress();
    const fd=new FormData();
    fd.append('action','cron_run');
    fd.append('bg','1');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){showToast('❌ خطا در اجرای کران',1);$('syncStatus').textContent='❌ خطا';$('syncStatus').style.color='#f87171';return;}
        showToast('⚡ کران در پس‌زمینه شروع شد');
        $('syncStatus').textContent='🔄 در حال اجرا در پس‌زمینه...';
        cronWatchFinish();
    }).catch(()=>{
        $('syncStatus').textContent='❌ خطا در اجرای کران';
        $('syncStatus').style.color='#f87171';
        showToast('❌ خطا شبکه',1);
    });
}

/* منتظر می‌ماند تا اجرای پس‌زمینه تمام شود، بعد خلاصه را نشان می‌دهد.
   معیار پایان همان چیزی است که پنل پیشرفت می‌بیند: done شدن فایل
   پیشرفت. سقف انتظار می‌گذاریم تا اگر چیزی خراب شد تا ابد نچرخد. */
function cronWatchFinish(){
    let tries=0;
    const iv=setInterval(()=>{
        tries++;
        if(tries>1200){clearInterval(iv);return;}   // ۲۰ دقیقه سقف
        fetch('?cron_last=1').then(r=>r.json()).then(d=>{
            if(!d||!d.profiles)return;              // هنوز چیزی ثبت نشده
            const age=Math.floor(Date.now()/1000)-(d.finished_at||0);
            if(age>90)return;                       // مالِ اجرای قبلی است
            clearInterval(iv);
            renderCronResult(d);
        }).catch(()=>{});
    },2000);
}

function renderCronResult(d){
    {
        if(!d||!d.profiles){showToast('❌ خطا در اجرای کران',1);$('syncStatus').textContent='❌ خطا';$('syncStatus').style.color='#f87171';return;}
        const profiles=d.profiles||[];
        const synced=profiles.filter(p=>p.status==='syncing');
        const notDue=profiles.filter(p=>p.status==='not_due');
        const disabled=profiles.filter(p=>p.status==='sync_disabled');
        const noProducts=profiles.filter(p=>p.bsl==='no_products'||p.woo==='no_products');
        let msg='✓ کران اجرا شد';
        if(synced.length>0)msg+=' | '+toFa(synced.length)+' سینک';
        if(notDue.length>0)msg+=' | '+toFa(notDue.length)+' هنوز نوبت نیست';
        if(disabled.length>0)msg+=' | '+toFa(disabled.length)+' غیرفعال';
        $('syncStatus').textContent=msg;
        $('syncStatus').style.color='#4ade80';
        showToast('✓ کران جاب اجرا شد');
        // v8.22: Show extraction results in the log
        const eLog=$('extractLog');
        if(eLog){
            profiles.forEach(p=>{
                if(p.extracted>0){eLog.innerHTML+='<div style="color:#4ade80;padding:2px 0">✅ '+esc(p.name||p.key)+' — '+toFa(p.extracted)+' محصول استخراج شد</div>';}
                if(p.woo==='queued'){eLog.innerHTML+='<div style="color:#a78bfa;padding:2px 0">📋 '+esc(p.name||p.key)+' — '+toFa(p.woo_total||0)+' محصول در صف ووکامرس</div>';}
                if(p.bsl==='queued'){eLog.innerHTML+='<div style="color:#22d3ee;padding:2px 0">📋 '+esc(p.name||p.key)+' — '+toFa(p.bsl_total||0)+' محصول در صف باسلام</div>';}
                if(p.status==='not_due'){eLog.innerHTML+='<div style="color:#64748b;padding:2px 0">⏳ '+esc(p.name||p.key)+' — هنوز نوبت نیست</div>';}
            });
            // v8.29: مرحلهٔ سوم — نتیجهٔ استعلام اعلان‌ها
            // v10.45: خطاها (errors) و «رد شد» (skipped) هم اینجا دیده می‌شوند
            const nf=d.notifications||{};
            const nk=Object.keys(nf).filter(k=>k!=='errors'&&k!=='skipped');
            if(nk.length){
                const lbl={orders:'🛒 سفارش جدید',chats:'💬 پیام جدید',products:'📋 تغییر محصول'};
                nk.forEach(k=>{eLog.innerHTML+='<div style="color:#fbbf24;padding:2px 0">'+(lbl[k]||k)+': '+toFa(nf[k])+' مورد — اعلان ارسال شد</div>';});
            }
            if(nf.errors&&nf.errors.length){
                nf.errors.forEach(e=>{eLog.innerHTML+='<div style="color:#f87171;padding:2px 0">⚠️ اعلان: '+esc(e)+'</div>';});
            }else if(!nk.length&&nf.skipped){
                eLog.innerHTML+='<div style="color:#64748b;padding:2px 0">🔔 استعلام اعلان‌ها: '+
                  (nf.skipped==='no_basalam_shops'?'هیچ غرفهٔ باسلامی با توکن تنظیم نشده':esc(nf.skipped))+'</div>';
            }else if(!nk.length){
                eLog.innerHTML+='<div style="color:#64748b;padding:2px 0">🔔 استعلام اعلان‌ها: مورد جدیدی نبود</div>';
            }
            eLog.innerHTML+='<div style="color:#22c55e;padding:4px 0;font-weight:bold">✅ کران جاب کامل شد</div>';
        }
        // v8.28: کران تمام شد — رصد را متوقف و صف/شمارنده‌ها را نهایی کن
        if(extractPollTimer)clearInterval(extractPollTimer);
        pollExtractProgress();
        refreshExtractQueue();
        const bar=$('extractProgressBar');
        if(bar){bar.style.width='100%';}
        // Show detailed results
        let html='';
        profiles.forEach(p=>{
            const statusColors={syncing:'#fbbf24',sync_disabled:'#64748b',not_due:'#94a3b8',queued_bsl:'#22d3ee',running_woo:'#a78bfa'};
            const statusLabels={syncing:'🔄 در حال سینک',sync_disabled:'⏹ غیرفعال',not_due:'⏳ هنوز نوبت نیست',queued_bsl:'📋 در صف باسلام',running_woo:'📋 در صف ووکامرس'};
            const sc=statusColors[p.status]||'#94a3b8';
            const sl=statusLabels[p.status]||p.status;
            html+='<div style="padding:4px 8px;border-bottom:1px solid #1e293b;font-size:11px">';
            html+='<b style="color:#e2e8f0">'+esc(p.name||p.key)+'</b> ';
            html+='<span style="color:'+sc+'">'+sl+'</span>';
            if(p.extracted>0)html+=' <span style="color:#4ade80;font-size:10px">🔍 '+toFa(p.extracted)+' استخراج</span>';
            if(p.bsl==='queued')html+=' <span style="color:#22d3ee;font-size:10px">📋 باسلام: '+toFa(p.bsl_total||0)+' محصول</span>';
            if(p.woo==='queued')html+=' <span style="color:#a78bfa;font-size:10px">📋 ووکامرس: '+toFa(p.woo_total||0)+' محصول</span>';
            if(p.remaining)html+=' <span style="color:#64748b;font-size:10px">⏳ '+Math.ceil(p.remaining/60)+' دقیقه مانده</span>';
            html+='</div>';
        });
        const list=$('syncProfilesList');
        if(list&&html)list.innerHTML=html;
        // Refresh sync status after a short delay
        setTimeout(()=>refreshSyncStatus(),3000);
    }
}

if ($('url').value) {
    setTimeout(() => {
        const match = profiles.find(p => p.url === $('url').value.trim());
        if (match) loadProfileFromServer($('url').value.trim());
    }, 100);
}

// ========== CSV/Excel Import Functions ==========
function uploadImportFile(){
    const fileInput=$('importFile');
    if(!fileInput.files.length){showToast('فایل انتخاب کنید',true);return;}
    const fd=new FormData();
    fd.append('action','upload_import');
    fd.append('importFile',fileInput.files[0]);
    $('importUploadStatus').textContent='⏳ در حال آپلود و تحلیل...';
    $('btnUploadImport').disabled=true;
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        $('btnUploadImport').disabled=false;
        if(!d.ok){$('importUploadStatus').textContent='❌ '+d.error;showToast(d.error,true);return;}
        importFile=d.file;
        importHeaders=d.headers;
        importMapping=d.mapping||{};
        $('importUploadStatus').textContent='✓ '+d.rows+' ردیف یافت شد ('+d.headers.length+' ستون)';
        renderImportMapping(d);
        $('importMappingCard').classList.remove('hidden');
    }).catch(e=>{$('importUploadStatus').textContent='❌ خطا';$('btnUploadImport').disabled=false;});
}
function renderImportMapping(d){
    const fieldDefs=[
        {key:'title',label:'عنوان محصول',icon:'📝',required:true},
        {key:'price',label:'قیمت',icon:'💰',required:false},
        {key:'image',label:'تصویر (URL)',icon:'🖼️',required:false},
        {key:'link',label:'لینک محصول',icon:'🔗',required:false},
        {key:'sku',label:'SKU / کد محصول',icon:'🏷️',required:false},
        {key:'shortDesc',label:'توضیحات کوتاه',icon:'📄',required:false},
        {key:'longDesc',label:'توضیحات بلند',icon:'📃',required:false},
    ];
    let html='';
    fieldDefs.forEach(fd=>{
        const autoIdx=importMapping[fd.key];
        let opts='<option value="-1">-- انتخاب نشده --</option>';
        importHeaders.forEach((h,i)=>{
            const sel=(autoIdx!==undefined && autoIdx===i)?'selected':'';
            opts+=`<option value="${i}" ${sel}>${esc(h)}</option>`;
        });
        html+=`<div class="crow"><label>${fd.icon} ${fd.label}${fd.required?' <span style="color:#f87171">*</span>':''}</label><select id="impMap_${fd.key}" onchange="updateImportMapping('${fd.key}',this.value)" style="flex:1">${opts}</select></div>`;
    });
    $('importMappingRows').innerHTML=html;
    // Show sample data
    if(d.sample && d.sample.length>0){
        let prev='<div style="font-size:10px;color:#64748b;margin-bottom:4px">نمونه ردیف اول:</div>';
        prev+='<div style="background:#0f172a;border:1px solid #334155;border-radius:6px;padding:6px;font-size:10px;max-height:100px;overflow:auto;direction:ltr;text-align:left;font-family:monospace">';
        importHeaders.forEach((h,i)=>{prev+=`<b>${esc(h)}</b>: ${esc(d.sample[0][h]||'')}<br>`;});
        prev+='</div>';
        $('importPreview').innerHTML=prev;
    }
}
function updateImportMapping(field,val){importMapping[field]=parseInt(val);}
function processImport(){
    if(!importFile){showToast('ابتدا فایل را آپلود کنید',true);return;}
    $('importProcessStatus').textContent='⏳ در حال پردازش...';
    $('btnProcessImport').disabled=true;
    const fd=new FormData();
    fd.append('action','process_import');
    fd.append('file',importFile);
    fd.append('mapping',JSON.stringify(importMapping));
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        $('btnProcessImport').disabled=false;
        if(!d.ok){$('importProcessStatus').textContent='❌ '+d.error;showToast(d.error,true);return;}
        importProducts=d.products;
        applyImportPriceAdjust();
        const withPrice=d.products.filter(p=>p.price&&extractNumber(p.price)>0).length;
        const withImage=d.products.filter(p=>p.image).length;
        $('impTotal').textContent=toFa(d.count);
        $('impWithPrice').textContent=toFa(withPrice);
        $('impWithImage').textContent=toFa(withImage);
        $('importResultCard').classList.remove('hidden');
        if($('impTitleSuffix2')&&$('impTitleSuffix'))$('impTitleSuffix2').value=$('impTitleSuffix').value;
        if($('impPriceMode2')&&$('impPriceMode'))$('impPriceMode2').value=$('impPriceMode').value;
        if($('impPriceVal2')&&$('impPriceVal'))$('impPriceVal2').value=$('impPriceVal').value;
        if($('impRoundPrice2')&&$('impRoundPrice'))$('impRoundPrice2').value=$('impRoundPrice').value;
        // v8.78: اگر لینک صفحهٔ محصول آمده، جعبهٔ «انتخاب جزئیات» را نشان بده
        importRefreshDetailBox();
        const _nl=importLinkedCount();
        $('importProcessStatus').textContent='✓ '+toFa(d.count)+' محصول وارد شد'
            +(_nl?(' · '+toFa(_nl)+' تا لینک صفحهٔ محصول دارند'):'');
        showToast('✓ '+d.count+' محصول وارد شد');
    }).catch(e=>{$('importProcessStatus').textContent='❌ خطا';$('btnProcessImport').disabled=false;});
}

// v7.81: Apply price adjustment and title suffix to imported products
/**
 * v10.16 (۲۹الف): برگرداندنِ نتیجهٔ استخراجِ جزئیات به ردیف‌های درون‌ریزی‌شده.
 *
 * مسئله‌ای که کاربر گزارش داد: «قیمت در جزئیات» بیشتر برای پروفایل‌هایی
 * به‌کار می‌آید که محصولاتشان با فایل وارد شده‌اند. ولی importProducts و
 * products دو انبارِ جدا هستند: استخراجِ تفصیلی (SSE) فقط products را
 * به‌روز می‌کند، در حالی که «ارسال به ووکامرس/باسلام» و تعدیلِ قیمت از روی
 * importProducts کار می‌کنند. نتیجه اینکه قیمتِ تازهٔ صفحهٔ محصول استخراج
 * می‌شد، در جدولِ نتایج هم دیده می‌شد، ولی موقعِ ارسال همان قیمتِ کهنهٔ
 * داخلِ فایل می‌رفت.
 *
 * اینجا فیلدهای جزئیات را از products به importProducts برمی‌گردانیم.
 * قیمت جدا حساب می‌شود: چون _origPrice پایهٔ تعدیل است، با آمدنِ قیمتِ
 * تازه باید کش هم تازه شود وگرنه تعدیل روی عددِ کهنه اعمال می‌ماند.
 */
function importPullFromProducts(){
    if(!importProducts||!importProducts.length)return 0;
    let n=0;
    const flds=(typeof DETAIL_FIELDS!=='undefined')?DETAIL_FIELDS:[];
    importProducts.forEach(ip=>{
        if(!ip||!ip.key)return;
        const src=products.get(ip.key);
        if(!src)return;
        flds.forEach(f=>{
            const v=src[f.key];
            if(v===undefined||v===null||v==='')return;
            if(f.key==='price'){
                /* قیمتِ تازهٔ صفحهٔ محصول باید پایهٔ تعدیل شود، نه قیمتِ فایل.
                   اما مراقب باش: وقتی ردیفِ فایل و محصول یک شیء مشترک‌اند،
                   applyImportPriceAdjust خودش قیمتِ تعدیل‌شده را روی همین شیء
                   می‌نویسد. اگر آن را «قیمتِ تازهٔ استخراج‌شده» بگیریم، هر بار
                   پایه بالاتر می‌رود و تعدیل تجمعی می‌شود (۱۰۰ ⇒ ۱۱۰ ⇒ ۱۲۱ ⇒ …).
                   خروجیِ خودمان در final_price ثبت است؛ همان را کنار می‌گذاریم. */
                const fin=String(ip.final_price===undefined?'':ip.final_price);
                if(fin!==''&&String(v)===fin)return;
                if(String(v)!==String(ip._origPrice===undefined?ip.price:ip._origPrice)){
                    ip._origPrice=String(v);
                    ip.price=String(v);
                    delete ip.final_price;
                    n++;
                }
                return;
            }
            if(String(ip[f.key]||'')!==String(v)){ip[f.key]=v;n++;}
        });
        if(Array.isArray(src.images)&&src.images.length>1){
            ip.images=src.images;
            if(src.image)ip.image=src.image;
            n++;
        }
    });
    return n;
}

function applyImportPriceAdjust(){
    /* v10.16: پیش از هر تعدیلی، تازه‌ترین دادهٔ استخراجِ جزئیات را بردار */
    importPullFromProducts();
    const mode=$('impPriceMode')?$('impPriceMode').value:'none';
    const val=parseFloat($('impPriceVal')?$('impPriceVal').value:0)||0;
    const roundMode=$('impRoundPrice')?$('impRoundPrice').value:'0';
    const suffix=$('impTitleSuffix')?$('impTitleSuffix').value.trim():'';
    const factor=parseInt(roundMode,10)||0;
    let changed=0;
    importProducts.forEach(p=>{
        if(p._origTitle===undefined)p._origTitle=p.title||'';
        if(p._origPrice===undefined)p._origPrice=p.price||'';
        p.title=p._origTitle;p.price=p._origPrice;
        if(suffix&&p.title)p.title=p.title+' '+suffix;
        let base=extractNumber(p.price);
        if(base>0&&mode!=='none'){
            let f=base;
            if(mode==='percent')f=base*(1+(val/100));
            else if(mode==='multiplier')f=base*val;
            f=Math.round(f);
            if(factor>0)f=Math.round(f/factor)*factor;
            p.price=String(f);p.raw_price=String(base);p.final_price=String(f);changed++;
        }else if(base>0){p.final_price=String(base);}
    });
    const pv=$('impPricePreview');
    if(pv){if(changed>0){pv.textContent='✓ '+toFa(changed)+' قیمت تعدیل شد';pv.style.color='#4ade80';}else if(mode!=='none'){pv.textContent='⚠️ محصولی با قیمت یافت نشد';pv.style.color='#fbbf24';}else{pv.textContent='';}}
    renderImportProductsPreview();
}
function reapplyImportPrice(){
    if($('impTitleSuffix2')&&$('impTitleSuffix'))$('impTitleSuffix').value=$('impTitleSuffix2').value;
    if($('impPriceMode2')&&$('impPriceMode'))$('impPriceMode').value=$('impPriceMode2').value;
    if($('impPriceVal2')&&$('impPriceVal'))$('impPriceVal').value=$('impPriceVal2').value;
    if($('impRoundPrice2')&&$('impRoundPrice'))$('impRoundPrice').value=$('impRoundPrice2').value;
    applyImportPriceAdjust();
    const pv2=$('impPricePreview2');
    if(pv2){const a=importProducts.filter(p=>p.final_price&&p._origPrice).length;if(a>0){pv2.textContent='✓ '+toFa(a)+' قیمت تعدیل شد';pv2.style.color='#4ade80';}else{pv2.textContent=toFa(importProducts.length)+' محصول';pv2.style.color='#94a3b8';}}
}
function renderImportProductsPreview(){
    const c=$('importProductsPreview');if(!c||!importProducts.length)return;
    let h='<table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="background:#1e293b;color:#94a3b8;border-bottom:2px solid #334155"><th style="padding:6px;text-align:right">#</th><th style="padding:6px;text-align:right">عنوان</th><th style="padding:6px;text-align:right">قیمت اصلی</th><th style="padding:6px;text-align:right">قیمت نهایی</th><th style="padding:6px;text-align:right">تصویر</th></tr></thead><tbody>';
    importProducts.forEach((p,i)=>{
        const op=p._origPrice||p.price||'',fp=p.final_price||p.price||'',hi=p.image?'✓':'—',pc=op!==fp&&p._origPrice!==undefined;
        h+='<tr style="border-bottom:1px solid #1e293b"><td style="padding:4px;color:#64748b">'+toFa(i+1)+'</td><td style="padding:4px;color:#60a5fa;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(p.title||'')+'</td><td style="padding:4px;color:#94a3b8;direction:ltr;text-align:right">'+esc(op)+'</td><td style="padding:4px;color:'+(pc?'#fbbf24':'#4ade80')+';direction:ltr;text-align:right">'+esc(fp)+(pc?' ⚡':'')+'</td><td style="padding:4px;color:#64748b">'+hi+'</td></tr>';
    });
    h+='</tbody></table>';c.innerHTML=h;
}

/* =====================================================================
 *  v8.78: جزئیات محصولات درون‌ریزی‌شده از روی صفحهٔ خودشان
 *
 *  محصول درون‌ریزی‌شده اگر ستون «لینک محصول» داشته باشد، از نظر ما هیچ
 *  فرقی با محصول اسکرپ‌شده ندارد: هر دو یک لینک صفحهٔ محصول دارند. پس
 *  به‌جای ساختن یک مسیر جدا، محصول را وارد همان نقشهٔ products می‌کنیم و
 *  از همان انتخابگر و همان استخراج‌کنندهٔ تفصیلی استفاده می‌کنیم.
 * ===================================================================== */

/** چند تا از ردیف‌های وارد شده لینک صفحهٔ محصول دارند */
function importLinkedCount(){
    return importProducts.filter(p => p && p.link && String(p.link).trim()).length;
}

/** وضعیت جعبهٔ «انتخاب جزئیات» را بعد از هر بار وارد کردن به‌روز کن */
function importRefreshDetailBox(){
    const n = importLinkedCount();
    const box = $('impDetailBox'), no = $('impNoLinkBox'), row = $('impExtractRow');
    if(box) box.classList.toggle('hidden', n === 0);
    if(no)  no.classList.toggle('hidden', n > 0 || !importProducts.length);
    if(row) row.style.display = n > 0 ? '' : 'none';
    const c = $('impLinkCount');
    if(c) c.innerHTML = '<b style="color:#f9a8d4">' + toFa(n) + ' محصول</b> لینک صفحه دارد. ';
}

/**
 * محصولات وارد شده را داخل نقشهٔ اصلی می‌گذارد تا بقیهٔ برنامه ببیندشان.
 * همان کاری که «➕ افزودن به نتایج» می‌کند، ولی بی‌صدا و بدون عوض کردن تب،
 * چون این‌جا فقط می‌خواهیم انتخابگر جزئیات چیزی برای باز کردن داشته باشد.
 */
function importSyncToProducts(){
    let added = 0;
    importProducts.forEach(p => {
        const key = p.key;
        if(!key) return;
        if(!products.has(key)){ products.set(key, p); order.push(key); added++; }
        else {
            /* v10.16 (۲۹الف): Object.assign خامْ همهٔ فیلدهای فایل را روی
               محصولِ موجود می‌ریخت و جزئیاتِ تازه‌استخراج‌شده (به‌ویژه قیمتِ
               صفحهٔ محصول) را با مقدارِ کهنهٔ فایل پاک می‌کرد. مقدارِ خالیِ
               فایل هرگز نباید دادهٔ استخراج‌شده را از بین ببرد. */
            const cur = products.get(key);
            Object.keys(p).forEach(k => {
                const v = p[k];
                if (v === undefined || v === null || v === '') return;
                if (Array.isArray(v) && !v.length) return;
                cur[k] = v;
            });
        }
    });
    return added;
}

/** صفحهٔ محصولِ یک ردیف درون‌ریزی‌شده را در انتخابگر جزئیات باز می‌کند */
function importOpenDetailPicker(){
    if(!importProducts.length){ showToast('ابتدا فایل را وارد کنید', true); return; }
    if(!importLinkedCount()){
        showToast('هیچ ردیفی لینک صفحهٔ محصول ندارد', true);
        return;
    }
    importSyncToProducts();
    // اولین محصولِ دارای لینک نمونه شود
    const first = importProducts.find(p => p && p.link && String(p.link).trim());
    if(first && first.key) detailSampleKey = first.key;
    refreshViews();
    scheduleSave();
    $('impDetailStatus').textContent = '✓ صفحهٔ محصول در تب «سلکتورها» باز شد';
    // openDetailProxy خودش تب را عوض می‌کند و نوار نمونه را می‌کشد
    openDetailProxy();
}

/** پیشنهاد خودکار سلکتورهای جزئیات، از روی همان لینکِ فایل */
function importSuggestDetail(){
    if(!importLinkedCount()){ showToast('هیچ ردیفی لینک ندارد', true); return; }
    importSyncToProducts();
    const first = importProducts.find(p => p && p.link && String(p.link).trim());
    if(first && first.key) detailSampleKey = first.key;
    refreshViews();
    $('impDetailStatus').textContent = '⏳ در حال تحلیل صفحهٔ محصول...';
    switchMainTab('selectors');
    suggestDetailSelectors();
}

/**
 * استخراج تفصیلی روی محصولات درون‌ریزی‌شده.
 * همان startDetailExtraction است — عمداً کپی نشده تا هر اصلاحی که آن‌جا
 * انجام می‌شود (مثل رفع گیر کردن در v8.77) این‌جا هم اثر کند.
 */
function importExtractDetails(){
    if(!importLinkedCount()){ showToast('هیچ ردیفی لینک صفحهٔ محصول ندارد', true); return; }
    const n = importSyncToProducts();
    refreshViews();
    scheduleSave();
    const enabled = getEnabledDetailFields();
    const galOn = galCollect().mode !== 'off';
    if(!enabled.length && !galOn){
        showToast('اول با «🎯 باز کردن صفحهٔ محصول» فیلدها را انتخاب کنید', true);
        importOpenDetailPicker();
        return;
    }
    $('impDetailStatus').textContent = '🔍 استخراج جزئیات شروع شد — نتیجه در تب «نتایج»';
    switchMainTab('results');
    startDetailExtraction();
}

function addImportToResults(){
    if(!importProducts.length){showToast('محصولی نیست',true);return;}
    if($('impTitleSuffix2')&&$('impTitleSuffix'))$('impTitleSuffix').value=$('impTitleSuffix2').value;
    if($('impPriceMode2')&&$('impPriceMode'))$('impPriceMode').value=$('impPriceMode2').value;
    if($('impPriceVal2')&&$('impPriceVal'))$('impPriceVal').value=$('impPriceVal2').value;
    if($('impRoundPrice2')&&$('impRoundPrice'))$('impRoundPrice').value=$('impRoundPrice2').value;
    applyImportPriceAdjust();
    /* v8.78: قبلاً اینجا برای محصولِ بی‌کلید md5() صدا زده می‌شد که در
       جاوااسکریپت اصلاً وجود ندارد و استثنا می‌داد؛ فقط چون بک‌اند همیشه
       کلید می‌داد، این خط هیچ‌وقت اجرا نمی‌شد و باگ پنهان مانده بود.
       حالا همان مسیر مشترکِ importSyncToProducts استفاده می‌شود. */
    const added = importSyncToProducts();
    refreshViews();
    switchMainTab('results');
    showToast('✓ '+toFa(added)+' محصول به نتایج اضافه شد');
    scheduleSave();
}
