    $('wSM').classList.remove('hidden');$('wO').textContent='۰';$('wU').textContent='۰';$('wK').textContent='۰';$('wF').textContent='۰';$('wX').textContent='۰';$('wT').textContent=toFa(ps.length);
    $('wSS').textContent='ذخیره محصولات...';
