function loadProfileSyncConfig(){
    // Load from current profile via server
    const url=$('url').value.trim();
    if(!url)return;
    fetch('?load_profile='+encodeURIComponent(url)).then(r=>r.json()).then(d=>{
        if(d.ok&&d.profile&&d.profile.syncConfig){
            const sc=d.profile.syncConfig;
            $('profileSyncEn').checked=!!sc.enabled;
            // v8.55: صفر یک مقدار معتبر است («هر بار فراخوانی»). شرط قبلی
            // آن را رد می‌کرد و منو ۳۶۰۰ نشان می‌داد در حالی که ذخیره صفر بود.
            if(sc.interval!==undefined&&sc.interval!==null)$('profileSyncInterval').value=String(sc.interval);
            if(sc.target)$('profileSyncTarget').value=sc.target;
            // v7.81: Load add/update checkboxes
            $('profileSyncWooAddUpdate').checked=!!sc.wooAddUpdate;
            $('profileSyncBslAddUpdate').checked=!!sc.bslAddUpdate;
            // v9.45: بدون استخراج (پروفایل‌های اکسل/CSV)
            if($('profileSyncNoExtract'))$('profileSyncNoExtract').checked=!!sc.noExtract;
            // v10.21 (۳۴الف): تازه‌سازیِ دوره‌ای — نبودِ کلید یعنی روشن
            if($('profileSyncNoExtractRefresh'))$('profileSyncNoExtractRefresh').checked=(sc.noExtractRefresh!==false);
            syncToggleNoExtractBox();
            updateSyncStatusText();
        }else{
            $('profileSyncEn').checked=false;
            $('profileSyncWooAddUpdate').checked=false;
            $('profileSyncBslAddUpdate').checked=false;
            if($('profileSyncNoExtract'))$('profileSyncNoExtract').checked=false;
            syncToggleNoExtractBox();
            $('profileSyncStatus').textContent='';
        }
    }).catch(()=>{});
}
function getSyncConfig(){
    const intervalVal=parseInt($('profileSyncInterval').value);
    return {
        enabled:$('profileSyncEn').checked,
        // v7.66: 0 means "sync on endpoint call" — preserve it, don't convert to 3600
        interval:isNaN(intervalVal)?3600:intervalVal,
        target:$('profileSyncTarget').value||'woo',
        // v7.81: Add/Update mode checkboxes — stored in profile for future use
        wooAddUpdate:$('profileSyncWooAddUpdate').checked,
        bslAddUpdate:$('profileSyncBslAddUpdate').checked,
        // v9.45: بدون استخراج — فقط آپدیت دوره‌ای قیمت/موجودی (پروفایل‌های اکسل/CSV)
        noExtract:!!($('profileSyncNoExtract')&&$('profileSyncNoExtract').checked),
        /* v10.21 (۳۴الف): تازه‌سازیِ دوره‌ایِ قیمت/موجودی از صفحهٔ محصول.
           پیش‌فرض روشن — کاربری که «بدون استخراج» را می‌زند می‌خواهد قیمتش
           به‌روز بماند؛ اگر نمی‌خواهد، صریح خاموشش می‌کند. */
        noExtractRefresh:!$('profileSyncNoExtractRefresh')||!!$('profileSyncNoExtractRefresh').checked
    };
}
/* v10.21 (۳۴الف): جعبهٔ تازه‌سازی فقط وقتی «بدون استخراج» روشن است دیده شود */
function syncToggleNoExtractBox(){
    const on=$('profileSyncNoExtract')&&$('profileSyncNoExtract').checked;
    const box=$('syncNoExtractBox');
    if(box)box.classList.toggle('hidden',!on);
    if(on)syncRenderNoExtractStat();
}
/* چند محصولِ همین پروفایل لینکِ صفحهٔ محصول دارد + آیا سلکتورِ قیمت هست */
function syncRenderNoExtractStat(){
    const el=$('syncNoExtractStat'); if(!el)return;
    let linked=0,total=0;
    products.forEach(p=>{total++;if(p&&p.link&&String(p.link).trim())linked++;});
    const hasPrice=(typeof getEnabledDetailFields==='function')
        ? getEnabledDetailFields().indexOf('price')>=0 : false;
    if(total===0){el.style.color='#94a3b8';el.textContent='هنوز محصولی در این پروفایل نیست';return;}
    if(linked===0){
        el.style.color='#fbbf24';
        el.textContent='⚠ هیچ‌کدام از '+toFa(total)+' محصول لینکِ صفحه ندارند — تازه‌سازی ممکن نیست';
        return;
    }
    if(!hasPrice){
        el.style.color='#fbbf24';
        el.textContent='⚠ '+toFa(linked)+' محصول لینک دارد، ولی سلکتورِ «قیمت» در تبِ جزئیات انتخاب نشده';
        return;
    }
    el.style.color='#67e8f9';
    el.textContent='✓ '+toFa(linked)+' از '+toFa(total)+' محصول لینکِ صفحه دارد — قیمت و موجودی تازه می‌شود';
}
// v7.81: Update sync status text when any sync config changes
function updateSyncStatusText(){
    const en=$('profileSyncEn').checked;
    if(!en){$('profileSyncStatus').textContent='';return;}
    const intv=$('profileSyncInterval').options[$('profileSyncInterval').selectedIndex].text;
    /* v10.34 (۴۸الف/ج): متن باید همان چیزی را بگوید که واقعاً اجرا می‌شود —
       تیکِ روشن یعنی سه‌گانهٔ افزودن/آپدیت/حذف، تیکِ خاموش یعنی ارسالِ کامل. */
    const wm=$('profileSyncWooAddUpdate').checked?'➕🔄🗑 ووکامرس':'📦 ووکامرسِ کامل';
    const bm=$('profileSyncBslAddUpdate').checked?'➕🔄🗄 باسلام':'📦 باسلامِ کامل';
    /* v10.21 (۳۴الف): وقتی تازه‌سازی روشن است، «بدون استخراج» دیگر یعنی
       «بدون فهرست» نه «بدون هیچ‌چیز» — متن باید همین را بگوید. */
    let ne='';
    if($('profileSyncNoExtract')&&$('profileSyncNoExtract').checked){
        const rf=!$('profileSyncNoExtractRefresh')||$('profileSyncNoExtractRefresh').checked;
        ne=rf?' 🚫بدون فهرست · 🔄 تازه‌سازی قیمت/موجودی':' 🚫بدون استخراج';
    }
    /* v9.91: مقصدِ «هیچ‌کدام» — استخراج انجام می‌شود ولی چیزی ارسال نمی‌شود،
       پس نشان‌دادن حالتِ ووکامرس/باسلام گمراه‌کننده است. */
    const tg=$('profileSyncTarget')?$('profileSyncTarget').value:'woo';
    if(tg==='none'){$('profileSyncStatus').textContent='✓ سینک فعال ('+intv+') | 🚫 بدون ارسال (فقط استخراج)'+ne;return;}
    $('profileSyncStatus').textContent='✓ سینک فعال ('+intv+') | '+wm+' | '+bm+ne;
}
function refreshSyncStatus(){
    fetch('?sync_status=1').then(r=>r.json()).then(d=>{
        if(!d.ok)return;
        const state=d.state||{};
        let html='';
        profiles.forEach(p=>{
            // Load full profile to check sync config
            const syncEnabled=false; // Will be loaded async
            html+=`<div style="padding:6px 8px;border-bottom:1px solid #334155;font-size:11px">`;
            html+=`<b>${esc(p.name)}</b> `;
            if(state[p.key]){
                const s=state[p.key];
                html+=`<span style="color:${s.status==='running'?'#fbbf24':'#4ade80'}">● ${s.status==='running'?'در حال اجرا':'✓'}</span>`;
                html+=` <span style="color:#64748b">آخرین: ${new Date(s.lastRun*1000).toLocaleString('fa-IR')}</span>`;
            }else{
                html+=`<span style="color:#64748b">● هنوز اجرا نشده</span>`;
            }
            html+=`</div>`;
        });
        $('syncProfilesList').innerHTML=html||'<div style="color:#64748b;font-size:11px;padding:8px">هیچ پروفایلی تنظیم نشده</div>';
    }).catch(()=>{});
}
// Override applyProfile to also load sync config
const _origApplyProfile=applyProfile;
applyProfile=function(p){
    _origApplyProfile(p);
    if(p.syncConfig){
        $('profileSyncEn').checked=!!p.syncConfig.enabled;
        // v8.55: همان اصلاح — صفر نباید نادیده گرفته شود
        if(p.syncConfig.interval!==undefined&&p.syncConfig.interval!==null)$('profileSyncInterval').value=String(p.syncConfig.interval);
        if(p.syncConfig.target)$('profileSyncTarget').value=p.syncConfig.target;
        // v7.81: Load add/update checkboxes
        $('profileSyncWooAddUpdate').checked=!!p.syncConfig.wooAddUpdate;
        $('profileSyncBslAddUpdate').checked=!!p.syncConfig.bslAddUpdate;
        // v9.45: بدون استخراج (پروفایل‌های اکسل/CSV)
        if($('profileSyncNoExtract'))$('profileSyncNoExtract').checked=!!p.syncConfig.noExtract;
        // v10.21 (۳۴الف)
        if($('profileSyncNoExtractRefresh'))$('profileSyncNoExtractRefresh').checked=(p.syncConfig.noExtractRefresh!==false);
        syncToggleNoExtractBox();
        updateSyncStatusText();
    }else{
        $('profileSyncEn').checked=false;
        $('profileSyncWooAddUpdate').checked=false;
        $('profileSyncBslAddUpdate').checked=false;
        if($('profileSyncNoExtract'))$('profileSyncNoExtract').checked=false;
        syncToggleNoExtractBox();
        $('profileSyncStatus').textContent='';
    }
    // v9.67: اتصال غیرمستقیمِ این پروفایل (پیش‌فرض: خاموش = مستقیم)
    // v9.76: مقدار ممکن است boolean یا رشتهٔ '1'/'0'/'true'/'false' باشد؛ همه را
    // درست بخوان تا سوییچ بعد از رفرش دقیقاً همان حالتی را نشان دهد که ذخیره شده.
    if($('profileNetIndirect')){
        const _ni=p.net_indirect;
        $('profileNetIndirect').checked = (_ni===true||_ni===1||_ni==='1'||_ni==='true');
    }
    updateProfileNetHint();
};
function updateProfileNetHint(){
    const el=document.getElementById('profileNetIndirectHint');
    if(!el)return;
    const on=!!(document.getElementById('profileNetIndirect')&&document.getElementById('profileNetIndirect').checked);
    el.textContent=on?'غیرمستقیم (Worker/پروکسی)':'مستقیم';
    el.style.color=on?'#22c55e':'#94a3b8';
}
// hook the toggle's onchange to refresh the hint label (scheduleSave already wired in HTML)
(function(){const t=document.getElementById('profileNetIndirect');if(t){t.addEventListener('change',updateProfileNetHint);}})();
// Override collectProfileData to include syncConfig
const _origCollectProfileData=collectProfileData;
collectProfileData=function(){
